namespace Otus.Modulo.PontoDeVendas
{
	[Module(ModuleName = "PontoDeVendaModulo", OnDemand = true)]
	[ModuleDependency("RestauranteModulo")]
	public class PontoDeVendaModulo : IModule
	{
		private readonly IUnityContainer _container;

		public PontoDeVendaModulo(IUnityContainer container)
		{
			_container = container;
		}

		public void Initialize()
		{
			try
			{
				_container.RegisterTypeForNavigation<PontoDeVendasView>();
				_container.RegisterTypeForNavigation<PontoDeVendaView>();
				_container.RegisterType<IBackupPontoDeVendaService, BackupPontoDeVendaService>(new ContainerControlledLifetimeManager(), Array.Empty<InjectionMember>());
				_container.RegisterType<IModoFuncionamentoService, ModoFuncionamentoService>(new ContainerControlledLifetimeManager(), Array.Empty<InjectionMember>());
				_container.RegisterType<IList<IModoFuncionamento>>(new InjectionMember[1]
				{
					new InjectionFactory((IUnityContainer container) => container.Resolve<IModoFuncionamentoService>(Array.Empty<ResolverOverride>()).ObterModosFuncionamento())
				});
				_container.RegisterType<IClientActorSystem>(new ContainerControlledLifetimeManager(), new InjectionMember[1]
				{
					new InjectionFactory((IUnityContainer container) => container.Resolve<PontoDeVendaClientActorSystem>(Array.Empty<ResolverOverride>()).Criar("PontoDeVendaDigisatClient"))
				});
				_container.RegisterType<SatService>("SatService", new ContainerControlledLifetimeManager(), Array.Empty<InjectionMember>());
				_container.RegisterType<EcfService>("EcfService", new ContainerControlledLifetimeManager(), Array.Empty<InjectionMember>());
				_container.RegisterType<DisplayService>("DisplayService", new ContainerControlledLifetimeManager(), Array.Empty<InjectionMember>());
				_container.RegisterType<NotaManualService>("NotaManualService", new ContainerControlledLifetimeManager(), Array.Empty<InjectionMember>());
				_container.RegisterType<MFePontoVendaService>("MFePontoVendaService", new ContainerControlledLifetimeManager(), Array.Empty<InjectionMember>());
				_container.RegisterType<INfceService>(new ContainerControlledLifetimeManager(), new InjectionMember[1]
				{
					new InjectionFactory((IUnityContainer container) => (!(DadosSistema.EmpresaLogada.Municipio.Uf.Sigla == "SC")) ? container.Resolve<NfceService>(Array.Empty<ResolverOverride>()) : container.Resolve<PafNfceService>(Array.Empty<ResolverOverride>()))
				});
				_container.RegisterType<ISatService, SatService>(new ContainerControlledLifetimeManager(), Array.Empty<InjectionMember>());
				_container.RegisterType<IEcfService, EcfService>(new ContainerControlledLifetimeManager(), Array.Empty<InjectionMember>());
				_container.RegisterType<IDisplayService, DisplayService>(new ContainerControlledLifetimeManager(), Array.Empty<InjectionMember>());
				_container.RegisterType<IMFePontoVendaService, MFePontoVendaService>(new ContainerControlledLifetimeManager(), Array.Empty<InjectionMember>());
				_container.RegisterType<INotaManualService, NotaManualService>(new ContainerControlledLifetimeManager(), Array.Empty<InjectionMember>());
				_container.RegisterType<IRegistroVendaService, RegistroVendaService>(new ContainerControlledLifetimeManager(), Array.Empty<InjectionMember>());
				_container.RegisterType<IPafEcfService, PafEcfService>(new ContainerControlledLifetimeManager(), Array.Empty<InjectionMember>());
				_container.RegisterType<IRegistrosPafNfceService, RegistrosPafNfceService>(new ContainerControlledLifetimeManager(), Array.Empty<InjectionMember>());
				_container.RegisterType<Otus.Modulo.PontoDeVendas.Interfaces.ITefService, Otus.Modulo.PontoDeVendas.Services.TefService>(new ContainerControlledLifetimeManager(), Array.Empty<InjectionMember>());
				_container.RegisterType<IMobileService, MobileService>(new ContainerControlledLifetimeManager(), Array.Empty<InjectionMember>());
				_container.RegisterType<IPostoService, PostoService>(new ContainerControlledLifetimeManager(), Array.Empty<InjectionMember>());
				_container.RegisterType<IFarmaciaService, FarmaciaService>(new ContainerControlledLifetimeManager(), Array.Empty<InjectionMember>());
				_container.RegisterType<Otus.Modulo.PontoDeVendas.Interfaces.IShipayService, Otus.Modulo.PontoDeVendas.Services.ShipayService>(new ContainerControlledLifetimeManager(), Array.Empty<InjectionMember>());
				_container.RegisterType<IPainelMensagem, PainelMensagem>(Array.Empty<InjectionMember>());
