namespace Otus.Modulo.PontoDeVendas.ViewModels
{
	public class AbastecimentoViewModel : BindableBase
	{
		private readonly List<NotificouSituacaoComunicacaoBicoResponse> _semComunicacao;

		private readonly IEnumerable<QuebraContinuidadeEncerranteResponse> _quebrasContinuidadeEncerrante;

		private readonly IProdutoServicoEmpresaRepositoryRead _produtoServicoEmpresaRepositoryRead;

		private readonly PerdaComunicacaoTotal _perdaComunicacaoTotal;

		private IEmissorService _emissorService;

		public bool Selecionado
		{
			get
			{
				return GetProperty(() => Selecionado);
			}
			set
			{
				if (PodeSelecionar())
				{
					SetProperty(() => Selecionado, value, OnSelecionou);
				}
			}
		}

		public bool VisivelNaTela
		{
			get
			{
				return GetProperty(() => VisivelNaTela);
			}
			protected set
			{
				SetProperty(() => VisivelNaTela, value);
			}
		}

		public IAbastecimento Abastecimento { get; }

		public event EventHandler Selecionou;

		public AbastecimentoViewModel(IAbastecimento abastecimento, List<NotificouSituacaoComunicacaoBicoResponse> semComunicacao, IEnumerable<QuebraContinuidadeEncerranteResponse> quebrasContinuidadeEncerrante, IProdutoServicoEmpresaRepositoryRead produtoServicoEmpresaRepositoryRead, PerdaComunicacaoTotal perdaComunicacaoTotal, IEmissorService emissorService, IEnumerable<DigisatServer.Domain.Main.Aggregates.CadastrosAgg.Pessoas.Pessoa> frentistas)
		{
			_semComunicacao = semComunicacao;
			_quebrasContinuidadeEncerrante = quebrasContinuidadeEncerrante;
			_produtoServicoEmpresaRepositoryRead = produtoServicoEmpresaRepositoryRead;
			_perdaComunicacaoTotal = perdaComunicacaoTotal;
			_emissorService = emissorService;
			Abastecimento = abastecimento;
			string text = frentistas.FirstOrDefault((DigisatServer.Domain.Main.Aggregates.CadastrosAgg.Pessoas.Pessoa x) => ((Fisica)x).Frentista.Codigo == Abastecimento.Frentista)?.Nome;
			Abastecimento.PreencherNomeFrensita(string.IsNullOrEmpty(text) ? "Frentista não informado" : $"Frentista: {text}");
			VisivelNaTela = true;
		}

		public bool PodeSelecionar()
		{
			if (DadosSistema.IsPaf)
			{
				if (VerificarBicoSemComunicacao() && VerificarQuebraContinuidadeEncerrante())
				{
					return VerificarEstoque();
				}
				return false;
			}
			return true;
		}

		private bool VerificarBicoSemComunicacao()
		{
			int num;
			if (!(_emissorService is INotaManualService))
			{
				if (!_perdaComunicacaoTotal.IsNotNull())
				{
					num = (_semComunicacao.All((NotificouSituacaoComunicacaoBicoResponse x) => x.BicoNoSoftware != Abastecimento.NumeroDoBicoNoSoftware) ? 1 : 0);
					goto IL_0065;
				}
				num = 1;
			}
			else
			{
				if (!_semComunicacao.Any((NotificouSituacaoComunicacaoBicoResponse x) => x.BicoNoSoftware == Abastecimento.NumeroDoBicoNoSoftware))
				{
					num = ((!_emissorService.To<NotaManualService>().EcfServicePronto) ? 1 : 0);
					goto IL_0065;
				}
				num = 1;
			}
			goto IL_0075;
			IL_0065:
			if (num == 0)
			{
				DialogoFactory.MostrarDialogoConfirma("É vedado a emissão de cupom fiscal referente a abastecimento de bico sem comunicação!");
			}
			goto IL_0075;
			IL_0075:
			return (byte)num != 0;
		}

		private bool VerificarQuebraContinuidadeEncerrante()
		{
			bool flag = _quebrasContinuidadeEncerrante.Any((QuebraContinuidadeEncerranteResponse x) => x.IdBico == Abastecimento.IdBico);
			if (flag)
			{
				DialogoFactory.MostrarDialogoConfirma("É vedado a emissão de cupom fiscal referente a abastecimento de bico com quebra de continuidade do encerrante!");
			}
			return !flag;
		}

		private bool VerificarEstoque()
		{
			ProdutoEmpresa produtoEmpresa = _produtoServicoEmpresaRepositoryRead.FindOne(EntityBaseSpecification<ProdutoServicoEmpresa>.PorId(Abastecimento.IdProduto)) as ProdutoEmpresa;
			if (VerificarTemEstoque(produtoEmpresa))
			{
				return VerificarCapacidadeDoTanque(produtoEmpresa);
			}
			return false;
		}

		private bool VerificarTemEstoque(ProdutoEmpresa produtoEmpresa)
		{
			if (Abastecimento.TemEstoque)
			{
				return Abastecimento.TemEstoque;
			}
			bool flag = produtoEmpresa.Estoque.Quantidade > 0m;
			if (!flag)
			{
				DialogoFactory.MostrarDialogoConfirma("É vedado a emissão de cupom fiscal referente a abastecimento sem quantidade suficiente em estoque!");
			}
			return flag;
		}

		private bool VerificarCapacidadeDoTanque(ProdutoEmpresa produtoEmpresa)
		{
			bool flag = produtoEmpresa.Estoque.Quantidade <= Abastecimento.CapacidadeDoTanque;
			if (!flag)
			{
				DialogoFactory.MostrarDialogoConfirma("É vedado a emissão de cupom fiscal referente a tanque com quantidade superior a capacidade de armazenamento!");
			}
			return flag;
		}

		public void Selecionar()
		{
			if (PodeSelecionar())
			{
				Selecionado = !Selecionado;
			}
		}

		public void MostrarNaTela()
		{
			VisivelNaTela = true;
		}

		public void EsconderDaTela()
		{
			VisivelNaTela = false;
		}

		protected virtual void OnSelecionou()
		{
			Selecionou?.Invoke(this, EventArgs.Empty);
		}

		public void SetarEmissorService(IEmissorService emissorService)
		{
			_emissorService = emissorService;
		}
	}
