	public class InformacaoBuscaVendedor : InformacaoBusca<VendedorLocal, VendedorLocal>
	{
		private readonly IPainelBuscaService<VendedorLocal> _painel;

		private List<VendedorLocal> _documentos;

		public override string DescricaoDireita => "Buscando por nome";

		public override string DescricaoEsquerda => "Insert - Seleciona";

		protected override string TextoPesquisa => Texto.ToLower();

		public override int TempoParaIniciarBusca => 200;

		public InformacaoBuscaVendedor(IPainelBuscaService<VendedorLocal> painel)
			: base((IPainelLista<VendedorLocal>)painel)
		{
			_painel = painel;
		}

		protected override bool QuantidadeCaracteresParaBuscar(string texto)
		{
			return texto.Length >= 1;
		}

		protected override bool QuantidadeCaracteresParaLimpar(string texto)
		{
			string text = HelperString.RetornarSomenteLetras(texto);
			if (text == null)
			{
				return false;
			}
			return text.Length == 0;
		}

		protected override ResultadoPesquisa<VendedorLocal> Pesquisar(string informacao)
		{
			try
			{
				LoaderProcessoService.MostrarLoader("Pesquisando...");
				return new ResultadoPesquisa<VendedorLocal>(_documentos.Where((VendedorLocal x) => x.Nome.ToLower().Contains(informacao.ToLower())));
			}
			finally
			{
				LoaderProcessoService.EsconderLoader();
			}
		}

		protected override void OnLimpouBuscaEvent()
		{
			_painel.Lista.Limpar();
			_painel.Lista.Adicionar(_documentos);
		}

		public void CarregarVendedores(IEnumerable<DigisatServer.Domain.Main.Aggregates.CadastrosAgg.Pessoas.Pessoa> pessoas)
		{
			try
			{
				LoaderProcessoService.MostrarLoader("Pesquisando...");
				_documentos = new List<VendedorLocal> { VendedorLocal.CriarNenhum() };
				_documentos.AddRange((from x in pessoas
					orderby x.Nome
					select VendedorLocal.Criar().ComPessoa(x)).ToList());
				OnPesquisouEvent(_documentos);
			}
			finally
			{
				LoaderProcessoService.EsconderLoader();
			}
		}
	}
	public class InformacaoBuscaNotaFiscalEletronica : InformacaoBusca<DocumentoFiscalEletronicoLocal, DocumentoFiscalEletronicoLocal>
	{
		private readonly IPainelBuscaService<DocumentoFiscalEletronicoLocal> _painel;

		public override string DescricaoDireita => "Buscando por número, nome, cpf ou cnpj";

		protected override string TextoPesquisa => Texto.ToLower();

