	public abstract class ItemBase : BindableBase, IDisposable
	{
		public decimal Quantidade
		{
			get
			{
				return GetProperty(() => Quantidade);
			}
			set
			{
				SetProperty(() => Quantidade, value, () =>
				{
					OnAlterouQuantidadeEvent(Quantidade);
				});
			}
		}

		public IObservable<decimal> WhenAlterouQuantidade => from x in Observable.FromEventPattern<EventHandler<decimal>, decimal>((EventHandler<decimal> h) =>
			{
				AlterouQuantidadeEvent += h;
			}, (EventHandler<decimal> h) =>
			{
				AlterouQuantidadeEvent -= h;
			})
			select Quantidade;

		public ICommand UsarQuantidadeInformadaCommand { get; set; }

		public event EventHandler<decimal> AlterouQuantidadeEvent;

		public event EventHandler UsarQuantidadeInformadaEvent;

		protected ItemBase()
		{
			UsarQuantidadeInformadaCommand = new DelegateCommand(OnUsarQuantidadeInformadaEvent);
		}

		protected virtual void OnAlterouQuantidadeEvent(decimal e)
		{
			AlterouQuantidadeEvent?.Invoke(this, e);
		}

		protected virtual void OnUsarQuantidadeInformadaEvent()
		{
			UsarQuantidadeInformadaEvent?.Invoke(this, null);
		}

		public abstract IItemEstoque Obter();

		public virtual void Dispose()
		{
		}
	}
	public class ItemBaseFactory
	{
		private IItemEstoque _itemEstoque;

		public ItemBaseFactory ComItem(IItemEstoque itemEstoque)
		{
			_itemEstoque = itemEstoque;
			return this;
		}

		public ItemBase Criar()
		{
			ItemBase itemBase = null;
			_itemEstoque.ToDo((ItemEstoqueGradeSerial x) =>
			{
				itemBase = new ItemGradeLista(x);
			});
			_itemEstoque.ToDo((ItemEstoqueGrade x) =>
			{
				itemBase = new ItemGrade(x);
			});
			_itemEstoque.ToDo((ItemEstoqueSerial x) =>
			{
				itemBase = new ItemSerial(x);
			});
			_itemEstoque.ToDo((ItemEstoqueLote x) =>
			{
				itemBase = new ItemLote(x);
			});
			_itemEstoque.ToDo((ItemEstoqueLoteGrade x) =>
			{
				itemBase = new ItemLoteLista(x);
			});
			_itemEstoque.ToDo((ItemEstoqueLoteSerial x) =>
			{
				itemBase = new ItemLoteLista(x);
			});
			return itemBase;
		}
	}
