	public class ItemDocumentoFiscalCombustivel : ItemDocumentoFiscalProduto
	{
		public IAbastecimento Abastecimento { get; protected set; }

		public bool RegistroAbastecimentoManual { get; protected set; }

		public ItemDocumentoFiscalCombustivel(ProdutoServicoLocal produtoServicoLocal, IAbastecimento abastecimento, bool registroAbastecimentoManual, TabelaPrecoLocal tabelaPreco)
			: base(produtoServicoLocal)
		{
			Abastecimento = abastecimento;
			RegistroAbastecimentoManual = registroAbastecimentoManual;
			Estoque = produtoServicoLocal.To<ProdutoLocal>().ObterEstoqueVenda(abastecimento.Litros);
			PrecoUnitario = (tabelaPreco.IsNenhuma ? abastecimento.PrecoUnitario : produtoServicoLocal.Preco);
			Quantidade = abastecimento.Litros;
		}

		public IMensagemPromocional ObterMensagemPromocionalComCupomAutomatico()
		{
			return ReferenciaSistemaAbastecimentoMensagemPromocional.Criar().ComNumeroBico(Abastecimento.NumeroDoBicoNoSoftware).ComEncerranteInicial(Abastecimento.EncerranteInicial)
				.ComEncerranteFinal(Abastecimento.EncerranteFinal)
				.ComLitros(Abastecimento.Litros)
				.ComCupomAutomatico()
				.Build();
		}
	}
