		private TabelaPrecoLocal _tabelaPrecoLocal;

		public ItemDocumentoFiscalFactory ComProdutoServicoLocal(ProdutoServicoLocal produtoServicoLocal)
		{
			_produtoServicoLocal = produtoServicoLocal;
			return this;
		}

		public ItemDocumentoFiscalFactory ComEstoque(EstoqueDto estoqueDto)
		{
			_estoqueDto = estoqueDto;
			return this;
		}

		public ItemDocumentoFiscalFactory ComAbastecimento(IAbastecimento comAbastecimento)
		{
			_abastecimento = comAbastecimento;
			return this;
		}

		public ItemDocumentoFiscalFactory ComRegistroAbastecimentoManual(bool registroAbastecimentoManual)
		{
			_registroAbastecimentoManual = registroAbastecimentoManual;
			return this;
		}

		public ItemDocumentoFiscalFactory ComTabelaPreco(TabelaPrecoLocal tabelaPrecoLocal)
		{
			_tabelaPrecoLocal = tabelaPrecoLocal;
			return this;
		}

		public ItemDocumentoFiscal Criar()
		{
			if (_produtoServicoLocal is MedicamentoFarmaciaPopularLocal medicamentoFarmaciaPopularLocal)
			{
				return new ItemDocumentoFiscalFarmaciaPopular(medicamentoFarmaciaPopularLocal);
			}
			if (_produtoServicoLocal is MedicamentoPbmLocal medicamentoPbmLocal)
			{
				return new ItemDocumentoFiscalPbm(medicamentoPbmLocal);
			}
			if (_abastecimento.IsNotNull())
			{
				return new ItemDocumentoFiscalCombustivel(_produtoServicoLocal, _abastecimento, _registroAbastecimentoManual, _tabelaPrecoLocal ?? TabelaPrecoLocal.Criar().ComNenhuma());
			}
			if (_produtoServicoLocal is ServicoLocal)
			{
				return ItemDocumentoFiscalServico.Criar(_produtoServicoLocal);
			}
			return ItemDocumentoFiscalProduto.Criar(_produtoServicoLocal).To<ItemDocumentoFiscalProduto>().ComEstoque(_estoqueDto.Morfar());
		}
	}
