	public class ItemDocumentoFiscalPbm : ItemDocumentoFiscalProduto
	{
		public ProdutoAutorizado ProdutoAutorizado { get; protected set; }

		public decimal ValorRepassePbm => ProdutoAutorizado.Repasse * (decimal)ProdutoAutorizado.Quantidade;

		public ItemDocumentoFiscalPbm(MedicamentoPbmLocal medicamentoPbmLocal)
			: base(medicamentoPbmLocal)
		{
			ProdutoAutorizado = medicamentoPbmLocal.ProdutoAutorizado;
			Desconto = ((ProdutoAutorizado.PrecoUnitario > 0m && ProdutoAutorizado.PrecoUnitario < medicamentoPbmLocal.Preco) ? (medicamentoPbmLocal.Preco - ProdutoAutorizado.PrecoUnitario) : 0m) * (decimal)ProdutoAutorizado.Quantidade;
		}

		public IProdutoVendido ObterProdutoVendido(TipoPbm tipoPbm)
		{
			return FluentFactory<ProdutoVendidoFactory>.Init().SetarDescricaoProduto(Descricao).SetarProdutoAutorizado(ProdutoAutorizado)
				.SetarNumeroItem(NumeroItem)
				.SetarTipoPbm(tipoPbm)
				.Criar();
		}

		public ProdutoAutorizado ObterProdutoAutorizado()
		{
			return ProdutoAutorizado.ComDesconto(Desconto).ComDescricao(Descricao).ComPrecoFarmacia(ProdutoServicoLocal.Preco);
		}
	}
	public class ItemDocumentoFiscalProduto : ItemDocumentoFiscal
	{
		public Estoque Estoque { get; protected set; }

		public IEnumerable<ComponenteBase> ComponentesRemovidos { get; protected set; }

		protected ItemDocumentoFiscalProduto(ProdutoServicoLocal produtoServicoLocal)
			: base(produtoServicoLocal)
		{
			PreencherComponentesRemovidos(produtoServicoLocal);
		}

		public static ItemDocumentoFiscal Criar(ProdutoServicoLocal produtoServicoLocal)
		{
			return new ItemDocumentoFiscalProduto(produtoServicoLocal);
		}

		public ItemDocumentoFiscalProduto ComEstoque(Estoque estoque)
		{
			Estoque = estoque;
			Quantidade = estoque?.Quantidade ?? 0m;
			ExibirInformacaoEstoqueVendido = (string.IsNullOrEmpty(Estoque?.InformacaoEstoqueVendido) ? Visibility.Collapsed : Visibility.Visible);
			return this;
		}

		public void VerificarEstoque(Seletor<IPainel> seletor)
		{
			ProdutoLocal produtoLocal = ProdutoServicoLocal as ProdutoLocal;
			produtoLocal.Estoque.TemEstoque(Estoque, produtoLocal.ObterEstoqueVendidos(seletor), DadosSistema.ConfiguracaoDto.Saida.PermitirEstoqueNegativo.Valor, isOrcamento: false);
		}

		private void PreencherComponentesRemovidos(ProdutoServicoLocal produtoServicoLocal)
		{
			produtoServicoLocal.ToDo((ProdutoLocal produto) =>
			{
				ComponentesRemovidos = produto.GetComponentesRemovidos();
				ComponentesRemovidosToText = ComponentesRemovidos.Aggregate(string.Empty, (string current, ComponenteBase componenteRemovido) => current + $"Sem {componenteRemovido.ProdutoDescricao}".ToUpper());
			});
		}
	}
