	public class ItemListaBase : ItemBase
	{
		private readonly IItemEstoqueBase _itemEstoque;

		public Lista<ItemBase> Lista { get; protected set; } = new Lista<ItemBase>();

		private ItemListaBase(IEnumerable<IItemEstoque> itensEstoque)
		{
			AssinarEventos();
			foreach (ItemBase item in itensEstoque.Select((IItemEstoque item) => FluentFactory<ItemBaseFactory>.Init().ComItem(item).Criar()))
			{
				Lista.Adicionar(item);
			}
		}

		protected ItemListaBase(IItemEstoqueBase itemEstoque)
		{
			_itemEstoque = itemEstoque;
			AssinarEventos();
			foreach (ItemBase item in itemEstoque.Lista.Select((IItemEstoque item) => FluentFactory<ItemBaseFactory>.Init().ComItem(item).Criar()))
			{
				Lista.Adicionar(item);
			}
		}

		private void AssinarEventos()
		{
			Lista.WhenAdicionouItem.Subscribe((ItemBase x) =>
			{
				x.WhenAlterouQuantidade.Subscribe((decimal y) =>
				{
					Quantidade = Lista.Itens.Sum((ItemBase z) => z.Quantidade);
				});
			});
		}

		public override IItemEstoque Obter()
		{
			return _itemEstoque.Criar((from z in Lista.Itens
				where z.Quantidade > 0m
				select z.Obter()).ToList());
		}

		public override void Dispose()
		{
			Lista.Dispose();
			base.Dispose();
		}

		public static Lista<ItemBase> Criar(IEnumerable<IItemEstoque> itensEstoque)
		{
			return new ItemListaBase(itensEstoque).Lista;
		}
	}
