	public class ModoFuncionamentoPafNfce : ModoFuncionamentoNfce
	{
		public override string Descricao
		{
			get
			{
				if (PdvEstadoOffline)
				{
					if (ConfiguracaoOffline.Carregar().TipoEmissaoNotaFiscalConsumidorEletronicaOffline != 1)
					{
						return "PAF NFC-E Contingência com servidor Off-line";
					}
					return "PAF NFC-E com servidor Off-line";
				}
				if (TipoEmissao != 1)
				{
					return "PAF NFC-E Contingência";
				}
				return "PAF NFC-E";
			}
		}

		public ModoFuncionamentoPafNfce(ISessaoService sessaoService, INfceService emissorService, IUnityContainer container)
			: base(sessaoService, emissorService, container)
		{
			F12Command = new DelegateCommand(() =>
			{
				SeletorDireito.Selecionar<PainelMenuFiscalPafNfce>();
			}, () => !(SeletorDireito.Get<PainelDocumentoFiscal>().Estado is DocumentoFiscalAberto));
		}

		protected override void AdicionarPaineis(ISessaoService sessaoService, IUnityContainer container)
		{
			SeletorDireito.Adicionar(container.Resolve<PainelIdentificacaoPafNfce>(new ResolverOverride[1]
			{
				new ParameterOverride("seletor", SeletorDireito)
			}));
			SeletorDireito.Adicionar(container.Resolve<PainelRegistrosPafNfce>(new ResolverOverride[1]
			{
				new ParameterOverrides
				{
					{ "emissorService", EmissorService },
					{ "seletor", SeletorDireito }
				}
			}));
			SeletorDireito.Adicionar(container.Resolve<PainelVendasIdentificadasPeloCpfCnpj>(new ResolverOverride[1]
			{
				new ParameterOverride("seletor", SeletorDireito)
			}));
			SeletorDireito.Adicionar(container.Resolve<PainelRequisicoesExternasRegistradas>(new ResolverOverride[1]
			{
				new ParameterOverride("seletor", SeletorDireito)
			}));
			SeletorDireito.Adicionar(container.Resolve<PainelBuscaKit>(new ResolverOverride[1]
			{
				new ParameterOverride("seletor", SeletorDireito)
			}));
			SeletorDireito.Adicionar(container.Resolve<PainelBuscaTipoDeVale>(new ResolverOverride[1]
			{
				new ParameterOverride("seletor", SeletorDireito)
			}));
			SeletorDireito.Adicionar(container.Resolve<PainelTotalizacaoNfce>(new ResolverOverride[1]
			{
				new ParameterOverrides
				{
					{ "emissorService", EmissorService },
					{ "seletorDireito", SeletorDireito },
					{ "seletorEsquerdo", SeletorEsquerdo }
				}
			}));
			SeletorDireito.Adicionar(container.Resolve<PainelBuscaNotaFiscalConsumidorEletronica>(new ResolverOverride[1]
			{
				new ParameterOverrides
				{
					{ "emissorService", EmissorService },
					{ "seletor", SeletorDireito },
					{ "seletorEsquerdo", SeletorEsquerdo }
				}
			}));
			SeletorDireito.Adicionar(container.Resolve<PainelBuscaNotaFiscalEletronica>(new ResolverOverride[1]
			{
				new ParameterOverrides
				{
					{ "emissorService", EmissorService },
					{ "seletor", SeletorDireito },
					{ "seletorEsquerdo", SeletorEsquerdo }
				}
			}));
			SeletorDireito.Adicionar(container.Resolve<PainelMenuAdministrativoPafNfce>(new ResolverOverride[1]
			{
				new ParameterOverrides
				{
					{ "emissorService", EmissorService },
					{ "seletorDireito", SeletorDireito }
				}
			}));
			SeletorDireito.Adicionar(container.Resolve<PainelRegistroAutorizacaoPagamentoPos>(new ResolverOverride[1]
			{
				new ParameterOverride("seletor", SeletorDireito)
			}));
			SeletorDireito.Adicionar(container.Resolve<PainelRegistroAutorizacaoPagamentoPix>(new ResolverOverride[1]
			{
				new ParameterOverride("seletor", SeletorDireito)
			}));
			SeletorDireito.Adicionar(container.Resolve<PainelResumoNfceEmitidaEmContingencia>(new ResolverOverride[1]
			{
				new ParameterOverride("seletor", SeletorDireito)
			}));
			SeletorDireito.Adicionar(container.Resolve<PainelInformacoesNfce>(new ResolverOverride[1]
			{
				new ParameterOverride("seletor", SeletorDireito)
			}));
			switch (sessaoService.Sessao.Perfis.ItemSelecionado.Empresa.RamoAtividade.Tipo)
			{
			case RamoDeAtividade.Farmacia:
				SeletorDireito.Adicionar(container.Resolve<PainelMenuFiscalPafNfce>(new ResolverOverride[1]
				{
					new ParameterOverride("seletor", SeletorDireito)
				}));
				break;
			case RamoDeAtividade.PostoCombustivel:
				SeletorDireito.Adicionar(container.Resolve<PainelMenuFiscalPafNfcePosto>(new ResolverOverride[1]
				{
					new ParameterOverrides
					{
						{ "emissorService", EmissorService },
						{ "seletor", SeletorDireito },
						{ "seletorEsquerdo", SeletorEsquerdo }
					}
				}));
				SeletorDireito.Adicionar(container.Resolve<PainelEstoqueFisicoCombustivel>(new ResolverOverride[1]
				{
					new ParameterOverrides
					{
						{ "emissorService", EmissorService },
						{ "seletor", SeletorDireito }
					}
				}));
				SeletorDireito.Adicionar(container.Resolve<PainelRegistroAbastecimentoDocumentoFiscalEletronicoManual>(new ResolverOverride[1]
				{
					new ParameterOverride("seletor", SeletorDireito)
				}));
				break;
			case RamoDeAtividade.Restaurante:
				SeletorDireito.Adicionar(container.Resolve<PainelMenuFiscalPafNfceRestaurante>(new ResolverOverride[1]
				{
					new ParameterOverride("seletor", SeletorDireito)
				}));
				SeletorDireito.Adicionar(container.Resolve<PainelMesasAbertasPafNfce>(new ResolverOverride[1]
				{
					new ParameterOverride("seletor", SeletorDireito)
				}));
				break;
			case RamoDeAtividade.Hotel:
				SeletorDireito.Adicionar(container.Resolve<PainelMenuFiscalPafNfceRestaurante>(new ResolverOverride[1]
				{
					new ParameterOverride("seletor", SeletorDireito)
				}));
				SeletorDireito.Adicionar(container.Resolve<PainelMesasAbertasPafNfce>(new ResolverOverride[1]
				{
					new ParameterOverride("seletor", SeletorDireito)
				}));
				break;
			default:
				SeletorDireito.Adicionar(container.Resolve<PainelMenuFiscalPafNfce>(new ResolverOverride[1]
				{
					new ParameterOverride("seletor", SeletorDireito)
				}));
				break;
			}
			SeletorDireito.Selecionar<PainelDocumentoFiscal>();
		}

		public override void ConsultarStatus()
		{
			_emissorService.To<PafNfceService>()?.ConsultarStatusServico();
		}
	}
	public class Moeda : IMoeda
	{
		public string Descricao { get; private set; }

		public decimal Cotacao { get; private set; }

		public decimal Valor { get; set; }

		private Moeda()
		{
		}

		private Moeda(string moeda, decimal cotacao)
		{
			Descricao = moeda;
			Cotacao = cotacao;
		}

		public void SetarValor(decimal valor)
		{
			Valor = ((Cotacao > 0m) ? (valor / Cotacao) : valor);
		}

		public override string ToString()
		{
			return Descricao;
		}

		public static Moeda Criar()
		{
			return new Moeda();
		}

		public Moeda ComDescricao(string descricao)
		{
			Descricao = descricao;
			return Build();
		}

		public Moeda ComCotacao(decimal cotacao)
		{
			Cotacao = cotacao;
			return Build();
		}

		public Moeda Build()
		{
			return new Moeda(Descricao, Cotacao);
		}
	}
	public abstract class ModoFuncionamentoBase : BindableBase, IModoFuncionamento
	{
		private readonly ISessaoService _sessaoService;

