		private void Fechar()
		{
			SeletorDireito.Fechar();
		}

		private void SeletorEsquerdoFechar()
		{
			SeletorEsquerdo.Fechar();
			if (SeletorEsquerdo.Historico.Any((IPainel x) => x.Is<PainelCardapioPontoDeVenda>()))
			{
				SeletorEsquerdo.Selecionar<PainelCardapioPontoDeVenda>();
			}
			else if (!SeletorEsquerdo.Historico.Any((IPainel x) => x.Is<PainelMenuRapidoPontoDeVenda>()))
			{
				SeletorEsquerdo.FecharTudo();
			}
		}

		public void SetarAtalho(KeyCustom keyCustom, Action action)
		{
			AtalhoCommand = new CustomDelegateCommand(new KeyGestureControl(keyCustom), action);
		}

		public virtual void Load()
		{
			SeletorEsquerdo.Painel.Load();
			SeletorDireito.Painel.Load();
			TefService.SetarModoFuncionamento(this);
			SeletorEsquerdo.Painel.ToDo((IPainelEsquerdo painel) =>
			{
				painel.SetarModoFuncionamento(this);
			});
			SeletorEsquerdo.Get<PainelMenuRapidoPontoDeVenda>().SetarModoFuncionamento(this);
			SeletorEsquerdo.Get<PainelMenuRapidoAdicionaisPontoVenda>().SetarModoFuncionamento(this);
			SeletorEsquerdo.Get<PainelCardapioPontoDeVenda>()?.SetarModoFuncionamento(this);
			SeletorDireito.Painel.ToDo((IPainelDocumentoFiscal painel) =>
			{
				painel.AssinarEventos();
			});
			bool flag = false;
			if (!PdvEstadoOffline)
			{
				flag = DadosSistema.PreencherMoedas();
			}
			try
			{
				if (!flag)
				{
					DadosSistema.PreencherMoedas(from x in _moedaRepositoryRead.Find(EntitySpecification<Otus.Modulo.PontoDeVendas.Aggregates.Moeda>.Ativo())
						select new MoedaDto
						{
							Ativo = x.Ativo,
							Descricao = x.Descricao,
							Id = x.Id.ToString(),
							Cotacao = x.Cotacao,
							DataInclusao = x.DataInclusao,
							Versao = x.Versao
						});
				}
			}
			catch (Exception)
			{
			}
		}

		public void UnLoad()
		{
			SeletorDireito.Painel.ToDo((IPainelDocumentoFiscal painel) =>
			{
				painel.DesassinarEventos();
			});
		}

		public void SetarComoUltimoModoFuncionamento()
		{
			_ultimoModoFuncionamento = true;
			if (_emissorServiceCarregado)
			{
				ExecutarRecarregarPreDocumentoFiscal();
			}
		}

		private void ExecutarRecarregarPreDocumentoFiscal()
		{
			SeletorDireito.Get<PainelDocumentoFiscal>().RecarregarPreDocumentoFiscal();
		}
	}
