	public class ModoFuncionamentoNfce : ModoFuncionamentoBase
	{
		private readonly ISessaoService _sessaoService;

		private IEnumerable<ResumoNfceTransmitidaDto> _resumo;

		private bool _documentoFiscalAberto;

		public int TipoEmissao = 1;

		protected readonly INfceService _emissorService;

		public override string Descricao
		{
			get
			{
				if (PdvEstadoOffline)
				{
					if (ConfiguracaoOffline.Carregar().TipoEmissaoNotaFiscalConsumidorEletronicaOffline != 1)
					{
						return "NFC-E Contingência com servidor Off-line";
					}
					return "NFC-E com servidor Off-line";
				}
				if (TipoEmissao != 1)
				{
					return "NFC-E Contingência";
				}
				return "NFC-E";
			}
		}

		public override string Informacao
		{
			get
			{
				if (TipoEmissao != 1)
				{
					return $"NFC-e's em contingência devem ser transmitidas em até 24 horas. ATALHOS: F1   OPERADOR: {_sessaoService.Sessao.NomeUsuario}  ";
				}
				return $"ATALHOS: F1   OPERADOR: {_sessaoService.Sessao.NomeUsuario}  ";
			}
		}

		public override ICor Cor
		{
			get
			{
				if (TipoEmissao != 1)
				{
					if (TipoEmissao != 9)
					{
						return new Cor("#15abbf");
					}
					return new Cor("#7A7389");
				}
				return new Cor("#008B8B");
			}
		}

		public override string NomeImagemPadraoPontoDeVenda
		{
			get
			{
				if (TipoEmissao != 1)
				{
					if (TipoEmissao != 9)
					{
						return "imgNFCeServidorOffline.png";
					}
					return "imgNFCeContingencia.png";
				}
				return "imgNFCeNormal.png";
			}
		}

		public ModoFuncionamentoNfce(ISessaoService sessaoService, INfceService emissorService, IUnityContainer container)
			: base(emissorService, container, sessaoService)
		{
			_sessaoService = sessaoService;
			_emissorService = emissorService;
			AdicionarPaineis(sessaoService, container);
			emissorService.To<NfceService>().WhenAlterarTipoEmissaoNfceEvent.Subscribe(WhenAlterarTipoEmissaoNfceEvent);
			emissorService.To<NfceService>().WhenExibirResumoNfceTransmitidaEvent.Subscribe(WhenExibirResumoNfceTransmitidaEvent);
			_emissorService.WhenDocumentoFiscalAbertoEvent.ObserveOn((SynchronizationContext)new DispatcherSynchronizationContext()).Subscribe((EventArgs args) =>
			{
				_documentoFiscalAberto = true;
				ExibirResumo();
			});
			_emissorService.WhenEmissorProntoEvent.ObserveOn((SynchronizationContext)new DispatcherSynchronizationContext()).Subscribe((EventArgs args) =>
			{
				IEstadoDocumentoFiscal estado = SeletorDireito.Get<PainelDocumentoFiscal>().Estado;
				if (!(estado is DocumentoFiscalAberto) && !(estado is DocumentoFiscalBloqueado))
				{
					_documentoFiscalAberto = false;
					ExibirResumo();
				}
			});
		}

		protected virtual void AdicionarPaineis(ISessaoService sessaoService, IUnityContainer container)
		{
			SeletorDireito.Adicionar(container.Resolve<PainelBuscaKit>(new ResolverOverride[1]
			{
				new ParameterOverride("seletor", SeletorDireito)
			}));
			SeletorDireito.Adicionar(container.Resolve<PainelBuscaTipoDeVale>(new ResolverOverride[1]
			{
				new ParameterOverride("seletor", SeletorDireito)
			}));
			SeletorDireito.Adicionar(container.Resolve<PainelTotalizacaoNfce>(new ResolverOverride[1]
			{
				new ParameterOverrides
				{
					{ "emissorService", EmissorService },
					{ "seletorDireito", SeletorDireito },
					{ "seletorEsquerdo", SeletorEsquerdo }
				}
			}));
			SeletorDireito.Adicionar(container.Resolve<PainelBuscaNotaFiscalConsumidorEletronica>(new ResolverOverride[1]
			{
				new ParameterOverrides
				{
					{ "emissorService", EmissorService },
					{ "seletor", SeletorDireito },
					{ "seletorEsquerdo", SeletorEsquerdo }
				}
			}));
			SeletorDireito.Adicionar(container.Resolve<PainelBuscaNotaFiscalEletronica>(new ResolverOverride[1]
			{
				new ParameterOverrides
				{
					{ "emissorService", EmissorService },
					{ "seletor", SeletorDireito },
					{ "seletorEsquerdo", SeletorEsquerdo }
				}
			}));
			SeletorDireito.Adicionar(container.Resolve<PainelMenuAdministrativo>(new ResolverOverride[1]
			{
				new ParameterOverrides
				{
					{ "emissorService", EmissorService },
					{ "seletorDireito", SeletorDireito }
				}
			}));
			SeletorDireito.Adicionar(container.Resolve<PainelInformacoesNfce>(new ResolverOverride[1]
			{
				new ParameterOverride("seletor", SeletorDireito)
			}));
			SeletorDireito.Adicionar(container.Resolve<PainelRegistroAutorizacaoPagamentoPos>(new ResolverOverride[1]
			{
				new ParameterOverride("seletor", SeletorDireito)
			}));
			SeletorDireito.Adicionar(container.Resolve<PainelRegistroAutorizacaoPagamentoPix>(new ResolverOverride[1]
			{
				new ParameterOverride("seletor", SeletorDireito)
			}));
			SeletorDireito.Adicionar(container.Resolve<PainelResumoNfceEmitidaEmContingencia>(new ResolverOverride[1]
			{
				new ParameterOverride("seletor", SeletorDireito)
			}));
			if (sessaoService.Sessao.Perfis.ItemSelecionado.Empresa.RamoAtividade.Tipo == RamoDeAtividade.PostoCombustivel)
			{
				SeletorDireito.Adicionar(container.Resolve<PainelRegistroAbastecimentoDocumentoFiscalEletronicoManual>(new ResolverOverride[1]
				{
					new ParameterOverride("seletor", SeletorDireito)
				}));
			}
			SeletorDireito.Selecionar<PainelDocumentoFiscal>();
		}

		private void ExibirResumo()
		{
			if (!_documentoFiscalAberto && _resumo != null)
			{
				SeletorDireito.Get<PainelResumoNfceEmitidaEmContingencia>().SetarResumo(_resumo);
				SeletorDireito.Selecionar<PainelResumoNfceEmitidaEmContingencia>();
				_resumo = null;
			}
		}

		private void WhenAlterarTipoEmissaoNfceEvent(int tipoEmissao)
		{
			TipoEmissao = tipoEmissao;
			RaisePropertyChanged(() => Descricao);
			RaisePropertyChanged(() => Informacao);
			RaisePropertyChanged(() => Cor);
			RaisePropertyChanged(() => NomeImagemPadraoPontoDeVenda);
			SeletorEsquerdo.Painel.ToDo((IPainelEsquerdo painel) =>
			{
				painel.SetarModoFuncionamento(this);
			});
		}

		private void WhenExibirResumoNfceTransmitidaEvent(IEnumerable<ResumoNfceTransmitidaDto> resumo)
		{
			_resumo = resumo;
			ExibirResumo();
		}

		public override void Load()
		{
			ConsultarStatus();
			base.Load();
		}

		public virtual void ConsultarStatus()
		{
			_emissorService.To<NfceService>().ConsultarStatusServico();
		}
	}
