	public class Informacao<TItem> : BindableBase, IInformacao
	{
		private readonly IPainelLista<TItem> _painel;

		public bool UsouSetasTeclado;

		public string Texto
		{
			get
			{
				return GetProperty(() => Texto);
			}
			set
			{
				SetProperty(() => Texto, value);
			}
		}

		public bool FocoNoTexto
		{
			get
			{
				return GetProperty(() => FocoNoTexto);
			}
			set
			{
				SetProperty(() => FocoNoTexto, value);
			}
		}

		public virtual string DescricaoEsquerda
		{
			get
			{
				return GetProperty(() => DescricaoEsquerda);
			}
			set
			{
				SetProperty(() => DescricaoEsquerda, value);
			}
		}

		public virtual string DescricaoDireita { get; protected set; }

		public decimal TextoToDecimal
		{
			get
			{
				decimal.TryParse(Texto.Replace("-", "").Replace("+", "").Replace("%", ""), out var result);
				return result;
			}
		}

		public bool TextoIsDecimal
		{
			get
			{
				if (Texto.ApenasNumeros().Length > 0)
				{
					return Texto.Contains(",");
				}
				return false;
			}
		}

		public ICommand KeyDownCommand { get; protected set; }

		public ICommand PreviewKeyDownCommand { get; protected set; }

		public ICommand ControlarFocoCommand { get; protected set; }

		public IObservable<string> WhenPropertyChanged => from x in Observable.FromEventPattern<PropertyChangedEventHandler, PropertyChangedEventArgs>((PropertyChangedEventHandler h) =>
			{
				PropertyChanged += h;
			}, (PropertyChangedEventHandler h) =>
			{
				PropertyChanged -= h;
			})
			select x.EventArgs.PropertyName;

		public event EventHandler LimpouEvent;

		public Informacao(IPainelLista<TItem> painel)
		{
			_painel = painel;
			KeyDownCommand = new AsyncCommand<System.Windows.Input.KeyEventArgs>(async (System.Windows.Input.KeyEventArgs args) =>
			{
				await Task.Factory.StartNew(() =>
				{
					ProcessarKey(args);
				}, CancellationToken.None, TaskCreationOptions.None, TaskScheduler.FromCurrentSynchronizationContext());
			}, (System.Windows.Input.KeyEventArgs p) => true, allowMultipleExecution: true);
			PreviewKeyDownCommand = new DelegateCommand<System.Windows.Input.KeyEventArgs>(ProcessarPreviewKey);
			ControlarFocoCommand = new DelegateCommand(ControlarFoco);
		}

		protected virtual void ProcessarKey(System.Windows.Input.KeyEventArgs keyEventArgs)
		{
			Key key = keyEventArgs.Key;
			if (key == Key.Escape)
			{
				OnLimpouEvent();
				Limpar();
			}
		}

		protected virtual void ProcessarPreviewKey(System.Windows.Input.KeyEventArgs keyEventArgs)
		{
			switch (keyEventArgs.Key)
			{
			case Key.Up:
				PosicionarNoAnterior();
				UsouSetasTeclado = true;
				break;
			case Key.Down:
				PosicionarNoProximo();
				UsouSetasTeclado = true;
				break;
			}
		}

		protected virtual void PosicionarNoAnterior()
		{
			_painel.Lista.PosicionarNoAnterior();
		}

		protected virtual void PosicionarNoProximo()
		{
			_painel.Lista.PosicionarNoProximo();
		}

		public void ControlarFoco()
		{
			((Action)(() =>
			{
				FocoNoTexto = !FocoNoTexto;
			})).BeginInvoke((IAsyncResult result) =>
			{
				DispatcherHelper.DoEvents();
			}, this);
		}

		public virtual void Limpar()
		{
			Texto = string.Empty;
		}

		protected virtual void OnLimpouEvent()
		{
			LimpouEvent?.Invoke(this, EventArgs.Empty);
		}
	}
	public abstract class InformacaoBusca<TItem, TEntity> : Informacao<TItem> where TItem : class where TEntity : class
	{
		public virtual int TempoParaIniciarBusca => 600;

		protected virtual string TextoPesquisa => Texto;

		public bool HabilitaEnter { get; set; }

		public decimal Quantidade
		{
			get
			{
				decimal result = 1m;
				if (!Texto.Contains("*"))
				{
					return result;
				}
				decimal.TryParse(Texto.CopiarTexto(0, Texto.LastIndexOf('*')), out result);
				return result;
			}
		}

		public bool PossuiQuantidadeInformada => Texto.Contains("*");

		public event EventHandler<IEnumerable<TEntity>> PesquisouEvent;

		public event EventHandler LimpouBuscaEvent;

		protected InformacaoBusca(IPainelLista<TItem> painel)
			: base(painel)
		{
			AssinarEventos();
		}

		private void AssinarEventos()
		{
			IObservable<string> source = WhenPropertyChanged.Where((string property) => property == "Texto");
			IObservable<string> inputPesquisa = from text in source.Select((string evt) => TextoPesquisa).Throttle(TimeSpan.FromMilliseconds(TempoParaIniciarBusca))
				where text != null && QuantidadeCaracteresParaBuscar(text)
				select text;
			Func<string, IObservable<ResultadoPesquisa<TEntity>>> pesquisa = Observable.ToAsync<string, ResultadoPesquisa<TEntity>>(Pesquisar);
			(from informacao in inputPesquisa
				from resultado in pesquisa(informacao).TakeUntil(inputPesquisa)
				select resultado).ObserveOn((SynchronizationContext)new DispatcherSynchronizationContext()).Subscribe((ResultadoPesquisa<TEntity> resultado) =>
			{
				OnPesquisouEvent(resultado.Resultados);
			}, (Exception exception) =>
			{
				exception.ShowLastException();
			});
			(from evt in source
				select Texto into text
				where text == null || QuantidadeCaracteresParaLimpar(text)
				select text).ObserveOn(SynchronizationContext.Current).Subscribe((string resultado) =>
			{
				OnLimpouBuscaEvent();
			});
			WhenPropertyChanged.Where((string property) => property == "Texto").Subscribe((string a) =>
			{
				HabilitaEnter = false;
			});
		}

		protected abstract ResultadoPesquisa<TEntity> Pesquisar(string informacao);

		protected virtual bool QuantidadeCaracteresParaBuscar(string texto)
		{
			string text = HelperString.RetornarSomenteLetras(texto);
			if (text == null)
			{
				return false;
			}
			return text.Length >= 3;
		}

		protected virtual bool QuantidadeCaracteresParaLimpar(string texto)
		{
			string text = HelperString.RetornarSomenteLetras(texto);
			if (text == null)
			{
				return false;
			}
			return text.Length < 3;
		}

		protected virtual void OnPesquisouEvent(IEnumerable<TEntity> e)
		{
			PesquisouEvent?.Invoke(this, e);
			HabilitaEnter = true;
		}

		protected virtual void OnLimpouBuscaEvent()
		{
			LimpouBuscaEvent?.Invoke(this, EventArgs.Empty);
		}

		public void ExcecutarPesquisa(string informacao)
		{
			Pesquisar(informacao);
		}
	}
