	public class InformacaoBuscaProdutoServico : InformacaoBusca<ProdutoServicoLocal, ProdutoServicoLocal>
	{
		private readonly PainelBuscaProdutoServico _painel;

		public override string DescricaoDireita => "Buscando por código interno, barras ou descrição";

		protected override string TextoPesquisa => Texto.ToLower();

		public override int TempoParaIniciarBusca => 2500;

		public InformacaoBuscaProdutoServico(PainelBuscaProdutoServico painel)
			: base((IPainelLista<ProdutoServicoLocal>)painel)
		{
			_painel = painel;
		}

		protected override bool QuantidadeCaracteresParaBuscar(string texto)
		{
			return texto.Length >= 1;
		}

		protected override void OnPesquisouEvent(IEnumerable<ProdutoServicoLocal> e)
		{
			base.OnPesquisouEvent(e);
			ControlarFoco();
			if (Texto.ApenasNumeros().Length >= 8)
			{
				FocusHelper.GetFocusedElement().To<System.Windows.Controls.TextBox>().SelectAll();
			}
		}

		protected override ResultadoPesquisa<ProdutoServicoLocal> Pesquisar(string informacao)
		{
			try
			{
				LoaderProcessoService.MostrarLoader("Pesquisando...");
				PerfilEmpresaSessao perfilEmpresa = _painel.SessaoService.Sessao.Perfis.ItemSelecionado;
				ObjectId idTabelaPreco = _painel.Seletor.Get<PainelDocumentoFiscal>().TabelaPrecoLocal?.Id ?? ObjectId.Empty;
				List<ProdutoServicoLocal> list = new List<ProdutoServicoLocal>();
				for (short num = 1; num <= 10; num++)
				{
					IPage<ProdutoServicoEmpresa> result = _painel.ProdutoServicoEmpresaRepositoryRead.Find(ProdutoServicoSpecifications.Ativo(), informacao, perfilEmpresa.Empresa.Id, idTabelaPreco.ToString(), num, 300).Result;
					IEnumerable<ProdutoServicoEmpresa> source = result.Lista;
					if (DadosSistema.ConfiguracaoDto.Saida.MostrarSomenteItensComQuantidadeSaldoPositiva.Valor)
					{
						source = result.Lista.Where((ProdutoServicoEmpresa x) => x.Is<ServicoEmpresa>() || (x.Is<ProdutoEmpresa>() && x.To<ProdutoEmpresa>().Estoque.QuantidadeSaldo > 0m));
					}
					list.AddRange(from x in source
						where x.Vendavel
						select FluentFactory<ProdutoServicoLocalFactory>.Init().ComPermissaoEstoqueNegativo(perfilEmpresa.Configuracao.PermitirEstoqueNegativo).ComProdutoServicoEmpresa(x.SetarTabelaPreco(idTabelaPreco))
							.ComSeletor(_painel.Seletor)
							.Criar());
					if (list.Count >= 300 || result.Lista.Count() < 300)
					{
						break;
					}
				}
				return new ResultadoPesquisa<ProdutoServicoLocal>(list.OrderByDescending((ProdutoServicoLocal a) => a.Descricao.ToLower().StartsWith(informacao.ToLower())).Take(300).ToList());
			}
			finally
			{
				LoaderProcessoService.EsconderLoader();
			}
		}
	}
	public class InformacaoDocumentoFiscal : InformacaoBusca<ItemDocumentoFiscal, ProdutoServicoLocal>
	{
		private readonly PainelDocumentoFiscal _painel;

		private bool _erro;

		private bool _buscaAbertaManualmente;

		private bool _ordenouPorDescricao;

		public ICommand VenderSelecionadoCommand { get; }

		protected override string TextoPesquisa
		{
			get
			{
				if (!Texto.IsNotNull() || !Texto.Contains("*"))
				{
					return Texto;
				}
				return Texto.CopiarTexto(Texto.IndexOf('*') + 1, Texto.Length - Texto.IndexOf('*'));
			}
		}

		public bool BuscaAberta
		{
			get
			{
				return GetProperty(() => BuscaAberta);
			}
			protected set
			{
				SetProperty(() => BuscaAberta, value);
			}
		}

		public Lista<ProdutoServicoLocal> ListaProdutoServico { get; protected set; }

		public bool DescontoAcrescimoPercentual => Texto.Contains("%");

		public double Width
		{
			get
			{
				return GetProperty(() => Width);
			}
			set
			{
				SetProperty(() => Width, value);
			}
		}

		public override string DescricaoEsquerda
		{
			get
			{
				return GetProperty(() => DescricaoEsquerda);
			}
			set
			{
				SetProperty(() => DescricaoEsquerda, value);
			}
		}

		public override string DescricaoDireita => "Quantidade * Código, Barras ou Descrição";

		public bool CapturouPeso { get; set; }

		public InformacaoDocumentoFiscal(PainelDocumentoFiscal painel)
			: base((IPainelLista<ItemDocumentoFiscal>)painel)
		{
			_painel = painel;
			_painel.WhenEstadoDocumentoFiscalChangedEvent.Subscribe((IEstadoDocumentoFiscal a) =>
			{
				DescricaoEsquerda = (a.Is<DocumentoFiscalFechado>() ? string.Empty : "Valor -/+ (Desconto/Acréscimo)");
			});
			ListaProdutoServico = new Lista<ProdutoServicoLocal>();
			PesquisouEvent += OnPesquisouEvent;
			LimpouEvent += OnLimpouEvent;
			LimpouBuscaEvent += OnLimpouBuscaEvent;
			Width = ((System.Windows.Application.Current.MainWindow.ActualWidth >= 1280.0) ? 600 : 410);
			VenderSelecionadoCommand = new AsyncCommand(ProcessarEnterAsync);
		}

		private void OnPesquisouEvent(object sender, IEnumerable<ProdutoServicoLocal> listaProdutoServico)
		{
			ListaProdutoServico.Limpar();
			ListaProdutoServico.Adicionar(listaProdutoServico);
			ListaProdutoServico.PosicionarNoPrimeiro();
			BuscaAberta = !_erro;
		}

		private void OnLimpouEvent(object sender, EventArgs eventArgs)
		{
			Limpar();
		}

		protected override bool QuantidadeCaracteresParaBuscar(string texto)
		{
			if (!_buscaAbertaManualmente)
			{
				string text = HelperString.RetornarSomenteLetras(texto);
				if (text == null)
				{
					return false;
				}
				return text.Length >= 3;
			}
			return true;
		}

		private void OnLimpouBuscaEvent(object sender, EventArgs eventArgs)
		{
			ListaProdutoServico.Limpar();
			BuscaAberta = _buscaAbertaManualmente;
		}

		protected override void ProcessarPreviewKey(System.Windows.Input.KeyEventArgs keyEventArgs)
		{
			base.ProcessarPreviewKey(keyEventArgs);
			switch (keyEventArgs.Key)
			{
			case Key.Next:
				BuscaAberta = true;
				_buscaAbertaManualmente = true;
				break;
			case Key.Prior:
				keyEventArgs.Handled = true;
				if (_ordenouPorDescricao)
				{
					ObservableCollection<ProdutoServicoLocal> observableCollection = new ObservableCollection<ProdutoServicoLocal>();
					observableCollection.AddRange(ListaProdutoServico.Itens);
					ListaProdutoServico.Limpar();
					ListaProdutoServico.AdicionarSemPosicionar(observableCollection.OrderByDescending((ProdutoServicoLocal a) => a.Descricao.ToLower().StartsWith(TextoPesquisa.ToLower())));
					_ordenouPorDescricao = false;
				}
				else
				{
					ObservableCollection<ProdutoServicoLocal> observableCollection2 = new ObservableCollection<ProdutoServicoLocal>();
					observableCollection2.AddRange(ListaProdutoServico.Itens);
					ListaProdutoServico.Limpar();
					ListaProdutoServico.AdicionarSemPosicionar(observableCollection2.OrderBy((ProdutoServicoLocal x) => x.DescricaoEMarca));
					_ordenouPorDescricao = true;
				}
				ListaProdutoServico.PosicionarNoPrimeiro();
				break;
			}
		}

		protected override async void ProcessarKey(System.Windows.Input.KeyEventArgs keyEventArgs)
		{
			base.ProcessarKey(keyEventArgs);
			switch (keyEventArgs.Key)
			{
			case Key.Return:
				await ProcessarEnterAsync();
				break;
			case Key.OemPlus:
				keyEventArgs.Handled = true;
				break;
			}
		}

		private async Task ProcessarEnterAsync()
		{
			GravarLog(TextoPesquisa);
			if (string.IsNullOrWhiteSpace(TextoPesquisa))
			{
				return;
			}
			string textoPesquisa = TextoPesquisa;
			string textoDigitado = Texto;
			decimal quantidadeInformada = Quantidade;
			base.Limpar();
			ProdutoServicoLocal produtoServicoLocal;
			if (BuscaAberta)
			{
				produtoServicoLocal = ListaProdutoServico?.ItemSelecionado;
				if (_painel.SessaoService.VerificarPermissao<DigisatServer.Infrastructure.Crosscutting.Module.PontoDeVenda, PermitirVendaDeItemAtravesDaPesquisa>() == null)
				{
					produtoServicoLocal = null;
				}
				BuscaAberta = false;
				_ordenouPorDescricao = false;
				_buscaAbertaManualmente = false;
			}
			else
			{
				if (textoPesquisa.StartsWith("2") && textoPesquisa.Length == 13)
				{
					Thread.Sleep(200);
					string codigoInterno = ProcessarCodigoDeBarrasService.RetornarCodigoInternoDoCodigoBarras(textoPesquisa);
					produtoServicoLocal = (await PesquisarAsync(codigoInterno)).Resultados.FirstOrDefault();
					if (produtoServicoLocal.IsNotNull())
					{
						produtoServicoLocal?.Vender(ProcessarCodigoDeBarrasService.RetornarQuantidadeDoCodigoBarras(textoPesquisa, produtoServicoLocal.Unidade, produtoServicoLocal.Preco), capturouPeso: true);
						Limpar();
					}
					else if (LancouKit(textoPesquisa, codigoInterno))
					{
						Limpar();
					}
					else
					{
						NaoLocalizado();
					}
					return;
				}
				if (DadosSistema.IsPostoCombustivel && textoPesquisa.StartsWith("AB") && textoPesquisa.Length == 13)
				{
					AbastecimentoViewModel abastecimentoViewModel = _painel.SeletorEsquerdo.Get<PainelEsquerdoPosto>()?.Lista?.Itens?.FirstOrDefault((AbastecimentoViewModel x) => x.Abastecimento?.CodigoReferencia?.Equals(textoPesquisa) ?? false);
					if (abastecimentoViewModel.IsNotNull())
					{
						abastecimentoViewModel.Selecionar();
						await _painel.SeletorEsquerdo.Get<PainelEsquerdoPosto>().ImportarAbastecimentos();
					}
					else
					{
						AbastecimentoNaoLocalizado();
					}
					return;
				}
				produtoServicoLocal = (await PesquisarAsync(textoPesquisa)).Resultados.FirstOrDefault();
			}
			if (produtoServicoLocal != null)
			{
				if (produtoServicoLocal.Pesavel && textoDigitado.Contains("*"))
				{
					produtoServicoLocal.Vender(quantidadeInformada, capturouPeso: true);
				}
				else
				{
					produtoServicoLocal.ToDo((ProdutoLocal produtoLocal) =>
					{
						List<CodigoBarraAlternativo> source = produtoLocal.ProdutoEmpresa.Produto.CodigosBarrasAlternativos.ToListEmptyWhenNull();
						quantidadeInformada = (source.Any((CodigoBarraAlternativo x) => x.CodigoBarras.ToLower().Equals(textoPesquisa.ToLower())) ? ((decimal)source.FirstOrDefault((CodigoBarraAlternativo x) => x.CodigoBarras.Equals(textoPesquisa)).FatorConversaoVenda * quantidadeInformada) : quantidadeInformada);
					});
					produtoServicoLocal.Vender(quantidadeInformada, CapturouPeso);
				}
				Limpar();
			}
			else
			{
				NaoLocalizado();
			}
		}

		public void GravarLog(string informacao)
		{
			string path = Path.Combine(AppDomain.CurrentDomain.BaseDirectory, "LogBalanca.txt");
			if (!File.Exists(path))
			{
				return;
			}
			using StreamWriter streamWriter = new StreamWriter(path, append: true);
			streamWriter.WriteLine(informacao);
			streamWriter.Close();
		}

		private bool LancouKit(string codigoBarras, string codigoInterno)
		{
			if (string.IsNullOrWhiteSpace(codigoInterno))
			{
				return false;
			}
			PainelBuscaKit painelBuscaKit = _painel.Seletor.Get<PainelBuscaKit>();
			if (painelBuscaKit.IsNull())
			{
				return false;
			}
			string id = _painel.SessaoService.Sessao.Perfis.ItemSelecionado.Empresa.Id;
			DigisatServer.Domain.Main.Aggregates.CadastrosAgg.Kits.Kit kit = painelBuscaKit.KitRepositoryRead.ObterPorCodigoInterno(codigoInterno, id);
			if (kit.IsNull())
			{
				return false;
			}
			if (!painelBuscaKit.ComposicaoDisponivel(kit))
			{
				DialogoFactory.MostrarDialogoConfirma("Kit não importado: um dos produtos da composição não está disponível nesta empresa.", bloquearEnter: true);
				return true;
			}
			if (!ProcessarCodigoDeBarrasService.TentarObterQuantidadeDeKit(codigoBarras, painelBuscaKit.ObterPreco(kit), out var quantidade))
			{
				DialogoFactory.MostrarDialogoConfirma("Não foi possível determinar a quantidade de kits pela etiqueta. Gere novamente o arquivo para a balança e repita a leitura.", bloquearEnter: true);
				return true;
			}
			painelBuscaKit.ExpandirKit(kit, quantidade);
			return true;
		}

