		protected async Task<ResultadoPesquisa<ProdutoServicoLocal>> PesquisarAsync(string informacao)
		{
			try
			{
				LoaderProcessoService.MostrarLoader("Pesquisando...");
				PerfilEmpresaSessao perfilEmpresa = _painel.SessaoService.Sessao.Perfis.ItemSelecionado;
				ObjectId idTabelaPreco = _painel.Seletor.Get<PainelDocumentoFiscal>().TabelaPrecoLocal?.Id ?? ObjectId.Empty;
				return RetornarResultadoPesquisa(informacao, await _painel.ProdutoServicoEmpresaRepositoryRead.Find(ProdutoServicoSpecifications.Ativo(), informacao, perfilEmpresa.Empresa.Id, idTabelaPreco.ToString(), 1, 1), perfilEmpresa, idTabelaPreco);
			}
			finally
			{
				LoaderProcessoService.EsconderLoader();
			}
		}

		private ResultadoPesquisa<ProdutoServicoLocal> RetornarResultadoPesquisa(string informacao, IPage<ProdutoServicoEmpresa> pagina, PerfilEmpresaSessao perfilEmpresa, ObjectId idTabelaPreco, bool executarFiltroSomenteItensComQuantidadeSaldoPositiva = false)
		{
			IEnumerable<ProdutoServicoEmpresa> source = pagina.Lista;
			if (executarFiltroSomenteItensComQuantidadeSaldoPositiva && DadosSistema.ConfiguracaoDto.Saida.MostrarSomenteItensComQuantidadeSaldoPositiva.Valor)
			{
				source = pagina.Lista.Where((ProdutoServicoEmpresa x) => x.Is<ServicoEmpresa>() || (x.Is<ProdutoEmpresa>() && x.To<ProdutoEmpresa>().Estoque.QuantidadeSaldo > 0m));
			}
			return new ResultadoPesquisa<ProdutoServicoLocal>(from x in source
				where x.Vendavel
				select FluentFactory<ProdutoServicoLocalFactory>.Init().ComSeletor(_painel.Seletor).ComInformacaoPesquisa(informacao)
					.ComPermissaoEstoqueNegativo(perfilEmpresa.Configuracao.PermitirEstoqueNegativo)
					.ComProdutoServicoEmpresa(x.SetarTabelaPreco(idTabelaPreco))
					.Criar() into a
				orderby a.Descricao.ToLower().StartsWith(informacao.ToLower()) descending
				select a);
		}

		protected override ResultadoPesquisa<ProdutoServicoLocal> Pesquisar(string informacao)
		{
			try
			{
				LoaderProcessoService.MostrarLoader("Pesquisando...");
				PerfilEmpresaSessao itemSelecionado = _painel.SessaoService.Sessao.Perfis.ItemSelecionado;
				ObjectId idTabelaPreco = _painel.Seletor.Get<PainelDocumentoFiscal>().TabelaPrecoLocal?.Id ?? ObjectId.Empty;
				List<ProdutoServicoLocal> list = new List<ProdutoServicoLocal>();
				for (short num = 1; num <= 10; num++)
				{
					IPage<ProdutoServicoEmpresa> result = _painel.ProdutoServicoEmpresaRepositoryRead.Find(ProdutoServicoSpecifications.Ativo(), informacao, itemSelecionado.Empresa.Id, idTabelaPreco.ToString(), num, 300).Result;
					list.AddRange(RetornarResultadoPesquisa(informacao, result, itemSelecionado, idTabelaPreco, executarFiltroSomenteItensComQuantidadeSaldoPositiva: true).Resultados);
					if (list.Count >= 300 || result.Lista.Count() < 300)
					{
						break;
					}
				}
				return new ResultadoPesquisa<ProdutoServicoLocal>(list.OrderByDescending((ProdutoServicoLocal a) => a.Descricao.ToLower().StartsWith(informacao.ToLower())).Take(300).ToList());
			}
			finally
			{
				LoaderProcessoService.EsconderLoader();
			}
		}

