		public void SalvarObservacao(string observacao)
		{
			if (Observacoes.Any((string x) => x.Contains(observacao)))
			{
				Observacoes.Remove(observacao);
			}
			else
			{
				Observacoes.Add(observacao);
			}
			ObservacaoToString = ((!Observacoes.Any()) ? null : string.Join(", ", Observacoes));
		}

		public void SalvarObservacoes(IEnumerable<string> observacoes)
		{
			if (!observacoes.Any())
			{
				return;
			}
			foreach (string observaco in observacoes)
			{
				Observacoes.Add(observaco);
			}
			ObservacaoToString = ((!Observacoes.Any()) ? null : string.Join("\n", Observacoes));
		}

		public ItemDocumentoFiscal AplicarDesconto(decimal valor, AutorizacaoDto autorizacao, IEmissorService emissorService)
		{
			ValidarDescontoAcrescimo(emissorService);
			if (valor == 0m && DialogoFactory.MostrarDialogoSimNao("Remover o desconto aplicado?") == MessageBoxResult.Yes)
			{
				Desconto = 0m;
			}
			if (Total <= valor || valor <= 0m)
			{
				throw new Exception("Desconto inválido");
			}
			Autorizacao = autorizacao;
			decimal num = LimiteDesconto;
			decimal num2 = TotalBruto * DadosSistema.LimiteDescontoUsuario / 100m;
			if (num2 > num)
			{
				num = num2;
			}
			decimal num3 = (Ativo ? (((num == 0m) ? (TotalBruto - 0.01m) : (TotalBruto * num / 100m)) - Desconto) : 0m);
			if (valor > num3 && (num > 0m || DadosSistema.LimiteDescontoUsuario > 0m))
			{
				if (DialogoFactory.MostrarDialogoSimNao("Limite de desconto atingido. Continuar?").Equals(MessageBoxResult.Yes))
				{
					autorizacao = _permitirVenderAcimaDoLimiteDeDesconto();
					if (autorizacao.IsNotNull())
					{
						decimal num4 = TotalBruto * autorizacao.LimiteDesconto / 100m;
						if (autorizacao.Direito.GetType() != typeof(DireitoDtoNull) || num4 >= valor)
						{
							Desconto = valor;
							if (autorizacao.Direito.GetType() != typeof(DireitoDtoNull))
							{
								Autorizacao = autorizacao;
							}
							return this;
						}
						DialogoFactory.MostrarDialogoConfirma($"Excedido o limite de desconto do usuário informado : {autorizacao.LimiteDesconto}%");
					}
				}
				valor = 0m;
			}
			Desconto = valor;
			return this;
		}

		private void PreencherAutorizacoes()
		{
			List<AutorizacaoDto> list = Autorizacoes.ToListEmptyWhenNull();
			if (!Autorizacao.IsNull() && !Autorizacao.Is<AutorizacaoDtoNull>())
			{
				list.Add(Autorizacao);
				Autorizacoes = list;
			}
		}

		public ItemDocumentoFiscal AplicarAcrescimo(decimal valor, AutorizacaoDto autorizacaoDto, IEmissorService emissorService)
		{
			ValidarDescontoAcrescimo(emissorService);
			if (valor >= Total || valor <= 0m)
			{
				throw new Exception("Acréscimo inválido");
			}
			Autorizacao = autorizacaoDto;
			Acrescimo = valor;
			return this;
		}

		private void ValidarDescontoAcrescimo(IEmissorService emissorService)
		{
			if (!Ativo)
			{
				throw new Exception("Item não permite esta operação");
			}
			if (emissorService.Is<IEcfService>() && (Desconto > 0m || Acrescimo > 0m))
			{
				throw new Exception("Item já possui valor de Acréscimo/Desconto");
			}
		}

