		public void VerificarCondicaoEspecial(IEnumerable<ItemDocumentoFiscal> listaItens, IEmissorService emissorService)
		{
			if (!TemCondicaoEspecial || !(DateTime.Now >= CondicaoEspecial.DataVigenciaInicial.Date) || !(DateTime.Now <= CondicaoEspecial.DataVigenciaFinal.ToFinalDia()))
			{
				return;
			}
			List<ItemDocumentoFiscal> list = listaItens.Where((ItemDocumentoFiscal x) => x.Ativo && x.Codigo == Codigo && x.QuantidadeDisponivel > 0m).ToList();
			decimal num = list.Sum((ItemDocumentoFiscal itemDocumentoFiscal) => itemDocumentoFiscal.QuantidadeDisponivel) + Quantidade;
			if (num >= CondicaoEspecial.Quantidade)
			{
				int num2 = (int)(num / CondicaoEspecial.Quantidade);
				decimal num3 = num % CondicaoEspecial.Quantidade;
				if (CondicaoEspecial.Is<CondicaoEspecialPrecoDiferenciadoUltimoItem>())
				{
					Desconto = ((PrecoUnitario - CondicaoEspecial.Preco) * (decimal)num2).ArredondarParaDuasCasasDecimais();
					emissorService.AplicarDesconto(this, Desconto);
					ZerarQuantidadeDisponivel(list);
					QuantidadeDisponivel = ((num3 > 0m) ? num3 : 0m);
				}
				else if (CondicaoEspecial.Is<CondicaoEspecialPrecoDiferenciadoTodosOsItens>())
				{
					decimal num4 = PrecoUnitario - CondicaoEspecial.Preco;
					if (num4 >= 0m)
					{
						QuantidadeDisponivel = ((num3 > 0m) ? num3 : 0m);
						decimal quantidade = num - QuantidadeDisponivel - list.Where((ItemDocumentoFiscal a) => a.Desconto == 0m).Sum((ItemDocumentoFiscal x) => x.QuantidadeDisponivel);
						AplicarDescontoNoItemCorrente(emissorService, num3, num2, num4.ArredondarParaDuasCasasDecimais(), quantidade);
						foreach (ItemDocumentoFiscal item in list.Where((ItemDocumentoFiscal a) => a.Desconto == 0m))
						{
							if (num3 > 0m)
							{
								if (item.Quantidade < (decimal)num2 * CondicaoEspecial.Quantidade)
								{
									item.Desconto = (item.Quantidade * num4).ArredondarParaDuasCasasDecimais();
								}
								else
								{
									item.Desconto = ((decimal)num2 * CondicaoEspecial.Quantidade * num4).ArredondarParaDuasCasasDecimais();
								}
							}
							else
							{
								item.Desconto = (item.Quantidade * num4).ArredondarParaDuasCasasDecimais();
							}
							emissorService.AplicarDesconto(item, item.Desconto);
						}
						ZerarQuantidadeDisponivel(list);
					}
				}
			}
			else
			{
				QuantidadeDisponivel = Quantidade;
			}
			if (CondicaoEspecial.Is<CondicaoEspecialPrecoDiferenciadoTodosOsItensAPartirDeterminadaQuantidade>())
			{
				decimal num5 = PrecoUnitario - CondicaoEspecial.Preco;
				decimal num6 = listaItens.Where((ItemDocumentoFiscal x) => x.Ativo && x.Codigo == Codigo && x.Quantidade > 0m).Sum((ItemDocumentoFiscal a) => a.Quantidade) + Quantidade;
				if (num5 >= 0m && num6 >= CondicaoEspecial.Quantidade)
				{
					AplicarDescontoNoItemCorrente(emissorService, 0m, 0m, num5.ArredondarParaDuasCasasDecimais(), Quantidade);
					foreach (ItemDocumentoFiscal item2 in list.Where((ItemDocumentoFiscal a) => a.Desconto == 0m))
					{
						item2.Desconto = (item2.Quantidade * num5).ArredondarParaDuasCasasDecimais();
						emissorService.AplicarDesconto(item2, item2.Desconto);
					}
				}
			}
			if (!CondicaoEspecial.Is<CondicaoEspecialPercentualDescontoTodosOsItensAPartirDeterminadaQuantidade>())
			{
				return;
			}
			decimal num7 = PrecoUnitario * (CondicaoEspecial.Preco / 100m);
			decimal num8 = listaItens.Where((ItemDocumentoFiscal x) => x.Ativo && x.Codigo == Codigo && x.Quantidade > 0m).Sum((ItemDocumentoFiscal a) => a.Quantidade) + Quantidade;
			if (!(num7 >= 0m) || !(num8 >= CondicaoEspecial.Quantidade))
			{
				return;
			}
			AplicarDescontoNoItemCorrente(emissorService, 0m, 0m, num7.TruncarValor(4), Quantidade);
			foreach (ItemDocumentoFiscal item3 in list.Where((ItemDocumentoFiscal a) => a.Desconto == 0m))
			{
				item3.Desconto = (item3.Quantidade * num7).ArredondarParaDuasCasasDecimais();
				emissorService.AplicarDesconto(item3, item3.Desconto);
			}
		}

		private void AplicarDescontoNoItemCorrente(IEmissorService emissorService, decimal quantidadeRestanteCondicaoEspecial, decimal numeroVezesAtendeCondicaoEspecial, decimal valorCalculado, decimal quantidade)
		{
			if (quantidadeRestanteCondicaoEspecial > 0m)
			{
				if (Quantidade < numeroVezesAtendeCondicaoEspecial * CondicaoEspecial.Quantidade)
				{
					decimal desconto = (Quantidade - QuantidadeDisponivel) * valorCalculado;
					ProcessarDescontoCondicaoEspecial(desconto);
				}
				else
				{
					decimal desconto2 = quantidade * valorCalculado;
					ProcessarDescontoCondicaoEspecial(desconto2);
				}
			}
			else
			{
				decimal desconto3 = quantidade * valorCalculado;
				ProcessarDescontoCondicaoEspecial(desconto3);
			}
			emissorService.AplicarDesconto(this, Desconto);
		}

		private void ProcessarDescontoCondicaoEspecial(decimal desconto)
		{
			if (!(desconto <= 0m))
			{
				if (Total <= desconto.ArredondarParaDuasCasasDecimais())
				{
					throw new Exception("Não é possível aplicar o desconto.\nLance o item da condição especial na sua totalidade ou de forma individual.");
				}
				Desconto = desconto.ArredondarParaDuasCasasDecimais();
			}
		}

		private static void ZerarQuantidadeDisponivel(List<ItemDocumentoFiscal> itens)
		{
			foreach (ItemDocumentoFiscal iten in itens)
			{
				iten.QuantidadeDisponivel = 0m;
			}
		}

