		public void CalcularValorIcmsDesonerado(PreDocumentoFiscal preDocumentoFiscal)
		{
			if (!DadosSistema.ConfiguracaoDto.Saida.DescontarValorIcmsDesonerado.Valor)
			{
				ValorIcmsDesonerado = 0m;
				return;
			}
			DigisatServer.Domain.Main.Aggregates.MovimentacoesAgg.Itens.IItemDocumentoFiscal itemDocumentoFiscal = ObterItem(preDocumentoFiscal);
			Percentual?.SetarItem((IItemDocumentoAuxiliarProduto)itemDocumentoFiscal);
			ValorIcmsDesonerado = Percentual.To<IPercentualDesonerado>()?.ValorICMSDesonerado ?? 0m;
		}

		public ItemDocumentoFiscal ProcessarComissaoTabelaPreco(TabelaPrecoLocal tabelaPrecoLocal)
		{
			ProdutoLocal produtoLocal = ProdutoServicoLocal.To<ProdutoLocal>();
			ProdutoEmpresa produtoEmpresa = produtoLocal?.ProdutoEmpresa;
			if (tabelaPrecoLocal.IsNull() || tabelaPrecoLocal.IsNenhuma)
			{
				return this;
			}
			if (tabelaPrecoLocal.TabelaPrecoDto.TipoItensTabelaPreco == TipoItensTabelaPreco.ItensSelecionados && ProdutoServicoLocal.Is<ProdutoLocal>() && !produtoLocal.ProdutoEmpresa.Preco.TabelaPreco.FirstOrDefault((DigisatServer.Domain.Main.Aggregates.CadastrosAgg.TabelasPreco.TabelaPreco y) => y.Id.Equals(tabelaPrecoLocal.Id)).Itens.Any((ItemTabelaPreco z) => z.PrecoReferencia.Equals(produtoEmpresa?.PrecoReferencia)))
			{
				return this;
			}
			ProdutoServicoLocal.ProcessarComissaoTabelaPreco(tabelaPrecoLocal, produtoLocal?.ProdutoEmpresa?.Preco?.TabelaPreco.FirstOrDefault((DigisatServer.Domain.Main.Aggregates.CadastrosAgg.TabelasPreco.TabelaPreco y) => y.Id.Equals(tabelaPrecoLocal.Id))?.Itens.FirstOrDefault((ItemTabelaPreco x) => x.PrecoReferencia.Equals(produtoEmpresa?.PrecoReferencia))?.PercentualComissaoItem ?? 0m);
			return this;
		}
	}
