	public class PontoDeVendaViewModel : BaseMinimizar
	{
		private readonly IConfiguracaoClientService _configuracaoClientService;

		private bool _podeMudarModoFuncionamento = true;

		private readonly CompositeDisposable _subscriptionsMain;

		private CompositeDisposable _subscriptions;

		private IList<IModoFuncionamento> _modosFuncionamento;

		private IDisposable _disposable;

		private static int _contador;

		public bool SincronizadorRodando
		{
			get
			{
