		public bool PermiteAlterarModoFuncionamento => DadosSistema.VerificarPermissao<DigisatServer.Infrastructure.Crosscutting.Module.PontoDeVenda, PermitirAlterarModoFuncionamentoPontoDeVenda>();

		public IModoFuncionamento ModoFuncionamento
		{
			get
			{
				return GetProperty(() => ModoFuncionamento);
