			set
			{
				if ((ModoFuncionamento == null || PermiteAlterarModoFuncionamento) && _podeMudarModoFuncionamento)
				{
					ModoFuncionamento?.UnLoad();
					SetProperty(() => ModoFuncionamento, value, OnModoFuncionamentoChanged);
				}
			}
