		public ICommand EntregarCommand { get; set; }

		public ICommand CtrlF2Command { get; set; }

		public PontoDeVendaViewModel(IList<IModoFuncionamento> modosFuncionamento, IEventPublisher eventPublisher, IConfiguracaoClientService configuracaoClientService)
		{
			EntregarCommand = new DelegateCommand(() =>
			{
			}, () => false);
			CtrlF2Command = new DelegateCommand(() =>
			{
			}, () => false);
			_configuracaoClientService = configuracaoClientService;
			ModosFuncionamento = modosFuncionamento;
			SetarAtalhos(modosFuncionamento);
			_subscriptionsMain = new CompositeDisposable
			{
				eventPublisher.GetEvent((Tef tef) =>
				{
					_subscriptions?.Dispose();
					_subscriptions = new CompositeDisposable
					{
						tef.WhenDepoisCancelarTransacoesEvent.Subscribe((TefDepoisCancelarTransacoesEventArgs args) =>
						{
							_podeMudarModoFuncionamento = true;
						}),
						tef.WhenDepoisConfirmarTransacoesEvent.Subscribe((TefDepoisConfirmarTransacoesEventArgs args) =>
						{
							_podeMudarModoFuncionamento = true;
						})
					};
					_podeMudarModoFuncionamento = !tef.RespostasPendentes.Any();
				}),
				eventPublisher.GetEvent((TerminouNotaFiscalManualPostoEvent x) =>
				{
					ModoFuncionamento = ModosFuncionamento.FirstOrDefault((IModoFuncionamento i) => i is ModoFuncionamentoCupomFiscal);
				}),
				eventPublisher.GetEvent((ChamarRestauranteEvent @event) =>
				{
					NavigationParameters navigationParameters = new NavigationParameters
					{
						{ "BloquearNavegacaoPessoa", true },
						{ "Comanda", @event.Comanda }
					};
					Navegar("RestauranteView", (NavigationResult navigationResult) =>
					{
					}, navigationParameters);
				})
			};
			SincronizadorRodando = true;
			_disposable = Observable.Interval(TimeSpan.FromSeconds(5.0)).Subscribe((long x) =>
			{
				Monitorar();
			});
		}

		private void Monitorar()
		{
			try
			{
				ServiceController serviceController = new ServiceController("SincronizadorDigisat");
				serviceController.Refresh();
				SincronizadorRodando = serviceController.Status == ServiceControllerStatus.Running;
				if (serviceController.Status != ServiceControllerStatus.Running)
				{
					_contador++;
				}
				if (_contador == 10)
				{
					_contador = 0;
					serviceController.Start();
				}
			}
			catch (Exception)
			{
			}
		}

		private void SetarAtalhos(IList<IModoFuncionamento> modosFuncionamento)
		{
			Key key = Key.D1;
			foreach (IModoFuncionamento modoFuncionamento in modosFuncionamento)
			{
				modoFuncionamento.SetarAtalho(new KeyCustom(key, ((int)(key - 34)).ToString()), () =>
				{
					if (modoFuncionamento.Habilitado)
					{
						ModoFuncionamento = modoFuncionamento;
					}
				});
				key++;
			}
		}

		private void SetarModoFuncionamento(IModoFuncionamento modoFuncionamento)
		{
			string ultimoModoFuncionamento = _configuracaoClientService.ObterConfiguracao()?.UltimoModoFuncionamento;
			if (ModosFuncionamento.Any((IModoFuncionamento x) => x.GetType().Name == ultimoModoFuncionamento && x.Habilitado))
			{
				ModoFuncionamento = (string.IsNullOrWhiteSpace(ultimoModoFuncionamento) ? modoFuncionamento : ModosFuncionamento.FirstOrDefault((IModoFuncionamento x) => x.GetType().Name == ultimoModoFuncionamento && x.Habilitado));
			}
			else
			{
				ModoFuncionamento = ModosFuncionamento.FirstOrDefault((IModoFuncionamento x) => x.Habilitado);
			}
			ModoFuncionamento?.SetarComoUltimoModoFuncionamento();
		}

		private void OnModoFuncionamentoChanged()
		{
			ModoFuncionamento.Load();
			ConfiguracaoClient configuracaoClient = _configuracaoClientService.ObterConfiguracao();
			configuracaoClient.SetarUltimoModoFuncionamento(ModoFuncionamento.GetType().Name);
			_configuracaoClientService.Salvar(configuracaoClient);
		}

		public override void Dispose()
		{
			_disposable?.Dispose();
			_disposable = null;
			_subscriptions?.Dispose();
			_subscriptionsMain?.Dispose();
			base.Dispose();
		}

		public override void FecharView()
		{
			if (ModoFuncionamento.Is<ModoFuncionamentoNfce>())
			{
				ModoFuncionamentoNfce modoFuncionamentoNfce = ModoFuncionamento.To<ModoFuncionamentoNfce>();
				if (modoFuncionamentoNfce != null && modoFuncionamentoNfce.TipoEmissao == 9)
				{
					int num = DadosSistema.GetService().Canal((INotaFiscalConsumidorEletronicaModuleService service) => service.QuantidadeDocumentosEmitidosEmContingencia());
					if (num > 0 && DialogoFactory.MostrarDialogoSimNao($"{num} notas fiscais emitidas em contingência não foram transmitidas. Continuar mesmo assim?") != MessageBoxResult.Yes)
					{
						return;
					}
				}
			}
			base.FecharView();
		}

		protected override void OnParametroInformado(object sender, NavigationParameters navigationParameters)
		{
			base.OnParametroInformado(sender, navigationParameters);
			Resolucao?.Update();
		}
	}
