				return GetProperty(() => DescricaoComando);
			}
			set
			{
				SetProperty(() => DescricaoComando, value);
			}
		}

		public decimal Preco
		{
			get
			{
				return GetProperty(() => Preco);
			}
			set
			{
				SetProperty(() => Preco, value);
			}
		}

		public string Status
		{
			get
			{
				return GetProperty(() => Status);
			}
			set
			{
				SetProperty(() => Status, value);
			}
		}

		public StatusBico StatusBico
		{
			get
			{
				return GetProperty(() => StatusBico);
			}
			set
			{
				SetProperty(() => StatusBico, value);
			}
		}

		public string IdBico { get; set; }

		public BicoStatusViewModel(BicoStatus bicoStatus, IEventPublisher eventPublisher)
		{
			_eventPublisher = eventPublisher;
			Atualizar(bicoStatus);
		}

		public void Atualizar(BicoStatus bicoStatus)
		{
			IdBico = bicoStatus.IdBico;
			NumeroBico = bicoStatus.BicoNoSoftware;
			Combustivel = bicoStatus.Combustivel;
			Preco = bicoStatus.Preco;
			Status = bicoStatus.Status.RetornarDescricao();
			StatusBico = bicoStatus.Status;
			BicoStatusViewModel bicoStatusViewModel = this;
			string descricaoComando;
			if (StatusBico == StatusBico.Abastecendo)
			{
				descricaoComando = "Enter - Parar";
			}
			else
			{
				descricaoComando = ((StatusBico == StatusBico.SolicitaLiberacao) ? "Enter - Autorizar" : string.Empty);
			}
			bicoStatusViewModel.DescricaoComando = descricaoComando;
		}

		private void Autorizar()
		{
			_eventPublisher.Publish(new AutorizarAbastecimentoRequest(IdBico));
			Status = "Aguarde";
		}

		private void Parar()
		{
			_eventPublisher.Publish(new PararAbastecimentoRequest(IdBico));
			Status = "Aguarde";
		}

		public void ExecutarComando()
		{
			if (StatusBico == StatusBico.SolicitaLiberacao)
			{
				Autorizar();
			}
			if (StatusBico == StatusBico.Abastecendo)
			{
				Parar();
			}
		}

		public bool PodeExecutarComando()
		{
			if (StatusBico != StatusBico.Abastecendo)
			{
				return StatusBico == StatusBico.SolicitaLiberacao;
			}
			return true;
		}
	}
