		public DescontinuidadeEncerranteItemInteracao(QuebraContinuidadeEncerranteResponse quebraContinuidadeEncerrante, IEnumerable<LacreBombaDto> lacresBomba)
			: base("Registrar descontinuidade", quebraContinuidadeEncerrante)
		{
			QuebraContinuidadeEncerrante = quebraContinuidadeEncerrante;
			DataHora = quebraContinuidadeEncerrante.DataHora;
			NumeroBomba = quebraContinuidadeEncerrante.NumeroBomba;
			NumeroBico = quebraContinuidadeEncerrante.NumeroBico;
			EncerranteInicial = quebraContinuidadeEncerrante.EncerranteInicial;
			EncerranteFinal = quebraContinuidadeEncerrante.EncerranteFinal;
			TotalLitros = quebraContinuidadeEncerrante.TotalLitros;
			Motivos = new Lista<MotivoDescontinuidadeEncerrante>();
			_lacres = lacresBomba;
			if (quebraContinuidadeEncerrante.MotivoDescontinuidade == MotivoDescontinuidade.ViradaDeMilhao)
			{
				Motivos.Adicionar(new MotivoDescontinuidadeEncerrante(MotivoDescontinuidade.ViradaDeMilhao));
			}
			else
			{
				Motivos.Adicionar(new MotivoDescontinuidadeEncerrante(MotivoDescontinuidade.Indefinido));
				Motivos.Adicionar(new MotivoDescontinuidadeEncerranteSubstituicaoPlaca(lacresBomba));
				Motivos.Adicionar(new MotivoDescontinuidadeEncerrante(MotivoDescontinuidade.DefeitoNaBomba));
				Motivos.Adicionar(new MotivoDescontinuidadeEncerrante(MotivoDescontinuidade.DescargaAtmosferica));
				Motivos.Adicionar(new MotivoDescontinuidadeEncerrante(MotivoDescontinuidade.QuedaDeEnergia));
				Motivos.Adicionar(new MotivoDescontinuidadeEncerrante(MotivoDescontinuidade.Outros));
			}
			Motivos.PosicionarNoPrimeiro();
		}

		public override void Limpar()
		{
			TotalLitros = QuebraContinuidadeEncerrante.TotalLitros;
			EncerranteInicial = QuebraContinuidadeEncerrante.EncerranteInicial;
		}

		public DescontinuidadeEncerranteItemInteracao ComLacres(IEnumerable<LacreBombaDto> lacres)
		{
			_lacres = lacres;
			return this;
		}

		public override DescontinuidadeEncerranteItemInteracao Build()
		{
			return new DescontinuidadeEncerranteItemInteracao(Valor, _lacres);
		}

		public void Confirmar(IWService service, IEventPublisher eventPublisher)
		{
			DescontinuidadeEncerranteDto descontinuidadeEncerranteDto = new DescontinuidadeEncerranteDto
			{
				MotivoDescontinuidade = Motivos.ItemSelecionado.MotivoDescontinuidade,
				Justificativa = Justificativa,
				MedidasAdotadas = MedidasAdotadas,
				IdQuebraContinuidadeEncerrante = Valor.Id
			};
			if (descontinuidadeEncerranteDto.MotivoDescontinuidade == MotivoDescontinuidade.SubstituicaoDaPlaca)
			{
				MotivoDescontinuidadeEncerranteSubstituicaoPlaca motivoDescontinuidadeEncerranteSubstituicaoPlaca = Motivos.ItemSelecionado as MotivoDescontinuidadeEncerranteSubstituicaoPlaca;
				descontinuidadeEncerranteDto.CNPJDaEmpresaQueEfetuouASubstituicao = motivoDescontinuidadeEncerranteSubstituicaoPlaca.CnpjEmpresa;
				descontinuidadeEncerranteDto.CPFDoTecnicoQueEfetuouASubstituicao = motivoDescontinuidadeEncerranteSubstituicaoPlaca.CpfTecnico;
				descontinuidadeEncerranteDto.NomeInterventor = motivoDescontinuidadeEncerranteSubstituicaoPlaca.NomeInterventor;
				descontinuidadeEncerranteDto.DataDaSubstituicao = motivoDescontinuidadeEncerranteSubstituicaoPlaca.Data;
				descontinuidadeEncerranteDto.ValorEncerranteAntesSubstituicao = motivoDescontinuidadeEncerranteSubstituicaoPlaca.EncerranteAntesSubstituicao;
				descontinuidadeEncerranteDto.ValorEncerranteAposSubstituicao = motivoDescontinuidadeEncerranteSubstituicaoPlaca.EncerranteAposSubstituicao;
				descontinuidadeEncerranteDto.NumeroDosLacresAplicados = motivoDescontinuidadeEncerranteSubstituicaoPlaca.LacresAplicados;
				descontinuidadeEncerranteDto.NumeroDosLacresRemovidos = motivoDescontinuidadeEncerranteSubstituicaoPlaca.LacresRemovidos;
				descontinuidadeEncerranteDto.Lacres = motivoDescontinuidadeEncerranteSubstituicaoPlaca.Lacres.Itens;
			}
			service.Canal((IPostoCombustivelModuleService x) =>
			{
				x.AdicionarDescontinuidadeEncerrante(descontinuidadeEncerranteDto);
			});
			QuebraContinuidadeEncerrante.DiminuirTotalLitros(TotalLitros);
			eventPublisher.Publish(new RegistroDescontinuidadeEncerrante(Valor, descontinuidadeEncerranteDto));
		}
	}
