		{
			get
			{
				return GetProperty(() => Complemento);
			}
			set
			{
				SetProperty(() => Complemento, value);
			}
		}

		public string Bairro
		{
			get
			{
				return GetProperty(() => Bairro);
			}
			set
			{
				SetProperty(() => Bairro, value);
			}
		}

		public Lista<UFDto> UFs { get; set; }

		public Lista<MunicipioDto> Municipios
		{
			get
			{
				return GetProperty(() => Municipios);
			}
			set
			{
				SetProperty(() => Municipios, value);
			}
		}

		public ICommand PesquisarCepCommand { get; set; }

		public bool Preenchido
		{
			get
			{
				if (!Cep.IsNullOrEmpty() && !Logradouro.IsNullOrEmpty() && !Numero.IsNullOrEmpty() && !Bairro.IsNullOrEmpty())
				{
					return Municipios.PossuiItemSelecionado;
				}
				return false;
			}
		}

		public string EnderecoToText => $"{Logradouro}, {Numero} {Complemento} {Bairro} " + $"{Municipios?.ItemSelecionado?.Nome}-{Municipios?.ItemSelecionado?.UF.Sigla} {Cep}";

		public Endereco()
		{
			ConsultaCepServiceFactory.SetCurrent(new ConsultaViaCepServiceFactory());
			ConsultaCepServiceFactory.SetWebProxy(DadosSistema.ObterProxy());
			_consultaCepService = ConsultaCepServiceFactory.Create();
			UFs = CriarUFs();
			UFs.Posicionar((UFDto x) => x.CodigoIbge == DadosSistema.EmpresaLogada.Municipio.Uf.CodigoIbge);
			Municipios.Posicionar((MunicipioDto x) => x.CodigoIbge == DadosSistema.EmpresaLogada.Municipio.CodigoIbge);
			PesquisarCepCommand = new DelegateCommand(PesquisarCep);
		}

		private Lista<UFDto> CriarUFs()
		{
			Lista<UFDto> lista = new Lista<UFDto>();
			lista.AdicionarSemPosicionar(from x in UFValueObjectService.ObterDtos()
				orderby x.Nome
				select x);
			lista.AlterouItemSelecionadoEvent += ListaOnAlterouItemSelecionadoEvent;
			return lista;
		}

		private void ListaOnAlterouItemSelecionadoEvent(object sender, UFDto ufDto)
		{
			if (Municipios.IsNull())
			{
				Municipios = new Lista<MunicipioDto>();
			}
			Municipios.Limpar();
			Municipios = CriarMunicipios(ufDto.CodigoIbge);
			Municipios.PosicionarNoPrimeiro();
		}

		private Lista<MunicipioDto> CriarMunicipios(int codigoIbgeUf)
		{
			Lista<MunicipioDto> lista = new Lista<MunicipioDto>();
			lista.Adicionar(from x in MunicipioValueObjectService.ObterMunicipiosPorCodigoIbgeUf(codigoIbgeUf)
				orderby x.Nome
				select x);
			return lista;
		}

		private void PesquisarCep()
		{
			try
			{
				OnConsultouCepEvent(_consultaCepService.ObterCep(Cep.RemoveDiacritics()));
			}
			catch (Exception ex)
			{
				ex.ShowLastException();
				Cep = string.Empty;
			}
		}

		private void OnConsultouCepEvent(CepInfo cepInfo)
		{
			if (cepInfo.Is<CepInvalido>())
			{
				throw new Exception("CEP inválido ou não encontrado.");
			}
			Logradouro = cepInfo.Logradouro;
			Bairro = cepInfo.Bairro;
			UFs.Posicionar((UFDto x) => x.CodigoIbge == cepInfo.Municipio.Uf.CodigoIbge);
			Municipios.Posicionar((MunicipioDto x) => x.CodigoIbge == cepInfo.Municipio.CodigoIbge);
			if (!string.IsNullOrWhiteSpace(Logradouro))
			{
				InformouCepComLogradouro = !string.IsNullOrWhiteSpace(Logradouro);
			}
		}

		public void Limpar()
		{
			Cep = string.Empty;
			Logradouro = string.Empty;
			Numero = string.Empty;
			Complemento = string.Empty;
			Bairro = string.Empty;
		}
	}
