	public class ItemComissaoLocal
	{
		public BaseCalculoComissao BaseCalculoComissao { get; protected set; }

		public IEnumerable<ItemDocumentoFiscal> Itens { get; protected set; }

		public ObjectId IdVendedor { get; protected set; }

		public string NomeVendedor { get; protected set; }

		public decimal PercentualComissao { get; protected set; }

		public decimal ValorComissao => ObterBaseCalculosComissao();

		public ItemComissaoLocal(ObjectId idVendedor, string nomeVendedor, decimal percentualComissao, BaseCalculoComissao baseCalculoComissao, IEnumerable<ItemDocumentoFiscal> itens)
		{
			IdVendedor = idVendedor;
			NomeVendedor = nomeVendedor;
			PercentualComissao = percentualComissao;
			BaseCalculoComissao = baseCalculoComissao;
			Itens = itens;
		}

		private decimal ObterBaseCalculosComissao()
		{
			decimal num = 0m;
			return BaseCalculoComissao switch
			{
				BaseCalculoComissao.TotalBruto => Itens.Where((ItemDocumentoFiscal x) => x.Ativo).Sum((ItemDocumentoFiscal itemDocumentoFiscal) => (itemDocumentoFiscal.TotalBruto * (PercentualComissao / 100m)).ArredondarParaDuasCasasDecimais()), 
				BaseCalculoComissao.Total => Itens.Where((ItemDocumentoFiscal x) => x.Ativo).Sum((ItemDocumentoFiscal itemDocumentoFiscal) => (itemDocumentoFiscal.Total * (PercentualComissao / 100m)).ArredondarParaDuasCasasDecimais()), 
				BaseCalculoComissao.TotalLiquido => Itens.Where((ItemDocumentoFiscal x) => x.Ativo).Sum((ItemDocumentoFiscal itemDocumentoFiscal) => (itemDocumentoFiscal.TotalLiquido * (PercentualComissao / 100m)).ArredondarParaDuasCasasDecimais()), 
				_ => num, 
			};
		}
	}
