		public Lista<LacreBombaDto> Lacres { get; set; }

		public List<LacreBombaDto> LacresAplicados { get; set; } = new List<LacreBombaDto>();

		public List<LacreBombaDto> LacresRemovidos { get; set; } = new List<LacreBombaDto>();

		public ICommand AdicionarLacreCommand { get; set; }

		public ICommand RemoverLacreCommand { get; set; }

		public MotivoDescontinuidadeEncerranteSubstituicaoPlaca(IEnumerable<LacreBombaDto> lacres)
			: base(MotivoDescontinuidade.SubstituicaoDaPlaca)
		{
			Lacres = new Lista<LacreBombaDto>();
			Lacres.Adicionar(lacres);
			Lacres.PosicionarNoPrimeiro();
			Data = DateTime.Now;
			AdicionarLacreCommand = new DelegateCommand(AdicionarLacre, PodeAdicionarLacre);
			RemoverLacreCommand = new DelegateCommand(RemoverLacre, PodeRemoverLacre);
		}

		private void AdicionarLacre()
		{
			LacreBombaDto item = new LacreBombaDto
			{
				DataAplicacao = Data,
				Numero = NumeroLacre
			};
			Lacres.Adicionar(item);
			LacresAplicados.Add(item);
			NumeroLacre = string.Empty;
		}

		private bool PodeAdicionarLacre()
		{
			if (!string.IsNullOrWhiteSpace(NumeroLacre))
			{
				return !Lacres.Existe((LacreBombaDto x) => x.Numero == NumeroLacre);
			}
			return false;
		}

		private void RemoverLacre()
		{
			LacresRemovidos.Add(Lacres.ItemSelecionado);
			Lacres.Remover(Lacres.ItemSelecionado);
		}

		private bool PodeRemoverLacre()
		{
			return Lacres.PossuiItemSelecionado;
		}
	}
