			{
				SetProperty(() => FocoNaNota, value);
			}
		}

		public Lista<NotaManualVolumeViewModel> Notas { get; set; }

		public ICommand AdicionarNotaCommand { get; set; }

		public ICommand RemoverNotaCommand { get; set; }

		public QuebraContinuidadeEncerranteResponse QuebraContinuidadeEncerrante { get; }

		public NotaManualItemInteracao()
		{
		}

		public NotaManualItemInteracao(QuebraContinuidadeEncerranteResponse quebraContinuidadeEncerrante)
			: base("Registrar nota manual", quebraContinuidadeEncerrante)
		{
			TotalLitros = quebraContinuidadeEncerrante.TotalLitros;
			Notas = new Lista<NotaManualVolumeViewModel>();
			Notas.AlterouEvent += NotasOnAlterouEvent;
			AdicionarNotaCommand = new DelegateCommand(AdicionarNota, PodeAdicionarNota);
			RemoverNotaCommand = new DelegateCommand(RemoverNota, PodeRemoverNota);
			QuebraContinuidadeEncerrante = quebraContinuidadeEncerrante;
		}

		private void NotasOnAlterouEvent(object sender, IEnumerable<NotaManualVolumeViewModel> notaManualVolumeViewModels)
		{
			TotalLitros = Valor.TotalLitros - notaManualVolumeViewModels.Sum((NotaManualVolumeViewModel x) => x.Volume);
		}

		private void AdicionarNota()
		{
			Notas.Adicionar(new NotaManualVolumeViewModel(NumeroNota, Volume));
			NumeroNota = 0;
			Volume = 0m;
			FocoNaNota = !FocoNaNota;
		}

		private bool PodeAdicionarNota()
		{
			if (NumeroNota > 0 && Volume > 0m && TotalLitros - Volume >= 0m)
			{
				return !Notas.Existe((NotaManualVolumeViewModel x) => x.Numero == NumeroNota);
			}
			return false;
		}

		private void RemoverNota()
		{
			Notas.Remover(Notas.ItemSelecionado);
		}

		private bool PodeRemoverNota()
		{
			return Notas.PossuiItemSelecionado;
		}

		public override NotaManualItemInteracao Build()
		{
			return new NotaManualItemInteracao(Valor);
		}

		public override void Limpar()
		{
			Notas.Limpar();
			TotalLitros = QuebraContinuidadeEncerrante.TotalLitros;
		}

		public void Confirmar(IWService service, IEventPublisher eventPublisher)
		{
			List<NotaManualAbastecimento> notasManuaisAbastecimentos = Notas.Itens.Select((NotaManualVolumeViewModel nota) =>
			{
				IAbastecimento abastecimento = service.Canal((IPostoCombustivelModuleService x) => x.AdicionarAbastecimentoNotaManual(Valor.IdBico, nota.Volume, nota.Numero)).Morfar();
				QuebraContinuidadeEncerrante.RegistrarAbastecimentosNotas(abastecimento);
				return new NotaManualAbastecimento(nota.Numero, abastecimento);
			}).ToList();
			eventPublisher.Publish(new RegistroNotaManualQuebraContinuidadeEncerrante(null, notasManuaisAbastecimentos));
		}
	}
