	public class PainelAberturaTurno : PainelInteracao<PainelAberturaTurno>
	{
		private readonly IEmissorService _emissorService;

		private readonly IWService _service;

		private readonly Seletor<IPainel> _seletor;

		private readonly ISessaoService _sessaoService;

		private ItemInteracaoDecimalFocusable _saldoInicial;

		private ItemInteracaoTexto _observacao;

		private bool _emissorPronto;

		private readonly IRepositoryBaseWrite<ValorSangriaLocal> _valorSangriaRepositoryWrite;

		private readonly IRepositoryRead<ValorSangriaLocal> _valorSangriaRepositoryRead;

		public override string Titulo => "Abrir turno";

		public PainelAberturaTurno()
		{
		}

		public PainelAberturaTurno(IRepositoryBaseWrite<ValorSangriaLocal> valorSangriaRepositoryWrite, IRepositoryRead<ValorSangriaLocal> valorSangriaRepositoryRead, IEmissorService emissorService, IWService service, Seletor<IPainel> seletor, ISessaoService sessaoService)
			: base(seletor)
		{
			_valorSangriaRepositoryWrite = valorSangriaRepositoryWrite;
			_valorSangriaRepositoryRead = valorSangriaRepositoryRead;
			_emissorService = emissorService;
			_service = service;
			_seletor = seletor;
			_sessaoService = sessaoService;
			_saldoInicial = ItemInteracaoBase<ItemInteracaoDecimalFocusable, decimal>.Criar().ComDescricao("Saldo inicial").Build();
			_observacao = ItemInteracaoBase<ItemInteracaoTexto, string>.Criar().ComDescricao("Observação").Build();
			Campos.Add(_saldoInicial);
			Campos.Add(_observacao);
		}

		public override void Load()
		{
			try
			{
				if (!_service.Canal((ITurnoModuleService service) => service.ObterTurnoAbertoDoUsuarioLogadoAsync()).Result.Is<TurnoDtoNull>())
				{
					throw new Exception("Já existe um turno aberto para este usuário.");
				}
				_emissorPronto = _emissorService.Carregado && !_emissorService.VerificarReducaoZEmitidaHoje() && !_emissorService.VerificarReducaoZPendente();
				AbrirGaveta();
			}
			catch (Exception ex)
			{
				ex.ShowLastException();
				Seletor.Voltar();
			}
		}

		private void AbrirGaveta()
		{
			if (_sessaoService.VerificarPermissao<DigisatServer.Infrastructure.Crosscutting.Module.PontoDeVenda, PermitirAbrirGaveta>() != null)
			{
				_emissorService.AbrirGaveta();
			}
		}

		public override void UnLoad()
		{
			_saldoInicial.Limpar();
			_observacao.Limpar();
		}

		public override bool PodeVoltar()
		{
			return true;
		}

		public override void Dispose()
		{
			_saldoInicial = null;
			_observacao = null;
		}

		protected override bool CanF2Method()
		{
			if (_emissorService.Is<IEcfService>())
			{
				if (base.CanF2Method() && _saldoInicial.Valor > 0m)
				{
					return _emissorPronto;
				}
				return false;
			}
			if (base.CanF2Method())
			{
				return _emissorPronto;
			}
			return false;
		}

		protected override void F2Method()
		{
			try
			{
				LoaderProcessoService.MostrarLoader("Abrindo turno...");
				new ValorSangriaService(_valorSangriaRepositoryWrite, _valorSangriaRepositoryRead).AlterarValor(_saldoInicial.Valor);
				TurnoDto turnoDto = new TurnoDto
				{
					SaldoInicial = _saldoInicial.Valor,
					Observacao = _observacao.Valor
				};
				if (_emissorService.Is<IEcfService>() && _emissorService.VerificarJornadaFiscalFechada())
				{
					turnoDto.SaldoInicial = 0m;
					AbrirTurno(turnoDto);
					Seletor.Get<PainelMenuAdministrativoCupomFiscal>().AbrirJornadaFiscalTurno(_saldoInicial.Valor);
					return;
				}
				_emissorService.EmitirSuprimento(_saldoInicial.Valor, _observacao.Valor, "SUPRIMENTO - ABERTURA");
				AbrirTurno(turnoDto);
				if (!DadosSistema.TurnoAberto)
				{
					_seletor.Get<PainelDocumentoFiscal>().Estado = DocumentoFiscalFechado.Criar();
				}
			}
			catch (Exception ex)
			{
				ex.ShowLastException();
			}
			finally
			{
				LoaderProcessoService.EsconderLoader();
				Seletor.VoltarTudo();
			}
		}

		private void AbrirTurno(TurnoDto turno)
		{
			_service.Canal((ITurnoModuleService service) =>
			{
				service.AdicionarAsync(turno);
			});
		}
	}
	public class PainelAbrirJornada : PainelInteracao<PainelAbrirJornada>
	{
		private readonly IEcfService _ecfService;

		private readonly IWService _service;

		private readonly ItemInteracaoDecimalFocusable _item;

		private Action _acao;

		private bool _emissorPronto;

		public override string Titulo => "Jornada fiscal";

		public PainelAbrirJornada()
		{
		}

		public PainelAbrirJornada(IEcfService ecfService, IWService service, Seletor<IPainel> seletor)
			: base(seletor)
		{
			_ecfService = ecfService;
			_service = service;
			_item = ItemInteracaoBase<ItemInteracaoDecimalFocusable, decimal>.Criar().ComDescricao("Valor").ComValor(0m)
				.Build();
			Campos.Add(_item);
			F2Command = new AsyncCommand(F2MethodAsync, CanF2Method, allowMultipleExecution: false);
		}

		private async Task F2MethodAsync()
		{
			await ExecutarAberturaJornadaFiscal(_item.Valor);
		}

		public Task ExecutarAberturaJornadaFiscal(decimal valor)
		{
			LoaderProcessoService.MostrarLoader("Abrindo jornada fiscal");
			return Task.Factory.StartNew(() =>
			{
				_ecfService.AbrirJornadaFiscal(valor);
				TurnoLancamentoDto turnoLancamento = new TurnoLancamentoDto
				{
					DataHora = DateTime.Now,
					OrigemLancamento = OrigensLancamentosTurno.ObterOrigemLancamentoTurnoPorCodigo(5).ProjectedAsDto(),
					Especie = new EspecieRecebimentoDto
					{
						Codigo = new Dinheiro().Codigo
					},
					Valor = valor,
					Ativo = true
				};
				_service.Canal((ITurnoModuleService service) =>
				{
					service.AdicionarLancamento(turnoLancamento);
				});
				Seletor.Voltar();
			}).ContinueWith((Task task) =>
			{
				LoaderProcessoService.EsconderLoader();
				if (task.IsFaulted)
				{
					task.Exception.ShowLastException();
				}
				else
				{
					Seletor.Voltar();
					_acao?.Invoke();
				}
			}, CancellationToken.None, TaskContinuationOptions.None, TaskScheduler.FromCurrentSynchronizationContext());
		}

		public void SetarAcaoAoConcluir(Action acao)
		{
			_acao = acao;
		}

		protected override void F2Method()
		{
		}

		protected override bool CanF2Method()
		{
			if (base.CanF2Method() && _item.Valor > 0m)
			{
				return _emissorPronto;
			}
			return false;
		}

		public override void Load()
		{
			_emissorPronto = _ecfService.Carregado && _ecfService.VerificarJornadaFiscalFechada() && !_ecfService.VerificarReducaoZEmitidaHoje() && !_ecfService.VerificarReducaoZPendente();
		}

		public override void UnLoad()
		{
			_item.Limpar();
		}

		public override bool PodeVoltar()
		{
			return true;
		}

		public override void Dispose()
		{
		}
	}
