	public class PainelAfericaoManual : PainelBicosValor
	{
		private readonly Seletor<IPainel> _seletorEsquerdo;

		private List<NotificouSituacaoComunicacaoBicoResponse> _semComunicao;

		public override string Titulo => "Registro de aferição manual";

		public PainelAfericaoManual()
		{
		}

		public PainelAfericaoManual(IWService service, IEventPublisher eventPublisher, Seletor<IPainel> seletorEsquerdo, Seletor<IPainel> seletorDireito)
			: base("Volume", service, eventPublisher, seletorDireito)
		{
			_seletorEsquerdo = seletorEsquerdo;
		}

		protected override void F2Method()
		{
			try
			{
				ItemInteracaoTexto bico = _listaBicos.ItemSelecionado as ItemInteracaoTexto;
				BicoDto bicoDto = _bicos.FirstOrDefault((BicoDto a) => a.Id == bico.Valor);
				decimal valor = _valor.Valor;
				DateTime dataHoraPerdaComunicacao = _semComunicao.FirstOrDefault((NotificouSituacaoComunicacaoBicoResponse a) => a.BicoNoSoftware == bicoDto.Numero).DataHora;
				AbastecimentoDto abastecimento = _service.Canal((IPostoCombustivelModuleService service) => service.AdicionarAfericaoManual(bico.Valor, valor, dataHoraPerdaComunicacao));
				_seletorEsquerdo.Get<PainelEsquerdoPosto>().ImprimirRelatorioAfericoes(abastecimento.Morfar());
			}
			catch (Exception ex)
			{
				DialogoFactory.MostrarDialogoConfirma(ex.Message);
