	public class PainelAliquota : PainelInteracao<PainelAliquota>
	{
		private readonly IEcfService _ecfService;

		private readonly ItemInteracaoComboBox _tipoAliquota;

		private readonly ItemInteracaoDecimalFocusable _percentualAliquota;

		public override string Titulo => "Visualizar/Cadastrar alíquotas";

		public override string DescricaoDoBotao => "Incluir";

		public PainelAliquota()
		{
		}

		public PainelAliquota(IEcfService ecfService, Seletor<IPainel> seletor)
			: base(seletor)
		{
			_ecfService = ecfService;
			ItemInteracaoTexto itemInteracaoTexto = ItemInteracaoBase<ItemInteracaoTexto, string>.Criar().ComDescricao("ISS").ComValor("iss")
				.Build();
			ItemInteracaoTexto itemInteracaoTexto2 = ItemInteracaoBase<ItemInteracaoTexto, string>.Criar().ComDescricao("ICMS").ComValor("icms")
				.Build();
			Lista<IItemInteracao> lista = new Lista<IItemInteracao>();
			lista.Adicionar(itemInteracaoTexto2, itemInteracaoTexto);
			_tipoAliquota = ItemInteracaoBase<ItemInteracaoComboBox, Lista<IItemInteracao>>.Criar().ComDescricao("Tipo").ComValor(lista)
				.Build();
			_percentualAliquota = ItemInteracaoBase<ItemInteracaoDecimalFocusable, decimal>.Criar().ComDescricao("Valor").ComValor(0m)
				.Build();
		}

		protected override async void F2Method()
		{
			LoaderProcessoService.MostrarLoader("Cadastrando alíquota...");
			await Task.Factory.StartNew(() =>
			{
				_ecfService.CadastrarAliquota(_tipoAliquota.Valor.ItemSelecionado.To<ItemInteracaoTexto>().Valor, _percentualAliquota.Valor);
			}).ContinueWith((Task task) =>
			{
				LoaderProcessoService.EsconderLoader();
				if (task.IsFaulted)
				{
					task.Exception.ShowLastException();
				}
				Seletor.Voltar();
			}, CancellationToken.None, TaskContinuationOptions.None, TaskScheduler.FromCurrentSynchronizationContext());
		}

		protected override bool CanF2Method()
		{
			if (base.CanF2Method())
			{
				return _percentualAliquota.Valor > 0m;
			}
			return false;
		}

		public override void Load()
		{
			Campos.Clear();
			_ecfService.AguardarEcfCarregado();
			Lista<Aliquota> lista = new Lista<Aliquota>();
			lista.Adicionar(_ecfService.Aliquotas);
			Campos.Insert(0, ItemInteracaoBase<ItemInteracaoListaAliquota, Lista<Aliquota>>.Criar().ComDescricao("Alíquotas cadastradas no ECF").ComValor(lista)
				.Build());
			Campos.Insert(1, _tipoAliquota);
			Campos.Insert(2, _percentualAliquota);
		}

		public override void UnLoad()
		{
			_tipoAliquota.Valor.PosicionarNoPrimeiro();
			_percentualAliquota.Valor = 0m;
			Campos.Clear();
		}

		public override bool PodeVoltar()
		{
			return true;
		}

		public override void Dispose()
		{
		}
	}
