	public class PainelAtalho : BindableBase, IPainelEsquerdo, IPainel
	{
		private readonly Seletor<IPainel> _seletorEsquerdo;

		private readonly Seletor<IPainel> _seletorDireito;

		private readonly System.Timers.Timer _timer;

		public IReadOnlyCollection<string> Atalhos
		{
			get
			{
				List<string> list = new List<string> { "[ Ctrl + F4 ] Fechar ponto de venda", "[ Ctrl + M ] Minimizar ponto de venda" };
				try
				{
					if (_seletorEsquerdo.Historico.LastOrDefault((IPainel x) => !(x is PainelAtalho)) is IPainelEsquerdo painelEsquerdo)
					{
						list.AddRange(painelEsquerdo.Atalhos);
					}
					if (_seletorDireito.Painel is IAtalhos)
					{
						list.AddRange(_seletorDireito.ToPainel<IAtalhos>().Atalhos);
					}
				}
				catch (Exception ex)
				{
					ex.ShowLastException();
				}
				return list;
			}
		}

		public IEnumerable<ItemMenuAtalho> MenuRibbon { get; } = new List<ItemMenuAtalho>();

		public PainelAtalho()
		{
		}

		public PainelAtalho(Seletor<IPainel> seletorEsquerdo, Seletor<IPainel> seletorDireito)
		{
			_seletorEsquerdo = seletorEsquerdo;
			_seletorDireito = seletorDireito;
			_timer = new System.Timers.Timer
			{
				Interval = 10000.0
			};
			_timer.Elapsed += (object sender, ElapsedEventArgs args) =>
			{
				UnLoad();
				_seletorEsquerdo.Voltar();
			};
