	public abstract class PainelBase<TClass> : UpdateViewBindableBase, IPainelDireito, IPainelSeletorDireito, IPainel, IDisposable where TClass : class, new()
	{
		public Seletor<IPainel> Seletor { get; protected set; }

		protected IPainelTitulo PainelTitulo => Seletor.Get<IPainelTitulo>();

		protected IPainelMensagem PainelMensagem => Seletor.Get<IPainelMensagem>();

		public ICommand FecharCommand { get; protected set; }

		public IObservable<string> WhenPropertyChanged => from x in Observable.FromEventPattern<PropertyChangedEventHandler, PropertyChangedEventArgs>((PropertyChangedEventHandler h) =>
			{
				PropertyChanged += h;
			}, (PropertyChangedEventHandler h) =>
			{
				PropertyChanged -= h;
			})
			select x.EventArgs.PropertyName;

		protected PainelBase()
		{
		}

		protected PainelBase(Seletor<IPainel> seletor)
		{
			Seletor = seletor;
			FecharCommand = new DelegateCommand(() =>
			{
				Seletor.Fechar();
			}, () => Seletor.PodeVoltar());
		}

		public virtual void FecharMethod()
		{
			Limpar();
		}

		protected virtual void Limpar()
		{
		}

		public static TClass Criar()
		{
			return new TClass();
		}

		public TClass ComSeletor(Seletor<IPainel> seletor)
		{
			Seletor = seletor;
			return this as TClass;
		}

		public virtual TClass Build()
		{
			return (TClass)Activator.CreateInstance(typeof(TClass), Seletor);
		}

		public abstract void Load();

		public abstract void UnLoad();

		public abstract bool PodeVoltar();

		public abstract void Dispose();
	}
	public class PainelBicosValor : PainelInteracao<PainelBicosValor>
	{
		protected readonly string _descricaoValorDecimal;

		protected readonly IWService _service;

		protected readonly IEventPublisher _eventPublisher;

		protected Lista<IItemInteracao> _listaBicos;

		protected ItemInteracaoDecimalTresCasas _valor;

		protected IEnumerable<BicoDto> _bicos;

		public override string Titulo => string.Empty;

		public PainelBicosValor()
		{
		}

		public PainelBicosValor(string descricaoValorDecimal, IWService service, IEventPublisher eventPublisher, Seletor<IPainel> seletor)
			: base(seletor)
		{
			_descricaoValorDecimal = descricaoValorDecimal;
			_service = service;
			_eventPublisher = eventPublisher;
		}

		public override void Load()
		{
			_listaBicos?.Limpar();
			_valor?.Limpar();
			Campos.Clear();
			try
			{
				ObterBicos();
				_listaBicos = new Lista<IItemInteracao>();
				foreach (BicoDto item2 in _bicos.OrderBy((BicoDto x) => x.Numero))
				{
					ItemInteracaoTexto item = ItemInteracaoBase<ItemInteracaoTexto, string>.Criar().ComDescricao(item2.ToText).ComValor(item2.Id)
						.Build();
					_listaBicos.Adicionar(item);
				}
				Campos.Add(ItemInteracaoBase<ItemInteracaoComboBoxFocusable, Lista<IItemInteracao>>.Criar().ComDescricao("Bico").ComValor(_listaBicos)
					.Build());
				_valor = ItemInteracaoBase<ItemInteracaoDecimalTresCasas, decimal>.Criar().ComDescricao(_descricaoValorDecimal).ComValor(0m)
					.Build();
				Campos.Add(_valor);
			}
			catch (Exception ex)
			{
				ex.ShowLastException();
				Seletor.Voltar();
			}
		}

		protected virtual void ObterBicos()
		{
			PaginaEntityDto result = _service.Canal((IBicoModuleService x) => x.PesquisarAtivosAsync(string.Empty, 1, 100)).Result;
			_bicos = result.Lista.Cast<BicoDto>();
		}

		public override void UnLoad()
		{
		}

		public override bool PodeVoltar()
		{
			return true;
		}

		protected override bool CanF2Method()
		{
			if (_listaBicos.IsNotNull() && _valor.IsNotNull() && _valor.Valor > 0m)
			{
				return _listaBicos.PossuiItemSelecionado;
			}
			return false;
		}

		public override void Dispose()
		{
		}

		protected override void F2Method()
		{
		}
	}
	public class PainelBuscaCarteiraDigital : PainelListaBase<PainelBuscaCarteiraDigital, CarteiraDigitalLocal>, IAtalhos, IPainelBusca
	{
		private readonly IPessoaRepositoryRead _pessoaRepositoryRead;

		private decimal _valor;

		private bool _isRecebimento;

		private bool _isMesaContaCreditoCliente;

		public string Titulo => "Carteira Digital";

		public IReadOnlyCollection<string> Atalhos => new List<string> { "[ Enter ] Confirmar" };

		public PainelBuscaCarteiraDigital()
		{
		}

		public PainelBuscaCarteiraDigital(IPessoaRepositoryRead pessoaRepositoryRead, Seletor<IPainel> seletor)
			: base(seletor)
		{
			_pessoaRepositoryRead = pessoaRepositoryRead;
		}

		public override void Load()
		{
			Lista.Limpar();
			IEnumerable<DigisatServer.Domain.Main.Aggregates.CadastrosAgg.Pessoas.Pessoa> source = _pessoaRepositoryRead.Find(EntitySpecification<DigisatServer.Domain.Main.Aggregates.CadastrosAgg.Pessoas.Pessoa>.Ativo().AdministradoraCartao());
			if (!source.Any())
			{
				DialogoFactory.MostrarDialogoConfirma("Nenhuma pessoa do tipo 'Administradora de cartão' cadastrada.");
				Seletor.Voltar();
				return;
			}
			foreach (Juridica item in source.OfType<Juridica>())
			{
				foreach (Rede redesTaxasCarteirasDigitai in item.AdministradoraCartao.RedesTaxasCarteirasDigitais)
				{
					if (redesTaxasCarteirasDigitai.IsCredito)
					{
						Lista.Adicionar(CarteiraDigitalLocal.Criar().ComPessoa(item).ComDescricao(redesTaxasCarteirasDigitai.Descricao)
							.ComOperacaoRedePos(OperacaoRedePos.Credito)
							.ComTaxa(redesTaxasCarteirasDigitai.Taxas.Where((Taxa taxa) => !taxa.Debito))
							.Build());
					}
					if (redesTaxasCarteirasDigitai.IsDebito)
					{
						Lista.Adicionar(CarteiraDigitalLocal.Criar().ComPessoa(item).ComDescricao(redesTaxasCarteirasDigitai.Descricao)
							.ComOperacaoRedePos(OperacaoRedePos.Debito)
							.ComTaxa(redesTaxasCarteirasDigitai.Taxas.Where((Taxa taxa) => taxa.Debito))
							.Build());
					}
				}
			}
			Lista.PosicionarNoPrimeiro();
			if (Lista.Numero <= 0)
			{
				DialogoFactory.MostrarDialogoConfirma("Nenhuma Rede encontrada.");
				Seletor.Voltar();
			}
		}

		public override void EnterMethod()
		{
			try
			{
				Seletor.Fechar();
				PainelBuscaTaxasCarteiraDigital painelBuscaTaxasCarteiraDigital = Seletor.Get<PainelBuscaTaxasCarteiraDigital>();
				painelBuscaTaxasCarteiraDigital.ComRedePosLocal(Lista.ItemSelecionado);
				painelBuscaTaxasCarteiraDigital.ComCallback(Callback);
				Seletor.Selecionar<PainelBuscaTaxasCarteiraDigital>();
			}
			catch (Exception ex)
			{
				ex.ShowLastException();
			}
		}

		private void Callback()
		{
			CarteiraDigitalLocal itemSelecionado = Lista.ItemSelecionado;
			InformacaoTransacaoCarteiraDigital informacaoTransacaoCarteiraDigital = InformacaoTransacaoCarteiraDigital.Criar().ComPessoa(itemSelecionado.Pessoa.ObterPessoaHistorico()).ComAdministradoraCartao(itemSelecionado.Pessoa)
				.ComRede(itemSelecionado.Descricao)
				.ComTipo(itemSelecionado.Descricao)
				.ComValor(_valor)
				.ComCodigoAutorizacaoTransacao(itemSelecionado.CodigoAutorizacao.ToStringEmptyWhenNull())
				.ComEndToEndId(itemSelecionado.CodigoAutorizacaoTransacao)
				.ComTaxa(itemSelecionado.Taxa)
				.Build();
			if (_isMesaContaCreditoCliente)
			{
				_isMesaContaCreditoCliente = false;
				PainelTotalizacaoEmissorBase painelTotalizacaoEmissorBase = Seletor.Get<PainelTotalizacaoEmissorBase>();
				if (painelTotalizacaoEmissorBase.EmissorService.IsExactlyObject<NfceService>() || painelTotalizacaoEmissorBase.EmissorService.IsExactlyObject<PafNfceService>() || painelTotalizacaoEmissorBase.EmissorService.IsExactlyObject<MFePontoVendaService>())
				{
					Seletor.Selecionar<PainelRegistroAutorizacaoPagamentoPix, PainelAdicionarMesaContaCreditoCliente>();
					if (Lista.ItemSelecionado.CodigoAutorizacao.IsNotNull())
					{
						informacaoTransacaoCarteiraDigital.ComCodigoAutorizacaoTransacao(itemSelecionado.CodigoAutorizacaoTransacao);
						Seletor.Get<PainelAdicionarMesaContaCreditoCliente>().FinalizarPagamentoCarteiraDigital(informacaoTransacaoCarteiraDigital);
					}
				}
				else
				{
					Seletor.Get<PainelAdicionarMesaContaCreditoCliente>().FinalizarPagamentoCarteiraDigital(informacaoTransacaoCarteiraDigital);
				}
			}
			else if (!_isRecebimento)
			{
				PainelTotalizacaoEmissorBase painelTotalizacaoEmissorBase2 = Seletor.Get<PainelTotalizacaoEmissorBase>();
				if (painelTotalizacaoEmissorBase2.EmissorService.IsExactlyObject<NfceService>() || painelTotalizacaoEmissorBase2.EmissorService.IsExactlyObject<PafNfceService>() || painelTotalizacaoEmissorBase2.EmissorService.IsExactlyObject<MFePontoVendaService>())
				{
					Seletor.Selecionar<PainelRegistroAutorizacaoPagamentoPix, PainelTotalizacaoBase>();
					if (Lista.ItemSelecionado.CodigoAutorizacao.IsNotNull())
					{
						informacaoTransacaoCarteiraDigital.ComCodigoAutorizacaoTransacao(itemSelecionado.CodigoAutorizacaoTransacao);
						painelTotalizacaoEmissorBase2.AdicionarCartaoResposta(informacaoTransacaoCarteiraDigital, 24);
					}
				}
				else
				{
					painelTotalizacaoEmissorBase2.AdicionarCartaoResposta(informacaoTransacaoCarteiraDigital, 24);
				}
			}
			else
			{
				PainelRecebimento painelRecebimento = Seletor.Get<PainelRecebimento>();
				painelRecebimento.SetarFinalizadoEmCarteiraDigital(finalizadoEmCarteiraDigital: true);
				painelRecebimento.FinalizarPagamentoCarteiraDigital(informacaoTransacaoCarteiraDigital);
			}
		}

		public override bool PodeVoltar()
		{
			return true;
		}

		public void SetarValor(decimal valor)
		{
			_valor = valor;
		}

		public void SetarIsRecebimento(bool isRecebimento = false)
		{
			_isRecebimento = isRecebimento;
		}

		public void SetarMesaContaCreditoCliente(bool isMesaContaCreditoCliente = false)
		{
			_isMesaContaCreditoCliente = isMesaContaCreditoCliente;
		}
	}
	public class PainelBuscaCarteiraDigitalShipay : PainelListaBase<PainelBuscaCarteiraDigitalShipay, CarteiraDigitalShipayLocal>, IAtalhos, IPainelBusca, IMenuRibbon
	{
		private readonly Otus.Modulo.PontoDeVendas.Interfaces.IShipayService _shipayService;

		private readonly IPessoaRepositoryRead _pessoaRepositoryRead;

		private readonly IImpressaoRelatorioService _impressoraNaoFiscalService;

		private readonly IDisplayService _displayService;

		private readonly Seletor<IPainel> _seletorEsquerdo;

		private decimal _valorPagamento;

		private OrderResponse _emPagamento;

		private ConsumidorLocal _consumidor;

		private bool _isMesaContaCreditoCliente;

		private const int MilisegundosExibicaoAprovado = 1500;

		public string Titulo => "Carteira Digital";

		public IReadOnlyCollection<string> Atalhos => new List<string> { "[ Enter ] Confirmar", "[ ESC ] Sair/Cancelar", "[ Ctrl+P ] Imprimir" };

		public IEnumerable<ItemMenuAtalho> MenuRibbon => new List<ItemMenuAtalho>
		{
			new ItemMenuAtalho("Enter", "Escolher carteira", new DelegateCommand(EnterMethod, PodeEnterCommand)),
			new ItemMenuAtalho("Esc", "Sair/Cancelar", new DelegateCommand(FecharMethod, PodeVoltar)),
			new ItemMenuAtalho(CtrlPCommand.KeyGesture.Descricao, "Imprimir", CtrlPCommand)
		};

		public CustomDelegateCommand CtrlPCommand { get; set; }

		public PainelBuscaCarteiraDigitalShipay()
		{
		}

		public PainelBuscaCarteiraDigitalShipay(Seletor<IPainel> seletorDireito, Seletor<IPainel> seletorEsquerdo, Otus.Modulo.PontoDeVendas.Interfaces.IShipayService shipayService, IPessoaRepositoryRead pessoaRepositoryRead, IImpressaoRelatorioService impressoraNaoFiscalService, IDisplayService displayService)
			: base(seletorDireito)
		{
			_impressoraNaoFiscalService = impressoraNaoFiscalService;
			_displayService = displayService;
			try
			{
				_seletorEsquerdo = seletorEsquerdo;
				_shipayService = shipayService;
				_pessoaRepositoryRead = pessoaRepositoryRead;
				FecharCommand = new DelegateCommand(FecharMethod, PodeVoltar);
				CtrlPCommand = new CustomDelegateCommand(new KeyGestureControl(Key.P), Imprimir, PodeImprimir);
			}
			catch (Exception ex)
			{
				ex.ShowLastException();
			}
		}

		private bool PodeImprimir()
		{
			return _emPagamento != null;
		}

		private void Imprimir()
		{
			try
			{
				RelatorioQrCodePagamentoDigital subReport = RelatorioQrCodePagamentoDigital.Criar().ComValor(_valorPagamento).ComFormaPagamento(Lista.ItemSelecionado.Descricao)
					.ComTextoQrCode(_emPagamento.qr_code_text);
				_impressoraNaoFiscalService.ImprimirRelatorio40ColunasAsync(subReport, "Pagamento Digital", DateTime.Today.ToString("dd/MM/yyyy"));
			}
			catch (Exception ex)
			{
				ex.ShowLastException();
			}
		}

		public override void Load()
		{
			AssinarEventos();
			CarregarCarteiras();
		}

		private void CarregarCarteiras()
		{
			Lista.Limpar();
			LoaderProcessoService.MostrarLoader("Carregando carteiras...");
			_shipayService.ObterCarteiras().ContinueWith((Task<IEnumerable<Wallet>> task) =>
			{
				ThreadPrincipal.Executar(() =>
				{
					LoaderProcessoService.EsconderLoader();
					if (task.IsFaulted)
					{
						task.Exception.ShowLastException();
					}
					else
					{
						Lista.Adicionar((from wallet in task.Result
							where wallet.active
							select CarteiraDigitalShipayLocal.Criar().ComDescricao(wallet.name)).ToArray());
						Lista.PosicionarNoPrimeiro();
						RecuperarFoco();
					}
				});
			});
		}

		public override void EnterMethod()
		{
			LoaderProcessoService.MostrarLoader();
			if (_consumidor.IsNotNull())
			{
				string descricao = Lista.ItemSelecionado.Descricao;
				_shipayService.Pagar(_consumidor, _valorPagamento, descricao).ContinueWith((Task task) =>
				{
					ThreadPrincipal.Executar(() =>
					{
						if (task.IsFaulted)
						{
							LoaderProcessoService.EsconderLoader();
							task.Exception.ShowLastException();
							_emPagamento = null;
						}
					});
				});
			}
			else
			{
				if (Lista.IsNull() || !Lista.PossuiItemSelecionado)
				{
					return;
				}
				PreDocumentoFiscal preDocumentoFiscal = Seletor.Get<PainelDocumentoFiscal>().PreDocumentoFiscal;
				string descricao2 = Lista.ItemSelecionado.Descricao;
				_shipayService.Pagar(preDocumentoFiscal, _valorPagamento, descricao2).ContinueWith((Task task) =>
				{
					ThreadPrincipal.Executar(() =>
					{
						if (task.IsFaulted)
						{
							LoaderProcessoService.EsconderLoader();
							task.Exception.ShowLastException();
							_emPagamento = null;
						}
					});
				});
			}
		}

		public override void FecharMethod()
		{
			if (_emPagamento.IsNotNull())
			{
				CancelarPagamento();
			}
			else
			{
				FecharPainel();
			}
		}

		private void CancelarPagamento()
		{
			FecharPainelQrCode();
			DialogoFactory.MostrarDialogoConfirma($"O pagamento pendente com ID {_emPagamento.order_id} será cancelado.");
			LoaderProcessoService.MostrarLoader("Cancelando pagamento...");
			_shipayService.CancelarPagamento(_emPagamento.order_id).ContinueWith((Task task) =>
			{
				ThreadPrincipal.Executar(() =>
				{
					if (task.IsFaulted)
					{
						LoaderProcessoService.EsconderLoader();
						task.Exception.ShowLastException();
						_emPagamento = null;
					}
				});
			});
		}

		private void ShipayServiceOnPagamentoExpiradoEvent(object o, OrderStatusResponse orderStatusResponse)
		{
			string text = "O tempo limite para confirmação do pagamento foi excedido";
			_seletorEsquerdo.Get<PainelMensagem>().AlterarMensagemTimer(text);
			DialogoFactory.MostrarDialogoConfirma($"{text}. ID do pagamento: {orderStatusResponse.order_id}.");
			FecharPainel();
		}

		private void ShipayServiceOnPagamentoCanceladoEvent(object o, OrderStatusResponse orderStatusResponse)
		{
			string text = "O pagamento foi cancelado";
			_seletorEsquerdo.Get<PainelMensagem>().AlterarMensagemTimer(text);
			DialogoFactory.MostrarDialogoConfirma($"{text}. ID do pagamento: {orderStatusResponse.order_id}.");
			FecharPainel();
		}

		private void ShipayServiceOnPagamentoAprovadoEvent(object o, OrderStatusResponse orderStatusResponse)
		{
			AlertaSonoro.TocarSomNotificacao(SomNotificacao.Alerta30);
			_seletorEsquerdo.Get<PainelEsquerdoQrCode>().SetarPagamentoAprovado(pagamentoAprovado: true);
			_seletorEsquerdo.Get<PainelMensagem>().AlterarMensagemTimer("Pagamento aprovado", 3.0);
			if (_consumidor.IsNotNull())
			{
				DormirAsync(1500, (object x) =>
				{
					FecharPainel();
					InformacaoTransacaoCarteiraDigital informacaoTransacaoCarteiraDigital = InformacaoTransacaoCarteiraDigital.Criar().ComValor(_valorPagamento).ComNsu(orderStatusResponse.order_id)
						.ComRede(orderStatusResponse.wallet)
						.ComTipo(orderStatusResponse.wallet)
						.ComAdministradoraCartao(RetornarAdministradoraCartao(orderStatusResponse.wallet))
						.ComEndToEndId(orderStatusResponse.wallet_payment_id)
						.ComCodigoAutorizacaoTransacao(orderStatusResponse.wallet_payment_id.ToStringEmptyWhenNull())
						.Build();
					if (_isMesaContaCreditoCliente)
					{
						_isMesaContaCreditoCliente = false;
						Seletor.Get<PainelAdicionarMesaContaCreditoCliente>().FinalizarPagamentoCarteiraDigitalShipay(informacaoTransacaoCarteiraDigital);
					}
					else
					{
						Seletor.Get<PainelRecebimento>().SetarFinalizadoEmCarteiraDigital(finalizadoEmCarteiraDigital: true);
						Seletor.Get<PainelRecebimento>().FinalizarPagamentoCarteiraDigital(informacaoTransacaoCarteiraDigital);
					}
					_consumidor = null;
				});
			}
			else
			{
				DormirAsync(1500, (object x) =>
				{
					FecharPainel();
					Seletor.Get<PainelTotalizacaoEmissorBase>().AdicionarCartaoResposta(InformacaoTransacaoCarteiraDigital.Criar().ComValor(_valorPagamento).ComNsu(orderStatusResponse.order_id)
						.ComRede(orderStatusResponse.wallet)
						.ComTipo(orderStatusResponse.wallet)
						.ComAdministradoraCartao(RetornarAdministradoraCartao(orderStatusResponse.wallet))
						.ComEndToEndId(orderStatusResponse.wallet_payment_id)
						.ComCodigoAutorizacaoTransacao(orderStatusResponse.wallet_payment_id.ToStringEmptyWhenNull())
						.Build(), 25);
				});
			}
		}

		private DigisatServer.Domain.Main.Aggregates.CadastrosAgg.Pessoas.Pessoa RetornarAdministradoraCartao(string rede)
		{
			IEnumerable<DigisatServer.Domain.Main.Aggregates.CadastrosAgg.Pessoas.Pessoa> source = _pessoaRepositoryRead.Find(EntitySpecification<DigisatServer.Domain.Main.Aggregates.CadastrosAgg.Pessoas.Pessoa>.Ativo().AdministradoraCartao());
			DigisatServer.Domain.Main.Aggregates.CadastrosAgg.Pessoas.Pessoa pessoa = null;
			if (!DadosSistema.ConfiguracaoDto.Geral.AdministradoraCartaoShipay.Referencia.IsNullOrEmpty())
			{
				DigisatServer.Domain.Main.Aggregates.CadastrosAgg.Pessoas.Pessoa pessoa2 = source.FirstOrDefault((DigisatServer.Domain.Main.Aggregates.CadastrosAgg.Pessoas.Pessoa x) => x.Id.Equals(DadosSistema.ConfiguracaoDto.Geral.AdministradoraCartaoShipay.Referencia.TryParseReferencia()));
				if (pessoa2.IsNotNull())
				{
					return pessoa2;
				}
			}
			if (source.Count() > 1)
			{
				pessoa = source.FirstOrDefault((DigisatServer.Domain.Main.Aggregates.CadastrosAgg.Pessoas.Pessoa x) => ((Juridica)x).AdministradoraCartao.Redes.Contains(rede.ToUpper()));
			}
			return pessoa ?? source.LastOrDefault();
		}

		private void ShipayServiceOnPagamentoCriadoEvent(object o, OrderResponse orderResponse)
		{
			_emPagamento = orderResponse;
			_seletorEsquerdo.Get<PainelEsquerdoQrCode>().SetarQrCode(orderResponse.qr_code).SetarQrCodeCopiaCola(orderResponse.qr_code_text);
			_seletorEsquerdo.Selecionar<PainelEsquerdoQrCode>();
			_seletorEsquerdo.Get<PainelMensagem>().AlterarMensagem("Escaneie e pague pelo seu celular");
			if (orderResponse.qr_code_text.ToLower().Contains("br.gov.bcb"))
			{
				_displayService.ApresentaQrCode(orderResponse.qr_code_text, 250, 60, 35);
			}
			RecuperarFoco();
		}

		private void FecharPainel()
		{
			_displayService.InicializaDisplay();
			_displayService.ApresentarImagemPadrao();
			_emPagamento = null;
			DesassinarEventos();
			FecharPainelQrCode();
			FecharPainelCarteiraDigital();
			LoaderProcessoService.EsconderLoader();
		}

		private void FecharPainelCarteiraDigital()
		{
