		{
		}

		public PainelBuscaConsumidorGenerico(IEmissorService emissorService, IWService service, IPessoaRepositoryRead pessoaRepositoryRead, Seletor<IPainel> seletor)
			: base(seletor)
		{
			emissorService.To<NfceService>()?.WhenPdvOfflineEventEvent.Subscribe((bool x) =>
			{
				PdvEstadoOffline = x;
			});
