	{
		public IEcfService EcfService { get; protected set; }

		public override string Titulo => "Abrir Cupom fiscal";

		public CustomDelegateCommand CtrlICommand { get; set; }

		public KeyGestureCustom Key => new KeyGestureCustom(System.Windows.Input.Key.F9);

		public string ToolTip => Titulo;

		public IEnumerable<ItemMenuAtalho> MenuRibbon => new List<ItemMenuAtalho>
		{
			new ItemMenuAtalho(CtrlICommand.KeyGesture.Descricao, "Imprimir ticket de troca", CtrlICommand, "Imprimir ticket de troca com dados do cupom fiscal original")
		};

		public IReadOnlyCollection<string> Atalhos => new List<string>();

		public PainelBuscaCupomFiscal()
		{
		}

		public PainelBuscaCupomFiscal(IEcfService ecfService, Seletor<IPainel> seletor)
			: base(seletor)
		{
			EcfService = ecfService;
			CtrlICommand = new CustomDelegateCommand(new KeyGestureControl(System.Windows.Input.Key.I), ImprimirTicketTroca, PodeImprimirTicketTroca);
			Lista.SetarCabecalho(Cabecalho<CabecalhoDocumentoFiscalEletronico>.Criar());
		}

		protected override void ListaOnAlterouItemSelecionadoEvent(object sender, DocumentoFiscalEletronicoLocal item)
		{
			base.ListaOnAlterouItemSelecionadoEvent(sender, item);
			RecuperarFoco();
		}

		private bool PodeImprimirTicketTroca()
		{
			if (Lista.PossuiItemSelecionado)
			{
				return Lista.ItemSelecionado.Movimentacao.Situacao.Codigo == 2;
			}
			return false;
		}

		private void ImprimirTicketTroca()
		{
			try
			{
				MovimentacaoDto movimentacao = Lista.ItemSelecionado.Movimentacao;
				EcfService.ImprimirRelatorioGerencialTicketTroca(GerarImpressoTicketTroca(movimentacao));
			}
			catch (Exception ex)
			{
				ex.ShowLastException();
			}
			finally
			{
				Limpar();
			}
		}

		private IEnumerable<string> GerarImpressoTicketTroca(MovimentacaoDto movimentacao)
		{
			List<string> list = new List<string>();
			list.Add("                                       ");
			list.Add(DadosSistema.EmpresaLogada.Nome);
			list.Add($"CNPJ: {DadosSistema.EmpresaLogada.CpfCnpjFormatado}");
			list.Add($"IE: {DadosSistema.EmpresaLogada.Ie}");
			list.Add($"Telefone: {DadosSistema.EmpresaLogada.Telefone}");
			list.Add($"End.: {DadosSistema.EmpresaLogada.EnderecoToText}");
			list.Add("                                       ");
			list.Add("-----------TICKET DE TROCA ------------");
			list.Add("                                       ");
			list.Add("Para efetuar trocas de mercadorias é necessário apresentar este ticket ou o documento original de venda.");
			list.Add("                                       ");
			list.Add("Dados da venda:                        ");
			list.Add($"{movimentacao.Tipo.RetornarDescricao()}");
			list.Add($"Nº: {movimentacao.Numero}");
			list.Add($"Emissão: {movimentacao.DataHoraEmissao:dd/MM/yyyy}");
			List<IGrouping<string, ItemDto>> list2 = (from x in movimentacao.Itens
				where x.VendedorResponsavel.IsNot<PessoaDtoNull>()
				group x by x.VendedorResponsavel.Nome).ToListEmptyWhenNull();
			if (list2.Count > 0)
			{
				list.Add($"Vendedor: {list2.FirstOrDefault()?.Key}");
			}
			if (!string.IsNullOrEmpty(DadosSistema.ConfiguracaoDto.Saida.MensagemRodapeTicketTroca.Valor))
			{
				list.Add(DadosSistema.ConfiguracaoDto.Saida.MensagemRodapeTicketTroca.Valor);
			}
			list.Add("                                       ");
			return list;
		}

		public override void EnterMethod()
		{
		}

		public override void Load()
		{
			base.Load();
			if (DadosSistema.CarregarQuantidadeRegistrosBuscaMovimentacao)
			{
				Informacao.PesquisarUltimosRegistros(DadosSistema.QuantidadeRegistrosCarregarBuscaMovimentacoes);
			}
		}
	}
