	{
		private readonly ICFeService _emissorService;

		private readonly IImpressoraNaoFiscalService _impressoraNaoFiscalService;

		protected readonly Seletor<IPainel> _seletorEsquerdo;

		public IWService Service { get; protected set; }

		public override string Titulo => "Abrir CFe";

		public CustomDelegateCommand DelCommand { get; set; }

