		public IWService Service { get; protected set; }

		public override string Titulo => "Importar DAV";

		public IReadOnlyCollection<string> Atalhos => new List<string> { "[ Enter ] Selecionar", "[ Ctrl + P ] Imprimir" };

		public IEnumerable<ItemMenuAtalho> MenuRibbon => new List<ItemMenuAtalho>
