			new ItemMenuAtalho(CtrlPCommand.KeyGesture.Descricao, "Imprimir", CtrlPCommand)
		};

		public CustomDelegateCommand CtrlPCommand { get; set; }

		public CustomDelegateCommand CtrlACommand { get; set; }

		public ICommand InsertCommand { get; set; }

		public KeyGestureCustom Key => new KeyGestureCustom(System.Windows.Input.Key.F10);

		public string ToolTip => "Importar Pedido de venda/Ordem de serviço/Orçamento";

		public PainelBuscaDocumentoAuxiliarVenda()
		{
		}

		public PainelBuscaDocumentoAuxiliarVenda(IWService service, IEmissorService emissorService, Seletor<IPainel> seletor)
			: base(seletor)
		{
			_emissorService = emissorService;
			Service = service;
			CtrlPCommand = new CustomDelegateCommand(new KeyGestureControl(System.Windows.Input.Key.P), ImprimirDav);
			InsertCommand = new DelegateCommand(Selecionar, () => PodeSelecionarCheckBox);
			CtrlACommand = new CustomDelegateCommand(new KeyGestureControl(System.Windows.Input.Key.A), SelecionarTodos, () => PodeSelecionarCheckBox);
			Lista.SetarCabecalho(Cabecalho<CabecalhoDocumentoAuxiliarVenda>.Criar());
		}

		private void Selecionar()
		{
			Lista.ItemSelecionado.Selecionado = !Lista.ItemSelecionado.Selecionado;
		}

		private void SelecionarTodos()
		{
			foreach (DocumentoAuxiliarVendaLocal iten in Lista.Itens)
			{
				iten.Selecionado = true;
			}
		}

		protected override void InformacaoOnPesquisouEvent(object sender, IEnumerable<DocumentoAuxiliarVendaLocal> lista)
		{
			Lista.Limpar();
			foreach (DocumentoAuxiliarVendaLocal listum in lista)
			{
				listum.ComCommand(CtrlPCommand);
			}
			Lista.Adicionar(lista);
			Lista.PosicionarNoPrimeiro();
			Pesquisou = true;
		}

		public override void EnterMethod()
		{
			List<MovimentacaoDto> list = new List<MovimentacaoDto>();
			IEnumerable<MovimentacaoDto> result = DadosSistema.GetService().Canal((IMovimentacaoSaidaModuleService service) => service.ObterMovimentacoesPreenchidasPorReferencia(from a in Lista.Itens
				where a.Selecionado
				select a.ResumoMovimentacao.Id)).Result;
			list.AddRange(result);
			if (!Lista.PossuiItemSelecionado)
			{
				return;
			}
			if (!list.Any())
			{
				List<string> idMovimentacao = new List<string> { Lista.ItemSelecionado.ResumoMovimentacao.Id };
				IEnumerable<MovimentacaoDto> result2 = DadosSistema.GetService().Canal((IMovimentacaoSaidaModuleService service) => service.ObterMovimentacoesPreenchidasPorReferencia(idMovimentacao)).Result;
				list.Add(result2.FirstOrDefault());
			}
			Seletor.Voltar();
			foreach (MovimentacaoDto item in list)
			{
				Seletor.Get<PainelDocumentoFiscal>().EmitirDocumentoFiscal(item);
			}
			string text = string.Join(Environment.NewLine, list.Select((MovimentacaoDto x) => x.Observacao));
			if (!string.IsNullOrWhiteSpace(text) && DialogoFactory.MostrarDialogoSimNao("Deseja utilizar a observação do documento importado na NFC-e/NF-e?") == MessageBoxResult.Yes)
			{
				Seletor.Get<PainelObservacao>().Reload(text);
				Seletor.Get<PainelObservacao>().F2Command.Execute(1);
			}
		}

		private async void ImprimirDav()
		{
			LoaderProcessoService.MostrarLoader("Imprimimdo DAV...");
			await Task.Factory.StartNew(() =>
			{
				if (Lista.PossuiItemSelecionado)
				{
					List<string> idsMovimentacoes = new List<string> { Lista.ItemSelecionado.ResumoMovimentacao.Id };
					IEnumerable<MovimentacaoDto> result = DadosSistema.GetService().Canal((IMovimentacaoSaidaModuleService service) => service.ObterMovimentacoesPreenchidasPorReferencia(idsMovimentacoes)).Result;
					ProcessarImpressao(result.FirstOrDefault());
				}
			}).ContinueWith((Task task) =>
			{
				LoaderProcessoService.EsconderLoader();
				if (task.IsFaulted)
				{
					task.Exception.ShowLastException();
				}
			}, CancellationToken.None, TaskContinuationOptions.None, TaskScheduler.FromCurrentSynchronizationContext());
		}

		private void ProcessarImpressao(MovimentacaoDto movimentacao)
		{
			VerificarDavImpressoEcf(movimentacao);
			if (_emissorService.Tipo == TipoMovimentacao.CupomFiscal || _emissorService.Is<PafNfceService>())
			{
				switch (movimentacao.Tipo)
				{
				case TipoMovimentacao.Orcamento:
					_emissorService.ImprimirRelatorioGerencialDavOrcamento(RetornarInformacoesRelatorioGerencialDav(movimentacao));
					break;
				case TipoMovimentacao.Dav:
				case TipoMovimentacao.Delivery:
					_emissorService.ImprimirRelatorioGerencialDav(RetornarInformacoesRelatorioGerencialDav(movimentacao));
					break;
				case TipoMovimentacao.DavOs:
					_emissorService.ImprimirRelatorioGerencialDavOs(RetornarInformacoesRelatorioGerencialDavOs(movimentacao));
					break;
				}
			}
			else
			{
				switch (movimentacao.Tipo)
				{
				case TipoMovimentacao.Orcamento:
					_emissorService.ImprimirRelatorioGerencialDavEOrcamentoEDavOs(RetornarImpressoOrcamento(movimentacao));
					break;
				case TipoMovimentacao.Dav:
				case TipoMovimentacao.Delivery:
					_emissorService.ImprimirRelatorioGerencialDavEOrcamentoEDavOs(RetornarImpressoDav(movimentacao));
					break;
				case TipoMovimentacao.DavOs:
					_emissorService.ImprimirRelatorioGerencialDavEOrcamentoEDavOs(RetornarImpressoDavOs(movimentacao));
					break;
				}
			}
			AtualizarDavImpressoEcf(movimentacao);
		}

		private void VerificarDavImpressoEcf(MovimentacaoDto movimentacao)
		{
			if (_emissorService.Tipo != TipoMovimentacao.CupomFiscal || !movimentacao.ImpressoEcf || !(movimentacao.DataHoraEmissao.Date != DateTime.Today.Date))
			{
				return;
			}
			throw new Exception("É vedada a re-impressão de DAV impresso por ECF.");
		}

		private void AtualizarDavImpressoEcf(EntityBaseDto movimentacao)
		{
			try
			{
				if (_emissorService.Tipo == TipoMovimentacao.CupomFiscal)
				{
					string numeroFabricacao = _emissorService.RetornarNumeroFabricacao();
					string mfAdicional = _emissorService.RetornarMfAdicional();
					string marcaEcf = _emissorService.RetornarMarcaEcf();
					string modeloEcf = _emissorService.RetornarModelo();
					int coo = _emissorService.RetornarContadorOrdemOperacao();
					Service.Canal((IMovimentacaoSaidaModuleService service) =>
					{
						service.AtualizarDavImpressoEcf(numeroFabricacao, mfAdicional, marcaEcf, modeloEcf, coo, movimentacao.Id);
					});
				}
			}
			catch (Exception ex)
			{
				throw new Exception("Erro ao atualizar as informações do DAV impresso.\n" + ex.Message);
			}
		}

		private IRelatorio RetornarImpressoOrcamento(MovimentacaoDto movimentacao)
		{
			if (DadosSistema.TamanhoBobina != TamanhoBobina.CinquentaESeisCinquentaESeteCinquentaEOitoMilimetros)
			{
				return new RelatorioOrcamento79Mm80Mm(movimentacao, DadosSistema.ImprimirItemResumidoEm40Colunas, DadosSistema.MargemEsquerdaImpressoraNaoFiscal, DadosSistema.RollPaper);
			}
			return new RelatorioOrcamento56Mm57Mm58Mm(movimentacao, DadosSistema.MargemEsquerdaImpressoraNaoFiscal, DadosSistema.ImprimirItemResumidoEm40Colunas, DadosSistema.RollPaper);
		}

