		private IEnumerable<string> RetornarInformacoesRelatorioGerencialDav(MovimentacaoDto movimentacao)
		{
			List<string> list = new List<string>
			{
				"NAO E VALIDO COMO RECIBO E COMO GARANTIA DE MERCADORIA - NAO COMPROVA PAGAMENTO",
				$"N. Documento: {movimentacao.Numero:0000000000000}",
				$"Situacao: {movimentacao.Situacao.Descricao}",
				"---------------------------------------",
				movimentacao.Empresa.Nome,
				movimentacao.Empresa.CpfCnpj,
				"---------------------------------------",
				$"Destinatario: {movimentacao.Pessoa.Nome}",
				$"CNPJ/CPF: {movimentacao.Pessoa.CpfCnpj}",
				$"End.: {movimentacao.Pessoa.EnderecoPrincipal.Logradouro}",
				$"N.: {movimentacao.Pessoa.EnderecoPrincipal.Numero}",
				$"Bairro.: {movimentacao.Pessoa.EnderecoPrincipal.Bairro}",
				$"Compl.: {movimentacao.Pessoa.EnderecoPrincipal.Complemento}",
				$"Cidade: {movimentacao.Pessoa.EnderecoPrincipal.Municipio?.Nome ?? string.Empty}",
				$"UF: {movimentacao.Pessoa.EnderecoPrincipal.Municipio?.UF?.Sigla ?? string.Empty}",
				$"CEP: {movimentacao.Pessoa.EnderecoPrincipal.Cep}",
				"---------------------------------------",
				"Item Codigo   Nome",
				"Und Qtd        Vl.Unit.  D/A R$  Vl.Total R$"
			};
			foreach (ItemDto iten in movimentacao.Itens)
			{
				string text = string.Format("{0}{1}", iten.Numero.ToString("000").PadRight(4), iten.ProdutoServico.CodigoInterno.PadRight(10));
				text += ((iten.Cancelado && DadosSistema.IsPaf) ? $"(Cancelado){iten.ProdutoServico.Descricao.PadRight(15)}" : iten.ProdutoServico.Descricao.PadRight(26));
				if (!iten.ObservacaoDigitada.IsNullOrEmpty())
				{
					text += $"OBS: {iten.ObservacaoDigitada}";
				}
				list.Add(text);
				list.Add(string.Format("{0}{1}{2}{3}{4}", iten.UnidadeMedida.Sigla.PadRight(4), iten.Quantidade.ToString("#,#####0.000").PadRight(11), iten.PrecoUnitario.ToString("#,#####0.00").PadRight(10), iten.DescontoDigitado.ToString("#,###0.00").PadRight(8), iten.TotalLiquido.ToString("#,#######0.00").PadRight(12)));
				if (iten.VendedorResponsavel.IsNot<PessoaDtoNull>())
				{
					list.Add($"Vendedor: {iten.VendedorResponsavel.Nome}");
				}
				if (iten.Cancelado && !DadosSistema.IsPaf)
				{
					list.Add($"Cancelado item: {iten.Numero:000}");
				}
			}
			list.Add("---------------------------------------");
			list.Add($"TOTAL: {movimentacao.Total:C2}");
			list.Add("---------------------------------------");
			if (!movimentacao.Observacao.IsNullOrEmpty())
			{
				list.Add($"OBSERVAÇÕES: {movimentacao.Observacao}");
				list.Add("---------------------------------------");
			}
			list.Add("Forma de pagamento");
			list.Add("Parcela  Vencimento            Valor R$");
			foreach (PagamentoRecebimentoDto pagamentosRecebimento in movimentacao.PagamentosRecebimentos)
			{
				list.Add(string.Format("{0}{1}{2}", pagamentosRecebimento.Ordem.ToString().PadRight(9), pagamentosRecebimento.DataVencimento.ToString("dd/MM/yyyy").PadRight(26), pagamentosRecebimento.Valor.ToString("#,#####0.00").PadRight(10)));
			}
			list.Add("---------------------------------------");
			list.Add("   E VEDADA A AUTENTICACAO DESTE DOCUMENTO   ");
			list.Add("            NAO E DOCUMENTO FISCAL           ");
			return list;
		}

