			{
				list.Add($"Objeto: {objeto.Objeto.Descricao}");
				list.Add($"Marca: {objeto.Objeto.Marca}");
				list.Add($"Modelo: {objeto.Objeto.Modelo}");
				list.Add($"Placa: {objeto.Objeto.Placa}");
				list.Add($"Serial: {objeto.Objeto.Serial}");
				list.Add($"Renavam: {objeto.Objeto.Renavam}");
				list.Add($"Ano de fabricacao: {objeto.Objeto.AnoFabricacao}");
				list.Add($"Defeito/Servico solicitado: {objeto.Defeito}");
				list.Add($"Diagnostico/Solucao: {objeto.Diagnostico}");
				list.Add("---------------------------------------");
			}
			list.Add($"Data/hora recebimento: {movimentacao.DataHoraRecebimento:dd/MM/yyyy - HH:mm:ss}");
			list.Add($"Data/hora prevista: {movimentacao.DataHoraPrevisao:dd/MM/yyyy - HH:mm:ss}");
			if (movimentacao.DataHoraEntrega > DateTime.MinValue)
			{
				list.Add($"Data/hora entrega: {movimentacao.DataHoraEntrega:dd/MM/yyyy - HH:mm:ss}");
			}
			list.Add("---------------------------------------");
			list.Add(movimentacao.Empresa.Nome);
			list.Add(movimentacao.Empresa.CpfCnpj);
			list.Add("---------------------------------------");
			list.Add($"Destinatario: {movimentacao.Pessoa.Nome}");
			list.Add($"CNPJ/CPF: {movimentacao.Pessoa.CpfCnpj}");
			list.Add($"End.: {movimentacao.Pessoa.EnderecoPrincipal.Logradouro}");
			list.Add($"N.: {movimentacao.Pessoa.EnderecoPrincipal.Numero}");
			list.Add($"Bairro.: {movimentacao.Pessoa.EnderecoPrincipal.Bairro}");
			list.Add($"Compl.: {movimentacao.Pessoa.EnderecoPrincipal.Complemento}");
			list.Add($"Cidade: {movimentacao.Pessoa.EnderecoPrincipal.Municipio?.Nome ?? string.Empty}");
			list.Add($"UF: {movimentacao.Pessoa.EnderecoPrincipal.Municipio?.UF?.Sigla ?? string.Empty}");
			list.Add($"CEP: {movimentacao.Pessoa.EnderecoPrincipal.Cep}");
			list.Add("Item Codigo   Nome");
			list.Add("Und Qtd        Vl.Unit.  D/A R$  Vl.Total R$");
			List<Tuple<string, int, string>> list2 = new List<Tuple<string, int, string>>();
			int num = 0;
			foreach (ItemDto iten in movimentacao.Itens)
			{
				num++;
				string text = string.Format("{0}{1}{2}", iten.Numero.ToString("000").PadRight(4), iten.ProdutoServico.CodigoInterno.ToString(CultureInfo.InvariantCulture).PadRight(10), iten.ProdutoServico.Descricao.PadRight(26));
				if (!iten.ObservacaoDigitada.IsNullOrEmpty())
				{
					text += $"OBS: {iten.ObservacaoDigitada.ToUpper()}";
				}
				list2.Add(new Tuple<string, int, string>(iten.ProdutoServico.CodigoInterno, num, text));
				num++;
				string item = string.Format("{0}{1}{2}{3}{4}", iten.UnidadeMedida.Sigla.ToString(CultureInfo.InvariantCulture).PadRight(4), iten.Quantidade.ToString("#,#####0.000").PadRight(11), iten.PrecoUnitario.ToString("#,#####0.00").PadRight(10), iten.DescontoDigitado.ToString("#,###0.00").PadRight(8), iten.TotalLiquido.ToString("#,#######0.00").PadRight(12));
				list2.Add(new Tuple<string, int, string>(iten.ProdutoServico.CodigoInterno, num, item));
				if (iten.Cancelado)
				{
					num++;
					string item2 = $"Cancelado item: {iten.Numero:000}";
					list2.Add(new Tuple<string, int, string>(iten.ProdutoServico.CodigoInterno, num, item2));
				}
			}
			foreach (IEnumerable<string> item3 in from tuple in list2
				group tuple by tuple.Item1 into source
				select from tuple in source.ToList()
					orderby tuple.Item2
					select tuple.Item3)
			{
				list.AddRange(item3);
			}
			list.Add("---------------------------------------");
			list.Add($"TOTAL: {movimentacao.Total:C2}");
			list.Add("---------------------------------------");
			if (!movimentacao.Observacao.IsNullOrEmpty())
			{
				list.Add($"OBSERVAÇÕES: {movimentacao.Observacao.ToUpper()}");
				list.Add("---------------------------------------");
			}
			list.Add("Forma de pagamento");
			list.Add("Parcela  Vencimento            Valor R$");
			foreach (PagamentoRecebimentoDto pagamentosRecebimento in movimentacao.PagamentosRecebimentos)
			{
				list.Add(string.Format("{0}{1}{2}", pagamentosRecebimento.Ordem.ToString().PadRight(9), pagamentosRecebimento.DataVencimento.ToString("dd/MM/yyyy").PadRight(26), pagamentosRecebimento.Valor.ToString("#,#####0.00").PadRight(10)));
			}
			list.Add("---------------------------------------");
			list.Add("   E VEDADA A AUTENTICACAO DESTE DOCUMENTO   ");
			list.Add("            NAO E DOCUMENTO FISCAL           ");
			return list;
		}

