	public class PainelBuscaKit : PainelBuscaBase<PainelBuscaKit, KitLocal, InformacaoBuscaKit>, IAtalhos, IPainelBusca, IItemMenuRibbon, ITitulo
	{
		public ISessaoService SessaoService { get; }

		public IKitRepositoryRead KitRepositoryRead { get; }

		public override string Titulo => "Importar kit";

		public IReadOnlyCollection<string> Atalhos => new List<string> { "[ Enter ] Selecionar o kit" };

		public KeyGestureCustom Key => new KeyGestureControl(System.Windows.Input.Key.K);

		public string ToolTip => Titulo;

		public PainelBuscaKit()
		{
		}

		public PainelBuscaKit(ISessaoService sessaoService, IKitRepositoryRead kitRepositoryRead, Seletor<IPainel> seletor)
			: base(seletor)
		{
			SessaoService = sessaoService;
			KitRepositoryRead = kitRepositoryRead;
			Lista.SetarCabecalho(Cabecalho<CabecalhoKit>.Criar());
		}

		public override void EnterMethod()
		{
			if (Lista.PossuiItemSelecionado)
			{
				Seletor.VoltarTudo();
				if (!ExpandirKit(Lista.ItemSelecionado.Kit, Informacao.Quantidade))
				{
					DialogoFactory.MostrarDialogoConfirma("Kit não importado: um dos produtos da composição não está disponível nesta empresa.");
				}
			}
		}

		public bool ComposicaoDisponivel(DigisatServer.Domain.Main.Aggregates.CadastrosAgg.Kits.Kit kit)
		{
			if (kit.IsNull())
			{
				return false;
			}
			List<ItemKit> source = kit.Itens.ToListEmptyWhenNull();
			if (source.Any())
			{
				return source.All((ItemKit x) => x.ProdutoServicoEmpresa.IsNotNull());
			}
			return false;
		}

		public decimal ObterPreco(DigisatServer.Domain.Main.Aggregates.CadastrosAgg.Kits.Kit kit)
		{
			if (ComposicaoDisponivel(kit))
			{
				return kit.Itens.Sum((ItemKit itemKit) => itemKit.Quantidade * (kit.UtilizarPrecoDosItensAoVender ? itemKit.PrecoVenda : itemKit.ProdutoServicoEmpresa.Preco.PrecoVendaVigente));
			}
			return 0m;
		}

		public bool ExpandirKit(DigisatServer.Domain.Main.Aggregates.CadastrosAgg.Kits.Kit kit, decimal quantidade)
		{
			if (!ComposicaoDisponivel(kit))
			{
				return false;
			}
			foreach (ItemKit iten in kit.Itens)
			{
				ProdutoServicoLocal produtoServicoLocal = FluentFactory<ProdutoServicoLocalFactory>.Init().ComSeletor(Seletor).ComProdutoServicoEmpresa(iten.ProdutoServicoEmpresa)
					.ComPermissaoEstoqueNegativo(DadosSistema.ConfiguracaoDto.Saida.PermitirEstoqueNegativo.Valor)
					.Criar();
				if (kit.UtilizarPrecoDosItensAoVender)
				{
					produtoServicoLocal = produtoServicoLocal.SetarPrecoUnitario(iten.PrecoVenda);
				}
				ProdutoServicoLocal produtoServicoLocal2 = produtoServicoLocal;
				decimal quantidade2 = iten.Quantidade * quantidade;
				ProdutoEmpresa produtoEmpresa = iten.ProdutoServicoEmpresa.To<ProdutoEmpresa>();
				int capturouPeso;
				if (produtoEmpresa != null && produtoEmpresa.Produto.Pesavel)
				{
					ProdutoEmpresa produtoEmpresa2 = iten.ProdutoServicoEmpresa.To<ProdutoEmpresa>();
					capturouPeso = ((produtoEmpresa2 == null || !produtoEmpresa2.Produto.UnidadeMedida.IsUnidade) ? 1 : 0);
				}
				else
				{
					capturouPeso = 0;
				}
				produtoServicoLocal2.Vender(quantidade2, (byte)capturouPeso != 0);
			}
			return true;
		}
	}
	public class PainelBuscalPedidoIfood : PainelBuscaBase<PainelBuscalPedidoIfood, PedidoIfoodLocal, InformacaoBuscaPedidoIfood>, IAtalhos, IPainelBusca, IPainelBuscaService<PedidoIfoodLocal>, IPainelLista<PedidoIfoodLocal>, IItemMenuRibbon, ITitulo
	{
		public IWService Service { get; protected set; }

		public override string Titulo => "Pedidos iFood";

		public IReadOnlyCollection<string> Atalhos => new List<string> { "[ Enter ] Importar pedido para documento fiscal" };

		public KeyGestureCustom Key => new KeyGestureCustom(System.Windows.Input.Key.Y, ModifierKeys.Control);

		public string ToolTip => Titulo;

		public PainelBuscalPedidoIfood()
		{
		}

		public PainelBuscalPedidoIfood(IWService service, Seletor<IPainel> seletor)
			: base(seletor)
		{
			Service = service;
			Lista.SetarCabecalho(Cabecalho<CabecalhoPedidoIfood>.Criar());
		}

		public override void EnterMethod()
		{
			if (Lista.PossuiItemSelecionado && !Lista.ItemSelecionado.PedidoIfood.Is<PedidoIfoodDtoNull>())
			{
				if (!Seletor.Get<PainelDocumentoFiscal>().EmissorCarregadoEPronto())
				{
					DialogoFactory.MostrarDialogoConfirma($"{Seletor.Get<PainelDocumentoFiscal>().Estado.MensagemOperador}");
				}
				else
				{
					Seletor.Get<PainelDocumentoFiscal>().EmitirDocumentoFiscal(Lista.ItemSelecionado.PedidoIfood);
				}
				Seletor.Voltar();
			}
		}
	}
	public class PainelBuscaMeioPagamentoTerminalPos : PainelListaBase<PainelBuscaMeioPagamentoTerminalPos, MeioPagamentoTerminalPosLocal>, IAtalhos, IPainelBusca, IMenuRibbon
	{
		private readonly Seletor<IPainel> _seletorEsquerdo;

		private readonly IMobileService _mobileService;

		private decimal _valorPagamento;

		private TransacaoDto _emPagamento;

		private bool _recebimento;

		private readonly IEmissorService _emissorService;

		private bool _isMesaContaCreditoCliente;

		public string Titulo => "Terminal POS";

		public IReadOnlyCollection<string> Atalhos => new List<string> { "[ Enter ] Confirmar", "[ ESC ] Sair/Cancelar" };

		public IEnumerable<ItemMenuAtalho> MenuRibbon => new List<ItemMenuAtalho>
		{
			new ItemMenuAtalho("Enter", "Escolher meio de pagamento", new DelegateCommand(EnterMethod, PodeEnterCommand)),
			new ItemMenuAtalho("Esc", "Sair/Cancelar", new DelegateCommand(FecharMethod, PodeVoltar))
		};

		public PainelBuscaMeioPagamentoTerminalPos()
		{
		}

		public PainelBuscaMeioPagamentoTerminalPos(IEmissorService emissorService, Seletor<IPainel> seletorDireito, Seletor<IPainel> seletorEsquerdo, IMobileService mobileService)
			: base(seletorDireito)
		{
			try
			{
				_emissorService = emissorService;
				_seletorEsquerdo = seletorEsquerdo;
				_mobileService = mobileService;
				FecharCommand = new DelegateCommand(FecharMethod, PodeVoltar);
			}
			catch (Exception ex)
			{
				ex.ShowLastException();
			}
		}

		public override void Load()
		{
			AssinarEventos();
			CarregarMeiosPagamento();
			EnterMethod();
		}

		private void CarregarMeiosPagamento()
		{
			Lista.Limpar();
			Lista.Adicionar(MeioPagamentoTerminalPosLocal.Criar().ComDescricao("Iniciando transação..."));
			Lista.PosicionarNoPrimeiro();
			RecuperarFoco();
		}

		public override void EnterMethod()
		{
			LoaderProcessoService.MostrarLoader();
			_mobileService.CriarAsync(DadosSistema.NumeroPdvTerminalPos, _valorPagamento).ContinueWith((Task task) =>
			{
				ThreadPrincipal.Executar(() =>
				{
					if (task.IsFaulted)
					{
						LoaderProcessoService.EsconderLoader();
						task.Exception.ShowLastException();
					}
				});
			});
		}

		public override void FecharMethod()
		{
			if (_emPagamento.IsNotNull())
			{
				Cancelar();
			}
			else
			{
				FecharPainel();
			}
		}

		private void Cancelar()
		{
			LoaderProcessoService.MostrarLoader("Cancelando pagamento...");
			_mobileService.CancelarAsync(_emPagamento.Id).ContinueWith((Task task) =>
			{
				ThreadPrincipal.Executar(() =>
				{
					if (!task.IsFaulted)
					{
						if (_recebimento)
						{
							Seletor.Get<PainelRecebimento>().SetarPagamentoNaoFinalizadoViaTerminalPos();
						}
					}
					else
					{
						LoaderProcessoService.EsconderLoader();
						task.Exception.ShowLastException();
					}
				});
			});
		}

		private void MobileServiceOnTransacaoTransacionandoEvent(object o, TransacaoDto transacaoDto)
		{
			_seletorEsquerdo.Get<PainelMensagem>().AlterarMensagem("Pagamento sendo processado");
		}

		private void MobileServiceOnTransacaoCanceladaEvent(object o, TransacaoDto transacaoDto)
		{
			_seletorEsquerdo.Get<PainelMensagem>().AlterarMensagem(Seletor.Get<PainelDocumentoFiscal>().Estado.MensagemOperador);
			DialogoFactory.MostrarDialogoConfirma($"O pagamento foi cancelado. ID do pagamento: {transacaoDto.Id}.");
			FecharPainel();
		}

		private void MobileServiceOnTransacaoConcluidaEvent(object o, TransacaoDto transacaoDto)
		{
			_seletorEsquerdo.Get<PainelMensagem>().AlterarMensagemTimer("Pagamento aprovado");
			if (_recebimento)
			{
				DormirAsync(300, (object x) =>
				{
					FecharPainel();
					_emissorService.AdicionarRelatorioGerencialTerminalPos(transacaoDto.ImpressoComprovante);
					Seletor.Get<PainelRecebimento>().FinalizarPagamentoTerminalPos(transacaoDto.PagamentoTransacao);
					_recebimento = false;
				});
			}
			else if (_isMesaContaCreditoCliente)
			{
				DormirAsync(300, (object x) =>
				{
					FecharPainel();
					_emissorService.AdicionarRelatorioGerencialTerminalPos(transacaoDto.ImpressoComprovante);
					Seletor.Get<PainelAdicionarMesaContaCreditoCliente>().FinalizarPagamentoTerminalPos(transacaoDto.PagamentoTransacao);
					_isMesaContaCreditoCliente = false;
				});
			}
			else
			{
				DormirAsync(300, (object x) =>
				{
					FecharPainel();
					_emissorService.AdicionarRelatorioGerencialTerminalPos(transacaoDto.ImpressoComprovante);
					Seletor.Get<PainelTotalizacaoEmissorBase>().AdicionarPagamentoTransacao(transacaoDto.PagamentoTransacao, 27);
				});
			}
		}

		private void MobileServiceOnTransacaoCriadaEvent(object o, TransacaoDto transacaoDto)
		{
			_emPagamento = transacaoDto;
			_seletorEsquerdo.Get<PainelMensagem>().AlterarMensagem("Verifique o dispositivo mobile");
			RecuperarFoco();
		}

		private void FecharPainel()
		{
			_emPagamento = null;
			FecharPainelBuscaMeioPagamentoMobile();
			LoaderProcessoService.EsconderLoader();
			DesassinarEventos();
		}

		private void FecharPainelBuscaMeioPagamentoMobile()
		{
			if (Seletor.Painel.Is<PainelBuscaMeioPagamentoTerminalPos>())
			{
				Seletor.Voltar();
			}
		}

		private void MobileServiceOnErroEvent(object sender, Exception exception)
		{
			LoaderProcessoService.EsconderLoader();
			exception.ShowLastException();
		}

		private void AssinarEventos()
		{
			_mobileService.TransacaoCriadaEvent += MobileServiceOnTransacaoCriadaEvent;
			_mobileService.TransacaoTransacionandoEvent += MobileServiceOnTransacaoTransacionandoEvent;
			_mobileService.TransacaoCanceladaEvent += MobileServiceOnTransacaoCanceladaEvent;
			_mobileService.TransacaoConcluidaEvent += MobileServiceOnTransacaoConcluidaEvent;
			_mobileService.ErroEvent += MobileServiceOnErroEvent;
		}

		private void DesassinarEventos()
		{
			_mobileService.TransacaoCriadaEvent -= MobileServiceOnTransacaoCriadaEvent;
			_mobileService.TransacaoTransacionandoEvent -= MobileServiceOnTransacaoTransacionandoEvent;
			_mobileService.TransacaoCanceladaEvent -= MobileServiceOnTransacaoCanceladaEvent;
			_mobileService.TransacaoConcluidaEvent -= MobileServiceOnTransacaoConcluidaEvent;
			_mobileService.ErroEvent -= MobileServiceOnErroEvent;
		}

		public override bool PodeVoltar()
		{
			return true;
		}

		public override bool PodeEnterCommand()
		{
			if (_emPagamento.IsNull() && Lista.IsNotNull())
			{
				return Lista.PossuiItemSelecionado;
			}
			return false;
		}

		public void SetarValor(decimal valor)
		{
			_valorPagamento = valor;
		}

		public void SetarRecebimento(bool recebimento)
		{
			_recebimento = recebimento;
		}

		public void SetarMesaContaCreditoCliente(bool isMesaContaCreditoCliente)
		{
			_isMesaContaCreditoCliente = isMesaContaCreditoCliente;
		}
	}
	public class PainelBuscaNotaFiscalConsumidorEletronica : PainelBuscaBase<PainelBuscaNotaFiscalConsumidorEletronica, DocumentoFiscalEletronicoLocal, InformacaoBuscaNotaFiscalConsumidorEletronica>, IAtalhos, IPainelBusca, IPainelBuscaService<DocumentoFiscalEletronicoLocal>, IPainelLista<DocumentoFiscalEletronicoLocal>, IItemMenuRibbon, ITitulo, IMenuRibbon
	{
		private readonly INfceService _emissorService;

		private readonly IImpressoraNaoFiscalService _impressoraNaoFiscalService;

		protected readonly Seletor<IPainel> _seletorEsquerdo;

		public IWService Service { get; protected set; }

		public override string Titulo => "Abrir NFC-e";

		public IReadOnlyCollection<string> Atalhos => new List<string> { "[ Enter ] Abrir a nota fiscal de consumidor eletrônica (NFC-e)" };

		public CustomDelegateCommand DelCommand { get; set; }

		public CustomDelegateCommand CtrlPCommand { get; set; }

		public CustomDelegateCommand CtrlTCommand { get; set; }

		public CustomDelegateCommand CtrlECommand { get; set; }

		public CustomDelegateCommand CtrlICommand { get; set; }

		public KeyGestureCustom Key => new KeyGestureCustom(System.Windows.Input.Key.F9);

		public string ToolTip => Titulo;

		public IEnumerable<ItemMenuAtalho> MenuRibbon => new List<ItemMenuAtalho>
		{
			new ItemMenuAtalho(DelCommand.KeyGesture.Descricao, "Cancelar", DelCommand, "Cancelar a nota fiscal de consumidor eletrônica (NFC-e)"),
			new ItemMenuAtalho(CtrlTCommand.KeyGesture.Descricao, "Transmitir", CtrlTCommand, "Transmitir a nota fiscal de consumidor eletrônica (NFC-e)"),
			new ItemMenuAtalho(CtrlPCommand.KeyGesture.Descricao, "Imprimir", CtrlPCommand, "Imprimir a nota fiscal de consumidor eletrônica (NFC-e)"),
			new ItemMenuAtalho(CtrlECommand.KeyGesture.Descricao, "Enviar e-mail", CtrlECommand, "Enviar e-mail da nota fiscal de consumidor eletrônica (NFC-e)"),
			new ItemMenuAtalho(CtrlICommand.KeyGesture.Descricao, "Imprimir ticket de troca", CtrlICommand, "Imprimir ticket de troca com dados da nota fiscal de consumidor eletrônica original")
		};

		public PainelBuscaNotaFiscalConsumidorEletronica()
		{
		}

		public PainelBuscaNotaFiscalConsumidorEletronica(IWService service, Seletor<IPainel> seletor, INfceService emissorService, IImpressoraNaoFiscalService impressoraNaoFiscalService, Seletor<IPainel> seletorEsquerdo)
			: base(seletor)
		{
			_emissorService = emissorService;
			_impressoraNaoFiscalService = impressoraNaoFiscalService;
			_seletorEsquerdo = seletorEsquerdo;
			Service = service;
			DelCommand = new CustomDelegateCommand(new KeyGestureCustom(System.Windows.Input.Key.Delete), CancelarNotaFiscalConsumidorEletronica, PodeCancelarNotaFiscalConsumidorEletronica);
			CtrlPCommand = new CustomDelegateCommand(new KeyGestureControl(System.Windows.Input.Key.P), ImprimirNotaFiscalConsumidorEletronica, PodeImprimirNotaFiscalConsumidorEletronica);
			CtrlTCommand = new CustomDelegateCommand(new KeyGestureControl(System.Windows.Input.Key.T), TransmitirNotaFiscalConsumidorEletronica, PodeTransmitirNotaFiscalConsumidorEletronica);
			CtrlECommand = new CustomDelegateCommand(new KeyGestureControl(System.Windows.Input.Key.E), EnviarEmail, PodeEnviarEmail);
			CtrlICommand = new CustomDelegateCommand(new KeyGestureControl(System.Windows.Input.Key.I), ImprimirTicketTroca, PodeImprimirTicketTroca);
			Lista.SetarCabecalho(Cabecalho<CabecalhoDocumentoFiscalEletronico>.Criar());
		}

		private bool PodeCancelarNotaFiscalConsumidorEletronica()
		{
			if (DadosSistema.IsPostoCombustivel && _emissorService.Tipo != TipoMovimentacao.CupomFiscal && !_seletorEsquerdo.Get<PainelEsquerdoPosto>().VerificarSemComunicacaoPostoService())
			{
				return false;
			}
			if (Lista.PossuiItemSelecionado)
			{
				return Lista.ItemSelecionado.Movimentacao.Situacao.Codigo == 2;
			}
			return false;
		}

		private void CancelarNotaFiscalConsumidorEletronica()
		{
			if (DialogoFactory.MostrarDialogoSimNao($"Cancelar NFC-e número {Lista.ItemSelecionado.Movimentacao.Numero}?") == MessageBoxResult.Yes)
			{
				_emissorService.CancelarVenda(Lista.ItemSelecionado.Movimentacao);
			}
		}

		private bool PodeTransmitirNotaFiscalConsumidorEletronica()
		{
			if (Lista.PossuiItemSelecionado)
			{
				if (Lista.ItemSelecionado.Movimentacao.Situacao.Codigo != 14 && Lista.ItemSelecionado.Movimentacao.Situacao.Codigo != 6 && Lista.ItemSelecionado.Movimentacao.Situacao.Codigo != 1 && Lista.ItemSelecionado.Movimentacao.Situacao.Codigo != 11)
				{
					return Lista.ItemSelecionado.Movimentacao.Situacao.Codigo == 13;
				}
				return true;
			}
			return false;
		}

		private void TransmitirNotaFiscalConsumidorEletronica()
		{
			_emissorService.TransmitirNfceEmSituacaoAguardando(Lista.ItemSelecionado.Movimentacao);
			Limpar();
		}

		private bool PodeImprimirNotaFiscalConsumidorEletronica()
		{
			if (Lista.PossuiItemSelecionado)
			{
				if (Lista.ItemSelecionado.Movimentacao.Situacao.Codigo != 2 && Lista.ItemSelecionado.Movimentacao.Situacao.Codigo != 14)
				{
					return Lista.ItemSelecionado.Movimentacao.Situacao.Codigo == 4;
				}
				return true;
			}
			return false;
		}

		private void ImprimirNotaFiscalConsumidorEletronica()
		{
			try
			{
				MovimentacaoDto movimentacaoDto;
				if (Lista.ItemSelecionado.Movimentacao.Situacao.Codigo.Equals(4))
				{
					movimentacaoDto = Service.Canal((INotaFiscalConsumidorEletronicaModuleService x) => x.PreencherXmlTextoAutorizadoNfceCanceladaCompactadoGZip(Lista.ItemSelecionado.Movimentacao));
					NFeProc nfeProc = (NFeProc)HelperXml.StringXmlToObject(movimentacaoDto.XmlTextoAutorizadoNfceCompactadoGZip.DecodificarBase64CompactoGzipParaString(), typeof(NFeProc));
					HistoricoDto historicoDto = movimentacaoDto.Historicos.FirstOrDefault((HistoricoDto x) => x.SituacaoMovimentacao.Codigo == 4);
					if (historicoDto.IsNotNull())
					{
						_emissorService.ImprimirCancelamentoNfce(nfeProc, historicoDto.ProtocoloAutorizacao, historicoDto.DataHoraRegistroEvento);
					}
					return;
				}
				movimentacaoDto = Service.Canal((INotaFiscalConsumidorEletronicaModuleService x) => x.PreencherXmlTextoAutorizadoNfceCompactadoGZip(Lista.ItemSelecionado.Movimentacao));
				_emissorService.ReimprimirDanfe(movimentacaoDto);
				List<RecebimentoDto> list = movimentacaoDto.PagamentosRecebimentos.OfType<RecebimentoDto>().Where((RecebimentoDto a) =>
				{
					if (!a.AVista)
					{
						EspeciePagamentoDto especiePagamento = a.EspeciePagamento;
						if (especiePagamento == null)
						{
							return false;
						}
						return especiePagamento.Codigo == 3;
					}
					return false;
				}).ToListEmptyWhenNull();
				if (list != null && list.Any())
				{
					DadosConsumidorRelatorioCarne consumidor = DadosConsumidorRelatorioCarne.Criar().ComNome(movimentacaoDto.Pessoa.Nome).ComCpfCnpjFormatado(movimentacaoDto.Pessoa.CpfCnpjFormatado)
						.ComEnderecoToText(movimentacaoDto.Pessoa.EnderecoPrincipal.ToText);
					List<DadosParcelaRelatorioCarne> parcelas = list.Select((RecebimentoDto x) => DadosParcelaRelatorioCarne.Criar().ComOrdem(x.Ordem).ComVencimento(x.DataVencimento)
						.ComValor(x.Valor)
						.ComReferencia(x.Referencia)).ToListEmptyWhenNull();
					ImprimirCarneVendaPrazo(RelatoriosEmissor.RetornarDadosRelatorioCarne(movimentacaoDto.Numero, movimentacaoDto.DataHoraEmissao, consumidor, parcelas));
				}
			}
			catch (Exception ex)
			{
				ex.ShowLastException();
			}
		}

		private void ImprimirCarneVendaPrazo(DadosRelatorioCarne40Colunas dadosRelatorio)
		{
			if (dadosRelatorio == null)
			{
				return;
			}
			if (DadosSistema.TamanhoBobina == TamanhoBobina.CinquentaESeisCinquentaESeteCinquentaEOitoMilimetros)
			{
				if (DadosSistema.ConfiguracaoDto.Saida.ImprimirViaEstabelecimentoCarneVendaPrazo.Valor)
				{
					ParcelamentoViaEstabelecimento56Mm57Mm58Mm relatorio = new ParcelamentoViaEstabelecimento56Mm57Mm58Mm(DadosSistema.RollPaper, DadosSistema.MargemEsquerdaImpressoraNaoFiscal)
					{
						Parametros = new Parametros
						{
							Objeto = dadosRelatorio
						}
					};
					_impressoraNaoFiscalService.Imprimir((IRelatorio)relatorio);
				}
				if (DadosSistema.ConfiguracaoDto.Saida.ImprimirCarneVendaPrazo.Valor)
				{
					ParcelamentoViaCliente56Mm57Mm58Mm relatorio2 = new ParcelamentoViaCliente56Mm57Mm58Mm(DadosSistema.RollPaper, DadosSistema.MargemEsquerdaImpressoraNaoFiscal)
					{
						Parametros = new Parametros
						{
							Objeto = dadosRelatorio
						}
					};
					_impressoraNaoFiscalService.Imprimir((IRelatorio)relatorio2);
				}
			}
			else
			{
				if (DadosSistema.ConfiguracaoDto.Saida.ImprimirViaEstabelecimentoCarneVendaPrazo.Valor)
				{
					ParcelamentoViaEstabelecimento79Mm80Mm relatorio3 = new ParcelamentoViaEstabelecimento79Mm80Mm(DadosSistema.RollPaper, DadosSistema.MargemEsquerdaImpressoraNaoFiscal)
					{
						Parametros = new Parametros
						{
							Objeto = dadosRelatorio
						}
					};
					_impressoraNaoFiscalService.Imprimir((IRelatorio)relatorio3);
				}
				if (DadosSistema.ConfiguracaoDto.Saida.ImprimirCarneVendaPrazo.Valor)
				{
					ParcelamentoViaCliente79Mm80Mm relatorio4 = new ParcelamentoViaCliente79Mm80Mm(DadosSistema.RollPaper, DadosSistema.MargemEsquerdaImpressoraNaoFiscal)
					{
						Parametros = new Parametros
						{
							Objeto = dadosRelatorio
						}
					};
					_impressoraNaoFiscalService.Imprimir((IRelatorio)relatorio4);
				}
			}
		}

		private bool PodeImprimirTicketTroca()
		{
			if (Lista.PossuiItemSelecionado)
			{
				return Lista.ItemSelecionado.Movimentacao.Situacao.Codigo == 2;
			}
			return false;
		}

		private void ImprimirTicketTroca()
		{
			try
			{
				MovimentacaoDto movimentacao = Lista.ItemSelecionado.Movimentacao;
				IRelatorio relatorio2;
				if (DadosSistema.TamanhoBobina != TamanhoBobina.CinquentaESeisCinquentaESeteCinquentaEOitoMilimetros)
				{
					IRelatorio relatorio = new RelatorioTicketTroca79Mm80Mm(movimentacao, DadosSistema.MargemEsquerdaImpressoraNaoFiscal, DadosSistema.RollPaper);
					relatorio2 = relatorio;
				}
				else
				{
					IRelatorio relatorio = new RelatorioTicketTroca56Mm57Mm58Mm(movimentacao, DadosSistema.MargemEsquerdaImpressoraNaoFiscal, DadosSistema.RollPaper);
					relatorio2 = relatorio;
				}
				IRelatorio relatorio3 = relatorio2;
				_impressoraNaoFiscalService.Imprimir(relatorio3);
			}
			catch (Exception ex)
			{
				ex.ShowLastException();
			}
		}

		private async void EnviarEmail()
		{
			try
			{
				MovimentacaoDto movimentacao = Service.Canal((INotaFiscalConsumidorEletronicaModuleService x) => x.PreencherXmlTextoAutorizadoNfceCompactadoGZip(Lista.ItemSelecionado.Movimentacao));
				await _emissorService.EnviarEmailNotaFiscalConsumidorEletronica(movimentacao);
			}
			catch (Exception ex)
			{
				ex.ShowLastException();
			}
			finally
			{
				Limpar();
			}
		}

		private bool PodeEnviarEmail()
		{
			if (Lista.PossuiItemSelecionado)
			{
				return Lista.ItemSelecionado.Movimentacao.Situacao.Codigo == 2;
			}
			return false;
		}

		public override void EnterMethod()
		{
			DocumentoFiscalEletronicoLocal itemSelecionado = Lista.ItemSelecionado;
			if (itemSelecionado.IsNull())
			{
				return;
			}
			switch (itemSelecionado.Movimentacao.Situacao.Codigo)
			{
			case 4:
			case 12:
			case 14:
				return;
			case 2:
				if (itemSelecionado.Movimentacao?.Itens?.Any((ItemDto x) => !string.IsNullOrEmpty(x.AbastecimentoReferencia)) ?? false)
				{
					DialogoFactory.MostrarDialogoConfirma("A NFC-e possui abastecimento vinculado e não pode ser importada!");
				}
				else
				{
					ProcessarNovaTransmissao();
				}
				return;
			}
			ItemDto itemDto = itemSelecionado.Movimentacao?.Itens?.FirstOrDefault((ItemDto x) => !string.IsNullOrEmpty(x.AbastecimentoReferencia));
			bool flag = false;
			try
			{
				if (itemDto.IsNotNull())
				{
					flag = _emissorService.VerificarExistenciaMovimentacaoAguardandoComAbastecimento(itemDto.AbastecimentoReferencia);
				}
			}
			catch (Exception)
			{
				flag = true;
			}
			if (flag)
			{
				DialogoFactory.MostrarDialogoConfirma("A NFC-e possui abastecimento vinculado e não pode ser importada, a mesma deve ser transmitida através da opção 'Ctrl+T - Transmitir'");
			}
			else
			{
				ProcessarNovaTransmissao();
			}
		}

		private void ProcessarNovaTransmissao()
		{
			if (DialogoFactory.MostrarDialogoSimNao("Uma nova transmissão da NFC-e irá gerar nova numeração. Continuar?") != MessageBoxResult.Yes)
			{
				return;
			}
			ConfiguracaoDepartamentoVenda configuracaoDepartamentoVenda = DadosSistema.ObterDepartamentoVenda();
			foreach (ItemDto iten in Lista.ItemSelecionado.Movimentacao.Itens)
			{
				iten.DepartamentoReferencia = configuracaoDepartamentoVenda.DepartamentoVendaReferencia;
			}
			Seletor.Get<PainelDocumentoFiscal>().EmitirDocumentoFiscal(Lista.ItemSelecionado.Movimentacao);
			Seletor.Voltar();
		}

