			if (DadosSistema.CarregarQuantidadeRegistrosBuscaMovimentacao)
			{
				Informacao.PesquisarUltimosRegistros(DadosSistema.QuantidadeRegistrosCarregarBuscaMovimentacoes);
			}
		}
