		public PainelBuscaNotaFiscalEletronica(IWService service, Seletor<IPainel> seletor, INfceService emissorService, IImpressoraNaoFiscalService impressoraNaoFiscalService, Seletor<IPainel> seletorEsquerdo)
			: base(seletor)
		{
			_emissorService = emissorService;
			_impressoraNaoFiscalService = impressoraNaoFiscalService;
			_seletorEsquerdo = seletorEsquerdo;
			Service = service;
			DelCommand = new CustomDelegateCommand(new KeyGestureCustom(System.Windows.Input.Key.Delete), CancelarNotaFiscalEletronica, PodeCancelarNotaFiscalEletronica);
			CtrlPCommand = new CustomDelegateCommand(new KeyGestureControl(System.Windows.Input.Key.P), ImprimirNotaFiscalEletronica, PodeImprimirNotaFiscalEletronica);
			CtrlTCommand = new CustomDelegateCommand(new KeyGestureControl(System.Windows.Input.Key.T), TransmitirNotaFiscalEletronica, PodeTransmitirNotaFiscalEletronica);
			CtrlECommand = new CustomDelegateCommand(new KeyGestureControl(System.Windows.Input.Key.E), EnviarEmail, PodeEnviarEmail);
			CtrlICommand = new CustomDelegateCommand(new KeyGestureControl(System.Windows.Input.Key.I), ImprimirTicketTroca, PodeImprimirTicketTroca);
