		private bool PodeCancelarNotaFiscalEletronica()
		{
			if (DadosSistema.IsPostoCombustivel && _emissorService.Tipo != TipoMovimentacao.CupomFiscal && !_seletorEsquerdo.Get<PainelEsquerdoPosto>().VerificarSemComunicacaoPostoService())
			{
				return false;
			}
			if (Lista.PossuiItemSelecionado)
			{
				return Lista.ItemSelecionado.Movimentacao.Situacao.Codigo == 2;
			}
			return false;
		}

		private void CancelarNotaFiscalEletronica()
		{
			if (DialogoFactory.MostrarDialogoSimNao($"Cancelar NF-e número {Lista.ItemSelecionado.Movimentacao.Numero}?") == MessageBoxResult.Yes)
			{
				_emissorService.CancelarVenda(Lista.ItemSelecionado.Movimentacao);
			}
		}

		private bool PodeTransmitirNotaFiscalEletronica()
		{
			if (Lista.PossuiItemSelecionado)
			{
				if (Lista.ItemSelecionado.Movimentacao.Situacao.Codigo != 14 && Lista.ItemSelecionado.Movimentacao.Situacao.Codigo != 6 && Lista.ItemSelecionado.Movimentacao.Situacao.Codigo != 1 && Lista.ItemSelecionado.Movimentacao.Situacao.Codigo != 11)
				{
					return Lista.ItemSelecionado.Movimentacao.Situacao.Codigo == 13;
				}
				return true;
			}
			return false;
		}

		private void TransmitirNotaFiscalEletronica()
		{
			_emissorService.TransmitirNfceEmSituacaoAguardando(Lista.ItemSelecionado.Movimentacao);
			Limpar();
		}

		private bool PodeImprimirNotaFiscalEletronica()
		{
			if (Lista.PossuiItemSelecionado)
			{
				if (Lista.ItemSelecionado.Movimentacao.Situacao.Codigo != 2 && Lista.ItemSelecionado.Movimentacao.Situacao.Codigo != 14)
				{
					return Lista.ItemSelecionado.Movimentacao.Situacao.Codigo == 4;
				}
				return true;
			}
			return false;
		}

		private void ImprimirNotaFiscalEletronica()
		{
			try
			{
				MovimentacaoDto movimentacaoDto;
				if (Lista.ItemSelecionado.Movimentacao.Situacao.Codigo.Equals(4))
				{
					movimentacaoDto = Service.Canal((INotaFiscalConsumidorEletronicaModuleService x) => x.PreencherXmlTextoAutorizadoNfceCanceladaCompactadoGZip(Lista.ItemSelecionado.Movimentacao));
					NFeProc nfeProc = (NFeProc)HelperXml.StringXmlToObject(movimentacaoDto.XmlTextoAutorizadoNfceCompactadoGZip.DecodificarBase64CompactoGzipParaString(), typeof(NFeProc));
					if (movimentacaoDto.Historicos.FirstOrDefault((HistoricoDto x) => x.SituacaoMovimentacao.Codigo == 4).IsNotNull())
					{
						_emissorService.ImprimirCancelamentoNfe(nfeProc, movimentacaoDto);
					}
					return;
				}
				movimentacaoDto = Service.Canal((INotaFiscalConsumidorEletronicaModuleService x) => x.PreencherXmlTextoAutorizadoNfceCompactadoGZip(Lista.ItemSelecionado.Movimentacao));
				_emissorService.ReimprimirDanfe(movimentacaoDto);
				List<RecebimentoDto> list = movimentacaoDto.PagamentosRecebimentos.OfType<RecebimentoDto>().Where((RecebimentoDto a) =>
				{
					if (!a.AVista)
					{
						EspeciePagamentoDto especiePagamento = a.EspeciePagamento;
						if (especiePagamento == null)
						{
							return false;
						}
						return especiePagamento.Codigo == 3;
					}
					return false;
				}).ToListEmptyWhenNull();
				if (list != null && list.Any())
				{
					DadosConsumidorRelatorioCarne consumidor = DadosConsumidorRelatorioCarne.Criar().ComNome(movimentacaoDto.Pessoa.Nome).ComCpfCnpjFormatado(movimentacaoDto.Pessoa.CpfCnpjFormatado)
						.ComEnderecoToText(movimentacaoDto.Pessoa.EnderecoPrincipal.ToText);
					List<DadosParcelaRelatorioCarne> parcelas = list.Select((RecebimentoDto x) => DadosParcelaRelatorioCarne.Criar().ComOrdem(x.Ordem).ComVencimento(x.DataVencimento)
						.ComValor(x.Valor)
						.ComReferencia(x.Referencia)).ToListEmptyWhenNull();
					ImprimirCarneVendaPrazo(RelatoriosEmissor.RetornarDadosRelatorioCarne(movimentacaoDto.Numero, movimentacaoDto.DataHoraEmissao, consumidor, parcelas));
				}
			}
			catch (Exception ex)
			{
				ex.ShowLastException();
			}
		}

		private void ImprimirCarneVendaPrazo(DadosRelatorioCarne40Colunas dadosRelatorio)
		{
			if (dadosRelatorio == null)
			{
				return;
			}
			if (DadosSistema.TamanhoBobina == TamanhoBobina.CinquentaESeisCinquentaESeteCinquentaEOitoMilimetros)
			{
				if (DadosSistema.ConfiguracaoDto.Saida.ImprimirViaEstabelecimentoCarneVendaPrazo.Valor)
				{
					ParcelamentoViaEstabelecimento56Mm57Mm58Mm relatorio = new ParcelamentoViaEstabelecimento56Mm57Mm58Mm(DadosSistema.RollPaper, DadosSistema.MargemEsquerdaImpressoraNaoFiscal)
					{
						Parametros = new Parametros
						{
							Objeto = dadosRelatorio
						}
					};
					_impressoraNaoFiscalService.Imprimir((IRelatorio)relatorio);
				}
				if (DadosSistema.ConfiguracaoDto.Saida.ImprimirCarneVendaPrazo.Valor)
				{
					ParcelamentoViaCliente56Mm57Mm58Mm relatorio2 = new ParcelamentoViaCliente56Mm57Mm58Mm(DadosSistema.RollPaper, DadosSistema.MargemEsquerdaImpressoraNaoFiscal)
					{
						Parametros = new Parametros
						{
							Objeto = dadosRelatorio
						}
					};
					_impressoraNaoFiscalService.Imprimir((IRelatorio)relatorio2);
				}
			}
			else
			{
				if (DadosSistema.ConfiguracaoDto.Saida.ImprimirViaEstabelecimentoCarneVendaPrazo.Valor)
				{
					ParcelamentoViaEstabelecimento79Mm80Mm relatorio3 = new ParcelamentoViaEstabelecimento79Mm80Mm(DadosSistema.RollPaper, DadosSistema.MargemEsquerdaImpressoraNaoFiscal)
					{
						Parametros = new Parametros
						{
							Objeto = dadosRelatorio
						}
					};
					_impressoraNaoFiscalService.Imprimir((IRelatorio)relatorio3);
				}
				if (DadosSistema.ConfiguracaoDto.Saida.ImprimirCarneVendaPrazo.Valor)
				{
					ParcelamentoViaCliente79Mm80Mm relatorio4 = new ParcelamentoViaCliente79Mm80Mm(DadosSistema.RollPaper, DadosSistema.MargemEsquerdaImpressoraNaoFiscal)
					{
						Parametros = new Parametros
						{
							Objeto = dadosRelatorio
						}
					};
					_impressoraNaoFiscalService.Imprimir((IRelatorio)relatorio4);
				}
			}
		}

		private bool PodeImprimirTicketTroca()
		{
			if (Lista.PossuiItemSelecionado)
			{
				return Lista.ItemSelecionado.Movimentacao.Situacao.Codigo == 2;
			}
			return false;
		}

		private void ImprimirTicketTroca()
		{
			try
			{
				MovimentacaoDto movimentacao = Lista.ItemSelecionado.Movimentacao;
				IRelatorio relatorio2;
				if (DadosSistema.TamanhoBobina != TamanhoBobina.CinquentaESeisCinquentaESeteCinquentaEOitoMilimetros)
				{
					IRelatorio relatorio = new RelatorioTicketTroca79Mm80Mm(movimentacao, DadosSistema.MargemEsquerdaImpressoraNaoFiscal, DadosSistema.RollPaper);
					relatorio2 = relatorio;
				}
				else
				{
					IRelatorio relatorio = new RelatorioTicketTroca56Mm57Mm58Mm(movimentacao, DadosSistema.MargemEsquerdaImpressoraNaoFiscal, DadosSistema.RollPaper);
					relatorio2 = relatorio;
				}
				IRelatorio relatorio3 = relatorio2;
				_impressoraNaoFiscalService.Imprimir(relatorio3);
			}
			catch (Exception ex)
			{
				ex.ShowLastException();
			}
		}

		private async void EnviarEmail()
		{
			try
			{
				MovimentacaoDto movimentacao = Service.Canal((INotaFiscalConsumidorEletronicaModuleService x) => x.PreencherXmlTextoAutorizadoNfceCompactadoGZip(Lista.ItemSelecionado.Movimentacao));
				await _emissorService.EnviarEmailNotaFiscalConsumidorEletronica(movimentacao);
			}
			catch (Exception ex)
			{
				ex.ShowLastException();
			}
			finally
			{
				Limpar();
			}
		}

		private bool PodeEnviarEmail()
		{
			if (Lista.PossuiItemSelecionado)
			{
				return Lista.ItemSelecionado.Movimentacao.Situacao.Codigo == 2;
			}
			return false;
		}

		public override void EnterMethod()
		{
			DocumentoFiscalEletronicoLocal itemSelecionado = Lista.ItemSelecionado;
			if (itemSelecionado.IsNull())
			{
				return;
			}
			switch (itemSelecionado.Movimentacao.Situacao.Codigo)
			{
			case 4:
			case 12:
			case 14:
				return;
			case 2:
				if (itemSelecionado.Movimentacao?.Itens?.Any((ItemDto x) => !string.IsNullOrEmpty(x.AbastecimentoReferencia)) ?? false)
				{
					DialogoFactory.MostrarDialogoConfirma("A NF-e possui abastecimento vinculado e não pode ser importada!");
				}
				else
				{
					ProcessarNovaTransmissao();
				}
				return;
			}
			ItemDto itemDto = itemSelecionado.Movimentacao?.Itens?.FirstOrDefault((ItemDto x) => !string.IsNullOrEmpty(x.AbastecimentoReferencia));
			bool flag = false;
			try
			{
				if (itemDto.IsNotNull())
				{
					flag = _emissorService.VerificarExistenciaMovimentacaoAguardandoComAbastecimento(itemDto.AbastecimentoReferencia);
				}
			}
			catch (Exception)
			{
				flag = true;
			}
			if (flag)
			{
				DialogoFactory.MostrarDialogoConfirma("A NF-e possui abastecimento vinculado e não pode ser importada, a mesma deve ser transmitida através da opção 'Ctrl+T - Transmitir'");
			}
			else
			{
				ProcessarNovaTransmissao();
			}
		}

		private void ProcessarNovaTransmissao()
		{
			if (DialogoFactory.MostrarDialogoSimNao("Uma nova transmissão da NF-e irá gerar nova numeração. Continuar?") != MessageBoxResult.Yes)
			{
				return;
			}
			ConfiguracaoDepartamentoVenda configuracaoDepartamentoVenda = DadosSistema.ObterDepartamentoVenda();
			foreach (ItemDto iten in Lista.ItemSelecionado.Movimentacao.Itens)
			{
				iten.DepartamentoReferencia = configuracaoDepartamentoVenda.DepartamentoVendaReferencia;
			}
			Seletor.Get<PainelDocumentoFiscal>().EmitirDocumentoFiscal(Lista.ItemSelecionado.Movimentacao);
			Seletor.Voltar();
		}

		protected override void ListaOnAlterouItemSelecionadoEvent(object sender, DocumentoFiscalEletronicoLocal item)
		{
			base.ListaOnAlterouItemSelecionadoEvent(sender, item);
			RecuperarFoco();
		}

		public override void Load()
		{
			base.Load();
			if (DadosSistema.CarregarQuantidadeRegistrosBuscaMovimentacao)
			{
				Informacao.PesquisarUltimosRegistros(DadosSistema.QuantidadeRegistrosCarregarBuscaMovimentacoes);
			}
		}
	}
	public class PainelBuscaPreVenda : PainelInteracao<PainelBuscaPreVenda>, IItemMenuRibbon, ITitulo, IMenuRibbon
	{
		private readonly IArquivoAuxiliarService _arquivoAuxiliarService;

		private readonly INfceService _nfceService;

		private readonly InteracaoComando<string> _interacaoNumero;

		private readonly ItemInteracaoListaPreVenda _interacaoListaPreVendas;

		private readonly IEmissorService _emissorService;

		public override string Titulo => "Importar pré-venda";

		public IEnumerable<ItemMenuAtalho> MenuRibbon => new List<ItemMenuAtalho>
		{
			new ItemMenuAtalho(F4Command.KeyGesture.Descricao, "Gerar NFC-e", F4Command)
		};

		public IWService Service { get; protected set; }

		public ICommand DelCommand { get; protected set; }

		public ICommand F3Command { get; protected set; }

		public CustomDelegateCommand F4Command { get; set; }

		public KeyGestureCustom Key => new KeyGestureCustom(System.Windows.Input.Key.F11);

		public string ToolTip => Titulo;

		public PainelBuscaPreVenda()
		{
		}

		public PainelBuscaPreVenda(IEmissorService emissorService, IWService service, IArquivoAuxiliarService arquivoAuxiliarService, Seletor<IPainel> seletor, INfceService nfceService)
			: base(seletor)
		{
			_emissorService = emissorService;
			_arquivoAuxiliarService = arquivoAuxiliarService;
			_nfceService = nfceService;
			Service = service;
			_interacaoNumero = InteracaoComando<string>.Criar().ComComando(new DelegateCommand(AdicionarNumero, PodePesquisarPorNumero)).Build();
			ItemInteracaoLongComandoFocusable item = ItemInteracaoBase<ItemInteracaoLongComandoFocusable, InteracaoComando<string>>.Criar().ComDescricao("Número").ComValor(_interacaoNumero)
				.Build();
			_interacaoListaPreVendas = ItemInteracaoBase<ItemInteracaoListaPreVenda, Lista<Otus.Modulo.PontoDeVendas.ViewModels.ItensInteracao.PreVenda>>.Criar().ComDescricao("Pré-venda(s) selecionada(s)").ComValor(new Lista<Otus.Modulo.PontoDeVendas.ViewModels.ItensInteracao.PreVenda>())
				.Build();
			Campos.Insert(0, item);
			Campos.Insert(1, _interacaoListaPreVendas);
			DelCommand = new DelegateCommand<object>(RemoverItem);
			F4Command = new CustomDelegateCommand(new KeyGestureCustom(System.Windows.Input.Key.F4), GerarNfCe, PodeGerarNFCe);
			F2Command = new AsyncCommand(F2MethodAsync, CanF2Method, allowMultipleExecution: false);
			F3Command = new DelegateCommand(Pesquisar);
		}

		private bool PodePesquisarPorNumero()
		{
			return !string.IsNullOrWhiteSpace(_interacaoNumero.Dado);
		}

		private void AdicionarNumero()
		{
			try
			{
				long numero = _interacaoNumero.Dado.ApenasNumeros().ToLong();
				if (!VerificarNumeroJaImportado(numero) && !_interacaoListaPreVendas.Valor.Itens.Any((Otus.Modulo.PontoDeVendas.ViewModels.ItensInteracao.PreVenda a) => a.Numero.Equals(numero)))
				{
					_interacaoListaPreVendas.Valor.Adicionar(Documento<Otus.Modulo.PontoDeVendas.ViewModels.ItensInteracao.PreVenda>.Criar().ComNumero(numero).ComCommand(DelCommand)
						.Build());
				}
			}
			catch (Exception ex)
			{
				DialogoFactory.MostrarDialogoConfirma(ex.Message, bloquearEnter: true);
			}
			finally
			{
				_interacaoNumero.Limpar(() => string.Empty);
				_interacaoNumero.SetarFocoNoDado();
			}
		}

		private bool VerificarNumeroJaImportado(long numero)
		{
			bool? flag = Seletor.Get<PainelDocumentoFiscal>().PreDocumentoFiscal?.MovimentacoesReferenciadas?.Any((MovimentacaoReferenciada x) => x.Numero.Equals(numero));
			int num;
			if (!flag.HasValue)
			{
				num = 0;
			}
			else
			{
				num = ((flag == true) ? 1 : 0);
				if (num != 0)
				{
					DialogoFactory.MostrarDialogoConfirma($"Pré-venda {numero} já importada nesse documento fiscal");
				}
			}
			return (byte)num != 0;
		}

		public void AdicionarNumeros(IEnumerable<long> numerosPreVendas)
		{
			try
			{
				foreach (long numeroPreVenda in numerosPreVendas)
				{
					if (!VerificarNumeroJaImportado(numeroPreVenda) && !_interacaoListaPreVendas.Valor.Itens.Any((Otus.Modulo.PontoDeVendas.ViewModels.ItensInteracao.PreVenda a) => a.Numero.Equals(numeroPreVenda)))
					{
						_interacaoListaPreVendas.Valor.Adicionar(Documento<Otus.Modulo.PontoDeVendas.ViewModels.ItensInteracao.PreVenda>.Criar().ComNumero(numeroPreVenda).ComCommand(DelCommand)
							.Build());
					}
				}
			}
			finally
			{
				_interacaoNumero.Limpar(() => string.Empty);
				_interacaoNumero.SetarFocoNoDado();
			}
		}

		private void RemoverItem(object item)
		{
			Otus.Modulo.PontoDeVendas.ViewModels.ItensInteracao.PreVenda item2 = (item as Otus.Modulo.PontoDeVendas.ViewModels.ItensInteracao.PreVenda) ?? _interacaoListaPreVendas.Valor.ItemSelecionado;
			_interacaoListaPreVendas.Valor.Remover(item2);
			Window mainWindow = System.Windows.Application.Current.MainWindow;
			TraversalRequest request = new TraversalRequest(FocusNavigationDirection.Next)
			{
				Wrapped = true
			};
			mainWindow.MoveFocus(request);
		}

		private void Pesquisar()
		{
			Seletor.Selecionar<PainelPesquisarPreVenda>();
		}

		public override void Load()
		{
		}

		public override void UnLoad()
		{
		}

		public override void FecharMethod()
		{
			base.FecharMethod();
			_interacaoListaPreVendas.Valor.Limpar();
		}

		public override bool PodeVoltar()
		{
			return true;
		}

		public override void Dispose()
		{
		}

		private async Task F2MethodAsync()
		{
			LoaderProcessoService.MostrarLoader("Importando pré-vendas...");
			await Task.Factory.StartNew(() =>
			{
				ObterPrevenda((IEnumerable<MovimentacaoDto> preVendas) =>
				{
					_interacaoListaPreVendas.Valor.Limpar();
					Seletor.Voltar();
					foreach (MovimentacaoDto preVenda in preVendas)
					{
						Seletor.Get<PainelDocumentoFiscal>().EmitirDocumentoFiscal(preVenda);
					}
					string text = string.Join(Environment.NewLine, preVendas.Select((MovimentacaoDto x) => x.Observacao));
					if (!string.IsNullOrWhiteSpace(text) && DialogoFactory.MostrarDialogoSimNao($"Observações da pré-venda:{Environment.NewLine}'{text}'.{Environment.NewLine}Deseja utilizar essa observação na NFC-e?") == MessageBoxResult.Yes)
					{
						Seletor.Get<PainelObservacao>().Reload(text);
						Seletor.Get<PainelObservacao>().F2Command.Execute(1);
					}
				});
			}, CancellationToken.None, TaskCreationOptions.None, TaskScheduler.FromCurrentSynchronizationContext()).ContinueWith((Task task) =>
			{
				LoaderProcessoService.EsconderLoader();
				if (task.IsFaulted)
				{
					task.Exception.ShowLastException();
				}
			}, CancellationToken.None, TaskContinuationOptions.None, TaskScheduler.FromCurrentSynchronizationContext());
		}

		protected override void F2Method()
		{
		}

		private void ObterPrevenda(Action<IEnumerable<MovimentacaoDto>> callback)
		{
			try
			{
				IEnumerable<long> numerosPreVendas = _interacaoListaPreVendas.Valor.Itens.Select((Otus.Modulo.PontoDeVendas.ViewModels.ItensInteracao.PreVenda a) => a.Numero);
				IEnumerable<MovimentacaoDto> source = Service.Canal((IPreVendaModuleService service) => service.MesclarPreVendas(DadosSistema.IsPaf, numerosPreVendas));
				if (!source.Any())
				{
					DialogoFactory.MostrarDialogoConfirma((_interacaoListaPreVendas.Valor.Itens.Count == 1) ? "Não foi possível importar a pré-venda" : "Não foi possível mesclar as pré-vendas");
					return;
				}
				List<MovimentacaoDto> preVendasMescladas = source.Where((MovimentacaoDto x) => x.Situacao.Codigo == 2).ToListEmptyWhenNull();
				IEnumerable<MovimentacaoDto> enumerable = source.Where((MovimentacaoDto x) => x.Situacao.Codigo == 16 || x.Situacao.Codigo == 12);
				if (!enumerable.IsNull())
				{
					ImprimirPreVendasMescladas(preVendasMescladas);
					callback(enumerable);
				}
			}
			catch (Exception)
			{
				DialogoFactory.MostrarDialogoConfirma("Erro ao importar/mesclar pré-venda(s)");
			}
		}

		private void ImprimirPreVendasMescladas(IEnumerable<MovimentacaoDto> preVendasMescladas)
		{
			try
			{
				if (_interacaoListaPreVendas.Valor.Itens.Count <= 1 || _emissorService.Tipo != TipoMovimentacao.CupomFiscal)
				{
					return;
				}
				IEnumerable<MovimentacaoDto> preVendas = Service.Canal((IPreVendaModuleService service) => service.ObterPreVendasPorNumero(preVendasMescladas.Select((MovimentacaoDto a) => a.Id)));
				Seletor.Get<PainelDocumentoFiscal>().EmitirCancelarPreVendasMescladas(preVendas);
			}
			catch (Exception)
			{
				DialogoFactory.MostrarDialogoConfirma("Erro ao cancelar pré-vendas mescladas");
			}
		}

		protected override bool CanF2Method()
		{
			return _interacaoListaPreVendas.Valor.Itens.Any();
		}

		protected override void Limpar()
		{
			foreach (IItemInteracao campo in Campos)
			{
				campo.Limpar();
			}
			base.Limpar();
		}

		private void GerarNfCe()
		{
			LoaderProcessoService.MostrarLoader();
			ObterPrevenda((IEnumerable<MovimentacaoDto> prevendaDto) =>
			{
				Task.Factory.StartNew(() =>
				{
					MovimentacaoDto movimentacaoDto = prevendaDto.FirstOrDefault().ProjectedPreVendaDavMovimentacaoDto(_arquivoAuxiliarService.Md5ArquivosAutenticados);
					return Service.Canal((INotaFiscalConsumidorEletronicaModuleService service) => service.EfetivarPreDocumentoFiscal(movimentacaoDto));
				}).ContinueWith((Task<MovimentacaoDto> task) =>
				{
					try
					{
						if (task.Exception.IsNotNull())
						{
							throw new Exception(task.Exception.InnerException.Message);
						}
						MovimentacaoDto result = task.Result;
						if (result.Situacao.Codigo == 6)
						{
							throw new Exception(result.Historicos.LastOrDefault().Observacao);
						}
						if (_nfceService.IsNull())
						{
							DialogoFactory.MostrarDialogoConfirma("NFC-e transmitida com sucesso");
						}
						else
						{
							_nfceService.To<NfceService>().Imprimir(result);
						}
					}
					catch (Exception ex)
					{
						DialogoFactory.MostrarDialogoConfirma(ex.Message);
					}
					finally
					{
						LoaderProcessoService.EsconderLoader();
						Seletor.Voltar();
					}
				}, TaskScheduler.FromCurrentSynchronizationContext());
			});
		}

		private bool PodeGerarNFCe()
		{
			return DadosSistema.PodeEmitirNFCePreVendaDav;
		}
	}
	public class PainelBuscaAdministradoraCartao : PainelListaBase<PainelBuscaAdministradoraCartao, AdministradoraCartaoLocal>, IAtalhos, IPainelBusca
	{
		private readonly IPessoaRepositoryRead _pessoaRepositoryRead;

		private bool _isRecebimento;

		private bool _isMesaContaCreditoCliente;

		public IWService Service { get; protected set; }

		public string Titulo => "Consulta de administradora de cartão";

		public IReadOnlyCollection<string> Atalhos => new List<string> { "[ Enter ] Selecionar a administradora de cartão" };

		public decimal Valor { get; set; }

		public PainelBuscaAdministradoraCartao()
		{
		}

		public PainelBuscaAdministradoraCartao(IPessoaRepositoryRead pessoaRepositoryRead, Seletor<IPainel> seletor)
			: base(seletor)
		{
			_pessoaRepositoryRead = pessoaRepositoryRead;
		}

		public override void Load()
		{
			Lista.Limpar();
			IEnumerable<DigisatServer.Domain.Main.Aggregates.CadastrosAgg.Pessoas.Pessoa> source = _pessoaRepositoryRead.Find(EntitySpecification<DigisatServer.Domain.Main.Aggregates.CadastrosAgg.Pessoas.Pessoa>.Ativo().AdministradoraCartao());
			if (!source.Any())
			{
				DialogoFactory.MostrarDialogoConfirma("Nenhuma pessoa do tipo 'Administradora de cartão' cadastrada.");
				Seletor.Voltar();
				return;
			}
			foreach (Juridica item in from x in source.OfType<Juridica>()
				where x.AdministradoraCartao.RedesTaxasCartoes.Any()
				select x)
			{
				Lista.Adicionar(AdministradoraCartaoLocal.Criar().ComPessoa(item).Build());
			}
			Lista.PosicionarNoPrimeiro();
			Lista.SetarCabecalho(Cabecalho<CabecalhoAdministradoraLocal>.Criar());
			if (Lista.Numero == 1)
			{
				EnterMethod();
			}
		}

		public override void EnterMethod()
		{
			if (Lista.PossuiItemSelecionado)
			{
				Seletor.Fechar();
				Seletor.Get<PainelBuscaRedePos>().SetarValor(Valor);
				if (_isMesaContaCreditoCliente)
				{
					_isMesaContaCreditoCliente = false;
					Seletor.Get<PainelBuscaRedePos>().SetarMesaContaCreditoCliente(isMesaContaCreditoCliente: true);
					Seletor.Get<PainelBuscaRedePos>().SetarAdministradoraCartao(Lista.ItemSelecionado.ObterAdministradoraCartao());
					Seletor.Selecionar<PainelBuscaRedePos, PainelAdicionarMesaContaCreditoCliente>();
				}
				else
				{
					Seletor.Get<PainelBuscaRedePos>().SetarIsRecebimento(_isRecebimento);
					Seletor.Get<PainelBuscaRedePos>().SetarAdministradoraCartao(Lista.ItemSelecionado.ObterAdministradoraCartao());
					Seletor.Selecionar<PainelBuscaRedePos, PainelTotalizacaoEmissorBase>();
				}
			}
		}

		public override bool PodeVoltar()
		{
			return true;
		}

		public void SetarValor(decimal valor)
		{
			Valor = valor;
		}

		public void SetarIsRecebimento(bool isRecebimento = false)
		{
			_isRecebimento = isRecebimento;
		}

		public void SetarMesaContaCreditoCliente(bool isMesaContaCreditoCliente = false)
		{
			_isMesaContaCreditoCliente = isMesaContaCreditoCliente;
		}
	}
	public class PainelBuscaRedePos : PainelListaBase<PainelBuscaRedePos, RedePosLocal>, IAtalhos, IPainelBusca
	{
		private readonly IPessoaRepositoryRead _pessoaRepositoryRead;

		private bool _isRecebimento;

		private bool _isMesaContaCreditoCliente;

		private DigisatServer.Domain.Main.Aggregates.CadastrosAgg.Pessoas.Pessoa _administradoraCartao;

		public IWService Service { get; protected set; }

		public string Titulo => "Consulta de redes";

		public IReadOnlyCollection<string> Atalhos => new List<string> { "[ Enter ] Selecionar a rede" };

		public decimal Valor { get; set; }

		public PainelBuscaRedePos()
		{
		}

		public PainelBuscaRedePos(IPessoaRepositoryRead pessoaRepositoryRead, Seletor<IPainel> seletor)
			: base(seletor)
		{
			_pessoaRepositoryRead = pessoaRepositoryRead;
		}

		public override void Load()
		{
			Lista.Limpar();
			foreach (Rede redesTaxasCarto in _administradoraCartao.To<Juridica>().AdministradoraCartao.RedesTaxasCartoes)
			{
				if (redesTaxasCarto.IsCredito)
				{
					Lista.Adicionar(RedePosLocal.Criar().ComPessoa(_administradoraCartao).ComDescricao(redesTaxasCarto.Descricao)
						.ComOperacaoRedePos(OperacaoRedePos.Credito)
						.ComTaxas(redesTaxasCarto.Taxas.Where((Taxa x) => !x.Debito && !x.DebitoParcelado))
						.Build());
				}
				if (redesTaxasCarto.IsDebito)
				{
					Lista.Adicionar(RedePosLocal.Criar().ComPessoa(_administradoraCartao).ComDescricao(redesTaxasCarto.Descricao)
						.ComOperacaoRedePos(OperacaoRedePos.Debito)
						.ComTaxas(redesTaxasCarto.Taxas.Where((Taxa x) => x.Debito || x.DebitoParcelado))
						.Build());
				}
			}
			Lista.PosicionarNoPrimeiro();
			Lista.SetarCabecalho(Cabecalho<CabecalhoRedePos>.Criar().ComValor(Valor));
			if (Lista.Numero <= 0)
			{
				DialogoFactory.MostrarDialogoConfirma("Nenhuma Rede encontrada.");
				Seletor.Voltar();
			}
		}

		public override void EnterMethod()
		{
			Seletor.Fechar();
			PainelBuscaTaxas painelBuscaTaxas = Seletor.Get<PainelBuscaTaxas>();
			painelBuscaTaxas.ComRedePosLocal(Lista.ItemSelecionado);
			painelBuscaTaxas.ComCallback(Callback);
			Seletor.Selecionar<PainelBuscaTaxas>();
		}

		private void Callback()
		{
			if (_isMesaContaCreditoCliente)
			{
				_isMesaContaCreditoCliente = false;
				PainelTotalizacaoBase painelTotalizacaoBase = Seletor.Get<PainelTotalizacaoEmissorBase>();
				if (painelTotalizacaoBase.IsNull())
				{
					painelTotalizacaoBase = Seletor.Get<PainelTotalizacaoNotaManual>();
				}
				if (painelTotalizacaoBase.EmissorService.IsExactlyObject<NfceService>() || painelTotalizacaoBase.EmissorService.IsExactlyObject<PafNfceService>() || painelTotalizacaoBase.EmissorService.IsExactlyObject<MFePontoVendaService>())
				{
					Seletor.Selecionar<PainelRegistroAutorizacaoPagamentoPos, PainelAdicionarMesaContaCreditoCliente>();
					if (Lista.ItemSelecionado.CodigoAutorizacao.IsNotNull())
					{
						Seletor.Get<PainelAdicionarMesaContaCreditoCliente>().FinalizarPagamentoCartaoPos(Lista.ItemSelecionado);
						Lista.ItemSelecionado.SomarValor(Valor);
					}
				}
				else
				{
					Seletor.Get<PainelAdicionarMesaContaCreditoCliente>().FinalizarPagamentoCartaoPos(Lista.ItemSelecionado);
				}
			}
			else if (!_isRecebimento)
			{
				PainelTotalizacaoBase painelTotalizacaoBase2 = Seletor.Get<PainelTotalizacaoEmissorBase>();
				if (painelTotalizacaoBase2.IsNull())
				{
					painelTotalizacaoBase2 = Seletor.Get<PainelTotalizacaoNotaManual>();
				}
				ICartaoPos cartaoPos = painelTotalizacaoBase2.Lista.Itens.FirstOrDefault((ItemPagamentoViewModel x) => x.EspeciePagamento.Codigo == 7) as ICartaoPos;
				if (painelTotalizacaoBase2.EmissorService.IsExactlyObject<NfceService>() || painelTotalizacaoBase2.EmissorService.IsExactlyObject<PafNfceService>() || painelTotalizacaoBase2.EmissorService.IsExactlyObject<MFePontoVendaService>())
				{
					Seletor.Selecionar<PainelRegistroAutorizacaoPagamentoPos, PainelTotalizacaoBase>();
					if (Lista.ItemSelecionado.CodigoAutorizacao.IsNotNull())
					{
						cartaoPos?.Adicionar(Lista.ItemSelecionado);
					}
				}
				else
				{
					cartaoPos?.Adicionar(Lista.ItemSelecionado);
				}
			}
			else
			{
				DigisatServer.Domain.Main.Aggregates.CadastrosAgg.Pessoas.Pessoa pessoa = RetornarAdministradoraCartao(Lista.ItemSelecionado.Rede);
				Seletor.Get<PainelRecebimento>().FinalizarPagamentoCartao(InformacaoTransacaoTef.Criar().ComRede(Lista.ItemSelecionado.Rede).ComDebito(Lista.ItemSelecionado.Debito)
					.ComCodigoAutorizacaoTransacao(Lista.ItemSelecionado.CodigoAutorizacaoTransacao)
					.ComAdministradoraCartao(pessoa)
					.ComNumeroParcelas(Lista.ItemSelecionado.Taxa.To<DigisatServer.Domain.Main.Aggregates.CadastrosAgg.Pessoas.Juridicas.Credito>()?.NumeroParcelas ?? 0)
					.ComTaxa(Lista.ItemSelecionado.Taxa)
					.ComIsCartaoPos(isCartaoPos: true)
					.Build());
			}
		}

		private DigisatServer.Domain.Main.Aggregates.CadastrosAgg.Pessoas.Pessoa RetornarAdministradoraCartao(string rede)
		{
			IEnumerable<DigisatServer.Domain.Main.Aggregates.CadastrosAgg.Pessoas.Pessoa> source = _pessoaRepositoryRead.Find(EntitySpecification<DigisatServer.Domain.Main.Aggregates.CadastrosAgg.Pessoas.Pessoa>.Ativo().AdministradoraCartao());
			DigisatServer.Domain.Main.Aggregates.CadastrosAgg.Pessoas.Pessoa pessoa = null;
			if (source.Count() > 1)
			{
				pessoa = source.FirstOrDefault((DigisatServer.Domain.Main.Aggregates.CadastrosAgg.Pessoas.Pessoa x) => ((Juridica)x).AdministradoraCartao.Redes.Contains(rede.ToUpper()));
			}
			return pessoa ?? source.LastOrDefault();
		}

		public override bool PodeVoltar()
		{
			return true;
		}

		public void SetarValor(decimal valor)
		{
			Valor = valor;
		}

		public void SetarIsRecebimento(bool isRecebimento = false)
		{
			_isRecebimento = isRecebimento;
		}

		public void SetarMesaContaCreditoCliente(bool isMesaContaCreditoCliente = false)
		{
			_isMesaContaCreditoCliente = isMesaContaCreditoCliente;
		}

		public void SetarAdministradoraCartao(DigisatServer.Domain.Main.Aggregates.CadastrosAgg.Pessoas.Pessoa administradoraCartao)
		{
			_administradoraCartao = administradoraCartao;
		}
	}
	public abstract class PainelBuscaBase<TClass, TItem, TInformacao> : PainelInformacao<TClass, TItem, TInformacao> where TClass : class, new() where TItem : class where TInformacao : InformacaoBusca<TItem, TItem>, IInformacao
	{
		public abstract string Titulo { get; }

		public bool Pesquisou
		{
			get
			{
				return GetProperty(() => Pesquisou);
			}
			set
			{
				SetProperty(() => Pesquisou, value);
			}
		}

		protected PainelBuscaBase()
		{
		}

		protected PainelBuscaBase(Seletor<IPainel> seletor)
			: base(seletor)
		{
			Informacao.PesquisouEvent += InformacaoOnPesquisouEvent;
			Informacao.LimpouEvent += InformacaoOnLimpouEvent;
			Lista.AlterouItemSelecionadoEvent += ListaOnAlterouItemSelecionadoEvent;
		}

		protected virtual void InformacaoOnPesquisouEvent(object sender, IEnumerable<TItem> lista)
		{
			Lista.Limpar();
			Lista.Adicionar(lista);
			Lista.PosicionarNoPrimeiro();
			Pesquisou = true;
		}

		private void InformacaoOnLimpouEvent(object sender, EventArgs eventArgs)
		{
			Lista.Limpar();
			Pesquisou = false;
		}

		public override void Load()
		{
			Lista.Limpar();
			base.Limpar();
		}

		protected override void Limpar()
		{
			Lista.Limpar();
			base.Limpar();
		}

		public override bool PodeVoltar()
		{
			return true;
		}

		public override void Dispose()
		{
			Informacao.PesquisouEvent -= InformacaoOnPesquisouEvent;
			Informacao.LimpouEvent -= InformacaoOnLimpouEvent;
			base.Dispose();
		}
	}
	public class PainelBuscaConsumidor : PainelBuscaBase<PainelBuscaConsumidor, ConsumidorLocal, InformacaoBuscaConsumidor>, IAtalhos, IPainelBusca, IPainelBuscaConsumidorService<ConsumidorLocal>, IPainelBuscaService<ConsumidorLocal>, IPainelLista<ConsumidorLocal>, IItemMenuRibbon, ITitulo, IMenuRibbon
	{
		public bool PdvEstadoOffline;

		public IWService Service { get; protected set; }

		public ISessaoService SessaoService { get; protected set; }

		public IPessoaRepositoryRead PessoaRepositoryRead { get; protected set; }

		public override string Titulo => "Buscar consumidor";

		public bool ObrigatorioIndicarConsumidor { get; set; }

		public ICommand F3Command { get; protected set; }

		public IEnumerable<ItemMenuAtalho> MenuRibbon => new List<ItemMenuAtalho>
		{
			new ItemMenuAtalho("F3", "Indicar consumidor", F3Command)
		};

		public IReadOnlyCollection<string> Atalhos => new List<string> { "[ Enter ] Selecionar o consumidor" };

		public KeyGestureCustom Key => new KeyGestureControl(System.Windows.Input.Key.F3);

		public string ToolTip => "Buscar consumidor cadastrado";

		public PainelBuscaConsumidor()
		{
		}

		public PainelBuscaConsumidor(IEmissorService emissorService, IWService service, ISessaoService sessaoService, IPessoaRepositoryRead pessoaRepositoryRead, Seletor<IPainel> seletor)
			: base(seletor)
		{
			emissorService.To<NfceService>()?.WhenPdvOfflineEventEvent.Subscribe((bool x) =>
			{
				PdvEstadoOffline = x;
			});
			Service = service;
			SessaoService = sessaoService;
			PessoaRepositoryRead = pessoaRepositoryRead;
			F3Command = new DelegateCommand(AbrirIndicaConsumidor, PodeAbrirIndicaConsumidor);
			Lista.SetarCabecalho(Cabecalho<CabecalhoConsumidor>.Criar());
		}

		public override void EnterMethod()
		{
			if (!Lista.PossuiItemSelecionado)
			{
				return;
			}
			if (!PdvEstadoOffline)
			{
				Lista.ItemSelecionado.AtualizarClienteDto();
			}
			else
			{
				DialogoFactory.MostrarDialogoConfirma("Atenção! Não foi possível atualizar saldo do cliente. Verifique a conexão com o servidor!", bloquearEnter: true);
			}
			if (Lista.ItemSelecionado.Pessoa.Segmentacao.IsNotNull() && Lista.ItemSelecionado.Pessoa.Segmentacao.IsNot<SegmentacaoDtoNull>() && Lista.ItemSelecionado.Pessoa.Segmentacao.AlertarOperadorAoIndicarNaMovimentacao)
			{
				DialogoFactory.MostrarDialogoConfirma($"Você está indicando uma pessoa que possui segmentação:\n{Lista.ItemSelecionado.Pessoa.Segmentacao.SegmentacaoToText}", bloquearEnter: false, System.Windows.HorizontalAlignment.Left);
			}
			if (Lista.ItemSelecionado.PossuiValorEmAtraso)
			{
				if (DadosSistema.ConfiguracaoDto.Saida.AlertarClienteInadimplente.Valor && DialogoFactory.MostrarDialogoConfirmaInformacaoOculta(Lista.ItemSelecionado.AvisoValorEmAtraso, "Situação 1. Verifique!") != MessageBoxResult.OK)
				{
					return;
				}
				AutorizacaoDto autorizacaoDto = SessaoService.VerificarPermissao<DigisatServer.Infrastructure.Crosscutting.Module.PontoDeVenda, PermitirVenderParaInadimplente>();
				if (autorizacaoDto == null)
				{
					return;
				}
				Seletor.Get<PainelDocumentoFiscal>()?.PreDocumentoFiscal?.AdicionarAutorizacao(autorizacaoDto);
			}
			Seletor.Get<PainelDocumentoFiscal>().IndicarConsumidor(Lista.ItemSelecionado);
			Seletor.VoltarEnquanto<IPainelBusca>();
		}

		public override void FecharMethod()
		{
			Seletor.Get<PainelDocumentoFiscal>().IndicarConsumidor(null);
			base.FecharMethod();
		}

		protected override void Limpar()
		{
			ObrigatorioIndicarConsumidor = false;
			base.Limpar();
		}

		public override bool PodeVoltar()
		{
			return !ObrigatorioIndicarConsumidor;
		}

		private void AbrirIndicaConsumidor()
		{
			Seletor.Selecionar<PainelIndicaConsumidor>();
		}

		private bool PodeAbrirIndicaConsumidor()
		{
			return true;
		}

		public override void UnLoad()
		{
			Informacao.Limpar();
			base.UnLoad();
		}
	}
	public class PainelBuscaConsumidorRecebimento : PainelBuscaConsumidorGenerico<PainelBuscaRecebimento>
	{
		public PainelBuscaConsumidorRecebimento()
