		}

		public PainelBuscaConsumidorRecebimento(IEmissorService emissorService, IWService service, IPessoaRepositoryRead pessoaRepositoryRead, Seletor<IPainel> seletor)
			: base(emissorService, service, pessoaRepositoryRead, seletor)
		{
