	public class PainelBuscaProdutoServico : PainelBuscaBase<PainelBuscaProdutoServico, ProdutoServicoLocal, InformacaoBuscaProdutoServico>, IItemMenuRibbon, ITitulo
	{
		private readonly IEventPublisher _eventPublisher;

		public ISessaoService SessaoService { get; protected set; }

		public IProdutoServicoEmpresaRepositoryRead ProdutoServicoEmpresaRepositoryRead { get; protected set; }

		public IReadOnlyCollection<string> Atalhos => new List<string> { "[ Enter ] Selecionar o produto/serviço" };

		public override string Titulo => "Buscar produtos/serviços";

		public KeyGestureCustom Key => new KeyGestureCustom(System.Windows.Input.Key.F7);

		public string ToolTip => Titulo;

		public PainelBuscaProdutoServico()
		{
		}

		public PainelBuscaProdutoServico(ISessaoService sessaoService, IProdutoServicoEmpresaRepositoryRead produtoServicoEmpresaRepositoryRead, Seletor<IPainel> seletor, IEventPublisher eventPublisher)
			: base(seletor)
		{
			_eventPublisher = eventPublisher;
			SessaoService = sessaoService;
			ProdutoServicoEmpresaRepositoryRead = produtoServicoEmpresaRepositoryRead;
			Lista.SetarCabecalho(Cabecalho<CabecalhoProdutoServico>.Criar());
		}

		protected override void ListaOnAlterouItemSelecionadoEvent(object sender, ProdutoServicoLocal produtoServicoLocal)
		{
			base.ListaOnAlterouItemSelecionadoEvent(sender, produtoServicoLocal);
			_eventPublisher.Publish(new SelecionouItemDocumentoFiscalProdutoEvent((!produtoServicoLocal.Is<ProdutoLocal>()) ? produtoServicoLocal.To<ServicoLocal>()?.Imagem : produtoServicoLocal.To<ProdutoLocal>()?.Imagem));
		}

		public override void EnterMethod()
		{
			if (Lista.PossuiItemSelecionado && Informacao.HabilitaEnter && SessaoService.VerificarPermissao<DigisatServer.Infrastructure.Crosscutting.Module.PontoDeVenda, PermitirVendaDeItemAtravesDaPesquisa>() != null)
			{
				Seletor.VoltarTudo();
				Lista.ItemSelecionado?.Vender(Seletor.Get<PainelDocumentoFiscal>().Informacao.Quantidade);
				Seletor.Get<PainelDocumentoFiscal>().Informacao.LimparInformacao();
			}
		}

		public override void UnLoad()
		{
			_eventPublisher.Publish(new LimparImagemEvent());
			base.UnLoad();
		}
	}
	public class PainelBuscaRecebimento : PainelInteracao<PainelBuscaRecebimento>, IPainelIndicaConsumidor
	{
		private readonly InteracaoComando<string> _interacaoReferencia;

		private readonly InteracaoComando<ConsumidorLocal> _interacaoCliente;

		private readonly ItemInteracaoListaRecebimento _itemListaRecebimento;

		private readonly ItemInteracaoComboBox _comboBoxOrigemBusca;

		private readonly ItemInteracaoTextBlock _total;

		public ConsumidorLocal Consumidor
		{
			get
			{
				return GetProperty(() => Consumidor);
			}
			protected set
			{
				SetProperty(() => Consumidor, value);
			}
		}

		public override string DescricaoDoBotao => "Receber";

		public IWService Service { get; protected set; }

		public override string Titulo => "Busca de parcelas";

		public PainelBuscaRecebimento()
		{
		}

		public PainelBuscaRecebimento(IWService service, Seletor<IPainel> seletor)
			: base(seletor)
		{
			Service = service;
			_interacaoReferencia = InteracaoComando<string>.Criar().ComComando(new DelegateCommand(PesquisarPorReferencia, PodePesquisarPorReferencia)).Build();
			ItemInteracaoTextoComandoFocusable item = ItemInteracaoBase<ItemInteracaoTextoComandoFocusable, InteracaoComando<string>>.Criar().ComDescricao("Referência").ComValor(_interacaoReferencia)
				.ComGlyphKind(GlyphKind.Search)
				.Build();
			Lista<IItemInteracao> lista = new Lista<IItemInteracao>();
			lista.Adicionar(item);
			ItemInteracaoComboBox itemInteracaoComboBox = ItemInteracaoBase<ItemInteracaoComboBox, Lista<IItemInteracao>>.Criar().ComDescricao("Referência").ComValor(lista)
				.Build();
			_interacaoCliente = InteracaoComando<ConsumidorLocal>.Criar().ComComando(new DelegateCommand(PesquisarPorConsumidor)).Build();
			(from evt in WhenPropertyChanged
				where evt == "Consumidor"
				select Consumidor into consumidor
				where consumidor != null
				select consumidor).ObserveOn(SynchronizationContext.Current).Subscribe((ConsumidorLocal resultado) =>
			{
				_interacaoCliente.ComDado(resultado);
			});
			ItemInteracaoButtonEditConsumidorReadOnly item2 = ItemInteracaoBase<ItemInteracaoButtonEditConsumidorReadOnly, InteracaoComando<ConsumidorLocal>>.Criar().ComDescricao("Cliente").ComValor(_interacaoCliente)
				.Build();
			Lista<IItemInteracao> lista2 = new Lista<IItemInteracao>();
			lista2.Adicionar(item2);
			ItemInteracaoComboBox itemInteracaoComboBox2 = ItemInteracaoBase<ItemInteracaoComboBox, Lista<IItemInteracao>>.Criar().ComDescricao("Cliente").ComValor(lista2)
				.Build();
			Lista<IItemInteracao> lista3 = new Lista<IItemInteracao>();
			lista3.Adicionar(itemInteracaoComboBox2, itemInteracaoComboBox);
			lista3.WhenAlterouItemSelecionado.Subscribe((IItemInteracao x) =>
			{
				foreach (IItemInteracao campo in Campos)
				{
					campo.Limpar();
				}
			});
			_comboBoxOrigemBusca = ItemInteracaoBase<ItemInteracaoComboBox, Lista<IItemInteracao>>.Criar().ComDescricao("Buscar por").ComValor(lista3)
				.Build();
			_total = ItemInteracaoBase<ItemInteracaoTextBlock, string>.Criar().Build();
			_itemListaRecebimento = ItemInteracaoBase<ItemInteracaoListaRecebimento, Lista<Otus.Modulo.PontoDeVendas.ViewModels.ItensInteracao.Recebimento>>.Criar().ComDescricao("Parcelas em aberto").ComOrigemDaBusca(_comboBoxOrigemBusca)
				.ComTotalizacao(_total)
				.ComValor(new Lista<Otus.Modulo.PontoDeVendas.ViewModels.ItensInteracao.Recebimento>())
				.Build();
			Campos.Insert(0, _itemListaRecebimento);
		}

		private void PesquisarPorReferencia()
		{
			try
			{
				long.TryParse(_interacaoReferencia.Dado, out var referencia);
				RecebimentoDto recebimentoDto = Service.Canal((IRecebimentoModuleService service) => service.ObterPorReferencia(referencia));
				if (recebimentoDto != null && !recebimentoDto.Is<RecebimentoDtoNull>())
				{
					if (recebimentoDto.Situacao.PodeSerQuitada)
					{
						PessoaDto pessoa = recebimentoDto.Pessoa;
						Otus.Modulo.PontoDeVendas.ViewModels.ItensInteracao.Recebimento parcela = Otus.Modulo.PontoDeVendas.ViewModels.ItensInteracao.Recebimento.Criar().ComRecebimentoDto(recebimentoDto).Build()
							.Selecionar(valor: true);
						if (Consumidor == null)
						{
							Consumidor = ConsumidorLocal.Criar().ComPessoa(recebimentoDto.Pessoa).ComFuncAtualizarClienteDto(() => Service.Canal((IPessoaModuleService service) => service.ObterClienteDto(pessoa.Id.ToString())));
						}
						if (Consumidor.Id.ToString() == pessoa.Id && !_itemListaRecebimento.Valor.Existe((Otus.Modulo.PontoDeVendas.ViewModels.ItensInteracao.Recebimento x) => x.RecebimentoDto.Id == parcela.RecebimentoDto.Id))
						{
							_itemListaRecebimento.Valor.Adicionar(parcela);
						}
						else
						{
							DialogoFactory.MostrarDialogoConfirma("Parcela já consta na lista ou cliente diferente", bloquearEnter: true);
						}
					}
					else
					{
						DialogoFactory.MostrarDialogoConfirma("Parcela não pode ser quitada", bloquearEnter: true);
					}
				}
				else
				{
					DialogoFactory.MostrarDialogoConfirma("Nenhum registro localizado!", bloquearEnter: true);
				}
			}
			catch (Exception ex)
			{
				DialogoFactory.MostrarDialogoConfirma(ex.Message, bloquearEnter: true);
			}
			finally
			{
				_interacaoReferencia.Limpar(() => string.Empty);
				_interacaoReferencia.SetarFocoNoDado();
			}
		}

		private bool PodePesquisarPorReferencia()
		{
			return !string.IsNullOrEmpty(_interacaoReferencia.Dado);
		}

		private void PesquisarPorConsumidor()
		{
			Seletor.Selecionar<PainelBuscaConsumidorRecebimento>();
		}

		public void IndicarConsumidor(ConsumidorLocal consumidorLocal)
		{
			Consumidor = consumidorLocal;
			if (Consumidor == null)
			{
				return;
			}
			try
			{
				_itemListaRecebimento.Valor.Limpar();
				_itemListaRecebimento.SelecionarTodos = false;
				IEnumerable<RecebimentoDto> resultado = null;
				Service.Canal((IRecebimentoModuleService service) => resultado = service.ObterPendentesPontoDeVenda(Consumidor.Id.ToString()));
				resultado = resultado.OrderBy((RecebimentoDto x) => x.DataVencimento);
				foreach (RecebimentoDto item in resultado)
				{
					_itemListaRecebimento.Valor.Adicionar(Otus.Modulo.PontoDeVendas.ViewModels.ItensInteracao.Recebimento.Criar().ComRecebimentoDto(item).Build());
				}
				_itemListaRecebimento.Valor.PosicionarNoPrimeiro();
			}
			catch (Exception ex)
			{
				DialogoFactory.MostrarDialogoConfirma(ex.Message);
			}
		}

		public override void Load()
		{
		}

		public override void FecharMethod()
		{
			_interacaoCliente.ComDado(null);
			base.FecharMethod();
		}

		public override void UnLoad()
		{
			Consumidor = null;
		}

		public override bool PodeVoltar()
		{
			return true;
		}

		public override void Dispose()
		{
		}

		protected override void F2Method()
		{
			Seletor.Get<PainelRecebimento>().SetarConsumidor(_interacaoCliente?.Dado ?? Consumidor);
			Seletor.Selecionar<PainelRecebimento>();
		}

		protected override bool CanF2Method()
		{
			_total.ComValor($"Total: {_itemListaRecebimento.Valor.Itens.Where((Otus.Modulo.PontoDeVendas.ViewModels.ItensInteracao.Recebimento x) => x.Selecionado).Sum((Otus.Modulo.PontoDeVendas.ViewModels.ItensInteracao.Recebimento x) => x.RecebimentoDto.ValorTotal).FormatarCampoValor(2)}");
			if (_itemListaRecebimento?.Valor != null)
			{
				return _itemListaRecebimento.Valor.Itens.Any((Otus.Modulo.PontoDeVendas.ViewModels.ItensInteracao.Recebimento x) => x.Selecionado);
			}
			return false;
		}

		public PainelBuscaRecebimento ComService(IWService service)
		{
			Service = service;
			return this;
		}

		public override PainelBuscaRecebimento Build()
		{
			return new PainelBuscaRecebimento();
		}

		protected override void Limpar()
		{
			for (int i = 0; i < Campos.Count; i++)
			{
				Campos[i].Limpar();
			}
			_comboBoxOrigemBusca.Valor.PosicionarNoPrimeiro();
			_total.Limpar();
			Campos.RemoveIfExists(_total);
			base.Limpar();
		}
	}
	public class PainelBuscaRegistroVenda : PainelBuscaBase<PainelBuscaRegistroVenda, DocumentoFiscalEletronicoLocal, InformacaoBuscaRegistroVenda>, IPainelBusca, IItemMenuRibbon, ITitulo, IAtalhos
	{
		private readonly IImpressoraNaoFiscalService _impressoraNaoFiscalService;

		public IRegistroVendaService RegistroVendaService { get; protected set; }

		public override string Titulo => "Abrir Registro de venda";

		public CustomDelegateCommand DelCommand { get; set; }

		public CustomDelegateCommand CtrlPCommand { get; set; }

		public CustomDelegateCommand CtrlICommand { get; set; }

		public KeyGestureCustom Key => new KeyGestureCustom(System.Windows.Input.Key.F9);

		public string ToolTip => Titulo;

		public IEnumerable<ItemMenuAtalho> MenuRibbon => new List<ItemMenuAtalho>
		{
			new ItemMenuAtalho(DelCommand.KeyGesture.Descricao, "Cancelar", DelCommand, "Cancelar o Registro de venda"),
			new ItemMenuAtalho(CtrlPCommand.KeyGesture.Descricao, "Imprimir", CtrlPCommand, "Imprimir o Registro de venda"),
			new ItemMenuAtalho(CtrlICommand.KeyGesture.Descricao, "Imprimir ticket de troca", CtrlICommand, "Imprimir ticket de troca com dados do registro de venda original")
		};

		public IReadOnlyCollection<string> Atalhos => new List<string>();

		public PainelBuscaRegistroVenda()
		{
		}

		public PainelBuscaRegistroVenda(IRegistroVendaService emissorService, Seletor<IPainel> seletor, IImpressoraNaoFiscalService impressoraNaoFiscalService)
			: base(seletor)
		{
			_impressoraNaoFiscalService = impressoraNaoFiscalService;
			RegistroVendaService = emissorService;
			DelCommand = new CustomDelegateCommand(new KeyGestureCustom(System.Windows.Input.Key.Delete), Cancelar, PodeCancelar);
			CtrlPCommand = new CustomDelegateCommand(new KeyGestureControl(System.Windows.Input.Key.P), Imprimir, PodeImprimir);
			CtrlICommand = new CustomDelegateCommand(new KeyGestureControl(System.Windows.Input.Key.I), ImprimirTicketTroca, PodeImprimirTicketTroca);
			Lista.SetarCabecalho(Cabecalho<CabecalhoDocumentoFiscalEletronico>.Criar());
		}

		protected override void ListaOnAlterouItemSelecionadoEvent(object sender, DocumentoFiscalEletronicoLocal item)
		{
			base.ListaOnAlterouItemSelecionadoEvent(sender, item);
			RecuperarFoco();
		}

		private bool PodeCancelar()
		{
			if (Lista.PossuiItemSelecionado)
			{
				return Lista.ItemSelecionado.Movimentacao.Situacao.Codigo == 2;
			}
			return false;
		}

		private void Cancelar()
		{
			if (DialogoFactory.MostrarDialogoSimNao($"Cancelar Registro de venda número {Lista.ItemSelecionado.Movimentacao.Numero}?") == MessageBoxResult.Yes)
			{
				RegistroVendaService.Cancelar(Lista.ItemSelecionado.Movimentacao.Numero);
			}
			Limpar();
		}

		private bool PodeImprimir()
		{
			return Lista.PossuiItemSelecionado;
		}

		private void Imprimir()
		{
			RegistroVendaService.Imprimir(Lista.ItemSelecionado.Movimentacao.Numero);
			List<RecebimentoDto> list = Lista.ItemSelecionado.Movimentacao.PagamentosRecebimentos.OfType<RecebimentoDto>().Where((RecebimentoDto a) =>
			{
				if (!a.AVista)
				{
					EspeciePagamentoDto especiePagamento = a.EspeciePagamento;
					if (especiePagamento == null)
					{
						return false;
					}
					return especiePagamento.Codigo == 3;
				}
				return false;
			}).ToListEmptyWhenNull();
			if (list != null && list.Any())
			{
				DadosConsumidorRelatorioCarne consumidor = DadosConsumidorRelatorioCarne.Criar().ComNome(Lista.ItemSelecionado.Movimentacao.Pessoa.Nome).ComCpfCnpjFormatado(Lista.ItemSelecionado.Movimentacao.Pessoa.CpfCnpjFormatado)
					.ComEnderecoToText(Lista.ItemSelecionado.Movimentacao.Pessoa.EnderecoPrincipal.ToText);
				List<DadosParcelaRelatorioCarne> parcelas = list.Select((RecebimentoDto x) => DadosParcelaRelatorioCarne.Criar().ComOrdem(x.Ordem).ComVencimento(x.DataVencimento)
					.ComValor(x.Valor)
					.ComReferencia(x.Referencia)).ToListEmptyWhenNull();
				ImprimirCarneVendaPrazo(RelatoriosEmissor.RetornarDadosRelatorioCarne(Lista.ItemSelecionado.Movimentacao.Numero, Lista.ItemSelecionado.Movimentacao.DataHoraEmissao, consumidor, parcelas));
			}
		}

		private void ImprimirCarneVendaPrazo(DadosRelatorioCarne40Colunas dadosRelatorio)
		{
			if (dadosRelatorio == null)
			{
				return;
			}
			if (DadosSistema.TamanhoBobina == TamanhoBobina.CinquentaESeisCinquentaESeteCinquentaEOitoMilimetros)
			{
				if (DadosSistema.ConfiguracaoDto.Saida.ImprimirViaEstabelecimentoCarneVendaPrazo.Valor)
				{
					ParcelamentoViaEstabelecimento56Mm57Mm58Mm relatorio = new ParcelamentoViaEstabelecimento56Mm57Mm58Mm(DadosSistema.RollPaper, DadosSistema.MargemEsquerdaImpressoraNaoFiscal)
					{
						Parametros = new Parametros
						{
							Objeto = dadosRelatorio
						}
					};
					_impressoraNaoFiscalService.Imprimir((IRelatorio)relatorio);
				}
				if (DadosSistema.ConfiguracaoDto.Saida.ImprimirCarneVendaPrazo.Valor)
				{
					ParcelamentoViaCliente56Mm57Mm58Mm relatorio2 = new ParcelamentoViaCliente56Mm57Mm58Mm(DadosSistema.RollPaper, DadosSistema.MargemEsquerdaImpressoraNaoFiscal)
					{
						Parametros = new Parametros
						{
							Objeto = dadosRelatorio
						}
					};
					_impressoraNaoFiscalService.Imprimir((IRelatorio)relatorio2);
				}
			}
			else
			{
				if (DadosSistema.ConfiguracaoDto.Saida.ImprimirViaEstabelecimentoCarneVendaPrazo.Valor)
				{
					ParcelamentoViaEstabelecimento79Mm80Mm relatorio3 = new ParcelamentoViaEstabelecimento79Mm80Mm(DadosSistema.RollPaper, DadosSistema.MargemEsquerdaImpressoraNaoFiscal)
					{
						Parametros = new Parametros
						{
							Objeto = dadosRelatorio
						}
					};
					_impressoraNaoFiscalService.Imprimir((IRelatorio)relatorio3);
				}
				if (DadosSistema.ConfiguracaoDto.Saida.ImprimirCarneVendaPrazo.Valor)
				{
					ParcelamentoViaCliente79Mm80Mm relatorio4 = new ParcelamentoViaCliente79Mm80Mm(DadosSistema.RollPaper, DadosSistema.MargemEsquerdaImpressoraNaoFiscal)
					{
						Parametros = new Parametros
						{
							Objeto = dadosRelatorio
						}
					};
					_impressoraNaoFiscalService.Imprimir((IRelatorio)relatorio4);
				}
			}
		}

		private bool PodeImprimirTicketTroca()
		{
			if (Lista.PossuiItemSelecionado)
			{
				return Lista.ItemSelecionado.Movimentacao.Situacao.Codigo == 2;
			}
			return false;
		}

		private void ImprimirTicketTroca()
		{
			try
			{
				MovimentacaoDto movimentacao = Lista.ItemSelecionado.Movimentacao;
				IRelatorio relatorio2;
				if (DadosSistema.TamanhoBobina != TamanhoBobina.CinquentaESeisCinquentaESeteCinquentaEOitoMilimetros)
				{
					IRelatorio relatorio = new RelatorioTicketTroca79Mm80Mm(movimentacao, DadosSistema.MargemEsquerdaImpressoraNaoFiscal, DadosSistema.RollPaper);
					relatorio2 = relatorio;
				}
				else
				{
					IRelatorio relatorio = new RelatorioTicketTroca56Mm57Mm58Mm(movimentacao, DadosSistema.MargemEsquerdaImpressoraNaoFiscal, DadosSistema.RollPaper);
					relatorio2 = relatorio;
				}
				IRelatorio relatorio3 = relatorio2;
				_impressoraNaoFiscalService.Imprimir(relatorio3);
			}
			catch (Exception ex)
			{
				ex.ShowLastException();
			}
			finally
			{
				Limpar();
			}
		}

		public override void EnterMethod()
		{
		}

		public override void Load()
		{
			base.Load();
			if (DadosSistema.CarregarQuantidadeRegistrosBuscaMovimentacao)
			{
				Informacao.PesquisarUltimosRegistros(DadosSistema.QuantidadeRegistrosCarregarBuscaMovimentacoes);
			}
		}
	}
	public class PainelBuscaTabelaPreco : PainelListaBase<PainelBuscaTabelaPreco, TabelaPrecoLocal>, IAtalhos, IPainelBusca, IItemMenuRibbon, ITitulo
	{
		private readonly ITabelaPrecoRepositoryRead _tabelaPrecoRepositoryRead;

		private ObjectId _idTabelaPreco;

		public string Titulo => "Tabela de preço";

		public IReadOnlyCollection<string> Atalhos => new List<string> { "[ Enter ] Selecionar tabela de preço" };

		public KeyGestureCustom Key => new KeyGestureControl(System.Windows.Input.Key.T);

		public string ToolTip => "Indicação da tabela de preço a ser praticada";

		public PainelBuscaTabelaPreco()
		{
		}

		public PainelBuscaTabelaPreco(IEventPublisher eventPublisher, ITabelaPrecoRepositoryRead tabelaPrecoRepositoryRead, ISessaoService sessaoService, Seletor<IPainel> seletor)
			: base(seletor)
		{
			_tabelaPrecoRepositoryRead = tabelaPrecoRepositoryRead;
			ObjectId.TryParse(sessaoService.Sessao.Perfis.ItemSelecionado.Configuracao.TabelaPrecoPadraoReferencia, out _idTabelaPreco);
			PreencherTabelasPreco(_idTabelaPreco);
			eventPublisher.GetEvent((ConfiguracaoDto x) =>
			{
				ObjectId.TryParse(x.Saida.TabelaPrecoPadrao.Referencia, out _idTabelaPreco);
				PreencherTabelasPreco(_idTabelaPreco);
			});
		}

		private void PreencherTabelasPreco(ObjectId tabelaPrecoPosicionada)
		{
			Lista.Limpar();
			Lista.Adicionar(TabelaPrecoLocal.Criar().ComNenhuma());
			IEnumerable<DigisatServer.Domain.Main.Aggregates.CadastrosAgg.TabelasPreco.TabelaPreco> source = _tabelaPrecoRepositoryRead.Find(EntitySpecification<DigisatServer.Domain.Main.Aggregates.CadastrosAgg.TabelasPreco.TabelaPreco>.Ativo());
			Lista.Adicionar(source.Select((DigisatServer.Domain.Main.Aggregates.CadastrosAgg.TabelasPreco.TabelaPreco x) => TabelaPrecoLocal.Criar().ComId(x.Id).ComDescricao(x.Descricao)
				.ComPercentualComisao(x.PercentualComissao)
				.ComTabelaPrecoDto(x.ProjectedAsDto())));
			if (tabelaPrecoPosicionada.IsDefaultOrEmpty())
			{
				Lista.PosicionarNoPrimeiro();
				return;
			}
			Lista.Posicionar((TabelaPrecoLocal x) => x.Id.Equals(tabelaPrecoPosicionada));
			Seletor.Get<PainelDocumentoFiscal>().IndicarTabelaPreco(Lista.ItemSelecionado);
		}

		public override void Load()
		{
			ObjectId id = Lista.ItemSelecionado.Id;
			PreencherTabelasPreco(id);
		}

		public override void EnterMethod()
		{
			if (Lista.PossuiItemSelecionado)
			{
				Seletor.Get<PainelDocumentoFiscal>().IndicarTabelaPreco(Lista.ItemSelecionado, solicitarRecalculo: true);
				Seletor.VoltarEnquanto<IPainelBusca>();
			}
		}

