	public class PainelBuscaTicket : PainelInteracao<PainelBuscaTicket>
	{
		private readonly Seletor<IPainel> _seletor;

		private readonly InteracaoComando<string> _interacaoReferenciaTicket;

		private ItemInteracaoTextBlock _referencia;

		private ItemInteracaoTextBlock _descricao;

		private ItemInteracaoTextBlock _detalhe;

		private TicketDto _resultado;

		public IWService Service { get; set; }

		public override string Titulo => "Aplicar ticket";

		public PainelBuscaTicket()
		{
		}

		public PainelBuscaTicket(IWService service, Seletor<IPainel> seletor)
			: base(seletor)
		{
			_seletor = seletor;
			Service = service;
			_interacaoReferenciaTicket = InteracaoComando<string>.Criar().ComComando(new DelegateCommand(PesquisarTicket, PodePesquisarPorTicket)).Build();
			ItemInteracaoTextoComandoFocusable item = ItemInteracaoBase<ItemInteracaoTextoComandoFocusable, InteracaoComando<string>>.Criar().ComDescricao("Ticket").ComValor(_interacaoReferenciaTicket)
				.ComGlyphKind(GlyphKind.Search)
				.Build();
			Campos.Insert(0, item);
		}

		private bool PodePesquisarPorTicket()
		{
			return !string.IsNullOrWhiteSpace(_interacaoReferenciaTicket.Dado);
		}

		private void PesquisarTicket()
		{
			Limpar();
			try
			{
				if (_interacaoReferenciaTicket.Dado.Contains("Referencia"))
				{
					DateTime dateTime = HelperQrCode.ObterValorCampo(_interacaoReferenciaTicket.Dado, "PeriodoVigenciaInicial").TryToDateTime();
					DateTime dateTime2 = HelperQrCode.ObterValorCampo(_interacaoReferenciaTicket.Dado, "PeriodoVigenciaFinal").TryToDateTime();
					if (!(DateTime.Now >= dateTime) || !(DateTime.Now <= dateTime2))
					{
						DialogoFactory.MostrarDialogoConfirma("Ticket fora da vigência");
						_resultado = null;
						return;
					}
					_resultado = DadosSistema.GetService().Canal((ITicketModuleService service) => service.ObterPorReferencia(HelperQrCode.ObterValorCampo(_interacaoReferenciaTicket.Dado, "Referencia")));
				}
				else
				{
					string referencia = $"TK{_interacaoReferenciaTicket.Dado.ApenasNumeros()}";
					_resultado = DadosSistema.GetService().Canal((ITicketModuleService service) => service.ObterPorReferencia(referencia));
					if (!_resultado.IsVigente)
					{
						DialogoFactory.MostrarDialogoConfirma("Ticket fora da vigência");
						_resultado = null;
						return;
					}
				}
				if (_resultado.IsExactlyObject<TicketDtoNull>())
				{
					DialogoFactory.MostrarDialogoConfirma("Ticket não localizado");
					_resultado = null;
					return;
				}
				if (!_resultado.Valido)
				{
					DialogoFactory.MostrarDialogoConfirma("Ticket inválido");
					_resultado = null;
					return;
				}
				_referencia = ItemInteracaoBase<ItemInteracaoTextBlock, string>.Criar().ComDescricao("Referência:").ComValor(_resultado.Referencia)
					.Build();
				Campos.Add(_referencia);
				_descricao = ItemInteracaoBase<ItemInteracaoTextBlock, string>.Criar().ComDescricao("Descrição:").ComValor(_resultado.Descricao)
					.Build();
				Campos.Add(_descricao);
				_detalhe = ItemInteracaoBase<ItemInteracaoTextBlock, string>.Criar().ComDescricao("Detalhe:").ComValor(_resultado.TicketDetalheToText)
					.Build();
				Campos.Add(_detalhe);
			}
			finally
			{
				_interacaoReferenciaTicket.Limpar(() => (string)null);
			}
		}

		public override void Load()
		{
		}

		public override void UnLoad()
		{
			Limpar();
		}

		protected override void Limpar()
		{
			_resultado = null;
			Campos.RemoveIfExists(_referencia);
			Campos.RemoveIfExists(_descricao);
			Campos.RemoveIfExists(_detalhe);
			base.Limpar();
		}

		public override bool PodeVoltar()
		{
			return true;
		}

		public override void Dispose()
		{
		}

		protected override void F2Method()
		{
			if (_resultado.IsNull())
			{
				_seletor.Voltar();
				return;
			}
			IList<string> tickets = Seletor.Get<PainelDocumentoFiscal>().PreDocumentoFiscal.Tickets;
			if (tickets != null && tickets.Any((string x) => x.Equals(_resultado.Referencia)))
			{
				DialogoFactory.MostrarDialogoConfirma("Ticket já utilizado nessa venda");
				_seletor.Voltar();
				return;
			}
			switch (_resultado.Tipo)
			{
			case TipoTicket.Consumo:
				DialogoFactory.MostrarDialogoConfirma("Esse tipo de ticket não pode ser aplicado");
				break;
			case TipoTicket.DescontoPercentualVenda:
				Seletor.Get<PainelTotalizacaoBase>().Informacao.Texto = $"{_resultado.Detalhe.Desconto}%";
				if (Seletor.Get<PainelTotalizacaoBase>().AplicarDesconto())
				{
					Seletor.Get<PainelDocumentoFiscal>().PreDocumentoFiscal.AdicionarTicket(_resultado.Referencia);
				}
				break;
			case TipoTicket.VinculadoClubePromocao:
			{
				AutorizacaoDto autorizacaoDto = DadosSistema.AutenticacaoService.Instancia.VerificarPermissao<DigisatServer.Infrastructure.Crosscutting.Module.PontoDeVenda, PermitirDescontoAcrescimo>();
				if (autorizacaoDto == null)
				{
					return;
				}
				Seletor.Get<PainelDocumentoFiscal>()?.PreDocumentoFiscal?.AdicionarAutorizacao(autorizacaoDto);
				IEnumerable<Otus.Modulo.PontoDeVendas.Aggregates.Scanntech.PromocaoScanntech> enumerable = Seletor.Get<PainelDocumentoFiscal>()?.PreDocumentoFiscal?.RetornarPromocoesScanntech();
				Seletor.Get<PainelDocumentoFiscal>()?.PreDocumentoFiscal?.ProcessarPromocoesScanntech(enumerable?.Where((Otus.Modulo.PontoDeVendas.Aggregates.Scanntech.PromocaoScanntech x) => x.Id.Equals(_resultado.Detalhe.PromocaoReferencia.TryParseReferencia())).ToListEmptyWhenNull());
				if (Seletor.Get<PainelDocumentoFiscal>()?.PreDocumentoFiscal?.Itens.Any((ItemDocumentoFiscal x) => x.AplicouPromocaoScanntech) ?? false)
				{
					Seletor.Get<PainelDocumentoFiscal>().PreDocumentoFiscal.AdicionarTicket(_resultado.Referencia);
				}
				break;
			}
			}
			_seletor.Voltar();
		}
	}
