	public class PainelBuscaValePresente : PainelBuscaBase<PainelBuscaValePresente, ValePresenteLocal, InformacaoBuscaValePresente>, IAtalhos, IPainelBusca, IPainelBuscaService<ValePresenteLocal>, IPainelLista<ValePresenteLocal>
	{
		private Action<ValePresenteDto> _callback;

		public override string Titulo => "Vales presente";

		public IReadOnlyCollection<string> Atalhos => new List<string> { "[ Enter ] Selecionar" };

		public IWService Service { get; }

		public PainelBuscaValePresente()
		{
		}

		public PainelBuscaValePresente(IWService service, Seletor<IPainel> seletor)
			: base(seletor)
		{
			Service = service;
		}

		public void SetarCallback(Action<ValePresenteDto> callback)
		{
			_callback = callback;
		}

		public override void EnterMethod()
		{
			try
			{
				if (Lista.IsNull() || !Lista.PossuiItemSelecionado)
				{
					Informacao.ExcecutarPesquisa(string.Empty);
				}
				else
				{
					SelecionarValePresente();
				}
			}
			catch (Exception ex)
			{
				ex.ShowLastException();
			}
		}

		private void SelecionarValePresente()
		{
			ValePresenteDto valePresente = Lista.ItemSelecionado.ValePresente;
			if (valePresente.Movimentacao.IsNot<ValePresenteMovimentacaoDtoNull>())
			{
				throw new Exception($"Este vale presente já foi utilizado:\n{valePresente.Movimentacao.MovimentacaoToText}");
			}
			if (valePresente.Quitacao.IsNot<ValePresenteQuitacaoDtoNull>())
			{
				throw new Exception($"Este vale presente já foi utilizado:\n{valePresente.Quitacao.DocumentoToText}");
			}
			if (valePresente.Cancelamento.IsNot<ValePresenteCancelamentoDtoNull>())
			{
				throw new Exception("Este vale presente foi cancelado.");
			}
			if (valePresente.Efetivacao.Is<ValePresenteEfetivacaoDtoNull>())
			{
				throw new Exception("Este vale presente não foi efetivado.");
			}
			_callback(valePresente);
			Seletor.Voltar();
		}
	}
	public class PainelBuscaVendaPausada : PainelListaBase<PreDocumentoFiscalPausadoLocal, PreDocumentoFiscalPausadoLocal>, IAtalhos, IPainelBusca, IItemMenuRibbon, ITitulo
	{
		private readonly IRepositoryRead<PreDocumentoFiscalPausado> _preDocumentoFiscalPausadoRepositoryRead;

		private readonly IRepositoryBaseWrite<PreDocumentoFiscalPausado> _preDocumentoFiscalPausadoRepositoryWrite;

		protected IRepositoryBaseWrite<PreDocumentoFiscal> _preDocumentoFiscalRepositoryWrite;

		private readonly ISessaoService _sessaoService;

		public string Titulo => "Vendas pausadas";

		public IReadOnlyCollection<string> Atalhos => new List<string> { "[ Enter ] Continuar venda" };

		public KeyGestureCustom Key => new KeyGestureControl(System.Windows.Input.Key.F9);

		public string ToolTip => "Continuar venda pausada";

		public CustomDelegateCommand DelCommand { get; set; }

		public IEnumerable<ItemMenuAtalho> MenuRibbon => new List<ItemMenuAtalho>
		{
			new ItemMenuAtalho(DelCommand.KeyGesture.Descricao, "Excluir", DelCommand, "Excluir venda pausada")
		};

		public PainelBuscaVendaPausada()
		{
		}

		public PainelBuscaVendaPausada(IRepositoryRead<PreDocumentoFiscalPausado> preDocumentoFiscalPausadoRepositoryRead, IRepositoryBaseWrite<PreDocumentoFiscal> preDocumentoFiscalRepositoryWrite, IRepositoryBaseWrite<PreDocumentoFiscalPausado> preDocumentoFiscalPausadoRepositoryWrite, Seletor<IPainel> seletor, ISessaoService sessaoService)
			: base(seletor)
		{
			_preDocumentoFiscalPausadoRepositoryRead = preDocumentoFiscalPausadoRepositoryRead;
			_preDocumentoFiscalRepositoryWrite = preDocumentoFiscalRepositoryWrite;
			_preDocumentoFiscalPausadoRepositoryWrite = preDocumentoFiscalPausadoRepositoryWrite;
			_sessaoService = sessaoService;
			DelCommand = new CustomDelegateCommand(new KeyGestureCustom(System.Windows.Input.Key.Delete), ExcluirVendaPausada, PodeExcluirVendaPausada);
		}

		private bool PodeExcluirVendaPausada()
		{
			return Lista.PossuiItemSelecionado;
		}

		private void ExcluirVendaPausada()
		{
			if (DialogoFactory.MostrarDialogoSimNao("Tem certeza que deseja excluir a venda posicionada?") == MessageBoxResult.Yes && !_sessaoService.VerificarPermissao<DigisatServer.Infrastructure.Crosscutting.Module.PontoDeVenda, PermitirCancelarDocumentoFiscal>().IsNull())
			{
				PreDocumentoFiscalPausado byId = _preDocumentoFiscalPausadoRepositoryRead.GetById(Lista.ItemSelecionado.Id);
				ExcluirVendaPausadaAposRecarregar(byId);
				PreencherVendasPausadas();
				RecuperarFoco();
			}
		}

		public override bool PodeEnterCommand()
		{
			return Lista.PossuiItemSelecionado;
		}

		public override void EnterMethod()
		{
			PreDocumentoFiscalPausado byId = _preDocumentoFiscalPausadoRepositoryRead.GetById(Lista.ItemSelecionado.Id);
			_preDocumentoFiscalRepositoryWrite.Update(byId.PreDocumentoFiscal);
			Seletor.Get<PainelDocumentoFiscal>().RecarregarPreDocumentoFiscal();
			ExcluirVendaPausadaAposRecarregar(byId);
			Seletor.VoltarEnquanto<IPainelBusca>();
		}

		private void ExcluirVendaPausadaAposRecarregar(PreDocumentoFiscalPausado preDocumentoFiscal)
		{
			_preDocumentoFiscalPausadoRepositoryWrite.Delete(preDocumentoFiscal);
		}

		public void ResetToDefault()
		{
			Lista.PosicionarNoPrimeiro();
		}

		public override void Load()
		{
			PreencherVendasPausadas();
		}

		private void PreencherVendasPausadas()
		{
			Lista.Limpar();
			List<PreDocumentoFiscalPausado> source = _preDocumentoFiscalPausadoRepositoryRead.Find(EntityBaseSpecification<PreDocumentoFiscalPausado>.All()).ToListEmptyWhenNull();
			Lista.Adicionar(from x in source
				where x.PreDocumentoFiscal.Empresa.Id.Equals(DadosSistema.EmpresaLogada.Id.TryParseReferencia())
				orderby x.DataInclusao descending
				select PreDocumentoFiscalPausadoLocal.Criar().ComId(x.Id).ComNomePessoa(x.PreDocumentoFiscal.Pessoa.Nome)
					.ComDataHora(x.PreDocumentoFiscal.DataInicioEmissao)
					.ComTotal(x.PreDocumentoFiscal.SubTotal));
			Lista.PosicionarNoPrimeiro();
		}

		public override bool PodeVoltar()
		{
			return true;
		}
	}
	public class PainelBuscaVendedor : PainelBuscaBase<PainelBuscaVendedor, VendedorLocal, InformacaoBuscaVendedor>, IAtalhos, IPainelBusca, IPainelBuscaService<VendedorLocal>, IPainelLista<VendedorLocal>, IItemMenuRibbon, ITitulo, IMenuRibbon
	{
		private readonly IPessoaRepositoryRead _pessoaRepositoryRead;

		public override string Titulo => "Buscar vendedor";

		public IReadOnlyCollection<string> Atalhos => new List<string> { "[ Enter ] Selecionar" };

		public KeyGestureCustom Key => new KeyGestureCustom(System.Windows.Input.Key.Home);

		public string ToolTip => Titulo;

		public IWService Service { get; protected set; }

		public IEnumerable<ItemMenuAtalho> MenuRibbon => new List<ItemMenuAtalho>();

		public PainelBuscaVendedor()
		{
		}

		public PainelBuscaVendedor(IWService service, Seletor<IPainel> seletor, IPessoaRepositoryRead pessoaRepositoryRead)
			: base(seletor)
		{
			Service = service;
			_pessoaRepositoryRead = pessoaRepositoryRead;
		}

		public override bool PodeVoltar()
		{
			return DadosSistema.VerificarPermissao<DigisatServer.Infrastructure.Crosscutting.Module.PontoDeVenda, PermitirIndicarGarcomNenhum>();
		}

		public override void Load()
		{
			base.Load();
			IEnumerable<DigisatServer.Domain.Main.Aggregates.CadastrosAgg.Pessoas.Pessoa> pessoas = _pessoaRepositoryRead.Find(PessoaSpecifications.Vendedores().PorAtivo());
			Informacao.CarregarVendedores(pessoas);
			DormirAsync(200, (object x) =>
			{
				Lista.PosicionarNoPrimeiro();
			});
		}

		public override void EnterMethod()
		{
			if (!Lista.PossuiItemSelecionado)
			{
				return;
			}
			if (!string.IsNullOrEmpty(Lista.ItemSelecionado.Pin))
			{
				while (true)
				{
					string informacao = string.Empty;
					if (DialogoFactory.MostrarDialogoEntradaString(ref informacao, "Informe o PIN", "Informe o PIN para confirmar a seleção", new DigisatServer.Infrastructure.Crosscutting.Icones.Informacao(), senha: true) == MessageBoxResult.OK)
					{
						if (informacao == null || !informacao.Equals(Lista.ItemSelecionado.Pin))
						{
							DialogoFactory.MostrarDialogoConfirma("PIN incorreto, tente novamente!");
							continue;
						}
						Seletor.Get<PainelDocumentoFiscal>().IndicarVendedor(Lista.ItemSelecionado);
						break;
					}
					if (DadosSistema.VerificarPermissao<DigisatServer.Infrastructure.Crosscutting.Module.PontoDeVenda, PermitirIndicarGarcomNenhum>())
					{
						break;
					}
					return;
				}
			}
			else if (Lista.ItemSelecionado.IsNenhum)
			{
				AutorizacaoDto autorizacaoDto = DadosSistema.AutenticacaoService.Instancia.VerificarPermissao<DigisatServer.Infrastructure.Crosscutting.Module.PontoDeVenda, PermitirIndicarGarcomNenhum>();
				if (autorizacaoDto == null)
				{
					return;
				}
				Seletor.Get<PainelDocumentoFiscal>()?.PreDocumentoFiscal?.AdicionarAutorizacao(autorizacaoDto);
				Seletor.Get<PainelDocumentoFiscal>().IndicarVendedor(Lista.ItemSelecionado);
			}
			else
			{
				Seletor.Get<PainelDocumentoFiscal>().IndicarVendedor(Lista.ItemSelecionado);
			}
			Seletor.VoltarEnquanto<IPainelBusca>();
		}
	}
