		{
			if (Lista.PossuiItemSelecionado)
			{
				if (_sessaoService.VerificarPermissao<DigisatServer.Infrastructure.Crosscutting.Module.PontoDeVenda, PermitirVendaDeItemAtravesDaPesquisa>() == null)
				{
					return;
				}
				Lista.ItemSelecionado.Vender(Seletor.Get<PainelDocumentoFiscal>().Informacao.Quantidade);
