			Lista.Adicionar(page.Lista.Select((ProdutoServicoEmpresa produtoServico) => FluentFactory<ProdutoServicoLocalFactory>.Init().ComCatalogo().ComPermissaoEstoqueNegativo(perfilEmpresa.Configuracao.PermitirEstoqueNegativo)
				.ComSeletor(Seletor)
				.ComProdutoServicoEmpresa(produtoServico.SetarTabelaPreco(idTabelaPreco))
				.Criar() as ProdutoServicoCatalogoLocal));
			Lista.PosicionarNoPrimeiro();
