		}

		public override void Dispose()
		{
			Lista.AlterouItemSelecionadoEvent -= ListaOnAlterouItemSelecionadoEvent;
			base.Dispose();
		}
	}
	public class PainelChamarSenha : PainelInteracao<PainelChamarSenha>, IItemMenuRibbon, ITitulo
	{
		private readonly InteracaoComando<string> _interacaoNumero;

		private readonly ItemInteracaoListaSenha _interacaoListaSenha;

		public IWService Service { get; set; }

		public override string Titulo => "Chamar senha";

		public KeyGestureCustom Key => new KeyGestureCustom(System.Windows.Input.Key.N, ModifierKeys.Control);

		public string ToolTip => Titulo;

		public ICommand DelCommand { get; protected set; }

		public PainelChamarSenha()
		{
		}

		public PainelChamarSenha(IWService service, Seletor<IPainel> seletor)
			: base(seletor)
		{
			Service = service;
			_interacaoNumero = InteracaoComando<string>.Criar().ComComando(new DelegateCommand(AdicionarNumero, PodePesquisarPorNumero)).Build();
			ItemInteracaoInteiroComandoFocusable item = ItemInteracaoBase<ItemInteracaoInteiroComandoFocusable, InteracaoComando<string>>.Criar().ComDescricao("Número").ComValor(_interacaoNumero)
				.ComGlyphKind(GlyphKind.Plus)
				.Build();
			_interacaoListaSenha = ItemInteracaoBase<ItemInteracaoListaSenha, Lista<Senha>>.Criar().ComDescricao("Senha(s) selecionada(s)").ComValor(new Lista<Senha>())
				.Build();
			Campos.Insert(0, item);
			Campos.Insert(1, _interacaoListaSenha);
			DelCommand = new DelegateCommand<object>(RemoverItem);
			F2Command = new DelegateCommand(F2Method, CanF2Method, false);
		}

		private bool PodePesquisarPorNumero()
		{
			return !string.IsNullOrWhiteSpace(_interacaoNumero.Dado);
		}

		private void AdicionarNumero()
		{
			try
			{
				long numero = _interacaoNumero.Dado.ApenasNumeros().ToLong();
				if (_interacaoListaSenha.Valor.Itens.Any((Senha a) => a.Numero.Equals(numero)))
				{
					return;
				}
				if (DadosSistema.ConfiguracaoDto.Saida.QuantidadePaineisSenha.Valor > 1)
				{
					List<KeyValuePair<int, string>> list = new List<KeyValuePair<int, string>>
					{
						new KeyValuePair<int, string>(0, "Todos")
					};
					for (int num = 1; num <= DadosSistema.ConfiguracaoDto.Saida.QuantidadePaineisSenha.Valor; num++)
					{
						list.Add(new KeyValuePair<int, string>(num, $"Painel {num}"));
					}
					KeyValuePair<int, string> keyValuePair = DialogoFactory.MostrarDialogoComboBox("Selecione o painel", "Painel de senha", list, "Value");
					if (keyValuePair.Key == 0)
					{
						_interacaoListaSenha.Valor.Adicionar(Documento<Senha>.Criar().ComNumero(numero).ComCommand(DelCommand)
							.Build());
					}
					else
					{
						_interacaoListaSenha.Valor.Adicionar(Documento<Senha>.Criar().ComNumero(numero).ComNumeroPainel(keyValuePair.Key)
							.ComCommand(DelCommand)
							.Build());
					}
				}
				else
				{
					_interacaoListaSenha.Valor.Adicionar(Documento<Senha>.Criar().ComNumero(numero).ComCommand(DelCommand)
						.Build());
				}
			}
			catch (Exception ex)
			{
				DialogoFactory.MostrarDialogoConfirma(ex.Message, bloquearEnter: true);
			}
			finally
			{
				_interacaoNumero.Limpar(() => string.Empty);
				_interacaoNumero.SetarFocoNoDado();
			}
		}

		private void RemoverItem(object item)
		{
			Senha item2 = (item as Senha) ?? _interacaoListaSenha.Valor.ItemSelecionado;
			_interacaoListaSenha.Valor.Remover(item2);
			Window mainWindow = System.Windows.Application.Current.MainWindow;
			TraversalRequest request = new TraversalRequest(FocusNavigationDirection.Next)
			{
				Wrapped = true
			};
			mainWindow.MoveFocus(request);
		}

		public override void Load()
		{
		}

		public override void UnLoad()
		{
			_interacaoListaSenha.Valor.Limpar();
		}

		public override bool PodeVoltar()
		{
			return true;
		}

		public override void Dispose()
		{
		}

		protected override void F2Method()
		{
			foreach (Senha iten in _interacaoListaSenha.Valor.Itens)
			{
				Chamar((iten.NumeroPainel > 0) ? new DigisatServer.Application.Main.Dto.Movimentacoes.SenhaDto
				{
					Valor = iten.Numero.ToStringOrEmpty(),
					NumeroPainel = iten.NumeroPainel
				} : new DigisatServer.Application.Main.Dto.Movimentacoes.SenhaDto
				{
					Valor = iten.Numero.ToStringOrEmpty()
				});
			}
			Seletor.Voltar();
		}

		private void Chamar(DigisatServer.Application.Main.Dto.Movimentacoes.SenhaDto senha)
		{
			DadosSistema.GetService().Canal((ISenhaModuleService service) =>
			{
				service.AdicionarAsync(senha, anunciar: true).ContinueWith((Task<DigisatServer.Application.Main.Dto.Movimentacoes.SenhaDto> task) =>
				{
					if (task.IsFaulted)
					{
						task.Exception.ShowLastException();
					}
				});
			});
		}
	}
	public class PainelCheque : PainelInteracao<PainelCheque>, IPainelIndicaConsumidor
	{
		private decimal _valorCheque;

		private readonly ItemInteracaoInteiroLimitado _banco;

		private readonly ItemInteracaoDataHora _dataPreDatado;

		private readonly ItemInteracaoInteiroLimitado _agencia;

		private readonly ItemInteracaoInteiroLimitado _conta;

		private readonly ItemInteracaoInteiroLimitado _numeroCheque;

		private ConsumidorLocal _consumidor;

		private readonly InteracaoComando<string> _interacaoCliente;

		private readonly ItemInteracaoCpf _campoCpf;

		private readonly ItemInteracaoCnpj _campoCnpj;

		private readonly ItemInteracaoTexto _observacao;

		public ConsumidorLocal Consumidor
		{
			get
			{
				return GetProperty(() => Consumidor);
			}
			protected set
			{
				SetProperty(() => Consumidor, value);
			}
		}

		public override string Titulo => "Dados do cheque";

		public PainelCheque()
		{
		}

		public PainelCheque(Seletor<IPainel> seletor)
			: base(seletor)
		{
			_interacaoCliente = InteracaoComando<string>.Criar().ComComando(new DelegateCommand(PesquisarPorConsumidor)).Build();
			_campoCpf = ItemInteracaoBase<ItemInteracaoCpf, Cpf>.Criar().ComDescricao("Cpf").Build();
			_campoCnpj = ItemInteracaoBase<ItemInteracaoCnpj, Cnpj>.Criar().ComDescricao("Cnpj").Build();
			(from evt in WhenPropertyChanged
				where evt == "Consumidor"
				select Consumidor into consumidor
				where consumidor != null
				select consumidor).ObserveOn(SynchronizationContext.Current).Subscribe((ConsumidorLocal resultado) =>
			{
				_interacaoCliente.ComDado(resultado.Nome);
				_campoCpf.Valor.SetarNumero(resultado.Documento);
				_campoCnpj.Valor.SetarNumero(resultado.Documento);
				_consumidor = resultado;
			});
			Campos.Add(ItemInteracaoBase<ItemInteracaoButtonEditConsumidor, InteracaoComando<string>>.Criar().ComDescricao("Cliente").ComValor(_interacaoCliente)
				.Build());
			Lista<IItemInteracao> lista = new Lista<IItemInteracao>();
			lista.Adicionar(_campoCpf);
			ItemInteracaoComboBox itemInteracaoComboBox = ItemInteracaoBase<ItemInteracaoComboBox, Lista<IItemInteracao>>.Criar().ComDescricao("Cpf").ComValor(lista)
				.Build();
			Lista<IItemInteracao> lista2 = new Lista<IItemInteracao>();
			lista2.Adicionar(_campoCnpj);
			ItemInteracaoComboBox itemInteracaoComboBox2 = ItemInteracaoBase<ItemInteracaoComboBox, Lista<IItemInteracao>>.Criar().ComDescricao("Cnpj").ComValor(lista2)
				.Build();
			Lista<IItemInteracao> lista3 = new Lista<IItemInteracao>();
			lista3.Adicionar(itemInteracaoComboBox, itemInteracaoComboBox2);
			Campos.Add(ItemInteracaoBase<ItemInteracaoComboBox, Lista<IItemInteracao>>.Criar().ComDescricao("Tipo documento").ComValor(lista3)
				.Build());
			_banco = ItemInteracaoBase<ItemInteracaoInteiroLimitado, long>.Criar().ComDescricao("Banco").ComTamanhoMaximo(4)
				.Build();
			Campos.Add(_banco);
			_agencia = ItemInteracaoBase<ItemInteracaoInteiroLimitado, long>.Criar().ComDescricao("Agência").ComTamanhoMaximo(5)
				.Build();
			Campos.Add(_agencia);
			_conta = ItemInteracaoBase<ItemInteracaoInteiroLimitado, long>.Criar().ComDescricao("Conta").ComTamanhoMaximo(12)
				.Build();
			Campos.Add(_conta);
			_numeroCheque = ItemInteracaoBase<ItemInteracaoInteiroLimitado, long>.Criar().ComDescricao("Número do cheque").ComTamanhoMaximo(8)
				.Build();
			Campos.Add(_numeroCheque);
			_dataPreDatado = ItemInteracaoBase<ItemInteracaoDataHora, DateTime>.Criar().ComDescricao("Pré datado").ComValor(DateTime.Now.Date)
				.Build();
			Campos.Add(_dataPreDatado);
			_observacao = ItemInteracaoBase<ItemInteracaoTexto, string>.Criar().ComDescricao("Observação").Build();
			Campos.Add(_observacao);
		}

		private void PesquisarPorConsumidor()
		{
			Seletor.Selecionar<PainelBuscaConsumidorCheque>();
		}

		public void IndicarConsumidor(ConsumidorLocal consumidorLocal)
		{
			Consumidor = consumidorLocal;
		}

		public override void Load()
		{
		}

		public override void UnLoad()
		{
		}

		protected override void Limpar()
		{
			_banco.Valor = 0L;
			_agencia.Valor = 0L;
			_conta.Valor = 0L;
			_numeroCheque.Valor = 0L;
			_dataPreDatado.Valor = DateTime.Now;
			Consumidor = ConsumidorLocal.Criar();
			_valorCheque = 0m;
			_observacao.Valor = string.Empty;
			base.Limpar();
		}

		public override bool PodeVoltar()
		{
			return true;
		}

		public override void Dispose()
		{
		}

		protected override void F2Method()
		{
			try
			{
				string documento = (string.IsNullOrEmpty(_campoCpf.Valor.Numero) ? _campoCnpj.Valor.Numero : _campoCpf.Valor.Numero);
				ChequeFactory chequeFactory = FluentFactory<ChequeFactory>.Init().SetarCodigoBanco(_banco.Valor).SetarAgencia(_agencia.Valor.ToString())
					.SetarConta(_conta.Valor.ToString())
					.SetarNumero(_numeroCheque.Valor.ToString())
					.SetarEmissao(DateTime.Today)
					.SetarPreDatado(_dataPreDatado.Valor)
					.SetarEmissorCheque(PessoaCheque.Criar(_interacaoCliente.Dado, documento))
					.SetarValor(_valorCheque)
					.SetarPessoaReferencia(PessoaChequeReferencia.Criar(_consumidor?.Pessoa))
					.SetarObservacao(_observacao.Valor);
				if (Seletor.Historico.OfType<PainelRecebimento>().Any())
				{
					ChequeDto cheque = chequeFactory.SetarEmpresaReferencia(PessoaChequeReferencia.Criar(DadosSistema.EmpresaLogada.Nome, DadosSistema.EmpresaLogada.CpfCnpj, ObjectId.Parse(DadosSistema.EmpresaLogada.Id))).Criar().ProjectedAsDto();
					Seletor.Get<PainelRecebimento>().SetarCheque(cheque);
				}
				else
				{
					Seletor.Get<PainelDocumentoFiscal>().PreDocumentoFiscal.SetarCheque(chequeFactory);
				}
				Seletor.Voltar();
				Limpar();
			}
			catch (Exception ex)
			{
				ex.ShowLastException();
			}
		}

		protected override bool CanF2Method()
		{
			if (_banco.Valor > 0 && _agencia.Valor > 0 && _conta.Valor > 0 && _numeroCheque.Valor > 0 && !string.IsNullOrEmpty(_interacaoCliente.Dado))
			{
				if (string.IsNullOrEmpty(_campoCpf.Valor.Numero))
				{
					return !string.IsNullOrEmpty(_campoCnpj.Valor.Numero);
				}
				return true;
			}
			return false;
		}

		public void SetarValorCheque(decimal valor)
		{
			_valorCheque = valor;
		}
	}
