	public class PainelConferencia : PainelInteracao<PainelConferencia>, IItemMenuRibbon, ITitulo
	{
		private readonly IEmissorService _emissorService;

		private readonly InteracaoComando<string> _interacaoNumero;

		private readonly ItemInteracaoListaMesaConta _interacaoListaMesaConta;

		public override string Titulo => $"Conferência de {DadosSistema.TipoRestaurante}";

		public KeyGestureCustom Key => new KeyGestureCustom(System.Windows.Input.Key.I, ModifierKeys.Control);

		public string ToolTip => $"Imprimir conferência de {DadosSistema.TipoRestaurante}";

		public ICommand DelCommand { get; protected set; }

		public PainelConferencia()
		{
		}

		public PainelConferencia(IEmissorService emissorService, Seletor<IPainel> seletor)
			: base(seletor)
		{
			_emissorService = emissorService;
			_interacaoNumero = InteracaoComando<string>.Criar().ComComando(new DelegateCommand(AdicionarNumero, PodePesquisarPorNumero)).Build();
			ItemInteracaoInteiroComandoFocusable item = ItemInteracaoBase<ItemInteracaoInteiroComandoFocusable, InteracaoComando<string>>.Criar().ComDescricao("Número").ComValor(_interacaoNumero)
				.ComGlyphKind(GlyphKind.Plus)
				.Build();
			_interacaoListaMesaConta = ItemInteracaoBase<ItemInteracaoListaMesaConta, Lista<MesaConta>>.Criar().ComDescricao($"{DadosSistema.TipoRestaurante}(s) selecionada(s)").ComValor(new Lista<MesaConta>())
				.Build();
			Campos.Insert(0, item);
			Campos.Insert(1, _interacaoListaMesaConta);
			DelCommand = new DelegateCommand<object>(RemoverItem);
			F2Command = new AsyncCommand(F2MethodAsync, CanF2Method, allowMultipleExecution: false);
		}

		private bool PodePesquisarPorNumero()
		{
			return !string.IsNullOrWhiteSpace(_interacaoNumero.Dado);
		}

		private void AdicionarNumero()
		{
			try
			{
				long numero = _interacaoNumero.Dado.ApenasNumeros().ToLong();
				if (!_interacaoListaMesaConta.Valor.Itens.Any((MesaConta a) => a.Numero.Equals(numero)))
				{
					_interacaoListaMesaConta.Valor.Adicionar(Documento<MesaConta>.Criar().ComNumero(numero).ComCommand(DelCommand)
						.Build());
				}
			}
			catch (Exception ex)
			{
				DialogoFactory.MostrarDialogoConfirma(ex.Message, bloquearEnter: true);
			}
			finally
			{
				_interacaoNumero.Limpar(() => string.Empty);
				_interacaoNumero.SetarFocoNoDado();
			}
		}

		private void RemoverItem(object item)
		{
			MesaConta item2 = (item as MesaConta) ?? _interacaoListaMesaConta.Valor.ItemSelecionado;
			_interacaoListaMesaConta.Valor.Remover(item2);
			Window mainWindow = System.Windows.Application.Current.MainWindow;
			TraversalRequest request = new TraversalRequest(FocusNavigationDirection.Next)
			{
				Wrapped = true
			};
			mainWindow.MoveFocus(request);
		}

		protected override bool CanF2Method()
		{
			return _interacaoListaMesaConta.Valor.Itens.Any();
		}

		private async Task F2MethodAsync()
		{
			foreach (MesaConta item in _interacaoListaMesaConta.Valor.Itens)
			{
				await Task.Factory.StartNew(() =>
				{
					_emissorService.ImprimirConferenciaMesaConta(item.Numero, mostrarPreview: false);
				});
			}
			_emissorService.ImprimirTotalizacaoConferenciaMesaConta(_interacaoListaMesaConta.Valor.Itens.Select((MesaConta x) => x.Numero), mostrarPreview: false);
			Seletor.Voltar();
		}

		protected override void F2Method()
		{
		}

		public override void Load()
		{
		}

		public override void UnLoad()
		{
			_interacaoListaMesaConta.Valor.Limpar();
		}

		public override bool PodeVoltar()
		{
			return true;
		}

		public override void Dispose()
		{
		}
	}
	public class PainelConvenio : PainelListaBase<PainelConvenio, ConvenioLocal>, IAtalhos
	{
		public IWService Service { get; protected set; }

		public string Titulo => "Consulta de convênios";

		public IReadOnlyCollection<string> Atalhos => new List<string> { "[ Enter ] Selecionar o convênio" };

		public PainelConvenio()
		{
		}

		public PainelConvenio(IWService service, Seletor<IPainel> seletor)
			: base(seletor)
		{
			Service = service;
		}

		public override void Load()
		{
			PesquisaDto objetoPesquisaConvenios = new PesquisaDto
			{
				Informacao = new PesquisaPessoaDto
				{
					TipoPessoaCadastro = TipoPessoaCadastro.Convenio
				},
				Pagina = 1,
				Tamanho = 100
			};
			PaginaEntityDto result = Service.Canal((IPessoaModuleService service) => service.PesquisarAtivosAsync(objetoPesquisaConvenios)).Result;
			Lista.Limpar();
			Lista.Adicionar(ConvenioLocalPadrao.Criar().ComNenhum());
			Lista.Adicionar(from PessoaDto x in result.Lista
				select ConvenioLocal.Criar().ComPessoaDto(x));
			Lista.PosicionarNoPrimeiro();
		}

		public override void EnterMethod()
		{
			decimal valor;
			if (Lista.ItemSelecionado.TipoDesconto == TipoDescontoConvenio.ValorFixo && Lista.ItemSelecionado.Desconto > Seletor.Get<PainelDocumentoFiscal>().PreDocumentoFiscal.SubTotal)
			{
				decimal subTotal = Seletor.Get<PainelDocumentoFiscal>().PreDocumentoFiscal.SubTotal;
				decimal value = 0.01m;
				decimal? num = Seletor.Get<PainelDocumentoFiscal>()?.PreDocumentoFiscal?.Itens?.Where((ItemDocumentoFiscal x) => x.Ativo).Count();
				valor = subTotal - (((decimal?)value * num) ?? 0m);
			}
			else
			{
				valor = Lista.ItemSelecionado.Desconto;
			}
			Seletor.Get<PainelTotalizacaoEmissorBase>().Informacao.Texto = ((Lista.ItemSelecionado.TipoDesconto == TipoDescontoConvenio.Percentual) ? (Lista.ItemSelecionado.Desconto.ToString("##,##") + "%") : (valor.FormatarCampoValor(2) + "-"));
			Seletor.Get<PainelTotalizacaoEmissorBase>().AplicarDesconto();
			Seletor.Get<PainelDocumentoFiscal>().PreDocumentoFiscal.SetarConvenio(Lista.ItemSelecionado);
			Seletor.Fechar();
		}

		public override bool PodeVoltar()
		{
			return true;
		}
	}
	public class PainelConsultaAutorizacaoPbm : PainelInteracao<PainelConsultaAutorizacaoPbm>
	{
		private readonly IFarmaciaService _farmaciaService;

		private Pbm _pbmSelecionado;

		private bool _processando;

		private ItemInteracaoComboBox _comboBoxOperadorasPortalDrogaria;

		private ItemInteracaoTextoLimitado _cep;

		private ItemInteracaoTextoLimitado _cpf;

		private ItemInteracaoTextoFocusable _campoNumeroCartao;

		private ItemInteracaoTextoFocusable _campoNsu;

		public IList<Operadora> Lista { get; protected set; } = new List<Operadora>();

		public override string Titulo => "Consulta autorização";

		public PainelConsultaAutorizacaoPbm()
		{
		}

		public PainelConsultaAutorizacaoPbm(Seletor<IPainel> seletor, IFarmaciaService farmaciaService)
			: base(seletor)
		{
			_farmaciaService = farmaciaService;
		}

		public override void Load()
		{
			Pbm pbmSelecionado = _pbmSelecionado;
			if (pbmSelecionado != null && pbmSelecionado.TipoPbm == TipoPbm.PortalDrogaria)
			{
				Campos.Clear();
				_campoNumeroCartao = ItemInteracaoBase<ItemInteracaoTextoFocusable, string>.Criar().ComDescricao("Número do cartão").Build();
				_campoNsu = ItemInteracaoBase<ItemInteracaoTextoFocusable, string>.Criar().ComDescricao("NSU").Build();
				Lista<IItemInteracao> lista = new Lista<IItemInteracao>();
				lista.Adicionar(_campoNumeroCartao);
				ItemInteracaoComboBox itemInteracaoComboBox = ItemInteracaoBase<ItemInteracaoComboBox, Lista<IItemInteracao>>.Criar().ComDescricao("Número do cartão").ComValor(lista)
					.Build();
				Lista<IItemInteracao> lista2 = new Lista<IItemInteracao>();
				lista2.Adicionar(_campoNsu);
				ItemInteracaoComboBox itemInteracaoComboBox2 = ItemInteracaoBase<ItemInteracaoComboBox, Lista<IItemInteracao>>.Criar().ComDescricao("NSU").ComValor(lista2)
					.Build();
				Lista<IItemInteracao> lista3 = new Lista<IItemInteracao>();
				lista3.Adicionar(itemInteracaoComboBox, itemInteracaoComboBox2);
				lista3.AlterouItemSelecionadoEvent += ItemFiltroOnAlterouItemSelecionadoEvent;
				Campos.Add(ItemInteracaoBase<ItemInteracaoComboBox, Lista<IItemInteracao>>.Criar().ComDescricao("Tipo informação").ComValor(lista3)
					.Build());
				try
				{
					LerArquivo();
				}
				catch (Exception ex)
				{
					ex.ShowLastException();
					Seletor.Voltar();
				}
				Lista<IItemInteracao> lista4 = new Lista<IItemInteracao>();
				lista4.Adicionar(Lista.Select((Operadora x) => ItemInteracaoBase<ItemInteracaoOperadoraPortalDrogaria, Operadora>.Criar().ComDescricao(x.NomeOperadora).ComValor(x)));
				lista4.AlterouItemSelecionadoEvent += ListaOperadorasOnAlterouItemSelecionadoEvent;
				_comboBoxOperadorasPortalDrogaria = ItemInteracaoBase<ItemInteracaoComboBox, Lista<IItemInteracao>>.Criar().ComDescricao("Operadora").ComValor(lista4)
					.Build();
				Campos.Add(_comboBoxOperadorasPortalDrogaria);
			}
			else
			{
				Pbm pbmSelecionado2 = _pbmSelecionado;
				string descricao = ((pbmSelecionado2 != null && pbmSelecionado2.TipoPbm == TipoPbm.EPharma) ? "Número da autorização sem o dígito" : "Número da autorização");
				Campos.Clear();
				Campos.Add(ItemInteracaoBase<ItemInteracaoTextoFocusable, string>.Criar().ComDescricao(descricao).Build());
			}
		}

		private void ItemFiltroOnAlterouItemSelecionadoEvent(object sender, IItemInteracao itemInteracao)
		{
			_campoNsu.Valor = string.Empty;
			_campoNumeroCartao.Valor = string.Empty;
		}

		private void ListaOperadorasOnAlterouItemSelecionadoEvent(object sender, IItemInteracao itemInteracao)
		{
			ItemInteracaoOperadoraPortalDrogaria itemSelecionado = itemInteracao as ItemInteracaoOperadoraPortalDrogaria;
			AdicionarRemoverCep(itemSelecionado);
			AdicionarRemoverCpf(itemSelecionado);
		}

		private void AdicionarRemoverCep(ItemInteracaoOperadoraPortalDrogaria itemSelecionado)
		{
			if (itemSelecionado != null && itemSelecionado.Valor.Cep)
			{
				_cep = ItemInteracaoBase<ItemInteracaoTextoLimitado, string>.Criar().ComDescricao("Cep").ComLimiteCaracteres(11)
					.Build();
				Campos.Add(_cep);
			}
			else
			{
				Campos.RemoveIfExists(_cep);
			}
		}

		private void AdicionarRemoverCpf(ItemInteracaoOperadoraPortalDrogaria itemSelecionado)
		{
			if (itemSelecionado != null && itemSelecionado.Valor.Cpf)
			{
				_cpf = ItemInteracaoBase<ItemInteracaoTextoLimitado, string>.Criar().ComDescricao("Cpf").ComLimiteCaracteres(8)
					.Build();
				Campos.Add(_cpf);
			}
			else
			{
				Campos.RemoveIfExists(_cpf);
			}
		}

		protected override void F2Method()
		{
			_processando = true;
			LoaderProcessoService.MostrarLoader();
			string cnpj = DadosSistema.EmpresaLogada.CpfCnpj;
			if (AmbienteTeste.IsValid)
			{
				cnpj = "99999994001645";
			}
			Task.Run(() =>
			{
				_farmaciaService.TestarAtividade(_pbmSelecionado.TipoPbm);
				string text = Campos.FirstOrDefault().To<ItemInteracaoTextoFocusable>()?.Valor?.ApenasNumeros();
				string value = ((!string.IsNullOrWhiteSpace(_campoNumeroCartao?.Valor)) ? _campoNumeroCartao?.Valor : _campoNsu?.Valor);
				IFarmaciaService farmaciaService = _farmaciaService;
				Pbm pbmSelecionado = _pbmSelecionado;
				IRetornoConsulta retorno = farmaciaService.Consultar((pbmSelecionado != null && pbmSelecionado.TipoPbm == TipoPbm.PortalDrogaria) ? value.RemoverPontoBarraHifen() : text, !string.IsNullOrWhiteSpace(_campoNumeroCartao?.Valor.RemoverPontoBarraHifen()), _comboBoxOperadorasPortalDrogaria?.Valor.ItemSelecionado.To<ItemInteracaoOperadoraPortalDrogaria>()?.Descricao, cnpj, 1, RetornarDadosComplementares(), 0, _pbmSelecionado.TipoPbm);
				ThreadPrincipal.Executar(() =>
				{
					Seletor.Voltar();
					Seletor.Get<PainelDocumentoFiscal>().EmitirDocumentoFiscal(retorno);
				});
			}).ContinueWith((Task task) =>
			{
				_processando = false;
				ThreadPrincipal.Executar(() =>
				{
					LoaderProcessoService.EsconderLoader();
					if (task.IsFaulted)
					{
						task.Exception.ShowLastException();
					}
					Pbm pbmSelecionado = _pbmSelecionado;
					if (pbmSelecionado == null || pbmSelecionado.TipoPbm != TipoPbm.PortalDrogaria)
					{
						DormirAsync(2000, (object x) =>
						{
							_farmaciaService.EfetivarTransacao(!string.IsNullOrWhiteSpace(_campoNumeroCartao?.Valor.RemoverPontoBarraHifen()), _comboBoxOperadorasPortalDrogaria?.Valor.ItemSelecionado.To<ItemInteracaoOperadoraPortalDrogaria>()?.Descricao, cnpj, 1, RetornarDadosComplementares(), 0, Seletor.Get<PainelDocumentoFiscal>().PreDocumentoFiscal, 0L);
						});
					}
				});
			});
		}

		private string RetornarDadosComplementares()
		{
			string text = string.Empty;
			ItemInteracaoTextoLimitado cep = _cep;
			bool? flag;
			if (cep == null)
			{
				flag = null;
			}
			else
			{
				string valor = cep.Valor;
				flag = ((valor != null) ? new bool?(!valor.IsNullOrEmpty()) : ((bool?)null));
			}
			if (flag ?? false)
			{
				text += $"08{_cep.Valor}";
			}
			ItemInteracaoTextoLimitado cpf = _cpf;
			bool? flag2;
			if (cpf == null)
			{
				flag2 = null;
			}
			else
			{
				string valor2 = cpf.Valor;
				flag2 = ((valor2 != null) ? new bool?(!valor2.IsNullOrEmpty()) : ((bool?)null));
			}
			if (flag2 ?? false)
			{
				text += $"11{_cpf.Valor}";
			}
			return text;
		}

		protected override bool CanF2Method()
		{
			if (Campos.IsNotNull() && !_processando)
			{
				if (string.IsNullOrWhiteSpace(Campos.FirstOrDefault().To<ItemInteracaoTextoFocusable>()?.Valor) && string.IsNullOrWhiteSpace(_campoNsu?.Valor))
				{
					return !string.IsNullOrWhiteSpace(_campoNumeroCartao?.Valor);
				}
				return true;
			}
			return false;
		}

		private void LerArquivo()
		{
			VerificarExistenciaArquivo();
			StreamReader streamReader = new StreamReader(Path.Combine(Path.GetPathRoot(Environment.SystemDirectory), "TRNCENTR", "TCTB_OPR.txt"));
			Lista?.Clear();
			string text;
			while ((text = streamReader.ReadLine()) != null)
			{
				Lista.Add(FluentFactory<OperadoraFactory>.Init().SetarNomeOperadora(text.CopiarTexto(0, 20)).SetarCodigoOperadora(text.CopiarTexto(20, 8))
					.SetarIsCep(text.Contains("CEP"))
					.SetarIsCpf(text.Contains("CPF"))
					.Criar());
			}
			streamReader.Close();
		}

		private void VerificarExistenciaArquivo()
		{
			if (!File.Exists(Path.Combine(Path.GetPathRoot(Environment.SystemDirectory), "TRNCENTR", "TCTB_OPR.txt")))
			{
				throw new Exception("Arquivo TCTB_OPR.txt não localizado.");
			}
		}

		public override void Dispose()
		{
		}

		public override void UnLoad()
		{
		}

		public override bool PodeVoltar()
		{
			return true;
		}

		public void SetarPbm(Pbm pbm)
		{
			_pbmSelecionado = pbm;
		}
	}
	public class Operadora
	{
		public string NomeOperadora { get; protected set; }

		public string CodigoOperadora { get; protected set; }

		public bool Cep { get; set; }

		public bool Cpf { get; protected set; }

		public Operadora(string nomeOperadora, string codigoOperadora, bool cep, bool cpf)
		{
			NomeOperadora = nomeOperadora;
			CodigoOperadora = codigoOperadora;
			Cep = cep;
			Cpf = cpf;
		}
	}
	public class OperadoraFactory
	{
		private string _nomeOperadora;

		private string _codigoOperadora;

		private bool _cep;

		private bool _cpf;

		public OperadoraFactory SetarNomeOperadora(string nomeOperadora)
		{
			_nomeOperadora = nomeOperadora;
			return this;
		}

		public OperadoraFactory SetarCodigoOperadora(string codigoOperadora)
		{
			_codigoOperadora = codigoOperadora;
			return this;
		}

		public OperadoraFactory SetarIsCep(bool cep)
		{
			_cep = cep;
			return this;
		}

		public OperadoraFactory SetarIsCpf(bool cpf)
		{
			_cpf = cpf;
			return this;
		}

		public Operadora Criar()
		{
			return new Operadora(_nomeOperadora, _codigoOperadora, _cep, _cpf);
		}
	}
	public class PainelEsquerdoBicos : PainelBase<PainelEsquerdoBicos>, IPainelEsquerdo, IPainel
	{
		private readonly IEventPublisher _eventPublisher;

		private IDisposable _statusBicosDisposable;

		public Lista<BicoStatusViewModel> Lista { get; set; } = new Lista<BicoStatusViewModel>();

		public string Titulo => "Status dos bicos";

		public IReadOnlyCollection<string> Atalhos => new List<string>();

		public IEnumerable<ItemMenuAtalho> MenuRibbon { get; protected set; }

		public ICommand ReturnCommand { get; set; }

		public PainelEsquerdoBicos()
		{
		}

		public PainelEsquerdoBicos(IEventPublisher eventPublisher, Seletor<IPainel> seletorEsquerdo)
			: base(seletorEsquerdo)
		{
			eventPublisher.GetEvent((ConnectPontoDeVendaPostoServiceResponse obj) =>
			{
				ThreadPrincipal.Executar(() =>
				{
					AdicionarBicos(obj);
				});
			});
			_eventPublisher = eventPublisher;
			ReturnCommand = new DelegateCommand(TratarBico, PodeTratarBico);
		}

		private bool PodeTratarBico()
		{
			if (Lista.PossuiItemSelecionado)
			{
				return Lista.ItemSelecionado.PodeExecutarComando();
			}
			return false;
		}

		private void TratarBico()
		{
			Lista.ItemSelecionado.ExecutarComando();
		}

		private void AdicionarBicos(ConnectPontoDeVendaPostoServiceResponse obj)
		{
			int bicoSelecionado = (Lista.PossuiItemSelecionado ? Lista.ItemSelecionado.NumeroBico : 0);
			foreach (BicoStatus bicoStatus in obj.BicosStatus.OrderBy((BicoStatus x) => x.BicoNoSoftware))
			{
				BicoStatusViewModel bicoStatusViewModel = Lista.Itens.FirstOrDefault((BicoStatusViewModel x) => x.NumeroBico == bicoStatus.BicoNoSoftware);
				if (bicoStatusViewModel.IsNull())
				{
					Lista.Adicionar(new BicoStatusViewModel(bicoStatus, _eventPublisher));
				}
				else
				{
					bicoStatusViewModel.Atualizar(bicoStatus);
				}
			}
			if (bicoSelecionado > 0)
			{
				Lista.Posicionar((BicoStatusViewModel x) => x.NumeroBico == bicoSelecionado);
			}
			else
			{
				Lista.PosicionarNoPrimeiro();
			}
		}

		public override void Load()
		{
			_statusBicosDisposable = _eventPublisher.GetEvent<StatusBicosResponse>(AtualizarListaBicos);
		}

		private void AtualizarListaBicos(StatusBicosResponse obj)
		{
			foreach (BicoStatus bico in obj.Bicos)
			{
				Lista.Itens.FirstOrDefault((BicoStatusViewModel x) => x.NumeroBico == bico.BicoNoSoftware).Atualizar(bico);
			}
		}

		public override void UnLoad()
		{
			_statusBicosDisposable.Dispose();
		}

		public void SetarModoFuncionamento(IModoFuncionamento modoFuncionamento)
		{
		}

		public override bool PodeVoltar()
		{
			return true;
		}

		public override void Dispose()
		{
		}
	}
	public class PainelEsquerdoPosto : UpdateViewBindableBase, IPainelEsquerdo, IPainel
	{
		private IEmissorService _emissorService;

		private Seletor<IPainel> _seletorDireito;

