		public string NumeroAbastecimentosToText
		{
			get
			{
				if (!Lista.Itens.Any((AbastecimentoViewModel x) => x.VisivelNaTela))
				{
					return "Nenhum abastecimento";
				}
				if (Lista.Itens.Count((AbastecimentoViewModel x) => x.VisivelNaTela) != 1)
				{
					return $"{Lista.Itens.Count((AbastecimentoViewModel x) => x.VisivelNaTela)} abastecimentos no total de R$ {Lista.Itens.Where((AbastecimentoViewModel x) => x.VisivelNaTela).Sum((AbastecimentoViewModel y) => y.Abastecimento.ValorTotal).FormatarCampoValor(2)}";
				}
				return "1 abastecimento";
			}
		}

