		public PainelEsquerdoPosto(IPostoService postoService, ISessaoService sessaoService, IWService service, IEventPublisher eventPublisher, IProdutoServicoEmpresaRepositoryRead produtoServicoEmpresaRepositoryRead, IRepositoryRead<PreDocumentoFiscalNotaManualPosto> preDocumentoFiscalNotaManualPostoRepositoryRead, IRepositoryBaseWrite<PreDocumentoFiscal> preDocumentoFiscalRepositoryWrite, IRepositoryWrite<Movimentacao> movimentacaoRepositoryWrite, IRepositoryBaseWrite<PreDocumentoFiscalNotaManualPosto> preDocumentoFiscalNotaManualPostoRepositoryWrite, IRepositoryBaseWrite<PerdaComunicacaoTotal> perdaComunicacaoRepositoryWrite, IRepositoryRead<PerdaComunicacaoTotal> perdaComunicacaoRepositoryRead, IEmissorService emissorService, Seletor<IPainel> seletorDireito, Seletor<IPainel> seletorEsquerdo, IRepositoryRead<DigisatServer.Domain.Main.Aggregates.CadastrosAgg.Pessoas.Pessoa> pessoaRepositoryRead, IRepositoryRead<DigisatServer.Domain.Main.Aggregates.CadastrosAgg.OperacoesFiscal.OperacaoFiscal> operacaoFiscalRepositoryRead, IRepositoryRead<Otus.Modulo.PontoDeVendas.Aggregates.Scanntech.PromocaoScanntech> promocaoScanntechRepositoryRead, IImpressoraNaoFiscalService impressoraNaoFiscalService)
		{
			MostrarBotaoFiltro = Visibility.Collapsed;
			PerdaComunicacaoTotal = perdaComunicacaoRepositoryRead.FindOne(EntityBaseSpecification<PerdaComunicacaoTotal>.All());
			postoService.Criar();
			eventPublisher.GetEvent((ConfiguracaoDto dto) =>
			{
				postoService.Desconectar();
				postoService.Conectar();
			});
			_sessaoService = sessaoService;
			_service = service;
			_eventPublisher = eventPublisher;
			_emissorService = emissorService;
			_seletorDireito = seletorDireito;
			_seletorEsquerdo = seletorEsquerdo;
			_pessoaRepositoryRead = pessoaRepositoryRead;
			_operacaoFiscalRepositoryRead = operacaoFiscalRepositoryRead;
			_promocaoScanntechRepositoryRead = promocaoScanntechRepositoryRead;
			_impressoraNaoFiscalService = impressoraNaoFiscalService;
			_produtoServicoEmpresaRepositoryRead = produtoServicoEmpresaRepositoryRead;
			_preDocumentoFiscalNotaManualPostoRepositoryRead = preDocumentoFiscalNotaManualPostoRepositoryRead;
			_preDocumentoFiscalRepositoryWrite = preDocumentoFiscalRepositoryWrite;
			_movimentacaoRepositoryWrite = movimentacaoRepositoryWrite;
			_preDocumentoFiscalNotaManualPostoRepositoryWrite = preDocumentoFiscalNotaManualPostoRepositoryWrite;
			_perdaComunicacaoRepositoryWrite = perdaComunicacaoRepositoryWrite;
			_emissorService.WhenEmissorCarregadoEvent.Subscribe((EventArgs args) =>
			{
				if (!_bwEmissorCarregado.IsBusy)
				{
					_bwEmissorCarregado.RunWorkerAsync();
				}
			});
			eventPublisher.GetEvent((SemComunicacaoServidorEvent x) =>
			{
				_semComunicacaoServidor = true;
				ControlarDocumentoFiscalBloqueadoSemComunicacaoServidor();
			});
			eventPublisher.GetEvent((ComunicandoServidorEvent x) =>
			{
				_semComunicacaoServidor = false;
				ControlarDocumentoFiscalBloqueadoSemComunicacaoServidor();
			});
			eventPublisher.GetEvent<ConnectPontoDeVendaPostoServiceResponse>(ProcessarConectouPostoService);
			eventPublisher.GetEvent<SemConfiguracaoPostoServiceEvent>(ProcessarMensagemPostoService);
			eventPublisher.GetEvent<SemComunicacaoPostoServiceEvent>(ProcessarMensagemPostoService);
			eventPublisher.GetEvent<NovoAbastecimentoResponse>(AdicionarAbastecimento);
			eventPublisher.GetEvent<IEnumerable<IAbastecimento>>(RemoverAbastecimentos);
			eventPublisher.GetEvent<QuebraContinuidadeEncerranteResponse>(OnRecebeuQuebraContinuidadeEncerrante);
			eventPublisher.GetEvent<RemoverQuebraContinuidadeEncerranteResponse>(OnRemoveuQuebraContinuidadeEncerrante);
			eventPublisher.GetEvent<RegistroDescontinuidadeEncerrante>(ProcessarRegistroDescontinuidadeEncerrante);
			if (DadosSistema.IsPaf)
			{
				eventPublisher.GetEvent<PerdeuComunicacaoTotalResponse>(NotificarPerdaComunicacaoTotal);
				eventPublisher.GetEvent<RetornouComunicacaoTotalResponse>(NotificarRetornoComunicacaoTotal);
				eventPublisher.GetEvent<NotificouSituacaoComunicacaoBicoResponse>(NotificarSituacaoComunicacaoBico);
				eventPublisher.GetEvent<AntesRegistrarDescontinuidadeEncerrante>(ProcessarAntesRegistrarDescontinuidadeEncerrante);
				eventPublisher.GetEvent<RegistroNotaManualQuebraContinuidadeEncerrante>(ProcessarRegistroNotaManualQuebraContinuidadeEncerrante);
			}
			CtrlFCommand = new AsyncCommand(FiltrarLista, () => !_semComunicacaoPostoService, allowMultipleExecution: false);
			InsertCommand = new AsyncCommand(ImportarAbastecimentos, PodeImportarAbastecimentos, allowMultipleExecution: false);
			CtrlAltXCommand = new AsyncCommand(ExcluirAbastecimentos, PodeExcluirAbastecimentos, allowMultipleExecution: false);
			CtrlF6Command = new DelegateCommand(RegistrarAfericao, PodeRegistrarAfericao);
			CtrlF7Command = new DelegateCommand(() =>
			{
				AtualizarPrecos();
			}, () => !_semComunicacaoPostoService);
			CtrlF8Command = new DelegateCommand(_seletorDireito.Selecionar<PainelPreset>, () => !_semComunicacaoPostoService);
			CtrlDCommand = new DelegateCommand(() =>
			{
				_seletorDireito.Selecionar<PainelObservacaoPosto>();
			}, PodeAdicionarDadosVeiculo);
			CtrlSCommand = new DelegateCommand(AbrirStatusBicos, PodeAbrirStatusBicos);
			CtrlAltSCommand = new DelegateCommand(AbrirStatusTanques, PodeAbrirStatusTanques);
			CtrlNCommand = new DelegateCommand(RegistrarAbastecimentoManual, PodeRegistrarAbastecimentoManual);
			CtrlQCommand = new DelegateCommand(RegistrarQuebraContinuidadeEncerrante, PodeRegistrarQuebraContinuidadeEncerrante);
			SpaceCommand = new DelegateCommand(Selecionar);
			CtrlACommand = new DelegateCommand(() =>
			{
				TodosSelecionados = !TodosSelecionados;
			});
			MenuRibbon = new List<ItemMenuAtalho>
			{
				new ItemMenuAtalho("Insert", "Importar abastecimento", InsertCommand),
				new ItemMenuAtalho("Ctrl+Alt+X", "Excluir abastecimento", CtrlAltXCommand),
				new ItemMenuAtalho("Ctrl+S", "Status bicos", CtrlSCommand),
				new ItemMenuAtalho("Ctrl+Alt+S", "Status tanques", CtrlAltSCommand),
				new ItemMenuAtalho("Ctrl+N", "Registrar abastecimento", CtrlNCommand),
				new ItemMenuAtalho("Ctrl+Q", "Quebra da continuidade", CtrlQCommand),
				new ItemMenuAtalho("Ctrl+F7", "Atualizar preços", CtrlF7Command),
				new ItemMenuAtalho("Ctrl+F8", "Preset", CtrlF8Command),
				new ItemMenuAtalho("Ctrl+F6", "Aferição", CtrlF6Command),
				new ItemMenuAtalho("Ctrl+D", "Dados do veículo", CtrlDCommand),
				new ItemMenuAtalho("Ctrl+F", "Filtrar lista", CtrlFCommand)
			};
			_backgroundWorker = new BackgroundWorker();
			_backgroundWorker.DoWork += BwOnDoWork;
			_backgroundWorker.RunWorkerCompleted += BackgroundWorkerOnRunWorkerCompleted;
			_bwEmissorCarregado = new BackgroundWorker();
			_bwEmissorCarregado.DoWork += BwEmissorCarregadoOnDoWork;
			_bwEmissorCarregado.RunWorkerCompleted += BwEmissorCarregadoOnRunWorkerCompleted;
			_bwDocumentoFechado = new BackgroundWorker();
			_frentistas = _pessoaRepositoryRead.Find(PessoaSpecifications.Frentistas().PorAtivo());
			CriarListaFrentistas(_frentistas);
			Lista.PropertyChanged += ListaOnPropertyChanged;
			Observable.Interval(TimeSpan.FromMinutes(1.0)).Subscribe((long x) =>
			{
				VerificarAlteracaoPreco();
			});
		}

		private void VerificarAlteracaoPreco()
		{
			try
			{
				if (_service.Canal((IPostoCombustivelModuleService x) => x.VerificarAlteracaoPreco()))
				{
					AtualizarPrecos(mostrarDialogoConfirma: false);
				}
			}
			catch (Exception)
			{
			}
		}

		private void ListaOnPropertyChanged(object sender, PropertyChangedEventArgs propertyChangedEventArgs)
		{
			if (propertyChangedEventArgs.PropertyName.Equals("Numero"))
			{
				RaisePropertyChanged(() => NumeroAbastecimentosToText);
				RaisePropertyChanged(() => NumeroAbastecimentosSelecionadosToText);
			}
		}

		private void CriarListaFrentistas(IEnumerable<DigisatServer.Domain.Main.Aggregates.CadastrosAgg.Pessoas.Pessoa> pessoas)
		{
			ListaFrentistas.Limpar();
			_listaFrentistasItemSelecionadoDisposable?.Dispose();
			ListaFrentistas.Adicionar(FrentistaViewModel.CriarTodos());
			IEnumerable<FrentistaViewModel> itens = from y in pessoas
				orderby y.Nome
				select new FrentistaViewModel(y.To<Fisica>().Frentista.Codigo, y.Nome);
			ListaFrentistas.Adicionar(itens);
			ListaFrentistas.PosicionarNoPrimeiro();
			VerificarBotaoFiltro();
			_listaFrentistasItemSelecionadoDisposable = ListaFrentistas.WhenAlterouItemSelecionado.Subscribe((FrentistaViewModel x) =>
			{
				if (MostrarBotaoFiltro == Visibility.Collapsed)
				{
					FiltrarLista();
				}
			});
		}

		private Task FiltrarLista()
		{
			ProcessarMensagemPostoService(new FiltrandoAbastecimentosEvent());
			DispatcherHelper.DoEvents();
			return Task.Factory.StartNew(() =>
			{
				foreach (AbastecimentoViewModel iten in Lista.Itens)
				{
					iten.EsconderDaTela();
				}
				if (ListaBicos.ItemSelecionado.IsTodos)
				{
					if (ListaFrentistas.ItemSelecionado.IsTodos)
					{
						foreach (AbastecimentoViewModel iten2 in Lista.Itens)
						{
							iten2.MostrarNaTela();
						}
						return;
					}
					{
						foreach (AbastecimentoViewModel item in Lista.Itens.Where((AbastecimentoViewModel a) => a.Abastecimento.Frentista.Equals(ListaFrentistas.ItemSelecionado.Codigo)))
						{
							item.MostrarNaTela();
						}
						return;
					}
				}
				if (ListaFrentistas.ItemSelecionado.IsTodos)
				{
					foreach (AbastecimentoViewModel item2 in Lista.Itens.Where((AbastecimentoViewModel a) => a.Abastecimento.NumeroDoBicoNoSoftware.Equals(ListaBicos.ItemSelecionado.Numero.ToInt())))
					{
						item2.MostrarNaTela();
					}
					return;
				}
				foreach (AbastecimentoViewModel item3 in Lista.Itens.Where((AbastecimentoViewModel a) => a.Abastecimento.NumeroDoBicoNoSoftware.Equals(ListaBicos.ItemSelecionado.Numero.ToInt()) && a.Abastecimento.Frentista.Equals(ListaFrentistas.ItemSelecionado.Codigo)))
				{
					item3.MostrarNaTela();
				}
			}).ContinueWith((Task task) =>
			{
				RaisePropertyChanged(() => NumeroAbastecimentosToText);
				RaisePropertyChanged(() => NumeroAbastecimentosSelecionadosToText);
				ProcessarMensagemPostoService(new ParouFiltroAbastecimentosEvent());
			});
		}

		private void BwEmissorCarregadoOnDoWork(object sender, DoWorkEventArgs doWorkEventArgs)
		{
			if (DadosSistema.IsPaf)
			{
				ImprimirRelatoriosNotificacaoComunicacao();
				EmitirCuponsFiscaisNotasManuaisContingencia();
				OnHabilitouNotaManualEvent(PerdaComunicacaoTotal != null);
			}
		}

		private void ImprimirRelatoriosNotificacaoComunicacao()
		{
			foreach (string item in (from x in _acoesQuandoEstadoDocumentoFechado
				where x.Value is NotificacaoComunicacaoAcao
				orderby x.Value.DataHora
				select x.Key).ToListEmptyWhenNull())
			{
				Acao acao = _acoesQuandoEstadoDocumentoFechado[item];
				BackgroundWorkerArgument argument = acao.Action;
				string mensagemAnterior = string.Empty;
				if (!string.IsNullOrWhiteSpace(argument.Message))
				{
					mensagemAnterior = _seletorDireito.Get<IPainelMensagem>().Informacao;
					LoaderProcessoService.MostrarLoader(argument.Message);
					ThreadPrincipal.Executar(() =>
					{
						_seletorDireito.Get<IPainelMensagem>().AlterarMensagem(argument.Message);
					});
				}
				try
				{
					argument.Action();
				}
				catch (Exception ex)
				{
					ex.ShowLastException();
				}
				finally
				{
					_acoesQuandoEstadoDocumentoFechado.Remove(item);
					if (!string.IsNullOrWhiteSpace(mensagemAnterior))
					{
						LoaderProcessoService.EsconderLoader();
						ThreadPrincipal.Executar(() =>
						{
							_seletorDireito.Get<IPainelMensagem>().AlterarMensagem(mensagemAnterior);
						});
					}
				}
			}
		}

		private void EmitirCuponsFiscaisNotasManuaisContingencia()
		{
			IEnumerable<PreDocumentoFiscalNotaManualPosto> enumerable = _preDocumentoFiscalNotaManualPostoRepositoryRead.Find(EntityBaseSpecification<PreDocumentoFiscalNotaManualPosto>.All());
			if (enumerable.Any())
			{
				EmitirCuponsFiscaisPreDocumentoFiscalNotaManualPosto(enumerable);
			}
		}

		private void EmitirCuponsFiscaisPreDocumentoFiscalNotaManualPosto(IEnumerable<PreDocumentoFiscalNotaManualPosto> notasManuais)
		{
			string mensagemAnterior = _seletorDireito.Get<IPainelMensagem>().Informacao;
			foreach (PreDocumentoFiscalNotaManualPosto notaManual in notasManuais)
			{
				ThreadPrincipal.Executar(() =>
				{
					_seletorDireito.Get<IPainelMensagem>().AlterarMensagem($"Emitindo cupom fiscal da nota: {notaManual.PreDocumentoFiscal.Numero}");
				});
				EmitirCupomFiscalNotaManual(notaManual);
			}
			ThreadPrincipal.Executar(() =>
			{
				_seletorDireito.Get<IPainelMensagem>().AlterarMensagem(mensagemAnterior);
			});
		}

		private void BwEmissorCarregadoOnRunWorkerCompleted(object sender, RunWorkerCompletedEventArgs runWorkerCompletedEventArgs)
		{
			if (DadosSistema.IsPaf)
			{
				VerificarEstoqueFisicoCombustiveisMesAnterior();
				_emissorService.VerificarEstado();
			}
		}

		private void BwOnDoWork(object sender, DoWorkEventArgs eventArgs)
		{
			BackgroundWorkerArgument argument = (BackgroundWorkerArgument)eventArgs.Argument;
			if (argument.IsNull())
			{
				return;
			}
			if (!string.IsNullOrWhiteSpace(argument.Message))
			{
				eventArgs.Result = _seletorDireito.Get<IPainelMensagem>().Informacao;
				LoaderProcessoService.MostrarLoader(argument.Message);
				ThreadPrincipal.Executar(() =>
				{
					_seletorDireito.Get<IPainelMensagem>().AlterarMensagem(argument.Message);
				});
			}
			argument.Action();
		}

		private void BackgroundWorkerOnRunWorkerCompleted(object sender, RunWorkerCompletedEventArgs runWorkerCompletedEventArgs)
		{
			if (!string.IsNullOrWhiteSpace(runWorkerCompletedEventArgs.Result?.ToString()))
			{
				LoaderProcessoService.EsconderLoader();
				ThreadPrincipal.Executar(() =>
				{
					_seletorDireito.Get<IPainelMensagem>().AlterarMensagem(runWorkerCompletedEventArgs.Result.ToString());
				});
			}
			runWorkerCompletedEventArgs.Error?.ShowLastException();
		}

		public void VerificarEstoqueFisicoCombustiveisMesAnterior()
		{
			DateTime dataMovimento = _emissorService.RetornarDataMovimento().AddMonths(-1);
			VerificarEstoqueFisicoCombustiveis(dataMovimento);
		}

		public void VerificarEstoqueFisicoCombustiveis(DateTime dataMovimento, Action acaoDepoisVerificarEstoqueFisico = null)
		{
			if (!_emissorService.VerificarDocumentoFiscalFechado() || _emissorService.VerificarReducaoZPendente() || !_jornadaFiscalAberta)
			{
				return;
			}
			bool flag = false;
			try
			{
				flag = _service.Canal((IPostoCombustivelModuleService x) => x.VerificarLancamentoEstoqueFisicoCombustivel(dataMovimento));
			}
			catch (Exception ex)
			{
				ex.ShowLastException("Falha ao verificar lançamento de estoque físico!");
			}
			if (flag)
			{
				ThreadPrincipal.Executar(() =>
				{
					_seletorDireito.Get<PainelEstoqueFisicoCombustivel>().SetarAcaoAoConcluir(acaoDepoisVerificarEstoqueFisico);
					_seletorDireito.Selecionar<PainelEstoqueFisicoCombustivel>();
				});
			}
			else
			{
				acaoDepoisVerificarEstoqueFisico?.Invoke();
			}
		}

		private BackgroundWorkerArgument CriarAcao(Action action, string message = "")
		{
			return new BackgroundWorkerArgument(action, message);
		}

		public void EmitirCupomFiscalNotaManual(PreDocumentoFiscalNotaManualPosto nota)
		{
			_emissorService.EmitirDocumentoFiscal(nota.PreDocumentoFiscal.Itens, null, null, nota.MensagensPromocionais.ToArray());
			nota.Efetivar(_preDocumentoFiscalRepositoryWrite, _movimentacaoRepositoryWrite, _operacaoFiscalRepositoryRead, _promocaoScanntechRepositoryRead, _emissorService);
			_preDocumentoFiscalNotaManualPostoRepositoryWrite.Delete(nota);
		}

		private void ProcessarMensagemPostoService(object obj)
		{
			obj.ToDo((ConnectPontoDeVendaPostoServiceResponse conectado) =>
			{
				_semComunicacaoPostoService = false;
				Mensagem = string.Empty;
				MostrarMensagem = false;
				MostrarListaBicosEFrentistas = true;
			});
			obj.ToDo((SemComunicacaoPostoServiceEvent semComunicacao) =>
			{
				_semComunicacaoPostoService = true;
				MostrarMensagem = true;
				Mensagem = semComunicacao.Mensagem;
				MostrarListaBicosEFrentistas = false;
			});
			obj.ToDo((SemConfiguracaoPostoServiceEvent semConfiguracao) =>
			{
				_semComunicacaoPostoService = true;
				MostrarMensagem = true;
				Mensagem = semConfiguracao.Mensagem;
			});
			obj.ToDo((FiltrandoAbastecimentosEvent filtrando) =>
			{
				MostrarMensagem = true;
				Mensagem = filtrando.Mensagem;
			});
			obj.ToDo((ParouFiltroAbastecimentosEvent filtrando) =>
			{
				MostrarMensagem = false;
			});
		}

		private void ProcessarConectouPostoService(ConnectPontoDeVendaPostoServiceResponse obj)
		{
			ProcessarMensagemPostoService(obj);
			NotificouSituacaoComunicacaoBicoResponse[] array = obj.Notificacoes.Where((NotificouSituacaoComunicacaoBicoResponse x) => x.Situacao == SituacaoComunicacaoConcentrador.Retorno).ToArray();
			if (DadosSistema.IsPaf && PerdaComunicacaoTotal.IsNotNull() && array.Any())
			{
				PerdaComunicacaoTotal = null;
				_perdaComunicacaoRepositoryWrite.DeleteAll();
				ExecutarAcaoQuandoDocumentoFechado(CriarAcaoImprimirRetornoComunicacao(array));
			}
			IEnumerable<NotificouSituacaoComunicacaoBicoResponse> source = obj.Notificacoes.Where((NotificouSituacaoComunicacaoBicoResponse x) => x.Situacao == SituacaoComunicacaoConcentrador.Perda);
			AdicionarNotificacoes(source.ToArray());
			ThreadPrincipal.Executar(() =>
			{
				AdicionarAbastecimentos(obj);
			});
		}

		private void AdicionarAbastecimentos(ConnectPontoDeVendaPostoServiceResponse obj)
		{
			Lista.Limpar();
			IEnumerable<AbastecimentoDto> abastecimentos = _service.Canal((IPostoCombustivelModuleService x) => x.ObterAbastecimentosDto(obj.Abastecimentos.Select((IAbastecimento y) => y.Id))).Result;
			List<AbastecimentoViewModel> itens = (from y in obj.Abastecimentos
				orderby y.DataHora descending
				select CriarAbastecimentoViewModel(y, !abastecimentos.FirstOrDefault((AbastecimentoDto x) => x.Id.Equals(y.Id)).ImpressoComprovantePista)).ToListEmptyWhenNull();
			Lista.Adicionar(itens);
			Lista.PosicionarNoPrimeiro();
			CriarListaBicos(obj.Abastecimentos);
		}

		private void CriarListaBicos(IEnumerable<IAbastecimento> abastecimentos)
		{
			ListaBicos.Limpar();
			_listaBicosItemSelecionadoDisposable?.Dispose();
			ListaBicos.AlterouEvent -= OnListaBicosOnAlterouEvent;
			ListaBicos.Adicionar(BicoViewModel.CriarTodos());
			IEnumerable<BicoViewModel> itens = from g in abastecimentos
				group g by g.NumeroDoBicoNoSoftware into y
				orderby y.Key
				select new BicoViewModel(y.Key);
			ListaBicos.Adicionar(itens);
			ListaBicos.Ordenar((BicoViewModel i) => i.NumeroBicoNoSoftware);
			ListaBicos.PosicionarNoPrimeiro();
			VerificarBotaoFiltro();
			_listaBicosItemSelecionadoDisposable = ListaBicos.WhenAlterouItemSelecionado.Subscribe((BicoViewModel x) =>
			{
				if (MostrarBotaoFiltro == Visibility.Collapsed)
				{
					FiltrarLista();
				}
			});
			ListaBicos.AlterouEvent += OnListaBicosOnAlterouEvent;
		}

		private void OnListaBicosOnAlterouEvent(object o, IEnumerable<BicoViewModel> models)
		{
			ListaBicos.Ordenar((BicoViewModel i) => i.NumeroBicoNoSoftware);
		}

		private void VerificarBotaoFiltro()
		{
			MostrarBotaoFiltro = ((Lista.Numero <= 500) ? Visibility.Collapsed : Visibility.Visible);
		}

		private void AdicionarListaBicos(AbastecimentoViewModel viewModel)
		{
			VerificarBotaoFiltro();
			int itemSelecionado = ListaBicos.ItemSelecionado.NumeroBicoNoSoftware;
			if (ListaBicos.Existe((BicoViewModel x) => x.NumeroBicoNoSoftware.Equals(viewModel.Abastecimento.NumeroDoBicoNoSoftware)))
			{
				if (!itemSelecionado.Equals(viewModel.Abastecimento.NumeroDoBicoNoSoftware) && !ListaBicos.ItemSelecionado.IsTodos)
				{
					viewModel.EsconderDaTela();
				}
				return;
			}
			ListaBicos.Adicionar(new BicoViewModel(viewModel.Abastecimento.NumeroDoBicoNoSoftware));
			if (!itemSelecionado.Equals(ListaBicos.ItemSelecionado.NumeroBicoNoSoftware))
			{
				ListaBicos.Posicionar((BicoViewModel x) => x.NumeroBicoNoSoftware.Equals(itemSelecionado));
			}
		}

		private void RemoverListaBicos(IAbastecimento abastecimento)
		{
			VerificarBotaoFiltro();
			if (Lista.Itens.Count((AbastecimentoViewModel x) => x.Abastecimento.NumeroDoBicoNoSoftware.Equals(abastecimento.NumeroDoBicoNoSoftware)) > 0)
			{
				return;
			}
			string itemSelecionado = ListaBicos.ItemSelecionado.Numero;
			BicoViewModel item = ListaBicos.Itens.FirstOrDefault((BicoViewModel x) => x.NumeroBicoNoSoftware.Equals(abastecimento.NumeroDoBicoNoSoftware));
			ListaBicos.Remover(item);
			if (!itemSelecionado.Equals(ListaBicos.ItemSelecionado.Numero))
			{
				ListaBicos.Posicionar((BicoViewModel x) => x.Numero.Equals(itemSelecionado));
			}
		}

		private void AdicionarAbastecimento(NovoAbastecimentoResponse abastecimento)
		{
			VerificarPerdaCombustivel(abastecimento.Abastecimento);
			ThreadPrincipal.Executar(() =>
			{
				if (!Lista.Existe((AbastecimentoViewModel x) => x.Abastecimento.Id == abastecimento.Abastecimento.Id))
				{
					AbastecimentoViewModel abastecimentoViewModel = CriarAbastecimentoViewModel(abastecimento.Abastecimento, !abastecimento.Abastecimento.ImpressoComprovantePista);
					Lista.Inserir(0, abastecimentoViewModel);
					AdicionarListaBicos(abastecimentoViewModel);
					if (!Lista.PossuiItemSelecionado || !Lista.ItemSelecionado.Selecionado)
					{
						Lista.PosicionarNoPrimeiro();
					}
				}
			});
		}

		private void VerificarPerdaCombustivel(IAbastecimento abastecimento)
		{
			if (DadosSistema.IsPaf && !abastecimento.TemEstoque && !Lista.Existe((AbastecimentoViewModel x) => x.Abastecimento.NumeroDoTanque == abastecimento.NumeroDoTanque && !x.Abastecimento.TemEstoque))
			{
				ExecutarAcaoDocumentoFechado(CriarAcao(() =>
				{
					ImprimirRelatorioGerencialPerdaCombustivel(abastecimento);
				}, "Imprimindo relatório de perda de combustível"));
			}
		}

		private void ImprimirRelatorioGerencialPerdaCombustivel(IAbastecimento abastecimento)
		{
			ProdutoEmpresa produtoEmpresa = _produtoServicoEmpresaRepositoryRead.FindOne(EntityBaseSpecification<ProdutoServicoEmpresa>.PorId(abastecimento.IdProduto)) as ProdutoEmpresa;
			List<string> list = new List<string>
			{
				string.Empty.PadRight(1),
				"PERDA DE COMBUSTÍVEIS",
				string.Empty.PadRight(1)
			};
			decimal num = produtoEmpresa.Estoque.Quantidade * -1m;
			list.Add($"{produtoEmpresa.ProdutoServico.CodigoInterno} {produtoEmpresa.ProdutoServico.Descricao}");
			list.Add($"#PE:TQ= {abastecimento.NumeroDoTanque.ToInt():00} VOL= {num:00,000.000} {abastecimento.DescricaoProduto}");
			_emissorService.ImprimirRelatorioPerdaCombustivel(list);
		}

		private AbastecimentoViewModel CriarAbastecimentoViewModel(IAbastecimento abastecimento, bool podeImprimir)
		{
			AbastecimentoViewModel abastecimentoViewModel = new AbastecimentoViewModel(abastecimento, _semComunicacao, _quebrasContinuidadeEncerranteResponse, _produtoServicoEmpresaRepositoryRead, PerdaComunicacaoTotal, _emissorService, _frentistas);
			abastecimentoViewModel.Selecionou += AbastecimentoViewModelOnSelecionou;
			if (!abastecimento.CaminhoImpressoraPista.IsNullOrEmpty() & podeImprimir)
			{
				ImprimirAbastecimentoImpressoraPista(abastecimento);
			}
			return abastecimentoViewModel;
		}

		private void AbastecimentoViewModelOnSelecionou(object sender, EventArgs eventArgs)
		{
			if (!(_emissorService is IEcfService))
			{
				RaisePropertyChanged(() => NumeroAbastecimentosToText);
				RaisePropertyChanged(() => NumeroAbastecimentosSelecionadosToText);
			}
			else if (Lista.Itens.Where((AbastecimentoViewModel x) => x.Selecionado).ToListEmptyWhenNull().Count > 3)
			{
				DialogoFactory.MostrarDialogoConfirma("Quantidade máxima de abastecimentos excedida!");
			}
		}

		private void ImprimirAbastecimentoImpressoraPista(IAbastecimento abastecimento)
		{
			if (!DadosSistema.ObterConfiguracaoClient().ObterConfiguracao().ImprimirComprovanteAbastecimento)
			{
				_emissorService.AtualizarImpressoComprovanteAbastecimento(abastecimento);
				return;
			}
			IRelatorio relatorio2;
			if (DadosSistema.TamanhoBobina != TamanhoBobina.CinquentaESeisCinquentaESeteCinquentaEOitoMilimetros)
			{
				IRelatorio relatorio = new RelatorioAbastecimento79Mm80Mm(abastecimento, DadosSistema.MargemEsquerdaImpressoraNaoFiscal, DadosSistema.RollPaper);
				relatorio2 = relatorio;
			}
			else
			{
				IRelatorio relatorio = new RelatorioAbastecimento56Mm57Mm58Mm(abastecimento, DadosSistema.MargemEsquerdaImpressoraNaoFiscal, DadosSistema.RollPaper);
				relatorio2 = relatorio;
			}
			IRelatorio relatorio3 = relatorio2;
			_impressoraNaoFiscalService.Imprimir(relatorio3, abastecimento.CaminhoImpressoraPista);
			_emissorService.AtualizarImpressoComprovanteAbastecimento(abastecimento);
		}

		private void ExecutarAcaoQuandoDocumentoFechado(BackgroundWorkerArgument backgroundWorkerArgument)
		{
			if (!ExecutarAcaoDocumentoFechado(backgroundWorkerArgument))
			{
				AdicionarNaListaAcoesQuandoEstadoDocumentoFechado(new Acao(backgroundWorkerArgument));
			}
		}

		private void ExecutarAcaoQuandoDocumentoFechado(BackgroundWorkerArgument backgroundWorkerArgument, NotificouSituacaoComunicacaoBicoResponse response)
		{
			if (!ExecutarAcaoDocumentoFechado(backgroundWorkerArgument) && !ObterNotificacaoComunicacaoAcao(response).IsNotNull())
			{
				AdicionarNaListaAcoesQuandoEstadoDocumentoFechado(new NotificacaoComunicacaoAcao(backgroundWorkerArgument, response.BicoNoSoftware, response.Situacao));
			}
		}

		private bool ExecutarAcaoDocumentoFechado(BackgroundWorkerArgument backgroundWorkerArgument)
		{
			int num;
			if (_seletorDireito.Get<PainelDocumentoFiscal>().Estado is DocumentoFiscalFechado)
			{
				num = (_emissorService.VerificarDocumentoFiscalFechado() ? 1 : 0);
				if (num != 0 && !_backgroundWorker.IsBusy)
				{
					_backgroundWorker.RunWorkerAsync(backgroundWorkerArgument);
				}
			}
			else
			{
				num = 0;
			}
			return (byte)num != 0;
		}

		private void AdicionarNaListaAcoesQuandoEstadoDocumentoFechado(Acao acao)
		{
			_acoesQuandoEstadoDocumentoFechado.Add(acao.Id, acao);
			if (_estadoDocumentoFechado.IsNotNull())
			{
				return;
			}
			_bwDocumentoFechado.DoWork += BwDocumentoFechadoOnDoWork;
			_bwDocumentoFechado.RunWorkerCompleted += BwDocumentoFechadoOnRunWorkerCompleted;
			_estadoDocumentoFechado = _seletorDireito.Get<PainelDocumentoFiscal>().WhenEstadoDocumentoFiscalChangedEvent.Where((IEstadoDocumentoFiscal x) => x is DocumentoFiscalFechado).Subscribe((IEstadoDocumentoFiscal x) =>
			{
				if (!_acoesQuandoEstadoDocumentoFechado.Any())
				{
					_estadoDocumentoFechado.Dispose();
					_estadoDocumentoFechado = null;
				}
				else
				{
					List<BackgroundWorkerArgument> argument = (from i in _acoesQuandoEstadoDocumentoFechado
						orderby i.Value.DataHora
						select i.Value.Action).ToListEmptyWhenNull();
					_acoesQuandoEstadoDocumentoFechado.Clear();
					if (!_bwDocumentoFechado.IsBusy)
					{
						_bwDocumentoFechado.RunWorkerAsync(argument);
					}
				}
			});
		}

		private void BwDocumentoFechadoOnRunWorkerCompleted(object sender, RunWorkerCompletedEventArgs runWorkerCompletedEventArgs)
		{
			if (!string.IsNullOrWhiteSpace(runWorkerCompletedEventArgs.Result.ToString()))
			{
				LoaderProcessoService.EsconderLoader();
				ThreadPrincipal.Executar(() =>
				{
					_seletorDireito.Get<IPainelMensagem>().AlterarMensagem(runWorkerCompletedEventArgs.Result.ToString());
				});
			}
			runWorkerCompletedEventArgs.Error?.ShowLastException();
		}

		private void BwDocumentoFechadoOnDoWork(object sender, DoWorkEventArgs doWorkEventArgs)
		{
			IEnumerable<BackgroundWorkerArgument> enumerable = (IEnumerable<BackgroundWorkerArgument>)doWorkEventArgs.Argument;
			if (enumerable.IsNull())
			{
				return;
			}
			doWorkEventArgs.Result = _seletorDireito.Get<IPainelMensagem>().Informacao;
			foreach (BackgroundWorkerArgument argument in enumerable)
			{
				if (!string.IsNullOrWhiteSpace(argument.Message))
				{
					LoaderProcessoService.MostrarLoader(argument.Message);
					ThreadPrincipal.Executar(() =>
					{
						_seletorDireito.Get<IPainelMensagem>().AlterarMensagem(argument.Message);
					});
				}
				argument.Action();
			}
		}

		private void RemoverAbastecimentos(IEnumerable<IAbastecimento> response)
		{
			foreach (IAbastecimento abastecimento in response)
			{
				ThreadPrincipal.Executar(() =>
				{
					AbastecimentoViewModel abastecimentoViewModel = Lista.Itens.FirstOrDefault((AbastecimentoViewModel x) => x.Abastecimento.Id == abastecimento.Id);
					if (!abastecimentoViewModel.IsNull())
					{
						abastecimentoViewModel.Selecionou -= AbastecimentoViewModelOnSelecionou;
						Lista.Remover(abastecimentoViewModel);
						RemoverListaBicos(abastecimentoViewModel.Abastecimento);
					}
				});
			}
		}

		private void NotificarPerdaComunicacaoTotal(PerdeuComunicacaoTotalResponse obj)
		{
			if (_emissorService.Is<IEcfService>())
			{
				AdicionarNotificacoes(obj.Notificacoes.ToArray());
				if (!PerdaComunicacaoTotal.IsNotNull())
				{
					PerdaComunicacaoTotal = new PerdaComunicacaoTotal(DateTime.Now);
					_perdaComunicacaoRepositoryWrite.Add(PerdaComunicacaoTotal);
					ExecutarAcaoQuandoDocumentoFechado(CriarAcaoImprimirPerdaComunicacao(obj.Notificacoes.ToArray()));
				}
			}
		}

		private void ImprimirRelatorioGerencialPerdaComunicacao(params NotificouSituacaoComunicacaoBicoResponse[] lista)
		{
			List<string> list = new List<string>
			{
				string.Empty.PadRight(1),
				"ALERTA: PERDA DE COMUNICACAO",
				string.Empty.PadRight(1)
			};
			list.AddRange(lista.Select((NotificouSituacaoComunicacaoBicoResponse x) => $"#PC:B{x.BicoNoSoftware:00} EF{x.Encerrante:0000000.000} ITPC:{x.DataHora:dd/MM/yyyy HH:mm:ss}"));
			_emissorService.ImprimirRelatorioPerdaComunicacao(list);
			_seletorDireito.Get<PainelDocumentoFiscal>()?.Informacao.ControlarFoco();
		}

		private void AdicionarNotificacoes(params NotificouSituacaoComunicacaoBicoResponse[] lista)
		{
			foreach (NotificouSituacaoComunicacaoBicoResponse notificouSituacaoComunicacaoBicoResponse in lista)
			{
				AdicionarNotificaoComunicacao(notificouSituacaoComunicacaoBicoResponse);
			}
		}

		private void AdicionarNotificaoComunicacao(NotificouSituacaoComunicacaoBicoResponse notificouSituacaoComunicacaoBicoResponse)
		{
			if (_emissorService.Tipo != TipoMovimentacao.CupomFiscal)
			{
				return;
			}
			if (notificouSituacaoComunicacaoBicoResponse.Situacao == SituacaoComunicacaoConcentrador.Perda && _semComunicacao.All((NotificouSituacaoComunicacaoBicoResponse x) => x.BicoNoSoftware != notificouSituacaoComunicacaoBicoResponse.BicoNoSoftware))
			{
				_semComunicacao.Add(notificouSituacaoComunicacaoBicoResponse);
			}
			else if (notificouSituacaoComunicacaoBicoResponse.Situacao == SituacaoComunicacaoConcentrador.Retorno && _semComunicacao.Any((NotificouSituacaoComunicacaoBicoResponse x) => x.BicoNoSoftware == notificouSituacaoComunicacaoBicoResponse.BicoNoSoftware))
			{
				_semComunicacao.Remove(_semComunicacao.FirstOrDefault((NotificouSituacaoComunicacaoBicoResponse x) => x.BicoNoSoftware == notificouSituacaoComunicacaoBicoResponse.BicoNoSoftware));
			}
			OnHabilitouNotaManualEvent(_semComunicacao.Any());
		}

		private void NotificarRetornoComunicacaoTotal(RetornouComunicacaoTotalResponse obj)
		{
			if (_emissorService.Is<IEcfService>())
			{
				AdicionarNotificacoes(obj.Notificacoes.ToArray());
				if (!PerdaComunicacaoTotal.IsNull())
				{
					PerdaComunicacaoTotal = null;
					_perdaComunicacaoRepositoryWrite.DeleteAll();
					ExecutarAcaoQuandoDocumentoFechado(CriarAcaoImprimirRetornoComunicacao(obj.Notificacoes.ToArray()));
				}
			}
		}

		private void ImprimirRelatorioGerencialRetornoComunicacao(params NotificouSituacaoComunicacaoBicoResponse[] lista)
		{
			List<string> list = new List<string>
			{
				string.Empty.PadRight(1),
				"ALERTA: RETORNO DE COMUNICACAO",
				string.Empty.PadRight(1)
			};
			list.AddRange(lista.Select((NotificouSituacaoComunicacaoBicoResponse notificacao) => $"#RC:B{notificacao.BicoNoSoftware:00} EI{notificacao.Encerrante:0000000.000} ITRC:{notificacao.DataHora:dd/MM/yyyy HH:mm:ss}"));
			_emissorService.ImprimirRelatorioRetornoComunicacao(list);
			_seletorDireito.Get<PainelDocumentoFiscal>()?.Informacao.ControlarFoco();
			EmitirCuponsFiscaisNotasManuaisContingencia(lista);
		}

		private void EmitirCuponsFiscaisNotasManuaisContingencia(IEnumerable<NotificouSituacaoComunicacaoBicoResponse> lista)
		{
			IEnumerable<PreDocumentoFiscalNotaManualPosto> source = _preDocumentoFiscalNotaManualPostoRepositoryRead.Find(EntityBaseSpecification<PreDocumentoFiscalNotaManualPosto>.All());
			if (!source.Any())
			{
				return;
			}
			foreach (NotificouSituacaoComunicacaoBicoResponse informacaoComunicacaoResponse in lista)
			{
				List<PreDocumentoFiscalNotaManualPosto> notasManuais = source.Where((PreDocumentoFiscalNotaManualPosto x) => x.BicoNoSoftware == informacaoComunicacaoResponse.BicoNoSoftware).ToListEmptyWhenNull();
				EmitirCuponsFiscaisPreDocumentoFiscalNotaManualPosto(notasManuais);
			}
		}

		private void NotificarSituacaoComunicacaoBico(NotificouSituacaoComunicacaoBicoResponse obj)
		{
			if (_emissorService.Is<IEcfService>())
			{
				AdicionarNotificacoes(obj);
				if (!PerdaComunicacaoTotal.IsNotNull())
				{
					BackgroundWorkerArgument backgroundWorkerArgument = ((obj.Situacao == SituacaoComunicacaoConcentrador.Perda) ? CriarAcaoImprimirPerdaComunicacao(obj) : CriarAcaoImprimirRetornoComunicacao(obj));
					ExecutarAcaoQuandoDocumentoFechado(backgroundWorkerArgument, obj);
				}
			}
		}

		private BackgroundWorkerArgument CriarAcaoImprimirPerdaComunicacao(params NotificouSituacaoComunicacaoBicoResponse[] lista)
		{
			return CriarAcao(() =>
			{
				ImprimirRelatorioGerencialPerdaComunicacao(lista);
			}, "Imprimindo relatório perda de comunicação");
		}

		private BackgroundWorkerArgument CriarAcaoImprimirRetornoComunicacao(params NotificouSituacaoComunicacaoBicoResponse[] lista)
		{
			return CriarAcao(() =>
			{
				ImprimirRelatorioGerencialRetornoComunicacao(lista);
			}, "Imprimindo relatório retorno de comunicação");
		}

		private NotificacaoComunicacaoAcao ObterNotificacaoComunicacaoAcao(NotificouSituacaoComunicacaoBicoResponse response)
		{
			string key = response.BicoNoSoftware + response.Situacao.RetornarDescricao();
			_acoesQuandoEstadoDocumentoFechado.TryGetValue(key, out var value);
			return value as NotificacaoComunicacaoAcao;
		}

		private void OnRecebeuQuebraContinuidadeEncerrante(QuebraContinuidadeEncerranteResponse quebraContinuidadeEncerrante)
		{
			if (!_quebrasContinuidadeEncerranteResponse.Exists((QuebraContinuidadeEncerranteResponse a) => a.IdBico == quebraContinuidadeEncerrante.IdBico))
			{
				_quebrasContinuidadeEncerranteResponse.Add(quebraContinuidadeEncerrante);
			}
			_seletorDireito.Get<PainelDocumentoFiscal>().Informacao.ControlarFoco();
		}

