		private void ProcessarRegistroNotaManualQuebraContinuidadeEncerrante(RegistroNotaManualQuebraContinuidadeEncerrante obj)
		{
			ExecutarAcaoDocumentoFechado(CriarAcao(() =>
			{
				DigisatServer.Domain.Main.Aggregates.CadastrosAgg.Pessoas.Pessoa byId = _pessoaRepositoryRead.GetById(ObjectId.Parse(_sessaoService.Sessao.Perfis.ItemSelecionado.Empresa.Id));
				foreach (NotaManualAbastecimento notasManuaisAbastecimento in obj.NotasManuaisAbastecimentos)
				{
					ProdutoServicoEmpresa produtoServicoEmpresa = _produtoServicoEmpresaRepositoryRead.FindOne(EntityBaseSpecification<ProdutoServicoEmpresa>.PorId(notasManuaisAbastecimento.Abastecimento.IdProduto));
					ItemDocumentoFiscalCombustivel item = FluentFactory<ItemDocumentoFiscalFactory>.Init().ComProdutoServicoLocal(FluentFactory<ProdutoServicoLocalFactory>.Init().ComProdutoServicoEmpresa(produtoServicoEmpresa).Criar()).ComAbastecimento(notasManuaisAbastecimento.Abastecimento)
						.Criar() as ItemDocumentoFiscalCombustivel;
					PreDocumentoFiscal preDocumentoFiscal = PreDocumentoFiscal.Criar(_preDocumentoFiscalRepositoryWrite, _movimentacaoRepositoryWrite, _operacaoFiscalRepositoryRead, _promocaoScanntechRepositoryRead, _emissorService, _sessaoService, new List<ItemDocumentoFiscal> { item }, byId);
					preDocumentoFiscal.SetarNumero(notasManuaisAbastecimento.NumeroNotaFiscal);
					PreDocumentoFiscalNotaManualPosto item2 = new PreDocumentoFiscalNotaManualPosto(preDocumentoFiscal);
					EmitirCuponsFiscaisPreDocumentoFiscalNotaManualPosto(new List<PreDocumentoFiscalNotaManualPosto> { item2 });
				}
				if (!obj.AbastecimentoRemanescente.IsNull())
				{
					ThreadPrincipal.Executar(() =>
					{
						_seletorDireito.Get<IPainelMensagem>().AlterarMensagemTimerComRetornoDaMensagemAnterior("Imprimindo cupom fiscal volume remanescente");
					});
					_emissorService.EmitirDocumentoFiscalAbastecimentos(obj.AbastecimentoRemanescente);
				}
			}));
		}

