		private void ProcessarAntesRegistrarDescontinuidadeEncerrante(AntesRegistrarDescontinuidadeEncerrante obj)
		{
			if (!_emissorService.Is<IEcfService>())
			{
				return;
			}
			LoaderProcessoService.MostrarLoader($"Faturando abastecimentos do bico {obj.NumeroBico}.");
			new Thread(() =>
			{
				try
				{
					List<IAbastecimento> list = (from x in Lista.Itens
						where x.Abastecimento.NumeroDoBicoNoSoftware == obj.NumeroBico
						select x.Abastecimento).ToListEmptyWhenNull();
					if (list.Any())
					{
						_emissorService.EmitirDocumentoFiscalAbastecimentos(list.ToArray());
					}
				}
				catch (Exception ex)
				{
					Exception ex2 = ex;
					Exception e = ex2;
					ThreadPrincipal.Executar(() =>
					{
						e.ShowLastException();
					});
				}
				finally
				{
					ThreadPrincipal.Executar(LoaderProcessoService.EsconderLoader);
				}
			}).Start();
		}

