		private bool PodeImportarAbastecimentos()
		{
			IEstadoDocumentoFiscal value = _seletorDireito.Get<PainelDocumentoFiscal>()?.Estado;
			if (value.IsNull() || value.Is<DocumentoFiscalBloqueado>() || value.Is<DocumentoFiscalCarregando>() || value.Is<DocumentoFiscalEmissorEmErro>())
			{
				return false;
			}
			if (_semComunicacaoPostoService || _semComunicacaoServidor)
			{
				return false;
			}
			if (!(_emissorService is IEcfService))
			{
				return Lista.Itens.Any((AbastecimentoViewModel x) => x.Selecionado);
			}
			if (!_jornadaFiscalAberta)
			{
				return false;
			}
			bool flag = _seletorDireito.Get<PainelTotalizacaoBase>().MensagensPromocionais.Any((IMensagemPromocional x) => x is ObservacaoPostoMensagemPromocional);
			int num = _seletorDireito.Get<PainelDocumentoFiscal>().Lista.Itens.OfType<ItemDocumentoFiscalCombustivel>().Count();
			int num2 = Lista.Itens.Count((AbastecimentoViewModel x) => x.Selecionado);
			if (flag && num2 + num > 1)
			{
				return false;
			}
			if (Lista.Itens.Any((AbastecimentoViewModel x) => x.Selecionado))
			{
				return num2 + num <= 3;
			}
			return false;
		}

		private Task ExcluirAbastecimentos()
		{
			return Task.Factory.StartNew(() =>
			{
				if (DialogoFactory.MostrarDialogoSimNao("Atenção! Este processo é irreversível. Deseja continuar?") == MessageBoxResult.Yes)
				{
					List<IAbastecimento> list = (from x in Lista.Itens
						where x.Selecionado
						select x.Abastecimento).ToListEmptyWhenNull();
					if (!_semComunicacaoServidor)
					{
						_emissorService.ExcluirAbastecimentos(list);
						_eventPublisher.Publish(new RemoverAbastecimentosRequest(list));
					}
				}
			}, CancellationToken.None, TaskCreationOptions.None, TaskScheduler.FromCurrentSynchronizationContext());
		}

		private bool PodeExcluirAbastecimentos()
		{
			if (!DadosSistema.IsPaf && !DadosSistema.VerificarPermissao<DigisatServer.Infrastructure.Crosscutting.Module.PontoDeVenda, PermitirExcluirAbastecimentoManual>())
			{
				return false;
			}
			IEstadoDocumentoFiscal value = _seletorDireito.Get<PainelDocumentoFiscal>()?.Estado;
			if (value.IsNull() || value.Is<DocumentoFiscalBloqueado>() || value.Is<DocumentoFiscalCarregando>() || value.Is<DocumentoFiscalEmissorEmErro>())
			{
				return false;
			}
			if ((from x in Lista.Itens
				where x.Selecionado
				select x.Abastecimento).ToListEmptyWhenNull().Any((IAbastecimento x) => !x.Manual))
			{
				return false;
			}
			if (_semComunicacaoPostoService || _semComunicacaoServidor)
			{
				return false;
			}
			if (!(_emissorService is IEcfService))
			{
				return Lista.Itens.Any((AbastecimentoViewModel x) => x.Selecionado);
			}
			if (!_jornadaFiscalAberta)
			{
				return false;
			}
			return Lista.Itens.Any((AbastecimentoViewModel x) => x.Selecionado);
		}

		private void RegistrarAfericao()
		{
			try
			{
				if (DialogoFactory.MostrarDialogoSimNao("Registrar aferição?") != MessageBoxResult.Yes)
				{
					return;
				}
				AutorizacaoDto autorizacaoDto = _sessaoService.VerificarPermissao<DigisatServer.Infrastructure.Crosscutting.Module.PontoDeVenda, PermitirRegistrarAfericao>();
				if (autorizacaoDto == null)
				{
					return;
				}
				_seletorDireito.Get<PainelDocumentoFiscal>()?.PreDocumentoFiscal?.AdicionarAutorizacao(autorizacaoDto);
				if (PerdaComunicacaoTotal.IsNotNull())
				{
					_seletorDireito.Get<PainelAfericaoManual>().SetarNotificacoesSemComunicacao(_semComunicacao);
					_seletorDireito.Selecionar<PainelAfericaoManual>();
					return;
				}
				List<IAbastecimento> abastecimentos = (from a in Lista.Itens
					where a.Selecionado
					select a.Abastecimento).ToListEmptyWhenNull();
				ImprimirRelatorioAfericoes(abastecimentos.ToArray());
				_service.Canal((IPostoCombustivelModuleService service) =>
				{
					service.AtualizarStatusAbastecimentosAfericao(abastecimentos.Select((IAbastecimento a) => a.Id));
				});
				_eventPublisher.Publish(new RemoverAbastecimentosRequest(abastecimentos));
			}
			catch (Exception ex)
			{
				ex.ShowLastException();
			}
		}

		public void ImprimirRelatorioAfericoes(params IAbastecimento[] abastecimentos)
		{
			List<string> impresso = new List<string> { " ", "AFERICAO DE BICO", " " };
			int num = ((DadosSistema.TamanhoBobina == TamanhoBobina.CinquentaESeisCinquentaESeteCinquentaEOitoMilimetros) ? 32 : 42);
			string text = (DadosSistema.IsPaf ? "" : "DATA/HORA");
			string text2 = "CODIGO - DESCRICAO".PadRight(num - text.Length, ' ');
			if (text2.Length + text.Length <= num)
			{
				impresso.Add($"{text2}{text}");
			}
			else
			{
				impresso.Add(text2);
				if (!DadosSistema.IsPaf)
				{
					impresso.Add(text.PadLeft(num, ' '));
				}
			}
			impresso.Add("".PadRight(num, '-'));
			foreach (IAbastecimento abastecimento in abastecimentos)
			{
				ProdutoServicoEmpresa produtoServicoEmpresa = _produtoServicoEmpresaRepositoryRead.FindOne(EntityBaseSpecification<ProdutoServicoEmpresa>.PorId(abastecimento.IdProduto));
				string text3 = (DadosSistema.IsPaf ? "" : $"{abastecimento.DataHora:dd/MM/yyyy HH:mm}");
				string text4 = $"{produtoServicoEmpresa.ProdutoServico.CodigoInterno} - {abastecimento.DescricaoProduto}";
				if (text3.Length + text4.Length <= num)
				{
					impresso.Add($"{text4.PadRight(num - text3.Length)}{text3}");
				}
				else
				{
					impresso.Add(text4.CopiarTexto(num));
					impresso.Add(text3.PadLeft(num, ' '));
				}
				if (!DadosSistema.IsPaf)
				{
					impresso.Add($"B{abastecimento.NumeroDoBicoNoSoftware:00} EI{abastecimento.EncerranteInicial:0000000.000} EF{abastecimento.EncerranteFinal:0000000.000} V{abastecimento.Litros:0.000}");
				}
				impresso.Add("".PadRight(num, '.'));
			}
			if (DadosSistema.IsPaf)
			{
				impresso.Add("".PadRight(num, '-'));
				impresso.AddRange(from afericao in abastecimentos
					orderby afericao.NumeroDoBicoNoSoftware
					select $"#AB:B{afericao.NumeroDoBicoNoSoftware:00} EI{afericao.EncerranteInicial:0000000.000} EF{afericao.EncerranteFinal:0000000.000} V{afericao.Litros:0.000}");
			}
			impresso.Add(" ");
			ExecutarAcaoDocumentoFechado(CriarAcao(() =>
			{
				_emissorService.ImprimirRelatorioAfericoes(impresso);
			}, "Imprimindo relatório de aferições"));
		}

