			{
				DateTime data = _emissorService.RetornarDataMovimento();
				List<IAbastecimento> second = ObterAbastecimentosVolumeRemanescente(data).ToListEmptyWhenNull();
				return (from x in Lista.Itens
					where x.Abastecimento.DataHora.Date < data
					select x.Abastecimento into x
					orderby x.DataHora
					select x).ToListEmptyWhenNull().Union(second).ToListEmptyWhenNull();
			}
			catch (Exception)
			{
				return Enumerable.Empty<IAbastecimento>();
			}
		}

