		public IEnumerable<string> ObterRelatorioBicosSemComunicacao(IEnumerable<BicoSemComunicacao> bicos)
		{
			if (!bicos.Any())
			{
				return Enumerable.Empty<string>();
			}
			List<string> list = new List<string>();
			list.Add(string.Empty.PadRight(1));
			list.Add("ALERTA: SEM COMUNICAÇÃO");
			list.Add(string.Empty.PadRight(1));
			list.AddRange(bicos.Select((BicoSemComunicacao bico) =>
			{
				CalculoTempo calculoTempo = new CalculoTempo((decimal)(DateTime.Now - bico.DataHoraPerda).TotalHours);
				return $"#SC:B{bico.BicoNoSoftware:00} ITPC:{bico.DataHoraPerda:dd/MM/yyyy HH:mm:ss} TEMPO:{calculoTempo.TempoString}";
			}).ToList());
			return list;
		}

