		public void SetarModoFuncionamento(IModoFuncionamento modoFuncionamento)
		{
			_emissorService = modoFuncionamento.EmissorService;
			if ((Lista != null) & (Lista.Numero > 0))
			{
				foreach (AbastecimentoViewModel iten in Lista.Itens)
				{
					iten.SetarEmissorService(_emissorService);
				}
			}
			_seletorDireito = modoFuncionamento.SeletorDireito;
			_seletorEsquerdo = modoFuncionamento.SeletorEsquerdo;
			_emissorDisposable?.Dispose();
			_emissorDisposable = new CompositeDisposable { _emissorService.WhenAlterouEstadoJornadaFiscalAbertaEvent.Subscribe((bool jornadaFiscal) =>
			{
				_jornadaFiscalAberta = jornadaFiscal;
				RaisePropertyChanged(() => CtrlQCommand);
			}) };
			ControlarDocumentoFiscalBloqueadoSemComunicacaoServidor();
		}

		private void ControlarDocumentoFiscalBloqueadoSemComunicacaoServidor()
		{
			if (!_emissorService.Is<IEcfService>())
			{
				if (_semComunicacaoServidor)
				{
					_seletorDireito.Get<PainelDocumentoFiscal>()?.BloquearDocumentoFiscalSemComunicacaoServidor();
				}
				else
				{
					_seletorDireito.Get<PainelDocumentoFiscal>()?.DesbloquearDocumentoFiscal();
				}
			}
		}

		protected virtual void OnHabilitouNotaManualEvent(bool e)
		{
			HabilitouNotaManualEvent?.Invoke(this, e);
		}

		private void SelecionarTodos()
		{
			foreach (AbastecimentoViewModel item in Lista.Itens.Where((AbastecimentoViewModel x) => x.VisivelNaTela))
			{
				item.Selecionado = TodosSelecionados;
			}
		}
	}
