		public PainelEsquerdoQrCode SetarQrCode(string qrCodeText)
		{
			PagamentoAprovado = false;
			string text = ExtrairBase64MultiplasOpcoes(qrCodeText);
			if (text != null)
			{
				QrCode = LoadBase64(text).ImageToByte().ToBitmapSource();
			}
			return this;
		}

		private static string ExtrairBase64MultiplasOpcoes(string qrCodeText)
		{
			foreach (string item in new List<string> { "^data:image\\/[a-zA-Z]+;base64,([A-Za-z0-9+/=]+)", "data:image\\/[^;]+;charset=utf-8;base64,([A-Za-z0-9+/=]+)", "data:image\\/png;base64,([A-Za-z0-9+/=]+)", "data:image\\/jpeg;base64,([A-Za-z0-9+/=]+)", "data:image\\/gif;base64,([A-Za-z0-9+/=]+)" })
			{
				Match match = Regex.Match(qrCodeText, item);
				if (match.Success)
				{
					return match.Groups[1].Value;
				}
			}
			return null;
		}

		public static Bitmap LoadBase64(string base64)
		{
			using MemoryStream stream = new MemoryStream(Convert.FromBase64String(base64));
			return (Bitmap)System.Drawing.Image.FromStream(stream);
		}

