		public override async void Load()
		{
			await DadosSistema.GetService().Canal((IPostoCombustivelRelatorioModuleService service) => service.ObterTanques()).ContinueWith((Task<IEnumerable<TanqueDto>> task) =>
			{
				ThreadPrincipal.Executar(() =>
				{
					AdicionarTanques(task.Result);
				});
			});
		}

		private void AdicionarTanques(IEnumerable<TanqueDto> tanques)
		{
			foreach (TanqueDto tanque in tanques.OrderBy((TanqueDto x) => x.Numero))
			{
				TanqueStatusViewModel tanqueStatusViewModel = Lista.Itens.FirstOrDefault((TanqueStatusViewModel x) => x.NumeroTanque == tanque.Numero);
				if (tanqueStatusViewModel.IsNull())
				{
					decimal quantidadeEstoque = tanque.Bombas.SelectMany((BombaDto x) => x.Bicos.Select((BicoDto y) => y.ProdutoServicoEmpresa)).DistinctBy((ProdutoServicoEmpresaDto x) => x.Id).Sum((ProdutoServicoEmpresaDto y) => y.ProdutoEmpresa.Estoque.Quantidade);
					Lista.Adicionar(new TanqueStatusViewModel(tanque.Numero, tanque.Descricao, tanque.CapacidadeNominal, tanque.Quantidade, quantidadeEstoque));
				}
				else
				{
					tanqueStatusViewModel.Atualizar(tanque);
				}
			}
			Lista.PosicionarNoPrimeiro();
		}

