	{
		private readonly Seletor<IPainel> _seletor;

		public IReadOnlyCollection<string> Atalhos => new List<string>();

		public IEnumerable<ItemMenuAtalho> MenuRibbon => Enumerable.Empty<ItemMenuAtalho>();

		public bool MostrarTecladoEspecieCompacto => System.Windows.Application.Current.MainWindow.ActualWidth < 1680.0;

		public decimal TotalSelecionado => DivisoesConta.Itens.Where((ItemDivisaoConta a) => a.Selecionado).Sum((ItemDivisaoConta a) => a.Valor);

		public int NumeroPessoasDivisaoConta
		{
			get
			{
				return GetProperty(() => NumeroPessoasDivisaoConta);
			}
			set
			{
