			}
		}

		public Lista<ItemDivisaoConta> DivisoesConta { get; set; } = new Lista<ItemDivisaoConta>();

		public bool MostrarPainelDivisao
		{
			get
			{
				return GetProperty(() => MostrarPainelDivisao);
			}
			set
			{
				SetProperty(() => MostrarPainelDivisao, value, () =>
				{
