		public PainelEsquerdoTotalizacao(Seletor<IPainel> seletor)
		{
			_seletor = seletor;
			F2Command = new DelegateCommand(DividirConta, () => NumeroPessoasDivisaoConta > 1);
			CtrlWCommand = new DelegateCommand(() =>
			{
				EsconderDivisao();
				_seletor.Get<PainelTotalizacaoBase>().Informacao.ControlarFoco();
			});
			DivideCommand = new DelegateCommand(() =>
			{
				EsconderDivisao();
				MostrarPainelDivisao = true;
			}, () => _seletor.Get<PainelTotalizacaoBase>().Troco > 0m);
			SpaceCommand = new DelegateCommand(() =>
			{
				DivisoesConta.ItemSelecionado.Selecionar();
			}, () => DivisoesConta.PossuiItemSelecionado && DivisoesConta.ItemSelecionado.PodeSelecionar());
			DivisoesConta.WhenAdicionouItem.Subscribe((ItemDivisaoConta x) =>
			{
				x.AlterouItemSelecionadoEvent += OnAlterouItemSelecionadoEvent;
			});
		}

		private void EsconderDivisao()
		{
