		public void SetarModoFuncionamento(IModoFuncionamento modoFuncionamento)
		{
		}

		public decimal AdicionarValor(decimal valor, ItemPagamentoViewModel itemPagamentoViewModel)
		{
			EspeciePagamento especiePagamento = itemPagamentoViewModel.EspeciePagamento;
			if (valor < TotalSelecionado)
			{
				throw new Exception("Não é possível informar valor menor que o correspondente a parte dividida");
			}
			if (!DivisoesConta.Itens.Where((ItemDivisaoConta a) => a.Selecionado).ToListEmptyWhenNull().Any())
			{
				return valor;
			}
			decimal totalSelecionado = TotalSelecionado;
			if (valor == _seletor.Get<PainelTotalizacaoBase>().Troco)
			{
				valor = totalSelecionado;
			}
			if (valor <= totalSelecionado)
			{
				return ProcessarConfirmacaoValorRecebido(valor, itemPagamentoViewModel, especiePagamento, totalSelecionado, registrarTroco: true);
			}
			List<ItemDivisaoConta> list = DivisoesConta.Itens.Where((ItemDivisaoConta a) => !a.Selecionado && a.ValorRecebido == 0m).ToListEmptyWhenNull();
			if (list.Count == 0)
			{
				return ProcessarConfirmacaoValorRecebido(valor, itemPagamentoViewModel, especiePagamento, totalSelecionado, registrarTroco: true);
			}
			if (DialogoFactory.MostrarDialogoSimNao("O valor informado é maior que a soma dos itens selecionados.\nDeseja receber o valor e recalcular as demais partes?") != MessageBoxResult.Yes)
			{
				if (especiePagamento.Codigo != 1 && especiePagamento.Codigo != 4)
				{
					throw new Exception($"Não é permitido troco em {especiePagamento.Descricao}.");
				}
				return ProcessarConfirmacaoValorRecebido(valor, itemPagamentoViewModel, especiePagamento, totalSelecionado, registrarTroco: true);
			}
			totalSelecionado = valor;
			decimal num = _seletor.Get<PainelTotalizacaoBase>().Troco - valor;
			if (num < 0m)
			{
				num = 0m;
			}
			decimal valor2 = (num / (decimal)list.Count).TruncarDuasCasasDecimais();
			foreach (ItemDivisaoConta item in list)
			{
				item.ComValor(valor2);
			}
			decimal num2 = num - list.Sum((ItemDivisaoConta a) => a.Valor);
			if (num2 > 0m)
			{
				list.Last().Valor += num2;
			}
			foreach (ItemDivisaoConta item2 in list)
			{
				DivisoesConta.Remover(item2);
			}
			DivisoesConta.Adicionar(list);
			DivisoesConta.WhenAdicionouItem.Subscribe((ItemDivisaoConta x) =>
			{
				x.AlterouItemSelecionadoEvent -= OnAlterouItemSelecionadoEvent;
			});
			DivisoesConta.WhenAdicionouItem.Subscribe((ItemDivisaoConta x) =>
			{
				x.AlterouItemSelecionadoEvent += OnAlterouItemSelecionadoEvent;
			});
			return ProcessarConfirmacaoValorRecebido(valor, itemPagamentoViewModel, especiePagamento, totalSelecionado);
		}

		private decimal ProcessarConfirmacaoValorRecebido(decimal valor, ItemPagamentoViewModel itemPagamentoViewModel, EspeciePagamento especiePagamento, decimal valorSelecionado, bool registrarTroco = false)
		{
			if (especiePagamento.Codigo != 2 && especiePagamento.Codigo != 7 && especiePagamento.Codigo != 24 && especiePagamento.Codigo != 26 && especiePagamento.Codigo != 25 && especiePagamento.Codigo != 27 && !(itemPagamentoViewModel is ValeDetalhadoRestauranteViewModel))
			{
				ConfirmarValorRecebido(valor, itemPagamentoViewModel, registrarTroco);
			}
			return valorSelecionado;
		}

		public void ConfirmarValorRecebido(decimal valor, ItemPagamentoViewModel itemPagamentoViewModel, bool registrarTroco = false)
		{
			EspeciePagamento especiePagamento = itemPagamentoViewModel.EspeciePagamento;
			List<ItemDivisaoConta> list = DivisoesConta.Itens.Where((ItemDivisaoConta a) => a.Selecionado).ToListEmptyWhenNull();
			if (!list.Any())
			{
				return;
			}
			foreach (ItemDivisaoConta item in list)
			{
				if (!registrarTroco)
				{
					item.Valor = (valor / (decimal)list.Count).TruncarDuasCasasDecimais();
				}
				item.ValorRecebido = (registrarTroco ? item.Valor : (valor / (decimal)list.Count).TruncarDuasCasasDecimais());
				item.DescricaoEspecie = especiePagamento.Descricao;
			}
			decimal num = list.Sum((ItemDivisaoConta x) => x.Valor);
			list.Last().ValorRecebido += valor - num;
			DivisoesConta.Posicionar((ItemDivisaoConta x) => x.ValorRecebido == 0m);
			if (DivisoesConta.PossuiItemSelecionado && DivisoesConta.ItemSelecionado.ValorRecebido == 0m)
			{
				DivisoesConta.ItemSelecionado.Selecionar();
			}
		}

		private void AdicionarContas(int numeroPessoasDivisaoConta)
		{
			DivisoesConta.Limpar();
			decimal troco = _seletor.Get<PainelTotalizacaoBase>().Troco;
			decimal valor = (troco / (decimal)numeroPessoasDivisaoConta).TruncarDuasCasasDecimais();
			for (int i = 0; i < numeroPessoasDivisaoConta; i++)
			{
				DivisoesConta.Adicionar(ItemDivisaoConta.Criar().ComValor(valor));
			}
			decimal num = troco - DivisoesConta.Itens.Sum((ItemDivisaoConta a) => a.Valor);
			if (num > 0m)
			{
				DivisoesConta.Itens.Last().Valor += num;
			}
			DivisoesConta.PosicionarNoPrimeiro();
			DivisoesConta.ItemSelecionado.Selecionar();
		}
	}
	public class ItemDivisaoConta : BindableBase
	{
		public bool Selecionado
		{
			get
			{
				return GetProperty(() => Selecionado);
			}
			set
			{
				SetProperty(() => Selecionado, value, () =>
				{
					OnAlterouItemSelecionadoEvent(this);
				});
			}
		}

		public string DescricaoEspecie
		{
			get
			{
				return GetProperty(() => DescricaoEspecie);
			}
			set
			{
				SetProperty(() => DescricaoEspecie, value);
			}
		}

		public decimal Valor { get; set; }

		public decimal ValorRecebido
		{
			get
			{
				return GetProperty(() => ValorRecebido);
			}
			set
			{
				SetProperty(() => ValorRecebido, value, () =>
				{
					RaisePropertyChanged(() => Troco);
					if (value > 0m)
					{
						Selecionado = false;
					}
				});
			}
		}

		public decimal Troco => ValorRecebido - Valor;

		public event EventHandler<ItemDivisaoConta> AlterouItemSelecionadoEvent;

		public static ItemDivisaoConta Criar()
		{
			return new ItemDivisaoConta();
		}

		public ItemDivisaoConta ComValor(decimal valor)
		{
			Valor = valor;
			return new ItemDivisaoConta
			{
				Valor = valor
			};
		}

		public void Selecionar()
		{
			Selecionado = !Selecionado;
		}

		public bool PodeSelecionar()
		{
			return ValorRecebido == 0m;
		}

		protected virtual void OnAlterouItemSelecionadoEvent(ItemDivisaoConta e)
		{
			if (ValorRecebido == 0m)
			{
				AlterouItemSelecionadoEvent?.Invoke(this, e);
			}
		}
	}
	public class PainelEstoqueFisicoCombustivel : PainelInteracao<PainelEstoqueFisicoCombustivel>
	{
		private readonly IWService _service;

		private readonly IEmissorService _emissorService;

		private readonly Seletor<IPainel> _seletor;

		private readonly Lista<EstoqueFisicoCombustivel> _lista = new Lista<EstoqueFisicoCombustivel>();

		private Action _acao;

		public override string Titulo => "Lançamento mensal de estoque físico de combustíveis";

		public PainelEstoqueFisicoCombustivel()
		{
		}

		public PainelEstoqueFisicoCombustivel(IWService service, IEmissorService emissorService, Seletor<IPainel> seletor)
			: base(seletor)
		{
			_service = service;
			_emissorService = emissorService;
			_seletor = seletor;
			F2Command = new AsyncCommand(F2MethodAsync, CanF2Method, allowMultipleExecution: false);
		}

		public override void Load()
		{
			Campos.Clear();
			ObterTanques();
			Campos.Insert(0, ItemInteracaoBase<ItemInteracaoEstoqueFisicoCombustivel, Lista<EstoqueFisicoCombustivel>>.Criar().ComDescricao("Ao finalizar movimentação mensal informe a quantidade, em litros, do combustível contido em cada tanque, apurado por meio da medição efetuada com régua ou com equipamento medidor de combustível.").ComValor(_lista)
				.Build());
		}

		private void ObterTanques()
		{
			if (_lista.Numero > 0)
			{
				ThreadPrincipal.Executar(() =>
				{
					_lista.Limpar();
				});
			}
			foreach (TanqueDto tanque in _service.Canal((ITanqueModuleService service) => service.PesquisarAtivosAsync(string.Empty, 1, short.MaxValue)).Result.Lista.Cast<TanqueDto>())
			{
				ThreadPrincipal.Executar(() =>
				{
					_lista.Adicionar(from g in tanque.Bombas.SelectMany((BombaDto b) => b.Bicos)
						group g by g.ProdutoServicoEmpresa.ProdutoServico.Descricao into y
						select new EstoqueFisicoCombustivel(tanque.Numero, y.Key));
				});
			}
		}

		public void SetarAcaoAoConcluir(Action acao)
		{
			_acao = acao;
		}

		public override bool PodeVoltar()
		{
			return false;
		}

		protected override bool CanF2Method()
		{
			return _lista.Itens.All((EstoqueFisicoCombustivel x) => x.Volume > 0m);
		}

		private async Task F2MethodAsync()
		{
			if (DialogoFactory.MostrarDialogoSimNao("Atenção! Os dados informados não poderão ser alterados. Deseja continuar?") != MessageBoxResult.Yes)
			{
				return;
			}
			List<string> linhas = new List<string> { "ESTOQUE FISICO DE COMBUSTIVEIS" };
			linhas.AddRange(_lista.Itens.Select((EstoqueFisicoCombustivel tanque) => string.Format("#EF:TA={0} VOL={1} {2}", tanque.NumeroTanque.ToStringLeftZero(2), tanque.Volume.ToString("00,000.000", new CultureInfo("pt-BR")), tanque.Combustivel)));
			LoaderProcessoService.MostrarLoader("Imprimindo relatório estoque físico combustíveis...");
			await Task.Factory.StartNew(() =>
			{
				_emissorService.ImprimirRelatorioGerencialEstoqueFisicoCombustivel(linhas);
				_service.Canal((IPostoCombustivelModuleService service) =>
				{
					service.AdicionarRegistroEstoqueFisicoCombustivel(_emissorService.RetornarDataMovimento());
				});
				_acao?.Invoke();
			}).ContinueWith((Task task) =>
			{
				LoaderProcessoService.EsconderLoader();
				if (task.IsFaulted)
				{
					task.Exception.ShowLastException();
				}
				_seletor.Voltar();
			}, CancellationToken.None, TaskContinuationOptions.None, TaskScheduler.FromCurrentSynchronizationContext());
		}

		protected override void F2Method()
		{
		}

		public override void Dispose()
		{
		}

		public override void UnLoad()
		{
			Campos.Clear();
			_lista.Limpar();
		}
	}
	public class PainelFechamentoTurno : PainelInteracao<PainelAberturaTurno>
	{
		private readonly IEmissorService _emissorService;

		private readonly IWService _service;

		private readonly Seletor<IPainel> _seletorEsquerdo;

		private readonly ISessaoService _sessaoService;

		private ItemInteracaoDecimalFocusable _totalEspecie;

		private ItemInteracaoDecimal _totalCheque;

		private ItemInteracaoDecimal _totalCartao;

		private ItemInteracaoDecimal _totalVale;

		private ItemInteracaoDecimal _totalDepositoBancario;

		private ItemInteracaoDecimal _totalTed;

		private ItemInteracaoDecimal _totalDoc;

		private ItemInteracaoDecimal _totalValePresente;

		private ItemInteracaoDecimal _totalOutrasEspecies;

		private ItemInteracaoDecimal _totalCarteirasDigitais;

		private ItemInteracaoDecimal _totalPrazo;

		private ItemInteracaoDecimal _totalCreditoLoja;

		private ItemInteracaoTexto _observacao;

		private TurnoDto _turnoDto;

		private bool _navegouPainelPendenciasNfce;

		private readonly SincronizacaoService _sincronizacaoService;

		public bool Processando
		{
			get
			{
				return GetProperty(() => Processando);
			}
			set
			{
				SetProperty(() => Processando, value);
			}
		}

		public override string Titulo => "Fechar turno";

		public PainelFechamentoTurno()
		{
		}

		public PainelFechamentoTurno(IRepositoryRead<Movimentacao> movimentacaoRepositoryRead, IRepositoryRead<RegistroPafEcf> registroPafEcfRepositoryRead, IRepositoryRead<DigisatServer.Domain.Main.Aggregates.AuxiliaresAgg.Pbms.TransacaoPbm> transacaoPbmRepositoryRead, IEmissorService emissorService, IWService service, Seletor<IPainel> seletorEsquerdo, Seletor<IPainel> seletorDireito, ISessaoService sessaoService)
			: base(seletorDireito)
		{
			_emissorService = emissorService;
			_service = service;
			_seletorEsquerdo = seletorEsquerdo;
			_sessaoService = sessaoService;
			_totalEspecie = ItemInteracaoBase<ItemInteracaoDecimalFocusable, decimal>.Criar().ComDescricao("Total em espécie").Build();
			_totalCheque = ItemInteracaoBase<ItemInteracaoDecimal, decimal>.Criar().ComDescricao("Total em cheque").Build();
			_totalCartao = ItemInteracaoBase<ItemInteracaoDecimal, decimal>.Criar().ComDescricao("Total em cartão").Build();
			_totalVale = ItemInteracaoBase<ItemInteracaoDecimal, decimal>.Criar().ComDescricao("Total em vale").Build();
			_totalDepositoBancario = ItemInteracaoBase<ItemInteracaoDecimal, decimal>.Criar().ComDescricao("Total em depósito bancário").Build();
			_totalTed = ItemInteracaoBase<ItemInteracaoDecimal, decimal>.Criar().ComDescricao("Total em TED").Build();
			_totalDoc = ItemInteracaoBase<ItemInteracaoDecimal, decimal>.Criar().ComDescricao("Total em DOC").Build();
			_totalValePresente = ItemInteracaoBase<ItemInteracaoDecimal, decimal>.Criar().ComDescricao("Total em vale presente").Build();
			_totalCarteirasDigitais = ItemInteracaoBase<ItemInteracaoDecimal, decimal>.Criar().ComDescricao("Total em carteiras digitais").Build();
			_totalCreditoLoja = ItemInteracaoBase<ItemInteracaoDecimal, decimal>.Criar().ComDescricao("Total em crédito loja").Build();
			_totalOutrasEspecies = ItemInteracaoBase<ItemInteracaoDecimal, decimal>.Criar().ComDescricao("Total em outras espécies").Build();
			_observacao = ItemInteracaoBase<ItemInteracaoTexto, string>.Criar().ComDescricao("Observação").Build();
			_totalPrazo = ItemInteracaoBase<ItemInteracaoDecimal, decimal>.Criar().ComDescricao("Total em prazo/pgto posterior").Build();
			Campos.Add(_totalEspecie);
			Campos.Add(_totalCheque);
			Campos.Add(_totalCartao);
			Campos.Add(_totalVale);
			Campos.Add(_totalValePresente);
			Campos.Add(_totalCreditoLoja);
			Campos.Add(_totalCarteirasDigitais);
			Campos.Add(_totalOutrasEspecies);
			if (emissorService.IsNot<IEcfService>() && emissorService.IsNot<INotaManualService>())
			{
				Campos.Add(_totalDepositoBancario);
				Campos.Add(_totalTed);
				Campos.Add(_totalDoc);
			}
			Campos.Add(_totalPrazo);
			Campos.Add(_observacao);
			_sincronizacaoService = new SincronizacaoService(movimentacaoRepositoryRead, registroPafEcfRepositoryRead, transacaoPbmRepositoryRead, service);
		}

		public override void Load()
		{
			new Thread(async () =>
			{
				Processando = true;
				LoaderProcessoService.MostrarLoader("Verificando turno aberto...");
				try
				{
					_turnoDto = _service.Canal((ITurnoModuleService service) => service.ObterTurnoAbertoDoUsuarioLogadoAsync().Result);
					if (_turnoDto.Is<TurnoDtoNull>())
					{
						throw new Exception("Nenhum turno aberto");
					}
					await Sincronizar();
					VerificarFechamentoTurnoPostoCombustivel();
					AbrirGaveta();
				}
				catch (Exception ex)
				{
					Exception ex2 = ex;
					Exception e = ex2;
					ThreadPrincipal.Executar(() =>
					{
						e.ShowLastException();
						Seletor.Voltar();
					});
				}
				finally
				{
					LoaderProcessoService.EsconderLoader();
					Processando = false;
					RaisePropertyChanged(() => Processando);
					RecuperarFoco();
				}
			}).Start();
		}

		private void AbrirGaveta()
		{
			if (_sessaoService.VerificarPermissao<DigisatServer.Infrastructure.Crosscutting.Module.PontoDeVenda, PermitirAbrirGaveta>() != null)
			{
				_emissorService.AbrirGaveta();
			}
		}

		public async Task Sincronizar()
		{
			_sincronizacaoService.DataInicial = DateTime.Today;
			_sincronizacaoService.DataFinal = DateTime.Today;
			await _sincronizacaoService.Processar().ContinueWith((Task task) =>
			{
				if (_sincronizacaoService.Erros.Any())
				{
					DialogoFactory.MostrarDialogoConfirma("Falha ao sincronizar: \n" + string.Join(Environment.NewLine, _sincronizacaoService.Erros.Select((string x) => x)));
				}
				LoaderProcessoService.EsconderLoader();
			}, CancellationToken.None, TaskContinuationOptions.None, TaskScheduler.Default);
		}

		private void VerificarFechamentoTurnoPostoCombustivel()
		{
			if (_navegouPainelPendenciasNfce)
			{
				return;
			}
			if (DadosSistema.IsPostoCombustivel && (_emissorService.Tipo == TipoMovimentacao.CupomFiscal || _emissorService.Tipo == TipoMovimentacao.NotaFiscalConsumidorEletronica))
			{
				List<IAbastecimento> abastecimentosPendentes = _seletorEsquerdo.Get<PainelEsquerdoPosto>().Lista.Itens.Select((AbastecimentoViewModel x) => x.Abastecimento).ToListEmptyWhenNull();
				if (!abastecimentosPendentes.Any())
				{
					VerificarNotasFicaisConsumidorEletronicasComPendencias();
					return;
				}
				ThreadPrincipal.Executar(() =>
				{
					_emissorService.EmitirDocumentoFiscalAbastecimentosFechamentoTurno(Seletor.VoltarTudo, VerificarNotasFicaisConsumidorEletronicasComPendencias, abastecimentosPendentes.ToArray());
				});
			}
			else
			{
				VerificarNotasFicaisConsumidorEletronicasComPendencias();
			}
		}

		private void VerificarNotasFicaisConsumidorEletronicasComPendencias()
		{
			if (!_emissorService.Is<INfceService>())
			{
				return;
			}
			IEnumerable<MovimentacaoBaseDto> movimentacoes = _service.Canal((INotaFiscalConsumidorEletronicaModuleService service) => service.ObterNfceComPendenciasTurno(_turnoDto.Id, _turnoDto.DataHoraAbertura, DateTime.Now)).Result;
			if (movimentacoes.Any())
			{
				ThreadPrincipal.Executar(() =>
				{
					Seletor.Get<PainelResumoNfceTurno>().SetarMovimentacoesComPendencias(movimentacoes);
					Seletor.Get<PainelResumoNfceTurno>().SetarTurno(_turnoDto);
					Seletor.Selecionar<PainelResumoNfceTurno>();
					_navegouPainelPendenciasNfce = true;
				});
			}
		}

		public override void UnLoad()
		{
			_emissorService.VerificarEstado();
			Limpar();
		}

		public override void FecharMethod()
		{
			base.FecharMethod();
			_navegouPainelPendenciasNfce = false;
		}

		public override bool PodeVoltar()
		{
			return true;
		}

		public override void Dispose()
		{
			_totalEspecie = null;
			_totalCartao = null;
			_totalCheque = null;
			_totalVale = null;
			_totalDepositoBancario = null;
			_totalTed = null;
			_totalDoc = null;
			_totalOutrasEspecies = null;
			_totalCreditoLoja = null;
			_totalValePresente = null;
			_totalCarteirasDigitais = null;
			_observacao = null;
			_totalPrazo = null;
		}

		protected override void Limpar()
		{
			_totalEspecie.Limpar();
			_totalCartao.Limpar();
			_totalCheque.Limpar();
			_totalVale.Limpar();
			_totalDepositoBancario.Limpar();
			_totalTed.Limpar();
			_totalDoc.Limpar();
			_totalOutrasEspecies.Limpar();
			_totalValePresente.Limpar();
			_totalCreditoLoja.Limpar();
			_totalCarteirasDigitais.Limpar();
			_observacao.Limpar();
			_totalPrazo.Limpar();
		}

		protected override void F2Method()
		{
			try
			{
				if (DadosSistema.AutenticacaoService.Instancia.VerificarPermissao<Turno, PermitirFecharTurno>() != null)
				{
					_turnoDto.Fechamento = new FechamentoDto
					{
						Observacao = _observacao.Valor,
						TotalEspecie = _totalEspecie.Valor,
						TotalCartao = _totalCartao.Valor,
						TotalCheque = _totalCheque.Valor,
						TotalVale = _totalVale.Valor,
						TotalDepositoBancario = _totalDepositoBancario.Valor,
						TotalTed = _totalTed.Valor,
						TotalDoc = _totalDoc.Valor,
						TotalValePresente = _totalValePresente.Valor,
						TotalOutrasEspecies = _totalOutrasEspecies.Valor,
						TotalCarteirasDigitais = _totalCarteirasDigitais.Valor,
						TotalPrazo = _totalPrazo.Valor,
						TotalCreditoLoja = _totalCreditoLoja.Valor
					};
					ImpressaoTurnoService impressaoTurnoService = new ImpressaoTurnoService(_emissorService, _service);
					TurnoDto turnoDto = _service.Canal((ITurnoModuleService service) => service.FecharTurnoAsync(_turnoDto).Result);
					_turnoDto.Fechamento.DataHoraFechamento = turnoDto.Fechamento.DataHoraFechamento;
					impressaoTurnoService.ExecutarFechamentoTurno(_turnoDto, turnoDto.Id);
					DialogoFactory.MostrarDialogoConfirma("O turno foi fechado");
					DadosSistema.SetarTurnoAbertoDoUsuario(turnoAberto: false);
					Seletor.Voltar();
				}
			}
			catch (Exception ex)
			{
				ex.ShowLastException();
			}
		}

		protected override bool CanF2Method()
		{
			if (base.CanF2Method() && _emissorService.Carregado && _emissorService.Pronto)
			{
				return !Processando;
			}
			return false;
		}
	}
	public class PainelGestaoAbastecimento : PainelInteracao<PainelGestaoAbastecimento>
	{
		private readonly IWService _service;

		private readonly ItemInteracaoDataHoraFocusable _dataInicial;

		private readonly ItemInteracaoDataHora _dataFinal;

		private readonly ItemInteracaoListaAbastecimento _listaAbastecimento;

		private IEnumerable<AbastecimentoDto> _abastecimentos = new List<AbastecimentoDto>();

		public override string Titulo => "Gerenciar abastecimento";

		public override string DescricaoDoBotao => "Tornar pendente";

		public ICommand F3Command { get; set; }

		public PainelGestaoAbastecimento()
		{
		}

		public PainelGestaoAbastecimento(IWService service, Seletor<IPainel> seletorDireito)
			: base(seletorDireito)
		{
			_service = service;
			_dataInicial = ItemInteracaoBase<ItemInteracaoDataHoraFocusable, DateTime>.Criar().ComDescricao("Data inicial").ComValor(DateTime.Now)
				.Build();
			_dataFinal = ItemInteracaoBase<ItemInteracaoDataHora, DateTime>.Criar().ComDescricao("Data final").ComValor(DateTime.Now)
				.Build();
			F3Command = new DelegateCommand(Pesquisar, PodePesquisar);
			_listaAbastecimento = ItemInteracaoBase<ItemInteracaoListaAbastecimento, Lista<ItemAbastecimento>>.Criar().ComValor(new Lista<ItemAbastecimento>()).Build();
			Campos.Insert(0, _dataInicial);
			Campos.Insert(1, _dataFinal);
			Campos.Insert(2, ItemInteracaoBase<ItemInteracaoButton, System.Windows.Controls.Button>.Criar().ComValor(new System.Windows.Controls.Button
			{
				Content = "Pesquisar",
				Tag = "F3",
				HorizontalAlignment = System.Windows.HorizontalAlignment.Left,
				Command = F3Command
			}).Build());
			Campos.Insert(3, _listaAbastecimento);
		}

		private void Pesquisar()
		{
			try
			{
				_abastecimentos = _service.Canal((IPostoCombustivelModuleService service) => service.ObterAbastecimentosPorPeriodo(_dataInicial.Valor, _dataFinal.Valor).Result);
				_listaAbastecimento.Valor.Limpar();
				_listaAbastecimento.Valor.Adicionar(_abastecimentos.Select((AbastecimentoDto abastecimento) => ItemAbastecimento.Criar().ComDataHora(abastecimento.DataHora).ComDescricaoProduto(abastecimento.DescricaoProduto)
					.ComBico(abastecimento.NumeroDoBicoNoSoftware)
					.ComValor(abastecimento.Total)
					.ComIdAbastecimento(abastecimento.Id)));
			}
			catch (Exception ex)
			{
				ex.ShowLastException();
			}
		}

		private bool PodePesquisar()
		{
			return _dataInicial.Valor.Date <= _dataFinal.Valor.Date;
		}

		protected override void F2Method()
		{
			try
			{
				string[] array = (from y in _listaAbastecimento.Valor.Itens
					where y.Selecionado
					select y.IdAbastecimento).ToArray();
				if (array.Any())
				{
					if (DialogoFactory.MostrarDialogoSimNao("Tem certeza que deseja tornar pendente os abastecimentos selecionados?") != MessageBoxResult.Yes)
					{
						Seletor.VoltarTudo();
						return;
					}
					DadosSistema.GetEventPublisher().Publish(new TornarAbastecimentosPendentesRequest(array));
					DialogoFactory.MostrarDialogoConfirma("Abastecimento estornados para pendente, verifique se o mesmo não consta em outra movimentação");
					Seletor.VoltarTudo();
				}
			}
			catch (Exception ex)
			{
				ex.ShowLastException();
			}
		}

		protected override bool CanF2Method()
		{
			return _abastecimentos.Any();
		}

		public override void Load()
		{
		}

		public override void UnLoad()
		{
			_listaAbastecimento?.Limpar();
		}

		public override bool PodeVoltar()
		{
			return true;
		}

		public override void Dispose()
		{
		}
	}
	public class PainelHabilitarShipay : PainelInteracao<PainelHabilitarShipay>
	{
		private readonly ItemInteracaoInteiroFocusable _identificacaoCaixa;

		private readonly ItemInteracaoTextoComando _clientId;

		private readonly InteracaoComando<string> _clientIdComando;

		public override string Titulo => "Identificação do caixa";

		public PainelHabilitarShipay()
		{
		}

		public PainelHabilitarShipay(Seletor<IPainel> seletor)
			: base(seletor)
		{
			ConfiguracaoShipay configuracaoShipay = ConfiguracaoShipay.Carregar();
			_identificacaoCaixa = ItemInteracaoBase<ItemInteracaoInteiroFocusable, int>.Criar().ComDescricao("Número PDV").ComValor(configuracaoShipay?.NumeroCaixa ?? 0)
				.Build();
			_clientIdComando = InteracaoComando<string>.Criar().ComComando(new AsyncCommand(CriarPdv, () => _identificacaoCaixa.IsNotNull() && _identificacaoCaixa.Valor > 0, allowMultipleExecution: false)).ComTooltip("Pressione 'Enter' para gerar o Client Id")
				.ComDado(configuracaoShipay?.ClientId)
				.Build();
			_clientId = ItemInteracaoBase<ItemInteracaoTextoComando, InteracaoComando<string>>.Criar().ComDescricao("Client ID").ComValor(_clientIdComando)
				.Build();
			Campos.Insert(0, _identificacaoCaixa);
			Campos.Insert(1, _clientId);
		}

		private async Task CriarPdv()
		{
			_ = 1;
			try
			{
				ShipayApiService api = new ShipayApiService(DadosSistema.ConfiguracaoDto.Geral.AccessKeyShipay.Valor, DadosSistema.ConfiguracaoDto.Geral.SecretKeyShipay.Valor, DadosSistema.ObterProxy());
				await api.AutenticarPdv();
				CriarPdvResponse criarPdvResponse = await api.PostAsync<CriarPdvResponse>(DigisatServer.Infrastructure.Crosscutting.Service.Shipay.Classes.Registrations.CriarPdv.Criar().Comstore_cnpj_cpf(DadosSistema.EmpresaLogada.CpfCnpj.RemoveCaracteresAlfanumerico()).Comstore_pos_name($"PDV{_identificacaoCaixa.Valor}"));
				_clientIdComando.Dado = criarPdvResponse.client_id;
			}
			catch (Exception ex)
			{
				DialogoFactory.MostrarDialogoConfirma(ex.GetLastException().Message.ToLower().Contains("conflict") ? "Já existe um PDV cadastrado com este identificador" : ex.Message, bloquearEnter: true);
			}
			finally
			{
				_clientIdComando.SetarFocoNoDado();
			}
		}

		public override void Load()
		{
			if (DadosSistema.UtilizarShipayDePagar)
			{
				DialogoFactory.MostrarDialogoConfirma("A Shipay está configurada para funcionar pela plataforma DePagar. Não é necessário habilitar este caixa.");
				Seletor.Voltar();
				return;
			}
			string valor = DadosSistema.ConfiguracaoDto.Geral.AccessKeyShipay.Valor;
			string valor2 = DadosSistema.ConfiguracaoDto.Geral.SecretKeyShipay.Valor;
			if (string.IsNullOrEmpty(valor) || string.IsNullOrEmpty(valor2))
			{
				DialogoFactory.MostrarDialogoConfirma("Informe o Access Key e Secret Key em Configurações > Geral > Shipay");
				Seletor.Voltar();
			}
		}

		public override void UnLoad()
		{
		}

		public override bool PodeVoltar()
		{
			return true;
		}

		public override void Dispose()
		{
		}

		protected override bool CanF2Method()
		{
			if (_identificacaoCaixa.IsNotNull() && _identificacaoCaixa.Valor > 0)
			{
				return _clientId.IsNotNull() & !string.IsNullOrEmpty(_clientId.Valor.Dado);
			}
			return false;
		}

		protected override void F2Method()
		{
			try
			{
				ConfiguracaoShipay.Criar().ComClientId(_clientId.Valor.Dado).ComIdentificadorPdv(_identificacaoCaixa.Valor)
					.Salvar();
				Seletor.Fechar();
			}
			catch (Exception ex)
			{
				ex.ShowLastException();
			}
		}
	}
