	public class PainelAdicionarMesaContaCreditoCliente : PainelInteracao<PainelAdicionarMesaContaCreditoCliente>, IItemMenuRibbon, ITitulo
	{
		private readonly Seletor<IPainel> _seletor;

		private readonly InteracaoComando<string> _interacaoNumero;

		private ItemInteracaoComboBox _especieCredito;

		private ItemInteracaoDecimal _valor;

		private ItemInteracaoInteiroValorMinimoFocusable _dividirValor;

		private ItemInteracaoTextBlock _total;

		private ItemInteracaoTextBlock _totalParte;

		private long _numero;

		private bool _isTransition;

		private ItemInteracaoTextBlock _creditoJaAdicionadoNaMesaConta;

		private ItemInteracaoListaMesaContaCredito _listaMesaContaCreditos;

		private ItemInteracaoButton _adicionar;

		private readonly IEmissorService _emissorService;

		private PagamentoTransacaoDto _pagamentoTransacaoTerminalPos;

		private InformacaoTransacaoCarteiraDigitalDto _pagamentoTransacaoCarteiraDigital;

		private InformacaoTransacaoCarteiraDigitalDto _pagamentoTransacaoCarteiraDigitalShipay;

		private RedePosDto _pagamentoTransacaoCartaoPos;

		private InformacaoTransacaoTefDto _pagamentoTransacaoCartao;

		private Otus.Modulo.PontoDeVendas.Interfaces.ITefService TefService;

		public IWService Service { get; set; }

		public ICommand F5Command { get; set; }

		public override string Titulo => $"Adicionar crédito na {DadosSistema.TipoRestaurante}";

		public KeyGestureCustom Key => new KeyGestureCustom(System.Windows.Input.Key.E, ModifierKeys.Control);

		public string ToolTip => Titulo;

		public PainelAdicionarMesaContaCreditoCliente()
		{
		}

		public PainelAdicionarMesaContaCreditoCliente(IWService service, IEmissorService emissorService, Seletor<IPainel> seletor, Otus.Modulo.PontoDeVendas.Interfaces.ITefService tefService)
			: base(seletor)
		{
			_emissorService = emissorService;
			_seletor = seletor;
			Service = service;
			TefService = tefService;
			_interacaoNumero = InteracaoComando<string>.Criar().ComComando(new AsyncCommand(PesquisarNumero, PodePesquisarPorNumero, allowMultipleExecution: false)).Build();
			ItemInteracaoInteiroComandoFocusable item = ItemInteracaoBase<ItemInteracaoInteiroComandoFocusable, InteracaoComando<string>>.Criar().ComDescricao("Número").ComValor(_interacaoNumero)
				.ComGlyphKind(GlyphKind.Search)
				.Build();
			Campos.Insert(0, item);
			F5Command = new AsyncCommand(Adicionar, PodeAdicionar);
		}

		private async Task Adicionar()
		{
			try
			{
				if (_especieCredito.Valor.ItemSelecionado.To<ItemInteracaoComboBox>()?.Descricao.ToLower().Equals("terminal pos") ?? false)
				{
					_isTransition = true;
					_seletor.Get<PainelBuscaMeioPagamentoTerminalPos>().SetarValor(_valor.Valor);
					_seletor.Get<PainelBuscaMeioPagamentoTerminalPos>().SetarMesaContaCreditoCliente(isMesaContaCreditoCliente: true);
					_seletor.Selecionar<PainelBuscaMeioPagamentoTerminalPos>();
				}
				else if (_especieCredito.Valor.ItemSelecionado.To<ItemInteracaoComboBox>()?.Descricao.ToLower().Equals("carteira digital") ?? false)
				{
					_isTransition = true;
					_seletor.Get<PainelBuscaCarteiraDigital>().SetarValor(_valor.Valor);
					_seletor.Get<PainelBuscaCarteiraDigital>().SetarMesaContaCreditoCliente(isMesaContaCreditoCliente: true);
					_seletor.Selecionar<PainelBuscaCarteiraDigital>();
				}
				else if (_especieCredito.Valor.ItemSelecionado.To<ItemInteracaoComboBox>()?.Descricao.ToLower().Equals("cartão pos") ?? false)
				{
					_isTransition = true;
					Seletor.Get<PainelBuscaAdministradoraCartao>().SetarValor(_valor.Valor);
					Seletor.Get<PainelBuscaAdministradoraCartao>().SetarMesaContaCreditoCliente(isMesaContaCreditoCliente: true);
					Seletor.Selecionar<PainelBuscaAdministradoraCartao>();
				}
				else if (_especieCredito.Valor.ItemSelecionado.To<ItemInteracaoComboBox>()?.Descricao.ToLower().Equals("carteira digital - shipay") ?? false)
				{
					_isTransition = true;
					Seletor.Get<PainelBuscaCarteiraDigitalShipay>().SetarPessoaEValor(ObterClienteConsumidor(), _valor.Valor);
					Seletor.Get<PainelBuscaCarteiraDigitalShipay>().SetarMesaContaCreditoCliente(isMesaContaCreditoCliente: true);
					Seletor.Selecionar<PainelBuscaCarteiraDigitalShipay>();
				}
				else if (_especieCredito.Valor.ItemSelecionado.To<ItemInteracaoComboBox>()?.Descricao.ToLower().Equals("cartão") ?? false)
				{
					_isTransition = true;
					TefService.Crt(_valor.Valor, _valor.Valor, 0m, possuiAcrescimoDesconto: false, 0, isRecebimentoPdv: true, null, isMesaContaCreditoCliente: true);
				}
				else if (_especieCredito.Valor.ItemSelecionado.To<ItemInteracaoComboBox>()?.Descricao.ToLower().Equals("dinheiro") ?? false)
				{
					await SalvarMesaContaCredito(1);
				}
			}
			catch (Exception ex)
			{
				ex.ShowLastException();
			}
		}

		private async Task SalvarMesaContaCredito(int especieRecebimento)
		{
			MesaContaCreditoDto mesaContaCredito = new MesaContaCreditoDto
			{
				DataHora = DateTime.Now,
				NumeroMesaConta = _numero,
				Valor = _valor.Valor
			};
			_isTransition = false;
			switch (especieRecebimento)
			{
			case 1:
				mesaContaCredito.EspecieRecebimento = new EspecieRecebimentoDto
				{
					Codigo = especieRecebimento
				};
				break;
			case 5:
				mesaContaCredito.EspecieRecebimento = new EspecieRecebimentoDto
				{
					Codigo = especieRecebimento
				};
				mesaContaCredito.PagamentoTransacaoCartaoPos = _pagamentoTransacaoCartaoPos;
				break;
			case 21:
				mesaContaCredito.EspecieRecebimento = new EspecieRecebimentoDto
				{
					Codigo = especieRecebimento
				};
				mesaContaCredito.PagamentoTransacaoCarteiraDigital = _pagamentoTransacaoCarteiraDigital;
				break;
			case 25:
				mesaContaCredito.EspecieRecebimento = new EspecieRecebimentoDto
				{
					Codigo = especieRecebimento
				};
				mesaContaCredito.PagamentoTransacaoCarteiraDigitalShipay = _pagamentoTransacaoCarteiraDigitalShipay;
				break;
			case 22:
				mesaContaCredito.EspecieRecebimento = new EspecieRecebimentoDto
				{
					Codigo = especieRecebimento
				};
				mesaContaCredito.PagamentoTransacaoTerminalPos = _pagamentoTransacaoTerminalPos;
				break;
			case 3:
				mesaContaCredito.EspecieRecebimento = new EspecieRecebimentoDto
				{
					Codigo = especieRecebimento
				};
				mesaContaCredito.PagamentoTransacaoCartao = _pagamentoTransacaoCartao;
				break;
			}
			await Service.Canal((IRestauranteModuleService x) => x.SalvarMesaContaCredito(mesaContaCredito)).ContinueWith((Task task) =>
			{
				ThreadPrincipal.Executar(async () =>
				{
					if (task.IsFaulted)
					{
						task.Exception.ShowLastException();
					}
					else
					{
						if (especieRecebimento != 25 && especieRecebimento != 21)
						{
							_emissorService.ImprimirRelatorioGerencialMesaContaCredito(RetornarInformacoesRelatorioGerencialMesaContaCredito());
						}
						await PesquisarNumero();
					}
				});
			});
		}

		private IEnumerable<string> RetornarInformacoesRelatorioGerencialMesaContaCredito()
		{
			return new List<string>
			{
				"COMPROVANTE DE CREDITO ADICIONADO",
				$"{DadosSistema.TipoRestaurante}: {_numero}",
				$"Valor: {_valor.Valor:C2}",
				$"Especie: {_especieCredito.Valor.ItemSelecionado.To<ItemInteracaoComboBox>()?.Descricao}",
				"---------------------------------------",
				"---------------------------------------",
				"   E VEDADA A AUTENTICACAO DESTE DOCUMENTO   ",
				"            NAO E DOCUMENTO FISCAL           "
			};
		}

		private bool PodeAdicionar()
		{
			ItemInteracaoDecimal valor = _valor;
			if (valor != null && valor.Valor > 0m)
			{
				decimal? num = _valor?.Valor;
				decimal num2 = _total?.Valor.ToDecimal(2) ?? 0m;
				if (!(num.GetValueOrDefault() < num2))
				{
					return false;
				}
				return num.HasValue;
			}
			return false;
		}

		private bool PodePesquisarPorNumero()
		{
			return !string.IsNullOrWhiteSpace(_interacaoNumero.Dado);
		}

		private async Task PesquisarNumero()
		{
			Limpar();
			if (_interacaoNumero.Dado.ApenasNumeros().ToLong() != 0L)
			{
				_numero = _interacaoNumero.Dado.ApenasNumeros().ToLong();
			}
			await Service.Canal((IRestauranteModuleService x) => x.ObterItensMesaConta(_numero)).ContinueWith((Task<IEnumerable<ItemMesaContaDto>> task) =>
			{
				ThreadPrincipal.Executar(() =>
				{
					if (task.IsFaulted)
					{
						task.Exception.ShowLastException();
					}
					else if (!task.Result.Any())
					{
						DialogoFactory.MostrarDialogoConfirma($"{DadosSistema.TipoRestaurante} {_numero} fechada!");
						_numero = 0L;
					}
					else
					{
						_total = ItemInteracaoBase<ItemInteracaoTextBlock, string>.Criar().ComDescricao("TOTAL PENDENTE:").ComValor(task.Result.Where((ItemMesaContaDto x) => !x.Cancelado).Sum((ItemMesaContaDto x) => x.Total).FormatarCampoValor(2))
							.Build();
						Campos.Add(_total);
						_dividirValor = ItemInteracaoBase<ItemInteracaoInteiroValorMinimoFocusable, int>.Criar().ComValorMinimo(1).ComDescricao("Dividir total pendente em quantas partes")
							.ComValor(1)
							.Build();
						_dividirValor.WhenPropertyChanged.Select((string v) => _total.Valor).Subscribe((string x) =>
						{
							CalcularDivisao();
						});
						Campos.Add(_dividirValor);
						_totalParte = ItemInteracaoBase<ItemInteracaoTextBlock, string>.Criar().ComDescricao("Total para cada parte:").Build();
						CalcularDivisao();
						Campos.Add(_totalParte);
						Lista<IItemInteracao> valor = new Lista<IItemInteracao>();
						ItemInteracaoComboBox item = ItemInteracaoBase<ItemInteracaoComboBox, Lista<IItemInteracao>>.Criar().ComDescricao("Dinheiro").ComValor(valor)
							.Build();
						Lista<IItemInteracao> valor2 = new Lista<IItemInteracao>();
						ItemInteracaoComboBox itemInteracaoComboBox = ItemInteracaoBase<ItemInteracaoComboBox, Lista<IItemInteracao>>.Criar().ComDescricao("Cartão POS").ComValor(valor2)
							.Build();
						Lista<IItemInteracao> valor3 = new Lista<IItemInteracao>();
						ItemInteracaoComboBox itemInteracaoComboBox2 = ItemInteracaoBase<ItemInteracaoComboBox, Lista<IItemInteracao>>.Criar().ComDescricao("Terminal POS").ComValor(valor3)
							.Build();
						Lista<IItemInteracao> valor4 = new Lista<IItemInteracao>();
						ItemInteracaoComboBox itemInteracaoComboBox3 = ItemInteracaoBase<ItemInteracaoComboBox, Lista<IItemInteracao>>.Criar().ComDescricao("Carteira Digital").ComValor(valor4)
							.Build();
						Lista<IItemInteracao> valor5 = new Lista<IItemInteracao>();
						ItemInteracaoComboBox item2 = ItemInteracaoBase<ItemInteracaoComboBox, Lista<IItemInteracao>>.Criar().ComDescricao("Carteira Digital - SHIPAY").ComValor(valor5)
							.Build();
						Lista<IItemInteracao> valor6 = new Lista<IItemInteracao>();
						ItemInteracaoComboBox item3 = ItemInteracaoBase<ItemInteracaoComboBox, Lista<IItemInteracao>>.Criar().ComDescricao("Cartão").ComValor(valor6)
							.Build();
						Lista<IItemInteracao> lista = new Lista<IItemInteracao>();
						lista.Adicionar(item);
						ConfiguracaoTef tef = DadosSistema.ObterConfiguracaoClient().ObterConfiguracao().Tef;
						if ((tef.TefConfigurado && tef.Tipo == TipoTef.PayGo) || tef.Tipo == TipoTef.Sitef || tef.Tipo == TipoTef.GetCard || tef.Tipo == TipoTef.Elgin)
						{
							lista.Adicionar(item3);
						}
						lista.Adicionar(itemInteracaoComboBox, itemInteracaoComboBox2, itemInteracaoComboBox3);
						if (DadosSistema.ShipayConfigurado)
						{
							lista.Adicionar(item2);
						}
						_especieCredito = ItemInteracaoBase<ItemInteracaoComboBox, Lista<IItemInteracao>>.Criar().ComDescricao("Espécie").ComValor(lista)
							.Build();
						Campos.Add(_especieCredito);
						_valor = ItemInteracaoBase<ItemInteracaoDecimal, decimal>.Criar().ComDescricao("Valor").Build();
						Campos.Add(_valor);
						_adicionar = ItemInteracaoBase<ItemInteracaoButton, System.Windows.Controls.Button>.Criar().ComValor(new System.Windows.Controls.Button
						{
							Content = "Adicionar",
							Tag = "F5",
							HorizontalAlignment = System.Windows.HorizontalAlignment.Left,
							Command = F5Command
						}).Build();
						Campos.Add(_adicionar);
					}
				});
			});
			await ObterCreditosMesaConta();
		}

		public async void FinalizarPagamentoTerminalPos(PagamentoTransacaoDto pagamentoTransacao)
		{
			_pagamentoTransacaoTerminalPos = pagamentoTransacao;
			await SalvarMesaContaCredito(22);
		}

		public async void FinalizarPagamentoCarteiraDigital(InformacaoTransacaoCarteiraDigital pagamentoTransacao)
		{
			_pagamentoTransacaoCarteiraDigital = new InformacaoTransacaoCarteiraDigitalDto
			{
				Pessoa = pagamentoTransacao.Pessoa.ProjectedPessoaHistoricoAsDto(),
				Nsu = pagamentoTransacao.Nsu.ToStringEmptyWhenNull(),
				Rede = pagamentoTransacao.Rede.ToStringEmptyWhenNull(),
				Valor = pagamentoTransacao.Valor,
				Impresso = pagamentoTransacao.Impresso.ToListEmptyWhenNull(),
				CodigoAutorizacaoTransacao = pagamentoTransacao.CodigoAutorizacao.ToStringEmptyWhenNull(),
				Taxa = pagamentoTransacao.Taxa.ProjectedAsDto(),
				Tipo = pagamentoTransacao.Tipo.ToStringEmptyWhenNull(),
				EndToEndId = pagamentoTransacao.EndToEndId.ToStringEmptyWhenNull(),
				PspPagador = pagamentoTransacao.PspPagador.ToStringEmptyWhenNull()
			};
			_emissorService.AdicionarRelatorioGerencialInformacoesTransacao(RelatoriosEmissor.RetornarRelatorioGerencialInformacoesTransacao(pagamentoTransacao, integrado: false, _emissorService.Is<IEcfService>()));
			_emissorService.ImprimirRelatorioGerencialInformacoesTransacao();
			await SalvarMesaContaCredito(21);
		}

		public async void FinalizarPagamentoCarteiraDigitalShipay(InformacaoTransacaoCarteiraDigital pagamentoTransacao)
		{
			_pagamentoTransacaoCarteiraDigitalShipay = new InformacaoTransacaoCarteiraDigitalDto
			{
				Pessoa = pagamentoTransacao.Pessoa.ProjectedPessoaHistoricoAsDto(),
				Nsu = pagamentoTransacao.Nsu.ToStringEmptyWhenNull(),
				Rede = pagamentoTransacao.Rede.ToStringEmptyWhenNull(),
				Valor = pagamentoTransacao.Valor,
				Impresso = pagamentoTransacao.Impresso.ToListEmptyWhenNull(),
				CodigoAutorizacaoTransacao = pagamentoTransacao.CodigoAutorizacao.ToStringEmptyWhenNull(),
				Taxa = pagamentoTransacao.Taxa.ProjectedAsDto(),
				Tipo = pagamentoTransacao.Tipo.ToStringEmptyWhenNull(),
				EndToEndId = pagamentoTransacao.EndToEndId.ToStringEmptyWhenNull(),
				PspPagador = pagamentoTransacao.PspPagador.ToStringEmptyWhenNull()
			};
			_emissorService.AdicionarRelatorioGerencialInformacoesTransacao(RelatoriosEmissor.RetornarRelatorioGerencialInformacoesTransacao(pagamentoTransacao, integrado: true, _emissorService.Is<IEcfService>()));
			_emissorService.ImprimirRelatorioGerencialInformacoesTransacao();
