		public async void FinalizarPagamentoCartaoPos(RedePosLocal pagamentoTransacao)
		{
			DigisatServer.Domain.Main.Aggregates.CadastrosAgg.Pessoas.Pessoa pessoa = pagamentoTransacao.ObterPessoaCompleta();
			_pagamentoTransacaoCartaoPos = new RedePosDto
			{
				Pessoa = DadosSistema.GetService().Canal((IPessoaModuleService service) => service.ObterPessoaPorId(pessoa.Id.ToString())),
				Descricao = pagamentoTransacao.Descricao,
				OperacaoRedePos = (pagamentoTransacao.Debito ? 4 : 3),
				Valor = _valor.Valor,
				CodigoAutorizacao = pagamentoTransacao.CodigoAutorizacao.ToStringEmptyWhenNull(),
				CodigoPagamentoNsu = pagamentoTransacao.CodigoPagamentoNsu.ToStringEmptyWhenNull(),
				Taxa = pagamentoTransacao.Taxa.ProjectedAsDto()
			};
			await SalvarMesaContaCredito(5);
		}

		public async void FinalizarPagamentoCartao(InformacaoTransacaoTef pagamentoTransacao)
		{
			_pagamentoTransacaoCartao = new InformacaoTransacaoTefDto
			{
				Pessoa = pagamentoTransacao.Pessoa.ProjectedPessoaHistoricoAsDto(),
				Nsu = pagamentoTransacao.Nsu.ToStringEmptyWhenNull(),
				Rede = pagamentoTransacao.Rede.ToStringEmptyWhenNull(),
				Valor = _valor.Valor,
				Impresso = pagamentoTransacao.Impresso.ToListEmptyWhenNull(),
				CodigoAutorizacaoTransacao = pagamentoTransacao.CodigoAutorizacaoTransacao.ToStringEmptyWhenNull(),
				Taxa = pagamentoTransacao.Taxa.ProjectedAsDto(),
				Debito = pagamentoTransacao.Debito,
				NomeAdministradora = pagamentoTransacao.NomeAdministradora.ToStringEmptyWhenNull(),
				NumeroParcelas = pagamentoTransacao.NumeroParcelas,
				NumeroCartao = pagamentoTransacao.NumeroCartao.ToStringEmptyWhenNull(),
				NomeCliente = pagamentoTransacao.NomeCliente.ToStringEmptyWhenNull()
			};
			TefService.Imprimir();
			await SalvarMesaContaCredito(3);
		}

		public ConsumidorLocal ObterClienteConsumidor()
		{
			Consumidor pessoa = Consumidor.Criar();
			return ConsumidorLocal.Criar().ComPessoa(pessoa);
		}

		private async Task ObterCreditosMesaConta()
		{
			await Service.Canal((IRestauranteModuleService x) => x.ObterMesaContaCreditoNaoUtilizado(new List<long> { _numero }, setarComoUtilizados: false)).ContinueWith((Task<IEnumerable<MesaContaCreditoDto>> task) =>
			{
				ThreadPrincipal.Executar(() =>
				{
					if (task.IsFaulted)
					{
						task.Exception.ShowLastException();
					}
					else if (task.Result.Any())
					{
						_listaMesaContaCreditos = ItemInteracaoBase<ItemInteracaoListaMesaContaCredito, Lista<ItemMesaContaCredito>>.Criar().ComValor(new Lista<ItemMesaContaCredito>()).Build();
						_listaMesaContaCreditos.Valor.Adicionar(task.Result.Select((MesaContaCreditoDto mesaContaCredito) => new ItemMesaContaCredito(mesaContaCredito.EspecieRecebimento.Descricao, mesaContaCredito.Valor, mesaContaCredito.Id, RemoverItemLista)));
						Campos.Add(_listaMesaContaCreditos);
						_creditoJaAdicionadoNaMesaConta?.Limpar();
						_creditoJaAdicionadoNaMesaConta = ItemInteracaoBase<ItemInteracaoTextBlock, string>.Criar().ComDescricao($"Crédito já adicionado na {DadosSistema.TipoRestaurante}:").ComValor(task.Result.Sum((MesaContaCreditoDto x) => x.Valor).FormatarCampoValor(2))
							.Build();
						if (_creditoJaAdicionadoNaMesaConta.Valor.ToDecimal(2) > 0m)
						{
							decimal num = _total.Valor.ToDecimal(2);
							_total.ComValor((num - _creditoJaAdicionadoNaMesaConta.Valor.ToDecimal(2)).FormatarCampoValor(2));
						}
						CalcularDivisao();
						Campos.Add(_creditoJaAdicionadoNaMesaConta);
					}
				});
			});
		}

		protected void CalcularDivisao()
		{
			_totalParte.ComValor((_total.Valor.ToDecimal(2) / (decimal)_dividirValor.Valor.ToInt()).FormatarCampoValor(2));
		}

		protected async void RemoverItemLista(object obj)
		{
			ItemMesaContaCredito item = obj as ItemMesaContaCredito;
			if (item.IsNotNull())
			{
				Service.Canal((IRestauranteModuleService x) =>
				{
					x.RemoverMesaContaCredito(item.Referencia);
				});
				Limpar();
				await PesquisarNumero();
			}
		}

		public override void Load()
		{
		}

		public override void UnLoad()
		{
			if (!_isTransition)
			{
				_interacaoNumero.Limpar(() => string.Empty);
				_numero = 0L;
			}
			Limpar();
		}

		protected override void Limpar()
		{
			Campos.RemoveIfExists(_especieCredito);
			Campos.RemoveIfExists(_valor);
			Campos.RemoveIfExists(_dividirValor);
			Campos.RemoveIfExists(_total);
			Campos.RemoveIfExists(_totalParte);
			Campos.RemoveIfExists(_creditoJaAdicionadoNaMesaConta);
			Campos.RemoveIfExists(_listaMesaContaCreditos);
			Campos.RemoveIfExists(_adicionar);
			base.Limpar();
		}

		public override bool PodeVoltar()
		{
			return true;
		}

		public override void Dispose()
		{
		}

		protected override void F2Method()
		{
			_seletor.VoltarTudo();
		}
	}
	public class PainelImportacaoParcialMesaConta : PainelInteracao<PainelImportacaoParcialMesaConta>, IItemMenuRibbon, ITitulo
	{
		private readonly InteracaoComando<string> _interacaoNumero;

		private readonly ItemInteracaoListaItemMesaConta _interacaoListaItemMesaConta;

		private readonly IEmissorService _emissorService;

		public IWService Service { get; set; }

		public override string Titulo => $"Importação parcial {DadosSistema.TipoRestaurante}";

		public KeyGestureCustom Key => new KeyGestureCustom(System.Windows.Input.Key.G, ModifierKeys.Control);

		public string ToolTip => Titulo;

		public PainelImportacaoParcialMesaConta()
		{
		}

		public PainelImportacaoParcialMesaConta(IWService service, IEmissorService emissorService, Seletor<IPainel> seletor)
			: base(seletor)
		{
			_emissorService = emissorService;
			Service = service;
			_interacaoNumero = InteracaoComando<string>.Criar().ComComando(new AsyncCommand(PesquisarNumero, PodePesquisarPorNumero, allowMultipleExecution: false)).Build();
			ItemInteracaoInteiroComandoFocusable item = ItemInteracaoBase<ItemInteracaoInteiroComandoFocusable, InteracaoComando<string>>.Criar().ComDescricao("Número").ComValor(_interacaoNumero)
				.ComGlyphKind(GlyphKind.Search)
				.Build();
			_interacaoListaItemMesaConta = ItemInteracaoBase<ItemInteracaoListaItemMesaConta, Lista<ItemMesaConta>>.Criar().ComDescricao("").ComValor(new Lista<ItemMesaConta>())
				.Build();
			Campos.Insert(0, item);
			Campos.Insert(1, _interacaoListaItemMesaConta);
			F2Command = new AsyncCommand(F2MethodAsync, CanF2Method, allowMultipleExecution: false);
		}

		private bool PodePesquisarPorNumero()
		{
			return !string.IsNullOrWhiteSpace(_interacaoNumero.Dado);
		}

		private async Task PesquisarNumero()
		{
			_interacaoListaItemMesaConta.Valor.Limpar();
			long numero = _interacaoNumero.Dado.ApenasNumeros().ToLong();
			await DadosSistema.GetService().Canal((IRestauranteModuleService x) => x.ObterMesaContaCreditoNaoUtilizado(new List<long> { numero }, setarComoUtilizados: false)).ContinueWith((Task<IEnumerable<MesaContaCreditoDto>> task) =>
			{
				ThreadPrincipal.Executar(async () =>
				{
					if (task.IsFaulted)
					{
						task.Exception.ShowLastException();
					}
					else if (!task.Result.Any())
					{
						await Service.Canal((IRestauranteModuleService x) => x.ObterItensMesaConta(numero)).ContinueWith((Task<IEnumerable<ItemMesaContaDto>> task2) =>
						{
							ThreadPrincipal.Executar(() =>
							{
								if (task2.IsFaulted)
								{
									task2.Exception.ShowLastException();
								}
								else if (!task2.Result.Any())
								{
									DialogoFactory.MostrarDialogoConfirma($"{DadosSistema.TipoRestaurante} {numero} fechada!");
								}
								else
								{
									_interacaoListaItemMesaConta.AlterarDescricao($"Selecione os itens da {DadosSistema.TipoRestaurante} {numero}");
									foreach (ItemMesaContaDto item in task2.Result.OrderBy((ItemMesaContaDto x) => x.Descricao))
									{
										_interacaoListaItemMesaConta.Valor.Adicionar(ItemMesaConta.Criar(item));
									}
									_interacaoListaItemMesaConta.Valor.PosicionarNoPrimeiro();
								}
								_interacaoNumero.Limpar(() => string.Empty);
							});
						});
					}
					else
					{
						DialogoFactory.MostrarDialogoConfirma($"A {DadosSistema.TipoRestaurante} contém créditos e seus itens não podem ser importados parcialmente.");
					}
				});
			});
		}

		public override void Load()
		{
		}

		public override void UnLoad()
		{
			_interacaoListaItemMesaConta.Valor.Limpar();
			_interacaoListaItemMesaConta.AlterarDescricao("");
		}

		public override bool PodeVoltar()
		{
			return true;
		}

		public override void Dispose()
		{
		}

		protected override void F2Method()
		{
		}

		protected override bool CanF2Method()
		{
			return _interacaoListaItemMesaConta?.Valor.Itens.Any((ItemMesaConta x) => x.Selecionado) ?? false;
		}

		protected async Task F2MethodAsync()
		{
			if (!Seletor.Get<PainelDocumentoFiscal>().PodeAbrirDocumentoTurno())
			{
				return;
			}
			try
			{
				IEnumerable<ItemMesaContaDto> itensFechadosMesaAtual;
				if (DadosSistema.IsPafEcf)
				{
					long numeroMesaContaAtual = _interacaoListaItemMesaConta.Valor.Itens.FirstOrDefault().Dto.NumeroMesaConta;
					int numeroMesaAtual = _interacaoListaItemMesaConta.Valor.Itens.FirstOrDefault().Dto.NumeroMesa;
					IEnumerable<ItemMesaContaDto> itensNaoSelecionados = from x in _interacaoListaItemMesaConta.Valor.Itens
						where !x.Selecionado
						select x.Dto;
					if (itensNaoSelecionados.Any())
					{
						long numeroMesaContaNova = default;
						_ = numeroMesaContaNova;
						numeroMesaContaNova = await ObterNumeroMesaContaDisponivel();
						IEnumerable<ItemMesaContaDto> itensNaoImportadosMesaContaNova = default;
						_ = itensNaoImportadosMesaContaNova;
						itensNaoImportadosMesaContaNova = await Service.Canal((IRestauranteModuleService service) => service.TransferirItensMesaConta(itensNaoSelecionados, numeroMesaContaNova, transferindoTodosItens: false, numeroMesaAtual));
						itensFechadosMesaAtual = await Service.Canal((IRestauranteModuleService service) => service.ObterItensParaDocumentoFiscal(_emissorService.RetornarNumeroDocumento(), _emissorService.RetornarNumeroFabricacao(), numeroMesaContaAtual));
						await Service.Canal((IRestauranteModuleService service) => service.TransferirItensMesaConta(itensNaoImportadosMesaContaNova, numeroMesaContaAtual, transferindoTodosItens: false, numeroMesaAtual));
					}
					else
					{
						itensFechadosMesaAtual = await Service.Canal((IRestauranteModuleService service) => service.ObterItensParaDocumentoFiscal(_emissorService.RetornarNumeroDocumento(), _emissorService.RetornarNumeroFabricacao(), numeroMesaContaAtual));
					}
				}
				else
				{
					IEnumerable<ItemMesaContaParcialDto> itensSelecionados = from x in _interacaoListaItemMesaConta.Valor.Itens
						where x.Selecionado || x.Dto.Cancelado
						select x.ObterDto();
					itensFechadosMesaAtual = await Service.Canal((IRestauranteModuleService service) => service.FecharItensMesasContas(itensSelecionados));
				}
				List<long> numerosImportados = new List<long>();
				numerosImportados.AddRange((from a in _interacaoListaItemMesaConta.Valor.Itens
					where a.Selecionado
					select a.Dto.NumeroMesaConta).Distinct());
				Seletor.Voltar();
				Seletor.Get<PainelDocumentoFiscal>().EmitirDocumentoFiscal(itensFechadosMesaAtual);
				Seletor.Get<PainelDocumentoFiscal>().PreDocumentoFiscal?.SetarNumerosMesasContasClienteImportadas(numerosImportados);
				List<long> numerosMesasContasPedirMenuImportadas = new List<long>(itensFechadosMesaAtual.Select((ItemMesaContaDto x) => x.NumeroMesaContaPedirMenu));
				Seletor.Get<PainelDocumentoFiscal>().PreDocumentoFiscal?.SetarNumerosMesasContasClientePedirMenuImportadas(numerosMesasContasPedirMenuImportadas);
				DormirAsync(2000, (object x) =>
				{
					if (Service.Canal((IPreVendaModuleService service) => service.VerificarExistenciaPreVendaAguardando(numerosImportados)) && DialogoFactory.MostrarDialogoSimNao("Existe(m) pré-venda(s) com o(s) número(s) informado(s). Deseja importá-la(s)?") == MessageBoxResult.Yes)
					{
						Seletor.Get<PainelBuscaPreVenda>().AdicionarNumeros(numerosImportados);
						Seletor.Selecionar<PainelBuscaPreVenda>();
					}
				});
			}
			catch (Exception ex)
			{
				ex.ShowLastException();
			}
		}

		private async Task<long> ObterNumeroMesaContaDisponivel()
		{
			long num = 0L;
			for (int tentativas = 0; num == 0L || tentativas < 3; tentativas++)
			{
				num = await CriarNumeroMesaContaDisponivel();
			}
			if (num == 0L)
			{
				throw new Exception("Falha ao obter número mesa/conta cliente");
			}
			return num;
		}

		private async Task<long> CriarNumeroMesaContaDisponivel()
		{
			try
			{
				int numeroMesaConta = new Random().Next(1073741823, int.MaxValue);
				return (!(await Service.Canal((IRestauranteModuleService x) => x.Obter(numeroMesaConta))).Itens.Any()) ? numeroMesaConta : 0;
			}
			catch (Exception)
			{
				return 0L;
			}
		}
	}
	public class PainelImportarMesaConta : PainelInteracao<PainelImportarMesaConta>, IItemMenuRibbon, ITitulo
	{
		private readonly IEmissorService _emissorService;

		private readonly InteracaoComando<string> _interacaoNumero;

		private readonly ItemInteracaoListaMesaConta _interacaoListaMesaConta;

		public IWService Service { get; set; }

		public override string Titulo => $"Importar {DadosSistema.TipoRestaurante}";

		public KeyGestureCustom Key => new KeyGestureCustom(System.Windows.Input.Key.F, ModifierKeys.Control);

		public string ToolTip => Titulo;

		public ICommand DelCommand { get; protected set; }

		public ICommand CtrlACommand { get; protected set; }

		public PainelImportarMesaConta()
		{
		}

		public PainelImportarMesaConta(IWService service, IEmissorService emissorService, Seletor<IPainel> seletor)
			: base(seletor)
		{
			_emissorService = emissorService;
			Service = service;
			_interacaoNumero = InteracaoComando<string>.Criar().ComComando(new DelegateCommand(AdicionarNumero, PodePesquisarPorNumero)).Build();
			ItemInteracaoInteiroComandoFocusable item = ItemInteracaoBase<ItemInteracaoInteiroComandoFocusable, InteracaoComando<string>>.Criar().ComDescricao("Número").ComValor(_interacaoNumero)
				.ComGlyphKind(GlyphKind.Plus)
				.Build();
			_interacaoListaMesaConta = ItemInteracaoBase<ItemInteracaoListaMesaConta, Lista<MesaConta>>.Criar().ComDescricao($"{DadosSistema.TipoRestaurante}(s) selecionada(s)").ComValor(new Lista<MesaConta>())
				.Build();
			Campos.Insert(0, item);
			Campos.Insert(1, _interacaoListaMesaConta);
			DelCommand = new DelegateCommand<object>(RemoverItem);
			F2Command = new AsyncCommand(F2MethodAsync, CanF2Method, allowMultipleExecution: false);
			CtrlACommand = new DelegateCommand(CtrlAMethod, CanCtrlAMethod);
		}

		private bool CanCtrlAMethod()
		{
			return DadosSistema.ConfiguracaoDto?.Saida?.MostrarOpcaoImportarTodasPendentes.Valor ?? false;
		}

		private void CtrlAMethod()
		{
			if (DialogoFactory.MostrarDialogoSimNao($"ATENÇÃO! Tem certeza que deseja importar todas as {DadosSistema.TipoRestaurante}(s) pendentes de fechamento?") != MessageBoxResult.Yes)
			{
				return;
			}
			foreach (long mesa in DadosSistema.GetService().Canal((IRestauranteModuleService service) => service.ObterNumerosMesasPendentesFechamento()))
			{
				if (!_interacaoListaMesaConta.Valor.Itens.Any((MesaConta a) => a.Numero.Equals(mesa)))
				{
					_interacaoListaMesaConta.Valor.Adicionar(Documento<MesaConta>.Criar().ComNumero(mesa).ComCommand(DelCommand)
						.Build());
				}
			}
		}

		private bool PodePesquisarPorNumero()
		{
			return !string.IsNullOrWhiteSpace(_interacaoNumero.Dado);
		}

		private void AdicionarNumero()
		{
			try
			{
				long numero = _interacaoNumero.Dado.ApenasNumeros().ToLong();
				if (!_interacaoListaMesaConta.Valor.Itens.Any((MesaConta a) => a.Numero.Equals(numero)))
				{
					_interacaoListaMesaConta.Valor.Adicionar(Documento<MesaConta>.Criar().ComNumero(numero).ComCommand(DelCommand)
						.Build());
				}
			}
			catch (Exception ex)
			{
				DialogoFactory.MostrarDialogoConfirma(ex.Message, bloquearEnter: true);
			}
			finally
			{
				_interacaoNumero.Limpar(() => string.Empty);
				_interacaoNumero.SetarFocoNoDado();
			}
		}

		private void RemoverItem(object item)
		{
			MesaConta item2 = (item as MesaConta) ?? _interacaoListaMesaConta.Valor.ItemSelecionado;
			_interacaoListaMesaConta.Valor.Remover(item2);
			Window mainWindow = System.Windows.Application.Current.MainWindow;
			TraversalRequest request = new TraversalRequest(FocusNavigationDirection.Next)
			{
				Wrapped = true
			};
			mainWindow.MoveFocus(request);
		}

		public override void Load()
		{
		}

		public override void UnLoad()
		{
			_interacaoListaMesaConta.Valor.Limpar();
		}

		public override bool PodeVoltar()
		{
			return true;
		}

		public override void Dispose()
		{
		}

		protected override void F2Method()
		{
		}

		protected async Task F2MethodAsync()
		{
			if (!Seletor.Get<PainelDocumentoFiscal>().PodeAbrirDocumentoTurno())
			{
				return;
			}
			await ObterMesaConta((IEnumerable<ItemMesaContaDto> mesaConta) =>
			{
				List<long> list = new List<long>(_interacaoListaMesaConta.Valor.Itens.Select((MesaConta x) => x.Numero));
				Seletor.Voltar();
				Seletor.Get<PainelDocumentoFiscal>().EmitirDocumentoFiscal(mesaConta);
				Seletor.Get<PainelDocumentoFiscal>().PreDocumentoFiscal?.SetarNumerosMesasContasClienteImportadas(list);
				List<long> numerosMesasContasPedirMenuImportadas = new List<long>(mesaConta.Select((ItemMesaContaDto x) => x.NumeroMesaContaPedirMenu));
				Seletor.Get<PainelDocumentoFiscal>().PreDocumentoFiscal?.SetarNumerosMesasContasClientePedirMenuImportadas(numerosMesasContasPedirMenuImportadas);
				VerificarPreVendas(list);
			});
		}

		private void VerificarPreVendas(List<long> numeroPreVendas)
		{
			if (Service.Canal((IPreVendaModuleService service) => service.VerificarExistenciaPreVendaAguardando(numeroPreVendas)) && DialogoFactory.MostrarDialogoSimNao("Existe(m) pré-venda(s) com o(s) número(s) informado(s). Deseja importá-la(s)?") == MessageBoxResult.Yes)
			{
				Seletor.Get<PainelBuscaPreVenda>().AdicionarNumeros(numeroPreVendas);
				Seletor.Selecionar<PainelBuscaPreVenda>();
				numeroPreVendas = null;
			}
		}

		private async Task ObterMesaConta(Action<IEnumerable<ItemMesaContaDto>> callback)
		{
			List<long> numeroPreVendas = new List<long>(_interacaoListaMesaConta.Valor.Itens.Select((MesaConta x) => x.Numero));
			try
			{
				List<ItemMesaContaDto> list = (await Service.Canal((IRestauranteModuleService service) => service.ObterItensParaDocumentoFiscal(_emissorService.RetornarNumeroDocumento(), _emissorService.RetornarNumeroFabricacao(), numeroPreVendas.ToArray()))).ToListEmptyWhenNull();
				if (!list.Any())
				{
					DialogoFactory.MostrarDialogoConfirma($"Nenhuma {DadosSistema.TipoRestaurante} encontrada.");
				}
				else
				{
					callback(list);
				}
			}
			catch (Exception ex)
			{
				ex.ShowLastException();
				Seletor.Voltar();
				VerificarPreVendas(numeroPreVendas);
			}
		}
	}
	public class PainelEstornarMesaContaCredito : PainelInteracao<PainelEstornarMesaContaCredito>
	{
		private readonly IEmissorService _emissorService;

		private readonly IWService _service;

		private readonly ItemInteracaoDataHoraFocusable _dataInicial;

		private readonly ItemInteracaoDataHora _dataFinal;

		private readonly ItemInteracaoInteiro _numero;

		private readonly ItemInteracaoListaEstornarMesaContaCredito _listaEstornarMesaContaCredito;

		private IEnumerable<ItemEstornarMesaContaCreditoDto> _itensRecuperarMesaContaCredito = new List<ItemEstornarMesaContaCreditoDto>();

		public override string Titulo => $"Estornar crédito da {DadosSistema.TipoRestaurante}";

		public override string DescricaoDoBotao => "Estornar";

		public ICommand F3Command { get; set; }

		public PainelEstornarMesaContaCredito()
		{
		}

		public PainelEstornarMesaContaCredito(IWService service, IEmissorService emissorService, Seletor<IPainel> seletorDireito)
			: base(seletorDireito)
		{
			_service = service;
			_emissorService = emissorService;
			_dataInicial = ItemInteracaoBase<ItemInteracaoDataHoraFocusable, DateTime>.Criar().ComDescricao("Data/hora inicial").ComValor(DateTime.Now)
				.Build();
			_dataFinal = ItemInteracaoBase<ItemInteracaoDataHora, DateTime>.Criar().ComDescricao("Data/hora final").ComValor(DateTime.Now)
				.Build();
			_numero = ItemInteracaoBase<ItemInteracaoInteiro, int>.Criar().ComDescricao("Número").Build();
			F3Command = new AsyncCommand(Pesquisar, PodePesquisar, allowMultipleExecution: false);
			_listaEstornarMesaContaCredito = ItemInteracaoBase<ItemInteracaoListaEstornarMesaContaCredito, Lista<ItemEstornarMesaContaCredito>>.Criar().ComValor(new Lista<ItemEstornarMesaContaCredito>()).Build();
			Campos.Insert(0, _dataInicial);
			Campos.Insert(1, _dataFinal);
			Campos.Insert(2, _numero);
			Campos.Insert(3, ItemInteracaoBase<ItemInteracaoButton, System.Windows.Controls.Button>.Criar().ComValor(new System.Windows.Controls.Button
			{
				Content = "Pesquisar",
				Tag = "F3",
				HorizontalAlignment = System.Windows.HorizontalAlignment.Left,
				Command = F3Command
			}).Build());
			Campos.Insert(4, _listaEstornarMesaContaCredito);
		}

		private async Task Pesquisar()
		{
			_itensRecuperarMesaContaCredito = _service.Canal((IRestauranteModuleService service) => service.ObterMesaContaCreditoUtilizadoPorPeriodoENumeroMesaConta(_numero.Valor, _dataInicial.Valor, _dataFinal.Valor).Result);
			_listaEstornarMesaContaCredito.Valor.Limpar();
			if (!_itensRecuperarMesaContaCredito.Any())
			{
				DialogoFactory.MostrarDialogoConfirma("Nenhum crédito já utilizado foi encontrado");
				return;
			}
			await ObterMesaConta((IEnumerable<ItemMesaContaDto> x) =>
			{
				_listaEstornarMesaContaCredito.Valor.Adicionar(_itensRecuperarMesaContaCredito.Select((ItemEstornarMesaContaCreditoDto turno) => ItemEstornarMesaContaCredito.Criar().ComId(turno.Id).ComUsuario(turno.Usuario)
					.ComDataHora(turno.DataHora)
					.ComValor(turno.Valor)
					.ComEspecie(turno.Especie)));
			});
		}

		private async Task ObterMesaConta(Action<IEnumerable<ItemMesaContaDto>> callback)
		{
			await _service.Canal((IRestauranteModuleService x) => x.ObterItensMesaConta(_numero.Valor)).ContinueWith((Task<IEnumerable<ItemMesaContaDto>> task) =>
			{
				ThreadPrincipal.Executar(() =>
				{
					if (task.IsFaulted)
					{
						task.Exception.ShowLastException();
					}
					else if (!task.Result.Any())
					{
						DialogoFactory.MostrarDialogoConfirma($"Nenhuma {DadosSistema.TipoRestaurante} encontrada.");
					}
					else
					{
						callback(task.Result);
					}
				});
			});
		}

		private bool PodePesquisar()
		{
			return _dataInicial.Valor <= _dataFinal.Valor;
		}

		protected override void F2Method()
		{
			try
			{
				_service.Canal((IRestauranteModuleService service) =>
				{
					service.ReabrirCreditosMesasContas(new List<string>(from x in _listaEstornarMesaContaCredito.Valor.Itens
						where x.Selecionado
						select x.Id));
				});
				DialogoFactory.MostrarDialogoConfirma($"Créditos estornados para a {DadosSistema.TipoRestaurante}");
				Seletor.VoltarTudo();
			}
			catch (Exception ex)
			{
				ex.ShowLastException();
			}
		}

		protected override void Limpar()
		{
			_numero?.Limpar();
			_dataInicial?.Limpar();
			_dataFinal?.Limpar();
			_listaEstornarMesaContaCredito?.Valor?.Limpar();
			_listaEstornarMesaContaCredito?.Limpar();
		}

		protected override bool CanF2Method()
		{
			return _itensRecuperarMesaContaCredito.Any();
		}

		public override void Load()
		{
			_dataInicial?.ComValor(new DateTime(DateTime.Now.Year, DateTime.Now.Month, DateTime.Now.Day, DateTime.Now.AddHours(-1.0).Hour, 0, 0));
			_dataFinal?.ComValor(DateTime.Now);
			_numero?.Limpar();
		}

		public override void UnLoad()
		{
		}

		public override bool PodeVoltar()
		{
			return true;
		}

		public override void Dispose()
		{
		}
	}
	public class PainelInformacoesNfce : PainelInteracao<PainelInformacoesNfce>, IItemMenuRibbon, ITitulo
	{
		private ItemInteracaoComboBoxFocusable _indicadorIntermediadorTransacao;

		private ItemInteracaoCnpj _itemInteracaoCnpjIntermediador;

		private ItemInteracaoTextoRequired _itemInteracaoIdentificadorIntermediador;

		private ItemInteracaoCpf _itemInteracaoCpfEntregador;

		private ItemInteracaoTextoRequired _itemInteracaoNomeEntregador;

		private Lista<IItemInteracao> _listaIndicadoresIntermediadorTransacao;

		private IDisposable _dispose;

		private readonly Seletor<IPainel> _seletor;

		public override string Titulo => "Informações da NFC-e";

		public KeyGestureCustom Key => new KeyGestureControl(System.Windows.Input.Key.B, Titulo);

		public string ToolTip => Titulo;

		public PainelInformacoesNfce()
		{
		}

		public PainelInformacoesNfce(Seletor<IPainel> seletor)
			: base(seletor)
		{
			_seletor = seletor;
			AdicionarCampoIndicadorIntermediadorTransacao();
		}

		private void AdicionarCampoIndicadorIntermediadorTransacao()
		{
			_listaIndicadoresIntermediadorTransacao = new Lista<IItemInteracao>(from item in HelperEnum.ObterParDeValores<IndicadorIntermediador>()
				select ItemInteracaoBase<ItemInteracaoTexto, string>.Criar().ComValor(item.Key).ComDescricao(item.Value.RetornarDescricao()));
			_dispose = _listaIndicadoresIntermediadorTransacao.WhenAlterouItemSelecionado.Subscribe((IItemInteracao itemSelecionado) =>
			{
				if (((ItemInteracaoTexto)itemSelecionado).Descricao.Equals(IndicadorIntermediador.SiteOuPlataformaDeTerceiros.RetornarDescricao()))
				{
					_itemInteracaoCnpjIntermediador = ItemInteracaoBase<ItemInteracaoCnpj, Cnpj>.Criar().ComDescricao("CNPJ do intermediador da transação").Build();
					_itemInteracaoIdentificadorIntermediador = ItemInteracaoBase<ItemInteracaoTextoRequired, string>.Criar().ComDescricao("Identificador cadastrado no intermediador").Build();
					RemoverCampos();
					Campos.Add(_itemInteracaoCnpjIntermediador);
					Campos.Add(_itemInteracaoIdentificadorIntermediador);
				}
				else if (((ItemInteracaoTexto)itemSelecionado).Descricao.Equals(IndicadorIntermediador.OperacaoComEntregaDomicilio.RetornarDescricao()))
				{
					_itemInteracaoCpfEntregador = ItemInteracaoBase<ItemInteracaoCpf, Cpf>.Criar().ComDescricao("CPF do entregador").Build();
					_itemInteracaoNomeEntregador = ItemInteracaoBase<ItemInteracaoTextoRequired, string>.Criar().ComDescricao("Nome do entregador").Build();
					RemoverCampos();
					Campos.Add(_itemInteracaoCpfEntregador);
					Campos.Add(_itemInteracaoNomeEntregador);
				}
				else
				{
					RemoverCampos();
				}
			});
			_indicadorIntermediadorTransacao = ItemInteracaoBase<ItemInteracaoComboBoxFocusable, Lista<IItemInteracao>>.Criar().ComValor(_listaIndicadoresIntermediadorTransacao).ComDescricao("Indicador de presença do comprador")
				.Build();
			Campos.Add(_indicadorIntermediadorTransacao);
		}

		public void RemoverCampos()
		{
			Campos.RemoveIfExists(_itemInteracaoCnpjIntermediador);
			Campos.RemoveIfExists(_itemInteracaoIdentificadorIntermediador);
			Campos.RemoveIfExists(_itemInteracaoCpfEntregador);
			Campos.RemoveIfExists(_itemInteracaoNomeEntregador);
		}

		protected override void F2Method()
		{
			IItemInteracao itemSelecionado = _listaIndicadoresIntermediadorTransacao.ItemSelecionado;
			if (((ItemInteracaoTexto)itemSelecionado).Descricao.Equals(IndicadorIntermediador.SiteOuPlataformaDeTerceiros.RetornarDescricao()))
			{
				Seletor.Get<PainelDocumentoFiscal>().PreDocumentoFiscal?.SetarDadosIntermediadorTransacao(HelperEnum.RetornarValorPelaDescription<IndicadorIntermediador>(((ItemInteracaoTexto)_indicadorIntermediadorTransacao.Valor.ItemSelecionado).Valor), _itemInteracaoCnpjIntermediador?.Valor.Numero, _itemInteracaoIdentificadorIntermediador?.Valor);
			}
			if (((ItemInteracaoTexto)itemSelecionado).Descricao.Equals(IndicadorIntermediador.OperacaoComEntregaDomicilio.RetornarDescricao()))
			{
				Seletor.Get<PainelDocumentoFiscal>().PreDocumentoFiscal?.SetarDadosEntregador(HelperEnum.RetornarValorPelaDescription<IndicadorIntermediador>(((ItemInteracaoTexto)_indicadorIntermediadorTransacao.Valor.ItemSelecionado).Valor), _itemInteracaoCpfEntregador?.Valor.Numero, _itemInteracaoNomeEntregador?.Valor, null);
			}
			Seletor.Voltar();
		}

		protected override bool CanF2Method()
		{
			if (!Campos.All((IItemInteracao campo) => !(campo is DigisatServer.Infrastructure.Crosscutting.Mvvm.Validation)))
			{
				return Campos.OfType<DigisatServer.Infrastructure.Crosscutting.Mvvm.Validation>().All((DigisatServer.Infrastructure.Crosscutting.Mvvm.Validation campo) => campo.Valid);
			}
			return true;
		}

		public override void Load()
		{
			PreDocumentoFiscal preDocumentoFiscal = _seletor.Get<PainelDocumentoFiscal>()?.PreDocumentoFiscal;
			if (preDocumentoFiscal != null && preDocumentoFiscal.PossuiEntregaDomicilio)
			{
				_listaIndicadoresIntermediadorTransacao.Posicionar((IItemInteracao x) => ((ItemInteracaoTexto)x).Valor.Equals(IndicadorIntermediador.OperacaoComEntregaDomicilio.RetornarDescricao()));
				_itemInteracaoCpfEntregador.Valor.Numero = preDocumentoFiscal.OperacaoComEntregaDomicilio.Cpf ?? string.Empty;
				_itemInteracaoNomeEntregador.Valor = preDocumentoFiscal.OperacaoComEntregaDomicilio.NomeEntregador ?? string.Empty;
			}
			else if (preDocumentoFiscal != null && preDocumentoFiscal.IndicadorIntermediadorTransacao == IndicadorIntermediador.SiteOuPlataformaDeTerceiros)
			{
				_listaIndicadoresIntermediadorTransacao.Posicionar((IItemInteracao x) => ((ItemInteracaoTexto)x).Valor.Equals(IndicadorIntermediador.SiteOuPlataformaDeTerceiros.RetornarDescricao()));
				_itemInteracaoCnpjIntermediador.Valor.Numero = preDocumentoFiscal.CnpjIntermediadorTransacao ?? string.Empty;
				_itemInteracaoIdentificadorIntermediador.Valor = preDocumentoFiscal.IdentificaoIntermediadorTransacao ?? string.Empty;
			}
		}

		public override void UnLoad()
		{
		}

		public override bool PodeVoltar()
		{
			return CanF2Method();
		}

		protected override void Limpar()
		{
			if (_itemInteracaoCnpjIntermediador.IsNotNull())
			{
				_itemInteracaoCnpjIntermediador.Valor.Numero = null;
			}
			if (_itemInteracaoIdentificadorIntermediador.IsNotNull())
			{
				_itemInteracaoIdentificadorIntermediador.Valor = null;
			}
			if (_itemInteracaoCpfEntregador.IsNotNull())
			{
				_itemInteracaoCpfEntregador.Valor.Numero = null;
			}
			if (_itemInteracaoNomeEntregador.IsNotNull())
			{
				_itemInteracaoNomeEntregador.Valor = null;
			}
			if (_listaIndicadoresIntermediadorTransacao.IsNotNull())
			{
				_listaIndicadoresIntermediadorTransacao.Posicionar((IItemInteracao x) => ((ItemInteracaoTexto)x).Valor.Equals(IndicadorIntermediador.SemIntermediador.RetornarDescricao()));
			}
			base.Limpar();
		}

		public void Reiniciar()
		{
			Limpar();
		}

		public override void Dispose()
		{
			_dispose?.Dispose();
		}
	}
	public class PainelLancamentoCodigoPontoDeVenda : PainelLancamentoCodigo<ObservacaoSelecionadaPontoDeVendaEvent>, IPainelEsquerdo, IPainel
	{
		private IEmissorService _emissor;

		private IModoFuncionamento _modoFuncionamento;

		public bool PdvEstadoOffline;

		public bool MostrarTecladoCompacto => System.Windows.Application.Current.MainWindow.ActualWidth < 1440.0;

		public ICommand CtrlF7Command { get; set; }

		public string CtrlF7CommandDescricao
		{
			get
			{
				if (DadosSistema.TipoMesaConta != TipoMesaContaCliente.Mesa)
				{
					return "Contas abertas";
				}
				return "Mesas abertas";
			}
		}

		public IReadOnlyCollection<string> Atalhos => new List<string>();

		public IEnumerable<ItemMenuAtalho> MenuRibbon => Enumerable.Empty<ItemMenuAtalho>();

		public PainelLancamentoCodigoPontoDeVenda(Seletor<IPainel> seletor, IEventPublisher eventPublisher, IRepositoryRead<ObservacaoRestaurante> observacaoRestauranteRepositoryRead, IMenuRapidoRepositoryRead menuRapidoRepositoryRead)
			: base(seletor, eventPublisher, observacaoRestauranteRepositoryRead, menuRapidoRepositoryRead)
		{
			CtrlF1Command = new DelegateCommand(PosicionarPainelCardapio);
			CtrlF7Command = new DelegateCommand(PosicionarPainelMesasContasAbertas, PodePosicionarPainelMesasContasAbertas);
			AltMCommand = new DelegateCommand(() =>
			{
			}, () => false);
		}

		private void PosicionarPainelCardapio()
		{
			try
			{
				if (_modoFuncionamento.SeletorEsquerdo.Historico.Any((IPainel x) => x.Is<PainelMenuRapidoPontoDeVenda>()))
				{
					_modoFuncionamento.SeletorEsquerdo.Selecionar<PainelMenuRapidoPontoDeVenda>();
				}
				else
				{
					_modoFuncionamento.SeletorEsquerdo.Selecionar<PainelCardapioPontoDeVenda>();
				}
			}
			catch (Exception)
			{
				DialogoFactory.MostrarDialogoConfirma("Não foi possível alternar para o painel Cardápios.");
			}
		}

		private bool PodePosicionarPainelMesasContasAbertas()
		{
			if (!PdvEstadoOffline)
			{
				return Habilitado;
			}
			return false;
		}

		private void PosicionarPainelMesasContasAbertas()
		{
			try
			{
				_modoFuncionamento.SeletorEsquerdo.Selecionar<PainelMesasContasAbertasPontoDeVenda>();
			}
			catch (Exception)
			{
				DialogoFactory.MostrarDialogoConfirma("Não foi possível alternar para o painel de mesas/contas abertas.");
			}
		}

		public void SetarModoFuncionamento(IModoFuncionamento modoFuncionamento)
		{
			_modoFuncionamento = modoFuncionamento;
			_emissor = modoFuncionamento.EmissorService;
			_emissor.To<NfceService>()?.WhenPdvOfflineEventEvent.Subscribe((bool x) =>
			{
				PdvEstadoOffline = x;
			});
		}
	}
