		{
			_emissorService = emissorService;
			emissorService.To<NfceService>()?.WhenPdvOfflineEventEvent.Subscribe((bool x) =>
			{
				PdvEstadoOffline = x;
			});
		}

		protected override void CriarCampos()
		{
			if (!PdvEstadoOffline)
			{
				CriarOpcaoAbrirTurno();
				if (DadosSistema.TurnoAberto)
				{
					AdicionarOpcaoFecharTurno();
					AdicionarOpcaoSuprimento();
					AdicionarOpcaoSangria();
					AdicionarOpcaoTef();
				}
				AdicionarOpcaoReimprimirFechamentosTurno();
