				{
					AdicionarOpcaoTransmitirRejeitadas();
				}
			}
			ConfiguracaoFarmacia configuracaoFarmacia = DadosSistema.ObterConfiguracaoFarmacia();
			AdicionarOpcaoEPharma(configuracaoFarmacia);
			AdicionarOpcaoSincronizar(configuracaoFarmacia);
