		{
			base.AdicionarOpcoes();
			AdicionarOpcaoMesasAbertasPafNfce();
			AdicionarOpcaoTransferenciaMesas();
		}

		private void AdicionarOpcaoTransferenciaMesas()
		{
			Lista.Adicionar(ItemMenu.Criar().ComIcone(new Otus.Infraestrutura.Models.Icones.Impressora()).ComDescricao($"Transf. {DadosSistema.TipoRestaurante}s")
				.ComDescricaoDetalhada($"Imprimir transferências de {DadosSistema.TipoRestaurante}")
				.ComAcao(ImprimirRelatorioTransferenciaMesaConta)
				.Build());
		}

		private async void ImprimirRelatorioTransferenciaMesaConta()
		{
			LoaderProcessoService.MostrarLoader($"Emitindo transferências de {DadosSistema.TipoRestaurante}");
			ExecutandoAcao = true;
			await Task.Factory.StartNew((Func<Task>)(async () =>
			{
				try
				{
					List<string> list = RelatorioGerencialRestauranteService.RetornarInformacoesRelatorioGerencialTransferencias(await Service.Canal((IRestauranteModuleService service) => service.ObterItensTransferidos())).ToList();
					list.Insert(0, $"Transferencia de {DadosSistema.TipoMesaContaPlural}".ToUpper());
					list.Insert(1, "".PadRight(40, '-'));
					ImpressoraNaoFiscalService.Imprimir(list);
				}
				catch (Exception ex)
				{
					ex.ShowLastException();
				}
			})).ContinueWith((Task<Task> task) =>
			{
				LoaderProcessoService.EsconderLoader();
				ExecutandoAcao = false;
				if (task.IsFaulted)
				{
					DialogoFactory.MostrarDialogoConfirma(task.Exception?.InnerException?.Message);
				}
				else
				{
					Seletor.Voltar();
				}
			}, CancellationToken.None, TaskContinuationOptions.None, TaskScheduler.FromCurrentSynchronizationContext());
		}

		protected void AdicionarOpcaoMesasAbertasPafNfce()
		{
			Lista.Adicionar(ItemMenu.Criar().ComIcone(new Otus.Infraestrutura.Models.Icones.Impressora()).ComDescricao($"{DadosSistema.TipoMesaContaPlural} abertas")
				.ComDescricaoDetalhada($"Imprimir {DadosSistema.TipoMesaContaPlural} abertas")
				.ComAcao(() =>
				{
					Seletor.Selecionar<PainelMesasAbertasPafNfce>();
				})
				.Build());
		}
	}
