		private async void ImprimirRelatorioTransferenciaMesaConta()
		{
			LoaderProcessoService.MostrarLoader($"Emitindo transferências de {DadosSistema.TipoRestaurante}");
			ExecutandoAcao = true;
			await Task.Factory.StartNew((Func<Task>)(async () =>
			{
				EcfService.AguardarEcfCarregado();
				try
				{
					IEnumerable<ItemMesaContaDto> itens = await Service.Canal((IRestauranteModuleService service) => service.ObterItensTransferidos());
					EcfService.ImprimirRelatorioGerencialTransfereciasMesaConta(RelatorioGerencialRestauranteService.RetornarInformacoesRelatorioGerencialTransferencias(itens));
				}
				catch (Exception ex)
				{
					ex.ShowLastException();
				}
			})).ContinueWith((Task<Task> task) =>
			{
				LoaderProcessoService.EsconderLoader();
				ExecutandoAcao = false;
				if (task.IsFaulted)
				{
					DialogoFactory.MostrarDialogoConfirma(task.Exception?.InnerException?.Message);
				}
				else
				{
					Seletor.Voltar();
				}
			}, CancellationToken.None, TaskContinuationOptions.None, TaskScheduler.FromCurrentSynchronizationContext());
		}
	}
	public class PainelMenuRapidoAdicionaisPontoVenda : PainelMenuRapidoAdicionais<VenderItemMenuRapidoPontoVendaEvent, ItemMenuRapidoSelecionadoComponentesPontoVendasEvent>
	{
