			: base(eventPublisher)
		{
			eventPublisher.GetEvent<ItemMenuRapidoSelecionadoAdicionaisPontoVendaEvent>().Subscribe((ItemMenuRapidoSelecionadoAdicionaisPontoVendaEvent itemEvent) =>
			{
				SelecionouItemMenuRapido(itemEvent.ItemMenuRapidoViewModel);
			});
		}

		public void SetarModoFuncionamento(IModoFuncionamento modoFuncionamento)
		{
			_modoFuncionamento = modoFuncionamento;
		}

		protected override void Abandonar()
		{
			if (_modoFuncionamento.SeletorEsquerdo.Historico.Any((IPainel x) => x.Is<PainelMenuRapidoBase>()))
			{
				_modoFuncionamento.SeletorEsquerdo.Selecionar<PainelMenuRapidoBase>();
