	public class PainelMenuRapidoPontoDeVenda : PainelMenuRapido<ItemMenuRapidoSelecionadoPontoDeVendaEvent>, IPainelEsquerdo, IPainel
	{
		private IEmissorService _emissor;

		private CompositeDisposable _disposable;

		private readonly Seletor<IPainel> _seletorEsquerdo;

		private bool _carregado;

		private IModoFuncionamento _modoFuncionamento;

		public bool PdvEstadoOffline;

		public IReadOnlyCollection<string> Atalhos { get; } = new List<string>();

		public IEnumerable<ItemMenuAtalho> MenuRibbon { get; } = Enumerable.Empty<ItemMenuAtalho>();

		public ICommand CtrlWCommand { get; set; }

		public PainelMenuRapidoPontoDeVenda(IMenuRapidoRepositoryRead menuRapidoRepositoryRead, IEventPublisher eventPublisher, Seletor<IPainel> seletorEsquerdo, Seletor<IPainel> seletorDireito)
			: base(menuRapidoRepositoryRead, eventPublisher, seletorEsquerdo)
		{
			PainelMenuRapidoPontoDeVenda painelMenuRapidoPontoDeVenda = this;
			_seletorEsquerdo = seletorEsquerdo;
			CtrlF7Command = new DelegateCommand(MesasContasAbertas, PodeMesasContasAbertas);
			CtrlF1Command = new DelegateCommand(() =>
			{
			}, () => false);
			eventPublisher.GetEvent((ItemMenuRapidoSelecionadoAdicionaisPontoVendaEvent e) =>
			{
				_modoFuncionamento.SeletorEsquerdo.Selecionar<PainelMenuRapidoAdicionaisPontoVenda>();
			});
			eventPublisher.GetEvent((ItemMenuRapidoSelecionadoComponentesPontoVendasEvent e) =>
			{
				painelMenuRapidoPontoDeVenda.SelecionarOpcionais(seletorEsquerdo, e);
			});
			eventPublisher.GetEvent((VenderItemMenuRapidoPontoVendaEvent e) =>
			{
				_modoFuncionamento.SeletorEsquerdo.Selecionar<PainelMenuRapidoPontoDeVenda>();
				PublicarEventoVenderItemMenuRapido(e.ItemMenuRapidoViewModel);
			});
			CtrlWCommand = new DelegateCommand(() =>
			{
				painelMenuRapidoPontoDeVenda._seletorEsquerdo.Fechar();
				if (painelMenuRapidoPontoDeVenda._seletorEsquerdo.Historico.Any((IPainel x) => x.Is<PainelCardapioPontoDeVenda>()))
				{
					painelMenuRapidoPontoDeVenda._modoFuncionamento.SeletorEsquerdo.Selecionar<PainelCardapioPontoDeVenda>();
				}
				else if (!painelMenuRapidoPontoDeVenda._seletorEsquerdo.Historico.Any((IPainel x) => x.Is<PainelMenuRapidoPontoDeVenda>()))
				{
					painelMenuRapidoPontoDeVenda._seletorEsquerdo.FecharTudo();
				}
				seletorDireito.Get<PainelDocumentoFiscal>()?.Informacao.ControlarFoco();
			});
		}

		protected override void SelecionarOpcionais(Seletor<IPainel> seletor, ItemMenuRapidoSelecionadoComponentesEvent e)
		{
			seletor.Get<PainelMenuRapidoComponentesPontoVenda>().SelecionouItemMenuRapido(e.ItemMenuRapidoViewModel);
			seletor.Selecionar<PainelMenuRapidoComponentesPontoVenda>();
		}

		protected override void Vender(ItemMenuRapidoViewModel arg)
		{
			if (arg.ItemMenuRapido.GruposMenu.Any())
			{
				EventPublisher.Publish(new ItemMenuRapidoSelecionadoAdicionaisPontoVendaEvent(arg));
			}
			else if (arg.ItemMenuRapido.Componentes.Any((ComponenteBase x) => x.Opcional))
			{
				EventPublisher.Publish(new ItemMenuRapidoSelecionadoComponentesPontoVendasEvent(arg));
			}
			else
			{
				PublicarEventoVenderItemMenuRapido(arg);
			}
		}

		private bool PodeMesasContasAbertas()
		{
			if (!PdvEstadoOffline && Habilitado)
			{
				return _seletorEsquerdo.Get<PainelMesasContasAbertasPontoDeVenda>().IsNotNull();
			}
			return false;
		}

		private void MesasContasAbertas()
		{
			try
			{
				_modoFuncionamento.SeletorEsquerdo.Selecionar<PainelMesasContasAbertasPontoDeVenda>();
			}
			catch (Exception)
			{
				DialogoFactory.MostrarDialogoConfirma("Não foi possível alterar para o lançamento por código");
			}
		}

		protected override bool PodeAlterarParaLancamentoPorCodigo()
		{
			if (!PdvEstadoOffline && Habilitado)
			{
				return _seletorEsquerdo.Get<PainelLancamentoCodigoPontoDeVenda>().IsNotNull();
			}
			return false;
		}

		protected override void AlterarParaLancamentoPorCodigo()
		{
			try
			{
				_modoFuncionamento.SeletorEsquerdo.Selecionar<PainelLancamentoCodigoPontoDeVenda>();
				_modoFuncionamento.SeletorDireito.Get<PainelDocumentoFiscal>()?.Informacao.ControlarFoco();
			}
			catch (Exception)
			{
				DialogoFactory.MostrarDialogoConfirma("Não foi possível alterar para o lançamento por código");
			}
		}

		public void SetarModoFuncionamento(IModoFuncionamento modoFuncionamento)
		{
			_modoFuncionamento = modoFuncionamento;
			_emissor = modoFuncionamento.EmissorService;
			_disposable?.Dispose();
			RaisePropertyChanged(() => Habilitado);
			_disposable = new CompositeDisposable
			{
				_emissor.WhenEmissorCarregadoEvent.Subscribe((EventArgs x) =>
				{
					Habilitado = true;
					_carregado = true;
					_seletorEsquerdo.Get<PainelMesasContasAbertasPontoDeVenda>()?.SetarHabilitado(Habilitado);
				}),
				_emissor.WhenEmissorProntoEvent.Subscribe((EventArgs x) =>
				{
					Habilitado = _emissor.Pronto;
					_seletorEsquerdo.Get<PainelMesasContasAbertasPontoDeVenda>()?.SetarHabilitado(Habilitado);
				}),
				_emissor.WhenEmissorErroEvent.Subscribe((string x) =>
				{
					Habilitado = false;
					_seletorEsquerdo.Get<PainelMesasContasAbertasPontoDeVenda>()?.SetarHabilitado(Habilitado);
				})
			};
			_emissor.To<NfceService>()?.WhenPdvOfflineEventEvent.Subscribe((bool x) =>
			{
				PdvEstadoOffline = x;
			});
			_seletorEsquerdo.Get<PainelMesasContasAbertasPontoDeVenda>()?.SetarModoFuncionamento(modoFuncionamento);
			_seletorEsquerdo.Get<PainelLancamentoCodigoPontoDeVenda>()?.SetarModoFuncionamento(modoFuncionamento);
		}

		public override void Habilitar<T>(Seletor<IPainel> seletorDireito)
		{
			if (_carregado)
			{
				base.Habilitar<T>(seletorDireito);
			}
		}
	}
	public class PainelMesasAbertasPafNfce : PainelInteracao<PainelIdentificacaoPafNfce>
	{
		private readonly IWService _service;

		private readonly IImpressoraNaoFiscalService _impressoraNaoFiscalService;

		public string Tipo => DadosSistema.TipoRestaurante;

		public override string Titulo => $"{DadosSistema.TipoMesaContaPlural} abertas";

		public Lista<MesaContaAbertaDto> MesasContasAbertas { get; protected set; } = new Lista<MesaContaAbertaDto>();

		public ICommand ImprimirCommand { get; set; }

		public PainelMesasAbertasPafNfce()
		{
		}

		public PainelMesasAbertasPafNfce(Seletor<IPainel> seletor, IWService service, IImpressoraNaoFiscalService impressoraNaoFiscalService)
			: base(seletor)
		{
			_service = service;
			_impressoraNaoFiscalService = impressoraNaoFiscalService;
			ImprimirCommand = new AsyncCommand(Imprimir, PodeImprimir, allowMultipleExecution: false);
		}

		private bool PodeImprimir()
		{
			if (MesasContasAbertas.IsNotNull())
			{
				return MesasContasAbertas.Numero > 0;
			}
			return false;
		}

		private Task Imprimir()
		{
			return Task.Factory.StartNew(() =>
			{
				try
				{
					IEnumerable<string> dados = RelatorioGerencialRestauranteService.RetornarInformacoesRelatorioGerencialMesasContasAbertas(MesasContasAbertas.Itens);
					_impressoraNaoFiscalService.Imprimir(dados);
				}
				catch (Exception ex)
				{
					ex.ShowLastException();
				}
			}).ContinueWith((Task task) =>
			{
				LoaderProcessoService.EsconderLoader();
				if (task.IsFaulted)
				{
					DialogoFactory.MostrarDialogoConfirma(task.Exception?.InnerException?.Message);
				}
				else
				{
					Seletor.Voltar();
				}
			}, CancellationToken.None, TaskContinuationOptions.None, TaskScheduler.FromCurrentSynchronizationContext());
		}

		public override void Load()
		{
			LoaderProcessoService.MostrarLoader();
			MesasContasAbertas.Limpar();
			_service.Canal((IRestauranteModuleService service) => service.ObterMesasContasAbertas()).ContinueWith((Task<IEnumerable<MesaContaAbertaDto>> task) =>
			{
				ThreadPrincipal.Executar(() =>
				{
					LoaderProcessoService.EsconderLoader();
					if (task.IsFaulted)
					{
						task.Exception.ShowLastException();
						FecharMethod();
					}
					else
					{
						MesasContasAbertas.Adicionar(task.Result);
						MesasContasAbertas.PosicionarNoPrimeiro();
						RecuperarFocoAsync();
						RaisePropertyChanged(() => PodeImprimir());
					}
				});
			});
		}

		public override void UnLoad()
		{
		}

		public override bool PodeVoltar()
		{
			return true;
		}

		public override void Dispose()
		{
			MesasContasAbertas.Dispose();
		}

		protected override void F2Method()
		{
			Seletor.Voltar();
		}
	}
	public class PainelMesasContasAbertasPontoDeVenda : PainelMesasContasAbertas, IPainelEsquerdo, IPainel
	{
		private readonly IEmissorService _emissorService;

		private readonly IWService _service;

		private Seletor<IPainel> _seletorDireito;

		private IModoFuncionamento _modoFuncionamento;

		private readonly IDisposable _disposable;

		public Lista<MesaViewModel> Itens
		{
			get
			{
				return GetProperty(() => Itens);
			}
			set
			{
				SetProperty(() => Itens, value);
			}
		}

		public string InformacaoDataHoraAtualizacao
		{
			get
			{
				string arg;
				if (Itens == null)
				{
					arg = string.Empty;
				}
				else if (Itens.Numero != 0)
				{
					arg = ((Itens.Numero == 1) ? $"1 {DadosSistema.TipoMesaConta.RetornarDescricao()} aberta." : $"{Itens.Numero} {TipoMesasContasCliente.ToLower()} abertas.");
				}
				else
				{
					arg = $"Nenhuma {DadosSistema.TipoMesaConta.RetornarDescricao()} aberta.";
				}
				return $"Atualizado em {DateTime.Now:dd/MM/yyyy HH:mm}. {arg}".ToUpper();
			}
		}

		public ICommand CtrlF1Command { get; set; }

		public ICommand CtrlF2Command { get; set; }

		public ICommand CtrlF6Command { get; set; }

		public ICommand CtrlF5Command { get; set; }

		public ICommand NavegarRestauranteCommand { get; set; }

		public ICommand EmitirConferenciaCommand { get; set; }

		public ICommand ImprimirConferenciaCommand { get; set; }

		public ICommand EmitirDocumentoFiscalCommand { get; set; }

		public ICommand AltMCommand { get; set; }

		public IReadOnlyCollection<string> Atalhos => new List<string>();

		public IEnumerable<ItemMenuAtalho> MenuRibbon => Enumerable.Empty<ItemMenuAtalho>();

		public PainelMesasContasAbertasPontoDeVenda(Seletor<IPainel> seletorDireito, IEmissorService emissorService, IWService service)
		{
			_seletorDireito = seletorDireito;
			_emissorService = emissorService;
			_service = service;
			CtrlF1Command = new DelegateCommand(PosicionarPainelCardapio);
			CtrlF2Command = new DelegateCommand(PosicionarPainelLancamentoCodigo);
			CtrlF5Command = new AsyncCommand(AtualizarAsync);
			NavegarRestauranteCommand = new DelegateCommand(() =>
			{
				NavegarRestaurante(Itens.ItemSelecionado);
			}, () => Itens.IsNotNull() && Itens.PossuiItemSelecionado);
			EmitirConferenciaCommand = new DelegateCommand(() =>
			{
				EmitirConferencia(Itens.ItemSelecionado, mostrarPreview: true);
			}, () => Itens.IsNotNull() && Itens.PossuiItemSelecionado);
			ImprimirConferenciaCommand = new DelegateCommand(() =>
			{
				EmitirConferencia(Itens.ItemSelecionado, mostrarPreview: false);
			}, () => Itens.IsNotNull() && Itens.PossuiItemSelecionado);
			EmitirDocumentoFiscalCommand = new DelegateCommand(() =>
			{
				EmitirDocumentoFiscal(Itens.ItemSelecionado);
			}, () => Itens.IsNotNull() && Itens.PossuiItemSelecionado);
			AltMCommand = new DelegateCommand(() =>
			{
			}, () => false);
			CtrlF6Command = new DelegateCommand(Pesquisar);
			if (!DadosSistema.ObterConfiguracaoClient().ObterConfiguracao().AtualizarMapaMesasContasAbertasAutomaticamente)
			{
				return;
			}
			_disposable = Observable.Interval(TimeSpan.FromSeconds(30.0)).Subscribe((long x) =>
			{
				ThreadPrincipal.Executar(async () =>
				{
					await AtualizarAsync();
				});
			});
		}

		private void PosicionarPainelCardapio()
		{
			try
			{
				if (_modoFuncionamento.SeletorEsquerdo.Historico.Any((IPainel x) => x.Is<PainelMenuRapidoPontoDeVenda>()))
				{
					_modoFuncionamento.SeletorEsquerdo.Selecionar<PainelMenuRapidoPontoDeVenda>();
				}
				else
				{
					_modoFuncionamento.SeletorEsquerdo.Selecionar<PainelCardapioPontoDeVenda>();
				}
			}
			catch (Exception)
			{
				DialogoFactory.MostrarDialogoConfirma("Não foi possível alternar para o painel Cardápio");
			}
		}

		private void PosicionarPainelLancamentoCodigo()
		{
			try
			{
				_modoFuncionamento.SeletorEsquerdo.Selecionar<PainelLancamentoCodigoPontoDeVenda>();
			}
			catch (Exception)
			{
				DialogoFactory.MostrarDialogoConfirma("Não foi possível alternar para o painel de lançamento por código");
			}
		}

		private async Task AtualizarAsync()
		{
			if (_emissorService.To<NfceService>()?.PdvEstadoOffline ?? false)
			{
				return;
			}
			try
			{
				LoaderProcessoService.MostrarLoader();
				await _service.Canal((IRestauranteModuleService s) => s.ObterItensMapaMesas()).ContinueWith((Task<IEnumerable<ItemMapaMesaDto>> result) =>
				{
					if (result.IsFaulted)
					{
						if (result.Exception.GetLastException().Message.Contains("recusou ativamente"))
						{
							_disposable.Dispose();
						}
						result.Exception.ShowLastException();
					}
					else
					{
						ThreadPrincipal.Executar(() =>
						{
							Preencher(result.Result);
						});
						RaisePropertyChanged(() => InformacaoDataHoraAtualizacao);
					}
				}, CancellationToken.None, TaskContinuationOptions.None, TaskScheduler.Default);
			}
			catch (Exception ex)
			{
				ex.ShowLastException();
			}
			finally
			{
				LoaderProcessoService.EsconderLoader();
			}
		}

		private void Preencher(IEnumerable<ItemMapaMesaDto> result)
		{
			if (Itens == null)
			{
				Itens = new Lista<MesaViewModel>();
			}
			long numeroMesaSelecionada = (Itens.PossuiItemSelecionado ? Itens.ItemSelecionado.Numero : 0);
			Itens.Limpar();
			foreach (ItemMapaMesaDto item in result.OrderBy((ItemMapaMesaDto x) => x.NumeroMesa))
			{
				if (!(item.DataHoraAbertura <= DateTime.MinValue))
				{
					if (item.Situacao == SituacaoMesaConta.Aberta)
					{
						Itens.Adicionar(new MesaAbertaViewModel(item.ReservasMesa, item.NumeroMesa, item.NumeroMesaMobile, item.TituloAutoAtendimento, item.Total, item.DataHoraAbertura, item.IsDelivery, EmitirConferencia, EmitirDocumentoFiscal, NavegarRestaurante));
					}
					if (item.Situacao == SituacaoMesaConta.Reservada)
					{
						Itens.Adicionar(new MesaReservadaViewModel(item.ReservasMesa, item.NumeroMesa, item.TituloAutoAtendimento, item.IsDelivery, EmitirConferencia, EmitirDocumentoFiscal, NavegarRestaurante));
					}
					if (item.Situacao == SituacaoMesaConta.SemConsumo)
					{
						Itens.Adicionar(new MesaSemConsumoViewModel(item.ReservasMesa, item.NumeroMesa, item.NumeroMesaMobile, item.TituloAutoAtendimento, item.Total, item.IsDelivery, EmitirConferencia, EmitirDocumentoFiscal, NavegarRestaurante));
					}
					if (item.Situacao == SituacaoMesaConta.ContaEmitida)
					{
						Itens.Adicionar(new MesaContaEmitidaViewModel(item.ReservasMesa, item.NumeroMesa, item.NumeroMesaMobile, item.TituloAutoAtendimento, item.Total, item.IsDelivery, EmitirConferencia, EmitirDocumentoFiscal, NavegarRestaurante));
					}
					if (item.Situacao == SituacaoMesaConta.Bloqueada)
					{
						Itens.Adicionar(new MesaBloqueadaViewModel(item.ReservasMesa, item.NumeroMesa, item.NumeroMesaMobile, item.TituloAutoAtendimento, item.Total, item.IsDelivery, EmitirConferencia, EmitirDocumentoFiscal));
					}
				}
			}
			if (numeroMesaSelecionada == 0L)
			{
				Itens.PosicionarNoPrimeiro();
				return;
			}
			Itens.Posicionar((MesaViewModel x) => x.Numero.Equals(numeroMesaSelecionada));
		}

		private void NavegarRestaurante(MesaViewModel obj)
		{
			if (!DadosSistema.VerificarPermissao<DigisatServer.Infrastructure.Crosscutting.Module.Restaurante, Visualizar>())
			{
				DialogoFactory.MostrarDialogoConfirma("Acesso negado!");
			}
			else if (obj.IsDelivery)
			{
				DialogoFactory.MostrarDialogoConfirma("Não é possível abrir Conta/Mesa para Delivery. \nUtilize o módulo 'Restaurante'");
			}
			else
			{
				DadosSistema.GetEventPublisher().Publish(new ChamarRestauranteEvent(obj.Numero.ToStringOrEmpty()));
			}
		}

		private void EmitirConferencia(MesaViewModel obj, bool mostrarPreview)
		{
			Task.Factory.StartNew(() =>
			{
				VerificarEstadoDocumentoFiscal();
				_emissorService.ImprimirConferenciaMesaConta(obj.Numero, mostrarPreview);
				ThreadPrincipal.Executar(async () =>
				{
					await AtualizarAsync();
				});
			}).ContinueWith((Task task) =>
			{
				if (task.IsFaulted)
				{
					task.Exception.ShowLastException();
				}
			});
		}

		private void VerificarEstadoDocumentoFiscal()
		{
			IEstadoDocumentoFiscal estado = _seletorDireito.Get<PainelDocumentoFiscal>().Estado;
			if (_emissorService.Tipo == TipoMovimentacao.CupomFiscal && estado.IsNot<DocumentoFiscalFechado>())
			{
				throw new Exception($"Estado do documento fiscal inválido. {estado.MensagemOperador}.");
			}
			if (estado.IsNot<DocumentoFiscalFechado>() && estado.IsNot<DocumentoFiscalAberto>())
			{
				throw new Exception($"Estado do documento fiscal inválido. {estado.MensagemOperador}.");
			}
		}

		private void EmitirDocumentoFiscal(MesaViewModel obj)
		{
			if (!_seletorDireito.Get<PainelDocumentoFiscal>().PodeAbrirDocumentoTurno())
			{
				RecuperarFoco();
				return;
			}
			Task.Factory.StartNew(() =>
			{
				VerificarEstadoDocumentoFiscal();
				IEnumerable<ItemMesaContaDto> result = _service.Canal((IRestauranteModuleService service) => service.ObterItensParaDocumentoFiscal(_emissorService.RetornarContadorCupomFiscal(), _emissorService.RetornarNumeroFabricacao(), obj.Numero)).Result;
				List<ItemMesaContaDto> source = result.ToListEmptyWhenNull();
				if (!source.Any())
				{
					throw new Exception($"Nenhuma {DadosSistema.TipoRestaurante} encontrada.");
				}
				_seletorDireito.Get<PainelDocumentoFiscal>().EmitirDocumentoFiscal(result);
				_seletorDireito.Get<PainelDocumentoFiscal>().PreDocumentoFiscal?.SetarNumerosMesasContasClienteImportadas(new long[1] { obj.Numero });
				List<long> numerosMesasContasPedirMenuImportadas = new List<long>(source.Select((ItemMesaContaDto x) => x.NumeroMesaContaPedirMenu));
				_seletorDireito.Get<PainelDocumentoFiscal>().PreDocumentoFiscal?.SetarNumerosMesasContasClientePedirMenuImportadas(numerosMesasContasPedirMenuImportadas);
				RecuperarFoco();
				ThreadPrincipal.Executar(async () =>
				{
					await AtualizarAsync();
				});
			}, CancellationToken.None, TaskCreationOptions.None, TaskScheduler.FromCurrentSynchronizationContext()).ContinueWith((Task task) =>
			{
				if (task.IsFaulted)
				{
					task.Exception.ShowLastException();
				}
				DormirAsync(2000, (object x) =>
				{
					if (_service.Canal((IPreVendaModuleService service) => service.VerificarExistenciaPreVendaAguardando(new List<long> { obj.Numero })) && DialogoFactory.MostrarDialogoSimNao("Existe(m) pré-venda(s) com o(s) número(s) informado(s). Deseja importá-la(s)?") == MessageBoxResult.Yes)
					{
						_seletorDireito.Get<PainelBuscaPreVenda>().AdicionarNumeros(new List<long> { obj.Numero });
						_seletorDireito.Selecionar<PainelBuscaPreVenda>();
					}
				});
			}, CancellationToken.None, TaskContinuationOptions.None, TaskScheduler.FromCurrentSynchronizationContext());
		}

		private void Pesquisar()
		{
			_seletorDireito.Selecionar<PainelPesquisarMesasContas>();
		}

		public bool PodeVoltar()
		{
			return false;
		}

		public async void Load()
		{
			await AtualizarAsync();
		}

		public void FecharMethod()
