	public class PainelModuloRequisicoesExternas : PainelBuscaBase<PainelModuloRequisicoesExternas, RequisicaoExternaLocal, InformacaoBuscaRequisicaoExterna>, IAtalhos, IPainelBusca, IPainelBuscaService<RequisicaoExternaLocal>, IPainelLista<RequisicaoExternaLocal>, IItemMenuRibbon, ITitulo
	{
		public IWService Service { get; protected set; }

		public override string Titulo => "MRE-Requisições Externas";

		public IReadOnlyCollection<string> Atalhos => new List<string> { "[ Enter ] Importar DAV para Cupom Fiscal" };

		public KeyGestureCustom Key => new KeyGestureCustom(System.Windows.Input.Key.J, ModifierKeys.Control);

		public string ToolTip => Titulo;

		public PainelModuloRequisicoesExternas()
		{
		}

		public PainelModuloRequisicoesExternas(IWService service, Seletor<IPainel> seletor)
			: base(seletor)
		{
			Service = service;
			Lista.SetarCabecalho(Cabecalho<CabecalhoRequisicaoExterna>.Criar());
		}

		public override void EnterMethod()
		{
			if (Lista.PossuiItemSelecionado && !Lista.ItemSelecionado.RequisicaoExterna.MovimentacaoDto.Is<MovimentacaoDtoNull>())
			{
				RequisicaoExternaLocal itemSelecionado = Lista.ItemSelecionado;
				if (itemSelecionado.Status.Equals("Denegada"))
				{
					DialogoFactory.MostrarDialogoConfirma("Não é possível emitir o cupom fiscal para requisição externa denegada!");
				}
				else if (itemSelecionado.EmitiuCupomFiscal)
				{
					DialogoFactory.MostrarDialogoConfirma($"Já foi emitido cupom fiscal {itemSelecionado.Ccf} para a requisição externa {itemSelecionado.Numero}!");
				}
				else if (!Seletor.Get<PainelDocumentoFiscal>().PodeAbrir())
				{
					DialogoFactory.MostrarDialogoConfirma($"{Seletor.Get<PainelDocumentoFiscal>().Estado.MensagemOperador}");
				}
				else
				{
					Seletor.Get<PainelDocumentoFiscal>().EmitirDocumentoFiscal(itemSelecionado.RequisicaoExterna.MovimentacaoDto);
				}
				Seletor.Voltar();
			}
		}
	}
