	public class PainelObservacaoPosto : PainelInteracao<PainelObservacaoPosto>, IPainelObservacao, IPainelIndicaConsumidor
	{
		private readonly Seletor<IPainel> _seletorDireito;

		private readonly ItemInteracaoCnpjSemValidacao _cnpj;

		private readonly ItemInteracaoCpfSemValidacao _cpf;

		private readonly ItemInteracaoTexto _ie;

		private readonly ItemInteracaoComboBox _placa;

		private readonly ItemInteracaoDecimal _quilometragem;

		private readonly ItemInteracaoDecimal _horimetro;

		private readonly ItemInteracaoTexto _unidadeConsumidora;

		private ItemInteracaoTexto _outraPlaca;

		private Lista<IItemInteracao> _placas;

		private string _placaSelecionada = string.Empty;

		private string _placaDigitada = string.Empty;

		private readonly Lista<IItemInteracao> _tiposVeiculo;

		private readonly ItemInteracaoComboBox _tipoDaPessoa;

		private readonly ItemInteracaoTexto _observacao;

		private readonly InteracaoComando<string> _interacaoCliente;

		private readonly ItemInteracaoComboBox _maquinaEquipamento;

		public ConsumidorLocal Consumidor
		{
			get
			{
				return GetProperty(() => Consumidor);
			}
			protected set
			{
				SetProperty(() => Consumidor, value);
			}
		}

		private bool IsMaquinaEquipamento => _tiposVeiculo?.ItemSelecionado == _maquinaEquipamento;

		public override string Titulo => "Informe as observações";

		public PainelObservacaoPosto()
		{
		}

		public PainelObservacaoPosto(Seletor<IPainel> seletor)
			: base(seletor)
		{
			_seletorDireito = seletor;
			_interacaoCliente = InteracaoComando<string>.Criar().ComComando(new DelegateCommand(PesquisarPorConsumidor)).Build();
			_cnpj = ItemInteracaoBase<ItemInteracaoCnpjSemValidacao, Cnpj>.Criar().ComDescricao("Cnpj").Build();
			_cpf = ItemInteracaoBase<ItemInteracaoCpfSemValidacao, Cpf>.Criar().ComDescricao("Cpf").Build();
			(from evt in WhenPropertyChanged
				where evt == "Consumidor"
				select Consumidor into consumidor
				where consumidor != null
				select consumidor).ObserveOn(SynchronizationContext.Current).Subscribe((ConsumidorLocal resultado) =>
			{
				CarregarDadosPessoa(resultado.Pessoa);
			});
			Campos.Add(ItemInteracaoBase<ItemInteracaoButtonEditConsumidor, InteracaoComando<string>>.Criar().ComDescricao("Cliente").ComValor(_interacaoCliente)
				.Build());
			_ie = ItemInteracaoBase<ItemInteracaoTexto, string>.Criar().ComDescricao("Inscrição estadual").Build();
			Lista<IItemInteracao> lista = new Lista<IItemInteracao>();
			lista.Adicionar(_cnpj, _ie);
			ItemInteracaoComboBox itemInteracaoComboBox = ItemInteracaoBase<ItemInteracaoComboBox, Lista<IItemInteracao>>.Criar().ComDescricao("Jurídica").ComValor(lista)
				.Build();
			Lista<IItemInteracao> lista2 = new Lista<IItemInteracao>();
			lista2.Adicionar(_cpf);
			ItemInteracaoComboBox itemInteracaoComboBox2 = ItemInteracaoBase<ItemInteracaoComboBox, Lista<IItemInteracao>>.Criar().ComDescricao("Física").ComValor(lista2)
				.Build();
			Lista<IItemInteracao> lista3 = new Lista<IItemInteracao>();
			lista3.Adicionar(itemInteracaoComboBox, itemInteracaoComboBox2);
			_tipoDaPessoa = ItemInteracaoBase<ItemInteracaoComboBox, Lista<IItemInteracao>>.Criar().ComDescricao("Tipo da pessoa").ComValor(lista3)
				.Build();
			Campos.Add(_tipoDaPessoa);
			_observacao = ItemInteracaoBase<ItemInteracaoTexto, string>.Criar().ComDescricao("Outras informações").Build();
			Campos.Add(_observacao);
			_quilometragem = ItemInteracaoBase<ItemInteracaoDecimal, decimal>.Criar().ComDescricao("Quilometragem").Build();
			_placa = ItemInteracaoBase<ItemInteracaoComboBox, Lista<IItemInteracao>>.Criar().ComDescricao("Placa").Build();
			Lista<IItemInteracao> lista4 = new Lista<IItemInteracao>();
			lista4.Adicionar(_quilometragem, _placa);
			_unidadeConsumidora = ItemInteracaoBase<ItemInteracaoTexto, string>.Criar().ComDescricao("Unidade consumidora").Build();
			_horimetro = ItemInteracaoBase<ItemInteracaoDecimal, decimal>.Criar().ComDescricao("Horímetro").Build();
			Lista<IItemInteracao> lista5 = new Lista<IItemInteracao>();
			lista5.Adicionar(_unidadeConsumidora, _horimetro);
			ItemInteracaoComboBox itemInteracaoComboBox3 = ItemInteracaoBase<ItemInteracaoComboBox, Lista<IItemInteracao>>.Criar().ComDescricao("Veículo").ComValor(lista4)
				.Build();
			_maquinaEquipamento = ItemInteracaoBase<ItemInteracaoComboBox, Lista<IItemInteracao>>.Criar().ComDescricao("Máquina/Equipamento").ComValor(lista5)
				.Build();
			_tiposVeiculo = new Lista<IItemInteracao>();
			_tiposVeiculo.Adicionar(itemInteracaoComboBox3, _maquinaEquipamento);
			_tiposVeiculo.AlterouItemSelecionadoEvent += TipoOnAlterouItemSelecionadoEvent;
			Campos.Add(ItemInteracaoBase<ItemInteracaoComboBox, Lista<IItemInteracao>>.Criar().ComDescricao("Tipo").ComValor(_tiposVeiculo)
				.Build());
		}

		private void PesquisarPorConsumidor()
		{
			Seletor.Selecionar<PainelBuscaConsumidorObservacaoPosto>();
		}

		public void IndicarConsumidor(ConsumidorLocal consumidorLocal)
		{
			Consumidor = consumidorLocal;
		}

		public override void Load()
		{
			ConsumidorLocal consumidor = Consumidor;
			if (consumidor != null && consumidor.Pessoa.IsNotNull())
			{
				CarregarDadosPessoa(Consumidor.Pessoa);
			}
			else if (_seletorDireito.Get<PainelDocumentoFiscal>().Consumidor.IsNull())
			{
				AdicionarPlacaOutra();
				PosicionarCampoPlaca();
				_tipoDaPessoa.Valor.PosicionarNoPrimeiro();
			}
			else if (_seletorDireito.Get<PainelDocumentoFiscal>().Consumidor.Pessoa.Is<Consumidor>())
			{
				ConsumidorLocal consumidor2 = _seletorDireito.Get<PainelDocumentoFiscal>().Consumidor;
				if (consumidor2.Documento.RemoveCaracteresAlfanumerico().Length > 11)
				{
					_cnpj.Valor.Numero = consumidor2.Documento;
					_tipoDaPessoa.Valor.PosicionarNoPrimeiro();
				}
				else
				{
					_cpf.Valor.Numero = consumidor2.Documento;
					_tipoDaPessoa.Valor.PosicionarNoUltimo();
				}
				AdicionarPlacaOutra();
				PosicionarCampoPlaca();
			}
			else
			{
				DigisatServer.Domain.Main.Aggregates.CadastrosAgg.Pessoas.Pessoa pessoa = _seletorDireito.Get<PainelDocumentoFiscal>().Consumidor.Pessoa;
				CarregarDadosPessoa(pessoa);
			}
		}

		private void CarregarDadosPessoa(DigisatServer.Domain.Main.Aggregates.CadastrosAgg.Pessoas.Pessoa pessoa)
		{
			if (!pessoa.IsNull())
			{
				if (pessoa.IsJuridica)
				{
					_cnpj.Valor.Numero = pessoa.CpfCnpjFormatado;
					_tipoDaPessoa.Valor.PosicionarNoPrimeiro();
				}
				else
				{
					_cpf.Valor.Numero = pessoa.CpfCnpjFormatado;
					_tipoDaPessoa.Valor.PosicionarNoUltimo();
				}
				_interacaoCliente.ComDado(pessoa.Nome);
				_ie.Valor = pessoa.Carteira.Ie?.Numero ?? string.Empty;
				if (_placas.IsNull())
				{
					_placas = new Lista<IItemInteracao>();
				}
				_placas.AlterouItemSelecionadoEvent -= PlacaOutraOnAlterouItemSelecionadoEvent;
				_placas.Limpar();
				_placas.Adicionar(pessoa.Carteira.Veiculos.Select((Veiculo x) => ItemInteracaoBase<ItemInteracaoTexto, string>.Criar().ComDescricao(x.Placa).ComValor(x.Placa)));
				_placas.AlterouItemSelecionadoEvent += PlacaOutraOnAlterouItemSelecionadoEvent;
				_placa.ComValor(_placas);
				AdicionarPlacaOutra();
				PosicionarCampoPlaca();
			}
		}

		private void AdicionarPlacaOutra()
		{
			Campos.Remove(_placa);
			if (_placas.IsNull())
			{
				_placas = new Lista<IItemInteracao>();
			}
			if (!_placas.Existe((IItemInteracao x) => IsPlacaOutra(x as ItemInteracaoTexto)))
			{
				_placas.Adicionar(ItemInteracaoBase<ItemInteracaoTexto, string>.Criar().ComDescricao("Outra").ComValor("Outra"));
			}
			_placa.ComValor(_placas);
		}

		private void PlacaOutraOnAlterouItemSelecionadoEvent(object sender, IItemInteracao itemInteracao)
		{
			ItemInteracaoTexto itemSelecionado = itemInteracao as ItemInteracaoTexto;
			AdicionarRemoverCampoPlaca(itemSelecionado);
		}

		private void TipoOnAlterouItemSelecionadoEvent(object sender, IItemInteracao itemInteracao)
		{
			if (itemInteracao == _maquinaEquipamento)
			{
				LimparPlaca();
			}
		}

		private void LimparPlaca()
		{
			_placaSelecionada = string.Empty;
			_placaDigitada = string.Empty;
			_outraPlaca?.Limpar();
			Lista<IItemInteracao> lista = _placa?.Valor;
			if (lista.IsNotNull())
			{
				lista.ItemSelecionado = null;
			}
			RemoverCampoPlaca();
		}

		private void PosicionarCampoPlaca()
		{
			if (IsMaquinaEquipamento)
			{
				LimparPlaca();
				return;
			}
			_placa?.Valor?.PosicionarNoPrimeiro();
			if (!string.IsNullOrEmpty(_placaSelecionada))
			{
				_placa?.Valor?.Posicionar((IItemInteracao x) => _placaSelecionada.Equals((x as ItemInteracaoTexto).Valor));
			}
			AtualizarCampoPlaca();
			if (_outraPlaca.IsNotNull() && !string.IsNullOrEmpty(_placaDigitada))
			{
				_outraPlaca.Valor = _placaDigitada;
			}
		}

		private void AtualizarCampoPlaca()
		{
			AdicionarRemoverCampoPlaca(_placa?.Valor?.ItemSelecionado as ItemInteracaoTexto);
		}

		private void AdicionarRemoverCampoPlaca(ItemInteracaoTexto itemSelecionado)
		{
			if (!IsPlacaOutra(itemSelecionado))
			{
				RemoverCampoPlaca();
			}
			else if (!_outraPlaca.IsNotNull() || !Campos.Contains(_outraPlaca))
			{
				_outraPlaca = ItemInteracaoBase<ItemInteracaoTexto, string>.Criar().ComDescricao("Placa").Build();
				Campos.Add(_outraPlaca);
			}
		}

		private void RemoverCampoPlaca()
		{
			Campos.Remove(_outraPlaca);
			_outraPlaca = null;
		}

		private static bool IsPlacaOutra(ItemInteracaoTexto item)
		{
			if (!"Outra".Equals(item?.Valor))
			{
				return "Outra".Equals(item?.Descricao);
			}
			return true;
		}

		private void LimparPlacas()
		{
			if (_placas.IsNotNull())
			{
				_placas.AlterouItemSelecionadoEvent -= PlacaOutraOnAlterouItemSelecionadoEvent;
				_placas.Limpar();
			}
			_placas = null;
		}

		public override void UnLoad()
		{
			RemoverCampoPlaca();
			LimparPlacas();
		}

		public override bool PodeVoltar()
		{
			return true;
		}

		public override void Dispose()
		{
		}

		protected override void Limpar()
		{
			Consumidor = ConsumidorLocal.Criar();
			_placaSelecionada = string.Empty;
			_placaDigitada = string.Empty;
			base.Limpar();
		}

		protected override void F2Method()
		{
			ItemInteracaoTexto itemInteracaoTexto = _placa?.Valor?.ItemSelecionado as ItemInteracaoTexto;
			string placa;
			if (IsPlacaOutra(itemInteracaoTexto))
			{
				placa = _outraPlaca?.Valor ?? string.Empty;
			}
			else if (string.IsNullOrEmpty(itemInteracaoTexto?.Valor))
			{
				placa = string.Empty;
			}
			else
			{
				placa = ((itemInteracaoTexto.Valor.Length == 7) ? itemInteracaoTexto.Valor.Insert(3, "-").ToUpper() : itemInteracaoTexto.Valor.ToUpper());
			}
			_placaSelecionada = itemInteracaoTexto?.Valor ?? string.Empty;
			_placaDigitada = ((!IsPlacaOutra(itemInteracaoTexto)) ? string.Empty : (_outraPlaca?.Valor ?? string.Empty));
			ObservacaoPostoMensagemPromocional observacaoPostoMensagemPromocional = ObservacaoPostoMensagemPromocional.Criar().ComRazaoSocial(_interacaoCliente.Dado).ComCnpj(_cnpj.Valor.Numero)
				.ComCpf(_cpf.Valor.Numero)
				.ComInscricaoEstadual(_ie.Valor)
				.ComPlaca(placa)
				.ComQuilometragem(_quilometragem.Valor)
				.ComUnidadeConsumidora(_unidadeConsumidora.Valor)
				.ComHorimetro(_horimetro.Valor)
				.ComObservacao(_observacao.Valor)
				.Build();
			DadosVeiculoMaquinaEquipamento dadosVeiculoMaquinaEquipamento = FluentFactory<DadosVeiculoMaquinaEquipamentoFactory>.Init().SetarRazaoSocial(_interacaoCliente.Dado).SetarCnpj(_cnpj.Valor.Numero)
				.SetarCpf(_cpf.Valor.Numero)
				.SetarHorimetro(_horimetro.Valor)
				.SetarInscricaoEstadual(_ie.Valor)
				.SetarPlaca(placa)
				.SetarQuilometragem(_quilometragem.Valor)
				.SetarUnidadeConsumidora(_unidadeConsumidora.Valor)
				.SetarObservacao(_observacao.Valor)
				.Criar();
			Seletor.Get<PainelDocumentoFiscal>().PreDocumentoFiscal.SetarObservacao(observacaoPostoMensagemPromocional.TextoFormatado);
			Seletor.Get<PainelTotalizacaoBase>().AdicionarMensagemPromocional(observacaoPostoMensagemPromocional);
			Seletor.Get<PainelDocumentoFiscal>().IndicarDadosVeiculoMaquinaEquipamento(dadosVeiculoMaquinaEquipamento);
			Seletor.Voltar();
		}

		public void ResetToDefault()
		{
			Consumidor = ConsumidorLocal.Criar();
			_interacaoCliente.ComDado(string.Empty);
			_cnpj.Limpar();
			_cpf.Limpar();
			_ie.Limpar();
			_placa?.Limpar();
			_quilometragem.Limpar();
			_unidadeConsumidora.Limpar();
			_horimetro.Limpar();
			_outraPlaca?.Limpar();
			LimparPlacas();
			_placaSelecionada = string.Empty;
			_placaDigitada = string.Empty;
			_observacao.Limpar();
		}
	}
	public class PainelPbm : PainelListaBase<PainelPbm, Pbm>, IAtalhos, IItemMenuRibbon, ITitulo
	{
		private readonly ConfiguracaoFarmacia _configuracaoFarmacia;

		private bool _dadosPortalDrogaria;

		public IReadOnlyCollection<string> Atalhos => new List<string> { "[ Enter ] Selecionar PBM" };

		public string Titulo { get; }

		public KeyGestureCustom Key => new KeyGestureCustom(System.Windows.Input.Key.I, ModifierKeys.Control);

		public string ToolTip { get; }

		public PainelPbm()
		{
		}

		public PainelPbm(Seletor<IPainel> seletor)
			: base(seletor)
		{
			Lista.SetarCabecalho(Cabecalho<CabecalhoPbm>.Criar());
			_configuracaoFarmacia = DadosSistema.ObterConfiguracaoFarmacia();
			if (_configuracaoFarmacia.UtilizarPortalDrogaria)
			{
				ApiDigisatService apiDigisatService = new ApiDigisatService(DadosSistema.ObterProxy());
				DadosPortalDrogariaApi objectJson = DadosPortalDrogariaApi.Criar().ComCnpj(DadosSistema.EmpresaLogada.CpfCnpj);
				apiDigisatService.PostAsync<string>(objectJson).ContinueWith((Task<string> task) =>
				{
					if (!task.IsFaulted && task.Result.Equals("Assinatura - OK"))
					{
						_dadosPortalDrogaria = true;
						return;
					}
					try
					{
						DialogoFactory.MostrarDialogoConfirma($"Portal da Drogaria:{Environment.NewLine}{task.Result}");
					}
					catch (Exception)
					{
						DialogoFactory.MostrarDialogoConfirma($"Portal da Drogaria:{Environment.NewLine}Erro ao consultar validação de assinatura!");
					}
					finally
					{
						RecuperarFoco();
						_dadosPortalDrogaria = false;
					}
				});
			}
			ToolTip = ((!_configuracaoFarmacia.UtilizarEPharma && !_configuracaoFarmacia.UtilizarVidaLink && !_configuracaoFarmacia.UtilizarPortalDrogaria) ? "Importar solicitação Farmácia Popular" : "Importar autorização PBM");
			Titulo = ((!_configuracaoFarmacia.UtilizarEPharma && !_configuracaoFarmacia.UtilizarVidaLink && !_configuracaoFarmacia.UtilizarPortalDrogaria) ? "Importar solicitação" : "Importar autorização");
		}

		public override void Load()
		{
			Lista.Limpar();
			Lista.Adicionar(new Pbm("Farmácia Popular", Seletor));
			if (_configuracaoFarmacia.UtilizarEPharma)
			{
				Lista.Adicionar(new Pbm<PainelConsultaAutorizacaoPbm>(TipoPbm.EPharma, Seletor));
			}
			if (_configuracaoFarmacia.UtilizarVidaLink)
			{
				Lista.Adicionar(new Pbm<PainelConsultaAutorizacaoPbm>(TipoPbm.VidaLink, Seletor));
			}
			if (_configuracaoFarmacia.UtilizarPortalDrogaria && _dadosPortalDrogaria)
			{
				Lista.Adicionar(new Pbm<PainelConsultaAutorizacaoPbm>(TipoPbm.PortalDrogaria, Seletor));
			}
			Lista.PosicionarNoUltimo();
			if (Lista.Numero == 1)
			{
				EnterMethod();
			}
		}

		public override void EnterMethod()
		{
			Seletor.Voltar();
			Lista.ItemSelecionado.SelecionarPainel();
		}

		public override bool PodeVoltar()
		{
			return true;
		}
	}
