	public class PainelIndicaConsumidor : PainelInteracao<PainelIndicaConsumidor>, IAtalhos, IPainelBusca, IItemMenuRibbon, ITitulo
	{
		private readonly IEmissorService _emissorService;

		private readonly IPessoaRepositoryRead _pessoaRepositoryRead;

		private readonly ISessaoService _sessaoService;

		private readonly ItemInteracaoCpfFocusable _cpf;

		private readonly ItemInteracaoConsultaCnpjFocusable _cnpj;

		private readonly ItemInteracaoTextoRequired _nome;

		private readonly ItemInteracaoTexto _endereco;

		private readonly ItemInteracaoTexto _whatsApp;

		private readonly ItemInteracaoTexto _ie;

		private readonly ItemInteracaoEmail _email;

		private readonly Lista<IItemInteracao> _itemFiltro;

		public bool PdvEstadoOffline;

		private readonly Endereco _enderecoPrincipal = new Endereco();

		private readonly Endereco _enderecoEntrega = new Endereco();

		private readonly IConsultaCnpjService _consultaCnpjService;

		public ConsultaCnpjInfo Consulta
		{
			get
			{
				return GetProperty(() => Consulta);
			}
			set
			{
				SetProperty(() => Consulta, value);
			}
		}

		public override string Titulo => "Indicar consumidor";

		public ICommand CtrlF3Command { get; protected set; }

		public IReadOnlyCollection<string> Atalhos => new List<string> { "[ Ctrl + F3 ] Pesquisar consumidor" };

		public KeyGestureCustom Key => new KeyGestureCustom(System.Windows.Input.Key.F3);

		public string ToolTip
		{
			get
			{
				IEmissorService emissorService = _emissorService;
				if (emissorService == null || !emissorService.Is<IEcfService>())
				{
					return "Indicar documento, nome, whatsapp e e-mail do consumidor";
				}
				return "Indicar documento, nome, whatsapp, e-mail e endereço do consumidor";
			}
		}

		public PainelIndicaConsumidor()
		{
		}

		public PainelIndicaConsumidor(IEmissorService emissorService, IPessoaRepositoryRead pessoaRepositoryRead, ISessaoService sessaoService, Seletor<IPainel> seletor)
			: base(seletor)
		{
			_consultaCnpjService = ConsultaCnpjServiceFactory.Create(DadosSistema.ObterProxy());
			emissorService.To<NfceService>()?.WhenPdvOfflineEventEvent.Subscribe((bool x) =>
			{
				PdvEstadoOffline = x;
			});
			_emissorService = emissorService;
			_pessoaRepositoryRead = pessoaRepositoryRead;
			_sessaoService = sessaoService;
			_cpf = ItemInteracaoBase<ItemInteracaoCpfFocusable, Cpf>.Criar().ComDescricao("Cpf").Build();
			Lista<IItemInteracao> lista = new Lista<IItemInteracao>();
			lista.Adicionar(_cpf);
			ItemInteracaoComboBox itemInteracaoComboBox = ItemInteracaoBase<ItemInteracaoComboBox, Lista<IItemInteracao>>.Criar().ComDescricao("Cpf").ComValor(lista)
				.Build();
			_cnpj = ItemInteracaoBase<ItemInteracaoConsultaCnpjFocusable, Cnpj>.Criar().ComDescricao("Cnpj").ComAcao(ConsultarCnpj)
				.Build();
			Lista<IItemInteracao> lista2 = new Lista<IItemInteracao>();
			lista2.Adicionar(_cnpj);
			ItemInteracaoComboBox itemInteracaoComboBox2 = ItemInteracaoBase<ItemInteracaoComboBox, Lista<IItemInteracao>>.Criar().ComDescricao("Cnpj").ComValor(lista2)
				.Build();
			_itemFiltro = new Lista<IItemInteracao>();
			_itemFiltro.Adicionar(itemInteracaoComboBox, itemInteracaoComboBox2);
			_itemFiltro.WhenAlterouItemSelecionado.Subscribe((IItemInteracao x) =>
			{
				ProcessarCampos();
			});
			Campos.Add(ItemInteracaoBase<ItemInteracaoComboBox, Lista<IItemInteracao>>.Criar().ComDescricao("Tipo do documento").ComValor(_itemFiltro)
				.Build());
			_nome = ItemInteracaoBase<ItemInteracaoTextoRequired, string>.Criar().ComDescricao("Nome").Build();
			Campos.Add(_nome);
			_endereco = ItemInteracaoBase<ItemInteracaoTexto, string>.Criar().ComDescricao("Endereço").Build();
			if (emissorService.Is<IEcfService>())
			{
				Campos.Add(_endereco);
			}
			_whatsApp = ItemInteracaoBase<ItemInteracaoTexto, string>.Criar().ComDescricao("WhatsApp").Build();
			Campos.Add(_whatsApp);
			_ie = ItemInteracaoBase<ItemInteracaoTexto, string>.Criar().ComDescricao("Inscrição estadual").Build();
			_email = ItemInteracaoBase<ItemInteracaoEmail, string>.Criar().ComDescricao("E-mail").Build();
			Campos.Add(_email);
			Campos.Add(ItemInteracaoBase<ItemInteracaoEndereco, Endereco>.Criar().ComDescricao("Endereço principal").ComValor(_enderecoPrincipal)
				.ComExpandido(expandido: true)
				.Build());
			Campos.Add(ItemInteracaoBase<ItemInteracaoEndereco, Endereco>.Criar().ComDescricao("Endereço entrega").ComValor(_enderecoEntrega)
				.ComExpandido(expandido: false)
				.Build());
			CtrlF3Command = new DelegateCommand(AbrirBuscaConsumidor, PodeAbrirBuscaConsumidor);
		}

		private void ConsultarCnpj(string cnpj)
		{
			try
			{
				Consulta = null;
				Consulta = _consultaCnpjService.Consultar(cnpj);
				_nome.Valor = Consulta.RazaoSocial;
				_ie.Valor = Consulta.Ies?.FirstOrDefault((DigisatServer.Infrastructure.Crosscutting.Service.ConsultaCnpj.IE x) => x.UF.Equals(Consulta.Uf))?.Numero ?? Consulta.Ies?.FirstOrDefault()?.Numero ?? string.Empty;
				_endereco.Valor = Consulta.EnderecoCompleto;
				_email.Valor = Consulta.Emails.FirstOrDefault();
				_whatsApp.Valor = Consulta.Telefones.FirstOrDefault();
				_enderecoPrincipal.Cep = Consulta.Cep;
				_enderecoPrincipal.Logradouro = Consulta.Logradouro;
				_enderecoPrincipal.Numero = Consulta.Numero;
				_enderecoPrincipal.Bairro = Consulta.Bairro;
				_enderecoPrincipal.Complemento = Consulta.Complemento;
				_enderecoPrincipal.UFs.Posicionar((UFDto x) => x.Sigla == Consulta.Uf);
				_enderecoPrincipal.Municipios.Posicionar((MunicipioDto x) => x.Nome == Consulta.Municipio);
			}
			catch (Exception ex)
			{
				ex.ShowLastException();
			}
		}

		private void ProcessarCampos()
		{
			if (Campos.IndexOf(_nome) >= 0 && _itemFiltro.PossuiItemSelecionado && !((!(_itemFiltro.ItemSelecionado.To<ItemInteracaoComboBox>()?.Valor?.ItemSelecionado?.Is<ItemInteracaoCnpjFocusable>())) ?? true))
			{
				_nome.Limpar();
			}
			else if (Campos.IndexOf(_nome) >= 0 && _nome.Valor.IsNullOrEmpty())
			{
				_nome.Valor = "Cliente consumidor";
			}
			if (_itemFiltro.PossuiItemSelecionado && (_itemFiltro.ItemSelecionado.To<ItemInteracaoComboBox>()?.Valor?.ItemSelecionado?.Is<ItemInteracaoConsultaCnpjFocusable>() ?? false))
			{
				Campos.Insert(4, _ie);
				return;
			}
			_ie?.Limpar();
			Campos.RemoveIfExists(_ie);
		}

		private void AbrirBuscaConsumidor()
		{
			Seletor.Selecionar<PainelBuscaConsumidor>();
		}

		private bool PodeAbrirBuscaConsumidor()
		{
			return true;
		}

		public override void Load()
		{
			ProcessarCampos();
		}

		public override void UnLoad()
		{
		}

		public override bool PodeVoltar()
		{
			return true;
		}

		public override void Dispose()
		{
		}

		protected override bool CanF2Method()
		{
			if (((ItemInteracaoComboBox)_itemFiltro.ItemSelecionado).Valor.ItemSelecionado is ItemInteracaoCpfFocusable)
			{
				return base.CanF2Method();
			}
			if (!_cnpj.Valor.Numero.IsNullOrEmpty())
			{
				return !_nome.Valor.IsNullOrEmpty();
			}
			return false;
		}

		protected override void F2Method()
		{
			string documento = _cnpj.Valor.Numero;
			if (((ItemInteracaoComboBox)_itemFiltro.ItemSelecionado).Valor.ItemSelecionado is ItemInteracaoCpfFocusable)
			{
				documento = _cpf.Valor.Numero;
			}
			Consumidor consumidor = Consumidor.Criar().ComNome(_nome.Valor);
			string endereco;
			if (_emissorService.Is<IEcfService>())
			{
				endereco = _endereco.Valor;
			}
			else
			{
				endereco = (_enderecoEntrega.Preenchido ? _enderecoEntrega.EnderecoToText : _enderecoPrincipal.EnderecoToText);
			}
			Consumidor pessoa = consumidor.ComEndereco(endereco).ComMunicipio(_sessaoService.Sessao.Perfis.ItemSelecionado.Empresa.Municipio.CodigoIbge).ComDocumento(documento)
				.Build();
			ConsumidorLocal consumidorLocal = ConsumidorLocal.Criar().ComPessoa(pessoa);
			Seletor.Get<PainelDocumentoFiscal>().IndicarConsumidor(consumidorLocal);
			try
			{
				if (PdvEstadoOffline || string.IsNullOrEmpty(_nome.Valor) || !DadosSistema.VerificarPermissao<DigisatServer.Infrastructure.Crosscutting.Module.Pessoa, Adicionar>())
				{
					return;
				}
				if (DadosSistema.GetService().Canal((IPessoaModuleService service) => service.VerificarDuplicidadeDocumento(documento)))
				{
					PessoaDto pessoa2;
					if (Consulta.IsNull())
					{
						pessoa2 = DadosSistema.GetService().Canal((IPessoaModuleService x) => x.ObterPessoaPorDocumento(documento));
					}
					else
					{
						DialogoFactory.MostrarDialogoConfirma("Documento já cadastrado, o cadastro será atualizado");
						pessoa2 = AtualizarCadastro(documento);
					}
					Seletor.Get<PainelDocumentoFiscal>().IndicarConsumidor(ConsumidorLocal.Criar().ComPessoa(pessoa2));
					Seletor.VoltarEnquanto<IPainelBusca>();
					Limpar();
				}
				else
				{
					if (documento.RemoveCaracteresAlfanumerico().Length == 11 && DialogoFactory.MostrarDialogoSimNao(string.IsNullOrEmpty(documento) ? "Deseja cadastrar a pessoa indicada (sem tipo de cadastro definido)?" : "Deseja cadastrar a pessoa indicada como cliente?") != MessageBoxResult.Yes)
					{
						return;
					}
					try
					{
						PessoaDto pessoaDto = new PessoaDto
						{
							Nome = _nome.Valor,
							Classificacao = new ClassificacaoDto
							{
								Codigo = 6
							},
							IndicadorOperacao = new CodigoDescricaoDto
							{
								Codigo = -1,
								Descricao = "Não definido"
							}
						};
						if (!string.IsNullOrEmpty(documento))
						{
							if (string.IsNullOrEmpty(_cnpj.Valor.Numero))
							{
								pessoaDto.Cpf = documento;
								pessoaDto.Fisica = new FisicaDto();
							}
							else
							{
								pessoaDto.Juridica = new JuridicaDto
								{
									NomeFantasia = _nome.Valor,
									Cnpj = documento
								};
								if ((Consulta.IsNull() || Consulta.Ies.IsNull() || !Consulta.Ies.Any()) && !_ie.Valor.IsNullOrEmpty())
								{
									pessoaDto.Ie = new IEDto
									{
										Numero = _ie.Valor,
										Uf = _enderecoPrincipal.Municipios.ItemSelecionado.UF
									};
									pessoaDto.Classificacao = new ClassificacaoDto
									{
										Codigo = 1,
										Descricao = Classificacoes.ObterClassificacaoPorCodigo(1).Descricao
									};
								}
								else if (Consulta.IsNotNull() && Consulta.Ies.IsNotNull() && Consulta.Ies.Any())
								{
									pessoaDto.Ie = new IEDto
									{
										Numero = (Consulta.Ies.FirstOrDefault((DigisatServer.Infrastructure.Crosscutting.Service.ConsultaCnpj.IE x) => x.UF.Equals(Consulta.Uf))?.Numero ?? Consulta.Ies.FirstOrDefault().Numero),
										Uf = UFValueObjectService.ObterPorSigla(Consulta.Ies.FirstOrDefault().UF).ProjectedAsDto()
									};
									if (Consulta.IsSimples)
									{
										pessoaDto.Classificacao = new ClassificacaoDto
										{
											Codigo = 5,
											Descricao = Classificacoes.ObterClassificacaoPorCodigo(5).Descricao
										};
									}
									else
									{
										pessoaDto.Classificacao = new ClassificacaoDto
										{
											Codigo = 1,
											Descricao = Classificacoes.ObterClassificacaoPorCodigo(1).Descricao
										};
									}
								}
							}
							pessoaDto.Cliente = new ClienteDto();
						}
						pessoaDto.Fisica.Genero = new GeneroDto
						{
							Codigo = 0
						};
						pessoaDto.Fisica.Raca = new RacaDto
						{
							Codigo = 0
						};
						pessoaDto.Fisica.Deficiencia = new DeficienciaDto
						{
							Codigo = 0
						};
						pessoaDto.Fisica.OpcaoDeficiencia = new OpcoesDeficienciaDto
						{
							Codigo = 0
						};
						if (_enderecoPrincipal.Preenchido)
						{
							pessoaDto.EnderecoPrincipal = new EnderecoDto
							{
								Logradouro = _enderecoPrincipal.Logradouro.ToStringEmptyWhenNull(),
								Bairro = _enderecoPrincipal.Bairro.ToStringEmptyWhenNull(),
								Cep = _enderecoPrincipal.Cep.ToStringEmptyWhenNull(),
								Complemento = _enderecoPrincipal.Complemento.ToStringEmptyWhenNull(),
								Numero = _enderecoPrincipal.Numero.ToStringEmptyWhenNull(),
								Municipio = _enderecoPrincipal.Municipios.ItemSelecionado
							};
						}
						else
						{
							pessoaDto.EnderecoPrincipal = new EnderecoDto
							{
								Logradouro = DadosSistema.EmpresaLogada.Logradouro.ToStringEmptyWhenNull(),
								Bairro = DadosSistema.EmpresaLogada.Bairro.ToStringEmptyWhenNull(),
								Cep = DadosSistema.EmpresaLogada.Cep.ToStringEmptyWhenNull(),
								Complemento = DadosSistema.EmpresaLogada.Complemento.ToStringEmptyWhenNull(),
								Numero = DadosSistema.EmpresaLogada.Numero.ToStringEmptyWhenNull(),
								Municipio = DadosSistema.EmpresaLogada.Municipio.ProjectedAsDto()
							};
						}
						if (_enderecoEntrega.Preenchido)
						{
							pessoaDto.EnderecoEntrega = new EnderecoDto
							{
								Logradouro = _enderecoEntrega.Logradouro.ToStringEmptyWhenNull(),
								Bairro = _enderecoEntrega.Bairro.ToStringEmptyWhenNull(),
								Cep = _enderecoEntrega.Cep.ToStringEmptyWhenNull(),
								Complemento = _enderecoEntrega.Complemento.ToStringEmptyWhenNull(),
								Numero = _enderecoEntrega.Numero.ToStringEmptyWhenNull(),
								Municipio = _enderecoEntrega.Municipios.ItemSelecionado
							};
						}
						if (!string.IsNullOrEmpty(_whatsApp?.Valor))
						{
							pessoaDto.TelefoneWhatsApp = new TelefoneDto
							{
								Numero = _whatsApp.Valor
							};
						}
						if (!string.IsNullOrEmpty(_email?.Valor))
						{
							pessoaDto.EmailPrincipal = new EnderecoEletronicoDto
							{
								Endereco = _email.Valor
							};
						}
						if (!string.IsNullOrEmpty(pessoaDto.Id))
						{
							return;
						}
						PessoaDto pessoaCadastrada = DadosSistema.GetService().Canal((IPessoaModuleService service) => service.AdicionarAsync(pessoaDto)).Result;
						if (string.IsNullOrEmpty(documento))
						{
							return;
						}
						DigisatServer.Domain.Main.Aggregates.CadastrosAgg.Pessoas.Pessoa byId = _pessoaRepositoryRead.GetById(pessoaCadastrada.Id.TryParseReferencia());
						if (byId.IsNotNull())
						{
							Seletor.Get<PainelDocumentoFiscal>().IndicarConsumidor(ConsumidorLocal.Criar().ComPessoa(byId));
							return;
						}
						PessoaDto pessoaDto2 = DadosSistema.GetService().Canal((IPessoaModuleService service) => service.ObterPessoaPorId(pessoaCadastrada.Id));
						Seletor.Get<PainelDocumentoFiscal>().IndicarConsumidor(pessoaDto2.IsNotNull() ? ConsumidorLocal.Criar().ComPessoa(pessoaDto2) : ConsumidorLocal.Criar().ComPessoa(pessoaCadastrada));
						return;
					}
					catch (Exception)
					{
						return;
					}
				}
			}
			catch (Exception ex2)
			{
				ex2.ShowLastException();
			}
			finally
			{
				Seletor.VoltarEnquanto<IPainelBusca>();
				Limpar();
			}
		}

		public PessoaDto AtualizarCadastro(string documento)
		{
			PessoaDto pessoaCadastrada = DadosSistema.GetService().Canal((IPessoaModuleService x) => x.ObterPessoaPorDocumento(documento));
			BaseDto baseDto = MunicipioValueObjectService.ObterMunicipioPorNomeESiglaUFDto(Consulta.Municipio, Consulta.Uf);
			pessoaCadastrada.Nome = Consulta.RazaoSocial;
			if (pessoaCadastrada.Juridica.IsExactlyObject<JuridicaDto>())
			{
				pessoaCadastrada.Juridica.NomeFantasia = ((Consulta.NomeFantasia.IsNullOrEmpty() || Consulta.NomeFantasia.Contains("***")) ? Consulta.RazaoSocial : Consulta.NomeFantasia);
			}
			if (Consulta.Emails.Any())
			{
				pessoaCadastrada.EmailPrincipal = new EnderecoEletronicoDto
				{
					Endereco = Consulta.Emails.First()
				};
				List<EnderecoEletronicoDto> list = pessoaCadastrada.EmailsNfe.ToList();
				list.AddRange(from email in Consulta.Emails.Skip(1)
					select new EnderecoEletronicoDto
					{
						Endereco = email
					});
				pessoaCadastrada.EmailsNfe = list;
			}
			pessoaCadastrada.EnderecoPrincipal = new EnderecoDto
			{
				Logradouro = Consulta.Logradouro.ToStringEmptyWhenNull(),
				Numero = Consulta.Numero.ToStringEmptyWhenNull(),
				Complemento = Consulta.Complemento.ToStringEmptyWhenNull(),
				Bairro = Consulta.Bairro.ToStringEmptyWhenNull(),
				Municipio = (baseDto.Is<MunicipioDtoNull>() ? new MunicipioDtoNull() : ((MunicipioDto)baseDto)),
				Cep = Consulta.Cep.ToStringEmptyWhenNull()
			};
			if (Consulta.Telefones.Any())
			{
				pessoaCadastrada.TelefonePrincipal = new TelefoneDto
				{
					Numero = Consulta.Telefones.First()
				};
				List<TelefoneDto> list2 = pessoaCadastrada.Celulares.ToList();
				list2.AddRange(from telefone in Consulta.Telefones.Skip(1)
					select new TelefoneDto
					{
						Numero = telefone
					});
				pessoaCadastrada.Celulares = list2;
			}
			if (Consulta.Ies.IsNotNull() && Consulta.Ies.Any())
			{
				pessoaCadastrada.Ie = new IEDto
				{
					Numero = (Consulta.Ies.FirstOrDefault((DigisatServer.Infrastructure.Crosscutting.Service.ConsultaCnpj.IE x) => x.UF.Equals(Consulta.Uf))?.Numero.ToStringEmptyWhenNull() ?? Consulta.Ies.FirstOrDefault().Numero.ToStringEmptyWhenNull()),
					Uf = UFValueObjectService.ObterPorSigla(Consulta.Ies.FirstOrDefault().UF).ProjectedAsDto()
				};
			}
			return DadosSistema.GetService().Canal((IPessoaModuleService x) => x.AtualizarAsync(pessoaCadastrada)).Result;
		}

		protected override void Limpar()
		{
			_cnpj?.Valor.Limpar();
			_cpf?.Valor.Limpar();
			_ie?.Limpar();
			_nome?.Limpar();
			_endereco?.Limpar();
			_whatsApp?.Limpar();
			_email?.Limpar();
			_itemFiltro?.PosicionarNoPrimeiro();
			_enderecoPrincipal?.Limpar();
			_enderecoEntrega?.Limpar();
			Consulta = null;
		}
	}
	public abstract class PainelInformacao<TClass, TItem, TInformacao> : PainelListaBase<TClass, TItem> where TClass : class, new() where TItem : class where TInformacao : class, IInformacao
	{
		public TInformacao Informacao
		{
			get
			{
				return GetProperty(() => Informacao);
			}
			set
			{
				SetProperty(() => Informacao, value);
			}
		}

		protected PainelInformacao()
		{
		}

		protected PainelInformacao(Seletor<IPainel> seletor)
			: base(seletor)
		{
			Informacao = (TInformacao)Activator.CreateInstance(typeof(TInformacao), this);
		}

		public override void Load()
		{
			Informacao.Limpar();
		}

		protected override void Limpar()
		{
			Informacao.Limpar();
			base.Limpar();
		}
	}
