			: base(seletorDireito)
		{
			PainelDocumentoFiscal painelDocumentoFiscal = this;
			CardapioRepositoryRead = cardapioRepositoryRead;
			MenuRapidoRepositoryRead = menuRapidoRepositoryRead;
			ImpressoraRepositoryRead = impressoraRepositoryRead;
			ProdutoServicoEmpresaRepositoryRead = produtoServicoEmpresaRepositoryRead;
			SessaoService = sessaoService;
			_perfilEmpresa = SessaoService.Sessao.Perfis.ItemSelecionado;
			_empresa = pessoaRepositoryRead.GetById(ObjectId.Parse(_perfilEmpresa.Empresa.Id));
			_largura = System.Windows.Application.Current.MainWindow.ActualWidth;
			_preDocumentoFiscalRepositoryWrite = preDocumentoFiscalRepositoryWrite;
			_preDocumentoFiscalRepositoryRead = preDocumentoFiscalRepositoryRead;
			_pessoaRepositoryRead = pessoaRepositoryRead;
			_movimentacaoRepositoryWrite = movimentacaoRepositoryWrite;
			_operacaoFiscalRepositoryRead = operacaoFiscalRepositoryRead;
			_promocaoScanntechRepositoryRead = promocaoScanntechRepositoryRead;
			_balancaService = balancaService;
			_emissorService = emissorService;
			_eventPublisher = eventPublisher;
			SeletorEsquerdo = seletorEsquerdo;
			_service = service;
			_usuarioRepositoryRead = usuarioRepositoryRead;
			_valorSangriaRepositoryRead = valorSangriaRepositoryRead;
			_farmaciaService = farmaciaService;
			_preDocumentoFiscalPausadoRepositoryWrite = preDocumentoFiscalPausadoRepositoryWrite;
			_emissorService.WhenDocumentoFiscalAbertoEvent.ObserveOn((SynchronizationContext)new DispatcherSynchronizationContext()).Subscribe((EventArgs args) =>
			{
				Estado = DocumentoFiscalAberto.Criar();
			});
			_emissorService.WhenEmissorProntoEvent.ObserveOn((SynchronizationContext)new DispatcherSynchronizationContext()).Subscribe((EventArgs args) =>
			{
				if (!(Estado is DocumentoFiscalAberto) && (!(Estado is DocumentoFiscalBloqueado) || Estado.IsExactlyObject<DocumentoFiscalBloqueadoSemAberturaTurno>()))
				{
					if (!_emissorService.VerificarDocumentoFiscalFechado(PreDocumentoFiscal))
					{
						Estado = DocumentoFiscalAberto.Criar();
						DormirAsync(500, (object a) =>
						{
							Informacao.ControlarFoco();
						});
					}
					else
					{
						Estado = DocumentoFiscalFechado.Criar();
						DormirAsync(500, (object a) =>
						{
							Informacao.ControlarFoco();
						});
					}
				}
			});
			_emissorService.WhenEmissorErroEvent.ObserveOn((SynchronizationContext)new DispatcherSynchronizationContext()).Subscribe((string args) =>
			{
				if (DadosSistema.IsPostoCombustivel && _emissorService is INotaManualService)
				{
					if (Estado is DocumentoFiscalCarregando)
					{
						Estado = DocumentoFiscalFechado.Criar();
					}
				}
				else
				{
					Estado = ((!string.IsNullOrWhiteSpace(args)) ? DocumentoFiscalEmissorEmErro.Criar().ComMensagem(args) : DocumentoFiscalEmissorEmErro.Criar());
				}
			});
			_emissorService.WhenEmissorAvisoEvent.ObserveOn((SynchronizationContext)new DispatcherSynchronizationContext()).Subscribe((string args) =>
			{
				if (!(Estado is DocumentoFiscalBloqueado))
				{
					Estado = DocumentoFiscalEmissorAviso.Criar().ComMensagem(args);
				}
			});
			_emissorService.WhenDocumentoFiscalCanceladoEvent.Subscribe((string identificadorDocumento) =>
			{
				eventPublisher.Publish(new CancelouPreDocumentoFiscalEvent(painelDocumentoFiscal.PreDocumentoFiscal, painelDocumentoFiscal._emissorService, identificadorDocumento));
			});
			eventPublisher.GetEvent<DocumentoFiscalBloqueado>().ObserveOn((SynchronizationContext)new DispatcherSynchronizationContext()).Subscribe((DocumentoFiscalBloqueado args) =>
			{
				Estado = args;
			});
			_emissorService.To<NfceService>()?.WhenPdvOfflineEventEvent.Subscribe((bool x) =>
			{
				PdvEstadoOffline = x;
				RaisePropertyChanged(() => MenuRibbon);
				CriarTipoDocumentoFiscalVerificandoPdvEstadoOffline();
			});
			CtrlF3Command = new CustomDelegateCommand(new KeyGestureControl(Key.F3), AbrirBuscaConsumidor, PodeAbrirBuscaConsumidor);
			F3Command = new CustomDelegateCommand(new KeyGestureCustom(Key.F3), AbrirIndicaConsumidor, PodeAbrirIndicaConsumidor);
			F7Command = new CustomDelegateCommand(new KeyGestureCustom(Key.F7), () =>
			{
				Seletor.Selecionar<PainelBuscaProdutoServico>();
			}, EstadoDocumentoFiscalValido);
			F8Command = new CustomDelegateCommand(new KeyGestureCustom(Key.F8), () =>
			{
				Seletor.Selecionar<PainelCatalogoGrupo>();
			}, PodeAbrirPainelCatalogoGrupo);
			F9Command = new CustomDelegateCommand(new KeyGestureCustom(Key.F9), AbrirPainelBuscaDocumentoFiscal, () => !PdvEstadoOffline && EstadoDocumentoFiscalValido());
			CtrlF10Command = new CustomDelegateCommand(new KeyGestureControl(Key.F10), AbrirPainelBuscaNotaFiscalEletronica, () => !PdvEstadoOffline && EstadoDocumentoFiscalValido());
			F10Command = new CustomDelegateCommand(new KeyGestureCustom(Key.F10), () =>
			{
