			CtrlF12Command = new CustomDelegateCommand(new KeyGestureControl(Key.F12), AbrirMenuAdministrativo, PodeAbrirMenuAdministrativo);
			CtrlKCommand = new CustomDelegateCommand(new KeyGestureControl(Key.K), () =>
			{
