			CtrlRCommand = new CustomDelegateCommand(new KeyGestureControl(Key.R), AbrirRecebimento, () => !PdvEstadoOffline && PodeAbrirRecebimento());
			CtrlFCommand = new CustomDelegateCommand(new KeyGestureControl(Key.F), ImportarMesaContaCliente, () => !PdvEstadoOffline && PodeImportarMesaContaCliente());
			CtrlNCommand = new CustomDelegateCommand(new KeyGestureControl(Key.N), ChamarSenha, () => !PdvEstadoOffline && PodeChamarSenha());
			CtrlICommand = new CustomDelegateCommand(new KeyGestureControl(Key.I), ExecutarCtrlI, PodeExecutarCtrlI);
			HomeCommand = new CustomDelegateCommand(new KeyGestureCustom(Key.Home), AbrirBuscaVendedor, PodeAbrirBuscaVendedor);
			AltPCommand = new CustomDelegateCommand(new KeyGestureControl(Key.P), AlterarPrecoVenda, PodeAlterarPrecoVenda);
			CtrlPCommand = new CustomDelegateCommand(new KeyGestureControl(Key.P), SalvarPreDocumentoFiscal, PodeSalvarPreDocumentoFiscal);
			CtrlF9Command = new CustomDelegateCommand(new KeyGestureControl(Key.F9), () =>
			{
				Seletor.Selecionar<PainelBuscaVendaPausada>();
