				{
					Lista.PosicionarNoProximo();
				}
				Informacao.UsouSetasTeclado = false;
			});
			PlusCommand = new DelegateCommand(AplicarAcrescimo, PodeAplicarDescontoAcrescimo);
			MinusCommand = new DelegateCommand(AplicarDesconto, PodeAplicarDescontoAcrescimo);
			F4Command = new DelegateCommand(Abrir, PodeAbrir);
			F5Command = new AsyncCommand(Totalizar, PodeTotalizar);
			CtrlF5Command = new DelegateCommand(InicializarEmissor, PodeInicializarEmissor);
			F6Command = new DelegateCommand(Cancelar, PodeCancelar);
			EndCommand = new DelegateCommand(AbrirGaveta, PodeAbrirGaveta);
			OemPlusCommand = new AsyncCommand(LerPeso, PodeLerPeso, allowMultipleExecution: false);
			CtrlTCommand = new CustomDelegateCommand(new KeyGestureControl(Key.T), AbrirTabelasPreco, PodeAbrirPainelBuscaTabelaPreco);
			CtrlOCommand = new DelegateCommand(AbrirObservacao, PodeAbrirObservacao);
			CtrlGCommand = new CustomDelegateCommand(new KeyGestureControl(Key.G), AbrirImportacaoParcialMesaConta, () => !PdvEstadoOffline && PodeAbrirImportacaoParcialMesaConta());
			CtrlYCommand = new CustomDelegateCommand(new KeyGestureControl(Key.Y), AbrirPainelPedidosIfood, PodeAbrirPainelPedidosIfood);
			CtrlECommand = new CustomDelegateCommand(new KeyGestureControl(Key.E), AbrirPainelAdicionarMesaContaCreditoCliente, () => !PdvEstadoOffline && PodeAbrirPainelAdicionarMesaContaCreditoCliente());
			AltMCommand = new CustomDelegateCommand(new KeyGestureAlt(Key.M), AbrirPainelMenuRapido, () => PodeAbrirPainelMenuRapido() && (DadosSistema.IsAdministrador || DadosSistema.ContemModuloAdicional(162)));
			AltRCommand = new CustomDelegateCommand(new KeyGestureAlt(Key.R), AbrirRestaurante, PodeAbrirRestaurante);
			_bwItens = new BackgroundWorker
			{
				WorkerSupportsCancellation = true
			};
			_bwItens.DoWork += BwItensOnDoWork;
			_bwItens.RunWorkerAsync();
			Lista.AdicionouEvent += ListaOnAdicionouEvent;
			Informacao.LimpouEvent += InformacaoOnLimpouEvent;
			Informacao.ListaProdutoServico.AlterouItemSelecionadoEvent += ListaProdutoServicoOnAlterouItemSelecionadoEvent;
			if (_emissorService.SemConfiguracao)
			{
				Estado = DocumentoFiscalEmissorEmErro.Criar();
			}
			_eventPublisher.GetEvent<ExecutouLogonEvent>().Subscribe((ExecutouLogonEvent e) =>
			{
				TrocarUsuarioVendedor();
			});
			_eventPublisher.GetEvent<TrocouEmpresaEvent>().Subscribe((TrocouEmpresaEvent e) =>
			{
				_perfilEmpresa = SessaoService.Sessao.Perfis.ItemSelecionado;
				_empresa = _pessoaRepositoryRead.GetById(ObjectId.Parse(_perfilEmpresa.Empresa.Id));
				_emissorService?.LimparUltimoDocumentoEmitido();
				SeletorEsquerdo.Get<PainelMenuRapidoBase>()?.Atualizar();
				_emissorService?.CancelarSeDocumentoAberto();
				_preDocumentoFiscalRepositoryWrite.DeleteAll();
				FinalizarDocumentoFiscal();
			});
			Lista.WhenAlterouItemSelecionado.Subscribe((ItemDocumentoFiscal @event) =>
			{
				@event.ProdutoServicoLocal.ToDo((ProdutoServicoLocal produto) =>
				{
					_eventPublisher.Publish(new SelecionouItemDocumentoFiscalProdutoEvent((!produto.Is<ProdutoLocal>()) ? produto.To<ServicoLocal>()?.Imagem : produto.To<ProdutoLocal>()?.Imagem));
				});
			});
			try
			{
				PdvEstadoOffline = !_service.Canal((IPdvOfflineModuleService a) => a.VerificarAtivacaoPdvOffline());
			}
			catch (Exception ex)
			{
				ConfiguracaoOffline configuracaoOffline = ConfiguracaoOffline.Carregar();
				if (ex.Message.Contains("Off-line") && configuracaoOffline.PdvOfflineValido && DadosSistema.HabilitacaoLocalContemModuloPdvOffline())
				{
					ThreadPrincipal.Executar(() =>
					{
						PdvEstadoOffline = true;
						OnPdvOffline(pdvOffline: true);
					});
				}
			}
			if (DadosSistema.ConfiguracaoDto?.Saida?.UtilizarPainelMenuRapidoComoPadrao?.Valor ?? false)
			{
				DormirAsync(1000, (object x) =>
				{
					AbrirPainelMenuRapido();
				});
			}
			AltF1Command = new CustomDelegateCommand(new KeyGestureAlt(Key.F1), VerificarPdvOffline, PodeVerificarPdvOffline);
			_podeVerificarPdvOffline = DadosSistema.HabilitacaoLocalContemModuloPdvOffline();
		}

		private void BwItensOnDoWork(object sender, DoWorkEventArgs doWorkEventArgs)
		{
			while (true)
			{
				Thread.Sleep(20);
				if (Dispatcher.CurrentDispatcher.HasShutdownStarted || Dispatcher.CurrentDispatcher.HasShutdownFinished)
				{
					break;
				}
				if (Estado.IsNot<DocumentoFiscalAberto>())
				{
					continue;
				}
				_itens.TryDequeue(out var result);
				if (result == null)
				{
					continue;
				}
				try
				{
					ExecutarVenda(result);
				}
				catch (Exception ex)
				{
					Exception ex2 = ex;
					Exception ex3 = ex2;
					ThreadPrincipal.Executar(() =>
					{
						ex3.ShowLastException();
					});
				}
			}
		}

		public IEnumerable<ItemDocumentoFiscal> ObterItensPendentes()
		{
			return _itens.ToList();
		}

		private void ExecutarVenda(ItemDocumentoFiscal itemDocumentoFiscal)
		{
			if (_cancelando && _emissorService.Is<IEcfService>())
			{
				throw new Exception("ECF executando comando. Tente novamente!");
			}
			if (!itemDocumentoFiscal.IsNull())
			{
				if (itemDocumentoFiscal.NumeroItem == 0)
				{
					itemDocumentoFiscal.ComNumeroItem(Lista.Itens.Count + 1);
				}
				_emissorService.Vender(itemDocumentoFiscal);
				itemDocumentoFiscal.VerificarCondicaoEspecial(Lista.Itens, _emissorService);
				itemDocumentoFiscal.VerificarDescontoPbm(_emissorService);
				itemDocumentoFiscal.CalcularValorIcmsDesonerado(PreDocumentoFiscal);
				AdicionarItemDocumentoFiscal(itemDocumentoFiscal);
				PreDocumentoFiscal.Salvar();
			}
		}

		public void RecarregarPreDocumentoFiscal()
		{
			if (Estado is DocumentoFiscalBloqueado || _recarregandoPreDocumentoFiscal)
			{
				return;
			}
			Estado = DocumentoFiscalCarregando.Criar();
			_recarregandoPreDocumentoFiscal = true;
			PreDocumentoFiscal preDocumentoFiscal = _preDocumentoFiscalRepositoryRead.FindOne(new TrueSpecification<PreDocumentoFiscal>());
			if (preDocumentoFiscal == null || !preDocumentoFiscal.CompararContadorOrdemOperacao(_emissorService.RetornarContadorOrdemOperacao()) || preDocumentoFiscal.Empresa.CpfCnpj != DadosSistema.EmpresaLogada.CpfCnpj)
			{
				if (_emissorService.Is<INfceService>() && _emissorService.To<INfceService>().ObterTipoEmissao() == DigisatServer.Infrastructure.Crosscutting.DFe.Util.Configuracoes.TipoEmissao.ContingenciaOfflineNfce)
				{
					_recarregandoPreDocumentoFiscal = false;
					return;
				}
				_emissorService.CancelarSeDocumentoAberto();
				_preDocumentoFiscalRepositoryWrite.DeleteAll();
				if (_emissorService.IsNot<IEcfService>())
				{
					Estado = DocumentoFiscalFechado.Criar();
				}
				_recarregandoPreDocumentoFiscal = false;
				return;
			}
			if (preDocumentoFiscal.EmPagamento || _emissorService.VerificarReducaoZPendente())
			{
				PreDocumentoFiscal = preDocumentoFiscal;
				PreDocumentoFiscal.SetarRepositorios(_preDocumentoFiscalRepositoryWrite, _movimentacaoRepositoryWrite, _operacaoFiscalRepositoryRead, _promocaoScanntechRepositoryRead);
				PreDocumentoFiscal.SetarEmissorService(_emissorService);
				ExecutarCancelamento();
				_recarregandoPreDocumentoFiscal = false;
				return;
			}
			if (preDocumentoFiscal.CanceladoSemItens)
			{
				_preDocumentoFiscalRepositoryWrite.DeleteAll();
				_emissorService.VerificarEstado();
				_recarregandoPreDocumentoFiscal = false;
				return;
			}
			if (!preDocumentoFiscal.EmPagamento && _emissorService.VerificarDocumentoFiscalFechado(preDocumentoFiscal) && preDocumentoFiscal.CompararContadorOrdemOperacao(_emissorService.RetornarContadorOrdemOperacao()))
			{
				preDocumentoFiscal.SetarRepositorios(_preDocumentoFiscalRepositoryWrite, _movimentacaoRepositoryWrite, _operacaoFiscalRepositoryRead, _promocaoScanntechRepositoryRead);
				preDocumentoFiscal.SetarEmissorService(_emissorService);
				preDocumentoFiscal.Cancelar(_emissorService.Tipo);
				_recarregandoPreDocumentoFiscal = false;
				return;
			}
			PreDocumentoFiscal = preDocumentoFiscal;
			PreDocumentoFiscal.SetarRepositorios(_preDocumentoFiscalRepositoryWrite, _movimentacaoRepositoryWrite, _operacaoFiscalRepositoryRead, _promocaoScanntechRepositoryRead);
			PreDocumentoFiscal.SetarEmissorService(_emissorService);
			IndicarConsumidor(PreDocumentoFiscal.Consumidor);
			IndicarVendedor(PreDocumentoFiscal.Vendedor);
			IndicarTabelaPreco(PreDocumentoFiscal.TabelaPreco);
			Seletor.Get<PainelBuscaTabelaPreco>().Reload(PreDocumentoFiscal.TabelaPreco);
			IndicarDadosVeiculoMaquinaEquipamento(PreDocumentoFiscal.DadosVeiculoMaquinaEquipamento);
			DescontouCashback(PreDocumentoFiscal.UtilizouCashback, PreDocumentoFiscal.ValorCashbackUtilizado);
			Seletor.Get<PainelObservacao>().Reload(PreDocumentoFiscal.Observacao);
			Lista.Limpar();
			foreach (ItemDocumentoFiscal iten in PreDocumentoFiscal.Itens)
			{
				AdicionarItemDocumentoFiscal(iten);
			}
			PreDocumentoFiscal.AdicionarItens(Lista.Itens);
			_emissorService.To<ICFeService>()?.SetarCFeDto(preDocumentoFiscal.CFeDto);
			Estado = DocumentoFiscalAberto.Criar();
			_recarregandoPreDocumentoFiscal = false;
		}

		private bool EstadoDocumentoFiscalValido()
		{
			if (!Estado.Is<DocumentoFiscalEmissorEmErro>() && !Estado.Is<DocumentoFiscalCarregando>())
			{
				return !Estado.Is<DocumentoFiscalBloqueado>();
			}
			return false;
		}

		private void CancelarItem()
		{
			if (!PodeCancelarItem())
			{
				return;
			}
			if (!DadosSistema.TurnoAberto && !PdvEstadoOffline)
			{
				DialogoFactory.MostrarDialogoConfirma("É necessário realizar a abertura do turno antes de cancelar item do documento fiscal");
			}
			else
			{
				if (DialogoFactory.MostrarDialogoSimNao((Lista.ItemSelecionado.TemCondicaoEspecial && DateTime.Now >= Lista.ItemSelecionado.CondicaoEspecial.DataVigenciaInicial.Date && DateTime.Now <= Lista.ItemSelecionado.CondicaoEspecial.DataVigenciaFinal.ToFinalDia()) ? "Todos os itens já lançados com o mesmo Produto/Serviço serão cancelados por possuírem condição especial no cadastro. Confirmar?" : "Cancelar item?") != MessageBoxResult.Yes)
				{
					return;
				}
				AutorizacaoDto autorizacaoDto = SessaoService.VerificarPermissao<DigisatServer.Infrastructure.Crosscutting.Module.PontoDeVenda, PermitirCancelarItemDocumentoFiscal>();
				if (autorizacaoDto == null)
				{
					return;
				}
				PreDocumentoFiscal?.AdicionarAutorizacao(autorizacaoDto);
				try
				{
					if (Lista.ItemSelecionado.TemCondicaoEspecial && DateTime.Now >= Lista.ItemSelecionado.CondicaoEspecial.DataVigenciaInicial.Date && DateTime.Now <= Lista.ItemSelecionado.CondicaoEspecial.DataVigenciaFinal.ToFinalDia())
					{
						foreach (ItemDocumentoFiscal item in Lista.Itens.Where((ItemDocumentoFiscal x) => x.Ativo && x.Codigo == Lista.ItemSelecionado.Codigo))
						{
							_emissorService.CancelarItem(item.NumeroItem);
							item.Cancelar(autorizacaoDto);
							_eventPublisher.Publish(new CancelouItemEvent(item, _emissorService));
						}
					}
					else
					{
						_emissorService.CancelarItem(Lista.ItemSelecionado.NumeroItem);
						Lista.ItemSelecionado.Cancelar(autorizacaoDto);
						_eventPublisher.Publish(new CancelouItemEvent(Lista.ItemSelecionado, _emissorService));
					}
					List<string> referenciasItensMesaConta = ObterReferenciasItensMesaConta(Lista.ItemSelecionado);
					if (DadosSistema.IsRestauranteOuHotel && referenciasItensMesaConta.Any() && _emissorService.Tipo != TipoMovimentacao.CupomFiscal && Lista.ItemSelecionado.IsNotNull())
					{
						if (DialogoFactory.MostrarDialogoSimNao($"Retornar o item integralmente para a {DadosSistema.TipoRestaurante}") == MessageBoxResult.Yes)
						{
							_service.Canal((IRestauranteModuleService x) => x.ReabrirItensMesasContas(referenciasItensMesaConta));
						}
						else
						{
							_service.Canal((IRestauranteModuleService x) => x.SetarCanceladoDocumentoFiscalAntesFinalizacaoSemRetornoItensMesaConta(referenciasItensMesaConta, DadosSistema.NomeUsuario));
						}
					}
					PreDocumentoFiscal.Salvar();
					Lista.PosicionarNoUltimo();
					Informacao.Limpar();
					Informacao.ControlarFoco();
				}
				catch (Exception ex)
				{
					DialogoFactory.MostrarDialogoConfirma($"Falha ao cancelar item{Environment.NewLine}{ex.Message}");
				}
			}
		}

		private static List<string> ObterReferenciasItensMesaConta(ItemDocumentoFiscal item)
		{
			if (item.IsNull())
			{
				return new List<string>();
			}
			List<string> list = new List<string>();
			list.Add(item.ItemMesaContaReferencia);
			list.AddRange(item.ItensMesaContaReferencia.ToListEmptyWhenNull());
			return list.Where((string x) => !x.IsObjectIdDefaultOrEmpty()).Distinct().ToListEmptyWhenNull();
		}

		public bool PodeCancelarItem()
		{
			string text = HelperString.RetornarSomenteLetras(Informacao.Texto);
			if ((text != null && text.Length > 0) || Informacao.BuscaAberta)
			{
				return false;
			}
			if (DadosSistema.IsPostoCombustivel && _emissorService.Tipo != TipoMovimentacao.CupomFiscal && !SeletorEsquerdo.Get<PainelEsquerdoPosto>().VerificarSemComunicacaoPostoService())
			{
				return false;
			}
			if (!string.IsNullOrEmpty(Informacao.Texto))
			{
				PosicionarNoItemInformado();
			}
			if (Lista.PossuiItemSelecionado && Lista.ItemSelecionado.Ativo)
			{
				return true;
			}
			Lista.PosicionarNoUltimo();
			Informacao.Limpar();
			return false;
		}

		private void PosicionarNoItemInformado()
		{
			int.TryParse(Informacao.Texto, out var numeroItem);
			Lista.Posicionar((ItemDocumentoFiscal x) => x.NumeroItem == numeroItem);
		}

		private void AplicarAcrescimo()
		{
			AutorizacaoDto autorizacaoDto = SessaoService.VerificarPermissao<DigisatServer.Infrastructure.Crosscutting.Module.PontoDeVenda, PermitirDescontoAcrescimo>();
			if (autorizacaoDto == null)
			{
				return;
			}
			try
			{
				PreDocumentoFiscal?.AdicionarAutorizacao(autorizacaoDto);
				ItemDocumentoFiscal itemDocumentoFiscal = Lista.ItemSelecionado?.AplicarAcrescimo(ObterValorDescontoAcrescimo(), autorizacaoDto, _emissorService);
				if (itemDocumentoFiscal != null)
				{
					_emissorService.AplicarAcrescimo(itemDocumentoFiscal, itemDocumentoFiscal.Acrescimo);
				}
				itemDocumentoFiscal.CalcularValorIcmsDesonerado(PreDocumentoFiscal);
				PreDocumentoFiscal?.Salvar();
			}
			catch (Exception ex)
			{
				PainelMensagem.AlterarMensagem(ex.Message);
			}
			Lista.PosicionarNoUltimo();
			Informacao.Limpar();
		}

		private decimal ObterValorDescontoAcrescimo()
		{
			decimal valor = Informacao.TextoToDecimal;
			if (Informacao.DescontoAcrescimoPercentual)
			{
				valor = decimal.Round(Lista.ItemSelecionado.TotalBruto * Informacao.TextoToDecimal / 100m, 2);
			}
			return valor.TruncarDuasCasasDecimais();
		}

		private bool PodeAplicarDescontoAcrescimo()
		{
			if (!Informacao.BuscaAberta)
			{
				if (!Informacao.TextoIsDecimal)
				{
					return Informacao.DescontoAcrescimoPercentual;
				}
				return true;
			}
			return false;
		}

		private void AplicarDesconto()
		{
			AutorizacaoDto autorizacaoDto = SessaoService.VerificarPermissao<DigisatServer.Infrastructure.Crosscutting.Module.PontoDeVenda, PermitirDescontoAcrescimo>();
			if (autorizacaoDto == null)
			{
				return;
			}
			try
			{
				PreDocumentoFiscal?.AdicionarAutorizacao(autorizacaoDto);
				ItemDocumentoFiscal itemDocumentoFiscal = Lista.ItemSelecionado?.AplicarDesconto(ObterValorDescontoAcrescimo(), autorizacaoDto, _emissorService);
				if (itemDocumentoFiscal != null)
				{
					_emissorService.AplicarDesconto(itemDocumentoFiscal, itemDocumentoFiscal.Desconto);
				}
				itemDocumentoFiscal.CalcularValorIcmsDesonerado(PreDocumentoFiscal);
				PreDocumentoFiscal?.Salvar();
			}
			catch (Exception ex)
			{
				PainelMensagem.AlterarMensagem(ex.Message);
			}
			Lista.PosicionarNoUltimo();
			Informacao.Limpar();
		}

