		private void AbrirPainelBuscaDocumentoFiscal()
		{
			if (_emissorService is INfceService)
			{
				Seletor.Selecionar<PainelBuscaNotaFiscalConsumidorEletronica>();
			}
			else if (_emissorService is ICFeService)
			{
				Seletor.Selecionar<PainelBuscaCupomFiscalEletronico>();
			}
			else if (_emissorService is IRegistroVendaService)
			{
				Seletor.Selecionar<PainelBuscaRegistroVenda>();
			}
			else if (_emissorService is IEcfService)
			{
				Seletor.Selecionar<PainelBuscaCupomFiscal>();
			}
		}

