		}

		public bool PodeAbrir()
		{
			if (Estado is DocumentoFiscalFechado)
			{
				return EmissorCarregadoEPronto();
			}
			return false;
		}

		public bool EmissorCarregadoEPronto()
		{
			if (_emissorService.Carregado)
			{
				return _emissorService.Pronto;
			}
			return false;
		}

		private void Abrir()
		{
			try
			{
				if (!VerificarProcessosAberturaPostoCombustivel())
				{
					ExecutarAbertura();
				}
			}
			catch (Exception ex)
			{
				DialogoFactory.MostrarDialogoConfirma(ex.Message);
			}
		}

		public bool AbrirDocumentoFiscalPostoCombustivel()
		{
			if (Estado is DocumentoFiscalAberto)
			{
				return true;
			}
			if (!PodeAbrir())
			{
				return false;
			}
			if (VerificarProcessosAberturaPostoCombustivel())
			{
				return false;
			}
			ExecutarAbertura();
			return Estado is DocumentoFiscalAberto;
		}

		public bool PodeAbrirDocumentoTurno()
		{
			if (DadosSistema.TurnoAberto || PdvEstadoOffline)
			{
				return true;
			}
			DialogoFactory.MostrarDialogoConfirma("É necessário realizar a abertura do turno antes de abrir o documento fiscal");
			return false;
		}

		private bool ExecutarAbertura(bool solicitarVendedor = true)
		{
			if (_cancelando && _emissorService.Is<IEcfService>())
			{
				throw new Exception("ECF executando comando. Tente novamente!");
			}
			try
			{
				if (!DadosSistema.TurnoAberto && !PdvEstadoOffline)
				{
					DialogoFactory.MostrarDialogoConfirma("É necessário realizar a abertura do turno antes de abrir o documento fiscal");
					return false;
				}
				PainelTitulo.ForcarLimparTitulo();
				PainelMensagem.AlterarMensagem("Abrindo documento fiscal...");
				DispatcherHelper.UpdateLayoutAndDoEvents();
				if (SessaoService.Sessao.Perfis.ItemSelecionado.Configuracao.SolicitarClienteAoAbrirDocumentoFiscal && Consumidor.IsNull())
				{
					AbrirBuscaConsumidor();
				}
				if ((SessaoService.Sessao.Perfis.ItemSelecionado.Configuracao.SolicitarVendedorAoAbrirDocumentoFiscal & solicitarVendedor) && (Vendedor.IsNull() || Vendedor.IsNenhum))
				{
					AbrirBuscaVendedor();
				}
				_emissorService.Abrir();
				PreDocumentoFiscal = PreDocumentoFiscal.Criar(_preDocumentoFiscalRepositoryWrite, _movimentacaoRepositoryWrite, _operacaoFiscalRepositoryRead, _promocaoScanntechRepositoryRead, _emissorService, SessaoService, Lista.Itens, _empresa, Consumidor, Vendedor, TabelaPrecoLocal, DadosVeiculoMaquinaEquipamento);
				ProcessarAberturaDoDocumentoFiscal();
				Seletor.Get<PainelInformacoesNfce>()?.Reiniciar();
				return true;
			}
			catch (DocumentoFiscalAbertoException)
			{
				ProcessarAberturaDoDocumentoFiscal();
			}
			catch (Exception)
			{
				PainelMensagem.ForcarLimparMensagem();
				if (!_emissorService.Pronto)
				{
					Estado = DocumentoFiscalEmissorEmErro.Criar();
				}
				else
				{
					Estado = DocumentoFiscalFechado.Criar();
				}
				_emissorService.CancelarSeDocumentoAberto();
				throw;
			}
			return false;
		}

		private void ProcessarAberturaDoDocumentoFiscal()
		{
			Estado = DocumentoFiscalAberto.Criar();
			DispatcherHelper.UpdateLayoutAndDoEvents();
		}

		private bool VerificarProcessosAberturaPostoCombustivel()
		{
			if (!DadosSistema.IsPostoCombustivel || _emissorService.Tipo != TipoMovimentacao.CupomFiscal)
			{
				return false;
			}
			List<IAbastecimento> list = SeletorEsquerdo.Get<PainelEsquerdoPosto>().ObterAbastecimentosPendentesPrimeiroCupomFiscal().ToListEmptyWhenNull();
			if (!list.Any())
			{
				return false;
			}
			EmitirDocumentoFiscalAbastecimentosPendentes(list);
			return true;
		}

		private void EmitirDocumentoFiscalAbastecimentosPendentes(IEnumerable<IAbastecimento> abastecimentos)
		{
			BackgroundWorker backgroundWorker = new BackgroundWorker();
			backgroundWorker.DoWork += BwAbastecimentoOnDoWork;
			backgroundWorker.RunWorkerCompleted += BwAbastecimentoOnRunWorkerCompleted;
			backgroundWorker.RunWorkerAsync(abastecimentos.ToArray());
		}

		private void BwAbastecimentoOnDoWork(object sender, DoWorkEventArgs doWorkEventArgs)
		{
			LoaderProcessoService.MostrarLoader();
			Estado = DocumentoFiscalEmissorAviso.Criar().ComMensagem("Emitindo cupom fiscal dos abastecimentos pendentes...");
			_emissorService.EmitirDocumentoFiscalAbastecimentos(doWorkEventArgs.Argument as IAbastecimento[]);
		}

		private void BwAbastecimentoOnRunWorkerCompleted(object sender, RunWorkerCompletedEventArgs runWorkerCompletedEventArgs)
		{
			if (sender is BackgroundWorker backgroundWorker)
			{
				backgroundWorker.DoWork -= BwAbastecimentoOnDoWork;
				backgroundWorker.RunWorkerCompleted -= BwAbastecimentoOnRunWorkerCompleted;
				LoaderProcessoService.EsconderLoader();
				if (runWorkerCompletedEventArgs.Error.IsNotNull())
				{
					runWorkerCompletedEventArgs.Error.ShowLastException();
				}
				else
				{
					_emissorService.VerificarEstado();
				}
			}
		}

		private async Task Totalizar()
		{
			try
			{
				_service.Canal((IPdvOfflineModuleService service) => service.VerificarAtivacaoPdvOffline());
				if (PdvEstadoOffline)
				{
					await (_emissorService.To<NfceService>()?.ConsultarStatusServicoAsync());
				}
			}
			catch (Exception)
			{
				if (!PdvEstadoOffline)
				{
					await (_emissorService.To<NfceService>()?.ConsultarStatusServicoAsync());
				}
			}
			if (DadosSistema.TurnoAberto || PdvEstadoOffline)
			{
				IRetornoConsulta retornoConsultaPbm = PreDocumentoFiscal.RetornoConsultaPbm;
				if (retornoConsultaPbm != null && retornoConsultaPbm.TipoPbm == TipoPbm.PortalDrogaria)
				{
					await Task.Run(() => _farmaciaService.EfetivarTransacao(!string.IsNullOrWhiteSpace(PreDocumentoFiscal.RetornoConsultaPbm?.NumeroAutorizacao), PreDocumentoFiscal.RetornoConsultaPbm?.Operadora, PreDocumentoFiscal.RetornoConsultaPbm?.CnpjEstabelecimento, 1, PreDocumentoFiscal.RetornoConsultaPbm?.DadosComplementares, 0, PreDocumentoFiscal, 0L)).ContinueWith((Task<RetornoProdutosAutorizadosComprovante> task) =>
					{
						if (task.IsFaulted)
						{
							task.Exception.ShowLastException();
						}
						else
						{
							PreDocumentoFiscal.SetarComprovantePortalDrogaria(task.Result.ReciboImpressao);
							RecalcularItensPortalDrogaria(task.Result.ProdutosAutorizados);
							ThreadPrincipal.Executar(ProcessarTotalizacao);
						}
					});
				}
				else
				{
					ProcessarTotalizacao();
				}
			}
			else
			{
				DialogoFactory.MostrarDialogoConfirma("É necessário realizar a abertura do turno antes de fechar o documento fiscal");
			}
		}

		private void ProcessarTotalizacao()
		{
			VerificarConsumacaoMinima();
			Seletor.Get<PainelTotalizacaoBase>().AdicionarMensagemPromocional(TextoLivreMensagemPromocional.Criar().ComLinha1(SessaoService.Sessao.Perfis.ItemSelecionado.Configuracao.MensagemPromocionalTextoLivreLinha1).ComLinha2(SessaoService.Sessao.Perfis.ItemSelecionado.Configuracao.MensagemPromocionalTextoLivreLinha2));
			Seletor.Get<PainelTotalizacaoBase>().AdicionarMensagemPromocional(TributoMensagemPromocional.Criar().ComItensDocumentoFiscal(Lista.Itens));
			if (Vendedores.Any())
			{
				Seletor.Get<PainelTotalizacaoBase>().AdicionarMensagemPromocional(VendedorMensagemPromocional.Criar().ComVendedores(Vendedores));
			}
			AdicionarSenhaPedido();
			AdicionarMensagemPbm();
			while (!PreDocumentoFiscal.Consumidor.Valido)
			{
				if (!SessaoService.Sessao.Perfis.ItemSelecionado.Configuracao.SolicitarClienteAcimaValorEstipuladoDocumentoFiscal || !(Subtotal >= SessaoService.Sessao.Perfis.ItemSelecionado.Configuracao.ValorEstipuladoSolicitarClienteDocumentoFiscal) || (!Consumidor.IsNull() && !Consumidor.Pessoa.Is<Consumidor>()))
				{
					PreDocumentoFiscal preDocumentoFiscal = Seletor.Get<PainelDocumentoFiscal>().PreDocumentoFiscal;
					if (preDocumentoFiscal == null || !preDocumentoFiscal.PossuiEntregaDomicilio)
					{
						break;
					}
				}
				Seletor.Get<PainelBuscaConsumidor>().ObrigatorioIndicarConsumidor = true;
				Seletor.Selecionar<PainelBuscaConsumidor, PainelDocumentoFiscal>();
			}
			if (_emissorService.Is<INfceService>() || _emissorService.Is<IRegistroVendaService>())
			{
				Subtotal = PreDocumentoFiscal.SubTotal + PreDocumentoFiscal.ModalidadeFrete.Valor;
			}
			if (_emissorService.Is<ICFeService>())
			{
				PreDocumentoFiscal.SetarAcrescimoDesconto(Acrescimo.Criar().ComValor(PreDocumentoFiscal.ModalidadeFrete.Valor));
			}
			DormirAsync(500, (object x) =>
			{
				Seletor.Selecionar<PainelTotalizacaoBase>();
				if (DadosSistema.IsRestauranteOuHotel)
				{
					SeletorEsquerdo.Selecionar<PainelEsquerdoTotalizacao>();
				}
			});
		}

		private void VerificarConsumacaoMinima()
		{
			if (!DadosSistema.IsRestauranteOuHotel)
			{
				return;
			}
			IEnumerable<long> enumerable = Seletor.Get<PainelDocumentoFiscal>().PreDocumentoFiscal?.NumerosMesasContasClientesImportadas;
			if (!enumerable.IsNull() && enumerable.Any() && !DadosSistema.ConfiguracaoDto.Saida.ProdutoServicoConsumacaoMinima.Referencia.IsNullOrEmpty())
			{
				ProdutoServicoEmpresa produtoServicoEmpresa = ProdutoServicoEmpresaRepositoryRead.FindOne(EntityBaseSpecification<ProdutoServicoEmpresa>.PorId(DadosSistema.ConfiguracaoDto.Saida.ProdutoServicoConsumacaoMinima.Referencia));
				if (!produtoServicoEmpresa.IsNull() && !(PreDocumentoFiscal.SubTotal > produtoServicoEmpresa.Preco.PrecoVendaVigente))
				{
					ItemDocumentoFiscalProduto itemDocumentoFiscalProduto = FluentFactory<ItemDocumentoFiscalFactory>.Init().ComProdutoServicoLocal(FluentFactory<ProdutoServicoLocalFactory>.Init().ComProdutoServicoEmpresa(produtoServicoEmpresa).Criar()).Criar()
						.To<ItemDocumentoFiscalProduto>()
						.ComEstoque(produtoServicoEmpresa.To<ProdutoEmpresa>().Estoque.Criar(1));
					itemDocumentoFiscalProduto.ComPrecoUnitario(produtoServicoEmpresa.Preco.PrecoVendaVigente - PreDocumentoFiscal.SubTotal);
					Vender(itemDocumentoFiscalProduto);
				}
			}
		}

		private void RecalcularItensPortalDrogaria(IEnumerable<ProdutoAutorizado> produtos)
		{
			if (produtos.IsNull() || !produtos.Any())
			{
				return;
			}
			List<string> list = new List<string>();
			List<ProdutoAutorizado> list2 = produtos.Where((ProdutoAutorizado x) => x.To<ProdutoAutorizadoPortalDrogaria>().Aceite.Equals(0)).ToListEmptyWhenNull();
			foreach (ItemDocumentoFiscal itemDocumentoFiscal in PreDocumentoFiscal.Itens)
			{
				ProdutoAutorizado produtoAutorizado = list2.FirstOrDefault((ProdutoAutorizado x) => x.CodigoBarras.Equals(itemDocumentoFiscal.ProdutoServicoLocal.Barras));
				if (!produtoAutorizado.IsNull())
				{
					decimal num = itemDocumentoFiscal.PrecoUnitario - produtoAutorizado.PrecoUnitario;
					if (produtoAutorizado.IsNull())
					{
						return;
					}
					if (_emissorService.Is<INfceService>() || _emissorService.Is<IRegistroVendaService>())
					{
						itemDocumentoFiscal.ComDesconto(num);
					}
					else
					{
						_emissorService.AplicarDesconto(itemDocumentoFiscal, num);
					}
					itemDocumentoFiscal.ComRepassePortalDrogaria(produtoAutorizado.Repasse);
				}
			}
			foreach (ProdutoAutorizado produtoAutorizado2 in list2)
			{
				List<ItemDocumentoFiscal> list3 = PreDocumentoFiscal.Itens.Where((ItemDocumentoFiscal x) =>
				{
					string barras = x.ProdutoServicoLocal.Barras;
					return barras != null && barras.Equals(produtoAutorizado2.CodigoBarras) && x.Ativo;
				}).ToListEmptyWhenNull();
				decimal num2 = list3.Sum((ItemDocumentoFiscal x) => x.Quantidade);
				if (!num2.Equals(produtoAutorizado2.Quantidade))
				{
					for (int num3 = 1; num3 < list3.Count; num3++)
					{
						list3[num3].Cancelar();
					}
					list3.FirstOrDefault().ComQuantidade(produtoAutorizado2.Quantidade);
					list.Add($"Divergência entre a quantidade enviada '{num2}' e a quantidade autorizada '{produtoAutorizado2.Quantidade}' do produto {produtoAutorizado2.CodigoBarras}. \n");
				}
			}
			if (list.Any())
			{
				DialogoFactory.MostrarDialogoConfirma(list.ToArray().LinhasParaTexto());
			}
		}

		private void AdicionarSenhaPedido()
		{
			if (!DadosSistema.IsRestauranteOuHotel)
			{
				return;
			}
			try
			{
				if (Seletor.Get<PainelTotalizacaoBase>().MensagensPromocionais.FirstOrDefault((IMensagemPromocional x) => x is MesaContaMensagemPromocional).IsNotNull())
				{
					return;
				}
				if (PdvEstadoOffline)
				{
					if (DadosSistema.ConfiguracaoDto.Saida.NumeroMaximoSenha.Valor != 0)
					{
						DialogoFactory.MostrarDialogoConfirma("Atenção! Não será possível obter a senha. Verifique a conexão com o servidor!");
					}
					return;
				}
				int num = _service.Canal((IRestauranteModuleService x) => x.ObterProximaSenha());
				if (num != 0)
				{
					Seletor.Get<PainelTotalizacaoBase>().AdicionarMensagemPromocional(SenhaPedidoMensagemPromocional.Criar().ComSenha(num));
				}
			}
			catch (Exception ex)
			{
				ex.ShowLastException();
			}
		}

		private void AdicionarMensagemPbm()
		{
			if (DadosSistema.IsFarmacia && !Seletor.Get<PainelTotalizacaoBase>().MensagensPromocionais.FirstOrDefault((IMensagemPromocional x) => x is DescontoPbm).IsNotNull())
			{
				decimal num = (from x in Lista.Itens.OfType<ItemDocumentoFiscalPbm>()
					where x.Ativo
					select x).Sum((ItemDocumentoFiscalPbm x) => x.Desconto);
				if (num > 0m)
				{
					Seletor.Get<PainelTotalizacaoBase>().AdicionarMensagemPromocional(DescontoPbm.Criar().ComValor(num));
				}
			}
		}

		protected virtual bool PodeTotalizar()
		{
			if (Subtotal > 0m && EstadoDocumentoFiscalValido() && !_itens.Any() && !_importandoParaDocumentoFiscal && SeletorEsquerdo.Painel.IsNot<PainelCardapioAdicionaisBase>() && SeletorEsquerdo.Painel.IsNot<PainelComponentesPontoVenda>() && SeletorEsquerdo.Painel.IsNot<PainelMenuRapidoAdicionaisPontoVenda>())
			{
				return SeletorEsquerdo.Painel.IsNot<PainelMenuRapidoComponentesPontoVenda>();
			}
			return false;
		}

		private void Cancelar()
		{
			string mensagem;
			if (Estado.Is<DocumentoFiscalAberto>())
			{
				mensagem = "Cancelar venda?";
			}
			else
			{
				mensagem = ((_emissorService.RetornarNumeroDocumento() != 0L) ? $"Cancelar última venda?\n Número: {_emissorService.RetornarNumeroDocumento()}" : "Cancelar última venda?");
			}
			if (DialogoFactory.MostrarDialogoSimNao(mensagem) == MessageBoxResult.Yes)
			{
				ExecutarCancelamento();
			}
		}

		private async void ExecutarCancelamento()
		{
			_cancelando = true;
			AutorizacaoDto autorizacao = null;
			await Task.Factory.StartNew(() =>
			{
				List<string> list = new List<string>();
				autorizacao = SessaoService.VerificarPermissao<DigisatServer.Infrastructure.Crosscutting.Module.PontoDeVenda, PermitirCancelarDocumentoFiscal>();
				if (autorizacao == null)
				{
					return new
					{
						ItensMesaContaReferencia = list,
						PossuiItensSemMesaContaReferencia = false
					};
				}
				PreDocumentoFiscal?.AdicionarAutorizacao(autorizacao);
				List<string> source = new List<string>();
				if (DadosSistema.IsRestauranteOuHotel && !(Estado is DocumentoFiscalFechado) && PreDocumentoFiscal.IsNotNull())
				{
					list.AddRange((from y in PreDocumentoFiscal.Itens
						where !string.IsNullOrEmpty(y.ItemMesaContaReferencia) && y.Ativo
						select y.ItemMesaContaReferencia).ToListEmptyWhenNull());
					list.AddRange(PreDocumentoFiscal.Itens.Where((ItemDocumentoFiscal x) =>
					{
						IEnumerable<string> itensMesaContaReferencia = x.ItensMesaContaReferencia;
						return itensMesaContaReferencia != null && itensMesaContaReferencia.Any() && x.Ativo;
					}).SelectMany((ItemDocumentoFiscal y) => y.ItensMesaContaReferencia).ToListEmptyWhenNull());
					list = list.Where((string x) => !x.IsObjectIdDefaultOrEmpty()).Distinct().ToListEmptyWhenNull();
					source = (from x in PreDocumentoFiscal.Itens.Where((ItemDocumentoFiscal x) =>
						{
							if (string.IsNullOrEmpty(x.ItemMesaContaReferencia))
							{
								IEnumerable<string> itensMesaContaReferencia = x.ItensMesaContaReferencia;
								if (itensMesaContaReferencia == null || !itensMesaContaReferencia.Any())
								{
									return x.Ativo;
								}
							}
							return false;
						})
						select x.ItemMesaContaReferencia).ToListEmptyWhenNull();
				}
				_emissorService.Cancelar(Estado, autorizacao.Morfar());
				PreDocumentoFiscal?.Cancelar(_emissorService.Tipo, autorizacao);
				ThreadPrincipal.Executar(() =>
				{
					if (DadosSistema.IsFarmacia && (PreDocumentoFiscal?.RetornoConsultaPbm?.CnpjEstabelecimento.IsNotNull() ?? false))
					{
						_farmaciaService.AnularVenda(PreDocumentoFiscal, 1);
						DialogoFactory.MostrarDialogoConfirma("001 - Operação anterior cancelada com sucesso");
					}
					Seletor.Get<PainelTotalizacaoBase>()?.LimparMensagensPromocionais();
					FinalizarDocumentoFiscal();
				});
				return new
				{
					ItensMesaContaReferencia = list,
					PossuiItensSemMesaContaReferencia = source.Any()
				};
			}).ContinueWith(task =>
			{
				DormirSync(2000, () =>
				{
					_cancelando = false;
				});
				VerificarUsuarioVendedor();
				if (task.IsFaulted)
				{
					task.Exception.ShowLastException();
				}
				else
				{
					ReabrirMesasContas(task.Result.ItensMesaContaReferencia, task.Result.PossuiItensSemMesaContaReferencia, autorizacao?.NomeUsuario);
				}
			});
		}

		private bool PodeCancelar()
		{
			if (DadosSistema.IsPostoCombustivel && _emissorService.Tipo != TipoMovimentacao.CupomFiscal)
			{
				PainelEsquerdoPosto painelEsquerdoPosto = SeletorEsquerdo.Get<PainelEsquerdoPosto>();
				if (painelEsquerdoPosto == null || !painelEsquerdoPosto.VerificarSemComunicacaoPostoService())
				{
					return false;
				}
			}
			if (Estado is DocumentoFiscalAberto || Estado is DocumentoFiscalFechado)
			{
				return !_itens.Any();
			}
			return false;
		}

		private async void ReabrirMesasContas(IEnumerable<string> itensMesasContasReferencias, bool possuiItensSemMesaContaReferencia, string nomeUsuarioAutorizouCancelamento)
		{
			if (!DadosSistema.IsRestauranteOuHotel || _emissorService.Tipo == TipoMovimentacao.CupomFiscal || itensMesasContasReferencias.IsNull() || !itensMesasContasReferencias.Any())
			{
				return;
			}
			if (DialogoFactory.MostrarDialogoSimNao($"Retornar os itens para a {DadosSistema.TipoRestaurante}") == MessageBoxResult.Yes)
			{
				await _service.Canal((IRestauranteModuleService x) => x.ReabrirItensMesasContas(itensMesasContasReferencias));
				if (possuiItensSemMesaContaReferencia)
				{
					DialogoFactory.MostrarDialogoConfirma($"Atenção! Os itens lançados após a importação não retornaram para a {DadosSistema.TipoRestaurante} e devem ser lançados manualmente.");
				}
			}
			else
			{
				await _service.Canal((IRestauranteModuleService x) => x.SetarCanceladoDocumentoFiscalAntesFinalizacaoSemRetornoItensMesaConta(itensMesasContasReferencias, nomeUsuarioAutorizouCancelamento));
			}
		}

