		private void AlterarPrecoVenda()
		{
			if (Lista.ItemSelecionado.LimiteDesconto > 0m)
			{
				DialogoFactory.MostrarDialogoConfirma("Alteração de preço não permitida para item com limite de desconto");
				return;
			}
			if (DadosSistema.LimiteDescontoUsuario > 0m)
			{
				DialogoFactory.MostrarDialogoConfirma("Alteração de preço não permitida usuário com limite de desconto");
				return;
			}
			if (Lista.ItemSelecionado.IsExactlyObject<ItemDocumentoFiscalCombustivel>())
			{
				DialogoFactory.MostrarDialogoConfirma("Alteração de preço não permitida para item combustível");
				return;
			}
			AutorizacaoDto autorizacaoDto = SessaoService.VerificarPermissao<DigisatServer.Infrastructure.Crosscutting.Module.PontoDeVenda, PermitirAlterarPrecoVenda>();
			if (autorizacaoDto == null)
			{
				return;
			}
			try
			{
				PreDocumentoFiscal?.AdicionarAutorizacao(autorizacaoDto);
				decimal informacao = 0m;
				if (DialogoFactory.MostrarDialogoEntradaDecimal(ref informacao, "Valor", "Informe o preço de venda unitário") != MessageBoxResult.OK || informacao <= 0m)
				{
					return;
				}
				if (Lista.ItemSelecionado.Desconto > 0m || Lista.ItemSelecionado.Acrescimo > 0m)
				{
					DialogoFactory.MostrarDialogoConfirma("Desconto/acréscimo do item será removido");
					Lista.ItemSelecionado.ComDesconto(0m);
					Lista.ItemSelecionado.ComAcrescimo(0m);
				}
				if (informacao < Lista.ItemSelecionado.ProdutoServicoLocal.PrecoCusto)
				{
					if (DadosSistema.AutenticacaoService.Instancia.VerificarPermissao<DigisatServer.Infrastructure.Crosscutting.Module.PontoDeVenda, PermitirVenderAbaixoPrecoCusto>() == null)
					{
						DialogoFactory.MostrarDialogoConfirma("Venda com preço abaixo do preço de custo não permitida.");
						return;
					}
					PreDocumentoFiscal?.AdicionarAutorizacao(autorizacaoDto);
				}
				Lista.ItemSelecionado.ComPrecoUnitario(informacao);
				_emissorService.AlterarPrecoUnitario(Lista.ItemSelecionado, informacao);
				PreDocumentoFiscal.Salvar();
			}
			catch (Exception ex)
			{
				DialogoFactory.MostrarDialogoConfirma($"Falha ao alterar preço de venda do item{Environment.NewLine}{ex.Message}");
			}
		}

