		private async Task LerPeso()
		{
			try
			{
				await ExecutarLerPeso(null, (decimal peso) =>
				{
					if (peso == 0m)
					{
						DialogoFactory.MostrarDialogoConfirma(new NaoFoiPossivelObterDadosBalancaException().Mensagem);
						Informacao.Texto = string.Empty;
					}
					else
					{
						Informacao.ControlarFoco();
						Informacao.Texto = $"{peso}*";
						Informacao.CapturouPeso = true;
					}
				});
			}
			catch (Exception)
			{
			}
		}

		public async Task ExecutarLerPeso(ProdutoEmpresa produtoEmpresa, Action<decimal> callback)
		{
			try
			{
				PainelMensagem.AlterarMensagemTimerComRetornoDaMensagemAnterior("Aguardando dados da balança...", _balancaService.ObterTimeOut());
			}
			catch (Exception)
			{
				callback(SolicitarLancamentoManual(produtoEmpresa));
				return;
			}
			DispatcherHelper.DoEvents();
			decimal quantidade;
			try
			{
				quantidade = (await _balancaService.LerPeso()).Peso;
				produtoEmpresa.ToDo((ProdutoEmpresa x) =>
				{
					quantidade = ((x.Tara > 0m) ? (quantidade - x.Tara) : quantidade);
				});
				if (quantidade <= 0m)
				{
					throw new NaoFoiPossivelObterDadosBalancaException();
				}
			}
			catch (NaoFoiPossivelObterDadosBalancaException)
			{
				callback(SolicitarLancamentoManual(produtoEmpresa));
				return;
			}
			catch (Exception)
			{
				DialogoFactory.MostrarDialogoConfirma("Timeout - Não foi possível obter dados da balança.");
				callback(SolicitarLancamentoManual(produtoEmpresa));
				return;
			}
			finally
			{
				PainelMensagem.ForcarLimparMensagem();
			}
			callback(quantidade);
		}

		private static decimal SolicitarLancamentoManual(ProdutoEmpresa produtoEmpresa)
		{
			decimal resultado = DialogoFactory.MostrarDialogoLancamentoManual(produtoEmpresa?.Preco.PrecoVendaVigente ?? 0m, DadosSistema.IsPafEcf);
			produtoEmpresa.ToDo((ProdutoEmpresa x) =>
			{
				resultado = ((x.Tara > 0m) ? (resultado - x.Tara) : resultado);
			});
			return resultado;
		}

		public void ExecutarSolicitacaoLancamentoManual(Action<decimal> callback)
		{
			callback(SolicitarLancamentoManualPreco());
		}

