		private IEnumerable<ItemMenuAtalho> ObterItensMenuRibbonAcoes()
		{
			List<ItemMenuAtalho> list = new List<ItemMenuAtalho>
			{
				new ItemMenuAtalho("F4", "Abrir venda", F4Command),
				new ItemMenuAtalho("F5", "Finalizar venda", F5Command),
				new ItemMenuAtalho("F6", "Cancelar venda", F6Command),
				new ItemMenuAtalho("End", "Abrir gaveta", EndCommand),
				new ItemMenuAtalho("Ctrl+F5", "Inicializar emissor", CtrlF5Command),
				new ItemMenuAtalho("Alt+M", "Abrir menu", AltMCommand),
				new ItemMenuAtalho("Delete", "Cancelar item", DelCommand),
				new ItemMenuAtalho("↑", "Mv cima", UpCommand),
				new ItemMenuAtalho("↓", "Mv baixo", DownCommand),
				new ItemMenuAtalho("Ctrl+P", "Pausar venda", CtrlPCommand),
				new ItemMenuAtalho("Alt+R", "Nova Conta/Mesa", AltRCommand)
			};
			list.Add(PdvEstadoOffline ? new ItemMenuAtalho("Alt+F1", "Desativar PDV Off-line", AltF1Command) : new ItemMenuAtalho("Alt+F1", "Ativar PDV Off-line", AltF1Command));
			if (_emissorService is INfceService)
			{
				list.Add(new ItemMenuAtalho("Ctrl+F11", "Alterar tipo de emissão", CtrlF11Command));
			}
			if (_emissorService.IsNot<IEcfService>())
			{
				list.Add(new ItemMenuAtalho("Alt+P", "Alterar preço de venda", AltPCommand));
			}
			return list;
		}

