		public override void Load()
		{
			if (PreDocumentoFiscal?.RetornoConsultaPbm?.IsNotNull() ?? false)
			{
				_farmaciaService.AnularVenda(PreDocumentoFiscal, 1);
			}
			VerificarUsuarioVendedor();
			Lista.PosicionarNoUltimo();
			if (!Lista.PossuiItemSelecionado)
			{
				PainelTitulo.LimparTitulo();
			}
			PainelMensagem.AlterarMensagem(Estado.MensagemOperador);
			bool turnoAberto = false;
			if (!PdvEstadoOffline)
			{
				try
				{
					turnoAberto = !_service.Canal((ITurnoModuleService x) => x.ObterTurnoAbertoDoUsuarioLogadoAsync()).Result.Is<TurnoDtoNull>();
				}
				catch (Exception)
				{
					turnoAberto = false;
				}
			}
			DadosSistema.SetarTurnoAbertoDoUsuario(turnoAberto);
			CriarTipoDocumentoFiscalVerificandoPdvEstadoOffline();
			DormirAsync(500, (object a) =>
			{
				Informacao.ControlarFoco();
			});
		}

		private void CriarTipoDocumentoFiscalVerificandoPdvEstadoOffline()
		{
			if (!DadosSistema.TurnoAberto && !PdvEstadoOffline)
			{
				_eventPublisher.Publish(DocumentoFiscalBloqueadoSemAberturaTurno.Criar());
			}
			else if (DadosSistema.ConfiguracaoDto.Saida.PontoDeSangria.Valor)
			{
				ValorSangriaLocal valorSangriaLocal = _valorSangriaRepositoryRead.Find(ValorSangriaLocalSpecifications.All()).FirstOrDefault();
				if (valorSangriaLocal.IsNotNull() && valorSangriaLocal.Valor > DadosSistema.ConfiguracaoDto.Saida.ValorEstipuladoPontoDeSangria.Valor)
				{
					_eventPublisher.Publish(DocumentoFiscalBloqueadoNecessarioSangria.Criar());
				}
				else
				{
					CriarTipoDocumentoFiscal();
				}
			}
			else
			{
				CriarTipoDocumentoFiscal();
			}
		}

		private void VerificarUsuarioVendedor()
		{
			new Thread(() =>
			{
				if (Vendedor == null)
				{
					TrocarUsuarioVendedor();
				}
			}).Start();
		}

		private void TrocarUsuarioVendedor()
		{
			UsuarioBase usuarioBase = _usuarioRepositoryRead.PorNome(DadosSistema.NomeUsuario);
			if (usuarioBase == null || usuarioBase.PessoaReferencia.IsDefaultOrEmpty())
			{
				ThreadPrincipal.Executar(() =>
				{
					IndicarVendedor(VendedorLocal.CriarNenhum());
				});
			}
			else
			{
				DigisatServer.Domain.Main.Aggregates.CadastrosAgg.Pessoas.Pessoa pessoaUsuario = _pessoaRepositoryRead.GetById(usuarioBase.PessoaReferencia);
				if (pessoaUsuario.IsNotNull() && pessoaUsuario.IsFisica && pessoaUsuario.To<Fisica>().Vendedor != null)
				{
					ThreadPrincipal.Executar(() =>
					{
						IndicarVendedor(VendedorLocal.Criar().ComPessoa(pessoaUsuario));
					});
				}
			}
			RaisePropertyChanged(() => ExibirVendedor);
		}

		protected void OnPdvOffline(bool pdvOffline)
		{
			PdvOfflineEvent?.Invoke(this, pdvOffline);
		}

		private void CriarTipoDocumentoFiscal()
		{
			if (!Estado.IsExactlyObject<DocumentoFiscalAberto>() && !Estado.IsExactlyObject<DocumentoFiscalBloqueadoSemComunicacaoServidor>() && !Estado.IsExactlyObject<DocumentoFiscalBloqueadoSemAberturaTurno>() && !Estado.IsExactlyObject<DocumentoFiscalCarregando>() && !Estado.IsExactlyObject<DocumentoFiscalBloqueado>() && !Estado.IsExactlyObject<DocumentoFiscalEmissorAviso>() && !Estado.IsExactlyObject<DocumentoFiscalEmissorEmErro>())
			{
				Estado = DocumentoFiscalFechado.Criar();
			}
		}

		private void ListaOnAdicionouEvent(object sender, ItemDocumentoFiscal itemDocumentoFiscal)
		{
			Subtotal = Lista.Itens.Sum((ItemDocumentoFiscal x) => x.TotalLiquido);
			QuantidadeTotalDosItens = $"Quantidade total: {Lista.Itens.Where((ItemDocumentoFiscal x) => x.Ativo).Sum((ItemDocumentoFiscal x) => x.Quantidade).FormatarCampoValor(2)}";
			ProcessarAberturaDoDocumentoFiscal();
		}

		public void Vender(ItemDocumentoFiscal itemDocumentoFiscal)
		{
			if (!DadosSistema.TurnoAberto && !PdvEstadoOffline)
			{
				DialogoFactory.MostrarDialogoConfirma("É necessário realizar a abertura do turno antes de lançar item no documento fiscal");
				return;
			}
			if (PodeAbrir())
			{
				if (VerificarProcessosAberturaPostoCombustivel())
				{
					return;
				}
				ExecutarAbertura();
				itemDocumentoFiscal.ComVendedor(Vendedor);
			}
			VerificarAutorizacaoPbm(itemDocumentoFiscal);
			if (_setouTabelaPrecoConsumidorSemItemLancado && TabelaPrecoLocal.IsNotNull())
			{
				ProdutoServicoEmpresa oneBy = ProdutoServicoEmpresaRepositoryRead.GetOneBy((ProdutoServicoEmpresa x) => x.Id, itemDocumentoFiscal.ProdutoServicoLocal.ProdutoServicoEmpresaReferencia);
				oneBy.SetarTabelaPreco(TabelaPrecoLocal.Id);
				itemDocumentoFiscal.ComPrecoItemMesaConta(oneBy.Preco.PrecoVendaVigente);
				_emissorService.AlterarPrecoUnitario(itemDocumentoFiscal, oneBy.Preco.PrecoVendaVigente);
			}
			_setouTabelaPrecoConsumidorSemItemLancado = false;
			itemDocumentoFiscal.ComTabelaPreco(TabelaPrecoLocal);
			ProcessarComissaoTabelaPreco(itemDocumentoFiscal);
			if (Estado.IsNot<DocumentoFiscalAberto>())
			{
				_emissorService.VerificarEstado();
			}
			if (itemDocumentoFiscal.PrecoUnitario < itemDocumentoFiscal.ProdutoServicoLocal.PrecoCusto)
			{
				AutorizacaoDto autorizacaoDto = DadosSistema.AutenticacaoService.Instancia.VerificarPermissao<DigisatServer.Infrastructure.Crosscutting.Module.PontoDeVenda, PermitirVenderAbaixoPrecoCusto>();
				if (autorizacaoDto == null)
				{
					DialogoFactory.MostrarDialogoConfirma("Venda com preço abaixo do preço de custo não permitida.");
					return;
				}
				PreDocumentoFiscal?.AdicionarAutorizacao(autorizacaoDto);
			}
			if (Estado.IsNot<DocumentoFiscalAberto>())
			{
				DialogoFactory.MostrarDialogoConfirma("Documento fiscal fechado. Tente novamente!");
			}
			else
			{
				_itens.Enqueue(itemDocumentoFiscal);
			}
		}

		private void VerificarAutorizacaoPbm(ItemDocumentoFiscal itemDocumentoFiscal)
		{
			if (PreDocumentoFiscal?.RetornoConsultaPbm == null || itemDocumentoFiscal is ItemDocumentoFiscalPbm || !PreDocumentoFiscal.RetornoConsultaPbm.NaoPermiteAdicionarProdutos)
			{
				return;
			}
			throw new Exception("Não é permitido adicionar itens nesse documento fiscal.");
		}

		private void ProcessarComissaoTabelaPreco(ItemDocumentoFiscal itemDocumentoFiscal)
		{
			itemDocumentoFiscal.ProcessarComissaoTabelaPreco(TabelaPrecoLocal);
		}

		private void AdicionarItemDocumentoFiscal(ItemDocumentoFiscal itemDocumentoFiscal)
		{
			ThreadPrincipal.Executar(() =>
			{
				itemDocumentoFiscal.WhenPropertyChanged.Subscribe((string x) =>
				{
					Subtotal = Lista.Itens.Sum((ItemDocumentoFiscal y) => y.TotalLiquido);
				});
				itemDocumentoFiscal.WhenPropertyChanged.Subscribe((string x) =>
				{
					QuantidadeTotalDosItens = $"Quantidade total: {Lista.Itens.Where((ItemDocumentoFiscal a) => a.Ativo).Sum((ItemDocumentoFiscal y) => y.Quantidade).FormatarCampoValor(2)}";
				});
				Lista.Adicionar(itemDocumentoFiscal);
				Lista.PosicionarNoUltimo();
			});
		}

