		public async void EmitirDocumentoFiscal(FarmaciaPopularDto farmaciaPopularDto)
		{
			_importandoParaDocumentoFiscal = true;
			try
			{
				if (PodeAbrir())
				{
					ExecutarAbertura(solicitarVendedor: false);
				}
				List<ItemFarmaciaPopularDto> itens = farmaciaPopularDto.Itens.Where((ItemFarmaciaPopularDto x) => x.AutorizacaoMedicamento.StartsWith("00SM")).ToListEmptyWhenNull();
				List<ObjectId> lista = itens.Select((ItemFarmaciaPopularDto x) => ObjectId.Parse(x.ProdutoServicoEmpresaReferencia)).ToListEmptyWhenNull();
				IEnumerable<ProdutoServicoEmpresa> source = await ProdutoServicoEmpresaRepositoryRead.AggregateIn(lista);
				foreach (ItemFarmaciaPopularDto item in itens)
				{
					try
					{
						ProdutoServicoEmpresa produtoServicoEmpresa = source.FirstOrDefault((ProdutoServicoEmpresa x) => x.Id.ToString().Equals(item.ProdutoServicoEmpresaReferencia));
						if (produtoServicoEmpresa == null)
						{
							throw new Exception($"O item '{item.Descricao}' não foi localizado na base de dados local!");
						}
						MedicamentoFarmaciaPopularLocal obj = FluentFactory<ProdutoServicoLocalFactory>.Init().ComSeletor(Seletor).ComProdutoServicoEmpresa(produtoServicoEmpresa)
							.ComPermissaoEstoqueNegativo(_perfilEmpresa.Configuracao.PermitirEstoqueNegativo)
							.ComItemFarmaciaPopular(item)
							.ComInformacaoPesquisa(string.Empty)
							.Criar() as MedicamentoFarmaciaPopularLocal;
						obj.Vender(obj.QuantidadeAutorizada);
					}
					catch (Exception ex)
					{
						ex.ShowLastException();
					}
				}
				PreDocumentoFiscal.SetarIdFarmaciaPopular(farmaciaPopularDto.Id);
			}
			finally
			{
				_importandoParaDocumentoFiscal = false;
			}
		}

		public void EmitirDocumentoFiscal(IRetornoConsulta retornoConsultaPbm)
		{
			_importandoParaDocumentoFiscal = true;
			try
			{
				if (PodeAbrir())
				{
					ExecutarAbertura(solicitarVendedor: false);
				}
				foreach (ProdutoAutorizado produtosAutorizado in retornoConsultaPbm.ProdutosAutorizados)
				{
					try
					{
						ProdutoServicoEmpresa produtoServicoEmpresa = ProdutoServicoEmpresaRepositoryRead.FindOne(ProdutoServicoEmpresaSpecifications.PorCodigoBarras(produtosAutorizado.CodigoBarras).PorEmpresa(DadosSistema.EmpresaLogada.Id));
						if (produtoServicoEmpresa == null)
						{
							throw new Exception($"O item com código de barras '{produtosAutorizado.CodigoBarras}' não foi localizado na base de dados local!");
						}
						MedicamentoPbmLocal medicamentoLocal = FluentFactory<ProdutoServicoLocalFactory>.Init().ComSeletor(Seletor).ComProdutoServicoEmpresa(produtoServicoEmpresa)
							.ComPermissaoEstoqueNegativo(_perfilEmpresa.Configuracao.PermitirEstoqueNegativo)
							.ComProdutoAutorizadoPbm(produtosAutorizado)
							.ComInformacaoPesquisa(string.Empty)
							.Criar() as MedicamentoPbmLocal;
						ThreadPrincipal.Executar(() =>
						{
							medicamentoLocal.Vender(medicamentoLocal.QuantidadeAutorizada);
						});
					}
					catch (Exception ex)
					{
						ex.ShowLastException();
						ExecutarCancelamento();
					}
				}
				PreDocumentoFiscal.SetarRetornoConsultaPbm(retornoConsultaPbm);
			}
			finally
			{
				_importandoParaDocumentoFiscal = false;
			}
		}

		private static List<ItemMesaContaDto> AgruparItensMesaConta(IEnumerable<ItemMesaContaDto> itens)
		{
			List<ItemMesaContaDto> list = itens.ToListEmptyWhenNull();
			if (!DadosSistema.AgruparItensImportacaoPontoDeVendas)
			{
				return list;
			}
			return (from i in list
				group i by new
				{
					i.NumeroMesaConta, i.ProdutoServicoEmpresaReferencia, i.ValorUnitario, i.GarcomReferencia, i.PercentualComissao, i.DepartamentoReferencia, i.ImpressoraReferencia, i.ImpressoraProdutoReferencia, i.Cancelado, i.ItemBase,
					i.ObservacoesToText, i.AdicionaisToText, i.ComponentesRemovidosToText
				}).Select(g =>
			{
				ItemMesaContaDto itemMesaContaDto = g.First().Clonar();
				itemMesaContaDto.Quantidade = g.Sum((ItemMesaContaDto x) => x.Quantidade);
				itemMesaContaDto.ValorComissao = g.Sum((ItemMesaContaDto x) => x.ValorComissao);
				itemMesaContaDto.ItensAgrupados = g.Select((ItemMesaContaDto x) => x.Id).ToListEmptyWhenNull();
				return itemMesaContaDto;
			}).ToListEmptyWhenNull();
		}

		public async void EmitirDocumentoFiscal(IEnumerable<ItemMesaContaDto> itens)
		{
			_importandoParaDocumentoFiscal = true;
			try
			{
				List<ItemMesaContaDto> itensMesaContaDto = AgruparItensMesaConta(itens);
				if (PodeAbrir())
				{
					ExecutarAbertura(solicitarVendedor: false);
				}
				IEnumerable<ObjectId> lista = itensMesaContaDto.Select((ItemMesaContaDto x) => ObjectId.Parse(x.ProdutoServicoEmpresaReferencia));
				IEnumerable<ProdutoServicoEmpresa> produtoServicoEmpresaLista = await ProdutoServicoEmpresaRepositoryRead.AggregateIn(lista);
				IEnumerable<ObjectId> fieldData = itensMesaContaDto.Select((ItemMesaContaDto i) => i.ImpressoraReferencia.TryParseReferencia()).Union(itensMesaContaDto.Select((ItemMesaContaDto i) => i.ImpressoraProdutoReferencia.TryParseReferencia())).Distinct();
				IEnumerable<DigisatServer.Domain.Main.Aggregates.CadastrosAgg.Impressoras.Impressora> impressoras = ImpressoraRepositoryRead.GetIn((DigisatServer.Domain.Main.Aggregates.CadastrosAgg.Impressoras.Impressora x) => x.Id, fieldData);
				foreach (ItemMesaContaDto item in itensMesaContaDto)
				{
					VendedorLocal vendedorLocal = ObterVendedorItemMesaConta(item);
					ProdutoServicoEmpresa produtoServicoEmpresa = produtoServicoEmpresaLista.FirstOrDefault((ProdutoServicoEmpresa x) => x.Id.ToString().Equals(item.ProdutoServicoEmpresaReferencia));
					ProdutoServicoLocal produtoServicoLocal = FluentFactory<ProdutoServicoLocalFactory>.Init().ComProdutoServicoEmpresa(produtoServicoEmpresa).ComImpressora(item.ImpressoraReferencia.IsNullOrEmpty() ? impressoras.FirstOrDefault((DigisatServer.Domain.Main.Aggregates.CadastrosAgg.Impressoras.Impressora x) => x.Id.Equals(item.ImpressoraProdutoReferencia.TryParseReferencia())) : impressoras.FirstOrDefault((DigisatServer.Domain.Main.Aggregates.CadastrosAgg.Impressoras.Impressora x) => x.Id.Equals(item.ImpressoraReferencia.TryParseReferencia())))
						.ComComponentesRevemovidos(item.ComponentesRemovidos.MorfarCollection())
						.Criar();
					ItemDocumentoFiscal itemDocumentoFiscal;
					if (produtoServicoLocal.Is<ServicoLocal>())
					{
						produtoServicoLocal.SetarQuantidade(item.Quantidade);
						itemDocumentoFiscal = FluentFactory<ItemDocumentoFiscalFactory>.Init().ComProdutoServicoLocal(produtoServicoLocal).Criar()
							.ComVendedor(vendedorLocal)
							.ComPermitirVenderAcimaDoLimiteDeDesconto(PermitirVenderAcimaDoLimiteDeDesconto)
							.ComPrecoItemMesaConta((_emissorService.Is<EcfService>() && item.ValorUnitario == 0m) ? 0.01m : item.ValorUnitario)
							.ComItemMesaContaReferencia(item.Id)
							.ComItensMesaContaReferencia(item.ItensAgrupados.ToListEmptyWhenNull())
							.ComDepartamentoReferencia(item.DepartamentoReferencia);
					}
					else
					{
						Estoque estoque = produtoServicoLocal.To<ProdutoLocal>()?.ProcessarComposicaoRestaurante(item.ItemBase ? 0m : item.Quantidade, Seletor);
						if (estoque.IsNull())
						{
							continue;
						}
						itemDocumentoFiscal = FluentFactory<ItemDocumentoFiscalFactory>.Init().ComProdutoServicoLocal(produtoServicoLocal).Criar()
							.To<ItemDocumentoFiscalProduto>()
							.ComEstoque(estoque)
							.ComPermitirVenderAcimaDoLimiteDeDesconto(PermitirVenderAcimaDoLimiteDeDesconto)
							.ComVendedor(vendedorLocal)
							.ComPrecoItemMesaConta((_emissorService.Is<EcfService>() && item.ValorUnitario == 0m) ? 0.01m : item.ValorUnitario)
							.ComItemMesaContaReferencia(item.Id)
							.ComItensMesaContaReferencia(item.ItensAgrupados.ToListEmptyWhenNull())
							.ComDepartamentoReferencia(item.DepartamentoReferencia)
							.ComQuantidade(item.ItemBase ? 0m : item.Quantidade)
							.ComQuantidadeImprimirAmbienteProducao(item.ItemBase ? item.Quantidade : 0m);
					}
					try
					{
						ExecutarVenda(itemDocumentoFiscal);
						if (item.Cancelado)
						{
							_emissorService.CancelarItem(itemDocumentoFiscal.NumeroItem);
							itemDocumentoFiscal.Cancelar();
						}
						await VenderAdicional(item, vendedorLocal);
					}
					catch (Exception ex)
					{
						ex.ShowLastException();
					}
				}
				if (itensMesaContaDto.All((ItemMesaContaDto x) => x.Cancelado))
				{
					ExecutarCancelamento();
					return;
				}
				ItemMesaContaDto itemMesaContaDto = itensMesaContaDto.FirstOrDefault();
				Seletor.Get<PainelTotalizacaoBase>().AdicionarMensagemPromocional(MesaContaMensagemPromocional.Criar().ComCer(itemMesaContaDto.Cer).ComCoo(itemMesaContaDto.Coo)
					.ComNumeroMesaConta(itemMesaContaDto.NumeroMesaConta)
					.ComNumeroSequencialEcf(itemMesaContaDto.NumeroSequencialEcf));
				if (itensMesaContaDto.FirstOrDefault().TituloAutoAtendimento.ToLower().Contains("autoatendimento"))
				{
					Seletor.Get<PainelTotalizacaoBase>().AdicionarMensagemPromocional(AutoAtendimentoPedidoMensagemPromocional.Criar().ComSenhaAutoAtendimento(itensMesaContaDto.FirstOrDefault().NumeroMesaConta));
				}
				if (itensMesaContaDto.IsNotNull() && (from x in itensMesaContaDto
					where !string.IsNullOrEmpty(x.PessoaCpf) || !string.IsNullOrEmpty(x.PessoaNome)
					group x by x.PessoaCpf).Count() == 1)
				{
					if (!itemMesaContaDto.PessoaId.IsObjectIdDefaultOrEmpty())
					{
						DigisatServer.Domain.Main.Aggregates.CadastrosAgg.Pessoas.Pessoa pessoaCadastrada = _pessoaRepositoryRead.GetOneBy((DigisatServer.Domain.Main.Aggregates.CadastrosAgg.Pessoas.Pessoa x) => x.Id, itemMesaContaDto.PessoaId.TryParseReferencia());
						ConsumidorLocal consumidorLocal = ConsumidorLocal.Criar().ComPessoa(pessoaCadastrada).ComFuncAtualizarClienteDto(() => _service.Canal((IPessoaModuleService service) => service.ObterClienteDto(pessoaCadastrada.Id.ToString())));
						consumidorLocal.AtualizarClienteDto();
						IndicarConsumidor(consumidorLocal);
					}
					else
					{
						Consumidor pessoa = DigisatServer.Domain.Main.Aggregates.CadastrosAgg.Pessoas.Consumidor.Criar().ComNome(string.IsNullOrEmpty(itensMesaContaDto.FirstOrDefault().PessoaNome) ? "Cliente Consumidor" : itensMesaContaDto.FirstOrDefault().PessoaNome).ComDocumento(itensMesaContaDto.FirstOrDefault().PessoaCpf)
							.ComMunicipio(SessaoService.Sessao.Perfis.ItemSelecionado.Empresa.Municipio.CodigoIbge)
							.ComEndereco(SessaoService.Sessao.Perfis.ItemSelecionado.Empresa.EnderecoToText)
							.Build();
						ConsumidorLocal consumidorLocal2 = ConsumidorLocal.Criar().ComPessoa(pessoa);
						IndicarConsumidor(consumidorLocal2);
					}
				}
				if (itensMesaContaDto.Any((ItemMesaContaDto itemMesaContaDto2) => itemMesaContaDto2.CriadoPeloDelivery) && (_emissorService.Is<ICFeService>() || _emissorService.Is<INfceService>() || _emissorService.Is<IRegistroVendaService>()))
				{
					IEnumerable<EntregaDeliveryDto> source = await _service.Canal((IDeliveryModuleService service) => service.ObterDeliveries((from itemMesaContaDto2 in itensMesaContaDto
						where itemMesaContaDto2.CriadoPeloDelivery
						select itemMesaContaDto2.NumeroMesaConta).ToArray()));
					decimal num = 0m;
					foreach (EntregaDeliveryDto item2 in source.Where((EntregaDeliveryDto entregaDeliveryDto) => entregaDeliveryDto.TotalFrete > 0m))
					{
						if (DialogoFactory.MostrarDialogoSimNao($"Deseja adicionar o valor de entrega, referente ao Delivery nº {item2.Numero}, ao total do documento fiscal?") == MessageBoxResult.Yes)
						{
							num += item2.TotalFrete;
						}
					}
					if (num > 0m)
					{
						PreDocumentoFiscal.SetarFrete(new CodigoDescricaoDto
						{
							Codigo = 1
						}, num);
					}
					if (source.Count() == 1 && source.First().Entregador.IsExactlyObject<PessoaDto>() && Consumidor.IsNotNull() && !Consumidor.Documento.IsNullOrEmpty())
					{
						PreDocumentoFiscal.SetarDadosEntregador(IndicadorIntermediador.OperacaoComEntregaDomicilio, source.First().Entregador.CpfCnpj, source.First().Entregador.Nome, source.First().Entregador.EnderecoPrincipal.Morfar());
					}
				}
				if (itensMesaContaDto.Sum((ItemMesaContaDto itemMesaContaDto2) => itemMesaContaDto2.Frete) > 0m && (_emissorService.Is<ICFeService>() || _emissorService.Is<INfceService>() || _emissorService.Is<IRegistroVendaService>()))
				{
					decimal num2 = 0m;
					if (DialogoFactory.MostrarDialogoSimNao("Deseja adicionar o valor de entrega no total do documento fiscal?") == MessageBoxResult.Yes)
					{
						num2 = itensMesaContaDto.Sum((ItemMesaContaDto itemMesaContaDto2) => itemMesaContaDto2.Frete);
					}
					if (num2 > 0m)
					{
						PreDocumentoFiscal.SetarFrete(new CodigoDescricaoDto
						{
							Codigo = 1
						}, num2);
					}
				}
				if (itensMesaContaDto.Sum((ItemMesaContaDto itemMesaContaDto2) => itemMesaContaDto2.DescontoPedirMenu) > 0m && (_emissorService.Is<ICFeService>() || _emissorService.Is<INfceService>() || _emissorService.Is<IRegistroVendaService>()))
				{
					decimal num3 = itensMesaContaDto.Sum((ItemMesaContaDto itemMesaContaDto2) => itemMesaContaDto2.DescontoPedirMenu);
					if (num3 > 0m)
					{
						PreDocumentoFiscal.SetarAcrescimoDesconto(Desconto.Criar().ComValor(Math.Abs(PreDocumentoFiscal.Desconto + num3)));
					}
				}
				if (!(PreDocumentoFiscal.NumerosMesasContasClientesPedirMenuImportadas?.Any() ?? false))
				{
					return;
				}
				await _service.Canal((IRestauranteModuleService service) => service.ObterDadosEntregador(PreDocumentoFiscal.NumerosMesasContasClientesPedirMenuImportadas)).ContinueWith((Task<DigisatServer.Application.Main.Dto.Cadastros.Mobile.EntregadorDto> task) =>
				{
					if (!task.IsFaulted && task.Result.IsNotNull())
					{
						PreDocumentoFiscal?.SetarDadosEntregador(IndicadorIntermediador.OperacaoComEntregaDomicilio, task.Result.Documento, task.Result.Nome, null);
					}
				});
			}
			finally
			{
				_importandoParaDocumentoFiscal = false;
			}
		}

		public async Task VenderAdicional(ItemMesaContaDto itemMesaContaDto, VendedorLocal vendedorLocal)
		{
			IEnumerable<ObjectId> lista = itemMesaContaDto.Adicionais.Select((ItemMesaContaAdicionalDto x) => ObjectId.Parse(x.ProdutoEmpresaReferencia));
			IEnumerable<ProdutoServicoEmpresa> source = await ProdutoServicoEmpresaRepositoryRead.AggregateIn(lista);
			foreach (ItemMesaContaAdicionalDto itemAdicional in itemMesaContaDto.Adicionais)
			{
				ProdutoServicoEmpresa produtoServicoEmpresa = source.FirstOrDefault((ProdutoServicoEmpresa x) => x.Id.ToString().Equals(itemAdicional.ProdutoEmpresaReferencia));
				ProdutoServicoLocal produtoServicoLocal = FluentFactory<ProdutoServicoLocalFactory>.Init().ComProdutoServicoEmpresa(produtoServicoEmpresa).Criar();
				decimal quantidade = itemAdicional.Quantidade * itemMesaContaDto.Quantidade;
				Estoque estoque = produtoServicoLocal.To<ProdutoLocal>()?.ProcessarComposicaoRestaurante(quantidade, Seletor);
				if (!estoque.IsNull())
				{
					ItemDocumentoFiscal itemDocumentoFiscal = FluentFactory<ItemDocumentoFiscalFactory>.Init().ComProdutoServicoLocal(produtoServicoLocal).Criar()
						.To<ItemDocumentoFiscalProduto>()
						.ComEstoque(estoque)
						.ComPermitirVenderAcimaDoLimiteDeDesconto(PermitirVenderAcimaDoLimiteDeDesconto)
						.ComVendedor(vendedorLocal)
						.ComPrecoItemMesaConta((_emissorService.Is<EcfService>() && itemAdicional.PrecoUnitario == 0m) ? 0.01m : itemAdicional.PrecoUnitario)
						.ComDepartamentoReferencia(itemMesaContaDto.DepartamentoReferencia);
					ExecutarVenda(itemDocumentoFiscal);
					if (itemMesaContaDto.Cancelado)
					{
						_emissorService.CancelarItem(itemDocumentoFiscal.NumeroItem);
						itemDocumentoFiscal.Cancelar();
					}
				}
			}
		}

		public async void EmitirDocumentoFiscal(PedidoIfoodDto pedidoIfoodDto)
		{
			_importandoParaDocumentoFiscal = true;
			try
			{
				EnderecoNacional enderecoEntrega = ObterEnderecoEntregaIfood(pedidoIfoodDto);
				if (!string.IsNullOrEmpty(pedidoIfoodDto.NomeCliente))
				{
					Consumidor consumidor = DigisatServer.Domain.Main.Aggregates.CadastrosAgg.Pessoas.Consumidor.Criar().ComNome(pedidoIfoodDto.NomeCliente).ComDocumento(pedidoIfoodDto.DocumentoCliente);
					if (enderecoEntrega.IsNotNull())
					{
						consumidor.ComEndereco(enderecoEntrega);
					}
					else
					{
						consumidor.ComMunicipio(SessaoService.Sessao.Perfis.ItemSelecionado.Empresa.Municipio.CodigoIbge).ComEndereco(pedidoIfoodDto.Entrega.Endereco.ToText);
					}
					IndicarConsumidor(ConsumidorLocal.Criar().ComPessoa(consumidor.Build()));
				}
				if (PodeAbrir())
				{
					ExecutarAbertura(solicitarVendedor: false);
				}
				ISpecification<DigisatServer.Domain.Main.Aggregates.CadastrosAgg.Cardapios.Cardapio> specification = EntitySpecification<DigisatServer.Domain.Main.Aggregates.CadastrosAgg.Cardapios.Cardapio>.All().PorItensCardapio(pedidoIfoodDto.Itens.Select((PedidoIfoodItemDto pedidoIfoodItemDto) => pedidoIfoodItemDto.ItemReferencia.TryParseReferencia()));
				IEnumerable<DigisatServer.Domain.Main.Aggregates.CadastrosAgg.Cardapios.Cardapio> source = CardapioRepositoryRead.Find(specification);
				IEnumerable<ItemCardapio> itensCardapio = source.SelectMany((DigisatServer.Domain.Main.Aggregates.CadastrosAgg.Cardapios.Cardapio cardapio) => cardapio.ItensCardapio);
				ISpecification<DigisatServer.Domain.Main.Aggregates.CadastrosAgg.MenusRapido.MenuRapido> specification2 = EntitySpecification<DigisatServer.Domain.Main.Aggregates.CadastrosAgg.MenusRapido.MenuRapido>.All().PorItensMenu(pedidoIfoodDto.Itens.Select((PedidoIfoodItemDto pedidoIfoodItemDto) => pedidoIfoodItemDto.ItemReferencia.TryParseReferencia()));
				IEnumerable<DigisatServer.Domain.Main.Aggregates.CadastrosAgg.MenusRapido.MenuRapido> source2 = MenuRapidoRepositoryRead.Find(specification2);
				IEnumerable<ItemMenuRapido> itensMenu = source2.SelectMany((DigisatServer.Domain.Main.Aggregates.CadastrosAgg.MenusRapido.MenuRapido cardapio) => cardapio.ItensMenuRapido);
				IEnumerable<ObjectId> lista = itensCardapio.Select((ItemCardapio x) => x.ProdutoEmpresaReferencia).Concat(itensMenu.Select((ItemMenuRapido x) => x.ProdutoEmpresaReferencia));
				IEnumerable<ProdutoServicoEmpresa> produtoServicoEmpresaLista = await ProdutoServicoEmpresaRepositoryRead.AggregateIn(lista);
				ConfiguracaoDepartamentoVenda departamento = DadosSistema.ObterDepartamentoVenda();
				List<string> itensNaoLocalizados = new List<string>();
				foreach (PedidoIfoodItemDto item in pedidoIfoodDto.Itens)
				{
					ItemCardapio itemCardapio = itensCardapio.FirstOrDefault((ItemCardapio cardapio) => cardapio.Id.Equals(item.ItemReferencia.TryParseReferencia()));
					ObjectId produtoEmpresaReferencia = itensMenu.FirstOrDefault((ItemMenuRapido menu) => menu.Id.Equals(item.ItemReferencia.TryParseReferencia()))?.ProdutoEmpresaReferencia ?? itemCardapio?.ProdutoEmpresaReferencia ?? ObjectId.Empty;
					ProdutoServicoEmpresa produtoServicoEmpresa = produtoServicoEmpresaLista.FirstOrDefault((ProdutoServicoEmpresa produtoServicoEmpresa2) => produtoServicoEmpresa2.Id.Equals(produtoEmpresaReferencia)) ?? ObterProdutoIfoodPorCodigo(item.Ean);
					if (produtoServicoEmpresa.IsNull())
					{
						itensNaoLocalizados.Add(item.Descricao);
						continue;
					}
					decimal num = ConverterQuantidadeIfood(item.Quantidade, item.Unidade);
					decimal itemValorUnitario = ((num.Equals(item.Quantidade) || num <= 0m) ? item.Preco : ((item.Total - item.TotalAdicionais) / num));
					ProdutoServicoLocal produtoServicoLocal = FluentFactory<ProdutoServicoLocalFactory>.Init().ComProdutoServicoEmpresa(produtoServicoEmpresa).Criar();
					ItemDocumentoFiscal itemDocumentoFiscal;
					if (produtoServicoLocal.Is<ServicoLocal>())
					{
						produtoServicoLocal.SetarQuantidade(num);
						itemDocumentoFiscal = FluentFactory<ItemDocumentoFiscalFactory>.Init().ComProdutoServicoLocal(produtoServicoLocal).Criar()
							.ComPermitirVenderAcimaDoLimiteDeDesconto(PermitirVenderAcimaDoLimiteDeDesconto)
							.ComPrecoItemMesaConta(itemValorUnitario)
							.ComDepartamentoReferencia(departamento.DepartamentoVendaReferencia);
					}
					else
					{
						Estoque estoque = produtoServicoLocal.To<ProdutoLocal>()?.ProcessarComposicaoRestaurante(num, Seletor);
						if (estoque.IsNull())
						{
							itensNaoLocalizados.Add(item.Descricao);
							continue;
						}
						itemDocumentoFiscal = FluentFactory<ItemDocumentoFiscalFactory>.Init().ComProdutoServicoLocal(produtoServicoLocal).Criar()
							.To<ItemDocumentoFiscalProduto>()
							.ComEstoque(estoque)
							.ComPermitirVenderAcimaDoLimiteDeDesconto(PermitirVenderAcimaDoLimiteDeDesconto)
							.ComPrecoItemMesaConta(itemValorUnitario)
							.ComDepartamentoReferencia(departamento.DepartamentoVendaReferencia);
					}
					try
					{
						ExecutarVenda(itemDocumentoFiscal);
						if (item.Desconto > 0m)
						{
							_emissorService.AplicarDesconto(itemDocumentoFiscal, item.Desconto);
							itemDocumentoFiscal.ComDesconto(item.Desconto);
						}
						await VenderAdicional(item);
					}
					catch (Exception ex)
					{
						ex.ShowLastException();
					}
				}
				if (itensNaoLocalizados.Any())
				{
					DialogoFactory.MostrarDialogoConfirma($"Produtos não localizados no cadastro e não lançados no documento:{Environment.NewLine}{string.Join(Environment.NewLine, itensNaoLocalizados.Select((string x) => $"- {x}"))}", bloquearEnter: true);
				}
				if (pedidoIfoodDto.TaxaEntrega > 0m && (_emissorService.Is<INfceService>() || _emissorService.Is<IRegistroVendaService>() || _emissorService.Is<ICFeService>()) && DialogoFactory.MostrarDialogoSimNao("Deseja adicionar o valor da taxa de entrega ao total do documento fiscal?") == MessageBoxResult.Yes)
				{
					PreDocumentoFiscal.SetarFrete(new CodigoDescricaoDto
					{
						Codigo = 1,
						Descricao = DigisatServer.Infrastructure.Crosscutting.Enum.ModalidadeFrete.PorContaDestinatarioRemetente.RetornarDescricao()
					}, pedidoIfoodDto.TaxaEntrega);
				}
				decimal num2 = pedidoIfoodDto.Itens.Sum((PedidoIfoodItemDto x) => x.Desconto);
				decimal num3 = pedidoIfoodDto.Descontos - num2;
				decimal num4 = pedidoIfoodDto.Acrescimos - num3;
				if (num4 < 0m)
				{
					PreDocumentoFiscal.SetarAcrescimoDesconto(Desconto.Criar().ComValor(Math.Abs(num4)));
				}
				else if (num4 > 0m)
				{
					PreDocumentoFiscal.SetarAcrescimoDesconto(Acrescimo.Criar().ComValor(num4));
				}
				SetarInformacoesNfcePedidoIfood(pedidoIfoodDto, enderecoEntrega);
				PreDocumentoFiscal.SetarPagamentosIfood(pedidoIfoodDto.Pagamentos.MetodosPagamento);
				PreDocumentoFiscal.SetarObservacaoFormaPagamento(pedidoIfoodDto.Pagamentos.ToText);
				string observacao = $"Pedido iFood: {pedidoIfoodDto.Numero}";
				PreDocumentoFiscal.SetarObservacao(observacao);
				PreDocumentoFiscal.SetarMovimentacaoReferenciada(pedidoIfoodDto);
				Seletor.Get<PainelTotalizacaoBase>().AdicionarMensagemPromocional(ObservacaoMensagemPromocional.Criar().ComObservacao(observacao));
				Seletor.Get<PainelObservacao>().Reload(observacao);
			}
			finally
			{
				_importandoParaDocumentoFiscal = false;
			}
		}

		private static EnderecoNacional ObterEnderecoEntregaIfood(PedidoIfoodDto pedidoIfoodDto)
		{
			PedidoIfoodEnderecoDto endereco = pedidoIfoodDto.Entrega.Endereco;
			string text = endereco.Cep.ApenasNumeros();
			if (string.IsNullOrWhiteSpace(endereco.Logradouro) || string.IsNullOrWhiteSpace(endereco.Bairro) || string.IsNullOrWhiteSpace(endereco.Municipio) || string.IsNullOrWhiteSpace(endereco.Uf) || string.IsNullOrEmpty(text))
			{
				return null;
			}
			Municipio municipio = MunicipioValueObjectService.ObterMunicipioPorNomeESiglaUF(endereco.Municipio, endereco.Uf);
			if (municipio.IsNull())
			{
				return null;
			}
			try
			{
				return new EnderecoNacional(endereco.Logradouro, string.IsNullOrWhiteSpace(endereco.Numero) ? "S/N" : endereco.Numero, endereco.Complemento, endereco.Bairro, text, municipio);
			}
			catch (Exception)
			{
				return null;
			}
		}

		private void SetarInformacoesNfcePedidoIfood(PedidoIfoodDto pedidoIfoodDto, EnderecoNacional enderecoEntrega)
		{
			if (_emissorService.IsNot<INfceService>() || pedidoIfoodDto.Tipo != TipoPedidoIfood.Delivery || enderecoEntrega.IsNull())
			{
				return;
			}
			ConsumidorLocal consumidor = PreDocumentoFiscal.Consumidor;
			if (consumidor == null || !consumidor.Valido)
			{
				return;
			}
			PreDocumentoFiscal.SetarIndicadorPresencaComprador(4);
			string text = DadosSistema.ConfiguracaoDto?.Saida.Ifood.MerchantId.Valor;
			if (!string.IsNullOrWhiteSpace(text))
			{
				PreDocumentoFiscal.SetarDadosIntermediadorTransacao(IndicadorIntermediador.SiteOuPlataformaDeTerceiros, "14380200000121", text);
			}
			if ("IFOOD".Equals(pedidoIfoodDto.Entrega.ResponsavelEntrega))
			{
				if (!string.IsNullOrWhiteSpace(pedidoIfoodDto.NomeEntregador))
				{
					PreDocumentoFiscal.SetarDadosEntregador(IndicadorIntermediador.OperacaoComEntregaDomicilio, string.Empty, pedidoIfoodDto.NomeEntregador, null);
				}
				return;
			}
			DigisatServer.Domain.Main.Aggregates.CadastrosAgg.Pessoas.Pessoa pessoa = SelecionarEntregadorPedidoIfood(pedidoIfoodDto);
			if (pessoa.IsNotNull())
			{
				PreDocumentoFiscal.SetarDadosEntregador(IndicadorIntermediador.OperacaoComEntregaDomicilio, pessoa.CpfCnpj, pessoa.Nome, pessoa.Carteira?.EnderecoPrincipal);
			}
		}

		private DigisatServer.Domain.Main.Aggregates.CadastrosAgg.Pessoas.Pessoa SelecionarEntregadorPedidoIfood(PedidoIfoodDto pedidoIfoodDto)
		{
			List<DigisatServer.Domain.Main.Aggregates.CadastrosAgg.Pessoas.Pessoa> list = (from x in _pessoaRepositoryRead.Find(PessoaSpecifications.AtivoPorTipoCadastro(ativo: true, TipoPessoaCadastro.Entregador))
				orderby x.Nome
				select x).ToList();
			if (!list.Any())
			{
				return null;
			}
			return DialogoFactory.MostrarDialogoComboBox($"Selecione um entregador para o pedido iFood {pedidoIfoodDto.Numero}.", "Entregador", list, "Nome");
		}

		private ProdutoServicoEmpresa ObterProdutoIfoodPorCodigo(string codigo)
		{
			if (!string.IsNullOrEmpty(codigo))
			{
				return ProdutoServicoEmpresaRepositoryRead.FindOne(ProdutoServicoEmpresaSpecifications.PorCodigoIfood(codigo).PorEmpresa(_perfilEmpresa.Empresa.Id));
			}
			return null;
		}

		private static decimal ConverterQuantidadeIfood(decimal quantidade, string unidade)
		{
			string text = unidade.ToStringEmptyWhenNull().Trim().ToUpperInvariant();
			if (text == "G" || text == "ML")
			{
				return quantidade / 1000m;
			}
			return quantidade;
		}

		public async Task VenderAdicional(PedidoIfoodItemDto pedidoIfoodItemDto)
		{
			IEnumerable<ObjectId> lista = pedidoIfoodItemDto.SubItens.Select((PedidoIfoodSubItemDto x) => ObjectId.Parse(x.ItemReferencia));
			IEnumerable<ProdutoServicoEmpresa> source = await ProdutoServicoEmpresaRepositoryRead.AggregateIn(lista);
			ConfiguracaoDepartamentoVenda configuracaoDepartamentoVenda = DadosSistema.ObterDepartamentoVenda();
			foreach (PedidoIfoodSubItemDto itemAdicional in pedidoIfoodItemDto.SubItens.Where((PedidoIfoodSubItemDto item) => item.Preco > 0m))
			{
				ProdutoServicoEmpresa produtoServicoEmpresa = source.FirstOrDefault((ProdutoServicoEmpresa x) => x.Id.ToString().Equals(itemAdicional.ItemReferencia));
				ProdutoServicoLocal produtoServicoLocal = FluentFactory<ProdutoServicoLocalFactory>.Init().ComProdutoServicoEmpresa(produtoServicoEmpresa).Criar();
				decimal quantidade = pedidoIfoodItemDto.Quantidade * itemAdicional.Quantidade;
				Estoque estoque = produtoServicoLocal.To<ProdutoLocal>()?.ProcessarComposicaoRestaurante(quantidade, Seletor);
				if (!estoque.IsNull())
				{
					ItemDocumentoFiscal itemDocumentoFiscal = FluentFactory<ItemDocumentoFiscalFactory>.Init().ComProdutoServicoLocal(produtoServicoLocal).Criar()
						.To<ItemDocumentoFiscalProduto>()
						.ComEstoque(estoque)
						.ComPermitirVenderAcimaDoLimiteDeDesconto(PermitirVenderAcimaDoLimiteDeDesconto)
						.ComPrecoItemMesaConta(itemAdicional.Preco)
						.ComDepartamentoReferencia(configuracaoDepartamentoVenda.DepartamentoVendaReferencia);
					ExecutarVenda(itemDocumentoFiscal);
				}
			}
		}

		public async void EmitirDocumentoFiscal(MovimentacaoDto movimentacao)
		{
			if (!ValidarQuantidadeEstoque(movimentacao) || !ValidarClienteValorAtraso(movimentacao))
			{
				return;
			}
			_importandoParaDocumentoFiscal = true;
			try
			{
				IEnumerable<ItemDto> enumerable2;
				if (!DadosSistema.ConfiguracaoDto.Saida.EmiteDocumentoFiscalConjugado.Valor)
				{
					IEnumerable<ItemDto> enumerable = movimentacao.Itens.Where((ItemDto a) => a.ProdutoServico.Tipo != TipoProdutoServico.Servico).ToList();
					enumerable2 = enumerable;
				}
				else
				{
					enumerable2 = movimentacao.Itens;
				}
				IEnumerable<ItemDto> itens = enumerable2;
				if (!itens.Any())
				{
					DialogoFactory.MostrarDialogoConfirma($"{movimentacao.TipoText} não possui itens para importar");
					RecuperarFoco();
					return;
				}
				ConsumidorLocal consumidorLocal = ConsumidorLocal.Criar().ComPessoa(movimentacao.Pessoa).ComFuncAtualizarClienteDto(() => _service.Canal((IPessoaModuleService service) => service.ObterClienteDto(movimentacao.Pessoa.Id.ToString())));
				consumidorLocal.AtualizarClienteDto();
				IndicarConsumidor(consumidorLocal);
				if (PodeAbrir() && !ExecutarAbertura(solicitarVendedor: false))
				{
					return;
				}
				DigisatServer.Domain.Main.Aggregates.CadastrosAgg.Pessoas.Pessoa pessoa = movimentacao.VendedorResponsavel.Morfar();
				if (pessoa != null)
				{
					IndicarVendedor(VendedorLocal.Criar().ComPessoa(pessoa));
				}
				IEnumerable<ProdutoServicoEmpresa> produtosServicosEmpresa = await ProdutoServicoEmpresaRepositoryRead.AggregateIn(itens.Select((ItemDto x) => ObjectId.Parse(x.ProdutoServicoEmpresaReferencia)));
				IEnumerable<IAbastecimento> source = Enumerable.Empty<IAbastecimento>();
				IEnumerable<string> idsAbastecimentos = itens.Select((ItemDto i) => i.AbastecimentoReferencia);
				if (idsAbastecimentos.Any())
				{
					source = (await _service.Canal((IPostoCombustivelModuleService x) => x.ObterAbastecimentosDto(idsAbastecimentos))).MorfarCollection();
				}
				List<string> list = new List<string>();
				foreach (ItemDto item in itens)
				{
					VendedorLocal vendedor = ObterVendedorIndicadoNoItem(item);
					ProdutoServicoEmpresa produtoServicoEmpresa = produtosServicosEmpresa.FirstOrDefault((ProdutoServicoEmpresa x) => x.Id.Equals(ObjectId.Parse(item.ProdutoServicoEmpresaReferencia)));
					IAbastecimento comAbastecimento = source.FirstOrDefault((IAbastecimento x) => x.Id.Equals(item.AbastecimentoReferencia));
					ProdutoServicoLocal produtoServicoLocal = FluentFactory<ProdutoServicoLocalFactory>.Init().ComSeletor(Seletor).ComItemDto(item)
						.ComProdutoServicoEmpresa(produtoServicoEmpresa)
						.Criar();
					EstoqueDto estoqueDto = item.Estoque;
					if (produtoServicoLocal.Is<ProdutoLocal>() && produtoServicoLocal.To<ProdutoLocal>().Estoque.IsNormal && !produtoServicoLocal.To<ProdutoLocal>().Estoque.PermiteVendaFracionada && item.Quantidade % 1m != 0m)
					{
						list.Add($"{produtoServicoLocal.Descricao}");
						continue;
					}
					produtoServicoLocal.ToDo((ProdutoLocal produtoLocal) =>
					{
						ProdutoEmpresa produtoEmpresa = produtoServicoEmpresa as ProdutoEmpresa;
						if (produtoEmpresa.IsNotNull() && !produtoEmpresa.Estoque.IsNormal && item.Estoque.IsExactlyObject<EstoqueDto>())
						{
							DialogoFactory.MostrarDialogoConfirma($"Informe o estoque vendido para o item {item.ProdutoServico.Descricao}");
							produtoLocal.CriarEstoqueControlado(item.Quantidade);
							estoqueDto = produtoLocal.ObterEstoqueControladoVendido().ProjectedAsDto();
						}
					});
					ItemDocumentoFiscal itemDocumentoFiscal = FluentFactory<ItemDocumentoFiscalFactory>.Init().ComProdutoServicoLocal(produtoServicoLocal).ComEstoque(estoqueDto)
						.ComAbastecimento(comAbastecimento)
						.Criar()
						.ComPermitirVenderAcimaDoLimiteDeDesconto(PermitirVenderAcimaDoLimiteDeDesconto)
						.ComDepartamentoReferencia(item.DepartamentoReferencia)
						.ComVendedor(vendedor);
					try
					{
						if (movimentacao.Tipo == TipoMovimentacao.Orcamento && itemDocumentoFiscal is ItemDocumentoFiscalProduto && !DadosSistema.ConfiguracaoDto.Saida.PermitirEstoqueNegativo.Valor)
						{
							((ItemDocumentoFiscalProduto)itemDocumentoFiscal).VerificarEstoque(Seletor);
						}
						ExecutarVenda(itemDocumentoFiscal);
						if (item.TotalDesconto > 0m)
						{
							_emissorService.AplicarDesconto(itemDocumentoFiscal, item.TotalDesconto);
							itemDocumentoFiscal.ComDesconto(item.TotalDesconto);
						}
						else if (item.TotalOutrasDespesas > 0m)
						{
							_emissorService.AplicarAcrescimo(itemDocumentoFiscal, item.TotalOutrasDespesas);
							itemDocumentoFiscal.ComAcrescimo(item.TotalOutrasDespesas);
						}
						if (item.Cancelado)
						{
							_emissorService.CancelarItem(itemDocumentoFiscal.NumeroItem);
							itemDocumentoFiscal.Cancelar();
						}
						itemDocumentoFiscal.CalcularValorIcmsDesonerado(PreDocumentoFiscal);
					}
					catch (Exception ex)
					{
						ex.ShowLastException($"Item: {produtoServicoEmpresa.ProdutoServico.Descricao}.");
					}
				}
				if (list.Any())
				{
					DialogoFactory.MostrarDialogoConfirma((list.Count > 1) ? $"Atenção! Os seguintes produtos não foram importados, pois estão configurados para não serem vendidos fracionados:\n {list.ToArray().LinhasParaTexto()}" : $"Atenção! O produto não foi importado, pois está configurado para não ser vendido fracionado:\n {list.ToArray().LinhasParaTexto()}");
				}
				if (DadosSistema.IsPaf)
				{
					if (itens.All((ItemDto x) => x.Cancelado))
					{
						PreDocumentoFiscal.SetarMovimentacaoReferenciada(movimentacao);
						ExecutarCancelamento();
						return;
					}
					switch (movimentacao.Tipo)
					{
					case TipoMovimentacao.Dav:
					case TipoMovimentacao.Delivery:
					case TipoMovimentacao.Orcamento:
						Seletor.Get<PainelTotalizacaoBase>().AdicionarMensagemPromocional(DavMensagemPromocional.Criar().ComNumero(movimentacao.Numero));
						break;
					case TipoMovimentacao.DavOs:
						Seletor.Get<PainelTotalizacaoBase>().AdicionarMensagemPromocional(DavOsMensagemPromocional.Criar().ComNumero(movimentacao.Numero));
						break;
					case TipoMovimentacao.PreVenda:
						Seletor.Get<PainelTotalizacaoBase>().AdicionarMensagemPromocional(PreVendaMensagemPromocional.Criar().ComNumero(movimentacao.Numero));
						break;
					case TipoMovimentacao.NotaFiscalConsumidorEletronica:
						return;
					}
				}
				PreDocumentoFiscal.SetarMovimentacaoReferenciada(movimentacao);
				if ((movimentacao.Tipo == TipoMovimentacao.Delivery || movimentacao.OrigemPedirMenu) && (_emissorService.Is<INfceService>() || _emissorService.Is<IRegistroVendaService>() || _emissorService.Is<ICFeService>()) && movimentacao.TotalFrete > 0m)
				{
					if (DialogoFactory.MostrarDialogoSimNao("Deseja adicionar o valor de frete ao total do documento fiscal?") == MessageBoxResult.Yes)
					{
						PreDocumentoFiscal.SetarFrete(movimentacao.ModalidadeFrete, movimentacao.TotalFrete);
					}
					IEnumerable<EntregaDeliveryDto> source2 = await _service.Canal((IDeliveryModuleService service) => service.ObterDeliveries(movimentacao.Numero));
					if (source2.Any() && source2.First().Entregador.IsExactlyObject<PessoaDto>() && movimentacao.Pessoa.Id != DadosSistema.IdClienteConsumidor)
					{
						PreDocumentoFiscal.SetarDadosEntregador(IndicadorIntermediador.OperacaoComEntregaDomicilio, source2.First().Entregador.CpfCnpj, source2.First().Entregador.Nome, source2.First().Entregador.EnderecoPrincipal.Morfar());
					}
				}
				if (movimentacao.Tipo != TipoMovimentacao.Delivery && movimentacao.OrigemPedirMenu)
				{
					_ = movimentacao.TotalDescontoAplicado > 0m;
				}
				if (!string.IsNullOrEmpty(movimentacao.ResumoFormaPagamentoToText))
				{
					string arg = (movimentacao.TabelaPreco.IsExactlyObject<TabelaPrecoDtoNull>() ? string.Empty : $"Tabela de preço: {movimentacao.TabelaPreco.Descricao}\n");
					PreDocumentoFiscal.SetarObservacaoFormaPagamento($"{arg}Resumo forma de pgto: {movimentacao.ResumoFormaPagamentoToText}\nResumo espécie pgto: {movimentacao.ResumoEspeciePagamentoToText?.RemoverQuebraDeLinha()}");
				}
			}
			finally
			{
				_importandoParaDocumentoFiscal = false;
			}
		}

		private bool ValidarQuantidadeEstoque(MovimentacaoDto dto)
		{
			try
			{
				if (!dto.IsDocumentoAuxiliar || !DadosSistema.ConfiguracaoDto.Saida.ValidarEstoqueAoFaturar.Valor)
				{
					return true;
				}
				_service.Canal((IMovimentacaoSaidaModuleService service) =>
				{
					service.ValidarQuantidadeEstoque(new List<string> { dto.Id });
				});
				return true;
			}
			catch (Exception ex)
			{
				ex.ShowLastException();
				return false;
			}
		}

		private bool ValidarClienteValorAtraso(MovimentacaoDto dto)
		{
			if (!dto.IsDocumentoAuxiliar || dto.Pessoa.ConsumidorReservadoSistema || !DadosSistema.ConfiguracaoDto.Saida.AlertarClienteInadimplente.Valor)
			{
				return true;
			}
			ClienteDto clienteDto = _service.Canal((IPessoaModuleService service) => service.ObterClienteDto(dto.Pessoa.Id));
			if (clienteDto.ValorEmAtraso <= 0m)
			{
				return true;
			}
			if (DialogoFactory.MostrarDialogoConfirmaInformacaoOculta(clienteDto.AvisoValorEmAtraso, "Situação 1. Verifique!") != MessageBoxResult.OK)
			{
				return false;
			}
			AutorizacaoDto autorizacaoDto = DadosSistema.AutenticacaoService.Instancia.VerificarPermissao<DigisatServer.Infrastructure.Crosscutting.Module.PontoDeVenda, PermitirVenderParaInadimplente>();
			if (autorizacaoDto.IsNotNull())
			{
				PreDocumentoFiscal?.AdicionarAutorizacao(autorizacaoDto);
			}
			return autorizacaoDto != null;
		}

		private static VendedorLocal ObterVendedorIndicadoNoItem(ItemDto item)
		{
			DigisatServer.Domain.Main.Aggregates.CadastrosAgg.Pessoas.Pessoa pessoa = item.VendedorResponsavel.Morfar();
			if (pessoa.IsNull())
			{
				pessoa = item.TecnicoResponsavel.Morfar();
			}
			if (pessoa.IsNull())
			{
				return null;
			}
			return VendedorLocal.Criar().ComPessoa(pessoa);
		}

		private VendedorLocal ObterVendedorItemMesaConta(ItemMesaContaDto itemMesaContaDto)
		{
			if (string.IsNullOrEmpty(itemMesaContaDto.GarcomReferencia))
			{
				return null;
			}
			DigisatServer.Domain.Main.Aggregates.CadastrosAgg.Pessoas.Pessoa byId = _pessoaRepositoryRead.GetById(ObjectId.Parse(itemMesaContaDto.GarcomReferencia));
			if (byId.IsNull())
			{
				return null;
			}
			return VendedorLocal.Criar().ComPessoa(byId);
		}

		public IEnumerable<IAbastecimento> EmitirAbastecimentos(IEnumerable<IAbastecimento> abastecimentos, bool registroAbastecimentoManual = false)
		{
			_importandoParaDocumentoFiscal = true;
			try
			{
				if (PodeAbrir() || (_emissorService is INotaManualService && Estado is DocumentoFiscalFechado))
				{
					ExecutarAbertura();
				}
				List<IAbastecimento> list = new List<IAbastecimento>();
				ConfiguracaoDepartamentoVenda configuracaoDepartamentoVenda = DadosSistema.ObterDepartamentoVenda();
				foreach (IAbastecimento abastecimento in abastecimentos)
				{
					ProdutoServicoEmpresa produtoServicoEmpresa = ProdutoServicoEmpresaRepositoryRead.FindOne(EntityBaseSpecification<ProdutoServicoEmpresa>.PorId(abastecimento.IdProduto));
					ItemDocumentoFiscal itemDocumentoFiscal = FluentFactory<ItemDocumentoFiscalFactory>.Init().ComProdutoServicoLocal(FluentFactory<ProdutoServicoLocalFactory>.Init().ComProdutoServicoEmpresa(produtoServicoEmpresa.SetarTabelaPreco(TabelaPrecoLocal?.Id ?? ObjectId.Empty)).Criar()).ComAbastecimento(abastecimento)
						.ComRegistroAbastecimentoManual(registroAbastecimentoManual)
						.ComTabelaPreco(TabelaPrecoLocal)
						.Criar()
						.ComPermitirVenderAcimaDoLimiteDeDesconto(PermitirVenderAcimaDoLimiteDeDesconto)
						.ComVendedor(Vendedor)
						.ComDepartamentoReferencia(configuracaoDepartamentoVenda.DepartamentoVendaReferencia);
					try
					{
						ExecutarVenda(itemDocumentoFiscal);
					}
					catch (Exception ex)
					{
						ex.ShowLastException();
						return list;
					}
					list.Add(abastecimento);
				}
				Informacao.ControlarFoco();
				return list;
			}
			finally
			{
				_importandoParaDocumentoFiscal = false;
			}
		}

		private void InformacaoOnLimpouEvent(object sender, EventArgs eventArgs)
		{
			if (Lista.PossuiItemSelecionado)
			{
				PainelTitulo.AlterarTitulo(Lista.ItemSelecionado.ToString());
			}
			else
			{
				PainelTitulo.LimparTitulo();
			}
			_eventPublisher.Publish(new LimparImagemEvent());
		}

		private void ListaProdutoServicoOnAlterouItemSelecionadoEvent(object sender, ProdutoServicoLocal produtoServico)
		{
			if (produtoServico != null)
			{
				PainelTitulo.AlterarTitulo(produtoServico.ToString());
				_eventPublisher.Publish(new SelecionouItemDocumentoFiscalProdutoEvent((!produtoServico.Is<ProdutoLocal>()) ? produtoServico.To<ServicoLocal>()?.Imagem : produtoServico.To<ProdutoLocal>()?.Imagem));
			}
		}

		public void IndicarConsumidor(ConsumidorLocal consumidorLocal)
		{
			if (consumidorLocal.IsNull())
			{
				return;
			}
			Consumidor = consumidorLocal;
			if (consumidorLocal.Valido)
			{
				_emissorService.IdentificarConsumidor(consumidorLocal);
			}
			PreDocumentoFiscal?.SetarConsumidor(consumidorLocal);
			Consumidor.ComFuncAtualizarClienteDto(() => DadosSistema.GetService().Canal((IPessoaModuleService service) => service.ObterClienteDto(consumidorLocal.Id.ToString())));
			TabelaPrecoLocal tabelaPrecoLocal = Seletor.Get<PainelBuscaTabelaPreco>().Lista.Itens.FirstOrDefault((TabelaPrecoLocal a) =>
			{
				ObjectId id = a.Id;
				ObjectId? objectId = consumidorLocal.Pessoa?.Cliente?.TabelaPrecoReferencia;
				return id == objectId;
			});
			if (tabelaPrecoLocal != null)
			{
				IndicarTabelaPreco(tabelaPrecoLocal, solicitarRecalculo: true, tabelaPrecoIndicadaPessoa: true);
				if (Lista.Numero <= 0)
				{
					_setouTabelaPrecoConsumidorSemItemLancado = true;
				}
			}
			VendedorLocal vendedorLocal = Seletor.Get<PainelBuscaVendedor>().Lista.Itens.FirstOrDefault((VendedorLocal a) =>
			{
				ObjectId id = a.Id;
				ObjectId? objectId = consumidorLocal.Pessoa?.Cliente?.VendedorReferencia;
				return id == objectId;
			});
			if (vendedorLocal != null && !vendedorLocal.IsNenhum)
			{
				IndicarVendedor(vendedorLocal);
			}
		}

		public void IndicarVendedor(VendedorLocal vendedorLocal)
		{
			if (!vendedorLocal.IsNull())
			{
				Vendedor = vendedorLocal;
				PreDocumentoFiscal?.SetarVendedor(vendedorLocal);
				RaisePropertyChanged(() => ExibirVendedor);
			}
		}

		public void IndicarTabelaPreco(TabelaPrecoLocal tabelaPrecoLocal, bool solicitarRecalculo = false, bool tabelaPrecoIndicadaPessoa = false)
		{
			if (TabelaPrecoLocal?.Id == tabelaPrecoLocal?.Id || (TabelaPrecoLocal == null && tabelaPrecoLocal.IsNenhuma))
			{
				return;
			}
			TabelaPrecoLocal = tabelaPrecoLocal;
			TabelaPreco = tabelaPrecoLocal?.DescricaoToView;
			PreDocumentoFiscal?.SetarTabelaPreco(tabelaPrecoLocal);
			if (_emissorService.Is<IEcfService>() || !solicitarRecalculo || Lista.Numero <= 0 || DialogoFactory.MostrarDialogoSimNao(tabelaPrecoIndicadaPessoa ? $"Deseja recalcular os preços dos itens utilizando a tabela de preço '{tabelaPrecoLocal.Descricao}', indicada na pessoa?" : $"Deseja recalcular os preços dos itens utilizando a tabela de preço '{tabelaPrecoLocal.Descricao}'?") != MessageBoxResult.Yes)
			{
				return;
			}
			bool flag = false;
			foreach (ItemDocumentoFiscal iten in Lista.Itens)
			{
				ProdutoServicoEmpresa oneBy = ProdutoServicoEmpresaRepositoryRead.GetOneBy((ProdutoServicoEmpresa x) => x.Id, iten.ProdutoServicoLocal.ProdutoServicoEmpresaReferencia);
				oneBy.SetarTabelaPreco(TabelaPrecoLocal.Id);
				decimal precoVendaVigente = oneBy.Preco.PrecoVendaVigente;
				if (precoVendaVigente < oneBy.Preco.Custo.Valor)
				{
					if (flag)
					{
						iten.ComPrecoItemMesaConta(precoVendaVigente);
						_emissorService.AlterarPrecoUnitario(iten, precoVendaVigente);
						iten.ProcessarComissaoTabelaPreco(TabelaPrecoLocal);
						iten.ComTabelaPreco(TabelaPrecoLocal);
					}
					else
					{
						AutorizacaoDto autorizacaoDto = DadosSistema.AutenticacaoService.Instancia.VerificarPermissao<DigisatServer.Infrastructure.Crosscutting.Module.PontoDeVenda, PermitirVenderAbaixoPrecoCusto>();
						if (autorizacaoDto != null)
						{
							PreDocumentoFiscal?.AdicionarAutorizacao(autorizacaoDto);
							iten.ComPrecoItemMesaConta(precoVendaVigente);
							_emissorService.AlterarPrecoUnitario(iten, precoVendaVigente);
							iten.ProcessarComissaoTabelaPreco(TabelaPrecoLocal);
							iten.ComTabelaPreco(TabelaPrecoLocal);
							flag = true;
						}
					}
				}
				else
				{
					iten.ComPrecoItemMesaConta(precoVendaVigente);
					_emissorService.AlterarPrecoUnitario(iten, precoVendaVigente);
					iten.ProcessarComissaoTabelaPreco(TabelaPrecoLocal);
					iten.ComTabelaPreco(TabelaPrecoLocal);
				}
				iten.CalcularValorIcmsDesonerado(PreDocumentoFiscal);
			}
			Subtotal = Lista.Itens.Sum((ItemDocumentoFiscal x) => x.TotalLiquido);
			RecalculouPrecoTabelaPreco = true;
		}

