		{
			UtilizouCashback = utilizouCashback;
			PreDocumentoFiscal?.SetarUtilizouCashback(utilizouCashback, valorCashbackUtilizado);
		}

		public void FinalizarDocumentoFiscal()
		{
			PreDocumentoFiscal = null;
			DadosVeiculoMaquinaEquipamento = null;
			UtilizouCashback = false;
			RecalculouPrecoTabelaPreco = false;
			Limpar();
			Lista.Limpar();
			Subtotal = 0m;
			QuantidadeTotalDosItens = string.Empty;
			Consumidor = null;
			Vendedor = null;
			Seletor.Get<PainelBuscaTabelaPreco>().ResetToDefault();
			Seletor.Get<PainelObservacao>().ResetToDefault();
			Seletor.Get<PainelObservacaoPosto>()?.ResetToDefault();
			PainelTitulo.LimparTitulo();
			Estado = DocumentoFiscalFechado.Criar();
			_emissorService.VerificarEstado();
			_emissorService.FinalizarDocumentoFiscal();
			_preDocumentoFiscalRepositoryWrite.DeleteAll();
			if (SeletorEsquerdo.Painel is PainelEsquerdoTotalizacao)
			{
				bool flag = SeletorEsquerdo.Historico.Any((IPainel x) => x is PainelMenuRapidoPontoDeVenda);
				SeletorEsquerdo.VoltarTudo();
				if (flag)
				{
					SeletorEsquerdo.Selecionar<PainelMenuRapidoPontoDeVenda>();
				}
			}
			SeletorEsquerdo.Get<PainelEsquerdoComercio>()?.LimparImagemProduto();
		}

		public void AssinarEventos()
		{
			_eventosCardapioDispose?.Dispose();
			_eventosObservacaoDispose?.Dispose();
			_eventosMenuRapidoDispose?.Dispose();
			_eventoFaturarPedidoIfoodDispose?.Dispose();
			_eventoFaturarPedidoIfoodDispose = _eventPublisher.GetEvent((FaturarPedidoIfoodPdvEvent @event) =>
			{
				AgendarImportacaoPedidoIfood();
			});
			AgendarImportacaoPedidoIfood();
			_eventosCardapioDispose = new CompositeDisposable { _eventPublisher.GetEvent<ItemCardapioSelecionadoPontoDeVendaEvent>(VenderItemCardapio) };
			_eventosObservacaoDispose = new CompositeDisposable { _eventPublisher.GetEvent((ObservacaoSelecionadaPontoDeVendaEvent @event) =>
			{
				if (Lista.PossuiItemSelecionado)
				{
					ThreadPrincipal.Executar(() =>
					{
						Lista.ItemSelecionado.SalvarObservacao(@event.Observacao);
						PreDocumentoFiscal.Salvar();
						Informacao.ControlarFoco();
					});
				}
			}) };
			_eventosMenuRapidoDispose = new CompositeDisposable { _eventPublisher.GetEvent<ItemMenuRapidoSelecionadoPontoDeVendaEvent>(VenderItemMenuRapido) };
		}

		private void VenderItemCardapio(ItemCardapioSelecionadoPontoDeVendaEvent @event)
		{
			LoaderProcessoService.MostrarLoader();
			new Thread(() =>
			{
				try
				{
					ThreadPrincipal.Executar(() =>
					{
						ExecutarVenderItem(@event);
					});
					foreach (ItemAdicionalViewModel itemAdicionalViewModel in @event.ItemCardapioViewModel.AdicionaisSelecionados)
					{
						ThreadPrincipal.Executar(() =>
						{
							ExecutarVenderAdicional(@event, itemAdicionalViewModel);
						});
					}
				}
				finally
				{
					LoaderProcessoService.EsconderLoader();
				}
			}).Start();
		}

		private void ExecutarVenderItem(ItemCardapioSelecionadoPontoDeVendaEvent @event)
		{
			ProdutoServicoEmpresa produtoServicoEmpresa = ProdutoServicoEmpresaRepositoryRead.FindOne(EntityBaseSpecification<ProdutoServicoEmpresa>.PorId(@event.ItemCardapioViewModel.ItemCardapio.ProdutoServicoEmpresa.Id));
			FluentFactory<ProdutoServicoLocalFactory>.Init().ComProdutoServicoEmpresa(produtoServicoEmpresa.SetarTabelaPreco(TabelaPrecoLocal?.Id ?? ObjectId.Empty)).ComSeletor(Seletor)
				.ComImpressora(@event.ItemCardapioViewModel.Impressora)
				.ComPermissaoEstoqueNegativo(_perfilEmpresa.Configuracao.PermitirEstoqueNegativo)
				.ComComponentesRevemovidos(@event.ItemCardapioViewModel.ComponentesRemovidos.Select((ItemComponenteViewModel componente) => componente.Dto))
				.Criar()
				.Vender((@event.ItemCardapioViewModel.ItemCardapio.Quantidade > 0m) ? @event.ItemCardapioViewModel.ItemCardapio.Quantidade : 1m);
		}

		private void ExecutarVenderAdicional(ItemCardapioSelecionadoPontoDeVendaEvent @event, ItemAdicionalViewModel itemAdicionalViewModel)
		{
			ProdutoServicoEmpresa produtoServicoEmpresa = ProdutoServicoEmpresaRepositoryRead.FindOne(EntityBaseSpecification<ProdutoServicoEmpresa>.PorId(itemAdicionalViewModel.ItemAdicional.ProdutoServicoEmpresa.Id));
			FluentFactory<ProdutoServicoLocalFactory>.Init().ComProdutoServicoEmpresa(produtoServicoEmpresa.SetarTabelaPreco(TabelaPrecoLocal?.Id ?? ObjectId.Empty)).ComSeletor(Seletor)
				.ComImpressora(@event.ItemCardapioViewModel.Impressora)
				.ComPermissaoEstoqueNegativo(_perfilEmpresa.Configuracao.PermitirEstoqueNegativo)
				.Criar()
				.Vender(itemAdicionalViewModel.To<ItemAdicionalSelecionadoViewModel>().Quantidade);
		}

		private void VenderItemMenuRapido(ItemMenuRapidoSelecionadoPontoDeVendaEvent @event)
		{
			LoaderProcessoService.MostrarLoader();
			new Thread(() =>
			{
				try
				{
					ThreadPrincipal.Executar(() =>
					{
						ExecutarVenderItem(@event);
					});
					ThreadPrincipal.Executar(() =>
					{
						ExecutarVenderAdicional(@event);
					});
				}
				finally
				{
					LoaderProcessoService.EsconderLoader();
				}
			}).Start();
		}

		private void ExecutarVenderItem(ItemMenuRapidoSelecionadoPontoDeVendaEvent @event)
		{
			ProdutoServicoEmpresa produtoServicoEmpresa = ProdutoServicoEmpresaRepositoryRead.FindOne(EntityBaseSpecification<ProdutoServicoEmpresa>.PorId(@event.ItemMenuRapidoViewModel.ItemMenuRapido.ProdutoServicoEmpresa.Id));
			ProdutoServicoLocal produtoServicoLocal = FluentFactory<ProdutoServicoLocalFactory>.Init().ComProdutoServicoEmpresa(produtoServicoEmpresa.SetarTabelaPreco(TabelaPrecoLocal?.Id ?? ObjectId.Empty)).ComSeletor(Seletor)
				.ComImpressora(@event.ItemMenuRapidoViewModel.Impressora)
				.ComPermissaoEstoqueNegativo(_perfilEmpresa.Configuracao.PermitirEstoqueNegativo)
				.ComComponentesRevemovidos(@event.ItemMenuRapidoViewModel.ComponentesRemovidos.Select((ItemMenuRapidoComponenteViewModel componente) => componente.Dto))
				.ComObservacoes(@event.ItemMenuRapidoViewModel.ObservacoesSelecionados)
				.ComValorDescontarBeneficio(@event.ItemMenuRapidoViewModel.ItemMenuRapido.ItemBase ? produtoServicoEmpresa.SetarTabelaPreco(TabelaPrecoLocal?.Id ?? ObjectId.Empty).Preco.PrecoVendaVigente : 0m)
				.ComDescricaoMenuRapido(@event.ItemMenuRapidoViewModel.ItemMenuRapido.DescricaoTela)
				.ComItemBase(@event.ItemMenuRapidoViewModel.ItemMenuRapido.ItemBase)
				.ComVenderComValorZerado(_emissorService.IsNot<EcfService>())
				.ComQuantidadeImprimirAmbienteProducao((@event.ItemMenuRapidoViewModel.ItemMenuRapido.Quantidade > 0m) ? @event.ItemMenuRapidoViewModel.ItemMenuRapido.Quantidade : 1m)
				.Criar();
			decimal quantidade;
			if (@event.ItemMenuRapidoViewModel.ItemMenuRapido.ItemBase && _emissorService.IsNot<EcfService>())
			{
				quantidade = 0m;
			}
			else
			{
				quantidade = ((@event.ItemMenuRapidoViewModel.ItemMenuRapido.Quantidade > 0m) ? @event.ItemMenuRapidoViewModel.ItemMenuRapido.Quantidade : 1m);
			}
			produtoServicoLocal.Vender(quantidade);
		}

		private void ExecutarVenderAdicional(ItemMenuRapidoSelecionadoPontoDeVendaEvent @event)
		{
			foreach (var item in from x in @event.ItemMenuRapidoViewModel.AdicionaisSelecionados
				group x by new
				{
					x.Grupo.UtilizarItemMaiorValor,
					x.Grupo.GrupoMenuReferencia,
					x.Grupo.TabelaPrecoReferencia
				})
			{
				IEnumerable<ProdutoServicoEmpresa> enumerable = ProdutoServicoEmpresaRepositoryRead.Find(EntityBaseEmpresaSpecification<ProdutoServicoEmpresa>.PorEmpresa(DadosSistema.EmpresaLogada.Id).PorProdutosServicosEmpresaReferencia(item.Select((ItemMenuRapidoAdicionalViewModel y) => y.ItemAdicionalMenuRapido.ProdutoServicoEmpresa.Id).ToArray()));
				foreach (ProdutoServicoEmpresa item2 in enumerable)
				{
					ObjectId tabelaPrecoReferencia = item.Key.TabelaPrecoReferencia;
					item2.SetarTabelaPreco(tabelaPrecoReferencia.IsDefaultOrEmpty() ? (TabelaPrecoLocal?.Id ?? ObjectId.Empty) : tabelaPrecoReferencia);
				}
				foreach (ItemMenuRapidoAdicionalViewModel itemMenuRapidoAdicionalViewModel in item)
				{
					ProdutoServicoEmpresa produtoServicoEmpresa = enumerable.FirstOrDefault((ProdutoServicoEmpresa x) => x.Id.Equals(itemMenuRapidoAdicionalViewModel.ItemAdicionalMenuRapido.ProdutoServicoEmpresa.Id));
					decimal valorItemMaiorValor = (item.Key.UtilizarItemMaiorValor ? enumerable.Max((ProdutoServicoEmpresa x) => x.Preco.PrecoVendaVigente) : 0m);
					FluentFactory<ProdutoServicoLocalFactory>.Init().ComProdutoServicoEmpresa(produtoServicoEmpresa).ComSeletor(Seletor)
						.ComImpressora(@event.ItemMenuRapidoViewModel.Impressora)
						.ComPermissaoEstoqueNegativo(_perfilEmpresa.Configuracao.PermitirEstoqueNegativo)
						.ComDescricaoMenuRapido(itemMenuRapidoAdicionalViewModel.Descricao)
						.ComValorDescontarBeneficio(itemMenuRapidoAdicionalViewModel.ValorDescontarBeneficio)
						.ComValorItemMaiorValor(valorItemMaiorValor)
						.ComVenderComValorZerado(_emissorService.IsNot<EcfService>())
						.Criar()
						.Vender(itemMenuRapidoAdicionalViewModel.To<ItemMenuRapidoAdicionalSelecionadoViewModel>().Quantidade);
				}
			}
		}

		public void DesassinarEventos()
		{
			_eventosCardapioDispose?.Dispose();
			_eventosCardapioDispose = null;
			_eventosObservacaoDispose?.Dispose();
			_eventosObservacaoDispose = null;
			_eventosMenuRapidoDispose?.Dispose();
			_eventosMenuRapidoDispose = null;
			_eventoFaturarPedidoIfoodDispose?.Dispose();
			_eventoFaturarPedidoIfoodDispose = null;
		}

		private void AgendarImportacaoPedidoIfood()
		{
			System.Windows.Application.Current.Dispatcher.BeginInvoke(new Action(ImportarPedidoIfoodSolicitado), DispatcherPriority.ApplicationIdle);
		}

		private void ImportarPedidoIfoodSolicitado()
		{
			if (!_eventoFaturarPedidoIfoodDispose.IsNull() && FaturarPedidoIfoodPdvEvent.PossuiPedidoPendente && !(Estado is DocumentoFiscalCarregando) && !(Estado is DocumentoFiscalEmissorAviso))
			{
				PedidoIfoodDto pedidoIfoodDto = FaturarPedidoIfoodPdvEvent.RetirarPedidoPendente();
				if (Seletor.Painel != this || !EmissorCarregadoEPronto() || !PodeAbrirPainelPedidosIfood())
				{
					DialogoFactory.MostrarDialogoConfirma($"Não foi possível faturar o pedido iFood {pedidoIfoodDto.Numero} no PDV.{Environment.NewLine}{Estado.MensagemOperador}{Environment.NewLine}Conclua a operação em andamento e importe o pedido pelo Ctrl+Y.");
				}
				else if (!(Estado is DocumentoFiscalAberto) || DialogoFactory.MostrarDialogoSimNao($"Existe uma venda em andamento no PDV.{Environment.NewLine}Incluir o pedido iFood {pedidoIfoodDto.Numero} nela?") == MessageBoxResult.Yes)
				{
					EmitirDocumentoFiscal(pedidoIfoodDto);
				}
			}
		}

