		public void BloquearDocumentoFiscalSemComunicacaoServidor()
		{
			if (!(Estado is DocumentoFiscalBloqueadoSemComunicacaoServidor))
			{
				Estado = DocumentoFiscalBloqueadoSemComunicacaoServidor.Criar();
			}
		}

		public void DesbloquearDocumentoFiscal()
		{
			if (Estado is DocumentoFiscalBloqueadoSemComunicacaoServidor)
			{
				Estado = DocumentoFiscalAberto.Criar();
				if (PreDocumentoFiscal.IsNull())
				{
					RecarregarPreDocumentoFiscal();
				}
			}
		}

		private void VerificarPdvOffline()
		{
			_emissorService.To<NfceService>()?.ConsultarStatusServico();
		}

		private bool PodeVerificarPdvOffline()
		{
			if (_emissorService.Is<NfceService>() && _podeVerificarPdvOffline)
			{
				return DadosSistema.VerificarPermissao<PontoDeVendaOffline, Visualizar>();
			}
			return false;
		}
	}
	public class PainelEspecie : PainelInteracao<PainelEspecie>
	{
