		private readonly IEnumerable<Especie> _especies = new List<Especie>
		{
			Especie.Criar().ComDescricao("Dinheiro"),
			Especie.Criar().ComDescricao("Cheque"),
			Especie.Criar().ComDescricao("Prazo"),
			Especie.Criar().ComDescricao(CartaoViewModel.DescricaoEcf).ComPermiteVinculado(permiteVinculado: true),
			Especie.Criar().ComDescricao("Vale"),
			Especie.Criar().ComDescricao("Cartao POS"),
			Especie.Criar().ComDescricao("Convenio"),
			Especie.Criar().ComDescricao("Vale Presente"),
			Especie.Criar().ComDescricao(CarteiraDigitalTefViewModel.DescricaoEcf).ComPermiteVinculado(permiteVinculado: true),
			Especie.Criar().ComDescricao("Crédito Loja"),
			Especie.Criar().ComDescricao("Terminal POS")
		};

		private IEnumerable<Especie> _especiesACadastrar;

		public override string Titulo => "Meios de pagamento ECF";

		public override string DescricaoDoBotao => "Incluir";

		public PainelEspecie()
		{
		}

		public PainelEspecie(IEcfService ecfService, Seletor<IPainel> seletor)
			: base(seletor)
		{
			_ecfService = ecfService;
		}

		protected override async void F2Method()
		{
			LoaderProcessoService.MostrarLoader("Cadastrando espécies...");
			await Task.Factory.StartNew(() =>
			{
				foreach (Especie item in _especiesACadastrar)
				{
					_ecfService.CadastrarEspecie(item.Descricao, item.PermiteVinculado);
				}
			}).ContinueWith((Task task) =>
			{
				LoaderProcessoService.EsconderLoader();
				if (task.IsFaulted)
				{
					task.Exception.ShowLastException();
				}
				Seletor.Voltar();
			}, CancellationToken.None, TaskContinuationOptions.None, TaskScheduler.FromCurrentSynchronizationContext());
		}

		protected override bool CanF2Method()
		{
			if (base.CanF2Method())
			{
				return _especiesACadastrar.Any();
			}
			return false;
		}

		public override void Load()
		{
			Campos.Clear();
			_ecfService.AguardarEcfCarregado();
			Lista<Especie> lista = new Lista<Especie>();
			List<Especie> especiesCadastradas = _ecfService.Especies.Where((Especie x) => !string.IsNullOrWhiteSpace(x.Descricao)).ToList();
			lista.Adicionar(especiesCadastradas);
			ItemInteracaoListaEspecie item = ItemInteracaoBase<ItemInteracaoListaEspecie, Lista<Especie>>.Criar().ComDescricao("Espécies cadastradas no ECF").ComValor(lista)
				.Build();
			Campos.Insert(0, item);
			_especiesACadastrar = _especies.Where((Especie x) => especiesCadastradas.All((Especie y) => y.Descricao != x.Descricao));
		}

		public override void UnLoad()
		{
			Campos.Clear();
		}

		public override bool PodeVoltar()
		{
			return true;
		}

		public override void Dispose()
		{
		}
	}
