	public class PainelEsquerdoComercio : BindableBase, IPainelEsquerdo, IPainel
	{
		private IDisposable _disposable;

		public IReadOnlyCollection<string> Atalhos => new List<string>();

		public IEnumerable<ItemMenuAtalho> MenuRibbon { get; }

		public Visibility ImagemPadraoVisibility
		{
			get
			{
				if (ImagemProduto != null)
				{
					return Visibility.Collapsed;
				}
				return Visibility.Visible;
			}
		}

		public Visibility ImagemProdutoVisibility
		{
			get
			{
				if (ImagemProduto != null)
				{
					return Visibility.Visible;
				}
				return Visibility.Collapsed;
			}
		}

		public Lista<Imagem> Imagens
		{
			get
			{
				return GetProperty(() => Imagens);
			}
			set
			{
				SetProperty(() => Imagens, value);
			}
		}

		public BitmapSource ImagemProduto
		{
			get
			{
				return GetProperty(() => ImagemProduto);
			}
			set
			{
				SetProperty(() => ImagemProduto, value, () =>
				{
					RaisePropertiesChanged(() => ImagemPadraoVisibility, System.Linq.Expressions.Expression.Lambda<Func<Visibility>>(System.Linq.Expressions.Expression.Property(System.Linq.Expressions.Expression.Constant(this, typeof(PainelEsquerdoComercio)), (MethodInfo)MethodBase.GetMethodFromHandle(__ldtoken(PainelEsquerdoComercio.get_ImagemProdutoVisibility()))), Array.Empty<ParameterExpression>()));
				});
			}
		}

		public PainelEsquerdoComercio(IEventPublisher eventPublisher)
		{
			eventPublisher.GetEvent<SelecionouItemDocumentoFiscalProdutoEvent>().Subscribe(ProcessarImagemProduto);
			eventPublisher.GetEvent<LimparImagemEvent>().Subscribe((LimparImagemEvent a) =>
			{
				LimparImagemProduto();
			});
			MenuRibbon = new List<ItemMenuAtalho>();
			eventPublisher.GetEvent<CarregouConfiguracaoServidorEvent>().Subscribe((CarregouConfiguracaoServidorEvent a) =>
			{
				ThreadPrincipal.Executar(CarregarImagensRotativasPontoDeVenda);
			});
		}

		private void ProcessarImagemProduto(SelecionouItemDocumentoFiscalProdutoEvent @event)
		{
			try
			{
				if (DadosSistema.ConfiguracaoDto.Saida.ExibirImagemProduto.Valor && !@event.IsNull() && !@event.ImagemProdutoServico.IsNull())
				{
					BitmapSource imagemProduto = @event.ImagemProdutoServico.Decompress().ToBitmapSource();
					ImagemProduto = imagemProduto;
				}
			}
			catch (Exception ex)
			{
				LoggerFactory.CreateLog().LogInfo("Erro ao criar o bitmap source do produto.", ex);
			}
		}

		public void SetarModoFuncionamento(IModoFuncionamento modoFuncionamento)
		{
			ThreadPrincipal.Executar(() =>
			{
				CarregarImagemPadraoPontoDeVenda(modoFuncionamento);
				CarregarImagensRotativasPontoDeVenda();
			});
		}

		public void FecharMethod()
		{
		}

		public bool CanFecharMethod()
		{
			return true;
		}

		public virtual void Load()
		{
			ImagemProduto = null;
		}

		private void CarregarImagemPadraoPontoDeVenda(IModoFuncionamento modoFuncionamento)
		{
			try
			{
				Imagens = new Lista<Imagem>();
				BitmapImage bitmapImage = new BitmapImage();
				bitmapImage.BeginInit();
				bitmapImage.UriSource = new Uri(Path.Combine(AppDomain.CurrentDomain.BaseDirectory, "Images", modoFuncionamento.NomeImagemPadraoPontoDeVenda), UriKind.Absolute);
				bitmapImage.EndInit();
				Imagens.Adicionar(new Imagem
				{
					ImagemPontoDeVenda = bitmapImage
				});
			}
			catch (Exception)
			{
			}
		}

		private void CarregarImagensRotativasPontoDeVenda()
		{
			try
			{
				if (!DadosSistema.ConfiguracaoServidorDto.IsNull() && (DadosSistema.ConfiguracaoServidorDto.Geral.ImagemPontoDeVenda1.Length > 100 || DadosSistema.ConfiguracaoServidorDto.Geral.ImagemPontoDeVenda2.Length > 100 || DadosSistema.ConfiguracaoServidorDto.Geral.ImagemPontoDeVenda3.Length > 100))
				{
					Imagens.Limpar();
					if (DadosSistema.ConfiguracaoServidorDto.Geral.ImagemPontoDeVenda1.Length > 100)
					{
						BitmapSource imagemPontoDeVenda = DadosSistema.ConfiguracaoServidorDto.Geral.ImagemPontoDeVenda1.Decompress().ToBitmapSource();
						Imagens.Adicionar(new Imagem
						{
							ImagemPontoDeVenda = imagemPontoDeVenda
						});
					}
					if (DadosSistema.ConfiguracaoServidorDto.Geral.ImagemPontoDeVenda2.Length > 100)
					{
						BitmapSource imagemPontoDeVenda2 = DadosSistema.ConfiguracaoServidorDto.Geral.ImagemPontoDeVenda2.Decompress().ToBitmapSource();
						Imagens.Adicionar(new Imagem
						{
							ImagemPontoDeVenda = imagemPontoDeVenda2
						});
					}
					if (DadosSistema.ConfiguracaoServidorDto.Geral.ImagemPontoDeVenda3.Length > 100)
					{
						BitmapSource imagemPontoDeVenda3 = DadosSistema.ConfiguracaoServidorDto.Geral.ImagemPontoDeVenda3.Decompress().ToBitmapSource();
						Imagens.Adicionar(new Imagem
						{
							ImagemPontoDeVenda = imagemPontoDeVenda3
						});
					}
					Imagens.PosicionarNoPrimeiro();
					AlternarImagens();
				}
			}
			catch (Exception)
			{
			}
		}

		private void AlternarImagens()
		{
			_disposable?.Dispose();
			_disposable = null;
			_disposable = Observable.Interval(TimeSpan.FromSeconds(DadosSistema.ConfiguracaoServidorDto.Geral.TempoParaTransicaoDaImagem.Valor)).Subscribe((long x) =>
			{
				Imagens.PosicionarNoProximo();
			});
		}

		public virtual void UnLoad()
		{
			_disposable?.Dispose();
			_disposable = null;
		}

		public virtual bool PodeVoltar()
		{
			return true;
		}

		public void LimparImagemProduto()
		{
			ImagemProduto = null;
		}
	}
	public class Imagem
	{
		public ImageSource ImagemPontoDeVenda { get; set; }
	}
