				.Build();
			F3Command = new DelegateCommand(Pesquisar, PodePesquisar);
			_listaMapaResumo = ItemInteracaoBase<ItemInteracaoListaMapaResumo, Lista<ItemMapaResumo>>.Criar().ComValor(new Lista<ItemMapaResumo>()).Build();
			Campos.Insert(0, _dataInicial);
			Campos.Insert(1, _dataFinal);
			Campos.Insert(2, ItemInteracaoBase<ItemInteracaoButton, System.Windows.Controls.Button>.Criar().ComValor(new System.Windows.Controls.Button
			{
				Content = "Pesquisar",
				Tag = "F3",
				HorizontalAlignment = System.Windows.HorizontalAlignment.Left,
				Command = F3Command
			}).Build());
			Campos.Insert(3, _listaMapaResumo);
		}

		private void Pesquisar()
		{
			_mapas = _mapaResumoRepositoryRead.Find(MapaResumoLocalSpecifications.All().PorNumeroFabricacao(_ecfService.NumeroFabricacao).PorDataMovimentoMaiorIgual(_dataInicial.Valor.Date)
				.PorDataMovimentoMenorIgual(_dataFinal.Valor.Date.ToFinalDia())) ?? new List<MapaResumoLocal>();
			_listaMapaResumo.Valor.Limpar();
			_listaMapaResumo.Valor.Adicionar(_mapas.Select((MapaResumoLocal mapa) => ItemMapaResumo.Criar().ComData(mapa.DataMovimento).ComCrz(mapa.ContadorReducaoZ)
				.ComVendaBruta(mapa.VendaBruta)));
		}

		private bool PodePesquisar()
		{
			return _dataInicial.Valor.Date <= _dataFinal.Valor.Date;
		}

		protected override void F2Method()
		{
			try
			{
				RelatorioMapaResumo.Criar().ComCnpj(_sessaoService.Sessao.Perfis.ItemSelecionado.Empresa.CpfCnpjFormatado).ComRazaoSocial(_sessaoService.Sessao.Perfis.ItemSelecionado.Empresa.Nome)
					.ComMapasResumo(_mapas.ToArray())
					.Processar()
					.ShowPreviewDialog();
			}
			catch (Exception ex)
			{
				ex.ShowLastException();
			}
		}

		protected override bool CanF2Method()
		{
			return _mapas.Any();
		}

