		{
		}

		public override void UnLoad()
		{
		}

		public override bool PodeVoltar()
		{
			return true;
		}

		public override void Dispose()
		{
		}
	}
	public class PainelMensagem : BindableBase, IPainelMensagem, IPainelSeletorDireito, IPainel
	{
		private readonly System.Timers.Timer _timer;

		private string _mensagemAnterior;

		public string Informacao
		{
			get
			{
				return GetProperty(() => Informacao);
			}
			set
			{
				SetProperty(() => Informacao, value);
			}
		}

		public PainelMensagem()
		{
			_timer = new System.Timers.Timer();
			_timer.Elapsed += (object sender, ElapsedEventArgs args) =>
			{
				_timer.Enabled = false;
				LimparMensagem(_mensagemAnterior);
			};
		}

		public void LimparMensagem(string mensagemAnterior = "")
		{
			if (!_timer.Enabled)
			{
				Informacao = mensagemAnterior;
				_mensagemAnterior = string.Empty;
			}
		}

		public void ForcarLimparMensagem()
		{
			if (_timer.Enabled)
			{
				_timer.Enabled = false;
			}
			LimparMensagem(_mensagemAnterior);
		}

		public void AlterarMensagem(string mensagem)
		{
			while (_timer.Enabled)
			{
				Thread.Sleep(20);
				DispatcherHelper.DoEvents();
			}
			Informacao = mensagem;
		}

		public void AlterarMensagemTimer(string titulo, double segundos = 5.0)
		{
			AlterarMensagem(titulo);
			if (_timer.Enabled)
			{
				_timer.Enabled = false;
			}
			_timer.Interval = TimeSpan.FromSeconds(segundos).TotalMilliseconds;
			_timer.Enabled = true;
		}

		public void AlterarMensagemTimerComRetornoDaMensagemAnterior(string mensagem, double segundos = 5.0)
		{
			_mensagemAnterior = Informacao;
			AlterarMensagemTimer(mensagem, segundos);
		}

		public static PainelMensagem Criar()
		{
			return new PainelMensagem();
		}

		public void FecharMethod()
		{
		}

		public bool CanFecharMethod()
		{
			return true;
		}

		public void Load()
		{
		}

		public void UnLoad()
		{
		}

		public bool PodeVoltar()
		{
			return true;
		}
	}
