		public static void RestartService(string serviceName, int timeoutMilliseconds = 10000)
		{
			try
			{
				ServiceController serviceController = new ServiceController(serviceName);
				int tickCount = Environment.TickCount;
				TimeSpan timeout = TimeSpan.FromMilliseconds(timeoutMilliseconds);
				serviceController.Refresh();
				if (serviceController.Status != ServiceControllerStatus.Stopped)
				{
					serviceController.Stop();
					serviceController.WaitForStatus(ServiceControllerStatus.Stopped, timeout);
					int tickCount2 = Environment.TickCount;
					timeout = TimeSpan.FromMilliseconds(timeoutMilliseconds - (tickCount2 - tickCount));
					serviceController.Start();
					serviceController.WaitForStatus(ServiceControllerStatus.Running, timeout);
				}
				else
				{
					serviceController.Start();
				}
				DialogoFactory.MostrarDialogoConfirma("Processo concluído. Verifique se os dados foram atualizados!");
			}
			catch (Exception)
			{
				DialogoFactory.MostrarDialogoConfirma("Não foi possível reiniciar o sincronizador");
			}
		}

