		public PainelMenuAdministrativoCupomFiscal(IEcfService emissorService, IEventPublisher eventPublisher, Otus.Modulo.PontoDeVendas.Interfaces.ITefService tefService, IWService service, IEnvioPafEcfService envioPafEcfService, IFarmaciaService farmaciaService, Seletor<IPainel> seletorEsquerdo, Seletor<IPainel> seletorDireito)
			: base(tefService, emissorService, envioPafEcfService, farmaciaService, seletorDireito)
		{
			_ecfService = emissorService;
			_eventPublisher = eventPublisher;
			_service = service;
			_seletorEsquerdo = seletorEsquerdo;
		}

		public override void Load()
		{
			base.Load();
			CriarCampos();
			Lista.PosicionarNoPrimeiro();
		}

		protected override void CriarCampos()
		{
			Lista.Limpar();
			base.CriarCampos();
			Lista.Adicionar(ItemMenu.Criar().ComDescricao("Abrir jornada fiscal").ComDescricaoDetalhada("Executar a abertura da jornada fiscal")
