				})
				.Build());
			Lista.Adicionar(ItemMenu.Criar().ComDescricao("Totalizadores não fiscais").ComDescricaoDetalhada("Visualizar/Cadastrar totalizadores não fiscais")
				.ComAcao(() =>
				{
