			Lista.Adicionar(ItemMenu.Criar().ComDescricao("Redução Z").ComDescricaoDetalhada("Emitir redução Z")
				.ComAcao(EmitirReducaoZ)
				.Build());
			Lista.Adicionar(ItemMenu.Criar().ComDescricao("Mapa resumo").ComDescricaoDetalhada("Visualizar/Imprimir mapa resumo")
				.ComAcao(() =>
				{
