		protected void ImprimirRelatorioMesasContasAbertas()
		{
			LoaderProcessoService.MostrarLoader($"Emitindo {DadosSistema.TipoRestaurante}s abertas");
			ExecutandoAcao = true;
			Task.Factory.StartNew((Func<Task>)(async () =>
			{
				EcfService.AguardarEcfCarregado();
				try
				{
					IEnumerable<MesaContaAbertaDto> mesasContasAbertasDto = await Service.Canal((IRestauranteModuleService service) => service.ObterMesasContasAbertas());
					EcfService.ImprimirRelatorioGerencialMesasContasAbertas(mesasContasAbertasDto);
				}
				catch (Exception ex)
				{
					ex.ShowLastException();
				}
			})).ContinueWith((Task<Task> task) =>
			{
				LoaderProcessoService.EsconderLoader();
				ExecutandoAcao = false;
				if (task.IsFaulted)
				{
					DialogoFactory.MostrarDialogoConfirma(task.Exception?.InnerException?.Message);
				}
				else
				{
					Seletor.Voltar();
				}
			}, CancellationToken.None, TaskContinuationOptions.None, TaskScheduler.FromCurrentSynchronizationContext());
		}

