		protected async void ExecutarFuncao(string mensagem, Action action)
		{
			LoaderProcessoService.MostrarLoader(mensagem);
			ExecutandoAcao = true;
			await Task.Factory.StartNew(() =>
			{
				if (!EcfService.Pronto)
				{
					throw new Exception("Emissor em erro!");
				}
				EcfService.AguardarEcfCarregado();
				action();
			}).ContinueWith((Task task) =>
			{
				LoaderProcessoService.EsconderLoader();
				ExecutandoAcao = false;
				if (task.IsFaulted)
				{
					DialogoFactory.MostrarDialogoConfirma(task.Exception?.InnerException?.Message);
				}
				else
				{
					Seletor.Voltar();
				}
			}, CancellationToken.None, TaskContinuationOptions.None, TaskScheduler.FromCurrentSynchronizationContext());
		}

		private async void GerarArquivo(string mensagem, Func<string> func)
		{
			LoaderProcessoService.MostrarLoader(mensagem);
			await Task.Factory.StartNew(() =>
			{
				EcfService.AguardarEcfCarregado();
				return func();
			}).ContinueWith((Task<string> task) =>
			{
				LoaderProcessoService.EsconderLoader();
				if (task.IsFaulted)
				{
					DialogoFactory.MostrarDialogoConfirma(task.Exception?.InnerException?.Message);
				}
				else
				{
					DialogoFactory.MostrarDialogoConfirma($"Arquivo {task.Result} gerado com sucesso.");
					Seletor.Voltar();
				}
			}, CancellationToken.None, TaskContinuationOptions.None, TaskScheduler.FromCurrentSynchronizationContext());
		}

		private void GerarTabelaIndiceTecnicoProducao()
		{
			IEnumerable<DigisatServer.Infrastructure.Crosscutting.RegistrosPafEcf.Classes.Composicao> enumerable = from x in _produtoServicoRepositoryRead.ObterComposicoes()
				select new DigisatServer.Infrastructure.Crosscutting.RegistrosPafEcf.Classes.Composicao(x.CodigoInterno, x.Descricao, x.Componentes.Select((DigisatServer.Domain.Main.Aggregates.CadastrosAgg.ProdutosServicos.Produtos.Componente y) => new DigisatServer.Infrastructure.Crosscutting.RegistrosPafEcf.Classes.Componente(y.Produto.CodigoInterno, y.Produto.Descricao, y.Quantidade, y.Produto.UnidadeMedida.Sigla)));
			if (!enumerable.Any())
			{
				DialogoFactory.MostrarDialogoConfirma("Este PAF-ECF não executa funções de baixa de estoque com base em índices técnicos de produção, não podendo ser utilizado por estabelecimento que necessite deste recurso.");
				return;
			}
			PafEcfArquivoTabelaIndiceTecnicoProducao pafEcfArquivoTabelaIndiceTecnicoProducao = new PafEcfArquivoTabelaIndiceTecnicoProducao(enumerable)
			{
				CaminhoDoArquivo = Path.Combine(AppDomain.CurrentDomain.BaseDirectory, "Fiscal"),
				ChavePrivada = Hash.RetornarChavePrivadaInformacaoDecifrada()
			};
			pafEcfArquivoTabelaIndiceTecnicoProducao.Salvar();
