	public class PainelParcelamento : PainelInteracao<PainelParcelamento>, IPainelIndicaConsumidor
	{
		private readonly List<ContaViewModel> _contas;

		private bool _parcelamentoConfirmado;

		private decimal _valorParcelamento;

		private bool _vencimentoParaDiaSeguinte;

		private readonly ItemInteracaoComboBoxFocusable _comboBoxFormasPagamento;

		private ItemInteracaoFormaPagamento _formaPagamentoPessoa;

		private ItemInteracaoTextBlockDescricaoValorMesmaLinha _nome;

		private ItemInteracaoTextBlockDescricaoValorMesmaLinha _limite;

		private ItemInteracaoTextBlockDescricaoValorMesmaLinha _saldoLimite;

		private ItemInteracaoTextBlockDescricaoValorMesmaLinha _diaAcerto;

		private ItemInteracaoListaPessoaAutorizada _pessoasAutorizadas;

		public ItemInteracaoListaParcelamento Parcelas => Campos.FirstOrDefault((IItemInteracao x) => x is ItemInteracaoListaParcelamento) as ItemInteracaoListaParcelamento;

		public bool Confirmado => _parcelamentoConfirmado;

		public ConsumidorLocal Consumidor => Seletor.Get<PainelTotalizacaoEmissorBase>().Consumidor;

		public override string Titulo => "Parcelamento";

		public PainelParcelamento()
		{
		}

		public PainelParcelamento(IRepositoryRead<DigisatServer.Domain.Main.Aggregates.FinanceirosAgg.FormasPagamento.FormaPagamento> formaPagamentoRepositoryRead, IRepositoryRead<DigisatServer.Domain.Main.Aggregates.FinanceirosAgg.Contas.Conta> contaRepositoryRead, Seletor<IPainel> seletor)
			: base(seletor)
		{
			Lista<IItemInteracao> lista = new Lista<IItemInteracao>();
			if (DadosSistema.VerificarPermissao<DigisatServer.Infrastructure.Crosscutting.Module.PontoDeVenda, PermitirInformarFormaPagamentoManual>())
			{
				FormaPagamento formaPagamento = new FormaPagamento
				{
					Descricao = "Nenhuma",
					DiasIntervalo = 30,
					DiasPrimeira = 30,
					QuantidadeParcelas = 1
				};
				ItemInteracaoFormaPagamentoNenhuma item = ItemInteracaoBase<ItemInteracaoFormaPagamentoNenhuma, FormaPagamento>.Criar().ComDescricao("Número de parcelas").ComValor(formaPagamento)
					.Build();
				formaPagamento.WhenPropertyChanged.Throttle(TimeSpan.FromMilliseconds(200.0)).SubscribeOn((SynchronizationContext)new DispatcherSynchronizationContext()).Subscribe(AdicionarParcelas);
				Lista<IItemInteracao> lista2 = new Lista<IItemInteracao>();
				lista2.Adicionar(item);
				ItemInteracaoComboBox item2 = ItemInteracaoBase<ItemInteracaoComboBox, Lista<IItemInteracao>>.Criar().ComDescricao("Nenhuma").ComValor(lista2)
					.Build();
				lista.Adicionar(item2);
				FormaPagamento formaPagamento2 = new FormaPagamento
				{
					Descricao = "Personalizada",
					Personalizada = true,
					PrimeiroVencimento = DateTime.Today,
					DiasIntervalo = 30,
					QuantidadeParcelas = 1
				};
				ItemInteracaoFormaPagamentoPersonalizada item3 = ItemInteracaoBase<ItemInteracaoFormaPagamentoPersonalizada, FormaPagamento>.Criar().ComDescricao("Primeiro vencimento").ComValor(formaPagamento2)
					.Build();
				formaPagamento2.WhenPropertyChanged.Throttle(TimeSpan.FromMilliseconds(200.0)).SubscribeOn((SynchronizationContext)new DispatcherSynchronizationContext()).Subscribe(AdicionarParcelas);
				Lista<IItemInteracao> lista3 = new Lista<IItemInteracao>();
				lista3.Adicionar(item3);
				ItemInteracaoComboBox item4 = ItemInteracaoBase<ItemInteracaoComboBox, Lista<IItemInteracao>>.Criar().ComDescricao("Personalizada").ComValor(lista3)
					.Build();
				lista.Adicionar(item4);
			}
			IOrderedEnumerable<DigisatServer.Domain.Main.Aggregates.FinanceirosAgg.FormasPagamento.FormaPagamento> source = from x in formaPagamentoRepositoryRead.Find(EntitySpecification<DigisatServer.Domain.Main.Aggregates.FinanceirosAgg.FormasPagamento.FormaPagamento>.Ativo())
				orderby x.Descricao
				select x;
			lista.Adicionar(from x in source
				where x is MesReferenciaPrimeiraParcela || x.To<IFormaPagamentoDiasPrimeiroVencimento>().DiasPrimeiraParcela > 0
				select ItemInteracaoBase<ItemInteracaoFormaPagamento, FormaPagamento>.Criar().ComDescricao(x.Descricao).ComValor(new FormaPagamento
				{
					Id = x.Id,
					Descricao = x.Descricao,
					DiasIntervalo = x.DiasIntervalo,
					DiasPrimeira = (x.To<IFormaPagamentoDiasPrimeiroVencimento>()?.DiasPrimeiraParcela ?? 0),
					MesPrimeiroVencimento = (x.To<MesReferenciaPrimeiraParcela>()?.MesPrimeiroVencimento ?? 0),
					DiaPrimeiroVencimento = (x.To<MesReferenciaPrimeiraParcela>()?.DiaPrimeiroVencimento ?? 0),
					QuantidadeParcelas = x.QuantidadeParcela,
					TaxaJuro = x.TaxaJuro,
					Intervalo = x.To<DiasDinamicosReferenciaPrimeiraParcela>()?.Intervalo
				})
					.Build());
			_comboBoxFormasPagamento = ItemInteracaoBase<ItemInteracaoComboBoxFocusable, Lista<IItemInteracao>>.Criar().ComDescricao("Formas de pagamento").ComValor(lista)
				.Build();
			lista.WhenAlterouItemSelecionado.Throttle(TimeSpan.FromMilliseconds(200.0)).DistinctUntilChanged().SubscribeOn((SynchronizationContext)new DispatcherSynchronizationContext())
				.Subscribe((IItemInteracao x) =>
				{
					if (x is ItemInteracaoFormaPagamento itemInteracaoFormaPagamento)
					{
						AdicionarParcelas(itemInteracaoFormaPagamento.Valor);
					}
					else
					{
						IItemInteracao itemInteracao = (x as ItemInteracaoComboBox)?.Valor.ItemSelecionado;
						FormaPagamento formaPagamento3 = (itemInteracao as ItemInteracaoFormaPagamentoNenhuma)?.Valor ?? (itemInteracao as ItemInteracaoFormaPagamentoPersonalizada)?.Valor;
						if (formaPagamento3 != null)
						{
							AdicionarParcelas(formaPagamento3);
						}
					}
				});
			Campos.Add(_comboBoxFormasPagamento);
			IEnumerable<DigisatServer.Domain.Main.Aggregates.FinanceirosAgg.Contas.Conta> source2 = contaRepositoryRead.Find(EntitySpecification<DigisatServer.Domain.Main.Aggregates.FinanceirosAgg.Contas.Conta>.Ativo());
			_contas = new List<ContaViewModel>(source2.Select((DigisatServer.Domain.Main.Aggregates.FinanceirosAgg.Contas.Conta x) => ContaViewModel.Criar().ComConta(x)));
		}

		protected void AdicionarParcelas(FormaPagamento item)
		{
			RemoverParcelas();
			DigisatServer.Domain.Main.Aggregates.CadastrosAgg.RelacoesEspecieConta.RelacaoEspecieConta relacaoEspecieConta = Seletor.Get<PainelDocumentoFiscal>().PreDocumentoFiscal.ObterRelacaoEspecieConta(3, string.Empty);
			DigisatServer.Domain.Main.Aggregates.FinanceirosAgg.Contas.Conta conta = ObterContaDoCliente()?.Conta ?? relacaoEspecieConta.Conta;
			Lista<Parcela> lista = new Lista<Parcela>();
			DateTime vencimento = ObterPrimeiroVencimento(item);
			if (item.MesPrimeiroVencimento > 0)
			{
				int num = DateTime.Today.Year;
				if (DateTime.Today.Month > item.MesPrimeiroVencimento)
				{
					num++;
				}
				vencimento = (DadosSistema.ConfiguracaoDto.Financeiro.EvitarVencimentosEmFinaisDeSemanaAoGerarParcelamento.Valor ? HelperDateTime.ObterDataEmDiaUtil(new DateTime(num, item.MesPrimeiroVencimento, item.DiaPrimeiroVencimento)) : new DateTime(num, item.MesPrimeiroVencimento, item.DiaPrimeiroVencimento));
			}
			long[] array = Referencia.GerarSequencia(item.QuantidadeParcelas).ToArray();
			for (int i = 1; i <= item.QuantidadeParcelas; i++)
			{
				Parcela parcela = Parcela.Criar().ComOrdem(i).ComVencimento(RetornarDataVencimento(ref vencimento, i, item))
					.ComEspecie(new Dinheiro())
					.ComContas(_contas)
					.ComContaRelacionada(conta)
					.ComValor((_valorParcelamento / (decimal)item.QuantidadeParcelas).ArredondarParaDuasCasasDecimais())
					.ComReferencia(array[i - 1])
					.ComTaxaJuro(item.TaxaJuro)
					.Build();
				parcela.WhenPropertyChanged.Subscribe((EventPattern<PropertyChangedEventArgs> x) =>
				{
					switch (x.EventArgs.PropertyName)
					{
					case "ContaSelecionada":
					{
						foreach (Parcela item2 in Parcelas.Valor.Itens.Where((Parcela a) => a.Ordem > parcela.Ordem).ToListEmptyWhenNull())
						{
							item2.ContaSelecionada = parcela.ContaSelecionada;
						}
						break;
					}
					case "Vencimento":
						ReajustarDiaVencimentoParcelaOrdemMaior(parcela);
						break;
					case "Valor":
						ReajustarValorParcelaOrdemMaior(parcela);
						break;
					}
				});
				lista.Adicionar(parcela);
			}
			Parcela parcela2 = lista.Itens.FirstOrDefault();
			if (parcela2 != null)
			{
				parcela2.Valor += _valorParcelamento - lista.Itens.Sum((Parcela x) => x.Valor);
			}
			Campos.Add(ItemInteracaoBase<ItemInteracaoListaParcelamento, Lista<Parcela>>.Criar().ComDescricao("Parcelas").ComValor(lista)
				.ComValorParcelamento(_valorParcelamento)
				.Build());
		}

		private ContaViewModel ObterContaDoCliente()
		{
			ObjectId contaReferencia = Seletor.Get<PainelDocumentoFiscal>()?.Consumidor?.Pessoa?.Cliente?.ContaReferencia ?? ObjectId.Empty;
			if (!contaReferencia.IsDefaultOrEmpty())
			{
				return _contas.FirstOrDefault((ContaViewModel x) => x.Id.Equals(contaReferencia));
			}
			return null;
		}

		private DateTime ObterPrimeiroVencimento(FormaPagamento formaPagamento)
		{
			if (formaPagamento.IsNotNull() && formaPagamento.Personalizada)
			{
				if (!(formaPagamento.PrimeiroVencimento == DateTime.MinValue))
				{
					return formaPagamento.PrimeiroVencimento.Date;
				}
				return DateTime.Today;
			}
			if (formaPagamento.IsNotNull())
			{
				IList<int> intervalo = formaPagamento.Intervalo;
				if (intervalo != null && intervalo.Any())
				{
					return DateTime.Now.AddDays(formaPagamento.Intervalo.FirstOrDefault().ToInt());
				}
			}
			if (formaPagamento.IsNull() || !formaPagamento.Is<MesReferenciaPrimeiraParcela>())
			{
				return DateTime.Today;
			}
			int num = DateTime.Today.Year;
			if (DateTime.Today.Month > formaPagamento.MesPrimeiroVencimento)
			{
				num++;
			}
			if (!DadosSistema.ConfiguracaoDto.Financeiro.EvitarVencimentosEmFinaisDeSemanaAoGerarParcelamento.Valor)
			{
				return new DateTime(num, formaPagamento.MesPrimeiroVencimento, formaPagamento.DiaPrimeiroVencimento);
			}
			return HelperDateTime.ObterDataEmDiaUtil(new DateTime(num, formaPagamento.MesPrimeiroVencimento, formaPagamento.DiaPrimeiroVencimento));
		}

		public void SetarValorParcelamento(decimal valor)
		{
			_valorParcelamento = valor;
		}

		public void SetarVencimentoParaDiaSeguinte()
		{
			_vencimentoParaDiaSeguinte = true;
		}

		public void SetarFormaPagamento(ObjectId formaPagamentoReferencia)
		{
			if (!formaPagamentoReferencia.ToString().IsObjectIdDefaultOrEmpty())
			{
				_formaPagamentoPessoa = _comboBoxFormasPagamento.Valor.Itens.OfType<ItemInteracaoFormaPagamento>().FirstOrDefault((ItemInteracaoFormaPagamento x) => x.Valor.Id == formaPagamentoReferencia);
			}
		}

		private void RemoverParcelas()
		{
			if (Parcelas != null)
			{
				Parcelas.Dispose();
				Campos.Remove(Parcelas);
			}
		}

		private void ReajustarDiaVencimentoParcelaOrdemMaior(Parcela parcela)
		{
			if (Parcelas == null)
			{
				return;
			}
			if (parcela.Vencimento == DateTime.Today)
			{
				parcela.Vencimento = DateTime.Today.AddDays(1.0);
			}
			foreach (Parcela item in Parcelas.Valor.Itens.Where((Parcela a) => a.Ordem > parcela.Ordem).ToListEmptyWhenNull())
			{
				DateTime vencimento;
				if (parcela.Vencimento.Day > 28 && item.Vencimento.Month == 2)
				{
					vencimento = new DateTime(item.Vencimento.Year, item.Vencimento.Month, 28);
				}
				else
				{
					vencimento = ((parcela.Vencimento.Day <= 30) ? new DateTime(item.Vencimento.Year, item.Vencimento.Month, parcela.Vencimento.Day) : new DateTime(item.Vencimento.Year, item.Vencimento.Month, 30));
				}
				item.Vencimento = vencimento;
			}
		}

		private void ReajustarValorParcelaOrdemMaior(Parcela parcela)
		{
			if (Parcelas == null || Parcelas.Diferenca == 0m)
			{
				return;
			}
			List<Parcela> list = Parcelas.Valor.Itens.Where((Parcela a) => a.Ordem > parcela?.Ordem).ToListEmptyWhenNull();
			decimal num = Parcelas.Valor.Itens.Where((Parcela a) => a.Ordem <= parcela?.Ordem).ToListEmptyWhenNull().Sum((Parcela a) => a.Valor);
			foreach (Parcela item in list)
			{
				item.Valor = ((Parcelas.ValorParcelamento - num) / (decimal)list.Count).ArredondarParaDuasCasasDecimais();
				if (item.Ordem == list.LastOrDefault()?.Ordem)
				{
					item.Valor += Parcelas.Diferenca;
				}
			}
		}

		private DateTime RetornarDataVencimento(ref DateTime vencimento, int ordemParcela, FormaPagamento item)
		{
			if (_vencimentoParaDiaSeguinte)
			{
				return DateTime.Now.AddDays(1.0);
			}
			if (item != null && item.Personalizada)
			{
				if (ordemParcela == 1)
				{
					return vencimento;
				}
				vencimento = (item.FixarDiaVencimento ? vencimento.AddMonths(1) : vencimento.AddDays(item.DiasIntervalo));
				if (!DadosSistema.ConfiguracaoDto.Financeiro.EvitarVencimentosEmFinaisDeSemanaAoGerarParcelamento.Valor)
				{
					return vencimento;
				}
				return HelperDateTime.ObterDataEmDiaUtil(vencimento);
			}
			if (item?.Intervalo?.Any() ?? false)
			{
				if (ordemParcela == 1)
				{
					if (!DadosSistema.ConfiguracaoDto.Financeiro.EvitarVencimentosEmFinaisDeSemanaAoGerarParcelamento.Valor)
					{
						return vencimento;
					}
					return HelperDateTime.ObterDataEmDiaUtil(vencimento);
				}
				int num = item.Intervalo.ElementAt(ordemParcela - 1);
				if (!DadosSistema.ConfiguracaoDto.Financeiro.EvitarVencimentosEmFinaisDeSemanaAoGerarParcelamento.Valor)
				{
					return DateTime.Now.AddDays(num.ToInt());
				}
				return HelperDateTime.ObterDataEmDiaUtil(DateTime.Now.AddDays(num.ToInt()));
			}
			int num2 = Consumidor?.DiaAcerto ?? 0;
			int diasPrimeira = item.DiasPrimeira;
			int diasIntervalo = item.DiasIntervalo;
			int mesPrimeiroVencimento = item.MesPrimeiroVencimento;
			if (ordemParcela == 1 && diasPrimeira == 0)
			{
				return vencimento;
			}
			DateTime vencimentoAnterior = vencimento;
			vencimento = vencimento.AddDays((ordemParcela == 1) ? diasPrimeira : diasIntervalo);
			if (num2 == 0)
			{
				if (!DadosSistema.ConfiguracaoDto.Financeiro.EvitarVencimentosEmFinaisDeSemanaAoGerarParcelamento.Valor)
				{
					return vencimento;
				}
				return HelperDateTime.ObterDataEmDiaUtil(vencimento);
			}
			if (ordemParcela == 1 && mesPrimeiroVencimento == 0 && diasIntervalo == 0)
			{
				vencimento = vencimento.AddMonths(1);
			}
			vencimento = HelperDateTime.ObterVencimentoNoDiaAcerto(vencimento, num2, vencimentoAnterior);
			if (!DadosSistema.ConfiguracaoDto.Financeiro.EvitarVencimentosEmFinaisDeSemanaAoGerarParcelamento.Valor)
			{
				return vencimento;
			}
			return HelperDateTime.ObterDataEmDiaUtil(vencimento);
		}

		public override void Load()
		{
			_parcelamentoConfirmado = false;
			if (!(Campos.FirstOrDefault((IItemInteracao a) => a is ItemInteracaoComboBoxFocusable) is ItemInteracaoComboBoxFocusable itemInteracaoComboBoxFocusable) || itemInteracaoComboBoxFocusable.Valor.Itens.Count == 0)
			{
				DialogoFactory.MostrarDialogoConfirma("Usuário não pode informar quantidade de parcelas manualmente e nenhuma forma de pagamento foi localizada");
				Seletor.Voltar();
				return;
			}
			_nome = ItemInteracaoBase<ItemInteracaoTextBlockDescricaoValorMesmaLinha, string>.Criar().ComDescricao("Pessoa:").ComValor(Consumidor?.Nome)
				.Build();
			Campos.Insert(0, _nome);
			_limite = ItemInteracaoBase<ItemInteracaoTextBlockDescricaoValorMesmaLinha, string>.Criar().ComDescricao("Limite:").ComValor(Consumidor?.LimiteDeCredito.FormatarCampoValor(2))
				.Build();
			Campos.Insert(1, _limite);
			_saldoLimite = ItemInteracaoBase<ItemInteracaoTextBlockDescricaoValorMesmaLinha, string>.Criar().ComDescricao("Saldo limite:").ComValor(Consumidor?.SaldoLimiteDeCredito.FormatarCampoValor(2))
				.Build();
			Campos.Insert(2, _saldoLimite);
			_diaAcerto = ItemInteracaoBase<ItemInteracaoTextBlockDescricaoValorMesmaLinha, string>.Criar().ComDescricao("Dia de acerto:").ComValor(Consumidor?.DiaAcerto.ToString())
				.Build();
			Campos.Insert(3, _diaAcerto);
			if (Consumidor != null && Consumidor.Pessoa.IsFisica && Consumidor.Pessoa.To<Fisica>().PessoasAutorizadas.IsNotNull() && Consumidor.Pessoa.To<Fisica>().PessoasAutorizadas.Any())
			{
				_pessoasAutorizadas = ItemInteracaoBase<ItemInteracaoListaPessoaAutorizada, Lista<ItemPessoaAutorizada>>.Criar().ComDescricao("Pessoas autorizadas:").ComValor(new Lista<ItemPessoaAutorizada>(Consumidor?.Pessoa?.To<Fisica>().PessoasAutorizadas.Select((string x) => ItemPessoaAutorizada.Criar().ComNome(x))))
					.Build();
				Campos.Insert(4, _pessoasAutorizadas);
			}
			if (_formaPagamentoPessoa.IsNotNull())
			{
				itemInteracaoComboBoxFocusable.Valor.Posicionar((IItemInteracao x) => x == _formaPagamentoPessoa);
			}
			else
			{
				itemInteracaoComboBoxFocusable.Valor.PosicionarNoPrimeiro();
			}
			itemInteracaoComboBoxFocusable.Valor.ItemSelecionado.ToDo((ItemInteracaoComboBox itemComboBox) =>
			{
				if (itemComboBox.Valor.ItemSelecionado is ItemInteracaoFormaPagamentoNenhuma itemInteracaoFormaPagamentoNenhuma)
				{
					itemInteracaoFormaPagamentoNenhuma.Valor.QuantidadeParcelas = 1;
					AdicionarParcelas(itemInteracaoFormaPagamentoNenhuma.Valor);
				}
				else if (itemComboBox.Valor.ItemSelecionado is ItemInteracaoFormaPagamentoPersonalizada itemInteracaoFormaPagamentoPersonalizada)
				{
					AdicionarParcelas(itemInteracaoFormaPagamentoPersonalizada.Valor);
				}
			});
			itemInteracaoComboBoxFocusable.Valor.ItemSelecionado.ToDo((ItemInteracaoFormaPagamento item) =>
			{
				AdicionarParcelas(item.Valor);
			});
		}

		public override void UnLoad()
		{
			if (!_parcelamentoConfirmado)
			{
				RemoverParcelas();
			}
			_formaPagamentoPessoa = null;
			_vencimentoParaDiaSeguinte = false;
			Campos.RemoveIfExists(_nome);
			Campos.RemoveIfExists(_limite);
			Campos.RemoveIfExists(_saldoLimite);
			Campos.RemoveIfExists(_diaAcerto);
			Campos.RemoveIfExists(_pessoasAutorizadas);
		}

		public override bool PodeVoltar()
		{
			return true;
		}

		public override void Dispose()
		{
		}

		protected override void F2Method()
		{
			if (!(Campos.FirstOrDefault((IItemInteracao a) => a is ItemInteracaoListaParcelamento) is ItemInteracaoListaParcelamento itemInteracaoListaParcelamento) || !itemInteracaoListaParcelamento.Valor.PossuiItemSelecionado || !itemInteracaoListaParcelamento.Valor.Itens.All((Parcela x) => x.Valor > 0m))
			{
				return;
			}
			string observacao;
			if ((!(_pessoasAutorizadas?.Valor?.Itens?.Any((ItemPessoaAutorizada x) => x.Selecionado))) ?? true)
			{
				observacao = string.Empty;
			}
			else
			{
				observacao = ((_pessoasAutorizadas.Valor.Itens.Count((ItemPessoaAutorizada x) => x.Selecionado) == 1) ? string.Format("Pessoa autorizada que efetuou a compra: {0}", string.Join("; ", from y in _pessoasAutorizadas.Valor.Itens
					where y.Selecionado
					select y.Nome)) : string.Format("Pessoas autorizadas que efetuaram a compra: {0}", string.Join("; ", from y in _pessoasAutorizadas.Valor.Itens
					where y.Selecionado
					select y.Nome)));
			}
			foreach (Parcela iten in Parcelas.Valor.Itens)
			{
				iten.ComObservacao(observacao);
			}
			_parcelamentoConfirmado = true;
			Seletor.Voltar();
		}

		protected override bool CanF2Method()
		{
			if (Parcelas != null && Parcelas.Valor.Itens.Any() && Parcelas.Diferenca == 0m)
			{
				return !Parcelas.Valor.Itens.Any((Parcela x) => x.Vencimento.Date < DateTime.Now.Date);
			}
			return false;
		}

		public void IndicarConsumidor(ConsumidorLocal consumidor)
		{
			Seletor.Get<PainelDocumentoFiscal>().IndicarConsumidor(consumidor);
		}
	}
	public class PainelPromocaoScanntechMeioPagamento : PainelInteracao<PainelPromocaoScanntechMeioPagamento>
	{
		protected readonly IWService _service;

		protected readonly IEventPublisher _eventPublisher;

		protected Lista<IItemInteracao> _meiosPagamento;

		protected ItemInteracaoTextoLimitado _bin;

		protected IEnumerable<string> _descricaoMeiosPagamento;

		private IEnumerable<Otus.Modulo.PontoDeVendas.Aggregates.Scanntech.PromocaoScanntech> _promocoesScanntechMeioPagamento;

		private ItemInteracaoComboBoxFocusable _comboBoxMeioPagamento;

		public override string Titulo => string.Empty;

		public Action CallBack { get; protected set; }

		public PainelPromocaoScanntechMeioPagamento()
		{
		}

		public PainelPromocaoScanntechMeioPagamento(IWService service, IEventPublisher eventPublisher, Seletor<IPainel> seletorDireito)
			: base(seletorDireito)
		{
			_service = service;
			_eventPublisher = eventPublisher;
		}

		public override void Load()
		{
			_meiosPagamento?.Limpar();
			_bin?.Limpar();
			Campos.Clear();
			try
			{
				_meiosPagamento = new Lista<IItemInteracao>();
				foreach (string item2 in _descricaoMeiosPagamento)
				{
					ItemInteracaoTexto item = ItemInteracaoBase<ItemInteracaoTexto, string>.Criar().ComDescricao(item2).ComValor(item2)
						.Build();
					_meiosPagamento.Adicionar(item);
				}
				_comboBoxMeioPagamento = ItemInteracaoBase<ItemInteracaoComboBoxFocusable, Lista<IItemInteracao>>.Criar().ComDescricao("Cartão").ComValor(_meiosPagamento)
					.Build();
				Campos.Add(_comboBoxMeioPagamento);
				_bin = ItemInteracaoBase<ItemInteracaoTextoLimitado, string>.Criar().ComDescricao("6 primeiros dígitos do cartão").ComLimiteCaracteres(6)
					.ComValor(string.Empty)
					.Build();
				Campos.Add(_bin);
			}
			catch (Exception ex)
			{
				ex.ShowLastException();
				Seletor.Voltar();
			}
		}

		public override void UnLoad()
		{
		}

		public override bool PodeVoltar()
		{
			return true;
		}

		public override bool CanEnterMethod()
		{
			if (_meiosPagamento.IsNotNull())
			{
				return _bin.IsNotNull();
			}
			return false;
		}

		public override void Dispose()
		{
		}

		public override void FecharMethod()
		{
			base.FecharMethod();
			Seletor.Voltar();
			CallBack();
		}

		protected override void F2Method()
		{
		}

		protected override bool CanF2Method()
		{
			return false;
		}

		public override void EnterMethod()
		{
			if (_bin.Valor.IsNullOrEmpty() || _bin.Valor.Length != 6)
			{
				DialogoFactory.MostrarDialogoConfirma("Informe os 6 primeiros dígitos do cartão");
				return;
			}
			IList<Otus.Modulo.PontoDeVendas.Aggregates.Scanntech.PromocaoScanntech> list = new List<Otus.Modulo.PontoDeVendas.Aggregates.Scanntech.PromocaoScanntech>();
			foreach (Otus.Modulo.PontoDeVendas.Aggregates.Scanntech.PromocaoScanntech item in _promocoesScanntechMeioPagamento.Where((Otus.Modulo.PontoDeVendas.Aggregates.Scanntech.PromocaoScanntech x) => x.Detalhe.Condicao.FormasPagamento.Any((Otus.Modulo.PontoDeVendas.Aggregates.Scanntech.FormaPagamento y) => y.Descricao.Equals(_comboBoxMeioPagamento.Valor.ItemSelecionado.To<ItemInteracaoTexto>().Descricao))))
			{
				foreach (Otus.Modulo.PontoDeVendas.Aggregates.Scanntech.FormaPagamento item2 in item.Detalhe.Condicao.FormasPagamento.Where((Otus.Modulo.PontoDeVendas.Aggregates.Scanntech.FormaPagamento x) => x.Descricao.Equals(_comboBoxMeioPagamento.Valor.ItemSelecionado.To<ItemInteracaoTexto>().Descricao)))
				{
					if (item2.Bins.Any((string y) => y.Equals(_bin.Valor)))
					{
						list.Add(item);
					}
				}
			}
			if (list.Any())
			{
				Seletor.Get<PainelTotalizacaoBase>().SetarMeioPagamentoElegivelParaPromocao(list);
				Seletor.Get<PainelTotalizacaoBase>().SetarBinInformado(_bin.Valor);
				Seletor.Get<PainelTotalizacaoBase>().SetarDebito(list.All((Otus.Modulo.PontoDeVendas.Aggregates.Scanntech.PromocaoScanntech x) => x.Detalhe.Condicao.FormasPagamento.Where((Otus.Modulo.PontoDeVendas.Aggregates.Scanntech.FormaPagamento y) => y.Descricao.Equals(_comboBoxMeioPagamento.Valor.ItemSelecionado.To<ItemInteracaoTexto>().Descricao)).All((Otus.Modulo.PontoDeVendas.Aggregates.Scanntech.FormaPagamento y) => y.CodigoTipoPagamento.Equals("13"))));
			}
			else
			{
				DialogoFactory.MostrarDialogoConfirma("Cartão não elegível para aplicação da promoção Scanntech");
				Seletor.Get<PainelTotalizacaoBase>().SetarMeioPagamentoElegivelParaPromocao(null);
				Seletor.Get<PainelTotalizacaoBase>().SetarBinInformado(null);
				Seletor.Get<PainelTotalizacaoBase>().SetarDebito(debito: false);
			}
			Seletor.Voltar();
			CallBack();
		}

		public void SetarPromocoesScanntechMeioPagamento(IEnumerable<Otus.Modulo.PontoDeVendas.Aggregates.Scanntech.PromocaoScanntech> promocoesScanntechMeioPagamento)
		{
			_promocoesScanntechMeioPagamento = promocoesScanntechMeioPagamento;
			List<string> descricaoMeiosPagamento = promocoesScanntechMeioPagamento.Where((Otus.Modulo.PontoDeVendas.Aggregates.Scanntech.PromocaoScanntech x) => x.Detalhe.Condicao.FormasPagamento.IsNotNull()).SelectMany((Otus.Modulo.PontoDeVendas.Aggregates.Scanntech.PromocaoScanntech x) => x.Detalhe?.Condicao?.FormasPagamento?.Select((Otus.Modulo.PontoDeVendas.Aggregates.Scanntech.FormaPagamento y) => y.Descricao)).Distinct()
				.ToListEmptyWhenNull();
			_descricaoMeiosPagamento = descricaoMeiosPagamento;
		}

		public void SetarCallBack(Action callBack)
		{
			CallBack = callBack;
		}
	}
	public class PainelQuebraContinuidadeEncerrante : PainelInteracao<PainelQuebraContinuidadeEncerrante>
	{
		private readonly IWService _service;

		private readonly IEventPublisher _eventPublisher;

		private ItemInteracaoComboBoxFocusable _comboBox;

		public override string Titulo => "Quebra da continuidade do encerrante";

		public PainelQuebraContinuidadeEncerrante()
		{
		}

		public PainelQuebraContinuidadeEncerrante(IWService service, IEventPublisher eventPublisher, Seletor<IPainel> seletor)
			: base(seletor)
		{
			_service = service;
			_eventPublisher = eventPublisher;
		}

		private IEnumerable<LacreBombaDto> ObterLacresBomba(int numeroBomba)
		{
			return _service.Canal((ITanqueModuleService x) => x.ObterLacresBomba(numeroBomba));
		}

		private ItemInteracaoComboBox CriarComboBox(IQuebraContinuidadeEncerrante quebraContinuidadeEncerrante)
		{
			Lista<IItemInteracao> lista = new Lista<IItemInteracao>();
			lista.Adicionar(quebraContinuidadeEncerrante);
			return ItemInteracaoBase<ItemInteracaoComboBox, Lista<IItemInteracao>>.Criar().ComValor(lista).ComDescricao(quebraContinuidadeEncerrante.Descricao)
				.Build();
		}

		public void SetarQuebraContinuidadeEncerrante(QuebraContinuidadeEncerranteResponse quebraContinuidadeEncerranteResponse)
		{
			Lista<IItemInteracao> lista = new Lista<IItemInteracao>();
			if (quebraContinuidadeEncerranteResponse.MotivoDescontinuidade == MotivoDescontinuidade.ViradaDeMilhao)
			{
				lista.Adicionar(CriarComboBox(ItemInteracaoBase<DescontinuidadeEncerranteItemInteracao, QuebraContinuidadeEncerranteResponse>.Criar().ComValor(quebraContinuidadeEncerranteResponse).Build()));
			}
			else if (quebraContinuidadeEncerranteResponse.TotalLitros < 0m)
			{
				lista.Adicionar(CriarComboBox(ItemInteracaoBase<DescontinuidadeEncerranteItemInteracao, QuebraContinuidadeEncerranteResponse>.Criar().ComLacres(ObterLacresBomba(quebraContinuidadeEncerranteResponse.NumeroBomba)).ComValor(quebraContinuidadeEncerranteResponse)
					.Build()));
			}
			else
			{
				lista.Adicionar(CriarComboBox(ItemInteracaoBase<AbastecimentoValidoItemInteracao, QuebraContinuidadeEncerranteResponse>.Criar().ComValor(quebraContinuidadeEncerranteResponse).Build()));
				if (DadosSistema.IsPaf)
				{
					lista.Adicionar(CriarComboBox(ItemInteracaoBase<NotaManualItemInteracao, QuebraContinuidadeEncerranteResponse>.Criar().ComValor(quebraContinuidadeEncerranteResponse).Build()));
				}
				lista.Adicionar(CriarComboBox(ItemInteracaoBase<DescontinuidadeEncerranteItemInteracao, QuebraContinuidadeEncerranteResponse>.Criar().ComLacres(ObterLacresBomba(quebraContinuidadeEncerranteResponse.NumeroBomba)).ComValor(quebraContinuidadeEncerranteResponse)
					.Build()));
			}
			_comboBox = ItemInteracaoBase<ItemInteracaoComboBoxFocusable, Lista<IItemInteracao>>.Criar().ComDescricao("Informe a ação a ser realizada").ComValor(lista)
				.Build();
			Campos.Add(_comboBox);
		}

		protected override void F2Method()
		{
			IQuebraContinuidadeEncerrante quebraContinuidadeEncerrante = _comboBox.Valor.ItemSelecionado.To<ItemInteracaoComboBox>().Valor.ItemSelecionado.To<IQuebraContinuidadeEncerrante>();
			quebraContinuidadeEncerrante.Confirmar(_service, _eventPublisher);
			if (quebraContinuidadeEncerrante.QuebraContinuidadeEncerrante.TotalLitros > 0m)
			{
				foreach (IItemInteracao iten in _comboBox.Valor.Itens)
				{
					iten.Limpar();
				}
				_comboBox.Valor.PosicionarNoPrimeiro();
			}
			else
			{
				_eventPublisher.Publish(new RemoverQuebraContinuidadeEncerranteRequest(quebraContinuidadeEncerrante.QuebraContinuidadeEncerrante.EmpresaReferencia, quebraContinuidadeEncerrante.QuebraContinuidadeEncerrante.IdBico));
				Seletor.Voltar();
				Seletor.Get<PainelDocumentoFiscal>().Informacao.ControlarFoco();
			}
		}

		public override void Load()
		{
			DescontinuidadeEncerranteItemInteracao descontinuidadeEncerranteItemInteracao = _comboBox.Valor.ItemSelecionado.To<ItemInteracaoComboBox>().Valor.ItemSelecionado as DescontinuidadeEncerranteItemInteracao;
			if (_comboBox.Valor.Numero == 1 && descontinuidadeEncerranteItemInteracao.IsNotNull() && DadosSistema.IsPaf && descontinuidadeEncerranteItemInteracao.QuebraContinuidadeEncerrante.MotivoDescontinuidade != MotivoDescontinuidade.ViradaDeMilhao)
			{
				EmitirCuponsAbastecimentosPendentes(descontinuidadeEncerranteItemInteracao.NumeroBico);
				return;
			}
			_comboBox.Valor.WhenAlterouItemSelecionado.Where((IItemInteracao x) => x.To<ItemInteracaoComboBox>().Valor.ItemSelecionado is DescontinuidadeEncerranteItemInteracao && DadosSistema.IsPaf).Subscribe((IItemInteracao x) =>
			{
				if (DialogoFactory.MostrarDialogoSimNao("Emitir os cupons pendentes e registrar descontinuidade de encerrante?", bloquearEnter: true) == MessageBoxResult.Yes)
				{
					EmitirCuponsAbastecimentosPendentes(x.To<ItemInteracaoComboBox>().Valor.ItemSelecionado.To<DescontinuidadeEncerranteItemInteracao>().NumeroBico);
				}
				else
				{
					DormirAsync(200, (object o) =>
					{
						_comboBox.Valor.PosicionarNoPrimeiro();
					});
				}
			});
		}

		private void EmitirCuponsAbastecimentosPendentes(int numeroBico)
		{
			_eventPublisher.Publish(new AntesRegistrarDescontinuidadeEncerrante(numeroBico));
		}

		public override void UnLoad()
		{
			Campos.Clear();
		}

		public override bool PodeVoltar()
		{
			return false;
		}

		public override void Dispose()
		{
		}
	}
	public class AntesRegistrarDescontinuidadeEncerrante
	{
		public int NumeroBico { get; }

		public AntesRegistrarDescontinuidadeEncerrante(int numeroBico)
		{
			NumeroBico = numeroBico;
		}
	}
	public class PainelRecebimento : PainelInteracao<PainelRecebimento>, IItemMenuRibbon, ITitulo
	{
