		private ItemInteracaoButtonDecimal _valorDesconto;

		private ItemInteracaoButtonDecimal _valorAcrescimo;

		private InteracaoComando<decimal> _interacaoDesconto;

		private InteracaoComando<decimal> _interacaoAcrescimo;

		private ItemInteracaoListaRecebimentoQuitacao _campoListaParcelas;

		private IEnumerable<DigisatServer.Domain.Main.Aggregates.FinanceirosAgg.Contas.Conta> _contas;

		private IList<EspeciePagamentoDto> _especies;

