		private ConsumidorLocal _consumidor;

		private IDisposable _disposable;

		private bool _finalizadoEmCheque;

		private bool _finalizadoEmCarteiraDigital;

		private bool _finalizadoEmCarteiraDigitalTef;

		private bool _pagamentoViaTerminalPos;

		private decimal _valor;

		private decimal _desconto;

		private decimal _acrescimo;

		private DateTime _vencimento;

		private DigisatServer.Domain.Main.Aggregates.FinanceirosAgg.Contas.Conta _conta;

		private EspeciePagamentoDto _especie;

		private InformacaoTransacaoTef _informacaoTransacaoTef;

		private PagamentoTransacaoDto _pagamentoTransacaoDto;

		private InformacaoTransacaoCarteiraDigital _informacaoTransacaoCarteiraDigital;

		private TipoTef _tef;

		private readonly ISessaoService _sessaoService;

		public Otus.Modulo.PontoDeVendas.Interfaces.ITefService TefService { get; protected set; }

		private Lista<Otus.Modulo.PontoDeVendas.ViewModels.ItensInteracao.Recebimento> ListaParcelas
		{
			get
			{
				Lista<Otus.Modulo.PontoDeVendas.ViewModels.ItensInteracao.Recebimento> lista = new Lista<Otus.Modulo.PontoDeVendas.ViewModels.ItensInteracao.Recebimento>();
				lista.Adicionar((Seletor.Get<PainelBuscaRecebimento>().Campos.FirstOrDefault((IItemInteracao x) => x is ItemInteracaoListaRecebimento) as ItemInteracaoListaRecebimento)?.Valor.Itens.Where((Otus.Modulo.PontoDeVendas.ViewModels.ItensInteracao.Recebimento x) => x.Selecionado));
				return lista;
			}
		}

		private decimal TotalParcelas => ListaParcelas.Itens.Sum((Otus.Modulo.PontoDeVendas.ViewModels.ItensInteracao.Recebimento a) => a.RecebimentoDto.ValorTotal.ArredondarParaDuasCasasDecimais()) - (_valorDesconto?.Valor.Dado ?? 0m) + (_valorAcrescimo?.Valor.Dado ?? 0m);

		public override string DescricaoDoBotao => "Quitar";

		public ChequeDto Cheque { get; set; }

		public IWService Service { get; protected set; }

		public override string Titulo => "Recebimentos";

		public KeyGestureCustom Key => new KeyGestureControl(System.Windows.Input.Key.R);

		public string ToolTip => Titulo;

		public ICommand DCommand { get; set; }

		public ICommand TCommand { get; set; }

		public ICommand OCommand { get; set; }

		public ICommand QCommand { get; set; }

		public ICommand MCommand { get; set; }

		public ICommand XCommand { get; set; }

		public PainelRecebimento()
		{
		}

		public PainelRecebimento(IWService service, IEmissorService emissorService, IRepositoryRead<DigisatServer.Domain.Main.Aggregates.FinanceirosAgg.Contas.Conta> contaRepositoryRead, Seletor<IPainel> seletor, Otus.Modulo.PontoDeVendas.Interfaces.ITefService tefService, IConfiguracaoClientService configuracaoClientService, ISessaoService sessaoService)
			: base(seletor)
		{
			_emissorService = emissorService;
			_contaRepositoryRead = contaRepositoryRead;
			_seletor = seletor;
			_configuracaoClientService = configuracaoClientService;
			_sessaoService = sessaoService;
			Service = service;
			TefService = tefService;
		}

		protected override void Limpar()
		{
			for (int i = 0; i < Campos.Count; i++)
			{
				Campos[i].Limpar();
			}
			_comboBoxContas.Valor.PosicionarNoPrimeiro();
			_comboBoxEspecies.Valor.PosicionarNoPrimeiro();
			_campoTroco.Limpar();
			_campoValorNovaParcela.Limpar();
			_campoVencimentoNovaParcela.Limpar();
			_valorDesconto.Limpar();
			_valorAcrescimo.Limpar();
			Campos.RemoveIfExists(_campoTroco);
			Campos.RemoveIfExists(_campoVencimentoNovaParcela);
			Campos.RemoveIfExists(_campoValorNovaParcela);
			Campos.RemoveIfExists(_campoListaParcelas);
			Campos.RemoveIfExists(_valorRecebido);
			Campos.RemoveIfExists(_comboBoxContas);
			Campos.RemoveIfExists(_comboBoxEspecies);
			Campos.RemoveIfExists(_valorDesconto);
			Campos.RemoveIfExists(_valorAcrescimo);
			base.Limpar();
		}

		public override void Load()
		{
			if (!_campoListaParcelas.IsNull())
			{
				Limpar();
			}
			_campoListaParcelas = ItemInteracaoBase<ItemInteracaoListaRecebimentoQuitacao, Lista<Otus.Modulo.PontoDeVendas.ViewModels.ItensInteracao.Recebimento>>.Criar().ComDescricao("Parcelas a quitar").ComValor(ListaParcelas)
				.Build();
			Campos.Insert(0, _campoListaParcelas);
			_contas = _contaRepositoryRead.Find(EntitySpecification<DigisatServer.Domain.Main.Aggregates.FinanceirosAgg.Contas.Conta>.Ativo());
			Lista<IItemInteracao> lista = new Lista<IItemInteracao>();
			lista.Adicionar(_contas.Select((DigisatServer.Domain.Main.Aggregates.FinanceirosAgg.Contas.Conta x) => ItemInteracaoBase<ItemInteracaoConta, ContaViewModel>.Criar().ComDescricao(x.Descricao).ComValor(ContaViewModel.Criar().ComConta(x))));
			_comboBoxContas = ItemInteracaoBase<ItemInteracaoComboBox, Lista<IItemInteracao>>.Criar().ComDescricao("Contas").ComValor(lista)
				.Build();
			Campos.Add(_comboBoxContas);
			_especies = new List<EspeciePagamentoDto>(EspeciePagamentoValueObjectService.ObterEspeciePagamentoParaQuitacao().ProjectedAsCollectionDto());
			_tef = _configuracaoClientService.ObterConfiguracao()?.Tef?.Tipo ?? TipoTef.Nenhum;
			if (_tef != TipoTef.Nenhum)
			{
				_especies.Add(new EspeciePagamentoECF(new Cartao(), 2, "Cartão").ProjectedAsDto());
			}
			Lista<IItemInteracao> lista2 = new Lista<IItemInteracao>();
			lista2.Adicionar(_especies.Select((EspeciePagamentoDto x) => ItemInteracaoBase<ItemInteracaoEspecie, Especie>.Criar().ComDescricao(x.Descricao).ComValor(Especie.Criar().ComDescricao(x.Descricao).ComCodigo(x.Codigo))
				.Build()));
			_interacaoDesconto = InteracaoComando<decimal>.Criar().ComComando(new DelegateCommand(AplicarDesconto)).Build();
			_valorDesconto = ItemInteracaoBase<ItemInteracaoButtonDecimal, InteracaoComando<decimal>>.Criar().ComDescricao("Desconto").ComValor(_interacaoDesconto)
				.ComSomenteLeitura(!DadosSistema.VerificarPermissao<DigisatServer.Infrastructure.Crosscutting.Module.PontoDeVenda, PermitirAplicarDescontoRecebimento>())
				.Build();
			Campos.Add(_valorDesconto);
			_interacaoAcrescimo = InteracaoComando<decimal>.Criar().ComComando(new DelegateCommand(AplicarAcrescimo)).Build();
			_valorAcrescimo = ItemInteracaoBase<ItemInteracaoButtonDecimal, InteracaoComando<decimal>>.Criar().ComDescricao("Acréscimo").ComValor(_interacaoAcrescimo)
				.ComSomenteLeitura(!DadosSistema.VerificarPermissao<DigisatServer.Infrastructure.Crosscutting.Module.PontoDeVenda, PermitirAplicarDescontoRecebimento>())
				.Build();
			Campos.Add(_valorAcrescimo);
			_valorRecebido = ItemInteracaoBase<ItemInteracaoDecimalFocusable, decimal>.Criar().ComDescricao("Valor recebido").ComValor(TotalParcelas)
				.Build();
			Campos.Add(_valorRecebido);
			_comboBoxEspecies = ItemInteracaoBase<ItemInteracaoComboBox, Lista<IItemInteracao>>.Criar().ComDescricao("Espécies").ComValor(lista2)
				.Build();
			Campos.Add(_comboBoxEspecies);
			_disposable = _comboBoxEspecies.Valor.WhenAlterouItemSelecionado.Subscribe((IItemInteracao x) =>
			{
				ValidarCreditosCliente();
			});
			_disposable = _comboBoxEspecies.Valor.WhenAlterouItemSelecionado.Subscribe((IItemInteracao x) =>
			{
				VerificarCarteiraDigital();
			});
			_disposable = _comboBoxEspecies.Valor.WhenAlterouItemSelecionado.Subscribe((IItemInteracao x) =>
			{
				VerificarCartao();
			});
			_disposable = _comboBoxEspecies.Valor.WhenAlterouItemSelecionado.Subscribe((IItemInteracao x) =>
			{
				VerificarCartaoPos();
			});
			_disposable = _comboBoxEspecies.Valor.WhenAlterouItemSelecionado.Subscribe((IItemInteracao x) =>
			{
				VerificarTerminalPos();
			});
			IObservable<string> whenPropertyChanged = _valorRecebido.WhenPropertyChanged;
			_interacaoDesconto.WhenPropertyChanged.Subscribe((string x) =>
			{
				Campos.RemoveIfExists(_campoTroco);
				Campos.RemoveIfExists(_campoVencimentoNovaParcela);
				Campos.RemoveIfExists(_campoValorNovaParcela);
				_valorRecebido.Limpar();
				_valorRecebido.ComValor(TotalParcelas);
			});
			_interacaoAcrescimo.WhenPropertyChanged.Subscribe((string x) =>
			{
				Campos.RemoveIfExists(_campoTroco);
				Campos.RemoveIfExists(_campoVencimentoNovaParcela);
				Campos.RemoveIfExists(_campoValorNovaParcela);
				_valorRecebido.Limpar();
				_valorRecebido.ComValor(TotalParcelas);
			});
			_campoTroco = ItemInteracaoBase<ItemInteracaoTextBlock, string>.Criar().ComDescricao("Troco").Build();
			_campoVencimentoNovaParcela = ItemInteracaoBase<ItemInteracaoData, DateTime>.Criar().ComDescricao("Vencimento da nova parcela").ComValor(ListaParcelas.Itens.Max((Otus.Modulo.PontoDeVendas.ViewModels.ItensInteracao.Recebimento x) => x.RecebimentoDto.DataVencimento))
				.Build();
			_campoValorNovaParcela = ItemInteracaoBase<ItemInteracaoDecimalReadOnly, decimal>.Criar().ComDescricao("Valor da nova parcela").Build();
			whenPropertyChanged.Subscribe((string x) =>
			{
				Campos.RemoveIfExists(_campoTroco);
				Campos.RemoveIfExists(_campoVencimentoNovaParcela);
				Campos.RemoveIfExists(_campoValorNovaParcela);
			});
			whenPropertyChanged.Select((string v) => _valorRecebido.Valor).Subscribe((decimal x) =>
			{
				ValidarCreditosCliente();
			});
			(from v in whenPropertyChanged
				select _valorRecebido.Valor into valor
				where TotalParcelas < valor
				select valor).Subscribe((decimal x) =>
			{
				Campos.Insert(DadosSistema.VerificarPermissao<DigisatServer.Infrastructure.Crosscutting.Module.PontoDeVenda, PermitirAplicarDescontoRecebimento>() ? 6 : 5, _campoTroco);
				_campoTroco.ComValor($"{_valorRecebido.Valor - TotalParcelas:N2}");
			});
			(from v in whenPropertyChanged
				select _valorRecebido.Valor into valor
				where TotalParcelas > valor && valor > 0m
				select valor).Subscribe((decimal x) =>
			{
				decimal num = RetornarValorNovaParcela();
				if (num > 0m)
				{
					Campos.Insert(DadosSistema.VerificarPermissao<DigisatServer.Infrastructure.Crosscutting.Module.PontoDeVenda, PermitirAplicarDescontoRecebimento>() ? 6 : 5, _campoVencimentoNovaParcela);
					Campos.Insert(DadosSistema.VerificarPermissao<DigisatServer.Infrastructure.Crosscutting.Module.PontoDeVenda, PermitirAplicarDescontoRecebimento>() ? 7 : 6, _campoValorNovaParcela);
					_campoValorNovaParcela.ComValor(num);
				}
			});
			DCommand = new DelegateCommand(() =>
			{
				_comboBoxEspecies.Valor.Posicionar((IItemInteracao x) => x.To<ItemInteracaoEspecie>().Descricao.Equals("Dinheiro"));
				F2Method();
			});
			TCommand = new DelegateCommand(() =>
			{
				_comboBoxEspecies.Valor.Posicionar((IItemInteracao x) => x.To<ItemInteracaoEspecie>().Descricao.Equals("Cartão"));
			});
			OCommand = new DelegateCommand(() =>
			{
				_comboBoxEspecies.Valor.Posicionar((IItemInteracao x) => x.To<ItemInteracaoEspecie>().Descricao.Equals("Cartão POS"));
			});
			QCommand = new DelegateCommand(() =>
			{
				_comboBoxEspecies.Valor.Posicionar((IItemInteracao x) => x.To<ItemInteracaoEspecie>().Descricao.Equals("Carteira digital"));
			});
			MCommand = new DelegateCommand(() =>
			{
				_comboBoxEspecies.Valor.Posicionar((IItemInteracao x) => x.To<ItemInteracaoEspecie>().Descricao.Equals("Terminal POS"));
			});
			XCommand = new DelegateCommand(() =>
			{
				_comboBoxEspecies.Valor.Posicionar((IItemInteracao x) => x.To<ItemInteracaoEspecie>().Descricao.Equals("Crédito loja"));
			});
		}

		private void AplicarDesconto()
		{
			_valorAcrescimo.Limpar();
			_valorDesconto.Limpar();
			_valorDesconto.Valor.Dado = DialogoFactory.MostrarDialogoDesconto(TotalParcelas);
			AutorizacaoDto autorizacaoDto = _sessaoService.VerificarPermissao<DigisatServer.Infrastructure.Crosscutting.Module.PontoDeVenda, PermitirAplicarDescontoRecebimento>();
			if (autorizacaoDto == null)
			{
				_valorDesconto.Valor.Dado = 0m;
			}
			Seletor.Get<PainelDocumentoFiscal>()?.PreDocumentoFiscal?.AdicionarAutorizacao(autorizacaoDto);
		}

		private void AplicarAcrescimo()
		{
			_valorDesconto.Limpar();
			_valorAcrescimo.Limpar();
			_valorAcrescimo.Valor.Dado = DialogoFactory.MostrarDialogoAcrescimo(TotalParcelas);
			AutorizacaoDto autorizacaoDto = _sessaoService.VerificarPermissao<DigisatServer.Infrastructure.Crosscutting.Module.PontoDeVenda, PermitirAplicarDescontoRecebimento>();
			if (autorizacaoDto == null)
			{
				_valorAcrescimo.Valor.Dado = 0m;
			}
			Seletor.Get<PainelDocumentoFiscal>()?.PreDocumentoFiscal?.AdicionarAutorizacao(autorizacaoDto);
		}

		protected void ValidarCreditosCliente()
		{
			decimal num = _consumidor?.TotalCreditoDevolucoes ?? 0m;
			if (!_consumidor.IsNull() && !_comboBoxEspecies.IsNull() && _comboBoxEspecies.Valor.PossuiItemSelecionado && ((ItemInteracaoEspecie)_comboBoxEspecies.Valor.ItemSelecionado).Valor.Codigo == 22 && !(_valorRecebido.Valor <= num) && !(_valorRecebido.Valor <= 0m))
			{
				DialogoFactory.MostrarDialogoConfirma($"O valor informado ultrapassa o valor de créditos disponíveis para {_consumidor.Nome}.");
				DormirAsync(500, (object action) =>
				{
					_valorRecebido.Limpar();
				});
			}
		}

		private void VerificarCarteiraDigital()
		{
			ConfiguracaoTef tef = DadosSistema.ObterConfiguracaoClient().ObterConfiguracao().Tef;
			if (_comboBoxEspecies.Valor.PossuiItemSelecionado && ((ItemInteracaoEspecie)_comboBoxEspecies.Valor.ItemSelecionado).Valor.Codigo == 24)
			{
				ConfiguracaoTef tef2 = DadosSistema.ObterConfiguracaoClient().ObterConfiguracao().Tef;
				if (tef2 != null && tef2.TefConfigurado && (tef.Tipo == TipoTef.PayGo || tef.Tipo == TipoTef.Sitef || tef.Tipo == TipoTef.GetCard || tef.Tipo == TipoTef.Elgin || tef.Tipo == TipoTef.Dial || tef.Tipo == TipoTef.Destaxa || tef.Tipo == TipoTef.Auttar) && DialogoFactory.MostrarDialogoSimNao("Iniciar o gerenciador padrão do TEF?") == MessageBoxResult.Yes)
				{
					_finalizadoEmCarteiraDigitalTef = true;
					PreencherVariaveis();
					int indiceEspecieEcf = 0;
					_emissorService.ToDo((IEcfService ecf) =>
					{
						indiceEspecieEcf = ecf.Especies.Where((Especie especie) => especie.PermiteVinculado).ToArray().FindIndex((Especie x) => x.Descricao.Equals("Cartao"));
					});
					TefService.CartDigi(_valorRecebido.Valor, _valorRecebido.Valor, 0m, possuiAcrescimoDesconto: false, indiceEspecieEcf, isRecebimentoPdv: true);
					return;
				}
			}
			if (_comboBoxEspecies.Valor.PossuiItemSelecionado && ((ItemInteracaoEspecie)_comboBoxEspecies.Valor.ItemSelecionado).Valor.Codigo == 24 && DadosSistema.ShipayConfigurado && DialogoFactory.MostrarDialogoSimNao("Gerar QR Code para pagamento?") == MessageBoxResult.Yes)
			{
				PreencherVariaveis();
				_seletor.Get<PainelBuscaCarteiraDigitalShipay>().SetarPessoaEValor(_consumidor, _valorRecebido.Valor);
				_seletor.Selecionar<PainelBuscaCarteiraDigitalShipay>();
			}
			else if (_comboBoxEspecies.Valor.PossuiItemSelecionado && ((ItemInteracaoEspecie)_comboBoxEspecies.Valor.ItemSelecionado).Valor.Codigo == 24)
			{
				PreencherVariaveis();
				Seletor.Get<PainelBuscaCarteiraDigital>().SetarValor(_valorRecebido.Valor);
				Seletor.Get<PainelBuscaCarteiraDigital>().SetarIsRecebimento(isRecebimento: true);
				Seletor.Selecionar<PainelBuscaCarteiraDigital, PainelRecebimento>();
			}
		}

		private void PreencherVariaveis()
		{
			_valor = _valorRecebido.Valor;
			_desconto = _valorDesconto.Valor.Dado;
			_acrescimo = _valorAcrescimo.Valor.Dado;
			_vencimento = _campoVencimentoNovaParcela.Valor;
			_conta = _contas.FirstOrDefault((DigisatServer.Domain.Main.Aggregates.FinanceirosAgg.Contas.Conta a) => a.Id.ToString() == (_comboBoxContas.Valor.ItemSelecionado as ItemInteracaoConta)?.Valor.Id.ToString());
			_especie = _especies.FirstOrDefault((EspeciePagamentoDto a) => a.Descricao == (_comboBoxEspecies.Valor.ItemSelecionado as ItemInteracaoEspecie)?.Valor.Descricao);
		}

		private void VerificarCartao()
		{
			if (!_comboBoxEspecies.Valor.PossuiItemSelecionado || ((ItemInteracaoEspecie)_comboBoxEspecies.Valor.ItemSelecionado).Valor.Codigo != 2 || _tef == TipoTef.Nenhum)
			{
				return;
			}
			PreencherVariaveis();
			int indiceEspecieEcf = 0;
			_emissorService.ToDo((IEcfService ecf) =>
			{
				indiceEspecieEcf = ecf.Especies.Where((Especie especie) => especie.PermiteVinculado).ToArray().FindIndex((Especie x) => x.Descricao.Equals("Cartao"));
			});
			TefService.Crt(_valorRecebido.Valor, _valorRecebido.Valor, 0m, possuiAcrescimoDesconto: false, indiceEspecieEcf, isRecebimentoPdv: true);
		}

		private void VerificarCartaoPos()
		{
			if (_comboBoxEspecies.Valor.PossuiItemSelecionado && ((ItemInteracaoEspecie)_comboBoxEspecies.Valor.ItemSelecionado).Valor.Codigo == 7)
			{
				PreencherVariaveis();
				Seletor.Get<PainelBuscaAdministradoraCartao>().SetarValor(_valorRecebido.Valor);
				Seletor.Get<PainelBuscaAdministradoraCartao>().SetarIsRecebimento(isRecebimento: true);
				Seletor.Selecionar<PainelBuscaAdministradoraCartao, PainelRecebimento>();
			}
		}

		private void VerificarTerminalPos()
		{
			if (_comboBoxEspecies.Valor.PossuiItemSelecionado && ((ItemInteracaoEspecie)_comboBoxEspecies.Valor.ItemSelecionado).Valor.Codigo == 27)
			{
				_pagamentoViaTerminalPos = true;
				PreencherVariaveis();
				_seletor.Get<PainelBuscaMeioPagamentoTerminalPos>().SetarValor(_valorRecebido.Valor);
				_seletor.Get<PainelBuscaMeioPagamentoTerminalPos>().SetarRecebimento(recebimento: true);
				_seletor.Selecionar<PainelBuscaMeioPagamentoTerminalPos>();
			}
		}

		public void SetarPagamentoNaoFinalizadoViaTerminalPos()
		{
			_pagamentoViaTerminalPos = false;
			_especie = null;
		}

		public void SetarFinalizadoEmCarteiraDigital(bool finalizadoEmCarteiraDigital)
		{
			_finalizadoEmCarteiraDigital = finalizadoEmCarteiraDigital;
		}

		private decimal RetornarValorNovaParcela()
		{
			decimal num = 0m;
			foreach (Otus.Modulo.PontoDeVendas.ViewModels.ItensInteracao.Recebimento iten in ListaParcelas.Itens)
			{
				num += iten.RecebimentoDto.ValorTotal;
				if (num >= _valorRecebido.Valor)
				{
					return num - _valorRecebido.Valor - _valorDesconto.Valor.Dado + _valorAcrescimo.Valor.Dado;
				}
			}
			return num - _valorRecebido.Valor - _valorDesconto.Valor.Dado + _valorAcrescimo.Valor.Dado;
		}

		public override void UnLoad()
		{
			Limpar();
		}

		public override bool PodeVoltar()
		{
			return true;
		}

		public override void Dispose()
		{
			_disposable?.Dispose();
			_disposable = null;
		}

		protected override bool CanF2Method()
		{
			if (_valorRecebido.Valor > 0m && ((ItemInteracaoEspecie)_comboBoxEspecies.Valor.ItemSelecionado).Valor.Codigo != 2)
			{
				return !_finalizadoEmCarteiraDigitalTef;
			}
			return false;
		}

		public void FinalizarPagamentoCarteiraDigital(InformacaoTransacaoCarteiraDigital informacaoTransacaoCarteiraDigital)
		{
			_informacaoTransacaoCarteiraDigital = informacaoTransacaoCarteiraDigital;
			F2Method();
			DormirSync(300, () =>
			{
				TefService.Imprimir();
			});
			_finalizadoEmCarteiraDigital = false;
			_finalizadoEmCarteiraDigitalTef = false;
			Seletor.Get<PainelDocumentoFiscal>().Informacao.ControlarFoco();
		}

		public void FinalizarPagamentoCartao(InformacaoTransacaoTef informacaoTransacaoTef)
		{
			_informacaoTransacaoTef = informacaoTransacaoTef;
			F2Method();
			DormirSync(300, () =>
			{
				TefService.Imprimir();
			});
			Seletor.Get<PainelDocumentoFiscal>().Informacao.ControlarFoco();
		}

		public void FinalizarPagamentoTerminalPos(PagamentoTransacaoDto pagamentoTransacao)
		{
			_pagamentoTransacaoDto = pagamentoTransacao;
			F2Method();
			_emissorService.ImprimirRelatoriosGerenciaisFinalizacao();
			_pagamentoViaTerminalPos = false;
		}

		protected override void F2Method()
		{
			QuitacaoDto quitacaoDto = Service.Canal((IRecebimentoModuleService x) => x.ObterQuitacaoDto());
			quitacaoDto.Conta = ((_finalizadoEmCarteiraDigital || _pagamentoViaTerminalPos || _informacaoTransacaoTef.IsNotNull()) ? _conta.ProjectedAsDto() : _contas.FirstOrDefault((DigisatServer.Domain.Main.Aggregates.FinanceirosAgg.Contas.Conta a) => a.Id.ToString() == (_comboBoxContas.Valor.ItemSelecionado as ItemInteracaoConta)?.Valor.Id.ToString()).ProjectedAsDto());
			quitacaoDto.DataVencimentoNovaParcela = ((_finalizadoEmCarteiraDigital || _pagamentoViaTerminalPos || _informacaoTransacaoTef.IsNotNull()) ? _vencimento : _campoVencimentoNovaParcela.Valor);
			quitacaoDto.Parcelas = ListaParcelas.Itens.Select((Otus.Modulo.PontoDeVendas.ViewModels.ItensInteracao.Recebimento a) => a.RecebimentoDto);
			QuitacaoDto quitacaoDto2 = quitacaoDto;
			decimal valorQuitado;
			if (_finalizadoEmCarteiraDigital || _pagamentoViaTerminalPos || _informacaoTransacaoTef.IsNotNull())
			{
				valorQuitado = _valor;
			}
			else
			{
				valorQuitado = ((_valorRecebido.Valor <= TotalParcelas) ? _valorRecebido.Valor : TotalParcelas);
			}
			quitacaoDto2.ValorQuitado = valorQuitado;
			quitacaoDto.Desconto = ((_finalizadoEmCarteiraDigital || _pagamentoViaTerminalPos || _informacaoTransacaoTef.IsNotNull()) ? _desconto : _valorDesconto.Valor.Dado);
			quitacaoDto.Acrescimo = ((_finalizadoEmCarteiraDigital || _pagamentoViaTerminalPos || _informacaoTransacaoTef.IsNotNull()) ? _acrescimo : _valorAcrescimo.Valor.Dado);
			QuitacaoDto quitacaoDto3 = quitacaoDto;
			EspeciePagamentoDto especiePagamento;
			if (_finalizadoEmCarteiraDigital)
			{
				especiePagamento = new EspeciePagamentoCarteiraDigitalDto
				{
					Codigo = _especie.Codigo,
					Descricao = _especie.Descricao.ToStringEmptyWhenNull(),
					EspecieRecebimento = _especie.EspecieRecebimento,
					IsUsoEcf = _especie.IsUsoEcf,
					ToText = _especie.ToText,
					TransacaoCarteiraDigital = new TransacaoCarteiraDigitalDto
					{
						Tipo = _informacaoTransacaoCarteiraDigital.Rede.ToStringEmptyWhenNull(),
						CodigoAutorizacaoTransacao = _informacaoTransacaoCarteiraDigital.CodigoAutorizacao.ToStringEmptyWhenNull(),
						Rede = _informacaoTransacaoCarteiraDigital.Rede.ToStringEmptyWhenNull(),
						Pessoa = _informacaoTransacaoCarteiraDigital.Pessoa.ProjectedPessoaHistoricoAsDto(),
						TaxaDto = (_informacaoTransacaoCarteiraDigital.Taxa.ProjectedAsDto() ?? new TaxaDtoNull()),
						EndToEndId = _informacaoTransacaoCarteiraDigital.EndToEndId.ToStringEmptyWhenNull(),
						PspPagador = _informacaoTransacaoCarteiraDigital.PspPagador.ToStringEmptyWhenNull()
					}
				};
			}
			else if (_pagamentoViaTerminalPos)
			{
				especiePagamento = (_pagamentoTransacaoDto.IsCarteiraDigital ? ((EspeciePagamentoDto)new EspeciePagamentoCarteiraDigitalDto
				{
					Codigo = _especie.Codigo,
					Descricao = _especie.Descricao.ToStringEmptyWhenNull(),
					EspecieRecebimento = _especie.EspecieRecebimento,
					IsUsoEcf = _especie.IsUsoEcf,
					ToText = _especie.ToText,
					TransacaoCarteiraDigital = new TransacaoCarteiraDigitalDto
					{
						Tipo = _pagamentoTransacaoDto.Rede.ToStringEmptyWhenNull(),
						CodigoAutorizacaoTransacao = _pagamentoTransacaoDto.CodigoAutorizacaoTransacao.ToStringEmptyWhenNull(),
						Rede = _pagamentoTransacaoDto.Rede.ToStringEmptyWhenNull(),
						Pessoa = _pagamentoTransacaoDto.Pessoa,
						TaxaDto = (_pagamentoTransacaoDto.Taxa ?? new TaxaDtoNull())
					}
				}) : ((EspeciePagamentoDto)new EspeciePagamentoCartaoDto
				{
					Codigo = _especie.Codigo,
					Descricao = _especie.Descricao.ToStringEmptyWhenNull(),
					EspecieRecebimento = _especie.EspecieRecebimento,
					IsUsoEcf = _especie.IsUsoEcf,
					ToText = _especie.ToText,
					Cartao = new CartaoDto
					{
						TipoCartao = ((!_pagamentoTransacaoDto.Debito) ? TipoCartao.Credito : TipoCartao.Debito),
						CodigoAutorizacaoTransacao = _pagamentoTransacaoDto.CodigoAutorizacaoTransacao.ToStringEmptyWhenNull(),
						Rede = _pagamentoTransacaoDto.Rede.ToStringEmptyWhenNull(),
						Pessoa = _pagamentoTransacaoDto.Pessoa,
						TaxaDto = (_pagamentoTransacaoDto.Taxa ?? new TaxaDtoNull())
					}
				}));
			}
			else
			{
				especiePagamento = (_informacaoTransacaoTef.IsNull() ? _especies.FirstOrDefault((EspeciePagamentoDto a) => a.Descricao == (_comboBoxEspecies.Valor.ItemSelecionado as ItemInteracaoEspecie)?.Valor.Descricao) : new EspeciePagamentoCartaoDto
				{
					Codigo = _especie.Codigo,
					Descricao = _especie.Descricao.ToStringEmptyWhenNull(),
					EspecieRecebimento = _especie.EspecieRecebimento,
					IsUsoEcf = _especie.IsUsoEcf,
					ToText = _especie.ToText,
					Cartao = new CartaoDto
					{
						TipoCartao = ((!_informacaoTransacaoTef.Debito) ? TipoCartao.Credito : TipoCartao.Debito),
						CodigoAutorizacaoTransacao = _informacaoTransacaoTef.CodigoAutorizacaoTransacao.ToStringEmptyWhenNull(),
						Rede = _informacaoTransacaoTef.Rede.ToStringEmptyWhenNull(),
						Pessoa = _informacaoTransacaoTef.Pessoa.ProjectedPessoaHistoricoAsDto(),
						TaxaDto = _informacaoTransacaoTef.Taxa.ProjectedAsDto()
					}
				});
			}
			quitacaoDto3.EspeciePagamento = especiePagamento;
			if (_finalizadoEmCarteiraDigital || _pagamentoViaTerminalPos || _informacaoTransacaoTef.IsNotNull())
			{
				_emissorService.EmitirDocumentoFiscalItemFinanceiro(quitacaoDto.ValorQuitado, _finalizadoEmCarteiraDigital, _finalizadoEmCarteiraDigitalTef, _pagamentoViaTerminalPos, _informacaoTransacaoCarteiraDigital, _informacaoTransacaoTef, _pagamentoTransacaoDto);
			}
			if ((_comboBoxEspecies.Valor.ItemSelecionado as ItemInteracaoEspecie)?.Valor.Descricao == "Cheque")
			{
				Cheque = new ChequeDtoNull();
				Seletor.Get<PainelCheque>().SetarValorCheque(_valorRecebido.Valor);
				Seletor.Selecionar<PainelCheque, PainelRecebimento>();
				if (!Cheque.IsNot<ChequeDtoNull>())
				{
					return;
				}
				EspeciePagamentoChequeDto especiePagamentoChequeDto = new EspeciePagamentoChequeDto
				{
					Descricao = quitacaoDto.EspeciePagamento.Descricao,
					Codigo = quitacaoDto.EspeciePagamento.Codigo,
					Cheque = Cheque,
					ToText = quitacaoDto.EspeciePagamento.ToText,
					EspecieRecebimento = quitacaoDto.EspeciePagamento.EspecieRecebimento,
					IsUsoEcf = quitacaoDto.EspeciePagamento.IsUsoEcf
				};
				quitacaoDto.EspeciePagamento = especiePagamentoChequeDto;
				_especie = especiePagamentoChequeDto;
				_finalizadoEmCheque = true;
			}
			try
			{
				Service.Canal((IRecebimentoModuleService x) =>
				{
					ImprimirComprovante(x.QuitarPontoDeVendaAsync(quitacaoDto), _valorRecebido.Valor);
				});
				_informacaoTransacaoTef = null;
				_valor = 0m;
				_desconto = 0m;
				_acrescimo = 0m;
				_vencimento = DateTime.MinValue;
				_conta = null;
				_especie = null;
				Seletor.FecharTudo();
			}
			catch (Exception ex)
			{
				DialogoFactory.MostrarDialogoConfirma(ex.Message);
			}
		}

		public void SetarCheque(ChequeDto cheque)
		{
			Cheque = cheque;
		}

		private void ImprimirComprovante(QuitadoDto quitado, decimal valorRecebido)
		{
			List<PagamentoRecebimentoDto> source = quitado.Parcelas.Where((PagamentoRecebimentoDto x) => x.ValorQuitacao > 0m).ToListEmptyWhenNull();
			if (!source.Any())
			{
				return;
			}
			PagamentoRecebimentoDto pagamentoRecebimentoDto = source.FirstOrDefault();
			if (pagamentoRecebimentoDto == null)
			{
				return;
			}
			ConsumidorLocal consumidor = ConsumidorLocal.Criar().ComPessoa(pagamentoRecebimentoDto.Pessoa);
			string descricao = pagamentoRecebimentoDto.EspeciePagamento.Descricao;
			_emissorService.EmitirComprovanteNaoFiscalRecebimento(consumidor, descricao, valorRecebido, source.Sum((PagamentoRecebimentoDto x) => x.ValorQuitacao));
			if (DadosSistema.ConfiguracaoDto.Financeiro.ImprimirUmReciboPorDocumentoQuitado.Valor)
			{
				foreach (PagamentoRecebimentoDto item in quitado.Parcelas.Where((PagamentoRecebimentoDto x) => x.Situacao.Codigo == 3))
				{
					_emissorService.ImprimirRelatorioGerencialRecebimento(GerarImpressoRecebimento(item, quitado.SaldoDevedor));
				}
				return;
			}
			_emissorService.ImprimirRelatorioGerencialRecebimento(GerarImpressoRecebimento(quitado));
		}

		private IEnumerable<string> GerarImpressoRecebimento(QuitadoDto quitado)
		{
			List<string> list = new List<string>();
			string arg = Conversoes.DecimalPorExtenso(quitado.Parcelas.Sum((PagamentoRecebimentoDto x) => x.ValorQuitacao));
			string arg2;
			if (_pagamentoViaTerminalPos)
			{
				arg2 = _pagamentoTransacaoDto.DescricaoDanfe;
			}
			else
			{
				arg2 = (((_finalizadoEmCarteiraDigital || _finalizadoEmCarteiraDigitalTef || _informacaoTransacaoTef.IsNotNull() || _finalizadoEmCheque) && _especie.IsNotNull()) ? _especie.Descricao : (_comboBoxEspecies.Valor.ItemSelecionado as ItemInteracaoEspecie)?.Valor.Descricao);
			}
			if (DadosSistema.TamanhoBobina == TamanhoBobina.CinquentaESeisCinquentaESeteCinquentaEOitoMilimetros && _emissorService.IsNot<IEcfService>())
