	public class PainelRegistroAbastecimentoDocumentoFiscalEletronicoManual : PainelBicosValor
	{
		public override string Titulo => "Registro de abastecimento";

		public PainelRegistroAbastecimentoDocumentoFiscalEletronicoManual()
		{
		}

		public PainelRegistroAbastecimentoDocumentoFiscalEletronicoManual(IWService service, IEventPublisher eventPublisher, Seletor<IPainel> seletor)
			: base("Volume", service, eventPublisher, seletor)
		{
		}

		protected override void ObterBicos()
		{
			_bicos = _service.Canal((IBicoModuleService x) => x.ObterTodosBicos());
		}

		protected override void F2Method()
		{
			ItemInteracaoTexto bico = _listaBicos.ItemSelecionado as ItemInteracaoTexto;
			decimal volume = _valor.Valor;
			try
			{
				IAbastecimento item = _service.Canal((IPostoCombustivelModuleService x) => x.AdicionarAbastecimentoCupomFiscalAutomatico(bico.Valor, volume)).Morfar();
				Seletor.Get<PainelDocumentoFiscal>().EmitirAbastecimentos(new List<IAbastecimento> { item });
				Seletor.Voltar();
			}
			catch (Exception ex)
			{
				ex.ShowLastException();
			}
		}
	}
	public class PainelRegistroAbastecimentoDocumentoFiscalManual : PainelBicosValor
	{
		private readonly IEmissorService _emissorService;

		private readonly Seletor<IPainel> _seletorEsquerdo;

		public override string Titulo => "Registro de abastecimento";

		public PainelRegistroAbastecimentoDocumentoFiscalManual()
		{
		}

		public PainelRegistroAbastecimentoDocumentoFiscalManual(IEmissorService emissorService, IWService service, IEventPublisher eventPublisher, Seletor<IPainel> seletorEsquerdo, Seletor<IPainel> seletorDireito)
			: base("Volume", service, eventPublisher, seletorDireito)
		{
			_emissorService = emissorService;
			_seletorEsquerdo = seletorEsquerdo;
		}

		protected override void ObterBicos()
		{
			IEnumerable<int> bicosSemComunicacao = from x in _seletorEsquerdo.Get<PainelEsquerdoPosto>().ObterBicosSemComunicacao()
				select x.BicoNoSoftware;
			_bicos = _service.Canal((IBicoModuleService x) => x.ObterBicos(bicosSemComunicacao));
		}

		protected override void F2Method()
		{
			ItemInteracaoTexto bico = _listaBicos.ItemSelecionado as ItemInteracaoTexto;
			decimal volume = _valor.Valor;
			IAbastecimento abastecimento = _service.Canal((IPostoCombustivelModuleService x) => x.AdicionarAbastecimentoCupomFiscalManual(bico.Valor, volume)).Morfar();
			Seletor.Get<PainelDocumentoFiscal>().EmitirAbastecimentos(new List<IAbastecimento> { abastecimento }, registroAbastecimentoManual: true);
			_service.Canal((IPostoCombustivelModuleService x) =>
			{
				x.AtualizarStatusAbastecimentosEmitidoCupomFiscalManualmente(abastecimento.Id, _emissorService.RetornarContadorOrdemOperacao(), _emissorService.RetornarDataEmissao(), _emissorService.RetornarNumeroFabricacao());
			});
			Seletor.Voltar();
		}

		public override bool PodeVoltar()
		{
			return true;
		}
	}
