		{
			PainelRegistroPafEcf painelRegistroPafEcf = this;
			_pafEcfService = pafEcfService;
			DataInicial = ItemInteracaoBase<ItemInteracaoDataFocusable, DateTime>.Criar().ComDescricao("Data inicial").ComValor(DateTime.Now)
				.Build();
			Campos.Add(DataInicial);
			DataFinal = ItemInteracaoBase<ItemInteracaoData, DateTime>.Criar().ComDescricao("Data final").ComValor(DateTime.Now)
				.Build();
			Campos.Add(DataFinal);
			ItensEstoque = new Lista<ItemEstoque>();
			ItemInteracaoListaRegistrosPafEcf listaEstoque = ItemInteracaoBase<ItemInteracaoListaRegistrosPafEcf, Lista<ItemEstoque>>.Criar().ComDescricao("Lista de estoque").ComValor(ItensEstoque)
				.Build();
			Lista<IItemInteracao> lista = new Lista<IItemInteracao>();
			lista.Adicionar(listaEstoque);
			ItemInteracaoComboBox itemInteracaoComboBox = ItemInteracaoBase<ItemInteracaoComboBox, Lista<IItemInteracao>>.Criar().ComDescricao("Parcial").ComValor(lista)
				.Build();
			ItemInteracaoTexto itemInteracaoTexto = ItemInteracaoBase<ItemInteracaoTexto, string>.Criar().ComDescricao("Total").ComValor("T")
				.Build();
			Lista<IItemInteracao> lista2 = new Lista<IItemInteracao>();
			lista2.Adicionar(itemInteracaoTexto, itemInteracaoComboBox);
			lista2.WhenAlterouItemSelecionado.Subscribe((IItemInteracao interacao) =>
			{
				if (interacao is ItemInteracaoComboBox && painelRegistroPafEcf.ItensEstoque.Numero <= 0)
				{
					IEnumerable<ItemEstoque> itens = from x in produtoServicoRepositoryRead.Find(EntitySpecification<DigisatServer.Domain.Main.Aggregates.CadastrosAgg.ProdutosServicos.ProdutoServico>.Ativo())
						select new ItemEstoque
						{
							Id = x.Id.ToString(),
							Descricao = x.Descricao
						};
					painelRegistroPafEcf.ItensEstoque.Adicionar(itens);
					listaEstoque.Valor.PosicionarNoPrimeiro();
				}
			});
			Campos.Add(ItemInteracaoBase<ItemInteracaoComboBox, Lista<IItemInteracao>>.Criar().ComDescricao("Abrangência do estoque").ComValor(lista2)
				.Build());
		}

		protected override void F2Method()
		{
			try
			{
				_pafEcfService.GerarArquivoRegistrosPafEcf(DataInicial.Valor, DataFinal.Valor, (from x in ItensEstoque.Itens
					where x.Selecionado
					select x.Id).ToListEmptyWhenNull(), completo: true);
				Seletor.Voltar();
			}
			catch (Exception ex)
			{
				ex.ShowLastException();
			}
		}

		public override void Load()
		{
			foreach (ItemEstoque iten in ItensEstoque.Itens)
			{
				iten.Deselecionar();
			}
		}

		public override void UnLoad()
		{
		}

		public override bool PodeVoltar()
		{
			return true;
		}

		public override void Dispose()
		{
		}
	}
	public class PainelRegistrosPafNfce : PainelRegistroPafEcf
	{
		private readonly IRegistrosPafNfceService _registrosPafNfceService;

		public PainelRegistrosPafNfce()
		{
		}

		public PainelRegistrosPafNfce(IRegistrosPafNfceService registrosPafNfceService, IRepositoryRead<DigisatServer.Domain.Main.Aggregates.CadastrosAgg.ProdutosServicos.ProdutoServico> produtoServicoRepositoryRead, Seletor<IPainel> seletor)
			: base(produtoServicoRepositoryRead, null, seletor)
		{
			_registrosPafNfceService = registrosPafNfceService;
		}

		protected override void F2Method()
		{
			try
			{
				LoaderProcessoService.MostrarLoader();
				Task.Factory.StartNew(() =>
				{
					_registrosPafNfceService.GerarArquivoRegistrosPafNfce(DataInicial.Valor, DataFinal.Valor, (from x in ItensEstoque.Itens
						where x.Selecionado
						select x.Id).ToListEmptyWhenNull(), completo: true);
				}).ContinueWith((Task task) =>
				{
					ThreadPrincipal.Executar(() =>
					{
						LoaderProcessoService.EsconderLoader();
						if (task.IsFaulted)
						{
							task.Exception.ShowLastException();
						}
						Seletor.Voltar();
					});
				});
			}
			catch (Exception ex)
			{
				ex.ShowLastException();
			}
		}
	}
