		private readonly ItemInteracaoBoleano _imprimirMovimentacoesPrazo;

		private readonly ItemInteracaoBoleano _imprimirLancamentosManuais;

		private readonly ItemInteracaoListaTurno _listaTurno;

		private IEnumerable<TurnoDto> _turnos = new List<TurnoDto>();

		public override string Titulo => "Imprimir resumo de turno";

		public override string DescricaoDoBotao => "Imprimir";

		public ICommand F3Command { get; set; }

		public PainelImpressaoResumoFechamentoTurno()
		{
		}

		public PainelImpressaoResumoFechamentoTurno(IEmissorService emissorService, IWService service, Seletor<IPainel> seletorDireito)
			: base(seletorDireito)
		{
			_emissorService = emissorService;
			_service = service;
			_dataInicial = ItemInteracaoBase<ItemInteracaoDataFocusable, DateTime>.Criar().ComDescricao("Data inicial").ComValor(DateTime.Now)
				.Build();
			_dataFinal = ItemInteracaoBase<ItemInteracaoData, DateTime>.Criar().ComDescricao("Data final").ComValor(DateTime.Now)
				.Build();
			_imprimirItensVendidos = ItemInteracaoBase<ItemInteracaoBoleano, bool>.Criar().ComDescricao("Imprimir itens vendidos").ComValor(valor: false)
				.Build();
			_imprimirMovimentacoesPrazo = ItemInteracaoBase<ItemInteracaoBoleano, bool>.Criar().ComDescricao("Imprimir lista de vendas a prazo").ComValor(valor: false)
				.Build();
			_imprimirLancamentosManuais = ItemInteracaoBase<ItemInteracaoBoleano, bool>.Criar().ComDescricao("Imprimir lançamentos manuais no caixa").ComValor(valor: false)
				.Build();
			F3Command = new DelegateCommand(Pesquisar, PodePesquisar);
			_listaTurno = ItemInteracaoBase<ItemInteracaoListaTurno, Lista<ItemTurno>>.Criar().ComValor(new Lista<ItemTurno>()).Build();
			Campos.Insert(0, _dataInicial);
			Campos.Insert(1, _dataFinal);
			Campos.Insert(2, _imprimirItensVendidos);
			Campos.Insert(3, _imprimirMovimentacoesPrazo);
			Campos.Insert(4, _imprimirLancamentosManuais);
			Campos.Insert(5, ItemInteracaoBase<ItemInteracaoButton, System.Windows.Controls.Button>.Criar().ComValor(new System.Windows.Controls.Button
			{
				Content = "Pesquisar",
				Tag = "F3",
				HorizontalAlignment = System.Windows.HorizontalAlignment.Left,
				Command = F3Command
			}).Build());
			Campos.Insert(6, _listaTurno);
		}

		private void Pesquisar()
		{
			try
			{
				_turnos = _service.Canal((ITurnoModuleService service) => service.ObterTurnosPorPeriodoAsync(_dataInicial.Valor.Date, _dataFinal.Valor.Date).Result) ?? new List<TurnoDto>();
				_listaTurno.Valor.Limpar();
				_listaTurno.Valor.Adicionar(_turnos.Select((TurnoDto turno) => ItemTurno.Criar().ComDataAbertura(turno.DataHoraAbertura).ComDataFechamento(turno.Fechamento.DataHoraFechamento)
					.ComUsuario(turno.Usuario.Nome)
					.ComTurno(turno)));
			}
			catch (Exception ex)
			{
				ex.ShowLastException();
			}
		}

		private bool PodePesquisar()
		{
			return _dataInicial.Valor.Date <= _dataFinal.Valor.Date;
		}

		protected override void F2Method()
		{
			try
			{
				new ImpressaoTurnoService(_emissorService, _service).ObterRelatorioResumoFechamentoDeTurnoSintetico(_listaTurno.Valor.ItemSelecionado.Turno, _listaTurno.Valor.ItemSelecionado.Turno.Id, _imprimirItensVendidos.Valor, _imprimirMovimentacoesPrazo.Valor, _imprimirLancamentosManuais.Valor);
			}
			catch (Exception ex)
			{
				ex.ShowLastException();
			}
		}

		protected override bool CanF2Method()
		{
			return _turnos.Any();
		}

		public override void Load()
		{
		}

		public override void UnLoad()
		{
		}

		public override bool PodeVoltar()
		{
			return true;
		}

		public override void Dispose()
		{
		}
	}
