			RelatorioGerencial.Criar().ComDescricao(RelatoriosGerenciais.Parcelamento.RetornarDescricao()),
			RelatorioGerencial.Criar().ComDescricao(RelatoriosGerenciais.ParametrosPafEcf.RetornarDescricao()),
			RelatorioGerencial.Criar().ComDescricao(RelatoriosGerenciais.Turnos.RetornarDescricao()),
			RelatorioGerencial.Criar().ComDescricao(RelatoriosGerenciais.Recebimentos.RetornarDescricao()),
			RelatorioGerencial.Criar().ComDescricao(RelatoriosGerenciais.SeriaisVendidos.RetornarDescricao()),
			RelatorioGerencial.Criar().ComDescricao(RelatoriosGerenciais.TicketTroca.RetornarDescricao())
		};

		public override string Titulo => "Visualizar/Cadastrar relatórios gerenciais";

		public override string DescricaoDoBotao => "Incluir";

		public PainelRelatorioGerencial()
		{
		}

		public PainelRelatorioGerencial(IEcfService ecfService, Seletor<IPainel> seletor)
			: base(seletor)
		{
			_ecfService = ecfService;
		}

		protected override async void F2Method()
		{
			LoaderProcessoService.MostrarLoader("Cadastrando relatórios gerenciais...");
			await Task.Factory.StartNew(() =>
			{
				foreach (RelatorioGerencial item in _relatoriosGerenciaisACadastrar)
				{
					_ecfService.CadastrarRelatorioGerencial(item.Descricao);
				}
			}).ContinueWith((Task task) =>
			{
				LoaderProcessoService.EsconderLoader();
				if (task.IsFaulted)
				{
					task.Exception.ShowLastException();
				}
				Seletor.Voltar();
			}, CancellationToken.None, TaskContinuationOptions.None, TaskScheduler.FromCurrentSynchronizationContext());
		}

		protected override bool CanF2Method()
		{
			if (base.CanF2Method())
			{
				return _relatoriosGerenciaisACadastrar.Any();
			}
			return false;
		}

		public override void Load()
		{
			Campos.Clear();
			_ecfService.AguardarEcfCarregado();
			Lista<RelatorioGerencial> lista = new Lista<RelatorioGerencial>();
			IEnumerable<RelatorioGerencial> relatoriosCadastradosEcf = _ecfService.RelatoriosGerenciais.Where((RelatorioGerencial x) => !string.IsNullOrWhiteSpace(x.Descricao));
			lista.Adicionar(relatoriosCadastradosEcf);
			Campos.Insert(0, ItemInteracaoBase<ItemInteracaoListaRelatorioGerencial, Lista<RelatorioGerencial>>.Criar().ComDescricao("Relatórios gerenciais cadastrados no ECF").ComValor(lista)
				.Build());
			_relatoriosGerenciaisACadastrar = Relatorios.Where((RelatorioGerencial x) => relatoriosCadastradosEcf.All((RelatorioGerencial y) => !x.Descricao.ToLower().StartsWith(y.Descricao.ToLower()))).ToList();
		}

		public override void UnLoad()
		{
			Campos.Clear();
		}

		public override bool PodeVoltar()
		{
			return true;
		}

		public override void Dispose()
		{
		}
	}
	public class PainelRequisicoesExternasRegistradas : PainelInteracao<PainelRequisicoesExternasRegistradas>
	{
		private readonly IWService _service;

		private readonly IArquivoAuxiliarService _arquivoAuxiliarService;

		private readonly ISessaoService _sessaoService;

		private readonly ItemInteracaoDataHoraFocusable _dataInicial;

		private readonly ItemInteracaoDataHora _dataFinal;

		public override string Titulo => "Gerar arquivo eletrônico das requisições externas";

		public PainelRequisicoesExternasRegistradas()
		{
		}

		public PainelRequisicoesExternasRegistradas(IWService service, IArquivoAuxiliarService arquivoAuxiliarService, ISessaoService sessaoService, Seletor<IPainel> seletor)
			: base(seletor)
		{
			_service = service;
			_arquivoAuxiliarService = arquivoAuxiliarService;
			_sessaoService = sessaoService;
			_dataInicial = ItemInteracaoBase<ItemInteracaoDataHoraFocusable, DateTime>.Criar().ComDescricao("Data inicial").ComValor(DateTime.Now)
				.Build();
			Campos.Add(_dataInicial);
			_dataFinal = ItemInteracaoBase<ItemInteracaoDataHora, DateTime>.Criar().ComDescricao("Data final").ComValor(DateTime.Now)
				.Build();
			Campos.Add(_dataFinal);
		}

		protected override async void F2Method()
		{
			Otus.Infraestrutura.Models.Sessoes.Pessoa empresa = _sessaoService.Sessao.Perfis.ItemSelecionado.Empresa;
			GeradorArquivoRequisicaoExternaDto parametro = new GeradorArquivoRequisicaoExternaDto
			{
				DataInicial = _dataInicial.Valor,
				DataFinal = _dataFinal.Valor
			};
			IEnumerable<RegistroW4Dto> source = await _service.Canal((IGeradorArquivoRegistrosPafEcfModuleService x) => x.ObterRegistrosW4ArquivoRequisicaoExterna(parametro));
			PafEcfArquivoRequisicaoExterna pafEcfArquivoRequisicaoExterna = new PafEcfArquivoRequisicaoExterna(parametro.DataInicial, parametro.DataFinal, new RegistroW1(empresa.CpfCnpj, empresa.Ie, empresa.Im, empresa.Nome), new RegistroW2(_arquivoAuxiliarService.Cnpj, _arquivoAuxiliarService.Ie, _arquivoAuxiliarService.Im, _arquivoAuxiliarService.RazaoSocialSoftwareHouse), new RegistroW3(_arquivoAuxiliarService.NumeroLaudo, _arquivoAuxiliarService.NomeAplicativo, _arquivoAuxiliarService.VersaoAplicativo));
			pafEcfArquivoRequisicaoExterna.AdicionarRegistrosW4(source.Select((RegistroW4Dto x) => new RegistroW4(x.OrigemRE, x.CRE, x.DAV, x.NumeroMesaContaCliente, x.CCF, x.ValorTotalRE, x.NumeroFabricacaoECF, x.Denegado, 0L)));
			pafEcfArquivoRequisicaoExterna.CaminhoDoArquivo = Path.Combine(AppDomain.CurrentDomain.BaseDirectory, "Fiscal");
			pafEcfArquivoRequisicaoExterna.ChavePrivada = Hash.RetornarChavePrivadaInformacaoDecifrada();
			pafEcfArquivoRequisicaoExterna.Salvar();
			DialogoFactory.MostrarDialogoConfirma($"Arquivo {pafEcfArquivoRequisicaoExterna.ObterCaminhoCompleto()} gerado com sucesso.");
			Seletor.Voltar();
		}

