	public class PainelResumoNfceTurno : PainelListaBase<PainelResumoNfceTurno, InformacaoPainelResumoNfceTurno>, IAtalhos
	{
		private readonly IWService _service;

		private readonly IImpressoraNaoFiscalService _impressoraNaoFiscalService;

		private TurnoDto _turno;

		private bool _processando;

		public string Titulo => "NFC-e com pendências no turno";

		public ICommand ConsultarSituacaoCommand { get; set; }

		public ICommand ImprimirCommand { get; set; }

		public IReadOnlyCollection<string> Atalhos => new List<string> { "[ F2 ] Consultar situação", "[ F3 ] Imprimir" };

		public PainelResumoNfceTurno()
		{
		}

		public PainelResumoNfceTurno(Seletor<IPainel> seletor, IWService service, IImpressoraNaoFiscalService impressoraNaoFiscalService)
			: base(seletor)
		{
			_service = service;
			_impressoraNaoFiscalService = impressoraNaoFiscalService;
			ConsultarSituacaoCommand = new DelegateCommand(ConsultarSituacao, PodeConsultarSituacao);
			ImprimirCommand = new DelegateCommand(Imprimir, PodeImprimir);
			Lista.SetarCabecalho(Cabecalho<CabecalhoResumoNfceTurno>.Criar());
		}

		public void SetarMovimentacoesComPendencias(IEnumerable<MovimentacaoBaseDto> dtos)
		{
			Lista.Limpar();
			Lista.Adicionar(dtos.Select((MovimentacaoBaseDto dto) => new InformacaoPainelResumoNfceTurno(dto)));
		}

		public override void Load()
		{
		}

		public override void UnLoad()
		{
		}

		private bool PodeConsultarSituacao()
		{
			if (Lista.IsNotNull() && Lista.Itens.Any())
			{
				return !_processando;
			}
			return false;
		}

		public void ConsultarSituacao()
		{
			Lista.PosicionarNoPrimeiro();
			new Thread(async () =>
			{
				LoaderProcessoService.MostrarLoader("Consultando situação... Aguarde!");
				MovimentacaoDto nfce = default;
				foreach (InformacaoPainelResumoNfceTurno item in Lista.Itens)
				{
					try
					{
						_processando = true;
						ProcessMessages();
						if (item.Dto.Situacao.Codigo == 6)
						{
							item.Mensagem = "Movimentação rejeitada deve ser corrigida ou inutilizada manualmente.";
							continue;
						}
						_ = nfce;
						nfce = await _service.Canal((INotaFiscalConsumidorEletronicaModuleService service) => service.ConsultarSituacao(item.Dto));
						ThreadPrincipal.Executar(() =>
						{
							item.AtualizarDto(nfce);
						});
					}
					catch (Exception ex)
					{
						item.Mensagem = ex.GetLastException().Message;
					}
					finally
					{
						_processando = false;
					}
					ThreadPrincipal.Executar(() =>
					{
						Lista.PosicionarNoProximo();
					});
				}
				ThreadPrincipal.Executar(() =>
				{
					LoaderProcessoService.EsconderLoader();
					DialogoFactory.MostrarDialogoConfirma("Concluído!");
				});
			}).Start();
		}

		public bool PodeImprimir()
		{
			if (Lista.IsNotNull())
			{
				return Lista.Itens.Any();
			}
			return false;
		}

		public void Imprimir()
		{
			List<string> list = new List<string>();
			int num = ((DadosSistema.TamanhoBobina == TamanhoBobina.CinquentaESeisCinquentaESeteCinquentaEOitoMilimetros) ? 32 : 40);
			list.Add("NFC-e com pendências no turno");
			list.Add("".PadRight(num, '-'));
			list.Add($"{_turno.DataHoraAbertura:dd/MM/yyyy HH:mm} a {DateTime.Now:dd/MM/yyyy HH:mm}");
			list.Add($"Operador: {_turno.Usuario.Nome}");
			list.Add("".PadRight(num, '-'));
			foreach (InformacaoPainelResumoNfceTurno iten in Lista.Itens)
			{
				string text = $"{iten.Dto.Numero} ".PadRight(10, ' ');
				string text2 = $"{iten.Dto.DataHoraEmissao:dd/MM/yyyy} ";
				int num2 = text.Length + text2.Length;
				string arg = $"{iten.Dto.Total:c2}".PadLeft(num - num2, ' ');
				list.Add($"{text}{text2}{arg}");
				list.Add("".PadRight(num, '-'));
			}
			list.Add($"Gerado em {DateTime.Now:dd/MM/yyyy HH:mm}");
			_impressoraNaoFiscalService.Imprimir(list);
		}

		public void SetarTurno(TurnoDto turnoFechado)
		{
			_turno = turnoFechado;
		}

		public override bool PodeVoltar()
		{
			return !_processando;
		}
	}
	public class PainelSangria : PainelInteracao<PainelSangria>
	{
		private readonly IEmissorService _emissorService;

		private readonly IWService _service;

		private readonly ItemInteracaoTextBlock _totalAcumulado;

		private readonly ItemInteracaoDecimalFocusable _item;

		private readonly ItemInteracaoComboBox _itemEspecie;

		private bool _emissorPronto;

		private readonly ItemInteracaoTexto _itemObservacao;

		private readonly IRepositoryBaseWrite<ValorSangriaLocal> _valorSangriaRepositoryWrite;

		private readonly IRepositoryRead<ValorSangriaLocal> _valorSangriaRepositoryRead;

		public override string Titulo => "Registrar sangria";

		public PainelSangria()
		{
		}

		public PainelSangria(IRepositoryBaseWrite<ValorSangriaLocal> valorSangriaRepositoryWrite, IRepositoryRead<ValorSangriaLocal> valorSangriaRepositoryRead, IEmissorService emissorService, IWService service, Seletor<IPainel> seletor)
			: base(seletor)
		{
			_valorSangriaRepositoryWrite = valorSangriaRepositoryWrite;
			_valorSangriaRepositoryRead = valorSangriaRepositoryRead;
			_emissorService = emissorService;
			_service = service;
			_totalAcumulado = ItemInteracaoBase<ItemInteracaoTextBlock, string>.Criar().Build();
			_item = ItemInteracaoBase<ItemInteracaoDecimalFocusable, decimal>.Criar().ComDescricao("Valor").ComValor(0m)
				.Build();
			ItemInteracaoTexto itemInteracaoTexto = ItemInteracaoBase<ItemInteracaoTexto, string>.Criar().ComDescricao("Dinheiro").ComValor("dinheiro")
				.Build();
			ItemInteracaoTexto itemInteracaoTexto2 = ItemInteracaoBase<ItemInteracaoTexto, string>.Criar().ComDescricao("Cheque").ComValor("cheque")
				.Build();
			Lista<IItemInteracao> lista = new Lista<IItemInteracao>();
			lista.Adicionar(itemInteracaoTexto, itemInteracaoTexto2);
			_itemEspecie = ItemInteracaoBase<ItemInteracaoComboBox, Lista<IItemInteracao>>.Criar().ComDescricao("Espécie").ComValor(lista)
				.Build();
			_itemObservacao = ItemInteracaoBase<ItemInteracaoTexto, string>.Criar().ComDescricao("Observação").ComValor(string.Empty)
				.Build();
			F2Command = new AsyncCommand(F2MethodAsync, CanF2Method, allowMultipleExecution: false);
		}

		protected override bool CanF2Method()
		{
			if (base.CanF2Method() && _item.Valor > 0m)
			{
				return _emissorPronto;
			}
			return false;
		}

		private async Task F2MethodAsync()
		{
			if (DadosSistema.AutenticacaoService.Instancia.VerificarPermissao<DigisatServer.Infrastructure.Crosscutting.Module.PontoDeVenda, PermitirRegistrarSangria>() == null)
			{
				return;
			}
			LoaderProcessoService.MostrarLoader("Registrando sangria");
			await Task.Factory.StartNew(() =>
			{
				EspecieRecebimentoDto especie = ((_itemEspecie.Valor.ItemSelecionado.To<ItemInteracaoTexto>().Valor == "dinheiro") ? new EspecieRecebimentoDto
				{
					Codigo = new Dinheiro().Codigo
				} : new EspecieRecebimentoDto
				{
					Codigo = new DigisatServer.Infrastructure.Crosscutting.ValueObject.FinanceirosVO.Especies.Recebimentos.Cheque().Codigo
				});
				TurnoLancamentoDto turnoLancamento = new TurnoLancamentoDto
				{
					DataHora = DateTime.Now,
					OrigemLancamento = OrigensLancamentosTurno.ObterOrigemLancamentoTurnoPorCodigo(4).ProjectedAsDto(),
					Especie = especie,
					Valor = _item.Valor,
					Ativo = true,
					Observacao = _itemObservacao.Valor.ToStringEmptyWhenNull()
				};
				_service.Canal((ITurnoModuleService service) =>
				{
					service.AdicionarLancamento(turnoLancamento);
				});
			}).ContinueWith((Task task) =>
			{
				LoaderProcessoService.EsconderLoader();
				if (task.IsFaulted)
				{
					DialogoFactory.MostrarDialogoConfirma(task.Exception?.InnerException?.Message);
				}
				else
				{
					_emissorService.EmitirSangria(_item.Valor, _itemObservacao.Valor);
					new ValorSangriaService(_valorSangriaRepositoryWrite, _valorSangriaRepositoryRead).AlterarValor(_item.Valor, aumentar: false);
					Seletor.VoltarTudo();
				}
			}, CancellationToken.None, TaskContinuationOptions.None, TaskScheduler.FromCurrentSynchronizationContext());
		}

		protected override void F2Method()
		{
		}

		public override void Load()
		{
			Campos.Clear();
			int num = 0;
			if (DadosSistema.ConfiguracaoDto.Saida.PontoDeSangria.Valor)
			{
				ValorSangriaLocal valorSangriaLocal = _valorSangriaRepositoryRead.Find(ValorSangriaLocalSpecifications.All()).FirstOrDefault();
				_totalAcumulado.ComValor($"Valor acumulado em dinheiro: {valorSangriaLocal.Valor.FormatarCampoValor(2)}");
				Campos.Insert(num++, _totalAcumulado);
			}
			Campos.Insert(num++, _item);
			Campos.Insert(num++, _itemEspecie);
			Campos.Insert(num++, _itemObservacao);
			_emissorPronto = _emissorService.Carregado && _emissorService.Pronto && !_emissorService.VerificarReducaoZEmitidaHoje() && !_emissorService.VerificarReducaoZPendente();
		}

		public override void UnLoad()
		{
			_totalAcumulado.Valor = string.Empty;
			_item.Valor = 0m;
			_itemObservacao.Valor = string.Empty;
			_itemEspecie.Valor.PosicionarNoPrimeiro();
			Campos.Clear();
		}

		public override bool PodeVoltar()
		{
			return true;
		}

		public override void Dispose()
		{
		}
	}
	public class PainelSincronizar : PainelInteracao<PainelSincronizar>
	{
		private readonly Seletor<IPainel> _seletor;

		private readonly ItemInteracaoDataFocusable _dataInicial;

		private readonly ItemInteracaoData _dataFinal;

		private bool _sincronizando;

		private SincronizacaoService _sincronizacaoService;

		public override string Titulo => "Sincronizar registros com o servidor";

		public override string DescricaoDoBotao => "Sincronizar";

		public PainelSincronizar()
		{
		}

		public PainelSincronizar(IRepositoryRead<Movimentacao> movimentacaoRepositoryRead, IRepositoryRead<RegistroPafEcf> registroPafEcfRepositoryRead, IRepositoryRead<DigisatServer.Domain.Main.Aggregates.AuxiliaresAgg.Pbms.TransacaoPbm> transacaoPbmRepositoryRead, IWService service, Seletor<IPainel> seletor)
			: base(seletor)
		{
			_seletor = seletor;
			_dataInicial = ItemInteracaoBase<ItemInteracaoDataFocusable, DateTime>.Criar().ComDescricao("Data inicial").ComValor(DateTime.Today.AddDays(-1.0))
				.Build();
			_dataFinal = ItemInteracaoBase<ItemInteracaoData, DateTime>.Criar().ComDescricao("Data final").ComValor(DateTime.Now)
				.Build();
			Campos.Insert(0, _dataInicial);
			Campos.Insert(1, _dataFinal);
			_sincronizacaoService = new SincronizacaoService(movimentacaoRepositoryRead, registroPafEcfRepositoryRead, transacaoPbmRepositoryRead, service);
		}

		protected override async void F2Method()
		{
			LoaderProcessoService.MostrarLoader();
			_sincronizando = true;
			_sincronizacaoService.DataInicial = _dataInicial.Valor;
			_sincronizacaoService.DataFinal = _dataFinal.Valor;
			await _sincronizacaoService.Processar().ContinueWith((Task task) =>
			{
				DialogoFactory.MostrarDialogoConfirma(_sincronizacaoService.Erros.Any() ? ("Falha ao sincronizar: \n" + string.Join(Environment.NewLine, _sincronizacaoService.Erros.Select((string x) => x))) : $"Foram sincronizados {_sincronizacaoService.Registros.Count} registros!");
				LoaderProcessoService.EsconderLoader();
				_sincronizando = false;
				_seletor.VoltarTudo();
			}, CancellationToken.None, TaskContinuationOptions.None, TaskScheduler.FromCurrentSynchronizationContext());
		}

		protected override bool CanF2Method()
		{
			if (_dataInicial.Valor.Date <= _dataFinal.Valor.Date)
			{
				return !_sincronizando;
			}
			return false;
		}

		public override void Load()
		{
		}

		public override void UnLoad()
		{
		}

		public override bool PodeVoltar()
		{
			return !_sincronizando;
		}

		public override void Dispose()
		{
			_sincronizacaoService = null;
		}
	}
