			_itemObservacao = ItemInteracaoBase<ItemInteracaoTexto, string>.Criar().ComDescricao("Observação").ComValor(string.Empty)
				.Build();
			F2Command = new AsyncCommand(F2MethodAsync, CanF2Method, allowMultipleExecution: false);
		}

		protected override bool CanF2Method()
		{
			if (base.CanF2Method() && _item.Valor > 0m)
			{
				return _emissorPronto;
			}
			return false;
		}

		private async Task F2MethodAsync()
		{
			LoaderProcessoService.MostrarLoader("Registrando suprimento");
			await Task.Factory.StartNew(() =>
			{
				TurnoLancamentoDto turnoLancamento = new TurnoLancamentoDto
				{
					DataHora = DateTime.Now,
					OrigemLancamento = OrigensLancamentosTurno.ObterOrigemLancamentoTurnoPorCodigo(5).ProjectedAsDto(),
					Especie = new EspecieRecebimentoDto
					{
						Codigo = new Dinheiro().Codigo
					},
					Valor = _item.Valor,
					Ativo = true,
					Observacao = _itemObservacao.Valor.ToStringEmptyWhenNull()
				};
				_service.Canal((ITurnoModuleService service) =>
				{
					service.AdicionarLancamento(turnoLancamento);
				});
			}).ContinueWith((Task task) =>
			{
				LoaderProcessoService.EsconderLoader();
				if (task.IsFaulted)
				{
					DialogoFactory.MostrarDialogoConfirma(task.Exception?.InnerException?.Message);
				}
				else
				{
					new ValorSangriaService(_valorSangriaRepositoryWrite, _valorSangriaRepositoryRead).AlterarValor(_item.Valor);
					_emissorService.EmitirSuprimento(_item.Valor, _itemObservacao.Valor, "SUPRIMENTO");
					Seletor.VoltarTudo();
				}
			}, CancellationToken.None, TaskContinuationOptions.None, TaskScheduler.FromCurrentSynchronizationContext());
		}

		protected override void F2Method()
		{
		}

		public override void Load()
		{
			Campos.Clear();
			Campos.Add(_item);
			Campos.Add(_itemObservacao);
			_emissorPronto = _emissorService.Carregado && _emissorService.Pronto && !_emissorService.VerificarReducaoZEmitidaHoje() && !_emissorService.VerificarReducaoZPendente();
		}

		public override void UnLoad()
		{
			_item.Valor = 0m;
			_itemObservacao.Valor = string.Empty;
			Campos.Clear();
		}

		public override bool PodeVoltar()
		{
			return true;
		}

		public override void Dispose()
		{
		}
	}
