		public bool EspecieVisivel(int codigo)
		{
			return codigo switch
			{
				7 => _especiesVisiveis.FirstOrDefault((EspeciePagamentoVisivel x) => x.Codigo.Equals(7))?.Visivel ?? true, 
				2 => _especiesVisiveis.FirstOrDefault((EspeciePagamentoVisivel x) => x.Codigo.Equals(2))?.Visivel ?? true, 
				3 => _especiesVisiveis.FirstOrDefault((EspeciePagamentoVisivel x) => x.Codigo.Equals(3))?.Visivel ?? true, 
				4 => _especiesVisiveis.FirstOrDefault((EspeciePagamentoVisivel x) => x.Codigo.Equals(4))?.Visivel ?? true, 
				5 => _especiesVisiveis.FirstOrDefault((EspeciePagamentoVisivel x) => x.Codigo.Equals(5))?.Visivel ?? true, 
				22 => _especiesVisiveis.FirstOrDefault((EspeciePagamentoVisivel x) => x.Codigo.Equals(22))?.Visivel ?? true, 
				23 => _especiesVisiveis.FirstOrDefault((EspeciePagamentoVisivel x) => x.Codigo.Equals(23))?.Visivel ?? true, 
				27 => _especiesVisiveis.FirstOrDefault((EspeciePagamentoVisivel x) => x.Codigo.Equals(27))?.Visivel ?? true, 
				28 => _especiesVisiveis.FirstOrDefault((EspeciePagamentoVisivel x) => x.Codigo.Equals(28))?.Visivel ?? true, 
				14 => _especiesVisiveis.FirstOrDefault((EspeciePagamentoVisivel x) => x.Codigo.Equals(14))?.Visivel ?? true, 
				13 => _especiesVisiveis.FirstOrDefault((EspeciePagamentoVisivel x) => x.Codigo.Equals(13))?.Visivel ?? true, 
				25 => _especiesVisiveis.FirstOrDefault((EspeciePagamentoVisivel x) => x.Codigo.Equals(25))?.Visivel ?? true, 
				24 => _especiesVisiveis.FirstOrDefault((EspeciePagamentoVisivel x) => x.Codigo.Equals(24))?.Visivel ?? true, 
				26 => _especiesVisiveis.FirstOrDefault((EspeciePagamentoVisivel x) => x.Codigo.Equals(26))?.Visivel ?? true, 
				11 => _especiesVisiveis.FirstOrDefault((EspeciePagamentoVisivel x) => x.Codigo.Equals(11))?.Visivel ?? true, 
				29 => _especiesVisiveis.FirstOrDefault((EspeciePagamentoVisivel x) => x.Codigo.Equals(29))?.Visivel ?? true, 
				_ => _especiesVisiveis.FirstOrDefault((EspeciePagamentoVisivel x) => x.Codigo.Equals(1))?.Visivel ?? true, 
