		public virtual void AdicionarItem(int especie)
		{
			if (!EspecieVisivel(especie) || IniciouRecebimentoDeValores)
			{
				return;
			}
			IniciouRecebimentoDeValores = true;
			try
			{
				ListaCabecalho<ItemPagamentoViewModel> lista = Lista;
				if (lista == null || lista.ItemSelecionado.IsNull())
				{
					return;
				}
				if (!BinInformado.IsNullOrEmpty() && !Lista.ItemSelecionado.Is<ICartao>())
				{
					DialogoFactory.MostrarDialogoConfirma("Desconto da promoção Scanntech será removido pois é condicionada a forma de pagamento.\nReinicie a finalização da venda!");
					Seletor.Get<PainelDocumentoFiscal>()?.PreDocumentoFiscal.DesfazerAplicacaoPromocoesScanntech();
					_navegouPainelPromocaoScanntechMeioPagamento = false;
					BinInformado = null;
					Seletor.Voltar();
					return;
				}
				bool flag = false;
				if (Informacao.TextoToDecimal == 0m)
				{
					Informacao.Texto = Troco.ToString("n2");
					flag = true;
				}
				if (Lista.ItemSelecionado.Is<IDinheiro>() && Moedas.Numero > 0)
				{
					ValorCalculadoCotacao = 0m;
					Seletor.Get<PainelMoeda>().SetarMoedas(Moedas.Itens);
					Seletor.Get<PainelMoeda>().SetarValor(Informacao.TextoToDecimal);
					Seletor.Selecionar<PainelMoeda, PainelTotalizacaoEmissorBase>();
					if (ValorCalculadoCotacao == 0m)
					{
						return;
					}
					if (flag)
					{
						ValorCalculadoCotacao = Troco;
					}
					Informacao.Texto = ValorCalculadoCotacao.FormatarCampoValor(2);
				}
				if (Lista.ItemSelecionado.Is<IPrazo>())
				{
					if (Seletor.Get<PainelDocumentoFiscal>().Consumidor.IsNull() || Seletor.Get<PainelDocumentoFiscal>().Consumidor.Pessoa.Is<Consumidor>())
					{
						decimal subtotal = Subtotal;
						decimal textoToDecimal = Informacao.TextoToDecimal;
						Seletor.Selecionar<PainelBuscaConsumidor, PainelTotalizacaoEmissorBase>();
						if (UtilizouCashback && textoToDecimal > Subtotal)
						{
							Informacao.Texto = "0";
						}
						else if (Seletor.Get<PainelDocumentoFiscal>().RecalculouPrecoTabelaPreco)
						{
							if (!(subtotal == textoToDecimal))
							{
								DialogoFactory.MostrarDialogoConfirma("O subtotal foi recalculado, finalize novamente!");
								RecuperarFoco();
								return;
							}
							Informacao.Texto = "0";
						}
						else
						{
							Informacao.Texto = textoToDecimal.ToString("n2");
						}
					}
					Lista.Posicionar((ItemPagamentoViewModel x) => x.EspeciePagamentoPosicionar == 3);
				}
				decimal valorRestante = Subtotal - Lista.Itens.Sum((ItemPagamentoViewModel x) => x.Valor);
				decimal num = ((Informacao.TextoToDecimal == 0m) ? valorRestante : Informacao.TextoToDecimal);
				bool flag2 = num > Subtotal - Lista.Itens.Sum((ItemPagamentoViewModel x) => x.Valor);
				if (Lista.ItemSelecionado.Is<ICarteiraDigital>() & flag2)
				{
					DialogoFactory.MostrarDialogoConfirma("Operação com carteira digital deve ser limitada ao saldo restante a pagar");
				}
				else
				{
					if (((Lista.ItemSelecionado.IsNot<IDinheiro>() && Lista.ItemSelecionado.IsNot<ICartao>() && Lista.ItemSelecionado.EspeciePagamento.Codigo != 7) & flag2) && DialogoFactory.MostrarDialogoSimNao("Detectado a existência de troco para espécie de recebimento diferente de Dinheiro. Continuar?") != MessageBoxResult.Yes)
					{
						return;
					}
					if (Lista.ItemSelecionado.Is<IVale>() || Lista.ItemSelecionado.Is<IValeDetalhado>())
					{
						bool flag3 = num > Subtotal - Lista.Itens.Sum((ItemPagamentoViewModel x) => x.Valor);
						ContraVale = (flag3 ? ((Subtotal - Lista.Itens.Sum((ItemPagamentoViewModel x) => x.Valor) - num) * -1m) : 0m);
						Lista.ItemSelecionado.ToDo((IValeDetalhado v) =>
						{
							v.CalcularValorPago(Informacao.TextoToDecimal, valorRestante);
						});
					}
					if (!((Lista.ItemSelecionado.Is<ITerminalPos>() || Lista.ItemSelecionado.EspeciePagamento.Codigo == 7) & flag2))
					{
						try
						{
							if (Lista.ItemSelecionado.Is<ICartao>() || Lista.ItemSelecionado.Is<ICarteiraDigital>())
							{
								_selecionouTef = true;
								Habilitado = false;
							}
							Lista.ItemSelecionado.SomarValor(num);
							return;
						}
						catch (Exception ex)
						{
							ex.ShowLastException();
							return;
						}
						finally
						{
							HabilitarPainel();
						}
					}
					DialogoFactory.MostrarDialogoConfirma("Operação é limitada ao saldo restante a pagar");
				}
			}
			finally
			{
				IniciouRecebimentoDeValores = false;
				AtualizarTotal();
			}
		}

		public void HabilitarPainel()
		{
			Habilitado = true;
			RecuperarFoco();
		}

		private bool PodeAplicarDescontoAcrescimo()
		{
			bool flag = Informacao.TextoToDecimal > 0m;
			if (!flag)
			{
				Informacao.Limpar();
			}
			return flag;
		}

		public void AplicarAcrescimo(decimal valorAcrescimo = 0m)
		{
			AutorizacaoDto autorizacaoDto = _sessaoService.VerificarPermissao<DigisatServer.Infrastructure.Crosscutting.Module.PontoDeVenda, PermitirDescontoAcrescimo>();
			if (autorizacaoDto == null)
			{
				return;
			}
			Seletor.Get<PainelDocumentoFiscal>()?.PreDocumentoFiscal?.AdicionarAutorizacao(autorizacaoDto);
			if (TotalIcmsDesonerado > 0m)
			{
				DialogoFactory.MostrarDialogoConfirma("Acréscimo não pode ser aplicado na totalização da venda que possui ICMS desonerado");
				return;
			}
			decimal num = ((valorAcrescimo > 0m) ? valorAcrescimo : ObterValorDescontoAcrescimo());
			if (num >= Subtotal || num <= 0m)
			{
				PainelMensagem.AlterarMensagemTimerComRetornoDaMensagemAnterior("Acréscimo inválido");
				Informacao.Limpar();
				return;
			}
			PainelDocumentoFiscal painelDocumentoFiscal = Seletor.Get<PainelDocumentoFiscal>();
			if (painelDocumentoFiscal != null && painelDocumentoFiscal.PreDocumentoFiscal.Itens.Any((ItemDocumentoFiscal x) => x.AplicouPromocaoScanntech))
			{
				PainelMensagem.AlterarMensagemTimerComRetornoDaMensagemAnterior("Acréscimo inválido pois possui promoção Scanntech ativada na venda");
				Informacao.Limpar();
			}
			else if (PossuiAcrescimoDesconto)
			{
				if (AcrescimoDesconto.Sigla.Equals("d"))
				{
					decimal num2 = num - AcrescimoDesconto.Valor;
					AcrescimoDesconto = ((num2 < 0m) ? Desconto.Criar().ComValor(num2 * -1m).ComAutorizacao(autorizacaoDto) : Acrescimo.Criar().ComValor(num2).ComAutorizacao(autorizacaoDto));
				}
				else
				{
					decimal valor = AcrescimoDesconto.Valor + num;
					AcrescimoDesconto = Acrescimo.Criar().ComValor(valor).ComAutorizacao(autorizacaoDto);
				}
			}
			else
			{
				AcrescimoDesconto = Acrescimo.Criar().ComValor(num).ComAutorizacao(autorizacaoDto);
			}
		}

		public void SomarAcrescimo(decimal valorAcrescimo, AutorizacaoDto autorizacao)
		{
			if (TotalIcmsDesonerado > 0m)
			{
				DialogoFactory.MostrarDialogoConfirma("Acréscimo não pode ser aplicado na totalização da venda que possui ICMS desonerado");
				return;
			}
			decimal num = ((valorAcrescimo > 0m) ? valorAcrescimo : ObterValorDescontoAcrescimo());
			if (num >= Subtotal || num <= 0m)
			{
				PainelMensagem.AlterarMensagemTimerComRetornoDaMensagemAnterior("Acréscimo inválido");
				Informacao.Limpar();
			}
			else
			{
				AcrescimoDesconto = Acrescimo.Criar().ComValor(num).ComAutorizacao(autorizacao);
				Seletor.Get<PainelDocumentoFiscal>()?.PreDocumentoFiscal.SetarComissaoSubsidiada(comissaoSubsidiada: true);
			}
		}

		public bool AplicarDesconto(bool descontoPrioritario = false)
		{
			AutorizacaoDto autorizacaoDto = _sessaoService.VerificarPermissao<DigisatServer.Infrastructure.Crosscutting.Module.PontoDeVenda, PermitirDescontoAcrescimo>();
			if (autorizacaoDto == null)
			{
				return false;
			}
			Seletor.Get<PainelDocumentoFiscal>()?.PreDocumentoFiscal?.AdicionarAutorizacao(autorizacaoDto);
			if (TotalIcmsDesonerado > 0m)
			{
				DialogoFactory.MostrarDialogoConfirma("Desconto não pode ser aplicado na totalização da venda que possui ICMS desonerado");
				return false;
			}
			decimal num = ObterValorDescontoAcrescimo();
			PainelDocumentoFiscal painelDocumentoFiscal = Seletor.Get<PainelDocumentoFiscal>();
			IEnumerable<ItemDocumentoFiscal> itens = painelDocumentoFiscal.PreDocumentoFiscal.Itens;
			decimal num2 = painelDocumentoFiscal.ValorLimiteDesconto;
			decimal num3 = itens.Where((ItemDocumentoFiscal x) => x.Ativo).Sum((ItemDocumentoFiscal x) => x.Desconto);
			decimal num4 = 0m;
			if (PossuiAcrescimoDesconto && AcrescimoDesconto.Sigla.Equals("d"))
			{
				num4 += AcrescimoDesconto.Valor;
			}
			decimal limiteUsuario = DadosSistema.LimiteDescontoUsuario;
			decimal num5 = itens.Where((ItemDocumentoFiscal x) => x.Ativo).Sum((ItemDocumentoFiscal x) => x.TotalBruto * limiteUsuario / 100m) - num4 - num3;
			decimal num6 = painelDocumentoFiscal.PreDocumentoFiscal.Itens.Where((ItemDocumentoFiscal x) => x.Ativo).Sum((ItemDocumentoFiscal x) => x.TotalBruto * x.LimiteDesconto / 100m) - num4 - num3;
			if (limiteUsuario > 0m)
			{
				num2 = ((num5 > num6) ? num5 : num6);
			}
			if (Subtotal < num || num <= 0m || num > num2)
			{
				bool flag = false;
				if (descontoPrioritario)
				{
					DialogoFactory.MostrarDialogoConfirma("Atenção! Desconto de cashback ultrapassa o limite de desconto, porém, ele é prioritário.");
					foreach (ItemDocumentoFiscal item in painelDocumentoFiscal.PreDocumentoFiscal?.Itens)
					{
						item.Autorizacao = new AutorizacaoDto
						{
							Data = DateTime.Now,
							Direito = new PermitirVenderAcimaDoLimiteDeDesconto().ProjectedAsDto(),
							NomeUsuario = DadosSistema.NomeUsuario
						};
					}
					flag = true;
				}
				else if (DialogoFactory.MostrarDialogoSimNaoInformacaoOculta($"Limite de desconto máximo para a venda é de: {num2.FormatarCampoValor(2)}", "Limite de desconto atingido. Continuar?").Equals(MessageBoxResult.Yes))
				{
					AutorizacaoDto autorizacaoLimite = _sessaoService.VerificarPermissao<MovimentacaoSaida, PermitirVenderAcimaDoLimiteDeDesconto>();
					Seletor.Get<PainelDocumentoFiscal>()?.PreDocumentoFiscal?.AdicionarAutorizacao(autorizacaoDto);
					if (autorizacaoLimite.IsNotNull())
					{
						num2 = itens.Where((ItemDocumentoFiscal x) => x.Ativo).Sum((ItemDocumentoFiscal x) => x.TotalBruto * autorizacaoLimite.LimiteDesconto / 100m) - num4 - num3;
						if (autorizacaoLimite.Direito.GetType() != typeof(DireitoDtoNull) || num2 >= num)
						{
							if (autorizacaoLimite.Direito.GetType() != typeof(DireitoDtoNull))
							{
								foreach (ItemDocumentoFiscal item2 in painelDocumentoFiscal.PreDocumentoFiscal?.Itens)
								{
									item2.Autorizacao = new AutorizacaoDto
									{
										Data = DateTime.Now,
										Direito = new PermitirVenderAcimaDoLimiteDeDesconto().ProjectedAsDto(),
										NomeUsuario = DadosSistema.NomeUsuario
									};
								}
							}
							flag = true;
						}
						else
						{
							DialogoFactory.MostrarDialogoConfirma($"Excedido o limite de desconto do usuario informado : {autorizacaoLimite.LimiteDesconto}%");
						}
					}
				}
				if (!flag)
				{
					Informacao.Limpar();
					return false;
				}
			}
			decimal? num7 = Seletor.Get<PainelDocumentoFiscal>()?.PreDocumentoFiscal?.Itens?.Where((ItemDocumentoFiscal x) => x.Ativo && x.IdPromocaoScanntech.IsNullOrEmpty()).Sum((ItemDocumentoFiscal a) => a.Total);
			decimal? num8 = num7;
			decimal num9 = ObterValorDescontoAcrescimo();
			if (num8.GetValueOrDefault() > num9 && num8.HasValue)
			{
				if (PossuiAcrescimoDesconto)
				{
					if (AcrescimoDesconto.Sigla.Equals("a"))
					{
						decimal num10 = AcrescimoDesconto.Valor - num;
						AcrescimoDesconto = ((num10 < 0m) ? Desconto.Criar().ComValor(num10 * -1m).ComAutorizacao(autorizacaoDto) : Acrescimo.Criar().ComValor(num10).ComAutorizacao(autorizacaoDto));
					}
					else
					{
						decimal valor = AcrescimoDesconto.Valor + num;
						AcrescimoDesconto = Desconto.Criar().ComValor(valor).ComAutorizacao(autorizacaoDto);
					}
				}
				else
				{
					AcrescimoDesconto = Desconto.Criar().ComValor(ObterValorDescontoAcrescimo()).ComAutorizacao(autorizacaoDto);
				}
				return true;
			}
			if (Informacao.TextoToDecimal == 100m)
			{
				num8 = num7;
				num9 = ObterValorDescontoAcrescimo();
				if (num8.GetValueOrDefault() == num9 && num8.HasValue)
				{
					AcrescimoDesconto = Desconto.Criar().ComValor(0.01m).ComAutorizacao(autorizacaoDto);
					return true;
				}
			}
			DialogoFactory.MostrarDialogoConfirma("Não pode ser aplicado pois o desconto é maior que a soma dos itens que ainda não possuem desconto");
			Informacao.Limpar();
			return false;
		}

		public decimal ObterValorDescontoAcrescimo()
		{
			decimal textoToDecimal = Informacao.TextoToDecimal;
			if (!Informacao.DescontoAcrescimoPercentual)
			{
				return textoToDecimal.TruncarDuasCasasDecimais();
			}
			decimal num = (((AcrescimoDesconto?.ValorCalculo ?? 0m) <= 0m) ? ((AcrescimoDesconto?.ValorCalculo ?? 0m) * -1m) : (AcrescimoDesconto?.ValorCalculo ?? 0m));
			textoToDecimal = decimal.Round((TotalBruto + num) * Informacao.TextoToDecimal / 100m, 2);
			return textoToDecimal.TruncarDuasCasasDecimais();
		}

