					.ToListEmptyWhenNull();
				IEnumerable<string> enumerable2 = Enumerable.Intersect(second: enumerable.SelectMany((Otus.Modulo.PontoDeVendas.Aggregates.Scanntech.PromocaoScanntech x) => x.Detalhe.Condicao.Itens.SelectMany((Otus.Modulo.PontoDeVendas.Aggregates.Scanntech.Item y) => y.Produtos.Select((Otus.Modulo.PontoDeVendas.Aggregates.Scanntech.Produto z) => z.CodigoBarras))).ToListEmptyWhenNull(), first: list?);
				if (enumerable2 != null && !enumerable2.Any())
