		{
			Seletor.Get<PainelDocumentoFiscal>()?.PreDocumentoFiscal?.ProcessarPromocoesScanntech(PromocoesScanntechElegiveis);
			Moedas = new Lista<IMoeda>();
			foreach (MoedaDto moeda in DadosSistema.Moedas)
