				Moedas.Adicionar(Moeda.Criar().ComDescricao(moeda.Descricao).ComCotacao(moeda.Cotacao)
					.Build());
			}
			IPainelDocumentoFiscal painelDocumentoFiscal = Seletor.Get<IPainelDocumentoFiscal>();
			if (painelDocumentoFiscal != null)
			{
				decimal totalBruto = (Subtotal = painelDocumentoFiscal.Subtotal + (AcrescimoDesconto?.ValorCalculo ?? 0m));
				TotalBruto = totalBruto;
			}
			if (!Lista.Itens.Any())
			{
				AdicionarEspeciesPagamento();
			}
			AdicionarMensagemPromocional(OperadorMensagemPromocional.Criar().ComOperador(_sessaoService.Sessao.NomeUsuario));
			Lista.PosicionarNoPrimeiro();
			AtualizarTotal();
			VerificarComissaoGarcom();
			VerificarCashback();
			VerificarMesaContaCredito();
			PainelDocumentoFiscal painelDocumentoFiscal2 = Seletor.Get<PainelDocumentoFiscal>();
			if (painelDocumentoFiscal2 != null && painelDocumentoFiscal2.PreDocumentoFiscal.Desconto > 0m)
			{
				AcrescimoDesconto = Desconto.Criar().ComValor(Seletor.Get<PainelDocumentoFiscal>()?.PreDocumentoFiscal.Desconto ?? 0m);
			}
			PainelDocumentoFiscal painelDocumentoFiscal3 = Seletor.Get<PainelDocumentoFiscal>();
			if (painelDocumentoFiscal3 != null && painelDocumentoFiscal3.PreDocumentoFiscal.OutrasDespesas > 0m)
			{
				AcrescimoDesconto = Acrescimo.Criar().ComValor(Seletor.Get<PainelDocumentoFiscal>()?.PreDocumentoFiscal.OutrasDespesas ?? 0m);
				Seletor.Get<PainelDocumentoFiscal>()?.PreDocumentoFiscal.SetarOutrasDespesas(0m);
			}
			ObservacaoFormaPagamento = Seletor.Get<PainelDocumentoFiscal>()?.PreDocumentoFiscal.ObservacaoFormaPagamento;
			PosicionarPagamentoIfood();
