		private void PosicionarPagamentoIfood()
		{
			if (VerificouPagamentoIfood)
			{
				return;
			}
			VerificouPagamentoIfood = true;
			MetodoPagamentoIfoodDto metodoPagamentoIfoodDto = Seletor.Get<PainelDocumentoFiscal>()?.PreDocumentoFiscal?.PagamentosIfood?.FirstOrDefault();
			if (metodoPagamentoIfoodDto.IsNull() || metodoPagamentoIfoodDto.Valor <= 0m || Lista.Itens.Sum((ItemPagamentoViewModel x) => x.Valor) > 0m)
			{
				return;
			}
			int especie = ObterEspeciePagamentoIfood(metodoPagamentoIfoodDto.Metodo);
			if (Lista.Itens.Any((ItemPagamentoViewModel x) => x.EspeciePagamentoPosicionar == especie))
			{
				decimal num = Math.Max(Subtotal - Lista.Itens.Sum((ItemPagamentoViewModel x) => x.Valor), 0m);
				decimal valor = ((especie == 1 && metodoPagamentoIfoodDto.TrocoPara > num) ? metodoPagamentoIfoodDto.TrocoPara : Math.Min(metodoPagamentoIfoodDto.Valor, num));
				Lista.Posicionar((ItemPagamentoViewModel x) => x.EspeciePagamentoPosicionar == especie);
				Informacao.Texto = valor.FormatarCampoValor(2);
			}
		}

		private static int ObterEspeciePagamentoIfood(string metodo)
		{
			switch (metodo?.Trim().ToUpperInvariant())
			{
			case "CASH":
				return 1;
			case "CREDIT":
			case "DEBIT":
			case "WALLET":
			case "DIGITAL_WALLET":
				return 7;
			case "MEAL_VOUCHER":
			case "FOOD_VOUCHER":
				return 5;
			case "PIX":
				return 24;
			default:
				return 0;
			}
		}

		private void VerificarCashback()
		{
			try
			{
				if (VerificouCashback)
				{
					return;
				}
				decimal num = Consumidor?.TotalCashback.TruncarDuasCasasDecimais() ?? 0m;
				if (num <= 0m || !DadosSistema.ConfiguracaoDto.Saida.SolicitarUtilizarCashbackAcimaValorEstipuladoDocumentoFiscal.Valor || num < DadosSistema.ConfiguracaoDto.Saida.ValorEstipuladoSolicitarCashbackDocumentoFiscal.Valor)
				{
					return;
				}
				string empty = string.Empty;
				empty += $"O total de cashback do cliente é {num:C2}.\n";
				if (DadosSistema.ConfiguracaoDto.Saida.LimitarUtilizacaoValorCashback.Valor && DadosSistema.ConfiguracaoDto.Saida.PercentualLimiteValorUtilizacaoCashBack.Valor > 0m)
				{
					switch (DadosSistema.ConfiguracaoDto.Saida.TiposLimiteValorCashback.Valor)
					{
					case 1:
						num = (Subtotal * DadosSistema.ConfiguracaoDto.Saida.PercentualLimiteValorUtilizacaoCashBack.Valor / 100m).TruncarDuasCasasDecimais();
						break;
					case 2:
						num = (num * DadosSistema.ConfiguracaoDto.Saida.PercentualLimiteValorUtilizacaoCashBack.Valor / 100m).TruncarDuasCasasDecimais();
						break;
					}
					if (num > (Consumidor?.TotalCashback ?? 0m))
					{
						num = Consumidor?.TotalCashback ?? 0m;
					}
					else
					{
						empty = empty + $"Máximo de cashback a ser utilizado nessa compra é {DadosSistema.ConfiguracaoDto.Saida.PercentualLimiteValorUtilizacaoCashBack.Valor}%, " + $"correspondente a {num:C2}.\n";
					}
				}
				if (Subtotal <= num)
				{
					decimal subtotal = Subtotal;
					decimal value = 0.01m;
					decimal? num2 = Seletor.Get<PainelDocumentoFiscal>()?.PreDocumentoFiscal?.Itens?.Where((ItemDocumentoFiscal x) => x.Ativo).Count();
					num = subtotal - (((decimal?)value * num2) ?? 0m);
					empty += "O valor mínimo do item deverá ser de R$ 0,01.\n";
				}
				MessageBoxResult messageBoxResult = DialogoFactory.MostrarDialogoSimNaoDoar($"{empty}\nDeseja utilizar o cashback até completar o desconto?");
				VerificouCashback = true;
				switch (messageBoxResult)
				{
				case MessageBoxResult.Yes:
				{
					AutorizacaoDto autorizacaoDto = DadosSistema.AutenticacaoService.Instancia.VerificarPermissao<DigisatServer.Infrastructure.Crosscutting.Module.PontoDeVenda, PermitirDescontarCashback>();
					if (autorizacaoDto != null)
					{
						Seletor.Get<PainelDocumentoFiscal>()?.PreDocumentoFiscal?.AdicionarAutorizacao(autorizacaoDto);
						Informacao.Texto = num.FormatarCampoValor(3);
						AplicarDesconto(descontoPrioritario: true);
						UtilizouCashback = true;
						ValorCashbackUtilizado = num;
						Informacao.ControlarFoco();
					}
					break;
				}
				case MessageBoxResult.No:
					Informacao.ControlarFoco();
					UtilizouCashback = false;
					ValorCashbackUtilizado = 0m;
					break;
				case MessageBoxResult.OK:
				{
					IEnumerable<PessoaDto> enumerable = DadosSistema.GetService().Canal((IPessoaModuleService service) => service.ObterPessoasReceptorasDoacaoCashBack());
					if (enumerable.Any())
					{
						decimal informacao = Consumidor?.TotalCashback.TruncarDuasCasasDecimais() ?? 0m;
						while (true)
						{
							string arg = "";
							decimal num3 = informacao;
							decimal? num4 = Consumidor?.TotalCashback.TruncarDuasCasasDecimais();
							if (!(num3 == num4.GetValueOrDefault()) || !num4.HasValue)
							{
								informacao = Consumidor?.TotalCashback.TruncarDuasCasasDecimais() ?? 0m;
								arg = "Valor informado é inválido!\n\n";
							}
							messageBoxResult = DialogoFactory.MostrarDialogoEntradaDecimal(ref informacao, "Valor", $"{arg}Informe o valor a ser doado.\nCashback disponivel R$ {Consumidor?.TotalCashback.TruncarDuasCasasDecimais():C2}.");
							if (messageBoxResult != MessageBoxResult.OK)
							{
								return;
							}
							if (informacao > 0m)
							{
								decimal num5 = informacao;
								num4 = Consumidor?.TotalCashback.TruncarDuasCasasDecimais();
								if (num5 <= num4.GetValueOrDefault() && num4.HasValue)
								{
									break;
								}
							}
						}
						PessoaDto pessoaDto = ((enumerable.Count() == 1) ? enumerable.FirstOrDefault() : DialogoFactory.MostrarDialogoComboBox("Selecione uma pessoa para doação do cashback", "Pessoas", enumerable, "Nome"));
						PessoaDto pessoaOrigemReferencia = DadosSistema.GetService().Canal((IPessoaModuleService service) => service.ObterPessoaPorId(Consumidor.Pessoa?.Id.ToString()));
						if (pessoaDto.IsNotNull())
						{
							TransferirCashback(new TransferenciaCashbackDto
							{
								PessoaDestinoReferencia = pessoaDto,
								PessoaOrigemReferencia = pessoaOrigemReferencia,
								Valor = informacao,
								Doacao = true
							});
						}
					}
					else
					{
						DialogoFactory.MostrarDialogoConfirma("Nenhuma pessoa para doação do cashback foi localizada");
					}
					Consumidor.AtualizarClienteDto();
					Informacao.ControlarFoco();
					UtilizouCashback = false;
					ValorCashbackUtilizado = 0m;
					if (Consumidor.TotalCashback > 0m)
					{
						VerificouCashback = false;
						VerificarCashback();
					}
					VerificouCashback = true;
					break;
				}
				}
			}
			catch (Exception value2)
			{
				Console.WriteLine(value2);
				throw;
			}
		}

		public void TransferirCashback(TransferenciaCashbackDto transferenciaCashbackDto)
		{
			try
			{
				AutorizacaoDto autorizacaoDto = DadosSistema.AutenticacaoService.Instancia.VerificarPermissao<DigisatServer.Infrastructure.Crosscutting.Module.PontoDeVenda, PermitirTransferirCashback>();
				if (autorizacaoDto != null)
				{
					Seletor.Get<PainelDocumentoFiscal>()?.PreDocumentoFiscal?.AdicionarAutorizacao(autorizacaoDto);
					DadosSistema.GetService().Canal((IGestaoCashbackModuleService service) =>
					{
						service.TransferirCashback(transferenciaCashbackDto);
					});
					Seletor.Get<PainelTotalizacaoBase>().AdicionarMensagemPromocional(TextoLivreMensagemPromocional.Criar().ComLinha1($"Cashback doado para {transferenciaCashbackDto.PessoaDestinoReferencia.Nome}"));
					DialogoFactory.MostrarDialogoConfirma("Doação de cashback realizada com sucesso");
				}
			}
			catch (Exception ex)
			{
				DialogoFactory.MostrarDialogoConfirma(ex.InnerException?.Message ?? ex.Message);
			}
		}

