		private void VerificarComissaoGarcom()
		{
			if (!DadosSistema.IsRestauranteOuHotel || VerificouComissaoGarcom)
			{
				return;
			}
			PreDocumentoFiscal preDocumentoFiscal = Seletor.Get<PainelDocumentoFiscal>().PreDocumentoFiscal;
			List<ItemDocumentoFiscal> itens = preDocumentoFiscal.Itens.Where((ItemDocumentoFiscal x) => x.Vendedor.IsNotNull() && x.Vendedor.PessoaHistorico.IsNotNull()).ToListEmptyWhenNull();
			List<ItemComissaoLocal> source = (from arg in (from g in itens
					group g by new
					{
						g.Vendedor.Id,
						g.Vendedor.Nome,
						g.ProdutoServicoLocal.ProdutoServicoHistorico.PercentualComissao,
						g.Vendedor.PessoaHistorico.To<FisicaHistorico>().Vendedor.BaseCalculoComissao
					}).ToListEmptyWhenNull()
				select new ItemComissaoLocal(arg.Key.Id, arg.Key.Nome, arg.Key.PercentualComissao, arg.Key.BaseCalculoComissao, itens.Where((ItemDocumentoFiscal x) => x.Vendedor.IsNotNull() && x.Vendedor.Id == arg.Key.Id && x.ProdutoServicoLocal.ProdutoServicoHistorico.PercentualComissao == arg.Key.PercentualComissao))).ToListEmptyWhenNull();
			if ((!source.Any() || source.Sum((ItemComissaoLocal a) => a.ValorComissao) <= 0m) && DadosSistema.ConfiguracaoDto.Saida.CouvertArtistico.Valor <= 0m)
			{
				return;
			}
			int num = preDocumentoFiscal.NumerosMesasContasClientesImportadas?.Count() ?? 1;
			if (DialogoFactory.MostrarDialogoConfirmaAcrescimos(out var totalAcrescimos, "Adicionar acréscimos no documento fiscal?", Subtotal, source.Sum((ItemComissaoLocal x) => x.ValorComissao), (num == 0) ? 1 : num, DadosSistema.ConfiguracaoDto.Saida.CouvertArtistico.Valor, VerificarPermissaoOptarPorNaoSomarComissao(), DadosSistema.VerificarPermissao<DigisatServer.Infrastructure.Crosscutting.Module.PontoDeVenda, PermitirOptarPorNaoSomarComissao>()) == MessageBoxResult.OK)
			{
				SomarAcrescimo(totalAcrescimos, null);
			}
			else
			{
				AutorizacaoDto autorizacaoDto = _sessaoService.VerificarPermissao<DigisatServer.Infrastructure.Crosscutting.Module.PontoDeVenda, PermitirOptarPorNaoSomarComissao>();
				if (autorizacaoDto == null)
				{
					FecharMethod();
					Seletor.Voltar();
					DormirAsync(500, (object x) =>
					{
						SeletorEsquerdo.VoltarTudo();
					});
					return;
				}
				Seletor.Get<PainelDocumentoFiscal>()?.PreDocumentoFiscal?.AdicionarAutorizacao(autorizacaoDto);
				Seletor.Get<PainelDocumentoFiscal>()?.PreDocumentoFiscal.SetarComissaoSubsidiada(comissaoSubsidiada: false);
			}
			VerificouComissaoGarcom = true;
			Informacao.ControlarFoco();
		}

		public Func<bool> VerificarPermissaoOptarPorNaoSomarComissao()
		{
			return () => !_sessaoService.VerificarPermissao<DigisatServer.Infrastructure.Crosscutting.Module.PontoDeVenda, PermitirOptarPorNaoSomarComissao>().IsNull();
		}

		private async void VerificarMesaContaCredito()
		{
			if (!DadosSistema.IsRestauranteOuHotel)
			{
				return;
			}
			IEnumerable<long> numerosMesasContasImportadas = Seletor.Get<PainelDocumentoFiscal>().PreDocumentoFiscal?.NumerosMesasContasClientesImportadas;
			if (numerosMesasContasImportadas.IsNull() || !numerosMesasContasImportadas.Any() || VerificouMesaContaCredito)
			{
				return;
			}
			VerificouMesaContaCredito = true;
			await DadosSistema.GetService().Canal((IRestauranteModuleService x) => x.ObterMesaContaCreditoNaoUtilizado(numerosMesasContasImportadas, setarComoUtilizados: true)).ContinueWith((Task<IEnumerable<MesaContaCreditoDto>> task) =>
			{
				ThreadPrincipal.Executar(() =>
				{
					if (task.IsFaulted)
					{
						task.Exception.ShowLastException();
					}
					else if (task.Result.Any())
					{
						DialogoFactory.MostrarDialogoConfirma($"Existem créditos adicionados na {DadosSistema.TipoRestaurante}.\nOs mesmos serão lançados automaticamente.");
						foreach (MesaContaCreditoDto mesaContaCredito in task.Result)
						{
							switch (mesaContaCredito.EspecieRecebimento.Codigo)
							{
							case 1:
								Lista.Posicionar((ItemPagamentoViewModel x) => x.EspeciePagamentoPosicionar == 1);
								Informacao.Texto = mesaContaCredito.Valor.FormatarCampoValor(2);
								AdicionarItem(Lista.ItemSelecionado.EspeciePagamento.Codigo);
								break;
							case 3:
								Lista.Posicionar((ItemPagamentoViewModel x) => x.EspeciePagamentoPosicionar == 2);
								Informacao.Texto = mesaContaCredito.Valor.FormatarCampoValor(2);
								if (!Lista.Itens.Any((ItemPagamentoViewModel x) => x.Is<ICartao>()))
								{
									DadosSistema.GetService().Canal((IRestauranteModuleService x) =>
									{
										x.SetarMesaContaCreditoParaNaoUtilizado(mesaContaCredito.Id);
									});
									DialogoFactory.MostrarDialogoConfirma("Nenhuma espécie Cartão foi encontrada");
									Seletor.VoltarTudo();
									return;
								}
								Lista.ItemSelecionado.To<ICartao>().AdicionarCartaoResposta(mesaContaCredito.PagamentoTransacaoCartao.Morfar());
								break;
							case 5:
							{
								Lista.Posicionar((ItemPagamentoViewModel x) => x.EspeciePagamentoPosicionar == 7);
								RedePosDto pagamentoTransacaoCartaoPos = mesaContaCredito.PagamentoTransacaoCartaoPos;
								RedePosLocal redePosLocal = RedePosLocal.Criar().ComPessoa(pagamentoTransacaoCartaoPos.Pessoa.Morfar()).ComDescricao(pagamentoTransacaoCartaoPos.Descricao)
									.ComOperacaoRedePos((pagamentoTransacaoCartaoPos.OperacaoRedePos == 3) ? OperacaoRedePos.Credito : OperacaoRedePos.Debito)
									.ComCodigoAutorizacao(pagamentoTransacaoCartaoPos.CodigoAutorizacao)
									.ComCodigoPagamentoNsu(pagamentoTransacaoCartaoPos.CodigoPagamentoNsu)
									.ComTaxas(new List<Taxa> { pagamentoTransacaoCartaoPos.Taxa.Morfar() })
									.Build();
								redePosLocal.SomarValor(pagamentoTransacaoCartaoPos.Valor);
								Informacao.Texto = mesaContaCredito.Valor.FormatarCampoValor(2);
								redePosLocal.SetarTaxaSelecionada(new TaxaViewModel(pagamentoTransacaoCartaoPos.Taxa.Morfar(), pagamentoTransacaoCartaoPos.Taxa.Descricao));
								Lista.ItemSelecionado.To<ICartaoPos>().Adicionar(redePosLocal);
								break;
							}
							case 21:
								Lista.Posicionar((ItemPagamentoViewModel x) => x.EspeciePagamentoPosicionar == 24);
								Informacao.Texto = mesaContaCredito.Valor.FormatarCampoValor(2);
								Lista.ItemSelecionado.To<ICarteiraDigital>().AdicionarCartaoResposta(mesaContaCredito.PagamentoTransacaoCarteiraDigital.Morfar());
								break;
							case 25:
								Lista.Posicionar((ItemPagamentoViewModel x) => x.EspeciePagamentoPosicionar == 25);
								Informacao.Texto = mesaContaCredito.Valor.FormatarCampoValor(2);
								if (!Lista.ItemSelecionado.EspeciePagamentoPosicionar.Equals(25))
								{
									DadosSistema.GetService().Canal((IRestauranteModuleService x) =>
									{
										x.SetarMesaContaCreditoParaNaoUtilizado(mesaContaCredito.Id);
									});
									DialogoFactory.MostrarDialogoConfirma("Nenhuma espécie Carteira Digital - SHIPAY foi encontrada");
									Seletor.VoltarTudo();
									return;
								}
								Lista.ItemSelecionado.To<ICarteiraDigital>().AdicionarCartaoResposta(mesaContaCredito.PagamentoTransacaoCarteiraDigitalShipay.Morfar());
								break;
							case 22:
								Lista.Posicionar((ItemPagamentoViewModel x) => x.EspeciePagamentoPosicionar == 27);
								Informacao.Texto = mesaContaCredito.Valor.FormatarCampoValor(2);
								Lista.ItemSelecionado.To<ITerminalPos>().AdicionarPagamentoTransacao(mesaContaCredito.PagamentoTransacaoTerminalPos);
								break;
							}
							Informacao.Texto = mesaContaCredito.Valor.FormatarCampoValor(2);
							Lista.Posicionar((ItemPagamentoViewModel x) => x.EspeciePagamentoPosicionar == 1);
							AtualizarTotal();
						}
						Seletor.Get<PainelDocumentoFiscal>().PreDocumentoFiscal.SetarReferenciasCreditoMesaConta(task.Result.Select((MesaContaCreditoDto x) => x.Id));
						Informacao.ControlarFoco();
					}
				});
			});
		}

		public void AdicionarMensagemPromocional(IMensagemPromocional mensagemPromocional)
		{
			if (mensagemPromocional != null)
			{
				RemoverMensagemPromocional<TextoLivreMensagemPromocional>(mensagemPromocional);
				RemoverMensagemPromocional<TributoMensagemPromocional>(mensagemPromocional);
				RemoverMensagemPromocional<VendedorMensagemPromocional>(mensagemPromocional);
				RemoverMensagemPromocional<ObservacaoMensagemPromocional>(mensagemPromocional);
				RemoverMensagemPromocional<ObservacaoPostoMensagemPromocional>(mensagemPromocional);
				if (_mensagensPromocionais.All((IMensagemPromocional x) => x.GetType().Name != mensagemPromocional.GetType().Name || x.GetType() == typeof(ReferenciaSistemaAbastecimentoMensagemPromocional) || x.GetType() == typeof(MesaContaMensagemPromocional)))
				{
					_mensagensPromocionais.Add(mensagemPromocional);
				}
			}
		}

		public void RemoverMensagemPromocional<T>(IMensagemPromocional mensagemPromocional)
		{
			if (mensagemPromocional.Is<T>())
			{
				IMensagemPromocional mensagemPromocional2 = _mensagensPromocionais.FirstOrDefault((IMensagemPromocional x) => x.Is<T>());
				if (mensagemPromocional2 != null)
				{
					_mensagensPromocionais.Remove(mensagemPromocional2);
				}
			}
		}

		public void LimparMensagensPromocionais()
		{
			_mensagensPromocionais.Clear();
		}

		public void AtualizarTotal()
		{
			decimal num = Subtotal - Lista.Itens.Sum((ItemPagamentoViewModel x) => x.Valor);
			decimal num2 = ((num < 0m) ? (num * -1m) : num);
			if (DadosSistema.ConfiguracaoDto.Saida.AlertarUsuarioTrocoAcimaEstipulado.Valor && num2 > DadosSistema.ConfiguracaoDto.Saida.TrocoEstipuladoAlertar.Valor && Lista.Itens.Any((ItemPagamentoViewModel x) => x.Valor > 0m) && num < 0m)
			{
				DialogoFactory.MostrarDialogoConfirma("Valor de troco elevado.");
				foreach (ItemPagamentoViewModel iten in Lista.Itens)
				{
					iten.Zerar();
				}
				RaisePropertyChanged(() => Lista);
				AtualizarTotal();
			}
			else
			{
				Troco = num2;
			}
			Informacao.Limpar();
		}

		public override bool PodeVoltar()
		{
			if (!IniciouFinalizacao)
			{
				return Lista.Itens.Where((ItemPagamentoViewModel a) => a.IsNot<IDinheiro>() && a.IsNot<IDepositoBancario>() && a.IsNot<ITed>() && a.IsNot<ICreditoLoja>() && a.IsNot<IValePresente>() && a.IsNot<IValeDetalhado>() && a.IsNot<IPrazo>() && a.IsNot<ICheque>() && a.IsNot<ICartaoPos>() && a.IsNot<IDoc>()).All((ItemPagamentoViewModel x) => x.Valor == 0m);
			}
			return false;
		}

