		}

		protected virtual void FinalizarDocumentoFiscal()
		{
		}

		protected virtual void ReiniciarVariaveis()
		{
			_navegouPainelPromocaoScanntechMeioPagamento = false;
			BinInformado = null;
			Debito = false;
			IniciouFinalizacao = false;
			IniciouRecebimentoDeValores = false;
			HabilitarPainel();
			ContraVale = 0m;
			ContraValePresente = null;
			Lista.Limpar();
			AcrescimoDesconto = null;
			RestaTroco = string.Empty;
			Subtotal = 0m;
			LimparMensagensPromocionais();
			ObservacaoFormaPagamento = null;
			VerificouComissaoGarcom = false;
			VerificouCashback = false;
			UtilizouCashback = false;
			ValorCashbackUtilizado = 0m;
			VerificouMesaContaCredito = false;
			VerificouPagamentoIfood = false;
			if (Seletor.Get<PainelDocumentoFiscal>()?.PreDocumentoFiscal?.Tickets.Any() ?? false)
			{
				Seletor.Get<PainelDocumentoFiscal>()?.PreDocumentoFiscal?.RemoverAcrescimoDesconto();
				Seletor.Get<PainelDocumentoFiscal>()?.PreDocumentoFiscal?.LimparTickets();
			}
		}

		protected virtual void TerminarFinalizacaoDocumentoFiscal()
		{
			PreDocumentoFiscal preDocumentoFiscal = Seletor.Get<PainelDocumentoFiscal>().PreDocumentoFiscal;
			preDocumentoFiscal.SetarPagamentos(ContraVale, Lista.Itens.ToArray());
			PreencherObservacaoComMensagemPromocional(preDocumentoFiscal);
			preDocumentoFiscal.SetarAcrescimoDesconto(AcrescimoDesconto);
			preDocumentoFiscal.SetarUtilizouCashback(UtilizouCashback, ValorCashbackUtilizado);
			preDocumentoFiscal.Efetivar(EmissorService.Tipo);
			Seletor.Get<IPainelDocumentoFiscal>().FinalizarDocumentoFiscal();
			string text = $"TROCO: Real: {Troco:n2}   ";
			string text2 = (Moedas.Itens.Any() ? string.Join("   ", Moedas.Itens.Select((IMoeda x) => $"{x.Descricao}: {x.Valor:n2}")) : string.Empty);
			text += text2;
			PainelTitulo.AlterarTituloTimer(text, 30.0);
			ReiniciarVariaveis();
			Seletor.Voltar();
			Seletor.Get<PainelDocumentoFiscal>().Informacao.ControlarFoco();
			if (DadosSistema.PodeAbrirImportacaoMesaContaAoFinalizarDocumentoFiscal())
			{
				Seletor.Selecionar<PainelImportarMesaConta>();
			}
		}

		public virtual void Cancelar()
		{
			IniciouFinalizacao = false;
			IniciouRecebimentoDeValores = false;
			AutorizacaoDto autorizacaoDto = _sessaoService.VerificarPermissao<DigisatServer.Infrastructure.Crosscutting.Module.PontoDeVenda, PermitirCancelarDocumentoFiscal>();
			if (autorizacaoDto == null)
			{
				return;
			}
			try
			{
				LoaderProcessoService.EsconderLoader();
				Seletor.Get<PainelDocumentoFiscal>()?.PreDocumentoFiscal?.AdicionarAutorizacao(autorizacaoDto);
				ExecutarCancelamento();
				Seletor.Get<IPainelDocumentoFiscal>().FinalizarDocumentoFiscal();
				PainelTitulo.ForcarLimparTitulo();
				ReiniciarVariaveis();
				Seletor.Voltar();
			}
			catch (Exception ex)
			{
				DialogoFactory.MostrarDialogoConfirma(ex.Message);
			}
		}

		protected virtual void ExecutarCancelamento()
		{
		}

		public override void FecharMethod()
		{
			if (PodeVoltar())
			{
				bool? flag = Seletor.Get<PainelDocumentoFiscal>()?.PreDocumentoFiscal?.ReferenciasCreditoMesaConta.IsNotNull();
				if (flag.HasValue && flag == true && (Seletor.Get<PainelDocumentoFiscal>()?.PreDocumentoFiscal?.ReferenciasCreditoMesaConta.Any() ?? false))
				{
					DadosSistema.GetService().Canal((IRestauranteModuleService x) =>
					{
						x.ReabrirCreditosMesasContas(Seletor.Get<PainelDocumentoFiscal>().PreDocumentoFiscal.ReferenciasCreditoMesaConta);
					});
				}
			}
			RemoverMensagemPromocional<ObservacaoMensagemPromocional>(ObservacaoMensagemPromocional.Criar());
			Seletor.Get<PainelTotalizacaoEmissorBase>().LimparParcelas();
			base.FecharMethod();
			Lista.Limpar();
			_navegouPainelPromocaoScanntechMeioPagamento = false;
			BinInformado = null;
			Debito = false;
			VerificouComissaoGarcom = false;
			VerificouCashback = false;
			UtilizouCashback = false;
			ValorCashbackUtilizado = 0m;
			VerificouMesaContaCredito = false;
			VerificouPagamentoIfood = false;
			_selecionouTef = false;
		}

		protected void PreencherObservacaoComMensagemPromocional(PreDocumentoFiscal preDocumentoFiscal)
		{
			preDocumentoFiscal.SetarObservacao(string.Join(Environment.NewLine, MensagensPromocionais.Where((IMensagemPromocional x) => !(x is TributoMensagemPromocional)).SelectMany((IMensagemPromocional x) => x.Linhas)));
		}

		public PreDocumentoFiscal ObterPreDocumentoFiscal()
		{
			return Seletor.Get<PainelDocumentoFiscal>().PreDocumentoFiscal;
		}

