		}

		public PainelTotalizacaoCupomFiscal(Otus.Modulo.PontoDeVendas.Interfaces.ITefService tefService, EcfService ecfService, IEventPublisher eventPublisher, ISessaoService sessaoService, Seletor<IPainel> seletorDireito, IImpressoraNaoFiscalService impressoraNaoFiscalService, Seletor<IPainel> seletorEsquerdo, IFarmaciaService farmaciaService, IConfiguracaoClientService configuracaoClientService, IRepositoryBaseWrite<ValorSangriaLocal> valorSangriaRepositoryWrite, IRepositoryRead<ValorSangriaLocal> valorSangriaRepositoryRead, IMobileService mobileService)
			: base(tefService, ecfService, sessaoService, eventPublisher, seletorDireito, impressoraNaoFiscalService, seletorEsquerdo, farmaciaService, configuracaoClientService, valorSangriaRepositoryWrite, valorSangriaRepositoryRead, mobileService)
		{
			_sessaoService = sessaoService;
		}

		protected override void FinalizarDocumentoFiscal()
		{
			if (_sessaoService.Sessao.Perfis.ItemSelecionado.Empresa.Municipio.Uf.CodigoIbge == 25)
			{
				AdicionarMensagemPromocional(ParaibaLegalMensagemPromocional.Criar().ComData(EmissorService.RetornarDataEmissao()).ComCoo(EmissorService.RetornarContadorOrdemOperacao())
					.ComIe(_sessaoService.Sessao.Perfis.ItemSelecionado.Empresa.Ie)
					.ComTotal(Subtotal));
			}
			if (Seletor.Get<PainelDocumentoFiscal>().TemAbastecimento)
			{
				foreach (ItemDocumentoFiscalCombustivel item in Seletor.Get<PainelDocumentoFiscal>().Lista.Itens.OfType<ItemDocumentoFiscalCombustivel>())
				{
					AdicionarMensagemPromocional(ReferenciaSistemaAbastecimentoMensagemPromocional.Criar().ComNumeroBico(item.Abastecimento.NumeroDoBicoNoSoftware).ComEncerranteInicial(item.Abastecimento.EncerranteInicial)
						.ComEncerranteFinal(item.Abastecimento.EncerranteFinal)
						.ComLitros(item.Abastecimento.Litros)
						.ComItemCancelado(!item.Ativo)
						.ComCupomManual(item.RegistroAbastecimentoManual)
						.Build());
				}
			}
			base.FinalizarDocumentoFiscal();
		}

		protected override void AdicionarEspeciesPagamento()
		{
			base.AdicionarEspeciesPagamento();
			if (DadosSistema.IsRestauranteOuHotel && EspecieVisivel(5))
			{
				Lista.Adicionar(ItemPagamentoRestaurante<ValeRestauranteViewModel, ValeViewModel>.Criar().ComSeletorEsquerdo(SeletorEsquerdo));
			}
			else if (EspecieVisivel(5))
			{
				Lista.Adicionar(ValeViewModel.Criar());
			}
		}
	}
