				Lista.Posicionar((ItemPagamentoViewModel x) => x.EspeciePagamentoPosicionar == 5);
				AdicionarItem(5);
			}, PodePagar);
			if (DadosSistema.PodeExecutarFuncao(typeof(Gerencial), typeof(Administrador), typeof(AdministradorIndustria)) || DadosSistema.ContemModuloAdicional(106))
			{
