		public override void Load()
		{
			_events?.Dispose();
			_events = new CompositeDisposable
			{
				EmissorService.WhenEmissorTerminouDocumentoFiscalEvent.Subscribe((long numeroDocumento) =>
				{
					PreDocumentoFiscal preDocumentoFiscal = Seletor.Get<PainelDocumentoFiscal>().PreDocumentoFiscal;
					long ccf = (EmissorService.Is<IEcfService>() ? preDocumentoFiscal.Ccf : numeroDocumento);
					EmissorService.AdicionarRelatorioGerencialContraVale(RelatoriosEmissor.RetornarRelatorioGerencialContraVale(numeroDocumento, ContraVale, EmissorService.Is<IEcfService>()));
					EmissorService.AdicionarRelatorioGerencialContraValePresente(RelatoriosEmissor.RetornarRelatorioGerencialContraValePresente(ContraValePresente, EmissorService.Is<IEcfService>()));
					EmissorService.AdicionarRelatorioGerencialParcelamento(RelatoriosEmissor.RetornarRelatorioGerencialParcelamento(ccf, preDocumentoFiscal.DataInicioEmissao, EmissorService.RetornarContadorOrdemOperacao(), Consumidor, Parcelas.OfType<ParcelaPrazo>()));
					DadosConsumidorRelatorioCarne consumidor = DadosConsumidorRelatorioCarne.Criar().ComNome(Consumidor?.Pessoa?.Nome).ComCpfCnpjFormatado(Consumidor?.Pessoa?.CpfCnpjFormatado)
						.ComEnderecoToText(Consumidor?.Pessoa?.Carteira?.EnderecoPrincipal?.ToText);
					List<DadosParcelaRelatorioCarne> parcelas = (from x in Parcelas.OfType<ParcelaPrazo>()
						select DadosParcelaRelatorioCarne.Criar().ComOrdem(x.Ordem).ComVencimento(x.Vencimento)
							.ComValor(x.Valor)
							.ComReferencia(x.Referencia)).ToListEmptyWhenNull();
					EmissorService.AdicionarDadosRelatorioCarne(RelatoriosEmissor.RetornarDadosRelatorioCarne(numeroDocumento, preDocumentoFiscal.DataInicioEmissao, consumidor, parcelas));
					EmissorService.AdicionarRelatorioGerencialSeriaisVendidos(RelatoriosEmissor.RetornarRelatorioGerencialSeriaisVendidos(numeroDocumento, from x in Seletor.Get<PainelDocumentoFiscal>().Lista.Itens.OfType<ItemDocumentoFiscalProduto>()
						where x.Ativo
						select x, EmissorService.Is<IEcfService>()));
					GerarImpressosPedidoRestaurante(preDocumentoFiscal, numeroDocumento.ToString());
					GerarPedidoPainelPedidoRestaurante(numeroDocumento, preDocumentoFiscal.Itens);
					if (DadosSistema.IsFarmacia && !string.IsNullOrWhiteSpace(preDocumentoFiscal.IdFarmaciaPopular))
					{
						Seletor.Get<PainelDocumentoFiscal>().ConfirmarAutorizacaoFarmaciaPopular(numeroDocumento).ContinueWith((Task<IEnumerable<string>> task2) =>
						{
							PainelTotalizacaoEmissorBase painelTotalizacaoEmissorBase = this;
							IRetornoConsulta retornoConsultaPbm3 = preDocumentoFiscal.RetornoConsultaPbm;
							painelTotalizacaoEmissorBase.ProcessarConfirmacaoVenda(task2, retornoConsultaPbm3 != null && retornoConsultaPbm3.TipoPbm == TipoPbm.PortalDrogaria, EmissorService.AdicionarRelatorioGerencialFarmaciaPopular, numeroDocumento);
						});
					}
					else if (DadosSistema.IsFarmacia && preDocumentoFiscal.RetornoConsultaPbm.IsNotNull())
					{
						IRetornoConsulta retornoConsultaPbm = preDocumentoFiscal.RetornoConsultaPbm;
						if (retornoConsultaPbm != null && retornoConsultaPbm.TipoPbm == TipoPbm.PortalDrogaria)
						{
							Task<IEnumerable<string>> task = Task.Factory.StartNew(() => preDocumentoFiscal.ComprovantePortalDrogaria);
							IRetornoConsulta retornoConsultaPbm2 = preDocumentoFiscal.RetornoConsultaPbm;
							ProcessarConfirmacaoVenda(task, retornoConsultaPbm2 != null && retornoConsultaPbm2.TipoPbm == TipoPbm.PortalDrogaria, EmissorService.AdicionarRelatorioGerencialFarmaciaPbm, numeroDocumento);
						}
						else
						{
							Task.Run(() => _farmaciaService.ConfirmarVenda(preDocumentoFiscal, ccf, preDocumentoFiscal.RetornoConsultaPbm.NumeroAutorizacao, preDocumentoFiscal.RetornoConsultaPbm.Operadora, preDocumentoFiscal.RetornoConsultaPbm.CnpjEstabelecimento, preDocumentoFiscal.RetornoConsultaPbm.DadosComplementares)).ContinueWith((Task<IEnumerable<string>> task2) =>
							{
								PainelTotalizacaoEmissorBase painelTotalizacaoEmissorBase = this;
								IRetornoConsulta retornoConsultaPbm3 = preDocumentoFiscal.RetornoConsultaPbm;
								painelTotalizacaoEmissorBase.ProcessarConfirmacaoVenda(task2, retornoConsultaPbm3 != null && retornoConsultaPbm3.TipoPbm == TipoPbm.PortalDrogaria, EmissorService.AdicionarRelatorioGerencialFarmaciaPbm, numeroDocumento);
							});
						}
					}
					else
					{
						System.Windows.Application.Current.Dispatcher.Invoke(ImprimirDocumentosPendentes);
					}
					AdicionarValorSangria();
				}),
				EmissorService.WhenErroAoTransmitirDocumentoFiscalEvent.Subscribe(ProcedimentoEmCasoDeErroAoTransmitirDocumentoFiscal)
			};
			base.Load();
		}

		private void AdicionarValorSangria()
		{
			decimal num = Lista.Itens.Where((ItemPagamentoViewModel x) => x.Is<IDinheiro>()).Sum((ItemPagamentoViewModel x) => x.Valor) - Troco;
			if (!(num <= 0m))
			{
				new ValorSangriaService(_valorSangriaRepositoryWrite, _valorSangriaRepositoryRead).AlterarValor(num);
			}
		}

		protected virtual void ProcedimentoEmCasoDeErroAoTransmitirDocumentoFiscal(string @event)
		{
			if (DialogoFactory.MostrarDialogoSimNao("Erro ao transmitir documento, deseja tentar novamente?" + Environment.NewLine + @event) == MessageBoxResult.Yes)
			{
				System.Windows.Application.Current.Dispatcher.Invoke(FinalizarDocumentoFiscal);
			}
			else
			{
				System.Windows.Application.Current.Dispatcher.Invoke(Cancelar);
			}
		}

		private void ProcessarConfirmacaoVenda(Task<IEnumerable<string>> task, bool isPortalDrogaria, Action<IEnumerable<string>> impressaoRelatorio, long numeroDocumento)
		{
			System.Windows.Application.Current.Dispatcher.Invoke(() =>
			{
				if (task.IsFaulted)
				{
					PreDocumentoFiscal preDocumentoFiscal = Seletor.Get<PainelDocumentoFiscal>().PreDocumentoFiscal;
					task.Exception.ShowLastException();
					Cancelar();
					_farmaciaService.AnularVenda(preDocumentoFiscal, 1);
				}
				else
				{
					impressaoRelatorio(task.Result);
					System.Windows.Application.Current.Dispatcher.Invoke(ImprimirDocumentosPendentes);
					if (isPortalDrogaria)
					{
						_farmaciaService.ConfirmarTransacao(Seletor.Get<PainelDocumentoFiscal>().PreDocumentoFiscal, 1, numeroDocumento);
					}
				}
			});
		}

		public override void UnLoad()
		{
			_events?.Dispose();
			_events = null;
			base.UnLoad();
		}

		private void ImprimirDocumentosPendentes()
		{
			LoaderProcessoService.MostrarLoader("Finalizando documento fiscal");
			_bwImprimirDocumentosPendentes.RunWorkerAsync();
		}

		private void BwOnDoWork(object sender, DoWorkEventArgs doWorkEventArgs)
		{
			HabilitarPainel();
			TefService.Imprimir();
			EmissorService.ImprimirRelatoriosGerenciaisFinalizacao();
			EmissorService.LimparRelatoriosGerenciais();
			ImprimirPedidosRestaurante();
		}

		private void ImprimirPedidosRestaurante()
		{
			try
			{
				foreach (KeyValuePair<DigisatServer.Domain.Main.Aggregates.CadastrosAgg.Impressoras.Impressora, IEnumerable<string>> item in ImpressosPedido)
				{
					if (DadosSistema.ConfiguracaoDto.Saida.UtilizarFonteMaiorImprimirPedidoNoAmbienteDeProducao.Valor)
					{
						_impressoraNaoFiscalService.ImprimirComDestaque(item.Value, item.Key.Caminho, item.Key.AvancoPapel);
					}
					else
					{
						_impressoraNaoFiscalService.Imprimir(item.Value, item.Key.Caminho, item.Key.AvancoPapel);
					}
				}
			}
			catch (Exception)
			{
			}
			ImpressosPedido.Clear();
		}

		private void BwImprimirDocumentosPendentesOnRunWorkerCompleted(object sender, RunWorkerCompletedEventArgs runWorkerCompletedEventArgs)
		{
			LoaderProcessoService.EsconderLoader();
			if (runWorkerCompletedEventArgs.Error != null)
			{
				if (DialogoFactory.MostrarDialogoSimNao("Erro ao imprimir documentos pendentes, deseja tentar novamente?") == MessageBoxResult.Yes)
				{
					_bwImprimirDocumentosPendentes.RunWorkerAsync();
				}
				else
				{
					TerminarFinalizacaoDocumentoFiscal();
				}
			}
			else
			{
				TerminarFinalizacaoDocumentoFiscal();
			}
		}

