		public void AdicionarCartaoResposta(InformacaoTransacaoTef informacaoTransacaoTef)
		{
			if (informacaoTransacaoTef.Desconto != 0m)
			{
				decimal num = (AcrescimoDesconto.Is<Desconto>() ? AcrescimoDesconto.Valor : 0m);
				num += informacaoTransacaoTef.Desconto;
				Informacao.Texto = num.ToString(CultureInfo.InvariantCulture).Replace(",", "").Replace(".", ",");
				AplicarDesconto();
			}
			if (informacaoTransacaoTef.Acrescimo != 0m)
			{
				decimal num2 = (AcrescimoDesconto.Is<Acrescimo>() ? AcrescimoDesconto.Valor : 0m);
				num2 += informacaoTransacaoTef.Acrescimo;
				Informacao.Texto = num2.ToString(CultureInfo.InvariantCulture).Replace(",", "").Replace(".", ",");
				AplicarAcrescimo();
			}
			GerarLog gerarLog = new GerarLog();
			ItemPagamentoViewModel itemSelecionado = Lista.ItemSelecionado;
			if (!(itemSelecionado is ICartao))
			{
				gerarLog.GravarLog($"Item pagamento atual é do tipo: {itemSelecionado?.Descricao}.");
			}
			if (_selecionouTef)
			{
				Lista.Posicionar((ItemPagamentoViewModel x) => x.EspeciePagamentoPosicionar == 2);
				ItemPagamentoViewModel itemSelecionado2 = Lista.ItemSelecionado;
				if (!BinInformado.IsNullOrEmpty() && (informacaoTransacaoTef.Bin != BinInformado || informacaoTransacaoTef.Debito != Debito))
				{
					gerarLog.GravarLog($"BIN informado: {BinInformado}");
					gerarLog.GravarLog($"BIN retornado: {informacaoTransacaoTef.Bin}");
					gerarLog.GravarLog($"Número cartão retornado: {informacaoTransacaoTef.NumeroCartao}");
					string arg = (Debito ? "Sim" : "Não");
					gerarLog.GravarLog($"Selecionado débito?: {arg}");
					string arg2 = (informacaoTransacaoTef.Debito ? "Sim" : "Não");
					gerarLog.GravarLog($"Retornou débito?: {arg2}");
					DialogoFactory.MostrarDialogoConfirma("Cartão não elegível para aplicação da promoção Scanntech");
					Seletor.Get<PainelDocumentoFiscal>()?.PreDocumentoFiscal.DesfazerAplicacaoPromocoesScanntech();
					Seletor.Get<PainelTotalizacaoBase>().SetarNavegouPainelPromocaoScanntechMeioPagamento(navegouPainelPromocaoScanntechMeioPagamento: false);
					TefService.Cancelar();
					Seletor.Voltar();
					return;
				}
				gerarLog.GravarLog("Chegou no AdicionarCartaoResposta.");
				itemSelecionado2.To<ICartao>()?.AdicionarCartaoResposta(informacaoTransacaoTef);
				gerarLog.GravarLog($"Passou do AdicionarCartaoResposta. Valor informado {Lista.ItemSelecionado.Valor}");
				BinInformado = null;
				Debito = false;
			}
			AtualizarTotal();
			gerarLog.GravarLog($"Passou do AtualizarTotal. Valor informado {informacaoTransacaoTef.Valor}");
			HabilitarPainel();
			_selecionouTef = false;
		}

