		protected override void AdicionarEspeciesPagamento()
		{
			TipoTef tipoTef = _configuracaoClientService.ObterConfiguracao()?.Tef?.Tipo ?? TipoTef.Nenhum;
			if (DadosSistema.IsRestauranteOuHotel)
			{
				if (EspecieVisivel(1))
				{
					Lista.Adicionar(ItemPagamentoRestaurante<DinheiroRestauranteViewModel, DinheiroViewModel>.Criar().ComSeletorEsquerdo(SeletorEsquerdo));
				}
				if (tipoTef != TipoTef.Nenhum && EspecieVisivel(2))
				{
					Lista.Adicionar(ItemPagamentoRestaurante<CartaoRestauranteViewModel, CartaoViewModel>.Criar().ComSeletorEsquerdo(SeletorEsquerdo).ComPainelTotalizacao(this)
						.ComTefService(TefService)
						.ComEmissorService(EmissorService));
				}
				AdicionarEspecieCarteiraDigitalRestaurante(tipoTef);
				if (EspecieVisivel(7))
				{
					Lista.Adicionar(ItemPagamentoRestaurante<CartaoPosRestauranteViewModel, CartaoPosViewModel>.Criar().ComSeletorEsquerdo(SeletorEsquerdo).ComSeletorDireito(Seletor)
						.ComEmissorService(EmissorService));
				}
				if (EspecieVisivel(3))
				{
					Lista.Adicionar(ItemPagamentoRestaurante<PrazoRestauranteViewModel, PrazoViewModel>.Criar().ComSeletorEsquerdo(SeletorEsquerdo).ComSessaoService(_sessaoService)
						.ComSeletorDireito(Seletor));
				}
				if (EspecieVisivel(29))
				{
					Lista.Adicionar(ItemPagamentoRestaurante<PagamentoPosteriorRestauranteViewModel, PagamentoPosteriorViewModel>.Criar().ComSeletorEsquerdo(SeletorEsquerdo).ComSessaoService(_sessaoService)
						.ComSeletorDireito(Seletor));
				}
				if (EspecieVisivel(4))
				{
					Lista.Adicionar(ItemPagamentoRestaurante<ChequeRestauranteViewModel, ChequeViewModel>.Criar().ComSeletorEsquerdo(SeletorEsquerdo).ComSessaoService(_sessaoService)
						.ComSeletorDireito(Seletor));
				}
				if ((DadosSistema.PodeExecutarFuncao(typeof(Gerencial), typeof(Administrador), typeof(AdministradorIndustria)) || DadosSistema.ContemModuloAdicional(106)) && EspecieVisivel(22))
				{
					Lista.Adicionar(ItemPagamentoRestaurante<ValeTrocaRestauranteViewModel, ValeTrocaViewModel>.Criar().ComSeletorEsquerdo(SeletorEsquerdo).ComSeletorDireito(Seletor)
						.ComSessaoService(_sessaoService));
				}
				if (!PdvEstadoOffline)
				{
					if (EspecieVisivel(23))
					{
						Lista.Adicionar(ValePresenteViewModel.Criar().ComSeletor(Seletor));
					}
					if (EspecieVisivel(27))
					{
						Lista.Adicionar(ItemPagamentoRestaurante<TerminalPosRestauranteViewModel, TerminalPosViewModel>.Criar().ComSeletorEsquerdo(SeletorEsquerdo).ComEmissorService(EmissorService)
							.ComSeletorDireito(Seletor));
					}
				}
				return;
			}
			PreDocumentoFiscal preDocumentoFiscal = Seletor.Get<PainelDocumentoFiscal>().PreDocumentoFiscal;
			decimal num = preDocumentoFiscal?.SubsidioMinisterioSaude ?? 0m;
			if (DadosSistema.IsFarmacia && num > 0m && EspecieVisivel(28))
			{
				Lista.Adicionar(ConvenioFarmaciaPopularViewModel.Criar().ComValor(num));
			}
			decimal num2 = preDocumentoFiscal?.ValorRepassePbm ?? 0m;
			if (DadosSistema.IsFarmacia && num2 > 0m && (preDocumentoFiscal == null || preDocumentoFiscal.RetornoConsultaPbm?.TipoPbm != TipoPbm.PortalDrogaria) && EspecieVisivel(28))
			{
				Lista.Adicionar(ConvenioPbmViewModel.Criar(preDocumentoFiscal.RetornoConsultaPbm.TipoPbm).ComValor(num2));
			}
			decimal num3 = preDocumentoFiscal?.ValorRepassePortalDrogaria ?? 0m;
			if (DadosSistema.IsFarmacia && num3 > 0m && preDocumentoFiscal != null)
			{
				TipoPbm? tipoPbm = preDocumentoFiscal.RetornoConsultaPbm?.TipoPbm;
				TipoPbm tipoPbm2 = TipoPbm.PortalDrogaria;
				if (tipoPbm.GetValueOrDefault() == tipoPbm2 && tipoPbm.HasValue && EspecieVisivel(28))
				{
					Lista.Adicionar(ConvenioPbmViewModel.Criar(preDocumentoFiscal.RetornoConsultaPbm.TipoPbm).ComValor(num3));
				}
			}
			if (EspecieVisivel(1))
			{
				Lista.Adicionar(DinheiroViewModel.Criar());
			}
			if (tipoTef != TipoTef.Nenhum && EspecieVisivel(2))
			{
				Lista.Adicionar(CartaoViewModel.Criar().ComSeletor(Seletor).ComPainelTotalizacao(this)
					.ComTefService(TefService)
					.ComEmissorService(EmissorService));
			}
			AdicionarEspecieCarteiraDigital(tipoTef);
			if (EspecieVisivel(7))
			{
				Lista.Adicionar(CartaoPosViewModel.Criar().ComSeletor(Seletor).ComEmissorService(EmissorService));
			}
			if (EspecieVisivel(3))
			{
