		protected override void FinalizarDocumentoFiscal()
		{
			Action actionPrincipal = () =>
			{
				LoaderProcessoService.MostrarLoader("Finalizando documento fiscal");
				FinalizarDocumentoFiscalEmissor();
				LoaderProcessoService.EsconderLoader();
			};
			Executar(actionPrincipal, FinalizarDocumentoFiscal, Cancelar);
		}

		protected virtual void FinalizarDocumentoFiscalEmissor()
		{
			try
			{
				AcrescimoDesconto acrescimoDesconto = AcrescimoDesconto ?? Desconto.Criar().ComValor(0m);
				DispatcherHelper.DoEvents();
				EmissorService.Totalizar(acrescimoDesconto);
			}
			catch (Exception)
			{
			}
			EmissorService.AbrirGaveta();
			foreach (ItemPagamentoViewModel item in from x in Lista.Itens
				orderby x.Valor
				where x.Valor > 0m
				select x)
			{
				Seletor.Get<PainelDocumentoFiscal>().PreDocumentoFiscal.SetarEmPagamento();
				DispatcherHelper.DoEvents();
				item.Emitir(EmissorService.EfetuarPagamento);
			}
			EmissorService.IdentificarConsumidor(Consumidor);
			EmissorService.Finalizar(MensagensPromocionais.OrderBy((IMensagemPromocional x) => x.Indice));
		}

		protected void Executar(Action actionPrincipal, Action actionTentarNovamente, Action actionCancelar)
		{
			try
			{
				actionPrincipal();
			}
			catch (Exception ex)
			{
				if (!ex.GetLastException().Message.Contains("Abandonar"))
				{
					ex.ShowLastException();
				}
				if (DialogoFactory.MostrarDialogoSimNao("Erro ao finalizar documento, deseja tentar novamente?") == MessageBoxResult.Yes)
				{
					actionTentarNovamente();
				}
				else
				{
					actionCancelar();
				}
			}
		}

		protected async Task GerarImpressosPedidoRestaurante(PreDocumentoFiscal preDocumentoFiscal, string numeroDocumento)
		{
			if (!DadosSistema.ConfiguracaoDto.Saida.ImprimirPedidoNoAmbienteDeProducao.Valor)
			{
				return;
			}
			IMensagemPromocional autoAtendimentoPedidoMensagemPromocional = MensagensPromocionais.FirstOrDefault((IMensagemPromocional x) => x is AutoAtendimentoPedidoMensagemPromocional);
			if (MensagensPromocionais.FirstOrDefault((IMensagemPromocional x) => x is MesaContaMensagemPromocional).IsNotNull() && autoAtendimentoPedidoMensagemPromocional.IsNull())
			{
				return;
			}
			IEnumerable<ItemDocumentoFiscal> itens = preDocumentoFiscal.Itens;
			List<ItemDocumentoFiscal> itens2 = itens.Where((ItemDocumentoFiscal x) => x.Impressora.IsNotNull()).ToListEmptyWhenNull();
			List<ItemDocumentoFiscal> itensComImpressoraNoProduto = itens.Where((ItemDocumentoFiscal x) => x.ImpressoraProduto.IsNotNull()).ToListEmptyWhenNull();
			IEnumerable<string> ambientesProducaoUtilizados = itens2.Select((ItemDocumentoFiscal x) => x.Impressora.Descricao).Concat(itensComImpressoraNoProduto.Select((ItemDocumentoFiscal x) => x.ImpressoraProduto.Descricao));
			IEnumerable<TicketDto> ticketsItensPeriodoEspecifico = Enumerable.Empty<TicketDto>();
			if (!PdvEstadoOffline)
			{
				ticketsItensPeriodoEspecifico = DadosSistema.GetService().Canal((ITicketModuleService service) => service.ObterTicketsItensPeriodoEspecifico()).ToListEmptyWhenNull();
			}
			SenhaPedidoMensagemPromocional senhaPedidoMensagemPromocional = MensagensPromocionais.FirstOrDefault((IMensagemPromocional x) => x is SenhaPedidoMensagemPromocional) as SenhaPedidoMensagemPromocional;
			int senha = 0;
			if (senhaPedidoMensagemPromocional.IsNotNull())
			{
				senha = senhaPedidoMensagemPromocional.Senha;
			}
			int ambienteDaVez = 0;
			foreach (IGrouping<ObjectId, ItemDocumentoFiscal> itensImpressora in from x in itens2
				where !string.IsNullOrEmpty(x.Impressora.Caminho)
				group x by x.Impressora.Id)
			{
				ambienteDaVez++;
				DigisatServer.Domain.Main.Aggregates.CadastrosAgg.Impressoras.Impressora impressora = itensImpressora.First((ItemDocumentoFiscal x) => x.Ativo).Impressora;
				if (impressora.ImprimirEmFormadoDeEtiquetaDeConsumo)
				{
					List<InformacaoImpresso> listaImpressos = new List<InformacaoImpresso>();
					foreach (ItemDocumentoFiscal itemImpressora in itensImpressora.Where((ItemDocumentoFiscal x) => x.Ativo))
					{
						for (int i = 0; (decimal)i < itemImpressora.Quantidade; i++)
						{
							if (DadosSistema.ConfiguracaoDto.Saida.UtilizarValidacaoTicketConsumo.Valor)
							{
								List<TicketDto> list = ticketsItensPeriodoEspecifico.Where((TicketDto x) => x.Detalhe.Condicao.Itens.SelectMany((ItemTicketDto a) => a.Produtos.Select((ProdutoTicketDto b) => b.ProdutoServicoEmpresaReferencia)).Contains(itemImpressora.ProdutoServicoLocal.ProdutoServicoEmpresaReferencia.ToString())).ToListEmptyWhenNull();
								TicketDto ticketDto = null;
								if (list.Any())
								{
									ticketDto = ((list.Count == 1) ? list.FirstOrDefault() : DialogoFactory.MostrarDialogoComboBox("Selecione o ticket desejado", "Tickets", list, "DescricaoVigenciaToText", permiteFechar: false));
								}
								TicketDto dto = new TicketDto
								{
									Tipo = TipoTicket.Consumo,
									DataEmissao = DateTime.Now,
									Descricao = itemImpressora.Descricao.ToStringEmptyWhenNull(),
									Valor = itemImpressora.PrecoUnitario,
									PeriodoVigenciaInicial = (ticketDto.IsNotNull() ? ticketDto.PeriodoVigenciaInicial : DateTime.Now),
									PeriodoVigenciaFinal = (ticketDto.IsNotNull() ? ticketDto.PeriodoVigenciaFinal : RetornarDataValidade()),
									ReferenciaAmbienteProducao = impressora.Id.ToStringEmptyWhenDefault(),
									DescricaoAmbienteProducao = impressora.Descricao.ToStringEmptyWhenNull(),
									OrigemReferencia = preDocumentoFiscal.Id.ToStringEmptyWhenDefault()
								};
								await DadosSistema.GetService().Canal((ITicketModuleService service) => service.AdicionarAsync(dto)).ContinueWith((Task<TicketDto> task) =>
								{
									if (task.IsFaulted)
									{
										task.Exception.ShowLastException();
									}
									else
									{
										listaImpressos.Add(new InformacaoImpresso
										{
											Informacao = ((task.Result.Valor > 0m) ? ($"{task.Result.Descricao}\n" + $"R$ {task.Result.Valor.FormatarCampoValor(2)}") : $"{task.Result.Descricao}"),
											Referencia = task.Result.Referencia,
											TextoQrCode = task.Result.TextoQrCode,
											PeriodoVigenciaInicial = task.Result.PeriodoVigenciaInicial,
											PeriodoVigenciaFinal = task.Result.PeriodoVigenciaFinal
										});
									}
								});
							}
							else
							{
								listaImpressos.Add(new InformacaoImpresso
								{
									Informacao = $"{itemImpressora.Descricao}\n" + $"R$ {itemImpressora.PrecoUnitario.FormatarCampoValor(2)}"
								});
							}
						}
					}
					foreach (InformacaoImpresso item in listaImpressos)
					{
						IRelatorio relatorio2;
						if (DadosSistema.TamanhoBobina != TamanhoBobina.CinquentaESeisCinquentaESeteCinquentaEOitoMilimetros)
						{
							IRelatorio relatorio = new RelatorioFichaConsumo79Mm80Mm(item, DadosSistema.MargemEsquerdaImpressoraNaoFiscal, DadosSistema.RollPaper, impressora.MensagemRodapeEtiquetaConsumo, numeroDocumento, impressora.ImprimirSenhaEtiquetaConsumo, senha, DadosSistema.EmpresaLogada.Imagem, DadosSistema.EmpresaLogada.Fantasia);
							relatorio2 = relatorio;
						}
						else
						{
							IRelatorio relatorio = new RelatorioFichaConsumo56Mm57Mm58Mm(item, DadosSistema.MargemEsquerdaImpressoraNaoFiscal, DadosSistema.RollPaper, impressora.MensagemRodapeEtiquetaConsumo, numeroDocumento, impressora.ImprimirSenhaEtiquetaConsumo, senha, DadosSistema.EmpresaLogada.Imagem, DadosSistema.EmpresaLogada.Fantasia);
							relatorio2 = relatorio;
						}
						IRelatorio relatorio3 = relatorio2;
						_impressoraNaoFiscalService.Imprimir(relatorio3, impressora.Caminho);
					}
				}
				else
				{
					string ambientesProducao = string.Format("{0}/{1} - {2}", ambienteDaVez, ambientesProducaoUtilizados.Distinct().Count(), string.Join(",", itens2.Select((ItemDocumentoFiscal x) => x.Impressora.Descricao).Distinct()));
					IEnumerable<string> value = CriarImpresso(itensImpressora.Select((ItemDocumentoFiscal x) => x).ToList(), autoAtendimentoPedidoMensagemPromocional, ambientesProducao, itensImpressora.FirstOrDefault().Impressora.Descricao);
					ImpressosPedido.Add(impressora, value);
				}
			}
			foreach (IGrouping<ObjectId, ItemDocumentoFiscal> itensImpressora2 in from x in itensComImpressoraNoProduto
				where !string.IsNullOrEmpty(x.ImpressoraProduto.Caminho)
				group x by x.ImpressoraProduto.Id)
			{
				ambienteDaVez++;
				DigisatServer.Domain.Main.Aggregates.CadastrosAgg.Impressoras.Impressora impressora2 = itensImpressora2.First((ItemDocumentoFiscal x) => x.Ativo).ImpressoraProduto;
				if (impressora2.ImprimirEmFormadoDeEtiquetaDeConsumo)
