								TicketDto ticketDto2 = null;
								if (list2.Any())
								{
									ticketDto2 = ((list2.Count == 1) ? list2.FirstOrDefault() : DialogoFactory.MostrarDialogoComboBox("Selecione o ticket desejado", "Tickets", list2, "DescricaoVigenciaToText", permiteFechar: false));
								}
								TicketDto dto2 = new TicketDto
								{
									Tipo = TipoTicket.Consumo,
									DataEmissao = DateTime.Now,
									Descricao = itemImpressora2.Descricao.ToStringEmptyWhenNull(),
									Valor = itemImpressora2.PrecoUnitario,
									PeriodoVigenciaInicial = (ticketDto2.IsNotNull() ? ticketDto2.PeriodoVigenciaInicial : DateTime.Now),
									PeriodoVigenciaFinal = (ticketDto2.IsNotNull() ? ticketDto2.PeriodoVigenciaFinal : RetornarDataValidade()),
									ReferenciaAmbienteProducao = impressora2.Id.ToStringEmptyWhenDefault(),
