		private DateTime RetornarDataValidade()
		{
			DateTime dateTime = DateTime.Now.AddDays(DadosSistema.ConfiguracaoDto.Saida.DiasValidadeTicketConsumo.Valor);
			return new DateTime(dateTime.Year, dateTime.Month, dateTime.Day, DadosSistema.ConfiguracaoDto.Saida.HoraFinalValidadeTicketConsumo.Valor.Hour, DadosSistema.ConfiguracaoDto.Saida.HoraFinalValidadeTicketConsumo.Valor.Minute, 0);
		}

		protected void GerarPedidoPainelPedidoRestaurante(long numeroDocumento, IEnumerable<ItemDocumentoFiscal> itensDocumentoFiscal)
		{
			if (!DadosSistema.IsRestauranteOuHotel || !DadosSistema.ConfiguracaoDto.Saida.UtilizarPainelPedidosPontoDeVenda.Valor)
			{
				return;
			}
			IMensagemPromocional mensagemPromocional = MensagensPromocionais.FirstOrDefault((IMensagemPromocional x) => x is AutoAtendimentoPedidoMensagemPromocional);
			if (MensagensPromocionais.FirstOrDefault((IMensagemPromocional x) => x is MesaContaMensagemPromocional).IsNotNull() && mensagemPromocional.IsNull())
			{
				return;
			}
			List<ItemPedidoRestauranteDto> itensPedido = new List<ItemPedidoRestauranteDto>();
			SenhaPedidoMensagemPromocional senhaPedidoMensagemPromocional = MensagensPromocionais.FirstOrDefault((IMensagemPromocional x) => x is SenhaPedidoMensagemPromocional) as SenhaPedidoMensagemPromocional;
			int senha = 0;
			if (senhaPedidoMensagemPromocional.IsNotNull())
			{
				senha = senhaPedidoMensagemPromocional.Senha;
			}
			foreach (ItemDocumentoFiscal item in itensDocumentoFiscal)
			{
				if (item.Ativo)
				{
					if (item.Quantidade == 0m)
					{
						item.ComQuantidade(item.QuantidadeImprimirAmbienteProducao);
					}
					itensPedido.Add(new ItemPedidoRestauranteDto
					{
						EmpresaReferencia = DadosSistema.EmpresaLogada.Id,
						AmbienteProducaoProduto = item.ProdutoServicoLocal.ImpressoraProduto.ProjectedAsDto(),
						AmbienteProducaoCardapio = item.Impressora.ProjectedAsDto(),
						GarcomNome = (item.Vendedor?.Nome ?? string.Empty),
						GarcomReferencia = (item.Vendedor?.Id.ToStringEmptyWhenDefault() ?? string.Empty),
						ItemMesaContaReferencia = item.ItemMesaContaReferencia.ToStringEmptyWhenNull(),
						Descricao = item.Descricao.ToStringEmptyWhenNull(),
						Codigo = item.Codigo.ToStringEmptyWhenNull(),
						Unidade = item.UnidadeMedida.ToStringEmptyWhenNull(),
						Quantidade = item.Quantidade,
						ValorUnitario = item.PrecoUnitario,
						DataHora = item.DataHora,
						Observacoes = item.Observacoes.Select((string x) => $"-- {x}"),
						Cancelado = item.Ativo,
						ComponentesRemovidos = (item.ProdutoServicoLocal.To<ProdutoLocal>()?.GetComponentesRemovidos()?.Select((ComponenteBase x) => $"-- Sem {x.ProdutoDescricao}".ToUpper()) ?? Enumerable.Empty<string>()),
						Delivery = false,
						SelecionadoParaEntrega = false,
						Senha = senha,
						NumeroMesaConta = numeroDocumento,
						TituloAutoAtendimento = (mensagemPromocional.IsNull() ? string.Empty : $"Autoatendimento: {mensagemPromocional?.To<AutoAtendimentoPedidoMensagemPromocional>().SenhaAutoAtendimento}")
					});
				}
			}
			DadosSistema.GetService().Canal((IRestauranteModuleService service) =>
			{
				service.GerarPedidoPainelPedidoRestaurante(itensPedido);
			});
		}

		private IEnumerable<string> CriarImpresso(IEnumerable<ItemDocumentoFiscal> itens, IMensagemPromocional autoAtendimentoPedidoMensagemPromocional, string ambientesProducao, string ambiente)
		{
			List<string> list = new List<string>();
			BoleanoDto imprimirDescricaoAmbienteImpressoAmbienteDeProducao = DadosSistema.ConfiguracaoDto.Saida.ImprimirDescricaoAmbienteImpressoAmbienteDeProducao;
			if (imprimirDescricaoAmbienteImpressoAmbienteDeProducao != null && imprimirDescricaoAmbienteImpressoAmbienteDeProducao.Valor)
			{
				AdicionarInformacaoAmbienteProducao(ambientesProducao, ambiente, (DadosSistema.TamanhoBobina == TamanhoBobina.CinquentaESeisCinquentaESeteCinquentaEOitoMilimetros) ? 32 : 42, list);
			}
			list.Add("IMPRESSO PEDIDO");
			if (Consumidor.IsNotNull())
			{
				list.Add($"PESSOA: {Consumidor?.Pessoa?.Nome.ToStringEmptyWhenNull()}");
			}
			if (autoAtendimentoPedidoMensagemPromocional.IsNotNull())
			{
				list.Add($"Autoatendimento: {autoAtendimentoPedidoMensagemPromocional?.To<AutoAtendimentoPedidoMensagemPromocional>().SenhaAutoAtendimento}");
			}
			SenhaPedidoMensagemPromocional senhaPedidoMensagemPromocional = MensagensPromocionais.FirstOrDefault((IMensagemPromocional x) => x is SenhaPedidoMensagemPromocional) as SenhaPedidoMensagemPromocional;
			if (senhaPedidoMensagemPromocional.IsNotNull())
			{
				list.Add($"SENHA: {senhaPedidoMensagemPromocional.Senha}    ");
			}
			if (DadosSistema.TamanhoBobina == TamanhoBobina.CinquentaESeisCinquentaESeteCinquentaEOitoMilimetros && EmissorService.IsNot<IEcfService>())
			{
				list.Add("".PadRight(32, '-'));
				list.Add(DadosSistema.ConfiguracaoDto.Saida.ImprimirCodigoItemImpressoAmbienteDeProducao.Valor ? string.Format("{0,-27} QTD", "CODIGO - DESCRICAO") : string.Format("{0,-27} QTD", "DESCRICAO"));
				list.Add("".PadRight(32, '-'));
				foreach (ItemDocumentoFiscal iten in itens)
				{
					if (!iten.Ativo)
					{
						continue;
					}
					if (iten.Quantidade == 0m)
					{
						iten.ComQuantidade(iten.QuantidadeImprimirAmbienteProducao);
					}
					string text = (DadosSistema.ConfiguracaoDto.Saida.ImprimirCodigoItemImpressoAmbienteDeProducao.Valor ? string.Format("{0}{1} - {2}", "\u0002", iten.Codigo, string.IsNullOrEmpty(iten.DescricaoMenuRapido) ? iten.Descricao.ToUpper() : iten.DescricaoMenuRapido.ToUpper()) : string.Format("{0}{1}", "\u0002", iten.Descricao.ToUpper()));
					if (text.Length > 25)
					{
						list.Add(string.Format("{0}{1,-32}", "\u0002", text.RemoverAcentos().CopiarTexto(0, 32)));
						list.Add(string.Format("{0}{1,-25} {2,6:0.###}", "\u0002", text.RemoverAcentos().CopiarTexto(32, 24), iten.Quantidade));
					}
					else
					{
						list.Add(string.Format("{0}{1,-25} {2,6:0.###}", "\u0002", text.CopiarTexto(0, 24).ToUpper(), iten.Quantidade));
					}
					foreach (ComponenteBase item in iten.ProdutoServicoLocal.To<ProdutoLocal>()?.GetComponentesRemovidos() ?? Enumerable.Empty<ComponenteBase>())
					{
						list.Add($"Sem {item}".ToUpper());
					}
					foreach (string observaco in iten.Observacoes)
					{
						list.Add($"-- {observaco}");
					}
					if (iten.Vendedor.IsNotNull() && !iten.Vendedor.IsNenhum)
					{
						list.Add($"VENDEDOR: {iten.Vendedor.Nome.CopiarTexto(31),-32}");
					}
					list.Add("".PadRight(32, '-'));
				}
				list.Add($"Soma da quantidade de itens: {itens.Where((ItemDocumentoFiscal x) => x.Ativo).Sum((ItemDocumentoFiscal x) => x.Quantidade)}");
				list.Add(DateTime.Now.ToString("dd/MM/yyyy HH:mm:ss").PadLeft(15));
				list.Add(new string('-', 32));
				return list;
			}
			list.Add("".PadRight(40, '-'));
			list.Add(DadosSistema.ConfiguracaoDto.Saida.ImprimirCodigoItemImpressoAmbienteDeProducao.Valor ? string.Format("{0,-36} QTD", "CODIGO - DESCRICAO") : string.Format("{0,-36} QTD", "DESCRICAO"));
			foreach (ItemDocumentoFiscal iten2 in itens)
			{
				if (!iten2.Ativo)
				{
					continue;
				}
				if (iten2.Quantidade == 0m)
				{
					iten2.ComQuantidade(iten2.QuantidadeImprimirAmbienteProducao);
				}
				string text2 = (DadosSistema.ConfiguracaoDto.Saida.ImprimirCodigoItemImpressoAmbienteDeProducao.Valor ? $"{iten2.Codigo} - {(string.IsNullOrEmpty(iten2.DescricaoMenuRapido) ? iten2.Descricao.ToUpper() : iten2.DescricaoMenuRapido.ToUpper())}" : $"{iten2.Descricao.ToUpper()}");
				if (text2.Length > 33)
				{
					list.Add($"{text2.RemoverAcentos().CopiarTexto(0, 40),-40}");
					list.Add($"{text2.RemoverAcentos().CopiarTexto(40, 33),-33} {iten2.Quantidade,6:0.000}");
				}
				else
				{
					list.Add($"{text2.RemoverAcentos().CopiarTexto(0, 32),-33} {iten2.Quantidade,6:0.000}");
				}
				foreach (ComponenteBase item2 in iten2.ProdutoServicoLocal.To<ProdutoLocal>()?.GetComponentesRemovidos() ?? Enumerable.Empty<ComponenteBase>())
				{
					list.Add($"-- Sem {item2.ProdutoDescricao}".ToUpper());
				}
				foreach (string observaco2 in iten2.Observacoes)
				{
					list.Add($"-- {observaco2}");
				}
				if (iten2.Vendedor.IsNotNull() && !iten2.Vendedor.IsNenhum)
				{
					list.Add($"VENDEDOR: {iten2.Vendedor.Nome,-32}");
				}
				list.Add("".PadRight(40, '-'));
			}
			list.Add($"Soma da quantidade de itens: {itens.Where((ItemDocumentoFiscal x) => x.Ativo).Sum((ItemDocumentoFiscal x) => x.Quantidade)}");
			list.Add(DateTime.Now.ToString("dd/MM/yyyy HH:mm:ss").PadLeft(15));
			list.Add(new string('-', 40));
			return list;
		}

		private static void AdicionarInformacaoAmbienteProducao(string ambientesToText, string ambiente, int caracteres, ICollection<string> linhas)
		{
			int num = caracteres - ambiente.Length;
			string arg = "".PadLeft((num - 1) / 2, '-');
			string arg2 = "".PadRight((num - 2) / 2, '-');
			linhas.Add("".PadRight(caracteres, '-'));
			linhas.Add($"{arg} {ambiente.ToUpper()} {arg2}");
			linhas.Add("".PadRight(caracteres, '-'));
			linhas.Add($"{ambientesToText.ToUpper()}");
			linhas.Add("".PadRight(caracteres, '-'));
		}

		protected override void TerminarFinalizacaoDocumentoFiscal()
		{
			Seletor.Get<PainelDocumentoFiscal>().PreDocumentoFiscal?.SetarParcelas(Parcelas.ToList());
			LimparParcelas();
			base.TerminarFinalizacaoDocumentoFiscal();
		}

		protected override void ExecutarCancelamento()
		{
			HabilitarPainel();
			TefService.Cancelar();
			LimparParcelas();
			if (DadosSistema.IsFarmacia && (!string.IsNullOrWhiteSpace(Seletor.Get<PainelDocumentoFiscal>().PreDocumentoFiscal.IdFarmaciaPopular) || Seletor.Get<PainelDocumentoFiscal>().PreDocumentoFiscal.RetornoConsultaPbm.IsNotNull()))
			{
				EmissorService.Cancelar(DocumentoFiscalFechado.Criar(), new AutorizacaoPafEcf(DadosSistema.NomeUsuario));
			}
			else
			{
				EmissorService.CancelarFinalizacao();
			}
			Seletor.Get<PainelDocumentoFiscal>().PreDocumentoFiscal?.Cancelar(EmissorService.Tipo);
		}

		public override void Dispose()
		{
			_bwImprimirDocumentosPendentes.DoWork -= BwOnDoWork;
			_bwImprimirDocumentosPendentes.RunWorkerCompleted -= BwImprimirDocumentosPendentesOnRunWorkerCompleted;
			base.Dispose();
		}

		public override void FecharMethod()
		{
			base.FecharMethod();
			if (SeletorEsquerdo.Painel is PainelEsquerdoTotalizacao)
			{
				bool flag = SeletorEsquerdo.Historico.Any((IPainel x) => x is PainelMenuRapidoPontoDeVenda);
				SeletorEsquerdo.VoltarTudo();
				if (flag)
				{
					SeletorEsquerdo.Selecionar<PainelMenuRapidoPontoDeVenda>();
				}
			}
		}
	}
	public class PainelTotalizacaoEmissorBaseValeDetalhado : PainelTotalizacaoEmissorBase
	{
		private readonly ISessaoService _sessaoService;

		public ICommand ECommand { get; protected set; }

		public ICommand WCommand { get; protected set; }

		public ICommand ACommand { get; protected set; }

		public ICommand SCommand { get; protected set; }

		protected PainelTotalizacaoEmissorBaseValeDetalhado()
		{
		}

		protected PainelTotalizacaoEmissorBaseValeDetalhado(Otus.Modulo.PontoDeVendas.Interfaces.ITefService tefService, IEmissorService emissorService, ISessaoService sessaoService, IEventPublisher eventPublisher, Seletor<IPainel> seletorDireito, IImpressoraNaoFiscalService impressoraNaoFiscalService, Seletor<IPainel> seletorEsquerdo, IFarmaciaService farmaciaService, IConfiguracaoClientService configuracaoClientService, IRepositoryBaseWrite<ValorSangriaLocal> valorSangriaRepositoryWrite, IRepositoryRead<ValorSangriaLocal> valorSangriaRepositoryRead, IMobileService mobileService)
			: base(tefService, emissorService, sessaoService, eventPublisher, seletorDireito, impressoraNaoFiscalService, seletorEsquerdo, farmaciaService, configuracaoClientService, valorSangriaRepositoryWrite, valorSangriaRepositoryRead, mobileService)
		{
			_sessaoService = sessaoService;
			ECommand = new DelegateCommand(() =>
			{
				Lista.Posicionar((ItemPagamentoViewModel x) => x.EspeciePagamentoPosicionar == 11);
				AdicionarItem(11);
			}, PodePagar);
			SCommand = new DelegateCommand(() =>
			{
				Lista.Posicionar((ItemPagamentoViewModel x) => x.EspeciePagamentoPosicionar == 13);
				AdicionarItem(13);
			}, PodePagar);
			ACommand = new DelegateCommand(() =>
			{
				Lista.Posicionar((ItemPagamentoViewModel x) => x.EspeciePagamentoPosicionar == 14);
				AdicionarItem(14);
			}, PodePagar);
			WCommand = new DelegateCommand(() =>
			{
				Lista.Posicionar((ItemPagamentoViewModel x) => x.EspeciePagamentoPosicionar == 12);
				AdicionarItem(12);
			}, PodePagar);
		}

		protected override void AdicionarEspeciesPagamento()
		{
			base.AdicionarEspeciesPagamento();
			if (DadosSistema.IsRestauranteOuHotel)
			{
				if (EspecieVisivel(5))
				{
					Lista.Adicionar(ItemPagamentoRestaurante<ValeDetalhadoRestauranteViewModel, ValeDetalhadoViewModel>.Criar().ComSeletorDireito(Seletor).ComSeletorEsquerdo(SeletorEsquerdo));
				}
				if (EspecieVisivel(11))
				{
					Lista.Adicionar(ItemPagamentoRestaurante<DepositoBancarioRestauranteViewModel, DepositoBancarioViewModel>.Criar().ComSessaoService(_sessaoService).ComSeletorDireito(Seletor)
						.ComSeletorEsquerdo(SeletorEsquerdo));
				}
				if (EspecieVisivel(14))
				{
					Lista.Adicionar(ItemPagamentoRestaurante<TedRestauranteViewModel, TedViewModel>.Criar().ComSessaoService(_sessaoService).ComSeletorDireito(Seletor)
						.ComSeletorEsquerdo(SeletorEsquerdo));
				}
				if (EspecieVisivel(13))
				{
					Lista.Adicionar(ItemPagamentoRestaurante<DocRestauranteViewModel, DocViewModel>.Criar().ComSessaoService(_sessaoService).ComSeletorDireito(Seletor)
						.ComSeletorEsquerdo(SeletorEsquerdo));
				}
			}
			else
			{
				if (EspecieVisivel(5))
				{
					Lista.Adicionar(ValeDetalhadoViewModel.Criar().ComSeletor(Seletor));
				}
				if (EspecieVisivel(11))
				{
					Lista.Adicionar(DepositoBancarioViewModel.Criar().ComSessaoService(_sessaoService).ComSeletor(Seletor));
				}
				if (EspecieVisivel(14))
				{
					Lista.Adicionar(TedViewModel.Criar().ComSessaoService(_sessaoService).ComSeletor(Seletor));
				}
				if (EspecieVisivel(13))
				{
					Lista.Adicionar(DocViewModel.Criar().ComSessaoService(_sessaoService).ComSeletor(Seletor));
				}
			}
		}

		public override void Cancelar()
		{
			if (DadosSistema.IsFarmacia && (!string.IsNullOrWhiteSpace(Seletor.Get<PainelDocumentoFiscal>().PreDocumentoFiscal.IdFarmaciaPopular) || Seletor.Get<PainelDocumentoFiscal>().PreDocumentoFiscal.RetornoConsultaPbm.IsNotNull()))
			{
				base.Cancelar();
				return;
			}
			ExecutarCancelamento();
			ReiniciarVariaveis();
			ThreadPrincipal.Executar(() =>
			{
				Seletor.Voltar();
				if (SeletorEsquerdo.Painel is PainelEsquerdoTotalizacao)
				{
					bool flag = SeletorEsquerdo.Historico.Any((IPainel x) => x is PainelMenuRapidoPontoDeVenda);
					SeletorEsquerdo.VoltarTudo();
					if (flag)
					{
						SeletorEsquerdo.Selecionar<PainelMenuRapidoPontoDeVenda>();
					}
				}
			});
		}
	}
	public class PainelTotalizacaoMFe : PainelTotalizacaoEmissorBaseValeDetalhado
	{
		private readonly ISessaoService _sessaoService;

		private CompositeDisposable _events;

		public PainelTotalizacaoMFe()
		{
		}

		public PainelTotalizacaoMFe(Otus.Modulo.PontoDeVendas.Interfaces.ITefService tefService, MFePontoVendaService emissorService, ISessaoService sessaoService, IEventPublisher eventPublisher, Seletor<IPainel> seletorDireito, IImpressoraNaoFiscalService impressoraNaoFiscalService, Seletor<IPainel> seletorEsquerdo, IFarmaciaService farmaciaService, IConfiguracaoClientService configuracaoClientService, IRepositoryBaseWrite<ValorSangriaLocal> valorSangriaRepositoryWrite, IRepositoryRead<ValorSangriaLocal> valorSangriaRepositoryRead, IMobileService mobileService)
			: base(tefService, emissorService, sessaoService, eventPublisher, seletorDireito, impressoraNaoFiscalService, seletorEsquerdo, farmaciaService, configuracaoClientService, valorSangriaRepositoryWrite, valorSangriaRepositoryRead, mobileService)
		{
			_sessaoService = sessaoService;
		}

		public override void Load()
		{
			_events?.Dispose();
			_events = new CompositeDisposable { EmissorService.WhenFalhaAoTransmitirDocumentoFiscalEvent.Subscribe(ProcedimentoEmCasoDeFalhaAoTransmitirDocumentoFiscal) };
			base.Load();
		}

		protected virtual void ProcedimentoEmCasoDeFalhaAoTransmitirDocumentoFiscal(FalhaAoTransmitirDocumentoFiscalEventArgs @event)
		{
			DialogoFactory.MostrarDialogoConfirma("Erro ao transmitir documento" + Environment.NewLine + @event.Mensagem);
			System.Windows.Application.Current.Dispatcher.Invoke(() =>
			{
				AutorizacaoDto autorizacaoDto = _sessaoService.VerificarPermissao<DigisatServer.Infrastructure.Crosscutting.Module.PontoDeVenda, PermitirCancelarDocumentoFiscal>();
				if (autorizacaoDto == null)
				{
					return;
				}
				try
				{
					LoaderProcessoService.EsconderLoader();
					Seletor.Get<PainelDocumentoFiscal>().PreDocumentoFiscal.AdicionarAutorizacao(autorizacaoDto);
					TefService.Cancelar();
					LimparParcelas();
					HabilitarPainel();
					ContraVale = 0m;
					ContraValePresente = null;
					AcrescimoDesconto = null;
					RestaTroco = string.Empty;
					Subtotal = 0m;
					IniciouFinalizacao = false;
					PainelTitulo.ForcarLimparTitulo();
					Lista.Limpar();
					Seletor.Voltar();
					if (SeletorEsquerdo.Painel is PainelEsquerdoTotalizacao)
					{
						bool flag = SeletorEsquerdo.Historico.Any((IPainel x) => x is PainelMenuRapidoPontoDeVenda);
						SeletorEsquerdo.VoltarTudo();
						if (flag)
						{
							SeletorEsquerdo.Selecionar<PainelMenuRapidoPontoDeVenda>();
						}
					}
				}
				catch (Exception ex)
				{
					DialogoFactory.MostrarDialogoConfirma(ex.Message);
				}
			});
		}
	}
	public class PainelTotalizacaoNfce : PainelTotalizacaoEmissorBaseValeDetalhado
	{
		private CompositeDisposable _events;

		private bool _transmitindo;

		private INfceService _nfceService;

		public PainelTotalizacaoNfce()
		{
		}

		public PainelTotalizacaoNfce(Otus.Modulo.PontoDeVendas.Interfaces.ITefService tefService, NfceService emissorService, ISessaoService sessaoService, IEventPublisher eventPublisher, Seletor<IPainel> seletorDireito, IImpressoraNaoFiscalService impressoraNaoFiscalService, Seletor<IPainel> seletorEsquerdo, IFarmaciaService farmaciaService, IConfiguracaoClientService configuracaoClientService, IRepositoryBaseWrite<ValorSangriaLocal> valorSangriaRepositoryWrite, IRepositoryRead<ValorSangriaLocal> valorSangriaRepositoryRead, IMobileService mobileService)
			: base(tefService, emissorService, sessaoService, eventPublisher, seletorDireito, impressoraNaoFiscalService, seletorEsquerdo, farmaciaService, configuracaoClientService, valorSangriaRepositoryWrite, valorSangriaRepositoryRead, mobileService)
		{
		}

		public override void Load()
		{
			_nfceService = EmissorService as INfceService;
			_events?.Dispose();
			_events = new CompositeDisposable
			{
				_nfceService.WhenEmissorTerminouDocumentoFiscalEvent.Subscribe((long x) =>
				{
					_transmitindo = false;
				}),
				_nfceService.WhenErroAoTransmitirDocumentoFiscalEvent.Subscribe((string x) =>
				{
					_transmitindo = false;
				}),
				_nfceService.WhenCancelarFinalizacaoEvent.Subscribe((bool x) =>
				{
					Cancelar();
				})
			};
			base.Load();
		}

		protected override void ReiniciarVariaveis()
		{
			_transmitindo = false;
			base.ReiniciarVariaveis();
		}

		protected override void FinalizarDocumentoFiscalEmissor()
		{
			base.FinalizarDocumentoFiscalEmissor();
			_transmitindo = true;
			EfetivarNfce();
		}

		private void EfetivarNfce()
		{
			PreDocumentoFiscal preDocumentoFiscal = Seletor.Get<PainelDocumentoFiscal>().PreDocumentoFiscal;
			preDocumentoFiscal.SetarParcelas(Parcelas.ToList());
			preDocumentoFiscal.SetarPagamentos(ContraVale, Lista.Itens.ToArray());
			PreencherObservacaoComMensagemPromocional(preDocumentoFiscal);
			preDocumentoFiscal.SetarAcrescimoDesconto(AcrescimoDesconto);
			preDocumentoFiscal.SetarUtilizouCashback(UtilizouCashback, ValorCashbackUtilizado);
			preDocumentoFiscal.Efetivar(EmissorService.Tipo);
		}

		protected override void TerminarFinalizacaoDocumentoFiscal()
		{
			IniciouFinalizacao = false;
			IniciouRecebimentoDeValores = false;
			Seletor.Get<IPainelDocumentoFiscal>().FinalizarDocumentoFiscal();
			PainelTitulo.AlterarTituloTimer($"TROCO: {Troco:n2}", 30.0);
			ReiniciarVariaveis();
			LimparParcelas();
			Seletor.Voltar();
			Seletor.Get<PainelDocumentoFiscal>().Informacao.ControlarFoco();
			if (DadosSistema.PodeAbrirImportacaoMesaContaAoFinalizarDocumentoFiscal())
			{
				Seletor.Selecionar<PainelImportarMesaConta>();
			}
		}

		public override bool PodeVoltar()
		{
			if (base.PodeVoltar())
			{
				return !_transmitindo;
			}
			return false;
		}

		protected override bool PodeAbrirPainelObservacao()
		{
			if (base.PodeAbrirPainelObservacao())
			{
				return !_transmitindo;
			}
			return false;
		}

		protected override bool PodeAbrirBuscaConsumidor()
		{
			if (base.PodeAbrirBuscaConsumidor())
			{
				return !_transmitindo;
			}
			return false;
		}

		protected override bool PodeAbrirIndicaConsumidor()
		{
			if (base.PodeAbrirIndicaConsumidor())
			{
				return !_transmitindo;
			}
			return false;
		}

		protected override bool PodeAbrirBuscaConvenio()
		{
			if (base.PodeAbrirBuscaConvenio())
			{
				return !_transmitindo;
			}
			return false;
		}

		protected override void ProcedimentoEmCasoDeErroAoTransmitirDocumentoFiscal(string @event)
		{
			PreDocumentoFiscal preDocumentoFiscal = Seletor.Get<PainelDocumentoFiscal>().PreDocumentoFiscal;
			if (preDocumentoFiscal.IsNotNull() && preDocumentoFiscal.Itens.OfType<ItemDocumentoFiscalCombustivel>().Any())
			{
				ThreadPrincipal.Executar(() =>
				{
					LoaderProcessoService.MostrarLoader();
				});
				DormirSync(5000, () =>
				{
					ThreadPrincipal.Executar(LoaderProcessoService.EsconderLoader);
					ItemDocumentoFiscalCombustivel itemDocumentoFiscalCombustivel = preDocumentoFiscal.Itens.OfType<ItemDocumentoFiscalCombustivel>().FirstOrDefault();
					bool flag = false;
					try
					{
						if (itemDocumentoFiscalCombustivel.IsNotNull())
						{
							flag = _nfceService.VerificarExistenciaMovimentacaoAguardandoComAbastecimento(itemDocumentoFiscalCombustivel.Abastecimento.Id);
						}
					}
					catch (Exception)
					{
						flag = true;
					}
					if (flag)
					{
						DialogoFactory.MostrarDialogoConfirma("Erro ao transmitir documento, como a NFC-e possui abastecimento vinculado, a mesma deve ser transmitida através da opção 'F9 - Abrir NFC-e'");
						ThreadPrincipal.Executar(() =>
						{
							Seletor.Get<PainelTotalizacaoBase>()?.LimparMensagensPromocionais();
							Seletor.Get<IPainelDocumentoFiscal>().FinalizarDocumentoFiscal();
							PainelTitulo.ForcarLimparTitulo();
							ReiniciarVariaveis();
							Seletor.Voltar();
						});
					}
					else
					{
						base.ProcedimentoEmCasoDeErroAoTransmitirDocumentoFiscal(@event);
					}
				});
			}
			else
			{
				base.ProcedimentoEmCasoDeErroAoTransmitirDocumentoFiscal(@event);
			}
		}
	}
	public class PainelTotalizacaoNotaManual : PainelTotalizacaoEmissorBase
	{
		private readonly IWService _service;

		public PainelTotalizacaoNotaManual()
		{
		}

		public PainelTotalizacaoNotaManual(NotaManualService notaManualService, Otus.Modulo.PontoDeVendas.Interfaces.ITefService tefService, ISessaoService sessaoService, IEventPublisher eventPublisher, Seletor<IPainel> seletor, IImpressoraNaoFiscalService impressoraNaoFiscalService, Seletor<IPainel> seletorEsquerdo, IFarmaciaService farmaciaService, IWService service, IConfiguracaoClientService configuracaoClientService, IRepositoryBaseWrite<ValorSangriaLocal> valorSangriaRepositoryWrite, IRepositoryRead<ValorSangriaLocal> valorSangriaRepositoryRead, IMobileService mobileService)
			: base(tefService, notaManualService, sessaoService, eventPublisher, seletor, impressoraNaoFiscalService, seletorEsquerdo, farmaciaService, configuracaoClientService, valorSangriaRepositoryWrite, valorSangriaRepositoryRead, mobileService)
		{
			_service = service;
			TCommand = new DelegateCommand(() =>
			{
				Lista.Posicionar((ItemPagamentoViewModel x) => x.EspeciePagamentoPosicionar == 2);
				AdicionarItem(2);
			}, PodePagarCartao);
			VCommand = new DelegateCommand(() =>
			{
				Lista.Posicionar((ItemPagamentoViewModel x) => x.EspeciePagamentoPosicionar == 5);
				AdicionarItem(5);
			}, PodePagar);
		}

		protected override void AdicionarEspeciesPagamento()
		{
			if (InformarNumeroNotaFiscal())
			{
				RecuperarFoco();
				base.AdicionarEspeciesPagamento();
				if (DadosSistema.IsRestauranteOuHotel && EspecieVisivel(5))
				{
					Lista.Adicionar(ItemPagamentoRestaurante<ValeRestauranteViewModel, ValeViewModel>.Criar().ComSeletorEsquerdo(SeletorEsquerdo));
				}
				else if (EspecieVisivel(5))
				{
					Lista.Adicionar(ValeViewModel.Criar());
				}
				HabilitarPainel();
			}
			else
			{
				Seletor.Voltar();
			}
		}

		protected virtual bool InformarNumeroNotaFiscal()
		{
			if (!_service.OnlineMsg())
			{
				return false;
			}
			string text;
			try
			{
				text = ((Seletor.Get<PainelDocumentoFiscal>().PreDocumentoFiscal.Numero == 0L) ? _service.Canal((INotaManualModuleService service) => service.ProximoNumeroNotaManual()).ToStringOrEmpty() : Seletor.Get<PainelDocumentoFiscal>().PreDocumentoFiscal.Numero.ToStringOrEmpty());
			}
			catch (Exception ex)
			{
				ex.ShowLastException();
				return false;
			}
			if (DialogoFactory.MostrarDialogoEntradaDataString(out var data, DateTime.MinValue, "Data emissão da nota fiscal", "Informe o número da nota fiscal", out var informacao, text, comInformacao: true, "Número da nota fiscal") != MessageBoxResult.OK)
			{
				Seletor.Get<PainelDocumentoFiscal>().PreDocumentoFiscal.SetarNumero(text.ToInt());
				return false;
			}
			int numeroInteiro = informacao.ToInt();
			if (numeroInteiro == 0)
			{
				DialogoFactory.MostrarDialogoConfirma("O número digitado é inválido. Será utilizado o número da sequência!");
				numeroInteiro = text.ToInt();
			}
			if (_service.Canal((INotaManualModuleService x) => x.Existe(numeroInteiro)))
			{
				DialogoFactory.MostrarDialogoConfirma("O número da nota fiscal já existe!");
				return InformarNumeroNotaFiscal();
			}
			Seletor.Get<PainelDocumentoFiscal>().PreDocumentoFiscal.SetarNumero(numeroInteiro);
			Seletor.Get<PainelDocumentoFiscal>().PreDocumentoFiscal.SetarDataEmissaoNotaManual(data);
			AdicionarMensagemPromocional(numeroInteiro);
			return true;
		}

		protected virtual void AdicionarMensagemPromocional(int numeroNotaManual)
		{
			AdicionarMensagemPromocional(NotaManualMensagemPromocional.Criar().ComNumero(numeroNotaManual));
		}

		protected override async void FinalizarDocumentoFiscal()
		{
			LoaderProcessoService.MostrarLoader("Finalizando documento fiscal");
			DispatcherHelper.UpdateLayoutAndDoEvents();
			await Task.Factory.StartNew(() =>
			{
				IEnumerable<IDadoEmissor> parcelamento = RelatoriosEmissor.RetornarRelatorioGerencialParcelamento(EmissorService.RetornarContadorCupomFiscal(), DateTime.Now, EmissorService.RetornarContadorOrdemOperacao(), Consumidor, Parcelas.OfType<ParcelaPrazo>());
				IEnumerable<string> contraVale = RelatoriosEmissor.RetornarRelatorioGerencialContraVale(EmissorService.RetornarContadorCupomFiscal(), ContraVale, EmissorService.Is<IEcfService>());
				IEnumerable<IDadoEmissor> seriaisVendido = RelatoriosEmissor.RetornarRelatorioGerencialSeriaisVendidos(EmissorService.RetornarContadorCupomFiscal(), from x in Seletor.Get<PainelDocumentoFiscal>().Lista.Itens.OfType<ItemDocumentoFiscalProduto>()
					where x.Ativo
					select x, EmissorService.Is<IEcfService>());
				EmissorService.To<NotaManualService>().EmitirCupomFiscal(Consumidor, Seletor.Get<PainelDocumentoFiscal>().Lista.Itens, AcrescimoDesconto, MensagensPromocionais, Lista.Itens.Where((ItemPagamentoViewModel x) => x.Valor > 0m), parcelamento, contraVale, seriaisVendido);
			}).ContinueWith((Task x) =>
			{
				LoaderProcessoService.EsconderLoader();
				if (x.IsFaulted)
				{
					if (DialogoFactory.MostrarDialogoSimNao("Erro ao finalizar nota manual, Deseja tentar novamente?") == MessageBoxResult.Yes)
					{
						FinalizarDocumentoFiscal();
					}
					else
					{
						Cancelar();
					}
				}
				else
				{
					TerminarFinalizacaoDocumentoFiscal();
				}
			}, CancellationToken.None, TaskContinuationOptions.None, TaskScheduler.FromCurrentSynchronizationContext());
		}
	}
	public class PainelTotalizacaoNotaManualPosto : PainelTotalizacaoNotaManual
	{
		private readonly IRepositoryBaseWrite<PreDocumentoFiscalNotaManualPosto> _preDocumentoFiscalNotaManualPostoRepositoryWrite;

		private readonly IWService _service;

		private readonly IEventPublisher _eventPublisher;

		private readonly Seletor<IPainel> _seletorEsquerdo;

		public PainelTotalizacaoNotaManualPosto()
		{
		}

		public PainelTotalizacaoNotaManualPosto(NotaManualService notaManualService, ISessaoService sessaoService, IRepositoryBaseWrite<PreDocumentoFiscalNotaManualPosto> preDocumentoFiscalNotaManualPostoRepositoryWrite, IWService service, IEventPublisher eventPublisher, Seletor<IPainel> seletor, Seletor<IPainel> seletorEsquerdo, Otus.Modulo.PontoDeVendas.Interfaces.ITefService tefService, IImpressoraNaoFiscalService impressoraNaoFiscalService, IFarmaciaService farmaciaService, IConfiguracaoClientService configuracaoClientService, IRepositoryBaseWrite<ValorSangriaLocal> valorSangriaRepositoryWrite, IRepositoryRead<ValorSangriaLocal> valorSangriaRepositoryRead, IMobileService mobileService)
			: base(notaManualService, tefService, sessaoService, eventPublisher, seletor, impressoraNaoFiscalService, seletorEsquerdo, farmaciaService, service, configuracaoClientService, valorSangriaRepositoryWrite, valorSangriaRepositoryRead, mobileService)
		{
			_preDocumentoFiscalNotaManualPostoRepositoryWrite = preDocumentoFiscalNotaManualPostoRepositoryWrite;
			_service = service;
			_eventPublisher = eventPublisher;
			_seletorEsquerdo = seletorEsquerdo;
		}

		protected override void AdicionarMensagemPromocional(int numeroNotaManual)
		{
			NotaManualPostoMensagemPromocional mensagemPromocional = NotaManualPostoMensagemPromocional.Criar().ComNumero(numeroNotaManual);
			AdicionarMensagemPromocional(mensagemPromocional);
		}

		protected override void FinalizarDocumentoFiscal()
		{
			TerminarFinalizacaoDocumentoFiscal();
		}

		protected override bool InformarNumeroNotaFiscal()
		{
			if (!_service.OnlineMsg())
			{
				return false;
			}
			string informacao = string.Empty;
			string numeroInicial;
			try
			{
				numeroInicial = ((Seletor.Get<PainelDocumentoFiscal>().PreDocumentoFiscal.Numero == 0L) ? _service.Canal((INotaManualModuleService service) => service.ProximoNumeroNotaManual()).ToStringOrEmpty() : Seletor.Get<PainelDocumentoFiscal>().PreDocumentoFiscal.Numero.ToStringOrEmpty());
			}
			catch (Exception ex)
			{
				ex.ShowLastException();
				return false;
			}
			if (DialogoFactory.MostrarDialogoEntradaString(ref informacao, "Número da nota fiscal", "Informe o número da nota fiscal", null, senha: false, numerico: true, preechimentoObrigatorio: false, numeroInicial) != MessageBoxResult.OK)
			{
				Seletor.Get<PainelDocumentoFiscal>().PreDocumentoFiscal.SetarNumero(numeroInicial.ToInt());
				return false;
			}
			numeroInicial = informacao;
			if (_service.Canal((INotaManualModuleService x) => x.Existe(numeroInicial.ToInt())))
			{
				DialogoFactory.MostrarDialogoConfirma("O número da nota fiscal já existe!");
				return InformarNumeroNotaFiscal();
			}
			Seletor.Get<PainelDocumentoFiscal>().PreDocumentoFiscal.SetarNumero(numeroInicial.ToInt());
			AdicionarMensagemPromocional(numeroInicial.ToInt());
			return true;
		}

		protected override void TerminarFinalizacaoDocumentoFiscal()
		{
			try
			{
				PreDocumentoFiscal preDocumentoFiscal = Seletor.Get<PainelDocumentoFiscal>().PreDocumentoFiscal;
				preDocumentoFiscal.SetarPagamentos(ContraVale, Lista.Itens.ToArray());
				PreencherObservacaoComMensagemPromocional(preDocumentoFiscal);
				preDocumentoFiscal.SetarAcrescimoDesconto(AcrescimoDesconto);
				PreDocumentoFiscalNotaManualPosto preDocumentoFiscalNotaManualPosto = new PreDocumentoFiscalNotaManualPosto(preDocumentoFiscal);
				_preDocumentoFiscalNotaManualPostoRepositoryWrite.Add(preDocumentoFiscalNotaManualPosto);
				_service.Canal((IPostoCombustivelModuleService x) =>
				{
					x.AtualizarStatusAbastecimentosEmitidoNotaFiscal(from a in preDocumentoFiscal.Itens.OfType<ItemDocumentoFiscalCombustivel>()
						select a.Abastecimento.Id, preDocumentoFiscal.Numero);
				});
				if (EmissorService.To<NotaManualService>().EcfServicePronto)
				{
					_seletorEsquerdo.Get<PainelEsquerdoPosto>().EmitirCupomFiscalNotaManual(preDocumentoFiscalNotaManualPosto);
				}
				Seletor.Get<IPainelDocumentoFiscal>().FinalizarDocumentoFiscal();
				ReiniciarVariaveis();
				Seletor.Voltar();
				VerificouComissaoGarcom = false;
				VerificouCashback = false;
				VerificouMesaContaCredito = false;
				_eventPublisher.Publish(new TerminouNotaFiscalManualPostoEvent());
			}
			catch (Exception ex)
			{
				ex.ShowLastException();
			}
		}
	}
	public class PainelTotalizacaoPorEspecie : PainelInteracao<PainelTotalizacaoPorEspecie>
	{
		private readonly IEmissorService _emissorService;

		private readonly Seletor<IPainel> _seletor;

		private readonly IUsuarioRepositoryRead _usuarioRepositoryRead;

		private readonly IWService _service;

		private readonly ItemInteracaoDataFocusable _dataInicial;

		private readonly ItemInteracaoData _dataFinal;

		public override string Titulo => "Visualizar totalização por espécie";

		public override string DescricaoDoBotao => "Visualizar";

		public PainelTotalizacaoPorEspecie()
		{
		}

		public PainelTotalizacaoPorEspecie(IUsuarioRepositoryRead usuarioRepositoryRead, IWService service, IEmissorService emissorService, Seletor<IPainel> seletor)
			: base(seletor)
		{
			_usuarioRepositoryRead = usuarioRepositoryRead;
			_service = service;
			_emissorService = emissorService;
			_seletor = seletor;
			_dataInicial = ItemInteracaoBase<ItemInteracaoDataFocusable, DateTime>.Criar().ComDescricao("Data inicial").ComValor(DateTime.Today)
				.Build();
			_dataFinal = ItemInteracaoBase<ItemInteracaoData, DateTime>.Criar().ComDescricao("Data final").ComValor(DateTime.Now)
				.Build();
			Campos.Insert(0, _dataInicial);
			Campos.Insert(1, _dataFinal);
		}

		protected override void F2Method()
		{
			ObterRelatorio();
		}

		private async void ObterRelatorio()
		{
			LoaderProcessoService.MostrarLoader();
			UsuarioBase usuario = _usuarioRepositoryRead.PorNome(DadosSistema.NomeUsuario);
			await _service.Canal((IMovimentacaoSaidaRelatorioModuleService service) => service.TotalizacaoPorEspecie(_dataInicial.Valor, _dataFinal.Valor.ToFinalDia(), usuario.Id.ToString(), ObterOrigem(), 2, agruparPorDia: false, null)).ContinueWith((Task<ResumoTotalizacaoEspecieDto> task) =>
			{
				LoaderProcessoService.EsconderLoader();
				if (task.IsFaulted)
				{
					task.Exception.ShowLastException();
				}
				else
				{
					_emissorService.ImprimirTotalizacaoPorEspecie(ObterLinhasTotalizacaoPorEspecie(task.Result, usuario));
				}
				_seletor.VoltarTudo();
			}, CancellationToken.None, TaskContinuationOptions.None, TaskScheduler.FromCurrentSynchronizationContext());
		}

		private int ObterOrigem()
		{
			return _emissorService.Tipo switch
			{
				TipoMovimentacao.NotaFiscalConsumidorEletronica => 8, 
				TipoMovimentacao.CupomFiscalEletronico => 7, 
				TipoMovimentacao.RegistroVenda => 15, 
				_ => 6, 
			};
		}

		protected IEnumerable<string> ObterLinhasTotalizacaoPorEspecie(ResumoTotalizacaoEspecieDto resumo, UsuarioBase usuario)
		{
			List<string> list;
			if (DadosSistema.TamanhoBobina == TamanhoBobina.CinquentaESeisCinquentaESeteCinquentaEOitoMilimetros && _emissorService.IsNot<IEcfService>())
			{
				list = new List<string>
				{
					DadosSistema.EmpresaLogada.Nome,
					DadosSistema.EmpresaLogada.CpfCnpjFormatado,
					"".PadRight(32, '='),
					"Totalização por espécie",
					$"De {_dataInicial.Valor:d} até {_dataFinal.Valor:d}",
					"Origem: " + _emissorService.Tipo.RetornarDescricaoCurta(),
					"Situação: Concluído",
					$"Operador: {usuario.Nome}",
					"".PadRight(32, ' '),
					"Espécie".PadRight(26, ' ') + "Valor",
					"".PadRight(32, '=')
				};
				foreach (var item in from x in resumo.Lista
					group x by new { x.Codigo, x.Descricao } into x
					orderby x.Key.Descricao
					select x)
				{
					list.Add(item.Key.Descricao.PadRight(23, ' ') + $"{item.Sum((TotalizacaoEspecieDto x) => x.Valor),8:0.00}");
					foreach (TotalizacaoEspecieDto item2 in item.Where((TotalizacaoEspecieDto x) => !string.IsNullOrWhiteSpace(x.DescricaoBandeira)))
					{
						list.Add($"{item2.DescricaoBandeira.PadLeft(15, ' ')} {item2.Valor,8:0.00}");
					}
					list.Add("".PadRight(32, '-'));
				}
				list.Add($"Total {resumo.Lista.Sum((TotalizacaoEspecieDto x) => x.Valor):c2}".PadLeft(32, ' '));
				list.Add($"Número documentos emitidos {resumo.Lista.Sum((TotalizacaoEspecieDto x) => x.Quantidade)}".PadLeft(32, ' '));
				list.Add("".PadRight(32, ' '));
				list.Add("".PadRight(32, '='));
				list.Add("Resumo por parc. em cartão");
				foreach (var item3 in from x in resumo.ListaCartoes
					group x by new { x.DescricaoBandeira, x.Debito, x.NumeroParcelas } into x
					orderby x.Key.DescricaoBandeira
					select x)
				{
					string arg;
					if (item3.Key.Debito)
					{
						arg = $"{item3.Key.DescricaoBandeira}";
					}
					else
					{
						arg = ((!item3.Key.Debito && item3.Key.NumeroParcelas == 0) ? $"{item3.Key.DescricaoBandeira} 1x" : $"{item3.Key.DescricaoBandeira} {item3.Key.NumeroParcelas}x");
					}
					list.Add($"{arg}".PadRight(24, ' ') + $"{item3.Sum((TotalizacaoEspecieDto x) => x.Valor),8:0.00}");
				}
				list.Add($"Total {resumo.ListaCartoes.Sum((TotalizacaoEspecieDto x) => x.Valor):c2}".PadLeft(32, ' '));
				list.Add("".PadRight(32, ' '));
				list.Add("".PadRight(32, '='));
				list.Add("Totalização parc. em cartão");
				foreach (var item4 in from x in resumo.ListaCartoes
					group x by new { x.Debito, x.NumeroParcelas } into x
					orderby x.Key.Debito
					select x)
				{
					string arg2;
					if (item4.Key.Debito)
					{
						arg2 = "Débito";
					}
					else
					{
						arg2 = ((!item4.Key.Debito && item4.Key.NumeroParcelas == 0) ? "1x" : $"{item4.Key.NumeroParcelas}x");
					}
					list.Add($"{arg2}".PadRight(24, ' ') + $"{item4.Sum((TotalizacaoEspecieDto x) => x.Valor),8:0.00}");
				}
				list.Add($"Total {resumo.ListaCartoes.Sum((TotalizacaoEspecieDto x) => x.Valor):c2}".PadLeft(32, ' '));
			}
			else
			{
				list = new List<string>
				{
					DadosSistema.EmpresaLogada.Nome,
					DadosSistema.EmpresaLogada.CpfCnpjFormatado,
					"".PadRight(40, '='),
					"Totalização por espécie",
					$"De {_dataInicial.Valor:d} até {_dataFinal.Valor:d}",
					"Origem: " + _emissorService.Tipo.RetornarDescricao(),
					"Situação: Concluído",
					$"Operador: {usuario.Nome}",
					"".PadRight(40, ' '),
					"Espécie".PadRight(34, ' ') + "Valor",
					"".PadRight(40, '=')
				};
				foreach (var item5 in from x in resumo.Lista
					group x by new { x.Codigo, x.Descricao } into x
					orderby x.Key.Descricao
					select x)
				{
					list.Add(item5.Key.Descricao.PadRight(32, ' ') + $"{item5.Sum((TotalizacaoEspecieDto x) => x.Valor),8:0.00}");
					foreach (TotalizacaoEspecieDto item6 in item5.Where((TotalizacaoEspecieDto x) => !string.IsNullOrWhiteSpace(x.DescricaoBandeira)))
					{
						list.Add($"{item6.DescricaoBandeira.PadLeft(23, ' ')} {item6.Valor,8:0.00}");
					}
					list.Add("".PadRight(40, '-'));
				}
				list.Add($"Total {resumo.Lista.Sum((TotalizacaoEspecieDto x) => x.Valor):c2}".PadLeft(40, ' '));
				list.Add($"Número documentos emitidos {resumo.Lista.Sum((TotalizacaoEspecieDto x) => x.Quantidade)}".PadLeft(40, ' '));
				list.Add("".PadRight(40, ' '));
				list.Add("".PadRight(40, '='));
				list.Add("Resumo por parcelamento em cartão");
				foreach (var item7 in from x in resumo.ListaCartoes
					group x by new { x.DescricaoBandeira, x.Debito, x.NumeroParcelas } into x
					orderby x.Key.DescricaoBandeira
					select x)
				{
					string arg3;
					if (item7.Key.Debito)
					{
						arg3 = $"{item7.Key.DescricaoBandeira}";
					}
					else
