						arg3 = ((!item7.Key.Debito && item7.Key.NumeroParcelas == 0) ? $"{item7.Key.DescricaoBandeira} 1x" : $"{item7.Key.DescricaoBandeira} {item7.Key.NumeroParcelas}x");
