				list.Add($"Total {resumo.ListaCartoes.Sum((TotalizacaoEspecieDto x) => x.Valor):c2}".PadLeft(40, ' '));
				list.Add("".PadRight(40, ' '));
				list.Add("".PadRight(40, '='));
				list.Add("Totalização parcelamento em cartão");
				foreach (var item8 in from x in resumo.ListaCartoes
					group x by new { x.Debito, x.NumeroParcelas } into x
