		{
			_events?.Dispose();
			_events = new CompositeDisposable { EmissorService.WhenFalhaAoTransmitirDocumentoFiscalEvent.Subscribe(ProcedimentoEmCasoDeFalhaAoTransmitirDocumentoFiscal) };
			base.Load();
		}

		protected virtual void ProcedimentoEmCasoDeFalhaAoTransmitirDocumentoFiscal(FalhaAoTransmitirDocumentoFiscalEventArgs @event)
		{
			DialogoFactory.MostrarDialogoConfirma("Erro ao transmitir documento" + Environment.NewLine + @event.Mensagem);
			System.Windows.Application.Current.Dispatcher.Invoke(() =>
			{
				AutorizacaoDto autorizacaoDto = _sessaoService.VerificarPermissao<DigisatServer.Infrastructure.Crosscutting.Module.PontoDeVenda, PermitirCancelarDocumentoFiscal>();
				if (autorizacaoDto == null)
				{
					return;
				}
				try
				{
					LoaderProcessoService.EsconderLoader();
					Seletor.Get<PainelDocumentoFiscal>().PreDocumentoFiscal.AdicionarAutorizacao(autorizacaoDto);
					TefService.Cancelar();
					LimparParcelas();
					HabilitarPainel();
					ContraVale = 0m;
					ContraValePresente = null;
					AcrescimoDesconto = null;
					RestaTroco = string.Empty;
					Subtotal = 0m;
					IniciouFinalizacao = false;
					PainelTitulo.ForcarLimparTitulo();
					Lista.Limpar();
					Seletor.Voltar();
					if (SeletorEsquerdo.Painel is PainelEsquerdoTotalizacao)
					{
						bool flag = SeletorEsquerdo.Historico.Any((IPainel x) => x is PainelMenuRapidoPontoDeVenda);
						SeletorEsquerdo.VoltarTudo();
						if (flag)
						{
							SeletorEsquerdo.Selecionar<PainelMenuRapidoPontoDeVenda>();
						}
					}
				}
				catch (Exception ex)
				{
					DialogoFactory.MostrarDialogoConfirma(ex.Message);
				}
			});
		}

		protected override void ProcedimentoEmCasoDeErroAoTransmitirDocumentoFiscal(string @event)
		{
			DialogoFactory.MostrarDialogoConfirma("Erro ao transmitir documento, consulte a existência do CF-e no Sistema de Gestão e Retaguarda do SAT-CF-e (Sefaz-SP) antes de prosseguir.");
			if (DialogoFactory.MostrarDialogoSimNao("O CF-e está autorizado no Sistema de Gestão e Retaguarda do SAT-CF-e (Sefaz-SP)?") == MessageBoxResult.No)
			{
				DialogoFactory.MostrarDialogoConfirma("Uma nova tentativa de finalização poderá gerar um novo CF-e.");
				System.Windows.Application.Current.Dispatcher.Invoke(Cancelar);
				return;
			}
			DialogoFactory.MostrarDialogoConfirma("Faça o download do XML no Sistema de Gestão e Retaguarda do SAT-CF-e (Sefaz-SP) e indique o mesmo na próxima etapa.");
			Microsoft.Win32.OpenFileDialog openFileDialog = new Microsoft.Win32.OpenFileDialog
			{
				InitialDirectory = Directory.GetCurrentDirectory(),
				Multiselect = false,
				Filter = "XML | *.xml"
			};
			openFileDialog.ShowDialog();
			while (string.IsNullOrWhiteSpace(openFileDialog.FileName))
			{
				if (DialogoFactory.MostrarDialogoSimNao("Nenhum arquivo XML de CF-e foi indicado e esse procedimento não poderá ser realizado em outro momento. Continuar?") == MessageBoxResult.Yes)
				{
					return;
				}
				openFileDialog.ShowDialog();
			}
			try
			{
				CFeDto cFeDto = ((CFe)HelperXml.Ler(openFileDialog.FileName, typeof(CFe))).ToXml().ProjectedAsCFeDto();
				EmissorService.SetarUltimoCfeDto(cFeDto);
				TerminarFinalizacaoDocumentoFiscal();
			}
			catch (Exception)
			{
				DialogoFactory.MostrarDialogoConfirma("Arquivo XML de CF-e inválido.");
			}
		}
	}
	public class PainelTotalizadorNaoFiscal : PainelInteracao<PainelTotalizadorNaoFiscal>
	{
		private readonly IEcfService _ecfService;

		private IEnumerable<TotalizadorNaoFiscal> _totalizadoresNaoFiscaisACadastrar = new List<TotalizadorNaoFiscal>();

		private readonly IEnumerable<TotalizadorNaoFiscal> _totalizadoresNaoFiscais = new List<TotalizadorNaoFiscal> { TotalizadorNaoFiscal.Criar().ComDescricao("Recebimentos") };

		public override string Titulo => "Visualizar/Cadastrar totalizadores não fiscais";

		public override string DescricaoDoBotao => "Incluir";

		public PainelTotalizadorNaoFiscal()
		{
		}

		public PainelTotalizadorNaoFiscal(IEcfService ecfService, Seletor<IPainel> seletor)
			: base(seletor)
		{
			_ecfService = ecfService;
		}

		protected override async void F2Method()
		{
			LoaderProcessoService.MostrarLoader("Cadastrando totalizadores não fiscais...");
			await Task.Factory.StartNew(() =>
			{
				foreach (TotalizadorNaoFiscal item in _totalizadoresNaoFiscaisACadastrar)
				{
					_ecfService.CadastrarTotalizadorNaoFiscal(item.Descricao);
				}
			}).ContinueWith((Task task) =>
			{
				LoaderProcessoService.EsconderLoader();
				if (task.IsFaulted)
				{
					task.Exception.ShowLastException();
				}
				Seletor.Voltar();
			}, CancellationToken.None, TaskContinuationOptions.None, TaskScheduler.FromCurrentSynchronizationContext());
		}

		protected override bool CanF2Method()
		{
			if (base.CanF2Method())
			{
				return _totalizadoresNaoFiscaisACadastrar.Any();
			}
			return false;
		}

		public override void Load()
		{
			Campos.Clear();
			_ecfService.AguardarEcfCarregado();
			Lista<TotalizadorNaoFiscal> lista = new Lista<TotalizadorNaoFiscal>();
			IEnumerable<TotalizadorNaoFiscal> totalizadoresCadastrados = _ecfService.TotalizadoresNaoFiscais.Where((TotalizadorNaoFiscal x) => !string.IsNullOrWhiteSpace(x.Descricao));
			lista.Adicionar(totalizadoresCadastrados);
			Campos.Insert(0, ItemInteracaoBase<ItemInteracaoListaTotalizadorNaoFiscal, Lista<TotalizadorNaoFiscal>>.Criar().ComDescricao("Totalizadores não fiscais cadastrados no ECF").ComValor(lista)
				.Build());
			_totalizadoresNaoFiscaisACadastrar = _totalizadoresNaoFiscais.Where((TotalizadorNaoFiscal x) => totalizadoresCadastrados.All((TotalizadorNaoFiscal y) => !string.Equals(y.Descricao, x.Descricao, StringComparison.CurrentCultureIgnoreCase)));
		}

		public override void UnLoad()
		{
			Campos.Clear();
		}

		public override bool PodeVoltar()
		{
			return true;
		}

		public override void Dispose()
		{
		}
	}
