	public class PainelVendasIdentificadasPeloCpfCnpj : PainelInteracao<PainelVendasIdentificadasPeloCpfCnpj>
	{
		private readonly IWService _service;

		private readonly IArquivoAuxiliarService _arquivoAuxiliarService;

		private readonly ISessaoService _sessaoService;

		private readonly ItemInteracaoMesAnoFocusable _mesAnoInicial;

		private readonly ItemInteracaoMesAno _mesAnoFinal;

		private readonly Lista<IItemInteracao> _itemFiltro;

		public override string Titulo => "Gerar arquivo eletrônico das vendas identificadas pelo CPF/CNPJ";

		public PainelVendasIdentificadasPeloCpfCnpj()
		{
		}

		public PainelVendasIdentificadasPeloCpfCnpj(IWService service, IArquivoAuxiliarService arquivoAuxiliarService, ISessaoService sessaoService, Seletor<IPainel> seletor)
			: base(seletor)
		{
			_service = service;
			_arquivoAuxiliarService = arquivoAuxiliarService;
			_sessaoService = sessaoService;
			_mesAnoInicial = ItemInteracaoBase<ItemInteracaoMesAnoFocusable, DateTime>.Criar().ComDescricao("Mês/Ano inicial").ComValor(DateTime.Now)
				.Build();
			Campos.Add(_mesAnoInicial);
			_mesAnoFinal = ItemInteracaoBase<ItemInteracaoMesAno, DateTime>.Criar().ComDescricao("Mês/Ano final").ComValor(DateTime.Now)
				.Build();
			Campos.Add(_mesAnoFinal);
			ItemInteracaoTexto itemInteracaoTexto = ItemInteracaoBase<ItemInteracaoTexto, string>.Criar().ComDescricao("Completo").ComValor("C")
				.Build();
			ItemInteracaoCpf item = ItemInteracaoBase<ItemInteracaoCpf, Cpf>.Criar().ComDescricao("Cpf").Build();
			Lista<IItemInteracao> lista = new Lista<IItemInteracao>();
			lista.Adicionar(item);
			ItemInteracaoComboBox itemInteracaoComboBox = ItemInteracaoBase<ItemInteracaoComboBox, Lista<IItemInteracao>>.Criar().ComDescricao("Cpf").ComValor(lista)
				.Build();
			ItemInteracaoCnpj item2 = ItemInteracaoBase<ItemInteracaoCnpj, Cnpj>.Criar().ComDescricao("Cnpj").Build();
			Lista<IItemInteracao> lista2 = new Lista<IItemInteracao>();
			lista2.Adicionar(item2);
			ItemInteracaoComboBox itemInteracaoComboBox2 = ItemInteracaoBase<ItemInteracaoComboBox, Lista<IItemInteracao>>.Criar().ComDescricao("Cnpj").ComValor(lista2)
				.Build();
			_itemFiltro = new Lista<IItemInteracao>();
			_itemFiltro.Adicionar(itemInteracaoTexto, itemInteracaoComboBox, itemInteracaoComboBox2);
			Campos.Add(ItemInteracaoBase<ItemInteracaoComboBox, Lista<IItemInteracao>>.Criar().ComDescricao("Filtro").ComValor(_itemFiltro)
				.Build());
		}

		protected override async void F2Method()
		{
			GeradorArquivoVendasIdentificadasCpfCnpjPafEcfDto parametros = new GeradorArquivoVendasIdentificadasCpfCnpjPafEcfDto
			{
				DataInicial = new DateTime(_mesAnoInicial.Valor.Year, _mesAnoInicial.Valor.Month, 1),
				DataFinal = new DateTime(_mesAnoFinal.Valor.Year, _mesAnoFinal.Valor.Month, DateTime.DaysInMonth(_mesAnoFinal.Valor.Year, _mesAnoFinal.Valor.Month)),
				Completo = (_itemFiltro.ItemSelecionado as ItemInteracaoTexto).IsNotNull(),
				Documento = ((!(_itemFiltro.ItemSelecionado as ItemInteracaoTexto).IsNull()) ? string.Empty : (((_itemFiltro.ItemSelecionado as ItemInteracaoComboBox).Valor.ItemSelecionado is ItemInteracaoCpf) ? ((ItemInteracaoCpf)(_itemFiltro.ItemSelecionado as ItemInteracaoComboBox).Valor.ItemSelecionado).Valor.Numero : ((ItemInteracaoCnpj)(_itemFiltro.ItemSelecionado as ItemInteracaoComboBox).Valor.ItemSelecionado).Valor.Numero))
			};
			Otus.Infraestrutura.Models.Sessoes.Pessoa empresa = _sessaoService.Sessao.Perfis.ItemSelecionado.Empresa;
			IEnumerable<RegistroZ4Dto> source = await _service.Canal((IGeradorArquivoRegistrosPafEcfModuleService x) => x.ObterRegistrosZ4ArquivoVendasIdentificasCpfCnpj(parametros));
			PafEcfArquivoVendaIdentificadaPeloCpfCnpj pafEcfArquivoVendaIdentificadaPeloCpfCnpj = new PafEcfArquivoVendaIdentificadaPeloCpfCnpj(new RegistroZ1(empresa.CpfCnpj, empresa.Ie, empresa.Im, empresa.Nome), new RegistroZ2(_arquivoAuxiliarService.Cnpj, _arquivoAuxiliarService.Ie, _arquivoAuxiliarService.Im, _arquivoAuxiliarService.RazaoSocialSoftwareHouse), new RegistroZ3(_arquivoAuxiliarService.NumeroLaudo, _arquivoAuxiliarService.NomeAplicativo, _arquivoAuxiliarService.VersaoAplicativo), parametros.Documento, parametros.DataInicial, parametros.DataFinal);
			pafEcfArquivoVendaIdentificadaPeloCpfCnpj.AdicionarRegistrosZ4(source.Select((RegistroZ4Dto x) => new RegistroZ4(x.CpfCnpj, x.Total, x.DataInicial, x.DataFinal)));
			pafEcfArquivoVendaIdentificadaPeloCpfCnpj.CaminhoDoArquivo = Path.Combine(AppDomain.CurrentDomain.BaseDirectory, "Fiscal");
			pafEcfArquivoVendaIdentificadaPeloCpfCnpj.ChavePrivada = Hash.RetornarChavePrivadaInformacaoDecifrada();
			pafEcfArquivoVendaIdentificadaPeloCpfCnpj.Salvar();
			DialogoFactory.MostrarDialogoConfirma($"Arquivo {pafEcfArquivoVendaIdentificadaPeloCpfCnpj.ObterCaminhoCompleto()} gerado com sucesso.");
			Seletor.Voltar();
		}

