		public static IEnumerable<IDadoEmissor> RetornarRelatorioGerencialParcelamento(long numeroDocumento, DateTime dataInicioEmissao, int coo, ConsumidorLocal consumidor, IEnumerable<ParcelaPrazo> parcelas)
		{
			List<ParcelaPrazo> list = parcelas.ToListEmptyWhenNull();
			if (!list.Any() || consumidor.IsNull())
			{
				return Enumerable.Empty<IDadoEmissor>();
			}
			decimal num = list.Sum((ParcelaPrazo x) => x.Valor);
			List<IDadoEmissor> list2 = new List<IDadoEmissor>
			{
				TextoEmissor.Criar().ComInformacao("======================================="),
				TextoEmissor.Criar().ComInformacao("   PARCELAMENTO - VIA ESTABELECIMENTO  "),
				TextoEmissor.Criar().ComInformacao("======================================="),
				TextoEmissor.Criar().ComInformacao($"Emissao: {dataInicioEmissao.FormatarData()}"),
