		public static IEnumerable<IDadoEmissor> RetornarRelatorioGerencialSeriaisVendidos(long numeroDocumento, IEnumerable<ItemDocumentoFiscalProduto> itensDocumentoFiscalProduto, bool isEcf)
		{
			List<ItemDocumentoFiscalProduto> list = itensDocumentoFiscalProduto.Where((ItemDocumentoFiscalProduto x) => !x.Estoque.IsNormal && x.Estoque.To<EstoqueBase>().Itens.Any((IItemEstoque i) => i is ItemEstoqueSerial)).ToListEmptyWhenNull();
			if (!list.Any())
			{
				return Enumerable.Empty<IDadoEmissor>();
			}
			List<IDadoEmissor> dados;
			if (DadosSistema.TamanhoBobina == TamanhoBobina.CinquentaESeisCinquentaESeteCinquentaEOitoMilimetros && !isEcf)
			{
				dados = new List<IDadoEmissor>
				{
					TextoEmissor.Criar().ComInformacao("================================"),
					TextoEmissor.Criar().ComInformacao("        SERIAIS VENDIDOS        "),
					TextoEmissor.Criar().ComInformacao("================================"),
					TextoEmissor.Criar().ComInformacao($"Documento fiscal: {numeroDocumento:000000000}")
				};
				foreach (ItemDocumentoFiscalProduto item in list)
				{
					item.Estoque.ToDo((EstoqueBase estoque) =>
					{
						List<ItemEstoqueSerial> list2 = estoque.Itens.OfType<ItemEstoqueSerial>().ToListEmptyWhenNull();
						if (list2.Any())
						{
							dados.Add(TextoEmissor.Criar().ComInformacao("                                "));
							dados.Add(TextoEmissor.Criar().ComInformacao($"Codigo: {item.Codigo}"));
							dados.Add(TextoEmissor.Criar().ComInformacao($"Descricao: {item.Descricao.CopiarTexto(21)}"));
							string arg = ((list2.Count > 1) ? "Seriais:" : "Serial:");
							dados.Add(TextoEmissor.Criar().ComInformacao($"{arg} {string.Join(Environment.NewLine, list2.Select((ItemEstoqueSerial x) => x.Codigo))}"));
							dados.Add(TextoEmissor.Criar().ComInformacao("                                "));
						}
					});
				}
			}
			else
			{
				dados = new List<IDadoEmissor>
				{
					TextoEmissor.Criar().ComInformacao("======================================="),
					TextoEmissor.Criar().ComInformacao("            SERIAIS VENDIDOS           "),
					TextoEmissor.Criar().ComInformacao("======================================="),
					TextoEmissor.Criar().ComInformacao($"Documento fiscal: {numeroDocumento:000000000}")
				};
				foreach (ItemDocumentoFiscalProduto item2 in list)
				{
					item2.Estoque.ToDo((EstoqueBase estoque) =>
					{
						List<ItemEstoqueSerial> list2 = estoque.Itens.OfType<ItemEstoqueSerial>().ToListEmptyWhenNull();
						if (list2.Any())
						{
							dados.Add(TextoEmissor.Criar().ComInformacao("                                       "));
							dados.Add(TextoEmissor.Criar().ComInformacao($"Codigo: {item2.Codigo}"));
							dados.Add(TextoEmissor.Criar().ComInformacao($"Descricao: {item2.Descricao.CopiarTexto(28)}"));
							string arg = ((list2.Count > 1) ? "Seriais:" : "Serial:");
							dados.Add(TextoEmissor.Criar().ComInformacao($"{arg} {string.Join(Environment.NewLine, list2.Select((ItemEstoqueSerial x) => x.Codigo))}"));
							dados.Add(TextoEmissor.Criar().ComInformacao("                                       "));
						}
					});
				}
			}
			return dados;
		}

		public static DadosRelatorioCarne40Colunas RetornarDadosRelatorioCarne(long numeroDocumento, DateTime dataInicioEmissao, DadosConsumidorRelatorioCarne consumidor, IEnumerable<DadosParcelaRelatorioCarne> parcelas)
		{
			if (!parcelas.ToListEmptyWhenNull().Any() || consumidor.IsNull())
			{
				return null;
			}
			DadosRelatorioCarne40Colunas dadosRelatorioCarne40Colunas = new DadosRelatorioCarne40Colunas();
			Otus.Infraestrutura.Models.Sessoes.Pessoa empresaLogada = DadosSistema.EmpresaLogada;
			dadosRelatorioCarne40Colunas.NomeEmitente = empresaLogada.Nome;
			dadosRelatorioCarne40Colunas.FantasiaEmitente = empresaLogada.Fantasia;
			dadosRelatorioCarne40Colunas.EnderecoEmitente = empresaLogada.EnderecoToText;
			dadosRelatorioCarne40Colunas.TelefoneEmitente = empresaLogada.Telefone;
			dadosRelatorioCarne40Colunas.NomeCliente = consumidor?.Nome;
			dadosRelatorioCarne40Colunas.DocumentoCliente = consumidor?.CpfCnpjFormatado;
			dadosRelatorioCarne40Colunas.NumeroDocumento = numeroDocumento;
			dadosRelatorioCarne40Colunas.DataInicioEmissao = dataInicioEmissao;
			dadosRelatorioCarne40Colunas.EnderecoCliente = consumidor?.EnderecoToText;
			dadosRelatorioCarne40Colunas.Operador = DadosSistema.NomeUsuario;
			foreach (DadosParcelaRelatorioCarne item2 in parcelas.OrderBy((DadosParcelaRelatorioCarne x) => x.Ordem))
			{
				DadosRelatorioCarneItem40Colunas item = new DadosRelatorioCarneItem40Colunas
				{
					Documento = numeroDocumento.ToString(),
					Ordem = item2.Ordem,
					Vencimento = item2.Vencimento,
					ValorParcela = item2.Valor,
					Referencia = item2.Referencia
				};
				dadosRelatorioCarne40Colunas.CarneItens.Add(item);
			}
			return dadosRelatorioCarne40Colunas;
		}

