	public class RequisicaoExternaLocal
	{
		public RequisicaoExternaDto RequisicaoExterna { get; protected set; }

		public string Numero => $"{RequisicaoExterna.Numero:000000000}";

		public string Dav => $"{RequisicaoExterna.NumeroDav:0000000000000}";

		public string MesaContaCliente => $"{RequisicaoExterna.NumeroMesaContaCliente:0000000000000}";

		public string Ccf => $"{RequisicaoExterna.Ccf:000000000}";

		public string Status => RequisicaoExterna.Status;

		public bool EmitiuCupomFiscal
		{
			get
			{
				if (RequisicaoExterna.Ccf > 0)
				{
					return !string.IsNullOrEmpty(RequisicaoExterna.NumeroFabricacaoEcf);
				}
				return false;
			}
		}

		private RequisicaoExternaLocal()
		{
		}

		private RequisicaoExternaLocal(RequisicaoExternaDto requisicaoExterna)
		{
			RequisicaoExterna = requisicaoExterna;
		}

		protected RequisicaoExternaLocal Build()
		{
			return new RequisicaoExternaLocal(RequisicaoExterna);
		}

		public static RequisicaoExternaLocal Criar()
		{
			return new RequisicaoExternaLocal();
		}

		public RequisicaoExternaLocal ComDto(RequisicaoExternaDto requisicaoExternaDto)
		{
			RequisicaoExterna = requisicaoExternaDto;
			return Build();
		}

		public override string ToString()
		{
			return $"Origem: {RequisicaoExterna.Origem} Número: {RequisicaoExterna.Numero:000000000}";
		}
	}
	public class TanqueStatusViewModel : BindableBase
	{
		public int NumeroTanque
		{
			get
			{
				return GetProperty(() => NumeroTanque);
			}
			set
			{
				SetProperty(() => NumeroTanque, value);
			}
		}

		public string Combustivel
		{
			get
			{
				return GetProperty(() => Combustivel);
			}
			set
			{
				SetProperty(() => Combustivel, value);
			}
		}

		public decimal Capacidade
		{
			get
			{
				return GetProperty(() => Capacidade);
			}
			set
			{
				SetProperty(() => Capacidade, value);
			}
		}

		public decimal Quantidade
		{
			get
			{
				return GetProperty(() => Quantidade);
			}
			set
			{
				SetProperty(() => Quantidade, value);
			}
		}

		public decimal QuantidadeEstoque
		{
			get
			{
				return GetProperty(() => QuantidadeEstoque);
			}
			set
			{
				SetProperty(() => QuantidadeEstoque, value);
			}
		}

		public decimal PercentualNivelEstoque => QuantidadeEstoque * 100m / ((Capacidade == 0m) ? 1m : Capacidade);

		public TanqueStatusViewModel(int numeroTanque, string combustivel, decimal capacidade, decimal quantidade, decimal quantidadeEstoque)
		{
			NumeroTanque = numeroTanque;
			Combustivel = combustivel;
			Capacidade = capacidade;
			Quantidade = quantidade;
			QuantidadeEstoque = quantidadeEstoque;
		}

		public void Atualizar(TanqueDto tanque)
		{
			NumeroTanque = tanque.Numero;
			Capacidade = tanque.CapacidadeNominal;
			Combustivel = tanque.Descricao;
			Quantidade = tanque.Quantidade;
			IEnumerable<ProdutoServicoEmpresaDto> source = tanque.Bombas.SelectMany((BombaDto x) => x.Bicos.Select((BicoDto y) => y.ProdutoServicoEmpresa));
			QuantidadeEstoque = source.DistinctBy((ProdutoServicoEmpresaDto x) => x.Id).Sum((ProdutoServicoEmpresaDto y) => y.ProdutoEmpresa.Estoque.Quantidade);
		}
	}
