	public class ParaibaLegalMensagemPromocional : MensagemPromocional, IMensagemPromocional
	{
		private decimal _total;

		private string _ie;

		private DateTime _data;

		private int _coo;

		public int Indice => 5;

		protected ParaibaLegalMensagemPromocional()
		{
		}

		protected ParaibaLegalMensagemPromocional(decimal total = 0m, string ie = "", DateTime data = default(DateTime), int coo = 0)
		{
			_total = total;
			_ie = ie;
			_data = data;
			_coo = coo;
			string text = string.Empty;
			try
			{
				text = _total.ToString("n2").Replace(CultureInfo.CurrentCulture.NumberFormat.CurrencyGroupSeparator, string.Empty).Replace(CultureInfo.CurrentCulture.NumberFormat.CurrencyDecimalSeparator, string.Empty);
				text = (text.StartsWith("0") ? text.Remove(0, 1) : text);
			}
			catch
			{
			}
			AdicionarLinha("PARAÍBA LEGAL - RECEITA CIDADÃ");
			AdicionarLinha("TORPEDO PREMIADO:");
			AdicionarLinha($"{_ie.ApenasNumeros()} {_data.Date:ddMMyyyy} {_coo:000000} {text}");
		}

		public static ParaibaLegalMensagemPromocional Criar()
		{
			return new ParaibaLegalMensagemPromocional();
		}

		public ParaibaLegalMensagemPromocional ComTotal(decimal total)
		{
			_total = total;
			return Build();
		}

		public ParaibaLegalMensagemPromocional ComIe(string ie)
		{
			_ie = ie;
			return Build();
		}

		public ParaibaLegalMensagemPromocional ComData(DateTime data)
		{
			_data = data;
			return Build();
		}

		public ParaibaLegalMensagemPromocional ComCoo(int coo)
		{
			_coo = coo;
			return Build();
		}

		private ParaibaLegalMensagemPromocional Build()
		{
			return new ParaibaLegalMensagemPromocional(_total, _ie, _data, _coo);
		}
	}
