		protected ReferenciaSistemaAbastecimentoMensagemPromocional(int numeroBico, decimal encerranteInicial, decimal encerranteFinal, decimal litros, bool itemCancelado, bool cupomAutomatico, bool cupomManual)
		{
			string arg = $":B{numeroBico:00} EI{encerranteInicial:0000000.000} EF{encerranteFinal:0000000.000} V{litros:0.000}";
			string text = $"#CF{arg}";
			if (cupomAutomatico)
			{
				text += "A";
			}
			if (cupomManual)
			{
				text += "M";
			}
			AdicionarLinha(text);
			if (itemCancelado)
			{
				AdicionarLinha($"#CC{arg}");
			}
		}

