	public class TributoMensagemPromocional : MensagemPromocional, IMensagemPromocional
	{
		private readonly IEnumerable<ItemDocumentoFiscal> _itens;

		public int Indice => 7;

		public decimal TotalTributos => _itens.Sum((ItemDocumentoFiscal x) => x.TotalTributos);

		public decimal TotalTributosMunicipais => _itens.Sum((ItemDocumentoFiscal x) => x.TotalTributosMunicipais);

		public decimal TotalTributosEstaduais => _itens.Sum((ItemDocumentoFiscal x) => x.TotalTributosEstaduais);

		public string FonteChaveNcm => _itens.FirstOrDefault()?.FonteNcm;

		private TributoMensagemPromocional()
		{
		}

		public TributoMensagemPromocional(IEnumerable<ItemDocumentoFiscal> itens)
		{
			_itens = itens;
			string text = $"Trib Aprox {CultureInfo.CurrentCulture.NumberFormat.CurrencySymbol}: ";
			if (TotalTributos > 0m)
			{
				text += $"Fed {TotalTributos:n2} ";
			}
			if (TotalTributosEstaduais > 0m)
			{
				text += $"Est {TotalTributosEstaduais:n2} ";
			}
			if (TotalTributosMunicipais > 0m)
			{
				text += $"Mun {TotalTributosMunicipais:n2} ";
			}
			text += $"F:{FonteChaveNcm.TrimEnd()}";
			AdicionarLinha(text);
		}

		public static TributoMensagemPromocional Criar()
		{
			return new TributoMensagemPromocional();
		}

		public TributoMensagemPromocional ComItensDocumentoFiscal(IEnumerable<ItemDocumentoFiscal> itens)
		{
			return new TributoMensagemPromocional(itens);
		}
	}
