		protected VendedorMensagemPromocional(IEnumerable<string> vendedores)
		{
			_vendedores = vendedores.Distinct();
			AdicionarLinha((_vendedores.Count() == 1) ? $"Vendedor: {_vendedores.FirstOrDefault()}" : $"Vendedor(es): {_vendedores.Aggregate(string.Empty, (string current, string vendedor) => current + $"{vendedor}; ")}");
		}

