	{
		public static string DescricaoEcf => "Cart. Digital";

		public IList<InformacaoTransacaoCarteiraDigital> InformacoesTransacoes { get; protected set; } = new List<InformacaoTransacaoCarteiraDigital>();

		public Otus.Modulo.PontoDeVendas.Interfaces.ITefService TefService { get; protected set; }

		public IEmissorService EmissorService { get; protected set; }

