		public override EspeciePagamento EspeciePagamento => EspeciePagamentoValueObjectService.ObterEspeciePagamentoPorCodigo(24);

		public override int EspeciePagamentoPosicionar => 26;

		public CarteiraDigitalTefViewModel()
		{
		}

		private CarteiraDigitalTefViewModel(Otus.Modulo.PontoDeVendas.Interfaces.ITefService tefService, PainelTotalizacaoEmissorBase painelTotalizacao, IEmissorService emissorService)
		{
			TefService = tefService;
			PainelTotalizacao = painelTotalizacao;
			EmissorService = emissorService;
		}

		public static CarteiraDigitalTefViewModel Criar()
		{
			return new CarteiraDigitalTefViewModel();
		}

		public CarteiraDigitalTefViewModel ComTefService(Otus.Modulo.PontoDeVendas.Interfaces.ITefService tefService)
		{
			TefService = tefService;
			return Build();
		}

		public CarteiraDigitalTefViewModel ComEmissorService(IEmissorService emissorService)
		{
			EmissorService = emissorService;
			return Build();
		}

		public CarteiraDigitalTefViewModel ComPainelTotalizacao(PainelTotalizacaoEmissorBase painelTotalizacao)
		{
			PainelTotalizacao = painelTotalizacao;
			return Build();
		}

		private CarteiraDigitalTefViewModel Build()
		{
			return new CarteiraDigitalTefViewModel(TefService, PainelTotalizacao, EmissorService);
		}

		public override void SomarValor(decimal valor)
		{
			int indiceEspecieEcf = 0;
			EmissorService.ToDo((IEcfService ecf) =>
			{
				indiceEspecieEcf = ecf.Especies.Where((Especie especie) => especie.PermiteVinculado).ToArray().FindIndex((Especie x) => x.Descricao.Equals(DescricaoEcf));
			});
			decimal subtotal = PainelTotalizacao.Subtotal;
			decimal totalPagamentos = PainelTotalizacao.Lista.Itens.Sum((ItemPagamentoViewModel x) => x.Valor);
			TefService.CartDigi(valor, subtotal, totalPagamentos, PainelTotalizacao.PossuiAcrescimoDesconto, indiceEspecieEcf);
		}

		public void AdicionarCartaoResposta(InformacaoTransacaoCarteiraDigital informacaoTransacaoTef)
		{
			base.SomarValor(informacaoTransacaoTef.ValorTotal);
			InformacoesTransacoes.Add(informacaoTransacaoTef);
		}
	}
