	public class CartaoViewModel : ItemPagamentoViewModel, ICartao, IItemPagamento
	{
		public static string DescricaoEcf => "Cartao";

		public IList<InformacaoTransacaoTef> Cartoes { get; protected set; } = new List<InformacaoTransacaoTef>();

		protected Seletor<IPainel> Seletor { get; set; }

		public Otus.Modulo.PontoDeVendas.Interfaces.ITefService TefService { get; protected set; }

		public IEmissorService EmissorService { get; protected set; }

		public PainelTotalizacaoEmissorBase PainelTotalizacao { get; protected set; }

		public override string Especie => $"[ T ] {Descricao}";

		public override EspeciePagamento EspeciePagamento => EspeciePagamentoValueObjectService.ObterEspeciePagamentoPorCodigo(2);

		public override int EspeciePagamentoPosicionar => 2;

		public CartaoViewModel()
		{
		}

		private CartaoViewModel(Seletor<IPainel> seletor, Otus.Modulo.PontoDeVendas.Interfaces.ITefService tefService, PainelTotalizacaoEmissorBase painelTotalizacao, IEmissorService emissorService)
		{
			Seletor = seletor;
			TefService = tefService;
			PainelTotalizacao = painelTotalizacao;
			EmissorService = emissorService;
		}

		public static CartaoViewModel Criar()
		{
			return new CartaoViewModel();
		}

		public CartaoViewModel ComSeletor(Seletor<IPainel> seletor)
		{
			Seletor = seletor;
			return Build();
		}

		public CartaoViewModel ComTefService(Otus.Modulo.PontoDeVendas.Interfaces.ITefService tefService)
		{
			TefService = tefService;
			return Build();
		}

		public CartaoViewModel ComEmissorService(IEmissorService emissorService)
		{
			EmissorService = emissorService;
			return Build();
		}

		public CartaoViewModel ComPainelTotalizacao(PainelTotalizacaoEmissorBase painelTotalizacao)
		{
			PainelTotalizacao = painelTotalizacao;
			return Build();
		}

		private CartaoViewModel Build()
		{
			return new CartaoViewModel(Seletor, TefService, PainelTotalizacao, EmissorService);
		}

		public override void SomarValor(decimal valor)
		{
			int indiceEspecieEcf = 0;
			EmissorService.ToDo((IEcfService ecf) =>
			{
				indiceEspecieEcf = ecf.Especies.Where((Especie especie) => especie.PermiteVinculado).ToArray().FindIndex((Especie x) => x.Descricao.Equals(DescricaoEcf));
			});
			decimal subtotal = PainelTotalizacao.Subtotal;
			decimal totalPagamentos = PainelTotalizacao.Lista.Itens.Sum((ItemPagamentoViewModel x) => x.Valor);
			IEnumerable<ItemDocumentoFiscal> enumerable = null;
			if (DadosSistema.IsPostoCombustivel)
			{
				PreDocumentoFiscal preDocumentoFiscal = Seletor.Get<PainelDocumentoFiscal>()?.PreDocumentoFiscal;
				if (preDocumentoFiscal.IsNotNull() && preDocumentoFiscal.Itens.Where((ItemDocumentoFiscal x) => x.Ativo).Any(IsCombustivelOuDerivadoPetroleo) && preDocumentoFiscal.Itens.Where((ItemDocumentoFiscal x) => x.Ativo).All(IsCombustivelOuDerivadoPetroleo) && TefService.ConfiguracaoTef.Tipo == TipoTef.Sitef && DialogoFactory.MostrarDialogoSimNao("O pagamento será em CARTÃO COMBUSTÍVEL?") == MessageBoxResult.Yes)
				{
					enumerable = preDocumentoFiscal.Itens.Where((ItemDocumentoFiscal x) => x.Ativo && IsCombustivelOuDerivadoPetroleo(x));
				}
			}
			if (enumerable != null && enumerable.Any())
			{
				IEnumerable<TefCombustivel> tefCombustiveis = enumerable.Select((ItemDocumentoFiscal x) => TefCombustivel.Criar().ComCodigoCombustivel(x.Codigo).ComQuantidadeCombustivel(x.Quantidade)
					.ComValorCombustivel(x.Total)
					.Build());
				TefService.Crt(valor, subtotal, totalPagamentos, PainelTotalizacao.PossuiAcrescimoDesconto, indiceEspecieEcf, isRecebimentoPdv: false, tefCombustiveis);
			}
			else
			{
				TefService.Crt(valor, subtotal, totalPagamentos, PainelTotalizacao.PossuiAcrescimoDesconto, indiceEspecieEcf);
			}
		}

		private static bool IsCombustivelOuDerivadoPetroleo(ItemDocumentoFiscal item)
		{
			if (item.Is<ItemDocumentoFiscalCombustivel>())
			{
				return true;
			}
			return item.ProdutoServicoLocal?.ProdutoServicoHistorico?.Tipo == TipoProdutoServico.Combustivel;
		}

		public void AdicionarCartaoResposta(InformacaoTransacaoTef informacaoTransacaoTef)
		{
			base.SomarValor(informacaoTransacaoTef.ValorTotal);
			Cartoes.Add(informacaoTransacaoTef);
		}
	}
	public class CartaoPosViewModel : ItemPagamentoViewModel, ICartaoPos, IItemPagamento
	{
		private decimal _valor;

		private Action<RedePosLocal> _callbackCartaoRestaurante;

		public override decimal Valor => Redes.Sum((RedePosLocal x) => x.Valor);

		public IList<RedePosLocal> Redes { get; protected set; } = new List<RedePosLocal>();

