			return new CartaoPosViewModel
			{
				Seletor = seletor,
				Valor = Valor
			};
		}

		public CartaoPosViewModel ComEmissorService(IEmissorService emissorService)
		{
			EmissorService = emissorService;
			return new CartaoPosViewModel
			{
				Seletor = Seletor,
				Valor = Valor,
				EmissorService = emissorService
			};
		}

		public override void SomarValor(decimal valor)
		{
			_valor = valor;
			Seletor.Get<PainelBuscaAdministradoraCartao>().SetarValor(_valor);
			Seletor.Get<PainelBuscaAdministradoraCartao>().SetarIsRecebimento();
			Seletor.Selecionar<PainelBuscaAdministradoraCartao, PainelTotalizacaoEmissorBase>();
			RaisePropertyChanged(() => Valor);
		}

		public void Adicionar(RedePosLocal redePosLocal)
		{
			if (redePosLocal != null)
			{
				Redes.Add(redePosLocal.SomarValor(_valor));
				_callbackCartaoRestaurante?.Invoke(redePosLocal);
			}
		}

		public void AdicionarCartaoPosRestaurante(RedePosLocal redePosLocal, Action<RedePosLocal> callback)
		{
			_callbackCartaoRestaurante = callback;
			Adicionar(redePosLocal);
		}

		public override void Zerar()
		{
			foreach (RedePosLocal rede in Redes)
			{
				rede.Zerar();
			}
			base.Zerar();
		}
	}
