			}
			Seletor.Get<PainelDocumentoFiscal>()?.PreDocumentoFiscal?.AdicionarAutorizacao(autorizacaoDto);
			if (Seletor.Get<PainelDocumentoFiscal>().Consumidor.IsNull() || Seletor.Get<PainelDocumentoFiscal>().Consumidor.Pessoa.Is<Consumidor>())
			{
				throw new Exception("Para finalizar o documento na espécie Prazo o cliente deve estar cadastrado!");
			}
			if (!Seletor.Get<PainelDocumentoFiscal>().Consumidor.PossuiLimiteDeCreditoDisponivel(valor))
			{
				if (DialogoFactory.MostrarDialogoConfirmaInformacaoOculta("Limite: " + Seletor.Get<PainelDocumentoFiscal>().Consumidor.LimiteDeCredito.FormatarCampoValor(2) + Environment.NewLine + "Saldo: " + Seletor.Get<PainelDocumentoFiscal>().Consumidor.SaldoLimiteDeCredito.FormatarCampoValor(2), "Situação 2. Verifique!") != MessageBoxResult.OK)
				{
					return;
				}
				AutorizacaoDto autorizacaoDto2 = SessaoService.VerificarPermissao<DigisatServer.Infrastructure.Crosscutting.Module.PontoDeVenda, PermitirUltrapassarLimiteCredito>();
				if (autorizacaoDto2 == null)
				{
					return;
				}
				Seletor.Get<PainelDocumentoFiscal>()?.PreDocumentoFiscal?.AdicionarAutorizacao(autorizacaoDto2);
			}
			Seletor.Get<PainelParcelamento>().SetarValorParcelamento(valor);
			Seletor.Get<PainelParcelamento>().SetarFormaPagamento(Seletor.Get<PainelDocumentoFiscal>().Consumidor.Pessoa.Cliente?.FormaPagamentoReferencia ?? ObjectId.Empty);
			Seletor.Selecionar<PainelParcelamento, PainelTotalizacaoEmissorBase>();
			PainelTotalizacaoEmissorBase painelTotalizacaoEmissorBase = Seletor.Get<PainelTotalizacaoEmissorBase>();
			PainelParcelamento painelParcelamento = Seletor.Get<PainelParcelamento>();
			if (!painelParcelamento.Confirmado)
			{
				painelTotalizacaoEmissorBase.LimparParcelasPrazo(3);
				return;
			}
			painelTotalizacaoEmissorBase.LimparParcelasPrazo(3);
			foreach (Parcela iten in painelParcelamento.Parcelas.Valor.Itens)
			{
				painelTotalizacaoEmissorBase.AdicionarParcela(ParcelaPrazo.Criar().ComReferencia(iten.Referencia).ComOrdem(iten.Ordem)
					.ComVencimento(iten.Vencimento)
					.ComConta(iten.ContaSelecionada.Conta)
					.ComValor(iten.Valor)
					.ComTaxaJuro(iten.TaxaJuro)
					.ComGerarBoleto(iten.GerarBoleto)
					.ComObservacao(iten.Observacao)
					.ComCodigoEspeciePagamento(3));
			}
			Zerar();
			base.SomarValor(valor);
		}
	}
