	public class ValePresenteViewModel : ItemPagamentoViewModel, IValePresente, IItemPagamento
	{
		private readonly Lista<ValePresenteDto> _valePresente = new Lista<ValePresenteDto>();

		private decimal _valor;

		public Seletor<IPainel> Seletor { get; protected set; }

		public override string Especie => "[ Y ] Vale presente";

		public override EspeciePagamento EspeciePagamento => EspeciePagamentoValueObjectService.ObterEspeciePagamentoPorCodigo(23);

		public override int EspeciePagamentoPosicionar => 23;

		public override string Descricao => EspeciePagamentoValueObjectService.ObterEspeciePagamentoPorCodigo(23).Descricao;

		public override int CodigoSat => 12;

		public static ValePresenteViewModel Criar()
		{
			return new ValePresenteViewModel();
		}

		public ValePresenteViewModel ComSeletor(Seletor<IPainel> seletor)
		{
			Seletor = seletor;
			return new ValePresenteViewModel
			{
				Seletor = seletor,
				Valor = Valor
			};
		}

		public override void SomarValor(decimal valor)
		{
			decimal subtotal = Seletor.Get<PainelTotalizacaoEmissorBase>().Subtotal;
			decimal num = Seletor.Get<PainelTotalizacaoEmissorBase>().Lista.Itens.Sum((ItemPagamentoViewModel x) => x.Valor);
			decimal num2 = subtotal - num;
			if (valor > num2)
			{
				throw new Exception("Recebimento em 'Vale presente' deve ser limitado ao valor restante a pagar.");
			}
			_valor = valor;
			Seletor.Selecionar<PainelBuscaValePresente>();
			Seletor.Get<PainelBuscaValePresente>().SetarCallback(Callback);
		}

		private void Callback(ValePresenteDto valePresente)
		{
			if (_valePresente.Itens.Any((ValePresenteDto x) => x.Id.Equals(valePresente.Id)))
			{
				throw new Exception("Este vale presente já foi selecionado.");
			}
			if (valePresente.Valor > _valor)
			{
				if (DialogoFactory.MostrarDialogoSimNao($"O valor do vale presente é maior que o valor a receber.\nVale Presente: {valePresente.Valor:c2}\nReceber: {_valor:c2}\nDeseja continuar?") != MessageBoxResult.Yes)
				{
					_valePresente.Adicionar(valePresente);
					return;
				}
				if (DialogoFactory.MostrarDialogoSimNao("Deseja criar um novo vale presente com o valor restante?") == MessageBoxResult.Yes)
				{
					ValePresenteDto novoVale = valePresente;
					novoVale.Valor = valePresente.Valor - _valor;
					ValePresenteDto contraValePresente = DadosSistema.GetService().Canal((IValePresenteModuleService service) => service.AdicionarContraVale(novoVale));
					Seletor.Get<PainelTotalizacaoEmissorBase>().ContraValePresente = contraValePresente;
				}
			}
			else if (valePresente.Valor < _valor)
			{
				if (DialogoFactory.MostrarDialogoSimNao($"O valor do vale presente é menor que o valor a receber.\nVale Presente: {valePresente.Valor:c2}\nReceber: {_valor:c2}\nDeseja continuar?") == MessageBoxResult.Yes)
				{
					base.SomarValor(valePresente.Valor);
					_valePresente.Adicionar(valePresente);
				}
				return;
			}
			_valePresente.Adicionar(valePresente);
			base.SomarValor(_valor);
		}

		public IEnumerable<ValePresenteDto> GetValePresente()
		{
			return _valePresente.Itens;
		}
	}
