	public class ValeTrocaViewModel : ItemPagamentoViewModel, ICreditoLoja, IItemPagamento
	{
		public Seletor<IPainel> SeletorDireito { get; protected set; }

		public override string Especie => "[ X ] Crédito loja";

		public override EspeciePagamento EspeciePagamento => EspeciePagamentoValueObjectService.ObterEspeciePagamentoPorCodigo(22);

		public override int EspeciePagamentoPosicionar => 22;

		public override string Descricao => EspeciePagamentoValueObjectService.ObterEspeciePagamentoPorCodigo(22).Descricao;

		public ISessaoService SessaoService { get; set; }

		public static ValeTrocaViewModel Criar()
		{
			return new ValeTrocaViewModel();
		}

		public ValeTrocaViewModel ComSeletorDireito(Seletor<IPainel> seletor)
		{
			SeletorDireito = seletor;
			return new ValeTrocaViewModel
			{
				SeletorDireito = seletor,
				Valor = Valor
			};
		}

		public ValeTrocaViewModel ComSessaoService(ISessaoService sessaoService)
		{
			SessaoService = sessaoService;
			return this;
		}

		public override void SomarValor(decimal valor)
		{
			if (valor == 0m)
			{
				return;
			}
			if (SeletorDireito.Get<PainelDocumentoFiscal>().Consumidor.IsNull() || SeletorDireito.Get<PainelDocumentoFiscal>().Consumidor.Pessoa.Is<Consumidor>())
			{
				SeletorDireito.Selecionar<PainelBuscaConsumidor, PainelTotalizacaoEmissorBase>();
			}
			if (SeletorDireito.Get<PainelDocumentoFiscal>().Consumidor.IsNull() || SeletorDireito.Get<PainelDocumentoFiscal>().Consumidor.Pessoa.Is<Consumidor>())
			{
				throw new Exception("Para finalizar o documento na espécie 'Crédito loja' o cliente deve estar cadastrado!");
			}
			decimal num = SeletorDireito.Get<PainelDocumentoFiscal>().Consumidor.TotalCreditoDevolucoes - Valor;
			if (valor > num)
			{
				if (num <= 0m)
				{
					if (DialogoFactory.MostrarDialogoSimNao($"O total de crédito para troca de mercadorias do cliente é {num:C}. Deseja continuar?") == MessageBoxResult.Yes)
					{
						AutorizacaoDto autorizacaoDto = SessaoService.VerificarPermissao<DigisatServer.Infrastructure.Crosscutting.Module.PontoDeVenda, PermitirUsarValeTrocaAcimaValorCreditoCliente>();
						if (autorizacaoDto != null)
						{
							SeletorDireito.Get<PainelDocumentoFiscal>()?.PreDocumentoFiscal?.AdicionarAutorizacao(autorizacaoDto);
							base.SomarValor(valor);
							SetarObservacao(valor);
						}
					}
				}
				else if (DialogoFactory.MostrarDialogoSimNao($"O total de crédito para troca de mercadorias do cliente é {num:C}. Deseja utilizar apenas o valor disponível de crédito?") == MessageBoxResult.Yes)
				{
					base.SomarValor(num);
					SetarObservacao(valor);
				}
				else
				{
					AutorizacaoDto autorizacaoDto = SessaoService.VerificarPermissao<DigisatServer.Infrastructure.Crosscutting.Module.PontoDeVenda, PermitirUsarValeTrocaAcimaValorCreditoCliente>();
					if (autorizacaoDto != null)
					{
						SeletorDireito.Get<PainelDocumentoFiscal>()?.PreDocumentoFiscal?.AdicionarAutorizacao(autorizacaoDto);
						base.SomarValor(valor);
						SetarObservacao(valor);
					}
				}
			}
			else
			{
				SetarObservacao(valor);
				base.SomarValor(valor);
			}
		}

		public void SetarObservacao(decimal valor)
		{
			decimal num = SeletorDireito.Get<PainelDocumentoFiscal>().Consumidor.TotalCreditoDevolucoes - valor;
			if (num > 0m)
			{
				SeletorDireito.Get<PainelTotalizacaoBase>().AdicionarMensagemPromocional(ObservacaoMensagemPromocional.Criar().ComObservacao($"Crédito disponível: R$ {num.FormatarCampoValor(2)}"));
			}
		}
	}
