	public abstract class Documento<T> : BindableBase where T : Documento<T>, new()
	{
		public long Numero { get; protected set; }

		public ICommand DelCommand { get; protected set; }

		protected Documento()
		{
		}

		protected Documento(long numero, ICommand command)
		{
			Numero = numero;
			DelCommand = command;
		}

		public static T Criar()
		{
			return new T();
		}

		public T ComNumero(long numero)
		{
			Numero = numero;
			return this as T;
		}

		public T ComCommand(ICommand command)
		{
			DelCommand = command;
			return this as T;
		}

		public abstract T Build();
	}
