	{
		public bool TodosSelecionados
		{
			get
			{
				return GetProperty(() => TodosSelecionados);
			}
			set
			{
				SetProperty(() => TodosSelecionados, value, SelecionarTodos);
			}
		}

		public ICommand SpaceCommand { get; set; }

		public ItemInteracaoListaResumoNfce()
		{
		}

		public ItemInteracaoListaResumoNfce(string descricao, Lista<ItemResumoNfce> valor)
			: base(descricao, valor)
		{
			TodosSelecionados = true;
			SpaceCommand = new DelegateCommand(Selecionar);
		}

		public void Selecionar()
		{
			if (Valor.ItemSelecionado.IsNotNull())
			{
				Valor.ItemSelecionado.Selecionar(!Valor.ItemSelecionado.Selecionado);
			}
		}

		private void SelecionarTodos()
		{
			foreach (ItemResumoNfce iten in Valor.Itens)
			{
				iten.Selecionado = TodosSelecionados;
			}
		}

		public override void Limpar()
		{
			Valor.Limpar();
		}
	}
