	public class ItemInteracaoListaEstoque : ItemInteracaoBase<ItemInteracaoListaEstoque, Lista<ItemBase>>
	{
		private decimal _quantidadeInformada;

		public bool MostrarQuantidadeInformada => _quantidadeInformada > 0m;

		public decimal Quantidade
		{
			get
			{
				return GetProperty(() => Quantidade);
			}
			set
			{
				SetProperty(() => Quantidade, value);
			}
		}

		public ItemInteracaoListaEstoque()
		{
		}

		public ItemInteracaoListaEstoque(string descricao, Lista<ItemBase> valor)
			: base(descricao, valor)
		{
			foreach (ItemBase iten in valor.Itens)
			{
				iten.WhenAlterouQuantidade.Subscribe((decimal x) =>
				{
					Quantidade = Valor.Itens.Sum((ItemBase z) => z.Quantidade);
				});
				iten.UsarQuantidadeInformadaEvent += ItemOnUsarQuantidadeInformadaEvent;
			}
		}

		private void ItemOnUsarQuantidadeInformadaEvent(object sender, EventArgs eventArgs)
		{
			ItemLote itemLote = sender as ItemLote;
			if (itemLote.IsNotNull() && _quantidadeInformada > 0m)
			{
				itemLote.Quantidade = _quantidadeInformada;
			}
		}

		public ItemInteracaoListaEstoque SetarQuantidadeInformada(decimal quantidadeInformada)
		{
			_quantidadeInformada = quantidadeInformada;
			return this;
		}

		public override void Limpar()
		{
			_quantidadeInformada = -1m;
			Valor.Limpar();
		}
	}
