	public class ItemMesaConta : ItemCheckBox
	{
		public bool MostrarBotoes => !DadosSistema.IsPafEcf;

		public ItemMesaContaDto Dto { get; protected set; }

		public string AdicionaisToString
		{
			get
			{
				if (!Dto.Adicionais.IsNotNull() || !Dto.Adicionais.Any())
				{
					return string.Empty;
				}
				return string.Join(Environment.NewLine, Dto.Adicionais?.Select((ItemMesaContaAdicionalDto x) => $"  + {x.Quantidade} x {x.DescricaoTela}"));
			}
		}

		public decimal Quantidade
		{
			get
			{
				return GetProperty(() => Quantidade);
			}
			set
			{
				SetProperty(() => Quantidade, value);
			}
		}

		public bool Agrupado
		{
			get
			{
				return GetProperty(() => Agrupado);
			}
			set
			{
				SetProperty(() => Agrupado, value);
			}
		}

		public Lista<ItemMesaConta> ItensDesmembrados
		{
			get
			{
				return GetProperty(() => ItensDesmembrados);
			}
			set
			{
				SetProperty(() => ItensDesmembrados, value);
			}
		}

		public decimal Total => Dto.TotalAdicionais + Dto.ValorUnitario;

		public ICommand AumentarQuantidadeCommand { get; set; }

		public ICommand DiminuirQuantidadeCommand { get; set; }

		public ICommand DividirCommand { get; set; }

		private ItemMesaConta(ItemMesaContaDto dto)
		{
			Dto = dto;
			Descricao = $"{dto.Codigo} - {dto.Descricao}";
			Quantidade = Dto.Quantidade;
			Agrupado = true;
			AumentarQuantidadeCommand = new DelegateCommand(AumentarQuantidade, PodeAumentarQuantidade);
			DiminuirQuantidadeCommand = new DelegateCommand(DiminuirQuantidade, PodeDiminuirQuantidade);
			DividirCommand = new DelegateCommand(Dividir, PodeDividir);
		}

		private void AumentarQuantidade()
		{
			Quantidade += ((Quantidade < 1m) ? 0.1m : 1m);
			if (Quantidade > Dto.Quantidade)
			{
				Quantidade = Dto.Quantidade;
			}
		}

		private bool PodeAumentarQuantidade()
		{
			if (Quantidade < Dto.Quantidade)
			{
				return !Dto.Cancelado;
			}
			return false;
		}

		private void DiminuirQuantidade()
		{
			Quantidade -= ((Quantidade <= 1m) ? 0.1m : 1m);
		}

		private bool PodeDiminuirQuantidade()
		{
			if (Quantidade > 0.1m)
			{
				return !Dto.Cancelado;
			}
			return false;
		}

		private void Dividir()
		{
			decimal num = DialogoFactory.MostrarDialogoLancamentoManualInteiro("Partes", 2, 2, int.MaxValue);
			if (num == 0m)
			{
				return;
			}
			ItensDesmembrados = new Lista<ItemMesaConta>();
			Selecionado = true;
			decimal valorComissao = (Dto.ValorComissao / num).ArredondarParaDuasCasasDecimais();
			for (int i = 0; (decimal)i < num; i++)
			{
				ItemMesaContaDto itemMesaContaDto = Clone.ObjectGraph(Dto);
				itemMesaContaDto.Quantidade = HelperDecimal.Arredondar(Quantidade / num, 3);
				itemMesaContaDto.ValorComissao = valorComissao;
				ItensDesmembrados.Adicionar(Criar(itemMesaContaDto));
			}
			if (Quantidade != ItensDesmembrados.Itens.Sum((ItemMesaConta x) => x.Quantidade))
			{
				decimal num2 = Quantidade - ItensDesmembrados.Itens.Sum((ItemMesaConta x) => x.Quantidade);
				ItensDesmembrados.Itens.LastOrDefault().Quantidade += num2;
				ItensDesmembrados.Itens.LastOrDefault().Dto.Quantidade += num2;
			}
			ItensDesmembrados.Itens?.FirstOrDefault()?.Selecionar();
			Lista<ItemMesaConta> itensDesmembrados = ItensDesmembrados;
			bool? flag;
			if (itensDesmembrados == null)
			{
				flag = null;
			}
			else
			{
				IReadOnlyCollection<ItemMesaConta> itens = itensDesmembrados.Itens;
				flag = ((itens != null) ? new bool?(!itens.Any()) : ((bool?)null));
			}
			Agrupado = flag ?? true;
		}

		private bool PodeDividir()
		{
			if (Quantidade > 0m)
			{
				return !Dto.Cancelado;
			}
			return false;
		}

		public static ItemMesaConta Criar(ItemMesaContaDto dto)
		{
			return new ItemMesaConta(dto);
		}

		public ItemMesaContaParcialDto ObterDto()
		{
			if (ItensDesmembrados?.Itens?.Any() ?? false)
			{
				if (!ItensDesmembrados.Itens.Any((ItemMesaConta x) => x.Selecionado))
				{
					throw new Exception("Selecione pelo menos uma parte");
				}
				return new ItemMesaContaParcialDto
				{
					Quantidade = ItensDesmembrados.Itens.Where((ItemMesaConta x) => x.Selecionado).Sum((ItemMesaConta y) => y.Quantidade),
					ItemMesaContaReferencia = Dto.Id
				};
			}
			return new ItemMesaContaParcialDto
			{
				Quantidade = Quantidade,
				ItemMesaContaReferencia = Dto.Id
			};
		}
	}
	public abstract class ItemInteracaoBase<TClass, TValor> : DigisatServer.Infrastructure.Crosscutting.Mvvm.Validation, IItemInteracao, IDisposable where TClass : class, new()
	{
		public string Descricao { get; protected set; }

		public virtual TValor Valor
		{
			get
			{
				return GetProperty(() => Valor);
			}
			set
			{
				SetProperty(() => Valor, value);
			}
		}

		public IObservable<string> WhenPropertyChanged => from x in Observable.FromEventPattern<PropertyChangedEventHandler, PropertyChangedEventArgs>((PropertyChangedEventHandler h) =>
			{
				PropertyChanged += h;
			}, (PropertyChangedEventHandler h) =>
			{
				PropertyChanged -= h;
			})
			select x.EventArgs.PropertyName;

		protected ItemInteracaoBase()
		{
		}

		protected ItemInteracaoBase(string descricao, TValor valor)
		{
			Descricao = descricao;
			Valor = valor;
		}

		public static TClass Criar()
		{
			return new TClass();
		}

		public TClass ComDescricao(string descricao)
		{
			Descricao = descricao;
			return this as TClass;
		}

		public TClass ComValor(TValor valor)
		{
			Valor = valor;
			return this as TClass;
		}

		public virtual TClass Build()
		{
			return (TClass)Activator.CreateInstance(typeof(TClass), Descricao, Valor);
		}

		public virtual void Dispose()
		{
		}

		public abstract void Limpar();
	}
