		{
			valor?.PosicionarNoPrimeiro();
		}

		public override void Limpar()
		{
			if (Valor.IsNull())
			{
				return;
			}
			foreach (IItemInteracao iten in Valor.Itens)
			{
				iten.Limpar();
			}
		}
	}
