	public class ItemInteracaoListaParcelamento : ItemInteracaoBase<ItemInteracaoListaParcelamento, Lista<Parcela>>
	{
		public decimal Diferenca => ValorParcelamento - Valor.Itens.Sum((Parcela x) => x.Valor);

		public decimal ValorParcelamento
		{
			get
			{
				return GetProperty(() => ValorParcelamento);
			}
			set
			{
				SetProperty(() => ValorParcelamento, value);
			}
		}

		public ItemInteracaoListaParcelamento()
		{
		}

		public ItemInteracaoListaParcelamento(string descricao, Lista<Parcela> valor, decimal valorParcelamento)
			: base(descricao, valor)
		{
			ValorParcelamento = valorParcelamento;
			foreach (Parcela iten in Valor.Itens)
			{
				iten.PropertyChanged += ParcelaOnPropertyChanged;
			}
		}

		private void ParcelaOnPropertyChanged(object sender, PropertyChangedEventArgs propertyChangedEventArgs)
		{
			RaisePropertyChanged(() => Diferenca);
		}

		public ItemInteracaoListaParcelamento ComValorParcelamento(decimal valorParcelamento)
		{
			ValorParcelamento = valorParcelamento;
			return this;
		}

		public override ItemInteracaoListaParcelamento Build()
		{
			return new ItemInteracaoListaParcelamento(Descricao, Valor, ValorParcelamento);
		}

		public override void Dispose()
		{
			foreach (Parcela iten in Valor.Itens)
			{
				iten.PropertyChanged -= ParcelaOnPropertyChanged;
			}
		}

		public override void Limpar()
		{
			Valor.Limpar();
		}
	}
