	public class ItemInteracaoListaRecebimento : ItemInteracaoBase<ItemInteracaoListaRecebimento, Lista<Recebimento>>
	{
		public double MaxHeight { get; set; }

		public IItemInteracao OrigemDaBusca
		{
			get
			{
				return GetProperty(() => OrigemDaBusca);
			}
			set
			{
				SetProperty(() => OrigemDaBusca, value);
			}
		}

		public IItemInteracao Totalizacao
		{
			get
			{
				return GetProperty(() => Totalizacao);
			}
			set
			{
				SetProperty(() => Totalizacao, value);
			}
		}

		public ICommand SpaceCommand { get; set; }

		public bool SelecionarTodos
		{
			get
			{
				return GetProperty(() => SelecionarTodos);
			}
			set
			{
				SetProperty(() => SelecionarTodos, value, () =>
				{
					OnSelecionarTodos(value);
				});
			}
		}

		public ItemInteracaoListaRecebimento()
		{
		}

		public ItemInteracaoListaRecebimento(string descricao, Lista<Recebimento> valor, IItemInteracao origemDaBusca, IItemInteracao totalizacao)
			: base(descricao, valor)
		{
			OrigemDaBusca = origemDaBusca;
			Totalizacao = totalizacao;
			SpaceCommand = new DelegateCommand(Selecionar);
			MaxHeight = System.Windows.Application.Current.MainWindow.ActualHeight - 498.0;
		}

		public ItemInteracaoListaRecebimento ComOrigemDaBusca(IItemInteracao origemDaBusca)
		{
			OrigemDaBusca = origemDaBusca;
			return this;
		}

		public ItemInteracaoListaRecebimento ComTotalizacao(IItemInteracao totalizacao)
		{
			Totalizacao = totalizacao;
			return this;
		}

		private void OnSelecionarTodos(bool value)
		{
			foreach (Recebimento iten in Valor.Itens)
			{
				iten.Selecionar(value);
			}
		}

		public void Selecionar()
		{
			if (Valor.ItemSelecionado.IsNotNull())
			{
				Valor.ItemSelecionado.Selecionar(!Valor.ItemSelecionado.Selecionado);
			}
		}

		public override void Limpar()
		{
			Valor?.Limpar();
		}

		public override ItemInteracaoListaRecebimento Build()
		{
			return new ItemInteracaoListaRecebimento(Descricao, Valor, OrigemDaBusca, Totalizacao);
		}
	}
