namespace Otus.Modulo.PontoDeVendas.Services
{
	public class BackupPontoDeVendaService : IBackupPontoDeVendaService
	{
		internal class BackupPontoDeVenda : BackupSistema
		{
			private string _nomeMaquina => Environment.MachineName.RemoveDiacritics();

			protected override string DiretorioArquivos => Path.Combine(Path.GetDirectoryName(Process.GetCurrentProcess().MainModule.FileName), "Fiscal");

			protected override string NomeSubdiretorioBackupArquivos => Path.Combine(_nomeMaquina, "Fiscal");

			protected override string NomeSubdiretorioBackupDados => Path.Combine(_nomeMaquina, "Dados");

			protected override string NomeBaseDados => Util<string>.GetDefaultMongoDbDatabaseName();

			protected override string SenhaBaseDados => DatabaseUtil.DefaultPass;

			protected override bool CopiarArquivosAntesGerarBackup => true;

			protected override Action<Task<IEnumerable<string>>> AcaoAposGerarBackupAutomatico => (Task<IEnumerable<string>> task) =>
			{
			};

			private BackupPontoDeVenda(ConfiguracaoBackup configuracaoBackup)
				: base(configuracaoBackup)
			{
			}

			public static BackupPontoDeVenda Criar()
			{
				return new BackupPontoDeVenda(new ConfiguracaoBackup(new List<string> { DadosSistema.DiretorioBackup() }));
			}

			public void GerarBackupArquivosConfiguracao()
			{
				try
				{
					string[] files = Directory.GetFiles(Path.GetDirectoryName(Process.GetCurrentProcess().MainModule.FileName), "Configuracao*.xml");
					foreach (string obj in files)
					{
						string destFileName = Path.Combine(path3: new FileInfo(obj).Name, path1: DadosSistema.DiretorioBackup(), path2: NomeSubdiretorioBackupDados);
						File.Copy(obj, destFileName, overwrite: true);
					}
				}
				catch (Exception)
				{
				}
			}
		}

		private bool _gerandoBackup;

		public void GerarBackup()
		{
			if (_gerandoBackup)
			{
				return;
			}
			Task.Factory.StartNew(() =>
			{
				_gerandoBackup = true;
				BackupPontoDeVenda backupPontoDeVenda = BackupPontoDeVenda.Criar();
				backupPontoDeVenda.GerarBackup();
				backupPontoDeVenda.GerarBackupArquivosConfiguracao();
				backupPontoDeVenda.Dispose();
			}).ContinueWith((Task task) =>
			{
				_gerandoBackup = false;
				if (task.IsFaulted)
				{
					task.Exception.ShowLastException("Falha ao gerar backup.");
				}
			});
		}
	}
