		public void ImprimirValoresCliente(MovimentacaoDto movimentacao)
		{
			try
			{
				if ((!DadosSistema.ConfiguracaoDto.Saida.ImprimirSaldoDevedorAposVenda.Valor || !DadosSistema.ConfiguracaoDto.Saida.ImprimirCashbackDisponivelAposVenda.Valor) && movimentacao.Pessoa.ConsumidorReservadoSistema)
				{
					return;
				}
				bool valor = DadosSistema.ConfiguracaoDto.Saida.ImprimirSaldoDevedorAposVenda.Valor;
				bool valor2 = DadosSistema.ConfiguracaoDto.Saida.ImprimirCashbackDisponivelAposVenda.Valor;
				decimal num = (valor ? Service.Canal((IRecebimentoModuleService service) => service.ObterSaldoDevedor(movimentacao.Pessoa.Id)) : 0m);
				decimal num2 = (valor2 ? Service.Canal((IPessoaModuleService service) => service.ObterItensCreditoDebitoCashback(movimentacao.Pessoa.Id)).Sum((ItemCreditoDebitoCashbackDto item) => item.Valor) : 0m);
				if (!(num <= 0m) || !(num2 <= 0m))
				{
					IRelatorio relatorio2;
					if (DadosSistema.TamanhoBobina != TamanhoBobina.CinquentaESeisCinquentaESeteCinquentaEOitoMilimetros)
					{
						IRelatorio relatorio = new RelatorioValoresCliente79Mm80Mm(movimentacao.Pessoa, num, num2, DadosSistema.MargemEsquerdaImpressoraNaoFiscal, DadosSistema.RollPaper, valor, valor2);
						relatorio2 = relatorio;
					}
					else
					{
						IRelatorio relatorio = new RelatorioValoresCliente56Mm57Mm58Mm(movimentacao.Pessoa, num, num2, DadosSistema.MargemEsquerdaImpressoraNaoFiscal, DadosSistema.RollPaper, valor, valor2);
						relatorio2 = relatorio;
					}
					IRelatorio relatorio3 = relatorio2;
					ImpressoraNaoFiscalService.Imprimir(relatorio3);
				}
			}
			catch (Exception ex)
			{
				ex.ShowLastException();
			}
		}

