		protected DigisatServer.Domain.Main.Aggregates.MovimentacoesAgg.Saidas.CupomFiscalEletronico Cancelar(CFeCancDto cfeCancelado, string usuarioAutorizouCancelamento)
		{
			DigisatServer.Domain.Main.Aggregates.MovimentacoesAgg.Saidas.CupomFiscalEletronico cupomFiscalEletronico = ObterCupomFiscalEletronicoParaCancelar(cfeCancelado.ChaveAcessoCfeCancelado);
			cupomFiscalEletronico.SetarSituacaoCancelado(SessaoService.Sessao.NomeUsuario, new Autorizacao(new PermitirCancelarDocumentoFiscal(), usuarioAutorizouCancelamento, DateTime.Now), cfeCancelado.XmlTexto);
			MovimentacaoRepositoryWrite.Update(cupomFiscalEletronico);
			decimal num = cupomFiscalEletronico.Pagamentos?.Where((ItemPagamento x) => x.EspeciePagamento.Codigo == 1).Sum((ItemPagamento x) => x.Valor) ?? 0m;
			if (num > 0m)
			{
				new ValorSangriaService(_valorSangriaRepositoryWrite, _valorSangriaRepositoryRead).AlterarValor(num, aumentar: false);
			}
			if (DadosSistema.IsFarmacia && !cupomFiscalEletronico.NumeroAutorizacaoPortalDrograria.IsNullOrEmpty())
			{
				_farmaciaService.AnularVendaPortalDrogaria(cupomFiscalEletronico.OperadoraPortalDrogaria, cupomFiscalEletronico.NumeroAutorizacaoPortalDrograria, 1);
			}
			IEnumerable<ItemPagamento> pagamentos = cupomFiscalEletronico.Pagamentos;
			if (pagamentos != null && pagamentos.OfType<ItemPagamentoCarteiraDigital>().Any())
			{
				EstornarPagamentosDigitais(cupomFiscalEletronico.Pagamentos?.OfType<ItemPagamentoCarteiraDigital>().SelectMany((ItemPagamentoCarteiraDigital pagamentoCarteiraDigital) => pagamentoCarteiraDigital.InformacoesTransacao.Select((InformacaoTransacaoCarteiraDigital transacaoCarteiraDigital) => transacaoCarteiraDigital.Nsu)));
			}
			IEnumerable<ItemPagamento> pagamentos2 = cupomFiscalEletronico.Pagamentos;
			if (pagamentos2 != null && pagamentos2.OfType<ItemPagamentoCartao>().Any())
			{
				CancelarTransacaoTef(new List<InformacaoTransacao>(cupomFiscalEletronico.Pagamentos?.OfType<ItemPagamentoCartao>().Where((ItemPagamentoCartao x) => x.InformacoesTransacao.Any() && x.EspeciePagamento.Codigo != 27 && !x.InformacoesTransacao.All((InformacaoTransacaoTef y) => y.CodigoAutorizacaoTransacao.IsNullOrEmpty())).SelectMany((ItemPagamentoCartao x) => x.InformacoesTransacao.Select((InformacaoTransacaoTef y) => new InformacaoTransacao(y.Rede, y.Nsu, y.Valor)))));
			}
			IEnumerable<ItemPagamento> pagamentos3 = cupomFiscalEletronico.Pagamentos;
			if (pagamentos3 != null && pagamentos3.OfType<ItemPagamentoCarteiraDigital>().Any())
			{
				CancelarTransacaoTef(new List<InformacaoTransacao>(cupomFiscalEletronico.Pagamentos?.OfType<ItemPagamentoCarteiraDigital>().Where((ItemPagamentoCarteiraDigital x) => x.InformacoesTransacao.Any() && x.EspeciePagamento.Codigo != 27 && x.InformacoesTransacao.Any((InformacaoTransacaoCarteiraDigital y) => y.CodigoAutorizacaoTransacao != 0) && x.InformacoesTransacao.Any((InformacaoTransacaoCarteiraDigital y) => y.IsNsuValidoCancelamentoShipay)).SelectMany((ItemPagamentoCarteiraDigital x) => x.InformacoesTransacao.Select((InformacaoTransacaoCarteiraDigital y) => new InformacaoTransacao(y.Rede, y.Nsu, y.Valor)))));
			}
			return cupomFiscalEletronico;
		}

		private DigisatServer.Domain.Main.Aggregates.MovimentacoesAgg.Saidas.CupomFiscalEletronico ObterCupomFiscalEletronicoParaCancelar(string chaveAcesso)
		{
			DigisatServer.Domain.Main.Aggregates.MovimentacoesAgg.Saidas.CupomFiscalEletronico cupomFiscalEletronico = MovimentacaoRepositoryRead.FindOne(MovimentacaoSpecification.PorTipo<DigisatServer.Domain.Main.Aggregates.MovimentacoesAgg.Saidas.CupomFiscalEletronico>().PorChaveAcesso(chaveAcesso)) as DigisatServer.Domain.Main.Aggregates.MovimentacoesAgg.Saidas.CupomFiscalEletronico;
			if (cupomFiscalEletronico.IsNotNull())
			{
				return cupomFiscalEletronico;
			}
			return BsonSerializer.Deserialize<DigisatServer.Domain.Main.Aggregates.MovimentacoesAgg.Saidas.CupomFiscalEletronico>(Service.Canal((IMovimentacaoSaidaModuleService x) => x.ObterCupomFiscalEletronicoChaveAcessoJson(chaveAcesso)).Result);
		}

		protected async Task EnviarEmailCupomFiscalEletronico(CFeDto cFeDto)
		{
			if (!DadosSistema.ConfiguracaoDto.Saida.EnviarEmailPdv.Valor)
			{
				return;
			}
			try
			{
				string text = $"{cFeDto.ChaveAcesso.ExtrairChaveDfe()}-CFe.xml";
				string text2 = $"Extrato CFe {cFeDto.NumeroExtrato,8:D8}.pdf";
				GeradorArquivos geradorArquivos = new GeradorArquivos(DadosSistema.EmpresaLogada.CpfCnpj);
				string text3 = Path.Combine(geradorArquivos.ObterPastaImpressosXmlAnoMes(TipoDocumento.CFe, geradorArquivos.ObterAnoMesPorChaveAcesso(cFeDto.ChaveAcesso.ExtrairChaveDfe())), text);
				string text4 = Path.Combine(geradorArquivos.ObterPastaImpressosPdfAnoMes(TipoDocumento.CFe, geradorArquivos.ObterAnoMesPorChaveAcesso(cFeDto.ChaveAcesso.ExtrairChaveDfe())), text2);
				IRelatorio relatorio = ((DadosSistema.TamanhoBobina != TamanhoBobina.CinquentaESeisCinquentaESeteCinquentaEOitoMilimetros) ? ((IRelatorio)ExtratoCfeSatAutorizado79Mm80Mm.Criar().ComCFe(cFeDto).ComMargemEsquerda(DadosSistema.MargemEsquerdaImpressoraNaoFiscal)
					.ComRollPaper(DadosSistema.RollPaper)
					.ComEmpresaSimplesNacional(DadosSistema.EmpresaLogada.RegimeTributario.IsNot<RegimeNormal>())
					.ComEmpresaLogadaImagemComprimida(DadosSistema.EmpresaLogada.Imagem)
					.ComCodigoIbgeUf(DadosSistema.EmpresaLogada.Municipio?.Uf?.CodigoIbge ?? 35)
					.Build()) : ((IRelatorio)ExtratoCfeSatAutorizado56Mm57Mm58Mm.Criar().ComCFe(cFeDto).ComMargemEsquerda(DadosSistema.MargemEsquerdaImpressoraNaoFiscal)
					.ComRollPaper(DadosSistema.RollPaper)
					.ComEmpresaSimplesNacional(DadosSistema.EmpresaLogada.RegimeTributario.IsNot<RegimeNormal>())
					.ComEmpresaLogadaImagemComprimida(DadosSistema.EmpresaLogada.Imagem)
					.ComCodigoIbgeUf(DadosSistema.EmpresaLogada.Municipio?.Uf?.CodigoIbge ?? 35)
					.Build()));
				HelperXml.CriarArquivoXml(cFeDto.XmlTexto, text3);
				if (DadosSistema.ConfiguracaoDto.Geral.ProtegerPdfExportadoComSenha.Valor && cFeDto.DocumentoCliente.RemoveCaracteresAlfanumerico().Length >= 6)
				{
					XtraReport xtraReport = relatorio.Processar();
					PdfExportOptions pdfExportOptions = new PdfExportOptions();
					pdfExportOptions.PasswordSecurityOptions.OpenPassword = cFeDto.DocumentoCliente.RemoveCaracteresAlfanumerico().CopiarTexto(6);
					xtraReport.ExportToPdf(text4, pdfExportOptions);
				}
				else
				{
					relatorio.Processar().ExportToPdf(text4);
				}
				List<AnexoEmail> anexos = new List<AnexoEmail>
				{
					new AnexoEmail(text4, text2),
					new AnexoEmail(text3, text)
				};
				ConfiguracaoEmailDto configuracaoEmail = await Service.Canal((IConfiguracaoModuleService x) => x.ObterConfiguracaoEmailSatAsync());
				ProcessarCorpoEmailDocumentoFiscalEletronico(configuracaoEmail, cFeDto);
				await EnviarEmail(configuracaoEmail, anexos, cFeDto);
			}
			catch (Exception ex)
			{
				DialogoFactory.MostrarDialogoConfirma(ex.Message);
			}
		}

		protected void ProcessarCorpoEmailDocumentoFiscalEletronico(ConfiguracaoEmailDto configuracaoEmail, CFeDto cFeDto)
		{
			configuracaoEmail.ModeloEmail.Corpo = configuracaoEmail.ModeloEmail.Corpo.Replace(TagEmailModeloDocumentoFiscalEletronico.NomePessoa.RetornarDescricao(), cFeDto.NomeCliente).Replace(TagEmailModeloDocumentoFiscalEletronico.NumeroDocumentoFiscal.RetornarDescricao(), cFeDto.NumeroExtrato.ToStringLeftZero(9)).Replace(TagEmailModeloDocumentoFiscalEletronico.DataEmissao.RetornarDescricao(), cFeDto.DataEmissao.FormatarData())
				.Replace(TagEmailModeloDocumentoFiscalEletronico.Serie.RetornarDescricao(), cFeDto.NumeroSerie)
				.Replace(TagEmailModeloDocumentoFiscalEletronico.Total.RetornarDescricao(), cFeDto.Total.FormatarCampoValor(2));
		}

		public async Task EnviarEmail(ConfiguracaoEmailDto configuracaoEmail, IEnumerable<AnexoEmail> caminho, CFeDto cFeDto)
		{
			try
			{
				LoaderProcessoService.MostrarLoader("Enviando e-mail...");
				string emailCliente = EmailCliente;
				EmailServiceFactory.SetCurrent(ObterEnvioEmailService(caminho, configuracaoEmail, emailCliente, cFeDto));
				ServiceEmail = EmailServiceFactory.Create();
				await ServiceEmail.Enviar();
				ThreadPrincipal.Executar(() =>
				{
					Notificacao.MostrarNotificacao($"E-mail enviado para {_emailDestinatario}");
				});
			}
			catch (Exception ex)
			{
				DialogoFactory.MostrarDialogoConfirma(ex.Message);
			}
			finally
			{
				LoaderProcessoService.EsconderLoader();
				ServiceEmail?.Dispose();
				EmailCliente = null;
			}
		}

		protected EnvioEmailServiceFactory ObterEnvioEmailService(IEnumerable<AnexoEmail> anexos, ConfiguracaoEmailDto configuracaoEmail, string emailDestinatario, CFeDto cFeDto)
		{
			if (configuracaoEmail.ModeloEmail.Is<EmailModeloDtoNull>())
			{
				throw new Exception("Verifique as configurações de modelo de e-mail!");
			}
			string email = (configuracaoEmail.EnviarCopiaRemetente ? configuracaoEmail.UsuarioEmail : string.Empty);
			DigisatServer.Infrastructure.Crosscutting.Mvvm.Email email2 = new DigisatServer.Infrastructure.Crosscutting.Mvvm.Email().ComAssunto(configuracaoEmail.ModeloEmail.Assunto).ComCorpo(configuracaoEmail.ModeloEmail.Corpo).ComEmailResposta(configuracaoEmail.ModeloEmail.EmailParaResposta)
				.ComEmailDestinatario(emailDestinatario)
				.ComAnexos(new Lista<AnexoEmail>(anexos));
			if (!configuracaoEmail.EnviarEmailAutomaticamente || emailDestinatario.IsEmpty())
			{
				if (DialogoFactory.MostrarDialogoEmail(ref emailDestinatario, email2, new EnviarEmail()) != MessageBoxResult.OK)
				{
					throw new Exception("O e-mail não será enviado.");
				}
				if (email2.EmailDestinatario.IsNullOrEmpty())
				{
					throw new Exception("O e-mail não será enviado. Destinatário não informado.");
				}
			}
			EnvioEmailServiceFactory envioEmailServiceFactory = new EnvioEmailServiceFactory().SetarServidorSmtp(configuracaoEmail.ServidorSmtp).SetarAssunto(email2.Assunto).SetarEmailCopiaOculta(email, DadosSistema.EmpresaLogada.Nome)
				.SetarEmailRemetenteParaResposta(email2.EmailResposta, DadosSistema.EmpresaLogada.Nome)
				.SetarEmailRemetente(configuracaoEmail.UsuarioEmail, DadosSistema.EmpresaLogada.Nome)
				.AdicionarDestinatarios(email2.EmailDestinatario, email2.EmailDestinatario)
				.SetarMensagem(email2.Corpo)
				.SetarPorta(configuracaoEmail.PortaEmail)
				.SetarSenha(configuracaoEmail.SenhaEmail)
				.SetarUsaSsl(configuracaoEmail.UsaSsl)
				.SetarIgnorarCertificadoInvalido(configuracaoEmail.IgnorarCertificadoInvalido);
			foreach (AnexoEmail item in email2.Anexos.Itens.Where((AnexoEmail x) => x.IsNotNull()))
			{
				envioEmailServiceFactory.AdicionarAnexo(item.CaminhoArquivo, item.NomeArquivo);
			}
			_emailDestinatario = email2.EmailDestinatario;
			return envioEmailServiceFactory;
		}

		public override void Abrir()
		{
			if (CfeDto == null)
			{
				CfeDto = new CFeDto
				{
					NumeroCaixa = ObterNumeroCaixa(),
					AssinaturaAplicativoComercial = Empresa.PontoDeVenda.AssinaturaAplicativoComercial,
					CnpjEmitente = Empresa.CpfCnpj,
					IeEmitente = Empresa.Ie,
					ImEmitente = Empresa.Im
				};
			}
		}

		protected abstract int ObterNumeroCaixa();

		protected void Abrir(ConsumidorLocal consumidor)
		{
			CfeDto = new CFeDto
			{
				NumeroCaixa = ObterNumeroCaixa(),
				AssinaturaAplicativoComercial = Empresa.PontoDeVenda.AssinaturaAplicativoComercial,
				CnpjEmitente = Empresa.CpfCnpj,
				IeEmitente = Empresa.Ie,
				ImEmitente = Empresa.Im,
				DocumentoCliente = consumidor.Documento,
				NomeCliente = consumidor.Nome,
				LogradouroEntrega = consumidor.Pessoa.Carteira?.EnderecoEntregaPrincipal.Logradouro,
				NumeroEntrega = consumidor.Pessoa.Carteira?.EnderecoEntregaPrincipal.Numero,
				BairroEntrega = consumidor.Pessoa.Carteira?.EnderecoEntregaPrincipal.Bairro,
				ComplementoEntrega = consumidor.Pessoa.Carteira?.EnderecoEntregaPrincipal.Complemento,
				MunicipioEntrega = consumidor.Pessoa.Carteira?.EnderecoEntregaPrincipal.To<EnderecoNacional>().Municipio.Nome,
				UfEntrega = consumidor.Pessoa.Carteira?.EnderecoEntregaPrincipal.To<EnderecoNacional>().Municipio.Uf.Sigla
			};
		}

		public override void Vender(Otus.Modulo.PontoDeVendas.ViewModels.ItemDocumentoFiscal item)
		{
			if (CfeDto.IsNull())
			{
				Abrir();
			}
			CfeDto.Produtos.Add(item.ProjectedAsDto());
		}

		public override void AplicarDesconto(Otus.Modulo.PontoDeVendas.ViewModels.ItemDocumentoFiscal itemDocumentoFiscal, decimal valor)
		{
			DetDto detDto = CfeDto.Produtos.FirstOrDefault((DetDto x) => x.NumeroItem == itemDocumentoFiscal.NumeroItem);
			if (detDto != null)
			{
				CfeDto.Produtos.Remove(detDto);
				itemDocumentoFiscal.ComDesconto(valor.ArredondarParaDuasCasasDecimais());
				CfeDto.Produtos.Add(itemDocumentoFiscal.ProjectedAsDto());
			}
		}

		public override void AplicarAcrescimo(Otus.Modulo.PontoDeVendas.ViewModels.ItemDocumentoFiscal itemDocumentoFiscal, decimal valor)
		{
			DetDto detDto = CfeDto.Produtos.FirstOrDefault((DetDto x) => x.NumeroItem == itemDocumentoFiscal.NumeroItem);
			if (detDto != null)
			{
				CfeDto.Produtos.Remove(detDto);
				itemDocumentoFiscal.ComAcrescimo(valor.ArredondarParaDuasCasasDecimais());
				CfeDto.Produtos.Add(itemDocumentoFiscal.ProjectedAsDto());
			}
		}

		public override void AlterarPrecoUnitario(Otus.Modulo.PontoDeVendas.ViewModels.ItemDocumentoFiscal itemDocumentoFiscal, decimal valor)
		{
			DetDto detDto = CfeDto.Produtos.FirstOrDefault((DetDto x) => x.NumeroItem == itemDocumentoFiscal.NumeroItem);
			if (detDto != null)
			{
				CfeDto.Produtos.Remove(detDto);
				itemDocumentoFiscal.ComPrecoUnitario(valor);
				CfeDto.Produtos.Add(itemDocumentoFiscal.ProjectedAsDto());
			}
		}

		public override void Totalizar(AcrescimoDesconto acrescimoDesconto)
		{
			if (acrescimoDesconto != null)
			{
				if (acrescimoDesconto.Is<Otus.Modulo.PontoDeVendas.ViewModels.Acrescimo>())
				{
					CfeDto.AcrescimoSubtotal = acrescimoDesconto.Valor;
				}
				if (acrescimoDesconto.Is<Otus.Modulo.PontoDeVendas.ViewModels.Desconto>())
				{
					CfeDto.DescontoSubtotal = acrescimoDesconto.Valor;
				}
			}
		}

		public override void EfetuarPagamento(ItemPagamentoViewModel item)
		{
			CfeDto.Pagamentos.AddRange(item.ProjectedAsDto());
		}

		public override void Finalizar(IEnumerable<IMensagemPromocional> mensagemPromocional)
		{
			CfeDto.InformacaoAdicional = mensagemPromocional.ProjectedAsDto();
			CfeDto.ReNumerarItens();
		}

		public override void Cancelar(IEstadoDocumentoFiscal estadoDocumentoFiscal, Autorizacao autorizacao)
		{
			CfeDto = null;
			if (!estadoDocumentoFiscal.Is<DocumentoFiscalFechado>())
			{
				OnDocumentoFiscalCanceladoEvent();
				return;
			}
			if (UltimoCfeDto == null)
			{
				throw new Exception("Documento inválido. Faça o cancelamento através da opção 'F9 - Abrir CFe'");
			}
			CancelarVenda(UltimoCfeDto.ChaveAcesso, autorizacao);
		}

		protected virtual void CancelarVenda(string chaveAcesso, Autorizacao autorizacao)
		{
			OnDocumentoFiscalCanceladoEvent(chaveAcesso);
		}

		public void CancelarCupomFiscalEletronico(string movimentacaoChaveAcesso)
		{
			AutorizacaoDto autorizacaoDto = SessaoService.VerificarPermissao<DigisatServer.Infrastructure.Crosscutting.Module.PontoDeVenda, PermitirCancelarDocumentoFiscal>();
			if (autorizacaoDto != null)
			{
				CancelarVenda(movimentacaoChaveAcesso, autorizacaoDto.Morfar());
			}
		}

		protected CFeCancDto ObterCFeCancDto(string chaveAcesso)
		{
			return new CFeCancDto
			{
				NumeroCaixa = ObterNumeroCaixa(),
				AssinaturaAplicativoComercial = Empresa.PontoDeVenda.AssinaturaAplicativoComercial,
				CnpjEmitente = Empresa.CpfCnpj,
				IeEmitente = Empresa.Ie,
				ImEmitente = Empresa.Im,
				ChaveAcesso = chaveAcesso
			};
		}

		public void ImprimirCupomFiscalEletronico(CFeBaseDto dto)
		{
			CFeDto cFeDto = dto as CFeDto;
			if (cFeDto.IsNotNull())
			{
				Imprimir(cFeDto);
			}
			CFeCancDto cFeCancDto = dto as CFeCancDto;
			if (cFeCancDto.IsNotNull())
			{
				Imprimir(cFeCancDto);
			}
		}

		public override void IdentificarConsumidor(ConsumidorLocal consumidor)
		{
			if (consumidor == null)
			{
				if (CfeDto != null)
				{
					CfeDto.DocumentoCliente = null;
					CfeDto.NomeCliente = null;
				}
				return;
			}
			if (CfeDto == null)
			{
				Abrir(consumidor);
				return;
			}
			CfeDto.DocumentoCliente = consumidor.Documento;
			CfeDto.NomeCliente = consumidor.Nome;
			EmailCliente = consumidor.Pessoa?.Carteira?.EmailPrincipal?.Endereco;
			CfeDto.LogradouroEntrega = consumidor.Pessoa?.Carteira?.EnderecoEntregaPrincipal.Logradouro;
			CfeDto.NumeroEntrega = consumidor.Pessoa?.Carteira?.EnderecoEntregaPrincipal.Numero;
			CfeDto.BairroEntrega = consumidor.Pessoa?.Carteira?.EnderecoEntregaPrincipal.Bairro;
			CfeDto.ComplementoEntrega = consumidor.Pessoa?.Carteira?.EnderecoEntregaPrincipal.Complemento;
			CfeDto.MunicipioEntrega = consumidor.Pessoa?.Carteira?.EnderecoEntregaPrincipal.To<EnderecoNacional>().Municipio.Nome;
			CfeDto.UfEntrega = consumidor.Pessoa?.Carteira?.EnderecoEntregaPrincipal.To<EnderecoNacional>().Municipio.Uf.Sigla;
		}

		protected override void OnErroAoTransmitirDocumentoFiscalEvent(string mensagem)
		{
			base.OnErroAoTransmitirDocumentoFiscalEvent(mensagem);
			CfeDto.Pagamentos.Clear();
		}

		protected override void OnFalhaAoTransmitirDocumentoFiscalEvent(FalhaAoTransmitirDocumentoFiscalEventArgs eventArgs)
		{
			base.OnFalhaAoTransmitirDocumentoFiscalEvent(eventArgs);
			CfeDto.Pagamentos.Clear();
		}

		public override void CancelarItem(int numeroItem)
		{
			DetDto item = CfeDto.Produtos.FirstOrDefault((DetDto x) => x.NumeroItem == numeroItem);
			CfeDto.Produtos.Remove(item);
		}

		public override void VerificarEstado()
		{
			OnEmissorProntoEvent();
		}

		public override string RetornarNumeroFabricacao()
		{
			return UltimoCfeDto?.NumeroSerie ?? string.Empty;
		}

		public override string RetornarChaveAcesso()
		{
			return UltimoCfeDto?.ChaveAcesso ?? string.Empty;
		}

		public string RetornarXmlAutorizadoTexto()
		{
			return UltimoCfeDto?.XmlTexto ?? string.Empty;
		}

		public override long RetornarNumeroDocumento()
		{
			return UltimoCfeDto?.NumeroExtrato ?? 0;
		}

		public override DateTime RetornarDataEmissao()
		{
			return DateTime.Now;
		}

		public CFeDto ObterCFeDto()
		{
			return CfeDto;
		}

		public void SetarCFeDto(CFeDto cFeDto)
		{
			if (CfeDto.IsNull())
			{
				CfeDto = cFeDto;
			}
		}

		public void FinalizarDocumentoFiscal()
		{
			CfeDto = null;
		}
	}
	public class DisplayService : IDisplayService
	{
		private readonly IConfiguracaoClientService _configuracaoClientService;

		private readonly BackgroundWorker _backgroundWorkerInicializacao = new BackgroundWorker();

		private DigisatServer.Infrastructure.Crosscutting.Display.Interfaces.IDisplayFactory _display;

		public const string NomeImagem = "Pix4.jpg";

		public bool DisplayInicializado { get; set; }

		public DisplayService(IConfiguracaoClientService configuracaoClientService)
		{
			_configuracaoClientService = configuracaoClientService;
			Inicializar();
		}

		private void Inicializar()
		{
			if (_display != null)
			{
				_backgroundWorkerInicializacao.DoWork -= BkwOnDoWork;
				_backgroundWorkerInicializacao.RunWorkerCompleted -= BkwOnRunWorkerCompleted;
			}
			_backgroundWorkerInicializacao.DoWork += BkwOnDoWork;
			_backgroundWorkerInicializacao.RunWorkerCompleted += BkwOnRunWorkerCompleted;
			if (!_backgroundWorkerInicializacao.IsBusy)
			{
				_backgroundWorkerInicializacao.RunWorkerAsync();
			}
		}

		private void BkwOnDoWork(object sender, DoWorkEventArgs doWorkEventArgs)
		{
			InstanciarDisplay();
			if (_display.IsNotNull())
			{
				Iniciar();
			}
		}

		private void InstanciarDisplay()
		{
			ConfiguracaoClient configuracaoClient = _configuracaoClientService.ObterConfiguracao();
			if (configuracaoClient.Display != null && !(configuracaoClient.Display.Marca == MarcaDisplay.Indefinida.RetornarDescricao()))
			{
				_display = RetornarDisplayPelaMarcaEModelo(HelperEnum.RetornarValorPelaDescription<MarcaDisplay>(configuracaoClient.Display.Marca), HelperEnum.RetornarValorPelaDescription<ModeloDisplay>(configuracaoClient.Display.Modelo));
				DisplayInicializado = true;
			}
		}

		private DigisatServer.Infrastructure.Crosscutting.Display.Interfaces.IDisplayFactory RetornarDisplayPelaMarcaEModelo(MarcaDisplay marca, ModeloDisplay modelo)
		{
			DigisatServer.Infrastructure.Crosscutting.Display.Interfaces.IDisplayFactory displayFactory = null;
			if (marca == MarcaDisplay.Elgin)
			{
				displayFactory = new DisplayFactory<DigisatServer.Infrastructure.Crosscutting.Display.Classes.Elgin.Elgin>(modelo);
			}
			if (displayFactory == null)
			{
				return null;
			}
			displayFactory.Porta = _configuracaoClientService.ObterConfiguracao().Display.Porta;
			return displayFactory;
		}

		private void Iniciar()
		{
			try
			{
				if (!DisplayInicializado)
				{
					return;
				}
				_display.DesconectarDisplay();
			}
			catch (Exception)
			{
			}
			ThreadPrincipal.Executar(() =>
			{
				int num = 0;
				while (num <= 5)
				{
					try
					{
						_display.AbreConexaoDisplay();
					}
					catch (Exception)
					{
						try
						{
							num++;
							SerialPort serialPort = new SerialPort(_display.Porta);
							serialPort.BaudRate = 9600;
							serialPort.Parity = Parity.None;
							serialPort.StopBits = StopBits.One;
							serialPort.DataBits = 8;
							serialPort.ReadTimeout = 2000;
							serialPort.Handshake = Handshake.None;
							serialPort.Dispose();
							serialPort.Close();
							Thread.Sleep(500);
							serialPort.Open();
							Thread.Sleep(500);
						}
						catch (Exception)
						{
						}
						continue;
					}
					break;
				}
				if (num == 6)
				{
					_display.ReinicializaDisplay();
				}
				CarregarImagemPadrao();
			});
		}

		public void CarregarImagemPadrao()
		{
			if (!DisplayInicializado)
			{
				return;
			}
			int num = 0;
			while (num <= 5)
			{
				try
				{
					string caminhoArquivo = Path.Combine(AppDomain.CurrentDomain.BaseDirectory, "Images", "Pix4.jpg");
					_display.CarregaImagemDisplay("Pix4.jpg", caminhoArquivo, 320, 480);
					ApresentarImagemPadrao();
					break;
				}
				catch (Exception)
				{
					try
					{
						num++;
						Thread.Sleep(500);
					}
					catch (Exception)
					{
					}
				}
			}
		}

		public void ApresentarImagemPadrao()
		{
			if (DisplayInicializado)
			{
				_display.ApresentaImagemDisplay("Pix4.jpg", 0, 0, 0);
			}
		}

		private void BkwOnRunWorkerCompleted(object sender, RunWorkerCompletedEventArgs runWorkerCompletedEventArgs)
		{
			LoaderProcessoService.EsconderLoader();
			Exception error = runWorkerCompletedEventArgs.Error;
			if (error != null)
			{
				if (error is EcfGrandeTotalInvalidoException || error is EcfNumeroFabricacaoInvalidoException)
				{
					error.ShowLastException();
				}
				if (!(error is SemConfiguracaoEcfException) && error.ShowLastException("Deseja tentar novamente?", yesNo: true))
				{
					Inicializar();
				}
			}
			else
			{
				_backgroundWorkerInicializacao.DoWork -= BkwOnDoWork;
				_backgroundWorkerInicializacao.RunWorkerCompleted -= BkwOnRunWorkerCompleted;
			}
		}

		public void InicializaDisplay()
		{
			if (!DisplayInicializado)
			{
				return;
			}
			try
			{
				_display.InicializaDisplay();
			}
			catch (Exception)
			{
			}
		}

		public void ReinicializaDisplay()
		{
			if (!DisplayInicializado)
			{
				return;
			}
			try
			{
				_display.ReinicializaDisplay();
			}
			catch (Exception)
			{
			}
		}

		public void ApresentaQrCode(string qrCode, int tamanho, int posHorizoltal, int posVertical)
		{
			if (!DisplayInicializado)
			{
				return;
			}
