			_produtoServicoEmpresaRepositoryRead = produtoServicoEmpresaRepositoryRead;
			_preDocumentoFiscalRepositoryRead = preDocumentoFiscalRepositoryRead;
			_promocaoScanntechRepositoryRead = promocaoScanntechRepositoryRead;
			_valorSangriaRepositoryWrite = valorSangriaRepositoryWrite;
			_valorSangriaRepositoryRead = valorSangriaRepositoryRead;
			CryptoFactory.SetCurrent(new AESCryptoFactory());
			_aesCrypto = CryptoFactory.Create();
			eventPublisher.GetEvent<DocumentoFiscalDesbloqueado>().Subscribe((DocumentoFiscalDesbloqueado args) =>
			{
				if (Carregado)
				{
					VerificarEcf();
				}
			});
			eventPublisher.GetEvent((Tef tef) =>
			{
				_subscriptions?.Dispose();
				_subscriptions = new CompositeDisposable
				{
					tef.WhenInfoEcfEvent.Subscribe((TefInfoEcfEventArgs args) =>
					{
						if (args.InfoEcf == TefTipo.InfoEcf.EstadoEcf)
						{
							switch (_ecf.VerificarDocumentoAberto())
							{
							case EcfTipo.Documento.Nenhum:
								args.Retorno = "L";
								break;
							case EcfTipo.Documento.RelatorioGerencial:
								args.Retorno = "G";
								break;
							case EcfTipo.Documento.ComprovanteCreditoDebito:
								args.Retorno = "C";
								break;
							case EcfTipo.Documento.CupomFiscal:
								switch (_ecf.VerificarEstadoDocumentoAberto())
								{
								case EcfTipo.EstadoDocumento.Aberto:
								case EcfTipo.EstadoDocumento.RegistroDeItem:
									args.Retorno = "V";
									break;
								case EcfTipo.EstadoDocumento.Pagamento:
									args.Retorno = "P";
									break;
								case EcfTipo.EstadoDocumento.Fechado:
									args.Retorno = "L";
									break;
								default:
									args.Retorno = "O";
									break;
								}
								break;
							default:
								args.Retorno = "O";
								break;
							}
						}
					}),
					tef.WhenComandarEcfAbrirVinculadoEvent.Subscribe((TefComandarEcfAbrirVinculadoEventArgs args) =>
					{
						try
						{
							AbrirComprovanteCreditoDebito(args.Valor, args.IndiceEspeciePagamentoEcf);
							args.Resultado = 1;
						}
						catch (Exception)
						{
							args.Resultado = 0;
						}
					}),
					tef.WhenComandarEcfImprimirViaEvent.Subscribe((TefComandarEcfImprimirViaEventArgs args) =>
					{
						try
						{
							switch (args.Tipo)
							{
							case TefTipo.RelatorioEcf.Gerencial:
								ImprimirRelatorioGerencial(args.ImagemComprovante);
								break;
							case TefTipo.RelatorioEcf.Vinculado:
								ImprimirComprovanteCreditoDebito(args.ImagemComprovante);
								break;
							}
							args.Resultado = 1;
						}
						catch (Exception)
						{
							args.Resultado = 0;
						}
					}),
					tef.WhenComandarEcfEvent.Subscribe((TefComandarEcfEventArgs args) =>
					{
						EcfTipo.Documento documento = _ecf.VerificarDocumentoAberto();
						Action action = args.Operacao switch
						{
							TefTipo.OperacaoEcf.AbreGerencial => () =>
							{
								try
								{
									AbrirRelatorioGerencial(Otus.Modulo.PontoDeVendas.Enums.RelatoriosGerenciais.Cartao);
								}
								catch (Exception ex2)
								{
									ex2.ShowLastException();
								}
							}, 
							TefTipo.OperacaoEcf.FechaGerencial => FecharRelatorioGerencial, 
							TefTipo.OperacaoEcf.PulaLinhas => (documento == EcfTipo.Documento.ComprovanteCreditoDebito) ? ((Action)(() =>
							{
								AvancarLinhasComprovanteCreditoDebito(5);
							})) : ((Action)(() =>
							{
								AvancarLinhasRelatorioGerencial(5);
							})), 
							TefTipo.OperacaoEcf.FechaVinculado => FecharComprovanteCreditoDebito, 
							TefTipo.OperacaoEcf.CancelaCupom => documento switch
							{
								EcfTipo.Documento.ComprovanteCreditoDebito => (Action)FecharComprovanteCreditoDebito, 
								EcfTipo.Documento.RelatorioGerencial => FecharRelatorioGerencial, 
								_ => () =>
								{
								}, 
							}, 
							_ => () =>
							{
							}, 
						};
						try
						{
							action();
							args.Resultado = 1;
						}
						catch (Exception)
						{
							args.Resultado = 0;
						}
					}),
					tef.WhenComandarEcfPagamentoEvent.Subscribe((TefComandarEcfPagamentoEventArgs args) =>
					{
						args.Resultado = 1;
					}),
					tef.WhenComandarEcfSubtotalizaEvent.Subscribe((TefComandarEcfSubtotalizaEventArgs args) =>
					{
						args.Resultado = 1;
					})
				};
			});
			InicializarEmissor();
		}

		public void InicializarEmissor()
		{
			if (!Carregado && _ecf != null)
			{
				_backgroundWorkerInicializacao.DoWork -= BkwOnDoWork;
				_backgroundWorkerInicializacao.RunWorkerCompleted -= BkwOnRunWorkerCompleted;
			}
			_backgroundWorkerInicializacao.DoWork += BkwOnDoWork;
			_backgroundWorkerInicializacao.RunWorkerCompleted += BkwOnRunWorkerCompleted;
			LoaderProcessoService.MostrarLoader("Lendo dados do ECF");
			if (!_backgroundWorkerInicializacao.IsBusy)
			{
				_backgroundWorkerInicializacao.RunWorkerAsync();
			}
		}

		private void BkwOnRunWorkerCompleted(object sender, RunWorkerCompletedEventArgs runWorkerCompletedEventArgs)
		{
			LoaderProcessoService.EsconderLoader();
			Exception error = runWorkerCompletedEventArgs.Error;
			if (error != null)
			{
				if (error is EcfGrandeTotalInvalidoException || error is EcfNumeroFabricacaoInvalidoException)
				{
					error.ShowLastException();
					OnEmissorEmErroEvent();
				}
				if (error is SemConfiguracaoEcfException)
				{
					OnEmissorEmErroEvent(error.Message);
				}
				else if (error.ShowLastException("Deseja tentar novamente?", yesNo: true))
				{
					InicializarEmissor();
				}
				else
				{
					OnEmissorEmErroEvent();
				}
			}
			else
			{
				FinalizarInicializacao();
				_backgroundWorkerInicializacao.DoWork -= BkwOnDoWork;
				_backgroundWorkerInicializacao.RunWorkerCompleted -= BkwOnRunWorkerCompleted;
			}
		}

		private void FinalizarInicializacao()
		{
			OnEmissorCarregadoEvent();
			VerificarEcf();
			_pafEcfService.SalvarRegistroR01(_ecf.NumeroFabricacao, _ecf.LetraMf, _ecf.Marca.RetornarDescricao(), _ecf.Modelo, _ecf.NumeroUsuario, _ecf.VersaoSoftwareBasico, _ecf.DataHoraSoftwareBasico, _ecf.NumeroEcf);
		}

		private void VerificarEcf()
		{
			if (!_ecf.VerificarEcfLigado())
			{
				OnEmissorEmErroEvent("Ecf desligado");
			}
			else if (_ecf.VerificarTampaAberta())
			{
				OnEmissorEmErroEvent("Tampa aberta");
			}
			else if (_ecf.VerificarFimPapel())
			{
				OnEmissorEmErroEvent("Fim papel");
			}
			else if (_ecf.VerificarReducaoZPendente())
			{
				OnEmissorAvisoEvent("Redução Z pendente");
			}
			else if (_ecf.VerificarReducaoZEmitidaHoje())
			{
				OnEmissorAvisoEvent("Redução Z emitida hoje");
			}
			else if (!VerificarJornadaFiscalAberta())
			{
				OnEmissorAvisoEvent("Jornada fiscal fechada");
			}
			else if (_ecf.VerificarDocumentoAberto() == EcfTipo.Documento.CupomFiscal)
			{
				OnDocumentoFiscalAbertoEvent();
			}
			else
			{
				OnEmissorProntoEvent();
			}
		}

		private void BkwOnDoWork(object sender, DoWorkEventArgs doWorkEventArgs)
		{
			InstanciarEcf();
			Iniciar();
		}

		private void Iniciar()
		{
			try
			{
				_ecf.TerminarComunicacao();
			}
			catch (Exception exception)
			{
				LoggerFactory.CreateLog().LogError("-> TerminarComunicacao", exception);
			}
			_ecf.Configurar();
			_ecf.IniciarComunicacao();
			_ecf.CarregarNumeroFabricacao();
			VerificarEcfHabilitada();
			_ecf.CarregarPermissaoDescontoIss();
			TestarDocumentoAberto();
			_ecf.CarregarTipo();
			_ecf.CarregarMarca();
			_ecf.CarregarModelo();
			_ecf.CarregarNumeroEcf();
			_ecf.CarregarNumeroUsuario();
			_ecf.CarregarDadosSoftwareBasico();
			_ecf.CarregarAliquotas();
			_ecf.CarregarEspeciesPagamento();
			_ecf.CarregarRelatoriosGerenciais();
			_ecf.CarregarTotalizadoresNaoFiscais();
			try
			{
				_ecf.CarregarDadosUltimaReducaoZ();
			}
			catch (Exception exception2)
			{
				LoggerFactory.CreateLog().LogError("-> CarregarDadosUltimaReducaoZ", exception2);
			}
			VerificarArquivoAuxiliar();
			_ecf.PodeEscreverNumeroFabricacaoArquivoAuxiliar = false;
			_ecf.PodeEscreverGrandeTotalArquivoAuxiliar = false;
			_ecf.CompararGrandeTotalArquivoAuxiliar();
			_ecf.CompararNumeroFabricacaoArquivoAuxiliar();
		}

		private void TestarDocumentoAberto()
		{
			EcfTipo.Documento documento = _ecf.VerificarDocumentoAberto();
			if (documento == EcfTipo.Documento.RelatorioGerencial)
			{
				FecharRelatorioGerencial();
			}
			if (documento == EcfTipo.Documento.ComprovanteCreditoDebito)
			{
				_ecf.FecharComprovanteCreditoDebito();
			}
			if (documento == EcfTipo.Documento.ComprovanteNaoFiscal)
			{
				_ecf.CancelarComprovanteNaoFiscal();
			}
		}

		private void VerificarArquivoAuxiliar()
		{
			ConfiguracaoClient configuracaoClient = _configuracaoClientService.ObterConfiguracao();
			if (configuracaoClient?.Ecf != null && configuracaoClient.Ecf.VerificarPrimeiraExecucao(_aesCrypto))
			{
				_ecf.EscreverNumeroFabricacaoArquivoAuxiliar();
				_ecf.EscreverGrandeTotalArquivoAuxiliar();
				configuracaoClient.SetarEcf(configuracaoClient.Ecf.ComExecucaoUm(_aesCrypto));
				_configuracaoClientService.Salvar(configuracaoClient);
			}
		}

		private void InstanciarEcf()
		{
			LoggerFactory.CreateLog().LogInfo("InstanciarEcf");
			if (_ecf != null)
			{
				LoggerFactory.CreateLog().LogInfo($"{_ecf.Marca} - {_ecf.Modelo} - {_ecf.NumeroFabricacao}");
				_ecf.DepoisCarregarDadosReducaoZEvent -= EcfOnDepoisCarregarDadosReducaoZEvent;
				_ecf.AntesEmitirReducaoZEvent -= EcfOnAntesEmitirReducaoZEvent;
				_ecf.DepoisEmitirReducaoZEvent -= EcfOnDepoisEmitirReducaoZEvent;
				_ecf.DepoisFecharRelatorioGerencialEvent -= EcfOnDepoisFecharRelatorioGerencialEvent;
				_ecf.DepoisFecharComprovanteCreditoDebitoEvent -= EcfOnDepoisFecharComprovanteCreditoDebitoEvent;
				_ecf.DepoisEmitirLeituraXEvent -= EcfOnDepoisEmitirLeituraXEvent;
				_ecf.DepoisAbrirJornadaFiscalEvent -= EcfOnDepoisAbrirJornadaFiscalEvent;
			}
			ConfiguracaoClient configuracaoClient = _configuracaoClientService.ObterConfiguracao();
			if (configuracaoClient.Ecf == null)
			{
				SemConfiguracao = true;
				throw new SemConfiguracaoEcfException();
			}
			SemConfiguracao = false;
			if (Enum.TryParse<MarcaEcf>(configuracaoClient.Ecf.Marca, out var result) && result != MarcaEcf.Indefinida)
			{
				_ecf = RetornarEcf(result);
				return;
			}
			foreach (MarcaEcf item in from MarcaEcf m in Enum.GetValues(typeof(MarcaEcf))
				where m != MarcaEcf.Indefinida
				select m)
			{
				_ecf = RetornarEcf(item);
				if (_ecf != null && _ecf.DllsInstaladas)
				{
					configuracaoClient.SetarEcf(configuracaoClient.Ecf.ComMarca(item.ToString()));
					_configuracaoClientService.Salvar(configuracaoClient);
					return;
				}
			}
			throw new Exception("Configuração inválida para o ECF. Dll do ECF não localizada.");
		}

		private IEcfFactory RetornarEcf(MarcaEcf marca)
		{
			string modelo = _configuracaoClientService.ObterConfiguracao().Ecf.Modelo;
			ModeloEcf result;
			if (string.IsNullOrEmpty(modelo))
			{
				result = RetornarModelo(marca);
			}
			else
			{
				Enum.TryParse<ModeloEcf>(modelo, out result);
			}
			return RetornarEcfPelaMarcaEModelo(marca, result);
		}

		private ModeloEcf RetornarModelo(MarcaEcf marca)
		{
			LoggerFactory.CreateLog().LogInfo("RetornarModelo");
			IEcfFactory ecfFactory = RetornarEcfPelaMarcaEModelo(marca, ModeloEcf.Default);
			ModeloEcf result = ModeloEcf.Default;
			if (ecfFactory != null && ecfFactory.DllsInstaladas)
			{
				try
				{
					ecfFactory.IniciarComunicacao();
					ecfFactory.CarregarNumeroFabricacao();
					string ecfNumeroFabricacao = ecfFactory.NumeroFabricacao;
					LoggerFactory.CreateLog().LogInfo($"ECF iniciado: {ecfNumeroFabricacao}");
					try
					{
						ecfFactory.TerminarComunicacao();
					}
					catch
					{
					}
					if (!string.IsNullOrEmpty(ecfNumeroFabricacao))
					{
						Ecf ecf = _sessaoService.Sessao.Perfis.ItemSelecionado.Empresa.PontoDeVenda.Ecfs.FirstOrDefault((Ecf x) => x.NumeroFabricacao == ecfNumeroFabricacao);
						if (ecf == null)
						{
							return result;
						}
						ConfiguracaoClient configuracaoClient = _configuracaoClientService.ObterConfiguracao();
						configuracaoClient.SetarEcf(configuracaoClient.Ecf.ComModelo(ecf.Modelo.ToString()));
						_configuracaoClientService.Salvar(configuracaoClient);
						result = ecf.Modelo;
					}
				}
				catch (Exception exception)
				{
					LoggerFactory.CreateLog().LogError("-> RetornarModelo", exception);
				}
			}
			return result;
		}

		private IEcfFactory RetornarEcfPelaMarcaEModelo(MarcaEcf marca, ModeloEcf modeloEcf)
		{
			IEcfFactory ecfFactory = null;
			switch (marca)
			{
			case MarcaEcf.Bematech:
				ecfFactory = new EcfFactory<Bematech>(modeloEcf);
				break;
			case MarcaEcf.Sweda:
				ecfFactory = new EcfFactory<Sweda>();
				break;
			case MarcaEcf.Daruma:
				ecfFactory = new EcfFactory<Daruma>();
				break;
			case MarcaEcf.Elgin:
				ecfFactory = new EcfFactory<DigisatServer.Infrastructure.Crosscutting.Ecf.Classes.Elgin.Elgin>();
				break;
			case MarcaEcf.Epson:
				ecfFactory = new EcfFactory<Epson>(modeloEcf);
				break;
			case MarcaEcf.Zpm:
				ecfFactory = new EcfFactory<Zpm>(modeloEcf);
				break;
			}
			if (ecfFactory == null)
			{
				return null;
			}
			ecfFactory.Porta = _configuracaoClientService.ObterConfiguracao().Ecf.Porta;
			ecfFactory.IdAplicativo = _arquivoAuxiliarService.NomeAplicativo;
			ecfFactory.Md5 = $"MD-5:{_arquivoAuxiliarService.Md5ArquivosAutenticados}";
			ecfFactory.CaminhoArquivos = Path.Combine(AppDomain.CurrentDomain.BaseDirectory, "Fiscal");
			ecfFactory.ChavePrivada = Hash.RetornarChavePrivadaInformacaoDecifrada();
			ecfFactory.SalvarDadosReducaoZ = true;
			ecfFactory.DepoisCarregarDadosReducaoZEvent += EcfOnDepoisCarregarDadosReducaoZEvent;
			ecfFactory.AntesEmitirReducaoZEvent += EcfOnAntesEmitirReducaoZEvent;
			ecfFactory.DepoisEmitirReducaoZEvent += EcfOnDepoisEmitirReducaoZEvent;
			ecfFactory.DepoisFecharRelatorioGerencialEvent += EcfOnDepoisFecharRelatorioGerencialEvent;
			ecfFactory.DepoisFecharComprovanteCreditoDebitoEvent += EcfOnDepoisFecharComprovanteCreditoDebitoEvent;
			ecfFactory.DepoisEmitirLeituraXEvent += EcfOnDepoisEmitirLeituraXEvent;
			ecfFactory.DepoisAbrirJornadaFiscalEvent += EcfOnDepoisAbrirJornadaFiscalEvent;
			return ecfFactory;
		}

		private void VerificarEcfHabilitada()
		{
			if (DadosSistema.EmpresaLogada.PontoDeVenda.Ecfs.All((Ecf a) => a.NumeroFabricacao != _ecf.NumeroFabricacao))
			{
				throw new Exception($"ECF não consta no arquivo de habilitação. Número de série {_ecf.NumeroFabricacao}");
			}
		}

		private void EcfOnDepoisFecharComprovanteCreditoDebitoEvent(object sender, DataHoraEventArgs dataHoraEventArgs)
		{
			_pafEcfService.SalvarComprovanteDebitoCredito(_ecf.NumeroFabricacao, _ecf.LetraMf, _ecf.Modelo, _ecf.NumeroUsuario, _ecf.Coo, _ecf.Gnf, _ecf.Ccd, _ecf.Marca.RetornarDescricao(), dataHoraEventArgs.Valor, _ecf.DataMovimento);
		}

		private void EcfOnDepoisCarregarDadosReducaoZEvent(object sender, EcfDepoisCarregarDadosReducaoZEventArgs ecfDepoisCarregarDadosReducaoZEventArgs)
		{
			if (ecfDepoisCarregarDadosReducaoZEventArgs.DadosReducaoZ is EcfDadosRecuperadosReducaoZ)
			{
				_envioPafEcfService.SalvarReducaoZ(ecfDepoisCarregarDadosReducaoZEventArgs.DadosReducaoZ);
			}
		}

		private void EcfOnAntesEmitirReducaoZEvent(object sender, EcfAntesEmitirReducaoZEventArgs ecfAntesEmitirReducaoZEventArgs)
		{
			if (!ecfAntesEmitirReducaoZEventArgs.ReducaoZPendente)
			{
				VerificarProcessosPostoAntesReducaoZ();
				VerificarProcessosRestauranteAntesReducaoZ();
				List<MovimentacaoDto> movimentacoes = _service.Canal((IPreVendaModuleService service) => service.ObterPrevendasExpiradasNoFechamentoDoDia(_ecf.DataMovimento)).Result.ToListEmptyWhenNull();
				EmitirCupomDasPrevendas(movimentacoes);
			}
		}

		private void VerificarProcessosRestauranteAntesReducaoZ()
		{
			if (DadosSistema.IsRestauranteOuHotel)
			{
				VerificarMesasContasAbertasExpiradas();
				ImprimirRelatorioGerencialMesasContasAbertas(ObterMesasContasAbertas());
			}
		}

		private IEnumerable<MesaContaAbertaDto> ObterMesasContasAbertas()
		{
			return _service.Canal((IRestauranteModuleService service) => service.ObterMesasContasAbertas()).Result.ToListEmptyWhenNull();
		}

		private void VerificarMesasContasAbertasExpiradas()
		{
			if (_service.Canal((IPessoaModuleService x) => x.VerificarUltimaEcfReducaoZEmpresa(RetornarDataMovimento())))
			{
				DateTime dataMovimento = RetornarDataMovimento();
				List<long> list = (from x in ObterMesasContasAbertas()
					where x.DataHoraAbertura.AddDays(1.0) <= dataMovimento.ToFinalDia()
					select x.NumeroMesaConta).ToListEmptyWhenNull();
				if (list.Any())
				{
					EmitirCupomMesasContasAbertas(list);
				}
			}
		}

		private void EmitirCupomMesasContasAbertas(IEnumerable<long> numerosMesaContaAberta)
		{
			DigisatServer.Domain.Main.Aggregates.CadastrosAgg.Pessoas.Pessoa byId = _pessoaRepositoryRead.GetById(ObjectId.Parse(_sessaoService.Sessao.Perfis.ItemSelecionado.Empresa.Id));
			foreach (long numeroMesaContaAberta in numerosMesaContaAberta)
			{
				Task<IEnumerable<ItemMesaContaDto>> task = _service.Canal((IRestauranteModuleService x) => x.ObterItensParaDocumentoFiscal(RetornarContadorCupomFiscal(), NumeroFabricacao, numeroMesaContaAberta));
				if (task.IsFaulted)
				{
					continue;
				}
				List<ItemMesaContaDto> list = task.Result.ToListEmptyWhenNull();
				Abrir();
				List<Otus.Modulo.PontoDeVendas.ViewModels.ItemDocumentoFiscal> list2 = new List<Otus.Modulo.PontoDeVendas.ViewModels.ItemDocumentoFiscal>();
				List<ProdutoServicoEmpresa> source = _produtoServicoEmpresaRepositoryRead.AggregateInSync(list.Select((ItemMesaContaDto x) => ObjectId.Parse(x.ProdutoServicoEmpresaReferencia))).ToListEmptyWhenNull();
				foreach (ItemMesaContaDto item in list)
				{
					ProdutoServicoEmpresa produtoServicoEmpresa = source.FirstOrDefault((ProdutoServicoEmpresa x) => x.Id.ToString().Equals(item.ProdutoServicoEmpresaReferencia));
					ProdutoServicoLocal produtoServicoLocal = FluentFactory<ProdutoServicoLocalFactory>.Init().ComProdutoServicoEmpresa(produtoServicoEmpresa).Criar();
					VendedorLocal vendedor = null;
					if (!string.IsNullOrEmpty(item.GarcomReferencia))
					{
						vendedor = VendedorLocal.Criar().ComPessoa(_pessoaRepositoryRead.GetById(ObjectId.Parse(item.GarcomReferencia)));
					}
					Otus.Modulo.PontoDeVendas.ViewModels.ItemDocumentoFiscal itemDocumentoFiscal;
					if (produtoServicoLocal.Is<ServicoLocal>())
					{
						produtoServicoLocal.SetarQuantidade(item.Quantidade);
						itemDocumentoFiscal = FluentFactory<Otus.Modulo.PontoDeVendas.ViewModels.ItemDocumentoFiscalFactory>.Init().ComProdutoServicoLocal(produtoServicoLocal).Criar()
							.ComVendedor(vendedor)
							.ComItemMesaContaReferencia(item.Id)
							.ComItensMesaContaReferencia(item.ItensAgrupados.ToListEmptyWhenNull())
							.ComDepartamentoReferencia(item.DepartamentoReferencia);
					}
					else
					{
						itemDocumentoFiscal = FluentFactory<Otus.Modulo.PontoDeVendas.ViewModels.ItemDocumentoFiscalFactory>.Init().ComProdutoServicoLocal(produtoServicoLocal).Criar()
							.To<ItemDocumentoFiscalProduto>()
							.ComEstoque(produtoServicoLocal.To<ProdutoLocal>().ObterEstoqueVenda(item.Quantidade))
							.ComVendedor(vendedor)
							.ComItemMesaContaReferencia(item.Id)
							.ComItensMesaContaReferencia(item.ItensAgrupados.ToListEmptyWhenNull())
							.ComDepartamentoReferencia(item.DepartamentoReferencia);
					}
					list2.Add(itemDocumentoFiscal);
					try
					{
						Vender(itemDocumentoFiscal);
						if (item.Cancelado)
						{
							CancelarItem(itemDocumentoFiscal.NumeroItem);
							itemDocumentoFiscal.Cancelar();
						}
					}
					catch (Exception ex)
					{
						ex.ShowLastException();
					}
				}
				if (list.All((ItemMesaContaDto x) => x.Cancelado))
				{
					_ecf.CancelarCupomFiscal();
					PreDocumentoFiscal.Criar(_preDocumentoFiscalRepositoryWrite, _movimentacaoRepositoryWrite, _operacaoFiscalRepositoryRead, _promocaoScanntechRepositoryRead, this, _sessaoService, list2, byId).Cancelar(Tipo);
					continue;
				}
				DinheiroViewModel dinheiroViewModel = DinheiroViewModel.Criar();
				dinheiroViewModel.SomarValor(_ecf.Subtotal);
				ItemMesaContaDto itemMesaContaDto = list.First();
				IMensagemPromocional[] source2 = new IMensagemPromocional[2]
				{
					MesaContaMensagemPromocional.Criar().ComCer(itemMesaContaDto.Cer).ComCoo(itemMesaContaDto.Coo)
						.ComNumeroMesaConta(itemMesaContaDto.NumeroMesaConta)
						.ComNumeroSequencialEcf(itemMesaContaDto.NumeroSequencialEcf),
					TributoMensagemPromocional.Criar().ComItensDocumentoFiscal(list2)
				};
				try
				{
					Totalizar(Otus.Modulo.PontoDeVendas.ViewModels.Desconto.Criar());
				}
				catch (Exception ex2)
				{
					ex2.ShowLastException();
				}
				EfetuarPagamento(dinheiroViewModel);
				Finalizar(source2.OrderBy((IMensagemPromocional x) => x.Indice));
				PreDocumentoFiscal preDocumentoFiscal = PreDocumentoFiscal.Criar(_preDocumentoFiscalRepositoryWrite, _movimentacaoRepositoryWrite, _operacaoFiscalRepositoryRead, _promocaoScanntechRepositoryRead, this, _sessaoService, list2, byId);
				preDocumentoFiscal.SetarPagamentos(0m, dinheiroViewModel);
				preDocumentoFiscal.SetarObservacao(string.Join(Environment.NewLine, source2.Select((IMensagemPromocional x) => x.TextoFormatado)));
				preDocumentoFiscal.Efetivar(Tipo);
			}
		}

		public override void EmitirCupomDasPrevendas(IEnumerable<MovimentacaoDto> movimentacoes)
		{
			DigisatServer.Domain.Main.Aggregates.CadastrosAgg.Pessoas.Pessoa byId = _pessoaRepositoryRead.GetById(ObjectId.Parse(_sessaoService.Sessao.Perfis.ItemSelecionado.Empresa.Id));
			foreach (MovimentacaoDto movimentaco in movimentacoes)
			{
				ConsumidorLocal consumidorLocal = ConsumidorLocal.Criar().ComPessoa(movimentaco.Pessoa);
				IdentificarConsumidor(consumidorLocal);
				Abrir();
				List<Otus.Modulo.PontoDeVendas.ViewModels.ItemDocumentoFiscal> list = new List<Otus.Modulo.PontoDeVendas.ViewModels.ItemDocumentoFiscal>();
				foreach (ItemDto iten in movimentaco.Itens)
				{
					ProdutoServicoEmpresa produtoServicoEmpresa = _produtoServicoEmpresaRepositoryRead.FindOne(EntityBaseSpecification<ProdutoServicoEmpresa>.PorId(iten.ProdutoServicoEmpresaReferencia));
					Otus.Modulo.PontoDeVendas.ViewModels.ItemDocumentoFiscal itemDocumentoFiscal = FluentFactory<Otus.Modulo.PontoDeVendas.ViewModels.ItemDocumentoFiscalFactory>.Init().ComProdutoServicoLocal(FluentFactory<ProdutoServicoLocalFactory>.Init().ComProdutoServicoEmpresa(produtoServicoEmpresa).ComItemDto(iten)
						.Criar()).ComEstoque(iten.Estoque)
						.Criar()
						.ComNumeroItem(list.Count + 1);
					list.Add(itemDocumentoFiscal);
					try
					{
						Vender(itemDocumentoFiscal);
						if (iten.TotalDesconto > 0m)
						{
							AplicarDesconto(itemDocumentoFiscal, iten.TotalDesconto);
							itemDocumentoFiscal.ComDesconto(iten.TotalDesconto);
						}
						else if (iten.TotalOutrasDespesas > 0m)
						{
							AplicarAcrescimo(itemDocumentoFiscal, iten.TotalOutrasDespesas);
							itemDocumentoFiscal.ComAcrescimo(iten.TotalOutrasDespesas);
						}
						if (iten.Cancelado)
						{
							CancelarItem(itemDocumentoFiscal.NumeroItem);
							itemDocumentoFiscal.Cancelar();
						}
					}
					catch (Exception ex)
					{
						ex.ShowLastException();
					}
				}
				if (movimentaco.Itens.All((ItemDto x) => x.Cancelado))
				{
					_ecf.CancelarCupomFiscal();
					PreDocumentoFiscal preDocumentoFiscal = PreDocumentoFiscal.Criar(_preDocumentoFiscalRepositoryWrite, _movimentacaoRepositoryWrite, _operacaoFiscalRepositoryRead, _promocaoScanntechRepositoryRead, this, _sessaoService, list, byId);
					preDocumentoFiscal.SetarMovimentacaoReferenciada(movimentaco);
					preDocumentoFiscal.Cancelar(Tipo);
					continue;
				}
				DinheiroViewModel dinheiroViewModel = DinheiroViewModel.Criar();
				dinheiroViewModel.SomarValor(movimentaco.Total);
				IMensagemPromocional[] source = new IMensagemPromocional[2]
				{
					PreVendaMensagemPromocional.Criar().ComNumero(movimentaco.Numero),
					TributoMensagemPromocional.Criar().ComItensDocumentoFiscal(list)
				};
				try
				{
					Totalizar(Otus.Modulo.PontoDeVendas.ViewModels.Desconto.Criar());
				}
				catch (Exception ex2)
				{
					ex2.ShowLastException();
				}
				EfetuarPagamento(DinheiroViewModel.Criar().ComValor(list.Sum((Otus.Modulo.PontoDeVendas.ViewModels.ItemDocumentoFiscal x) => x.TotalLiquido)));
				Finalizar(source.OrderBy((IMensagemPromocional x) => x.Indice));
				PreDocumentoFiscal preDocumentoFiscal2 = PreDocumentoFiscal.Criar(_preDocumentoFiscalRepositoryWrite, _movimentacaoRepositoryWrite, _operacaoFiscalRepositoryRead, _promocaoScanntechRepositoryRead, this, _sessaoService, list, byId, consumidorLocal);
				preDocumentoFiscal2.SetarMovimentacaoReferenciada(movimentaco);
				preDocumentoFiscal2.SetarPagamentos(0m, dinheiroViewModel);
				preDocumentoFiscal2.SetarObservacao(string.Join(Environment.NewLine, source.Select((IMensagemPromocional x) => x.TextoFormatado)));
				preDocumentoFiscal2.Efetivar(Tipo);
				Cancelar(DocumentoFiscalFechado.Criar(), new AutorizacaoPafEcf(preDocumentoFiscal2.NomeUsuario));
			}
		}

		private void VerificarProcessosPostoAntesReducaoZ()
