		public override void EmitirDocumentoFiscalAbastecimentosFechamentoTurno(Action voltarAction, Action verificarPendenciasAction, IAbastecimento[] abastecimentosPendentes)
		{
			if (DialogoFactory.MostrarDialogoSimNao("Faturar os abastecimentos pendentes antes de efetuar o fechamento do turno?") == MessageBoxResult.Yes)
			{
				voltarAction?.Invoke();
				EmitirDocumentoFiscalAbastecimentos(abastecimentosPendentes);
			}
			else
			{
				verificarPendenciasAction?.Invoke();
			}
		}

		public override void EmitirDocumentoFiscalAbastecimentos(params IAbastecimento[] abastecimentosPendentes)
		{
			DigisatServer.Domain.Main.Aggregates.CadastrosAgg.Pessoas.Pessoa byId = _pessoaRepositoryRead.GetById(ObjectId.Parse(_sessaoService.Sessao.Perfis.ItemSelecionado.Empresa.Id));
			foreach (IAbastecimento abastecimento in abastecimentosPendentes.ToListEmptyWhenNull())
			{
				LoggerFactory.CreateLog().LogInfo($"Abastecimento: {abastecimento.Id} - Bico: {abastecimento.NumeroDoBicoNoSoftware} - Valor: {abastecimento.ValorTotal:c2}");
				try
				{
					Abrir();
					PreDocumentoFiscal preDocumentoFiscal = PreDocumentoFiscal.Criar(_preDocumentoFiscalRepositoryWrite, _movimentacaoRepositoryWrite, _operacaoFiscalRepositoryRead, _promocaoScanntechRepositoryRead, this, _sessaoService, null, byId);
					ProdutoServicoEmpresa produtoServicoEmpresa = _produtoServicoEmpresaRepositoryRead.FindOne(EntityBaseSpecification<ProdutoServicoEmpresa>.PorId(abastecimento.IdProduto));
					Otus.Modulo.PontoDeVendas.ViewModels.ItemDocumentoFiscal item = FluentFactory<Otus.Modulo.PontoDeVendas.ViewModels.ItemDocumentoFiscalFactory>.Init().ComProdutoServicoLocal(FluentFactory<ProdutoServicoLocalFactory>.Init().ComProdutoServicoEmpresa(produtoServicoEmpresa).Criar()).ComAbastecimento(abastecimento)
						.Criar();
					List<Otus.Modulo.PontoDeVendas.ViewModels.ItemDocumentoFiscal> list = new List<Otus.Modulo.PontoDeVendas.ViewModels.ItemDocumentoFiscal> { item };
					foreach (Otus.Modulo.PontoDeVendas.ViewModels.ItemDocumentoFiscal item2 in list)
					{
						Vender(item2);
						_eventPublisher.Publish(new RemoverAbastecimentosRequest(new List<IAbastecimento> { item2.To<ItemDocumentoFiscalCombustivel>().Abastecimento }));
					}
					preDocumentoFiscal.AdicionarItens(list);
					preDocumentoFiscal.Salvar();
					Totalizar(Otus.Modulo.PontoDeVendas.ViewModels.Desconto.Criar());
					DinheiroViewModel dinheiroViewModel = DinheiroViewModel.Criar().ComValor(list.Sum((Otus.Modulo.PontoDeVendas.ViewModels.ItemDocumentoFiscal x) => x.TotalLiquido));
					EfetuarPagamento(dinheiroViewModel);
					preDocumentoFiscal.SetarPagamentos(0m, dinheiroViewModel);
					List<IMensagemPromocional> list2 = list.Select((Otus.Modulo.PontoDeVendas.ViewModels.ItemDocumentoFiscal value) => value.To<ItemDocumentoFiscalCombustivel>().ObterMensagemPromocionalComCupomAutomatico()).ToList();
					list2.Add(TributoMensagemPromocional.Criar().ComItensDocumentoFiscal(list));
					Finalizar(list2.OrderBy((IMensagemPromocional x) => x.Indice));
					preDocumentoFiscal.SetarObservacao(string.Join(Environment.NewLine, list2.Select((IMensagemPromocional x) => x.TextoFormatado)));
					_service.Canal((IPostoCombustivelModuleService x) =>
					{
						x.AtualizarStatusAbastecimentoEmitidoCupomFiscalAutomatico(abastecimento.Id, RetornarContadorOrdemOperacao(), RetornarDataEmissao(), RetornarNumeroFabricacao());
					});
					preDocumentoFiscal.Efetivar(Tipo);
				}
				catch (Exception ex)
				{
					LoggerFactory.CreateLog().LogInfo("EmitirDocumentoFiscalAbastecimentos", ex);
					VerificarEcf();
					throw;
				}
			}
		}

		public override void EmitirDocumentoFiscal(IEnumerable<Otus.Modulo.PontoDeVendas.ViewModels.ItemDocumentoFiscal> itens, ConsumidorLocal consumidor = null, AcrescimoDesconto acrescimoDesconto = null, params IMensagemPromocional[] mensagensPromocionais)
		{
			List<Otus.Modulo.PontoDeVendas.ViewModels.ItemDocumentoFiscal> list = itens.ToList();
			IdentificarConsumidor(consumidor);
			try
			{
				Abrir();
				foreach (Otus.Modulo.PontoDeVendas.ViewModels.ItemDocumentoFiscal item in list)
				{
					Vender(item);
				}
				Totalizar(acrescimoDesconto ?? Otus.Modulo.PontoDeVendas.ViewModels.Desconto.Criar());
				EfetuarPagamento(DinheiroViewModel.Criar().ComValor(list.Sum((Otus.Modulo.PontoDeVendas.ViewModels.ItemDocumentoFiscal x) => x.TotalLiquido)));
				Finalizar(mensagensPromocionais.OrderBy((IMensagemPromocional x) => x.Indice));
			}
			catch (Exception)
			{
				VerificarEcf();
				OnEmissorEmErroEvent();
				throw;
			}
		}

		private void VerificarProcessosPostoDepoisReducaoZ()
		{
			if (DadosSistema.IsPostoCombustivel)
			{
				AbrirJornadaFiscalAposReducaoZ();
				ImprimirRelatorioGerencialEncerrantes();
				ImprimirRelatorioGerencialAlertaSemComunicacao();
				EmitirCupomFiscalAbastecimentosPendentes();
			}
		}

		private void VerificarProcessosRestauranteDepoisReducaoZ()
		{
			if (DadosSistema.IsRestauranteOuHotel)
			{
				AbrirJornadaFiscalAposReducaoZ();
				ImprimirRelatorioGerencialMesasContasAbertas(ObterMesasContasAbertas());
				EmitirCupomMesasContasAbertasAberturaDia();
			}
		}

		private void EmitirCupomMesasContasAbertasAberturaDia()
		{
			List<long> list = (from x in ObterMesasContasAbertas()
				where x.DataHoraAbertura.AddDays(1.0) <= DateTime.Today.AddDays(-1.0).ToFinalDia()
				select x.NumeroMesaConta).ToListEmptyWhenNull();
			if (list.Any())
			{
				EmitirCupomMesasContasAbertas(list.ToListEmptyWhenNull());
			}
		}

		private void EcfOnDepoisEmitirReducaoZEvent(object sender, EcfDepoisEmitirReducaoZEventArgs ecfDepoisEmitirReducaoZEventArgs)
		{
			VerificarEcf();
			try
			{
				OnAlterouEstadoJornadaFiscalEvent(e: false);
				IEcfDadosReducaoZ dadosReducaoZ = ecfDepoisEmitirReducaoZEventArgs.DadosReducaoZ;
				OnEmissorAvisoEvent("Salvando dados da redução Z. Aguarde...");
				_pafEcfService.SalvarReducaoZ(dadosReducaoZ);
				for (int i = 0; i < 5000; i++)
				{
					if (Dispatcher.CurrentDispatcher.HasShutdownStarted)
					{
						break;
					}
					if (Dispatcher.CurrentDispatcher.HasShutdownFinished)
					{
						break;
					}
					Thread.Sleep(1);
					DispatcherHelper.DoEvents();
				}
				OnEmissorAvisoEvent("Gerando arquivo do PAF ECF. Aguarde...");
				_pafEcfService.GerarArquivoRegistrosPafEcf(dadosReducaoZ.DataMovimento, dadosReducaoZ.DataMovimento);
				if (ecfDepoisEmitirReducaoZEventArgs.ReducaoZPendente)
				{
					VerificarProcessosPostoDepoisReducaoZ();
					VerificarProcessosRestauranteDepoisReducaoZ();
					List<MovimentacaoDto> list = _service.Canal((IPreVendaModuleService service) => service.ObterPrevendasExpiradasNaAberturaDia(_ecf.DataHora)).Result.ToListEmptyWhenNull();
					if (list.Any())
					{
						if (!VerificarJornadaFiscalAberta())
						{
							AbrirJornadaFiscalAposReducaoZ();
						}
						EmitirCupomDasPrevendas(list);
					}
				}
				if (DadosSistema.IsPostoCombustivel)
				{
					AtualizarAbastecimentosVerificadosReducaoZ();
				}
				if (ecfDepoisEmitirReducaoZEventArgs.PrimeiraReducaoMes && DadosSistema.PodeGerarArquivosBinarios)
				{
					DateTime dateTime = dadosReducaoZ.DataHora.AddMonths(-1);
					DateTime dataInicial = new DateTime(dateTime.Year, dateTime.Month, 1);
					DateTime dataFinal = new DateTime(dataInicial.Year, dataInicial.Month, DateTime.DaysInMonth(dataInicial.Year, dataInicial.Month));
					GerarArquivoBinario(() => GerarArquivoBinarioMemoriaFiscal(new EcfArquivoBinarioMemoriaFiscalData
					{
						DataInicial = dataInicial,
						DataFinal = dataFinal
					}));
					GerarArquivoBinario(() => GerarArquivoBinarioMemoriaFitaDetalhe(new EcfArquivoBinarioMemoriaFitaDetalheData
					{
						DataInicial = dataInicial,
						DataFinal = dataFinal
					}));
				}
				if (ecfDepoisEmitirReducaoZEventArgs.PrimeiraReducaoMes && DadosSistema.UFEmpresaLogada.DeveTransmitirArquivoRegistrosPafEcfRequisitoLXI())
				{
					_pafEcfService.VerificarTransmissaoRegistrosPafEcf();
				}
				OnEmissorAvisoEvent("Gerando arquivos do Bloco X. Aguarde...");
				_envioPafEcfService.SalvarReducaoZ(dadosReducaoZ);
				if (DadosSistema.EmpresaLogada.RamoAtividade.IsNot<DigisatServer.Infrastructure.Crosscutting.Model.RamosAtividade.Restaurante>() && DateTime.Now > new DateTime(DateTime.Now.Year, 1, 1) && DateTime.Now < new DateTime(DateTime.Now.Year, 1, 21))
				{
					_envioPafEcfService.SalvarEstoque(dadosReducaoZ.DataMovimento);
					_envioPafEcfService.TransmitirTodos();
				}
			}
			finally
			{
				VerificarEcf();
			}
		}

		private void GerarArquivoBinario(Func<string> func)
		{
			try
			{
				DialogoFactory.MostrarDialogoConfirma($"Arquivo {func()} gerado com sucesso.");
			}
			catch (Exception ex)
			{
				ex.ShowLastException();
			}
		}

