		public void Abrir()
		{
			try
			{
				if (AguardarEcfCarregado())
				{
					_ecf.AbrirCupomFiscal();
				}
			}
			catch (Exception)
			{
				EcfTipo.EstadoDocumento estadoDocumento = _ecf.VerificarEstadoDocumentoAberto();
				if (_ecf.VerificarDocumentoAberto() == EcfTipo.Documento.CupomFiscal && (estadoDocumento == EcfTipo.EstadoDocumento.Aberto || estadoDocumento == EcfTipo.EstadoDocumento.RegistroDeItem))
				{
					throw new DocumentoFiscalAbertoException();
				}
				throw;
			}
		}

		public void Vender(Otus.Modulo.PontoDeVendas.ViewModels.ItemDocumentoFiscal item)
		{
			EcfProdutoServico produtoServico = new EcfProdutoServico
			{
				Codigo = item.Codigo,
				Descricao = item.DescricaoCestNcm,
				Arredondar = false,
				PercentualAliquota = item.PercentualAliquota,
				PrecoUnitario = item.PrecoUnitario,
				Quantidade = item.Quantidade,
				TipoTributacao = item.Tributacao,
				UnidadeMedida = item.UnidadeMedida
			};
			IEcfAliquota ecfAliquota = _ecf.Aliquotas.FirstOrDefault((IEcfAliquota x) => x.Tipo == item.Tributacao && x.Percentual == item.PercentualAliquota);
			if (ecfAliquota != null)
			{
				item.ComIndiceAliquotaEcf(ecfAliquota.Id);
			}
			try
			{
				_ecf.VenderCupomFiscal(produtoServico);
			}
			catch (Exception)
			{
				VerificarEcf();
				throw;
			}
		}

