		public void EfetuarPagamento(ItemPagamentoViewModel itemPagamento)
		{
			IEcfEspeciePagamento ecfEspeciePagamento = _ecf.EspeciesPagamento.FirstOrDefault((IEcfEspeciePagamento x) => x.Descricao.ToLower().Contains(itemPagamento.Descricao.RemoverAcentos().ToLower()));
			if (ecfEspeciePagamento.IsNull() && itemPagamento.Is<ICarteiraDigital>())
			{
				ecfEspeciePagamento = _ecf.EspeciesPagamento.FirstOrDefault((IEcfEspeciePagamento x) => x.Descricao.ToLower().Contains(CarteiraDigitalTefViewModel.DescricaoEcf.ToLower()));
			}
			if (ecfEspeciePagamento == null)
			{
				throw new Exception("Espécie de pagamento inválida");
			}
			EcfEspeciePagamento especiePagamento = new EcfEspeciePagamento
			{
				Id = ecfEspeciePagamento.Id,
				Descricao = ecfEspeciePagamento.Descricao,
				PermiteVinculado = ecfEspeciePagamento.PermiteVinculado,
				Indice = ecfEspeciePagamento.Indice,
				Valor = itemPagamento.Valor
			};
			_ecf.EfetuarPagamentoCupomFiscal(especiePagamento);
		}

		public void Finalizar(IEnumerable<IMensagemPromocional> mensagemPromocional)
		{
			List<IEcfMensagemPromocional> list = new List<IEcfMensagemPromocional>();
			foreach (IMensagemPromocional promocional in mensagemPromocional)
			{
				list.AddRange(promocional.Linhas.Select((string linha) => new EcfMensagemPromocional
				{
					Texto = linha,
					QuebrarLinha = true,
					Negrito = promocional.Is<IMensagemPromocionalNegrito>()
				}));
			}
			if (_ecf.VerificarDocumentoAberto() == EcfTipo.Documento.CupomFiscal)
			{
				_ecf.EncerrarCupomFiscal(list);
				OnEmissorTerminouDocumentoFiscalEvent(_ecf.Coo);
			}
		}

		public void Cancelar(IEstadoDocumentoFiscal estadoDocumentoFiscal, Autorizacao autorizacao)
		{
			int coo = _ecf.Coo;
			int ccf = _ecf.Ccf;
			OnDocumentoFiscalCanceladoEvent(coo.ToString());
			_ecf.CancelarCupomFiscal();
			if (estadoDocumentoFiscal is DocumentoFiscalFechado)
			{
				CancelarCupomFiscal(autorizacao, ccf);
			}
			if (DadosSistema.IsPostoCombustivel)
			{
				ImprimirCancelamentoAbastecimento(estadoDocumentoFiscal, coo);
			}
		}

		public void ImprimirCancelamentoAbastecimento(IEstadoDocumentoFiscal estadoDocumentoFiscal, int cooAtual)
		{
			List<string> list = new List<string>();
			if (estadoDocumentoFiscal is DocumentoFiscalFechado)
			{
				List<AbastecimentoDto> source = _service.Canal((IPostoCombustivelModuleService x) => x.ObterAbastecimentosPorCupomFiscal(cooAtual, _ecf.NumeroFabricacao)).ToListEmptyWhenNull();
				if (source.Any())
				{
					list.Add("CANCELAMENTO DE ABASTECIMENTO");
					list.AddRange(from abastecimento in source
						orderby abastecimento.NumeroDoBicoNoSoftware
						select $":B{abastecimento.NumeroDoBicoNoSoftware:00} EI{abastecimento.EncerranteInicial:0000000.000} EF{abastecimento.EncerranteFinal:0000000.000} V{abastecimento.Litros:0.000}" into mensagem
						select $"#CC{mensagem}");
				}
			}
			else
			{
				list.AddRange(ObterLinhasRelatorioCancelamentoAbastecimentoCupomFiscalAberto());
			}
			if (list.Any())
			{
				ImprimirRelatorioGerencial(list, Otus.Modulo.PontoDeVendas.Enums.RelatoriosGerenciais.CancelamentoAbastecimento);
			}
		}

		private IEnumerable<string> ObterLinhasRelatorioCancelamentoAbastecimentoCupomFiscalAberto()
		{
			List<IAbastecimento> list = (from x in _preDocumentoFiscalRepositoryRead.FindOne(new TrueSpecification<PreDocumentoFiscal>()).Itens.OfType<ItemDocumentoFiscalCombustivel>()
				orderby x.Abastecimento.NumeroDoBicoNoSoftware
				select x.Abastecimento).ToListEmptyWhenNull();
			if (!list.Any())
			{
				return Enumerable.Empty<string>();
			}
			List<string> list2 = new List<string> { "CANCELAMENTO DE ABASTECIMENTO" };
			foreach (IAbastecimento item in list)
			{
				string arg = $":B{item.NumeroDoBicoNoSoftware:00} EI{item.EncerranteInicial:0000000.000} EF{item.EncerranteFinal:0000000.000} V{item.Litros:0.000}";
				list2.Add($"#CF{arg}");
				list2.Add($"#CC{arg}");
			}
			return list2;
		}

		private void CancelarCupomFiscal(Autorizacao autorizacao, int ccf)
		{
			DigisatServer.Domain.Main.Aggregates.MovimentacoesAgg.Saidas.CupomFiscal cupomFiscal = _movimentacaoRepositoryRead.FindOne(MovimentacaoSpecification.PorTipo<DigisatServer.Domain.Main.Aggregates.MovimentacoesAgg.Saidas.CupomFiscal>().PorNumero(ccf)) as DigisatServer.Domain.Main.Aggregates.MovimentacoesAgg.Saidas.CupomFiscal;
			if (cupomFiscal.IsNull())
			{
				return;
			}
			decimal num = cupomFiscal.Pagamentos?.Where((ItemPagamento x) => x.EspeciePagamento.Codigo == 1).Sum((ItemPagamento x) => x.Valor) ?? 0m;
			if (num > 0m)
			{
				new ValorSangriaService(_valorSangriaRepositoryWrite, _valorSangriaRepositoryRead).AlterarValor(num, aumentar: false);
			}
			cupomFiscal.SetarSituacaoCancelado(_sessaoService.Sessao.NomeUsuario, autorizacao);
			_movimentacaoRepositoryWrite.Update(cupomFiscal);
			IEnumerable<ItemPagamento> pagamentos = cupomFiscal.Pagamentos;
			if (pagamentos != null && pagamentos.OfType<ItemPagamentoCarteiraDigital>().Any())
			{
				EstornarPagamentosDigitais(cupomFiscal.Pagamentos.OfType<ItemPagamentoCarteiraDigital>().SelectMany((ItemPagamentoCarteiraDigital pagamentoCarteiraDigital) => pagamentoCarteiraDigital.InformacoesTransacao.Select((InformacaoTransacaoCarteiraDigital transacaoCarteiraDigital) => transacaoCarteiraDigital.Nsu)));
			}
			IEnumerable<ItemPagamento> pagamentos2 = cupomFiscal.Pagamentos;
			if (pagamentos2 != null && pagamentos2.OfType<ItemPagamentoCartao>().Any())
			{
				CancelarTransacaoTef(new List<InformacaoTransacao>(cupomFiscal.Pagamentos?.OfType<ItemPagamentoCartao>().Where((ItemPagamentoCartao x) => x.InformacoesTransacao.Any() && x.EspeciePagamento.Codigo != 27 && !x.InformacoesTransacao.All((InformacaoTransacaoTef y) => y.CodigoAutorizacaoTransacao.IsNullOrEmpty())).SelectMany((ItemPagamentoCartao x) => x.InformacoesTransacao.Select((InformacaoTransacaoTef y) => new InformacaoTransacao(y.Rede, y.Nsu, y.Valor)))));
			}
			IEnumerable<ItemPagamento> pagamentos3 = cupomFiscal.Pagamentos;
			if (pagamentos3 == null || !pagamentos3.OfType<ItemPagamentoCarteiraDigital>().Any())
			{
				return;
			}
			CancelarTransacaoTef(new List<InformacaoTransacao>(cupomFiscal.Pagamentos?.OfType<ItemPagamentoCarteiraDigital>().Where((ItemPagamentoCarteiraDigital x) => x.InformacoesTransacao.Any() && x.EspeciePagamento.Codigo != 27 && x.InformacoesTransacao.Any((InformacaoTransacaoCarteiraDigital y) => y.CodigoAutorizacaoTransacao != 0) && x.InformacoesTransacao.Any((InformacaoTransacaoCarteiraDigital y) => y.IsNsuValidoCancelamentoShipay)).SelectMany((ItemPagamentoCarteiraDigital x) => x.InformacoesTransacao.Select((InformacaoTransacaoCarteiraDigital y) => new InformacaoTransacao(y.Rede, y.Nsu, y.Valor)))));
		}

