		public void EmitirComprovanteNaoFiscalRecebimento(ConsumidorLocal consumidor, string especie, decimal valorRecebido, decimal valorQuitado)
		{
			IdentificarConsumidor(consumidor);
			try
			{
				IEcfComprovanteNaoFiscal ecfComprovanteNaoFiscal = _ecf.TotalizadoresNaoFiscais.FirstOrDefault((IEcfComprovanteNaoFiscal x) => !string.IsNullOrEmpty(x.Descricao) && x.Descricao.ToLower().Contains("recebimentos"));
				if (ecfComprovanteNaoFiscal != null)
				{
					_ecf.AbrirComprovanteNaoFiscal();
					_ecf.RegistrarItemComprovanteNaoFiscal(new EcfRegistrarItemComprovanteNaoFiscal
					{
						DescontoAcrescimo = EcfTipo.DescontoAcrescimo.Nenhum,
						ValorDescontoAcrescimo = 0m,
						Valor = valorQuitado,
						Descricao = ecfComprovanteNaoFiscal.Descricao
					});
					_ecf.TotalizarComprovanteNaoFiscal(new EcfDescontoAcrescimo
					{
						Tipo = EcfTipo.DescontoAcrescimo.Nenhum,
						Valor = 0m
					});
					IEcfEspeciePagamento ecfEspeciePagamento = _ecf.EspeciesPagamento.FirstOrDefault((IEcfEspeciePagamento x) => x.Descricao.ToLower().Contains(especie.RemoverAcentos().ToLower()));
					if (ecfEspeciePagamento == null)
					{
						throw new Exception("Espécie de pagamento inválida");
					}
					EcfEspeciePagamento ecfEspeciePagamento2 = new EcfEspeciePagamento
					{
						Id = ecfEspeciePagamento.Id,
						Descricao = ecfEspeciePagamento.Descricao,
						Indice = ecfEspeciePagamento.Indice,
						PermiteVinculado = ecfEspeciePagamento.PermiteVinculado,
						Valor = valorRecebido
					};
					_ecf.EfetuarPagamentoComprovanteNaoFiscal(ecfEspeciePagamento2);
					_ecf.EncerrarComprovanteNaoFiscal(new List<IEcfMensagemPromocional>());
					_pafEcfService.SalvarComprovanteNaoFiscal(_ecf.NumeroFabricacao, _ecf.LetraMf, _ecf.Modelo, _ecf.NumeroUsuario, _ecf.Coo, _ecf.Gnf, _ecf.Marca.RetornarDescricao(), _ecf.DataHora, new List<IEcfEspeciePagamento> { ecfEspeciePagamento2 }, _ecf.DataMovimento);
				}
			}
			catch (Exception)
			{
				if (_ecf.VerificarDocumentoAberto() == EcfTipo.Documento.ComprovanteNaoFiscal)
				{
					_ecf.CancelarComprovanteNaoFiscal();
				}
			}
			finally
			{
				_ecf.RemoverConsumidor();
			}
		}

