		public override void ImprimirConferenciaMesaConta(long numeroMesaConta, bool mostrarPreview)
		{
			LoaderProcessoService.MostrarLoader($"Emitindo conferência de {DadosSistema.TipoRestaurante}");
			try
			{
				int cer = ((DadosSistema.TipoMesaConta == TipoMesaContaCliente.Mesa) ? RetornarContadorEspecificoRelatorioGerencial(Otus.Modulo.PontoDeVendas.Enums.RelatoriosGerenciais.ConferenciaMesa) : RetornarContadorEspecificoRelatorioGerencial(Otus.Modulo.PontoDeVendas.Enums.RelatoriosGerenciais.ConferenciaContaCliente));
				List<string> list = _service.Canal((IRestauranteModuleService service) => service.ObterRelatorioConferenciaMesaConta(numeroMesaConta, cer + 1, RetornarContadorOrdemOperacao() + 1, RetornarNumeroSequencialEcf(), NumeroFabricacao)).Result.ToListEmptyWhenNull();
				if (!list.Any())
				{
					DialogoFactory.MostrarDialogoConfirma($"{DadosSistema.TipoRestaurante} fechada");
					return;
				}
				list.Insert(0, $"CONFERENCIA DE {DadosSistema.TipoRestaurante}".ToUpper());
				list.Add("AGUARDE A EMISSAO DO CUPOM FISCAL");
				ImprimirRelatorioGerencialConferenciaMesaConta(list);
			}
			catch (Exception ex)
			{
				ex.ShowLastException();
			}
			finally
			{
				LoaderProcessoService.EsconderLoader();
			}
		}

		public override void ImprimirRelatorioGerencialSeriaisVendidos()
		{
			try
			{
				if (SeriaisVendidos.IsNull() || !SeriaisVendidos.Any() || DialogoFactory.MostrarDialogoSimNao("Imprimir relatório gerencial de seriais vendidos?") != MessageBoxResult.Yes)
				{
					return;
				}
				AbrirRelatorioGerencial(Otus.Modulo.PontoDeVendas.Enums.RelatoriosGerenciais.SeriaisVendidos);
				List<string> list = new List<string>();
				foreach (IDadoEmissor seriaisVendido in SeriaisVendidos)
				{
					if (seriaisVendido.Is<TextoEmissor>())
					{
						list.Add(seriaisVendido.Informacao);
						continue;
					}
					_ecf.ImprimirRelatorioGerencial(list);
					_ecf.ImprimirCodigoBarras(seriaisVendido.Informacao);
					list.Clear();
				}
				if (list.Any())
				{
					_ecf.ImprimirRelatorioGerencial(list);
				}
				FecharRelatorioGerencial();
			}
			catch (Exception ex)
			{
				if (_ecf.VerificarDocumentoAberto() == EcfTipo.Documento.RelatorioGerencial)
				{
					FecharRelatorioGerencial();
				}
				ex.ShowLastException();
			}
		}

		public override void ImprimirRelatorioGerencialInformacoesTransacao()
		{
			for (int i = 0; i < DadosSistema.ConfiguracaoDto.Saida.NumeroViasComprovanteCarteiraDigital.Valor; i++)
			{
				try
				{
					if (InformacoesTransacao.IsNull() || !InformacoesTransacao.Any())
					{
						break;
					}
					AbrirRelatorioGerencial(Otus.Modulo.PontoDeVendas.Enums.RelatoriosGerenciais.CarteiraDigital);
					List<string> list = new List<string>();
					foreach (IDadoEmissor item in InformacoesTransacao)
					{
						if (item.Is<TextoEmissor>())
						{
							list.Add(item.Informacao);
							continue;
						}
						_ecf.ImprimirRelatorioGerencial(list);
						_ecf.ImprimirCodigoBarras(item.Informacao);
						list.Clear();
					}
					if (list.Any())
					{
						_ecf.ImprimirRelatorioGerencial(list);
					}
					FecharRelatorioGerencial();
				}
				catch (Exception ex)
				{
					if (_ecf.VerificarDocumentoAberto() == EcfTipo.Documento.RelatorioGerencial)
					{
						FecharRelatorioGerencial();
					}
					ex.ShowLastException();
				}
			}
		}

		public override void ImprimirRelatorioGerencialParcelamento()
		{
			if (Parcelamento.IsNull() || !Parcelamento.Any() || !DadosSistema.ConfiguracaoDto.Saida.ImprimirCarneVendaPrazo.Valor)
			{
				return;
			}
			try
			{
				AbrirRelatorioGerencial(Otus.Modulo.PontoDeVendas.Enums.RelatoriosGerenciais.Parcelamento);
				List<string> list = new List<string>();
				foreach (IDadoEmissor item in Parcelamento)
				{
					if (item.Is<TextoEmissor>())
					{
						list.Add(item.Informacao);
					}
					else if (item.Is<LinhaEmBrancoEcfEmissor>())
					{
						list.Add(item.Informacao);
						_ecf.ImprimirRelatorioGerencial(list);
						list.Clear();
					}
					else
					{
						_ecf.ImprimirRelatorioGerencial(list);
						_ecf.ImprimirCodigoBarras(item.Informacao);
						list.Clear();
					}
				}
				if (list.Any())
				{
					_ecf.ImprimirRelatorioGerencial(list);
				}
				FecharRelatorioGerencial();
			}
			catch (Exception ex)
			{
				if (_ecf.VerificarDocumentoAberto() == EcfTipo.Documento.RelatorioGerencial)
				{
					FecharRelatorioGerencial();
				}
				ex.ShowLastException();
			}
		}

