		private void AbrirRelatorioGerencial(RelatoriosGerenciais relatorio)
		{
			string descricao = relatorio.RetornarDescricao();
			IEcfRelatorioGerencial ecfRelatorioGerencial = _ecf.RelatoriosGerenciais.FirstOrDefault((IEcfRelatorioGerencial r) => !string.IsNullOrEmpty(r.Descricao) && descricao.ToLower().StartsWith(r.Descricao.ToLower()));
			if (ecfRelatorioGerencial == null)
			{
				throw new Exception($"Relatório gerencial '{descricao}' não cadastrado!");
			}
			_ecf.AbrirRelatorioGerencial(ecfRelatorioGerencial.Id.ToInt());
			_relatorioGerencialEmImpressao = relatorio;
		}

