		private void AbrirComprovanteCreditoDebito(decimal valor, string indiceEspeciePagamentoEcf)
		{
			IEcfEspeciePagamento ecfEspeciePagamento = _ecf.EspeciesPagamento.Where((IEcfEspeciePagamento especie) => especie.PermiteVinculado).ToArray()[indiceEspeciePagamentoEcf.ToInt()];
			if (ecfEspeciePagamento == null)
			{
				throw new Exception("Espécie de pagamento inválida");
			}
			_ecf.AbrirComprovanteCreditoDebito(new EcfComprovanteCreditoDebito
			{
				Documento = _ecf.Coo,
				NumeroParcelas = 1,
				EspeciePagamento = new EcfEspeciePagamento
				{
					Id = ecfEspeciePagamento.Id,
					Descricao = ecfEspeciePagamento.Descricao,
					Indice = ecfEspeciePagamento.Indice,
					PermiteVinculado = ecfEspeciePagamento.PermiteVinculado,
					Valor = valor
				}
			});
		}

