		public EmissorNaoFiscalService(IImpressoraNaoFiscalService impressoraNaoFiscalService, IWService service, Otus.Modulo.PontoDeVendas.Interfaces.IShipayService shipayService, IRepositoryRead<DigisatServer.Domain.Main.Aggregates.CadastrosAgg.Pessoas.Pessoa> pessoaRepositoryRead, Otus.Modulo.PontoDeVendas.Interfaces.ITefService tefService)
			: base(service, shipayService, tefService)
		{
			_impressoraNaoFiscalService = impressoraNaoFiscalService;
			_service = service;
			_pessoaRepositoryRead = pessoaRepositoryRead;
			_geradorImpressoTurnoService = new GeradorImpressoTurnoService(DadosSistema.TamanhoBobina == TamanhoBobina.CinquentaESeisCinquentaESeteCinquentaEOitoMilimetros);
		}

