		public override void ImprimirRelatorioGerencialParcelamento()
		{
			if (DadosRelatorioCarne == null)
			{
				return;
			}
			if (DadosSistema.TamanhoBobina == TamanhoBobina.CinquentaESeisCinquentaESeteCinquentaEOitoMilimetros)
			{
				if (DadosSistema.ConfiguracaoDto.Saida.ImprimirViaEstabelecimentoCarneVendaPrazo.Valor)
				{
					ParcelamentoViaEstabelecimento56Mm57Mm58Mm relatorio = new ParcelamentoViaEstabelecimento56Mm57Mm58Mm(DadosSistema.RollPaper, DadosSistema.MargemEsquerdaImpressoraNaoFiscal)
					{
						Parametros = new Parametros
						{
							Objeto = DadosRelatorioCarne
						}
					};
					_impressoraNaoFiscalService.Imprimir((IRelatorio)relatorio);
				}
				if (DadosSistema.ConfiguracaoDto.Saida.ImprimirCarneVendaPrazo.Valor)
				{
					ParcelamentoViaCliente56Mm57Mm58Mm relatorio2 = new ParcelamentoViaCliente56Mm57Mm58Mm(DadosSistema.RollPaper, DadosSistema.MargemEsquerdaImpressoraNaoFiscal)
					{
						Parametros = new Parametros
						{
							Objeto = DadosRelatorioCarne
						}
					};
					_impressoraNaoFiscalService.Imprimir((IRelatorio)relatorio2);
				}
			}
			else
			{
				if (DadosSistema.ConfiguracaoDto.Saida.ImprimirViaEstabelecimentoCarneVendaPrazo.Valor)
				{
					ParcelamentoViaEstabelecimento79Mm80Mm relatorio3 = new ParcelamentoViaEstabelecimento79Mm80Mm(DadosSistema.RollPaper, DadosSistema.MargemEsquerdaImpressoraNaoFiscal)
					{
						Parametros = new Parametros
						{
							Objeto = DadosRelatorioCarne
						}
					};
					_impressoraNaoFiscalService.Imprimir((IRelatorio)relatorio3);
				}
				if (DadosSistema.ConfiguracaoDto.Saida.ImprimirCarneVendaPrazo.Valor)
				{
					ParcelamentoViaCliente79Mm80Mm relatorio4 = new ParcelamentoViaCliente79Mm80Mm(DadosSistema.RollPaper, DadosSistema.MargemEsquerdaImpressoraNaoFiscal)
					{
						Parametros = new Parametros
						{
							Objeto = DadosRelatorioCarne
						}
					};
					_impressoraNaoFiscalService.Imprimir((IRelatorio)relatorio4);
				}
			}
		}

