		public override void ImprimirRelatorioGerencialEncerrantes()
		{
			IEnumerable<string> collection = _service.Canal((IPostoCombustivelModuleService x) => x.ObterRelatorioEncerrantes());
			List<string> list = new List<string>();
			int totalWidth = ((DadosSistema.TamanhoBobina == TamanhoBobina.CinquentaESeisCinquentaESeteCinquentaEOitoMilimetros) ? 32 : 40);
			list.Add(DadosSistema.EmpresaLogada.Nome);
			list.Add(DadosSistema.EmpresaLogada.CpfCnpjFormatado);
			list.Add("".PadRight(totalWidth, '='));
			list.AddRange(collection);
			list.Add("".PadRight(totalWidth, '='));
			list.Add($"Gerado em {DateTime.Now:dd/MM/yyyy HH:mm}");
			_impressoraNaoFiscalService.Imprimir(list);
		}

		public override void ImprimirRelatorioEncerrantesPorPeriodo(DateTime dataHoraInicial, DateTime dataHoraFinal)
		{
			IEnumerable<string> collection = _service.Canal((IPostoCombustivelModuleService x) => x.ObterRelatorioEncerrantesPorPeriodo(dataHoraInicial, dataHoraFinal));
			List<string> list = new List<string>();
			int totalWidth = ((DadosSistema.TamanhoBobina == TamanhoBobina.CinquentaESeisCinquentaESeteCinquentaEOitoMilimetros) ? 32 : 40);
			list.Add(DadosSistema.EmpresaLogada.Nome);
			list.Add(DadosSistema.EmpresaLogada.CpfCnpjFormatado);
			list.Add("".PadRight(totalWidth, '='));
			list.Add("Período informado:");
			list.Add($"De {dataHoraInicial:dd/MM/yyyy HH:mm}");
			list.Add($"Até {dataHoraFinal:dd/MM/yyyy HH:mm}");
			list.Add("".PadRight(totalWidth, '='));
			list.AddRange(collection);
			list.Add("".PadRight(totalWidth, '='));
			list.Add($"Gerado em {DateTime.Now:dd/MM/yyyy HH:mm}");
			_impressoraNaoFiscalService.Imprimir(list);
		}

