		public void AdicionarRelatorioGerencialTerminalPos(IEnumerable<string> linhas)
		{
			List<string> list = linhas.SelectMany((string linha) => linha.Split('\n')).ToList();
			if (ImpressoTerminalPos.IsNull() || !ImpressoTerminalPos.Any())
			{
				ImpressoTerminalPos = new List<string>(list);
				return;
			}
			ImpressoTerminalPos.Add(string.Empty);
			ImpressoTerminalPos.Add(string.Empty);
			ImpressoTerminalPos.Add(ComandoCortar);
			foreach (string item in list)
			{
				ImpressoTerminalPos.Add(item);
			}
		}

