		public void EstornarPagamentosDigitais(IEnumerable<string> pagamentosIds)
		{
			if (pagamentosIds.IsNull() || !pagamentosIds.Any() || (!DadosSistema.UtilizarShipayDePagar && ConfiguracaoShipay.Carregar() == null))
			{
				return;
			}
			foreach (string pagamentoId in DadosSistema.UtilizarShipayDePagar ? pagamentosIds.Where(IdCobrancaDePagarValido) : pagamentosIds)
			{
				_shipayService.EstornarPagamento(pagamentoId).ContinueWith((Task task) =>
				{
					if (task.IsFaulted)
					{
						ThreadPrincipal.Executar(() =>
						{
							DialogoFactory.MostrarDialogoConfirma($"Ocorreu um erro ao solicitar o estorno do pagamento {pagamentoId}: {task.Exception.GetLastException().Message}");
						});
					}
					else
					{
						ThreadPrincipal.Executar(() =>
						{
							DialogoFactory.MostrarDialogoConfirma("Pagamento digital cancelado com sucesso.");
						});
					}
				});
			}
		}

		private static bool IdCobrancaDePagarValido(string id)
		{
			Guid result;
			return Guid.TryParse(id, out result);
		}

