		public void CancelarTransacaoTef(IEnumerable<InformacaoTransacao> informacoesTransacoes)
		{
			try
			{
				ThreadPrincipal.Executar(() =>
				{
					LoaderProcessoService.MostrarLoader("Cancelando transações do TEF...");
				});
				if (!informacoesTransacoes.IsNotNull() || !informacoesTransacoes.Any() || informacoesTransacoes.All((InformacaoTransacao x) => x.Nsu.IsNullOrEmpty()))
				{
					return;
				}
				foreach (InformacaoTransacao informacoesTransaco in informacoesTransacoes)
				{
					DialogoFactory.MostrarDialogoConfirma((!_tefService.Cnc(informacoesTransaco.Rede, informacoesTransaco.Nsu, DateTime.Today, informacoesTransaco.Valor, forcarCancelamento: true)) ? "Não foi possível cancelar a transação de TEF." : "Transação de TEF cancelada com sucesso.");
				}
			}
			finally
			{
				ThreadPrincipal.Executar(LoaderProcessoService.EsconderLoader);
			}
		}
	}
