	public class FarmaciaService : IFarmaciaService
	{
		private readonly IRepositoryWrite<DigisatServer.Domain.Main.Aggregates.AuxiliaresAgg.Pbms.TransacaoPbm> _transacaoPbmRepositoryWrite;

		private int _numeroSequencial;

		public FarmaciaService(IRepositoryWrite<DigisatServer.Domain.Main.Aggregates.AuxiliaresAgg.Pbms.TransacaoPbm> transacaoPbmRepositoryWrite)
		{
			_transacaoPbmRepositoryWrite = transacaoPbmRepositoryWrite;
		}

		private int ObterNumeroSequencial()
		{
			if (_numeroSequencial == 9999)
			{
				_numeroSequencial = 0;
			}
			return ++_numeroSequencial;
		}

		public void TestarAtividade(TipoPbm pbm)
		{
			FluentFactory<PbmFactory>.Init().SetarPbm(pbm).SetarNumeroSequencial(ObterNumeroSequencial())
				.SetarConfiguracaoFarmacia(DadosSistema.ObterConfiguracaoFarmacia())
				.Criar()
				.TestarAtividade();
		}

		public IRetornoConsulta Consultar(string numeroAutorizacao, bool numeroCartaoPortalDrogaria, string operadora, string cnpjEstabelecimento, int numeroPdv, string dadosComplementares, int indicadorContinuacao, TipoPbm pbm)
		{
			IRetornoConsulta retornoConsulta = FluentFactory<PbmFactory>.Init().SetarPbm(pbm).SetarNumeroSequencial(ObterNumeroSequencial())
				.SetarConfiguracaoFarmacia(DadosSistema.ObterConfiguracaoFarmacia())
				.Criar()
				.Consultar(numeroAutorizacao, numeroCartaoPortalDrogaria, operadora, cnpjEstabelecimento, numeroPdv, dadosComplementares, indicadorContinuacao);
			if (retornoConsulta.Status == DigisatServer.Infrastructure.Crosscutting.Farmacia.Pbms.Status.Erro)
			{
				throw new Exception(retornoConsulta.MensagemRetorno);
			}
			if (retornoConsulta.Status == DigisatServer.Infrastructure.Crosscutting.Farmacia.Pbms.Status.Ok && !retornoConsulta.ProdutosAutorizados.Any())
			{
				throw new Exception("Autorização não possui produtos autorizados.");
			}
			return retornoConsulta;
		}

		public RetornoProdutosAutorizadosComprovante EfetivarTransacao(bool numeroCartaoPortalDrogaria, string operadora, string cnpjEstabelecimento, int numeroPdv, string dadosComplementares, int indicadorContinuacao, PreDocumentoFiscal preDocumentoFiscal, long numeroDocumento)
		{
			if (preDocumentoFiscal.IsNull() || preDocumentoFiscal.RetornoConsultaPbm.TipoPbm != TipoPbm.PortalDrogaria)
			{
				return null;
			}
			TestarAtividade(preDocumentoFiscal.RetornoConsultaPbm.TipoPbm);
			IRetornoVenda retornoVenda = FluentFactory<PbmFactory>.Init().SetarPbm(preDocumentoFiscal.RetornoConsultaPbm.TipoPbm).SetarNumeroSequencial(ObterNumeroSequencial())
				.SetarConfiguracaoFarmacia(DadosSistema.ObterConfiguracaoFarmacia())
				.Criar()
				.EfetivarTransacao(produtosVendidos: ObterItens(preDocumentoFiscal), numeroAutorizacao: preDocumentoFiscal.RetornoConsultaPbm.NumeroAutorizacao, numeroCartaoPortalDrogaria: numeroCartaoPortalDrogaria, operadora: operadora, cnpjEstabelecimento: cnpjEstabelecimento, numeroPdv: numeroPdv, dadosComplementares: dadosComplementares, indicadorContinuacao: indicadorContinuacao, numeroDocumentoFiscal: preDocumentoFiscal.Numero);
			if (retornoVenda.Status == DigisatServer.Infrastructure.Crosscutting.Farmacia.Pbms.Status.Erro)
			{
				throw new Exception(retornoVenda.MensagemRetorno);
			}
			return new RetornoProdutosAutorizadosComprovante(retornoVenda.ReciboImpressao, retornoVenda.ProdutosAutorizados);
		}

		public IEnumerable<IProdutoVendido> ObterItens(PreDocumentoFiscal preDocumentoFiscal)
		{
			List<IProdutoVendido> list = new List<IProdutoVendido>();
			List<IProdutoVendido> list2 = (from x in preDocumentoFiscal.Itens.OfType<ItemDocumentoFiscalPbm>()
				where x.Ativo
				select x.ObterProdutoVendido(preDocumentoFiscal.RetornoConsultaPbm.TipoPbm)).ToListEmptyWhenNull();
			if (preDocumentoFiscal.RetornoConsultaPbm.TipoPbm == TipoPbm.PortalDrogaria)
			{
				foreach (IProdutoVendido produtoVendido in list2)
				{
					Otus.Modulo.PontoDeVendas.ViewModels.ItemDocumentoFiscal itemDocumentoFiscal = preDocumentoFiscal.Itens.First((Otus.Modulo.PontoDeVendas.ViewModels.ItemDocumentoFiscal x) => x.ProdutoServicoLocal.Barras.Equals(produtoVendido.To<ProdutoVendidoPortalDrogaria>().CodigoBarras));
					if (itemDocumentoFiscal.PrecoUnitario < produtoVendido.To<ProdutoVendidoPortalDrogaria>().PrecoLiquido)
					{
						produtoVendido.To<ProdutoVendidoPortalDrogaria>().PrecoLiquido = itemDocumentoFiscal.PrecoUnitario;
					}
				}
			}
			list.AddRange(list2);
			if (preDocumentoFiscal.RetornoConsultaPbm.TipoPbm == TipoPbm.PortalDrogaria && preDocumentoFiscal.Itens.Where((Otus.Modulo.PontoDeVendas.ViewModels.ItemDocumentoFiscal x) => !(x is ItemDocumentoFiscalPbm) && x.Ativo).ToListEmptyWhenNull().Any())
			{
				List<Otus.Modulo.PontoDeVendas.ViewModels.ItemDocumentoFiscal> source = preDocumentoFiscal.Itens.Where((Otus.Modulo.PontoDeVendas.ViewModels.ItemDocumentoFiscal x) => !(x is ItemDocumentoFiscalPbm) && x.Ativo).ToListEmptyWhenNull();
				List<ProdutoVendidoPortalDrogaria> list3 = new List<ProdutoVendidoPortalDrogaria>();
				list3.AddRange(source.Select((Otus.Modulo.PontoDeVendas.ViewModels.ItemDocumentoFiscal x) => new ProdutoVendidoPortalDrogaria(x.ProdutoServicoLocal.Barras, x.ProdutoServicoLocal.Quantidade.ToInt(), x.ProdutoServicoLocal.Preco, x.ProdutoServicoLocal.Preco, x.NumeroItem)));
				list.AddRange(list3);
			}
			return list;
		}

		public void AnularVendaPortalDrogaria(string operadora, string numeroAutorizacao, int numeroPdv)
		{
			TestarAtividade(TipoPbm.PortalDrogaria);
			IRetornoVenda retornoVenda = FluentFactory<PbmFactory>.Init().SetarPbm(TipoPbm.PortalDrogaria).SetarNumeroSequencial(ObterNumeroSequencial())
				.SetarConfiguracaoFarmacia(DadosSistema.ObterConfiguracaoFarmacia())
				.Criar()
				.AnularVenda(operadora, numeroAutorizacao, DadosSistema.EmpresaLogada.CpfCnpj, numeroPdv);
			if (retornoVenda.Status == DigisatServer.Infrastructure.Crosscutting.Farmacia.Pbms.Status.Erro)
			{
				throw new Exception(retornoVenda.MensagemRetorno);
			}
		}

		public void AnularVenda(PreDocumentoFiscal preDocumentoFiscal, int numeroPdv)
		{
			if (!preDocumentoFiscal.IsNull() && preDocumentoFiscal.RetornoConsultaPbm.TipoPbm == TipoPbm.PortalDrogaria)
			{
				TestarAtividade(preDocumentoFiscal.RetornoConsultaPbm.TipoPbm);
				IRetornoVenda retornoVenda = FluentFactory<PbmFactory>.Init().SetarPbm(preDocumentoFiscal.RetornoConsultaPbm.TipoPbm).SetarNumeroSequencial(ObterNumeroSequencial())
					.SetarConfiguracaoFarmacia(DadosSistema.ObterConfiguracaoFarmacia())
					.Criar()
					.AnularVenda(preDocumentoFiscal.RetornoConsultaPbm.Operadora, preDocumentoFiscal.RetornoConsultaPbm.NumeroAutorizacao, preDocumentoFiscal.RetornoConsultaPbm.CnpjEstabelecimento, numeroPdv);
				string text = retornoVenda.MensagemRetorno.ToLower();
				if (retornoVenda.Status == DigisatServer.Infrastructure.Crosscutting.Farmacia.Pbms.Status.Erro && !text.Contains("autorizacao invalido") && !text.Contains("nao encontrada") && !text.Contains("transacao expirada"))
				{
					throw new Exception(retornoVenda.MensagemRetorno);
				}
			}
		}

		public void ConfirmarTransacao(PreDocumentoFiscal preDocumentoFiscal, int numeroPdv, long numeroDocumento)
		{
			if (!preDocumentoFiscal.IsNull() && preDocumentoFiscal.RetornoConsultaPbm.TipoPbm == TipoPbm.PortalDrogaria)
			{
				TestarAtividade(preDocumentoFiscal.RetornoConsultaPbm.TipoPbm);
				FluentFactory<PbmFactory>.Init().SetarPbm(preDocumentoFiscal.RetornoConsultaPbm.TipoPbm).SetarNumeroSequencial(ObterNumeroSequencial())
					.SetarConfiguracaoFarmacia(DadosSistema.ObterConfiguracaoFarmacia())
					.Criar()
					.ConfirmacaoTransacao(preDocumentoFiscal.RetornoConsultaPbm.Operadora, preDocumentoFiscal.RetornoConsultaPbm.NumeroAutorizacao, preDocumentoFiscal.RetornoConsultaPbm.CnpjEstabelecimento, numeroPdv);
				SalvarTransacaoPbm(preDocumentoFiscal, preDocumentoFiscal.RetornoConsultaPbm.CnpjConvenio, preDocumentoFiscal.RetornoConsultaPbm.NumeroAutorizacao, numeroDocumento);
			}
		}

		public IEnumerable<string> ConfirmarVenda(PreDocumentoFiscal preDocumentoFiscal, long numeroDocumento, string numeroCartao, string operadora, string cnpjEstabelecimento, string dadosComplementares)
		{
			TestarAtividade(preDocumentoFiscal.RetornoConsultaPbm.TipoPbm);
			preDocumentoFiscal.AtualizarDadosEmissor();
			IRetornoVenda retornoVenda = FluentFactory<PbmFactory>.Init().SetarPbm(preDocumentoFiscal.RetornoConsultaPbm.TipoPbm).SetarNumeroSequencial(ObterNumeroSequencial())
				.SetarConfiguracaoFarmacia(DadosSistema.ObterConfiguracaoFarmacia())
				.Criar()
				.Vender(produtosVendidos: (from x in preDocumentoFiscal.Itens.OfType<ItemDocumentoFiscalPbm>()
					where x.Ativo
					select x.ObterProdutoVendido(preDocumentoFiscal.RetornoConsultaPbm.TipoPbm)).ToListEmptyWhenNull(), numeroAutorizacao: preDocumentoFiscal.RetornoConsultaPbm.NumeroAutorizacao, numeroEcf: preDocumentoFiscal.NumeroSequencialEcf, serie: preDocumentoFiscal.Serie, numeroPdv: DadosSistema.NumeroPdvSat, numeroCupomFiscal: numeroDocumento, chaveAcesso: preDocumentoFiscal.ChaveAcesso.ApenasNumeros(), tipoMovimentacao: preDocumentoFiscal.ObterTipoDocumentoFiscal(), operadora: operadora, cnpjEstabelecimento: cnpjEstabelecimento, dadosComplementares: dadosComplementares, totalDocumentoFiscal: preDocumentoFiscal.Itens.OfType<ItemDocumentoFiscalPbm>().Sum((ItemDocumentoFiscalPbm y) => y.Total), dadosCartaoConvenio: preDocumentoFiscal.DadosCartaoConvenio);
			if (retornoVenda.Status == DigisatServer.Infrastructure.Crosscutting.Farmacia.Pbms.Status.Erro)
			{
				throw new Exception(retornoVenda.MensagemRetorno);
			}
			SalvarTransacaoPbm(preDocumentoFiscal, retornoVenda.CnpjConvenio, retornoVenda.Nsu, numeroDocumento);
			return retornoVenda.ReciboImpressao;
		}

		private void SalvarTransacaoPbm(PreDocumentoFiscal preDocumentoFiscal, string cnpjConvenioRetorno, string nsu, long numeroDocumento)
		{
			string cnpjConvenio = (string.IsNullOrWhiteSpace(preDocumentoFiscal.RetornoConsultaPbm.CnpjConvenio) ? cnpjConvenioRetorno : preDocumentoFiscal.RetornoConsultaPbm.CnpjConvenio);
			DocumentoFiscalPbm documentoFiscalPbm = DocumentoFiscalPbm.Criar().ComChaveAcesso(preDocumentoFiscal.ChaveAcesso).ComNumero(numeroDocumento)
				.ComSerie(preDocumentoFiscal.Serie)
				.ComNumeroFabricacaoEcf(preDocumentoFiscal.NumeroFabricacao)
				.ComNumeroSequencialEcf(preDocumentoFiscal.NumeroSequencialEcf)
				.ComTipoMovimentacao(preDocumentoFiscal.ObterTipoDocumentoFiscal())
				.Build();
			IEnumerable<ProdutoAutorizado> produtosAutorizados = from x in preDocumentoFiscal.Itens.OfType<ItemDocumentoFiscalPbm>()
				select x.ObterProdutoAutorizado();
			DigisatServer.Domain.Main.Aggregates.AuxiliaresAgg.Pbms.TransacaoPbm entity = DigisatServer.Domain.Main.Aggregates.AuxiliaresAgg.Pbms.TransacaoPbm.Criar().ComTipoPbm(preDocumentoFiscal.RetornoConsultaPbm.TipoPbm).ComNumeroAutorizacao(preDocumentoFiscal.RetornoConsultaPbm.NumeroAutorizacao)
				.ComCnpjConvenio(cnpjConvenio)
				.ComNsu(nsu)
				.ComProdutosAutorizados(produtosAutorizados)
				.ComDocumentoFiscal(documentoFiscalPbm)
				.ComEmpresaReferencia(DadosSistema.EmpresaLogada.Id);
			_transacaoPbmRepositoryWrite.Add(entity);
		}

		public string Fechar(TipoPbm tipoPbm)
		{
			TestarAtividade(tipoPbm);
			return FluentFactory<PbmFactory>.Init().SetarPbm(tipoPbm).SetarNumeroSequencial(ObterNumeroSequencial())
				.SetarConfiguracaoFarmacia(DadosSistema.ObterConfiguracaoFarmacia())
				.Criar()
				.Fechar();
		}
	}
	public class RegistrosPafNfceService : IRegistrosPafNfceService
	{
		private readonly IWService _service;

		public RegistrosPafNfceService(IWService service)
		{
			_service = service;
		}

		public void GerarArquivoRegistrosPafNfce(DateTime dataInicial, DateTime dataFinal, IEnumerable<string> ids = null, bool completo = false)
		{
			GeradorArquivoRegistrosPafEcfDto parametros = new GeradorArquivoRegistrosPafEcfDto
			{
				DataInicial = dataInicial,
				DataFinal = dataFinal,
				ProdutoServicoReferencias = ids.ToListEmptyWhenNull(),
				Completo = completo,
				IsPafNfce = true
			};
			string nomeArquivo = $"RegistrosPAF_NFCe_{dataInicial:ddMMyyyy}_{dataFinal:ddMMyyyy}.txt";
			Task<IEnumerable<string>> task = _service.Canal((IGeradorArquivoRegistrosPafEcfModuleService x) => x.ObterLinhasParaGeracaoDoArquivoAsync(parametros));
			string text = Path.Combine(AppDomain.CurrentDomain.BaseDirectory, "Fiscal");
			string path = TxtFile.Criar().ComConteudo(task.Result).ComNomeArquivo(nomeArquivo)
				.ComDiretorioArquivo(text)
				.Build()
				.Gerar();
			string text2 = Path.Combine(text, path);
			Assinaturas.AdicionarAssinaturaPafEcfArquivo(Assinaturas.CalcularAssinaturaPafecfArquivo(Hash.RetornarChavePrivadaInformacaoDecifrada(), text2), text2);
			DialogoFactory.MostrarDialogoConfirma($"Arquivo {text2} gerado com sucesso.");
		}
	}
	public static class RelatorioGerencialRestauranteService
	{
		public static IEnumerable<string> RetornarInformacoesRelatorioGerencialMesasContasAbertas(IEnumerable<MesaContaAbertaDto> mesasContasAbertas)
		{
			if (!mesasContasAbertas.Any())
			{
				return new List<string> { string.Format($"NAO EXISTE {DadosSistema.TipoRestaurante.ToUpper()} ABERTA") };
			}
			IList<string> list = new List<string> { $"{DadosSistema.TipoMesaContaPlural} abertas".ToUpper() };
			list.Add($"{DadosSistema.TipoRestaurante.ToUpper().PadRight(14, ' ')} DATA/HORA        VALOR R$");
			list.Add("".PadRight(40, '-'));
			foreach (MesaContaAbertaDto mesasContasAberta in mesasContasAbertas)
			{
				list.Add(string.Format("{0}{1:dd/MM/yy-HH:mm:ss}{2}", mesasContasAberta.NumeroMesaConta.ToString().PadRight(13, ' '), mesasContasAberta.DataHoraAbertura, mesasContasAberta.Total.ToString("n2").PadLeft(12, ' ')));
			}
			return list;
		}

		public static IEnumerable<string> RetornarInformacoesRelatorioGerencialTransferencias(IEnumerable<ItemMesaContaDto> itens)
		{
			if (!itens.Any())
			{
				return new List<string> { "NAO EXISTEM TRANSFERENCIAS" };
			}
			IList<string> list = new List<string>();
			list.Add("CODIGO       DESCRICAO ");
			list.Add("QTD                    VALOR UNITARIO R$");
			list.Add("".PadRight(40, '-'));
			string arg = DadosSistema.TipoRestaurante.ToUpper();
			foreach (ItemMesaContaDto iten in itens)
			{
				list.Add($"{iten.Codigo.PadRight(13, ' ')} {iten.Descricao.PadRight(26, ' ')}".ToUpper());
				list.Add(string.Format("{0} {1}", iten.Quantidade.ToString("n3").PadRight(10, ' '), iten.ValorUnitario.ToString("n2").PadLeft(29, ' ')));
				if (iten.Cancelado)
				{
					list.Add("CANCELADO");
				}
				list.Add($"{arg} ORIGEM: {iten.NumeroMesaContaOrigem} DESTINO: {iten.NumeroMesaConta}");
				list.Add("".PadRight(40, '-'));
			}
			return list;
		}
	}
	public class MFePontoVendaService : CFeService, IMFePontoVendaService, ICFeService, IEmissorService
	{
		private IActorRef _satClientActor;

		private readonly IEventPublisher _eventPublisher;

		private readonly IClientActorSystem _actorSystem;

		private ConfiguracaoMFe _configuracaoMFe;

		private readonly IBoletoProxyService _boletoProxyService;

		public MFePontoVendaService(IImpressoraNaoFiscalService impressoraNaoFiscalService, ISessaoService sessaoService, IEventPublisher eventPublisher, IWService service, IConfiguracaoClientService configuracaoClientService, IRepositoryRead<Movimentacao> movimentacaoRepositoryRead, IRepositoryWrite<Movimentacao> movimentacaoRepositoryWrite, INotificacao notificacao, IClientActorSystem actorSystem, Otus.Modulo.PontoDeVendas.Interfaces.IShipayService shipayService, IRepositoryRead<DigisatServer.Domain.Main.Aggregates.CadastrosAgg.Pessoas.Pessoa> pessoaRepositoryRead, IRepositoryBaseWrite<ValorSangriaLocal> valorSangriaRepositoryWrite, IRepositoryRead<ValorSangriaLocal> valorSangriaRepositoryRead, IFarmaciaService farmaciaService, Otus.Modulo.PontoDeVendas.Interfaces.ITefService tefService, IBoletoProxyService boletoProxyService)
			: base(impressoraNaoFiscalService, sessaoService, service, configuracaoClientService, movimentacaoRepositoryRead, movimentacaoRepositoryWrite, notificacao, shipayService, pessoaRepositoryRead, valorSangriaRepositoryWrite, valorSangriaRepositoryRead, farmaciaService, tefService)
		{
			_eventPublisher = eventPublisher;
			_actorSystem = actorSystem;
			_boletoProxyService = boletoProxyService;
			eventPublisher.GetEvent((ConfiguracaoMFe configuracaoMfe) =>
			{
				_configuracaoMFe = configuracaoMfe;
				InicializarEmissor();
			});
			_configuracaoMFe = ConfiguracaoClientService.ObterConfiguracao().Mfe;
			AssinarEventosDoAtor();
		}

		private void AssinarEventosDoAtor()
		{
			_eventPublisher.GetEvent<ConnectResponse>().Subscribe((ConnectResponse x) =>
			{
				_satClientActor.Tell(new ConsultarStatusRequest());
			});
			_eventPublisher.GetEvent<ConsultarStatusResponse>().Subscribe((ConsultarStatusResponse x) =>
			{
				InicializarEmissor();
				OnEmissorProntoEvent();
				OnAlterouEstadoJornadaFiscalEvent(e: true);
			});
			_eventPublisher.GetEvent<ErroCFeResponse>().Subscribe((ErroCFeResponse x) =>
			{
				OnErroAoTransmitirDocumentoFiscalEvent(x.Mensagem);
			});
			_eventPublisher.GetEvent<FalhaCFeResponse>().Subscribe((FalhaCFeResponse x) =>
			{
				OnFalhaAoTransmitirDocumentoFiscalEvent(new FalhaAoTransmitirDocumentoFiscalEventArgs(x.Codigo, x.Mensagem));
				OnDocumentoFiscalAbertoEvent();
			});
			_eventPublisher.GetEvent<ErroCFeCancResponse>().Subscribe((ErroCFeCancResponse x) =>
			{
				DialogoFactory.MostrarDialogoConfirma(x.Mensagem);
			});
			_eventPublisher.GetEvent<EnviarDadosVendaResponse>().Subscribe((EnviarDadosVendaResponse x) =>
			{
				UltimoCfeDto = x.CFe;
				try
				{
					Imprimir(x.CFe);
				}
				finally
				{
					CfeDto = null;
					OnEmissorTerminouDocumentoFiscalEvent(UltimoCfeDto.NumeroExtrato);
				}
				if (!string.IsNullOrEmpty(x.CFe.DocumentoCliente))
				{
					Task.Factory.StartNew(() => EnviarEmailCupomFiscalEletronico(x.CFe));
				}
			});
			_eventPublisher.GetEvent<CancelarUltimaVendaResponse>().Subscribe((CancelarUltimaVendaResponse response) =>
			{
				UltimoCfeDto = null;
				try
				{
					Imprimir(response.CFeCanc.ChaveAcessoCfeCancelado);
					Imprimir(response.CFeCanc);
					Cancelar(response.CFeCanc, response.UsuarioAutorizouCancelamento);
				}
				catch
				{
				}
			});
		}

		private void Imprimir(string chaveAcesso)
		{
			MovimentacaoRepositoryRead.FindOne(MovimentacaoSpecification.PorTipo<DigisatServer.Domain.Main.Aggregates.MovimentacoesAgg.Saidas.CupomFiscalEletronico>().PorChaveAcesso(chaveAcesso)).ToDo((DigisatServer.Domain.Main.Aggregates.MovimentacoesAgg.Saidas.CupomFiscalEletronico cfe) =>
			{
				Imprimir(cfe.XmlTexto.ProjectedAsCFeDto());
			});
		}

		public override void Finalizar(IEnumerable<IMensagemPromocional> mensagemPromocional)
		{
			OnEmissorAvisoEvent("Enviando dados da venda. Aguarde...");
			base.Finalizar(mensagemPromocional);
			_satClientActor.Tell(new EnviarDadosVendaRequest(CfeDto, isMfe: true));
		}

		public void Inicializar()
		{
			if (_configuracaoMFe.IsNull() || !_configuracaoMFe.MfeConfigurado)
			{
				OnEmissorEmErroEvent("MFE não configurado! Acesse Auxiliares/Configurações/Periférico/Emissor de MFE.");
			}
			if (_satClientActor.IsNull())
			{
				_satClientActor = _actorSystem.Criar<MfeClientActor>();
			}
			else
			{
				_satClientActor.Tell(new ConsultarStatusRequest());
			}
		}

		public void SetarUltimoCfeDto(CFeDto cFeDto)
		{
		}

		protected override int ObterNumeroCaixa()
		{
			return ConfiguracaoClientService.ObterConfiguracao().Mfe.NumeroPdv;
		}

		protected override void CancelarVenda(string chaveAcesso, Autorizacao autorizacao)
		{
			base.CancelarVenda(chaveAcesso, autorizacao);
			_satClientActor.Tell(new CancelarUltimaVendaRequest(ObterCFeCancDto(chaveAcesso), autorizacao.NomeUsuario));
		}

		public override void EfetivouPreDocumentoFiscal(Movimentacao movimentacao)
		{
			MovimentacaoDto dto = movimentacao.ProjectedAsDto();
			ImprimirTicketTroca(dto);
			ImprimirValoresCliente(dto);
			ThreadPrincipal.Executar(() =>
			{
				ImpressaoBoletoService.Init().ComBoletoProxyService(_boletoProxyService).VerificarImpressaoBoletos(dto);
			});
		}

		public void LimparUltimoDocumentoEmitido()
		{
			UltimoCfeDto = null;
		}

		public override void InicializarEmissor()
		{
			if (_configuracaoMFe.IsNull() || !_configuracaoMFe.MfeConfigurado)
			{
				OnEmissorEmErroEvent("MFE não configurado! Acesse Auxiliares/Configurações/Periférico/Emissor de MFE.");
			}
			base.InicializarEmissor();
		}
	}
	public class MovimentacaoJsonService
	{
		private static string DiretorioExe => Path.GetDirectoryName(Process.GetCurrentProcess().MainModule.FileName);

		private static string DiretorioArquivos => Path.Combine(DiretorioExe, "Backup", "Json");

		public static void CriarJson(Movimentacao movimentacao)
		{
			try
			{
				string text = Path.Combine(DiretorioArquivos, movimentacao.Tipo.ToString(), movimentacao.DataHoraEmissao.ToString("MMyyyy"));
				if (!Directory.Exists(text))
				{
					Directory.CreateDirectory(text);
				}
				string path = $"{movimentacao.Tipo}_{movimentacao.Numero}_{DateTime.Now:yy-MM-dd_HH-mm}.txt";
				string text2 = Path.Combine(text, path);
				string contents = movimentacao.ToJson();
				File.WriteAllText(text2, contents);
				using (ZipFile zipFile = new ZipFile())
				{
					zipFile.CompressionLevel = CompressionLevel.BestCompression;
					zipFile.AddFile(text2, "");
					zipFile.Save(text2.Replace(".txt", ".zip"));
				}
				File.Delete(text2);
			}
			catch (Exception)
			{
			}
		}
	}
	public class PreDocumentoFiscalLogService
	{
		private static string DiretorioExe => Path.GetDirectoryName(Process.GetCurrentProcess().MainModule.FileName);

		private static string DiretorioLog => Path.Combine(DiretorioExe, "Log", "PreDocumentoFiscal");

		public static void CriarLog(string mensagem, bool erro)
		{
			try
			{
				string text = Path.Combine(DiretorioLog, DateTime.Now.ToString("yyyy"), DateTime.Now.ToString("MM"));
				if (!Directory.Exists(text))
				{
					Directory.CreateDirectory(text);
				}
				string path = $"{DateTime.Now:dd}_log.txt";
				string path2 = Path.Combine(text, path);
				string text2 = $"{DateTime.Now:dd/MM/yyyy HH:mm}";
				text2 = ((!erro) ? (text2 + " - INFO") : (text2 + " - ERRO"));
				text2 += $" - {mensagem}\r\n";
				File.AppendAllText(path2, text2);
			}
			catch (Exception)
			{
			}
		}
	}
