		public override void EmitirDocumentoFiscalAbastecimentosFechamentoTurno(Action voltarAction, Action verificarPendenciasAction, IAbastecimento[] abastecimentosPendentes)
		{
			if (DialogoFactory.MostrarDialogoSimNao("Faturar os abastecimentos pendentes antes de efetuar o fechamento do turno?") == MessageBoxResult.Yes)
			{
				voltarAction?.Invoke();
				EmitirDocumentoFiscalAbastecimentos(abastecimentosPendentes);
			}
			else
			{
				verificarPendenciasAction?.Invoke();
			}
		}

		public override void EmitirDocumentoFiscalAbastecimentos(params IAbastecimento[] abastecimentosPendentes)
		{
			DigisatServer.Domain.Main.Aggregates.CadastrosAgg.Pessoas.Pessoa byId = _pessoaRepositoryRead.GetById(ObjectId.Parse(_sessaoService.Sessao.Perfis.ItemSelecionado.Empresa.Id));
			List<Otus.Modulo.PontoDeVendas.ViewModels.ItemDocumentoFiscal> list = new List<Otus.Modulo.PontoDeVendas.ViewModels.ItemDocumentoFiscal>();
			foreach (IAbastecimento item2 in abastecimentosPendentes.ToListEmptyWhenNull())
			{
				ProdutoServicoEmpresa produtoServicoEmpresa = _produtoServicoEmpresaRepositoryRead.FindOne(EntityBaseSpecification<ProdutoServicoEmpresa>.PorId(item2.IdProduto));
				ItemDocumentoFiscalCombustivel item = FluentFactory<Otus.Modulo.PontoDeVendas.ViewModels.ItemDocumentoFiscalFactory>.Init().ComProdutoServicoLocal(FluentFactory<ProdutoServicoLocalFactory>.Init().ComProdutoServicoEmpresa(produtoServicoEmpresa).Criar()).ComAbastecimento(item2)
					.Criar() as ItemDocumentoFiscalCombustivel;
				list.Add(item);
			}
			PreDocumentoFiscal preDocumentoFiscal = PreDocumentoFiscal.Criar(_preDocumentoFiscalRepositoryWrite, _movimentacaoRepositoryWrite, _operacaoFiscalRepositoryRead, _promocaoScanntechRepositoryRead, this, _sessaoService, new List<Otus.Modulo.PontoDeVendas.ViewModels.ItemDocumentoFiscal>(), byId);
			preDocumentoFiscal.AdicionarItens(list);
			DinheiroViewModel dinheiroViewModel = DinheiroViewModel.Criar();
			dinheiroViewModel.SomarValor(preDocumentoFiscal.Total);
			preDocumentoFiscal.SetarPagamentos(0m, dinheiroViewModel);
			preDocumentoFiscal.SetarObservacao(string.Empty);
			preDocumentoFiscal.Efetivar(Tipo);
			_service.Canal((IPostoCombustivelModuleService x) =>
			{
				x.AtualizarStatusAbastecimentosEmitidoNotaFiscal(abastecimentosPendentes.Select((IAbastecimento a) => a.Id), 0L);
			});
			_eventPublisher.Publish(new RemoverAbastecimentosRequest(abastecimentosPendentes));
		}

		public override void EmitirDocumentoFiscalItemFinanceiro(decimal valor, bool finalizadoEmCarteiraDigital, bool finalizadoEmCarteiraDigitalTef, bool finalizadoEmTerminalPos, InformacaoTransacaoCarteiraDigital informacaoTransacaoCarteiraDigital, InformacaoTransacaoTef informacaoTransacaoTef, PagamentoTransacaoDto pagamentoTransacao)
		{
			DigisatServer.Domain.Main.Aggregates.CadastrosAgg.Pessoas.Pessoa byId = _pessoaRepositoryRead.GetById(ObjectId.Parse(_sessaoService.Sessao.Perfis.ItemSelecionado.Empresa.Id));
			bool? flag;
			if (byId == null)
			{
				flag = null;
			}
			else
			{
				DigisatServer.Domain.Main.Aggregates.CadastrosAgg.Pessoas.Carteiras.Carteira carteira = byId.Carteira;
				if (carteira == null)
				{
					flag = null;
				}
				else
				{
					DigisatServer.Domain.Main.Aggregates.CadastrosAgg.Pessoas.Enderecos.Endereco enderecoPrincipal = carteira.EnderecoPrincipal;
					if (enderecoPrincipal == null)
					{
						flag = null;
					}
					else
					{
						EnderecoNacional enderecoNacional = enderecoPrincipal.To<EnderecoNacional>();
						if (enderecoNacional == null)
						{
							flag = null;
						}
						else
						{
							Municipio municipio = enderecoNacional.Municipio;
							if (municipio == null)
							{
								flag = null;
							}
							else
							{
								UF uf = municipio.Uf;
								flag = ((uf != null) ? new bool?(!uf.DeveGerarDadosPagamentoCarteiraDigitalObservacoesContribuinte()) : ((bool?)null));
							}
						}
					}
				}
			}
			if (!((!flag) ?? true))
			{
				return;
			}
			List<Otus.Modulo.PontoDeVendas.ViewModels.ItemDocumentoFiscal> list = new List<Otus.Modulo.PontoDeVendas.ViewModels.ItemDocumentoFiscal>();
			ProdutoServicoEmpresa produtoServicoEmpresa = _produtoServicoEmpresaRepositoryRead.FindOne(EntityBaseSpecification<ProdutoServicoEmpresa>.PorId("65326c7a660dbd460c135c7d"));
			if (produtoServicoEmpresa.IsNull())
			{
				DialogoFactory.MostrarDialogoConfirma("Cadastro do 'Item financeiro' não localizado. Entre em contato com o Suporte Técnico");
				return;
			}
			produtoServicoEmpresa.ProdutoServico.SetarCodigoInterno("CFOP5949");
			produtoServicoEmpresa.ProdutoServico.SetarDescricao("Pagamento de Prestação");
			ItemDocumentoFiscalProduto itemDocumentoFiscalProduto = FluentFactory<Otus.Modulo.PontoDeVendas.ViewModels.ItemDocumentoFiscalFactory>.Init().ComProdutoServicoLocal(FluentFactory<ProdutoServicoLocalFactory>.Init().ComProdutoServicoEmpresa(produtoServicoEmpresa).Criar()).Criar()
				.To<ItemDocumentoFiscalProduto>()
				.ComEstoque(produtoServicoEmpresa.To<ProdutoEmpresa>().Estoque.Criar(1));
			DigisatServer.Domain.Main.Aggregates.CadastrosAgg.OperacoesFiscal.OperacaoFiscal operacaoFiscal = _operacaoFiscalRepositoryRead.Find(OperacaoFiscalSpecification.PorCfop(5949)).FirstOrDefault();
			itemDocumentoFiscalProduto.ProdutoServicoLocal.SetarOperacaoFiscal(FluentFactory<OperacaoFiscalFactory>.Init().SetarId(operacaoFiscal.Id).SetarCodigoCFOP(operacaoFiscal.Cfop.Codigo)
				.SetarCompoeTotalNota(compoeTotalNota: true)
				.SetarGeraComissao(geraComissao: false)
				.SetarGeraCreditoPisCofins(geraCreditoPisCofins: false)
				.SetarMovimentaEstoque(movimentaEstoque: false)
				.SetarMovimentaFinanceiro(movimentaFinanceiro: false)
				.Criar());
			itemDocumentoFiscalProduto.ComPrecoUnitario(valor);
			list.Add(itemDocumentoFiscalProduto);
			PreDocumentoFiscal preDocumentoFiscal = PreDocumentoFiscal.Criar(_preDocumentoFiscalRepositoryWrite, _movimentacaoRepositoryWrite, _operacaoFiscalRepositoryRead, _promocaoScanntechRepositoryRead, this, _sessaoService, new List<Otus.Modulo.PontoDeVendas.ViewModels.ItemDocumentoFiscal>(), byId);
			preDocumentoFiscal.AdicionarItens(list);
			if (finalizadoEmCarteiraDigital | finalizadoEmCarteiraDigitalTef)
			{
				CarteiraDigitalViewModel carteiraDigitalViewModel = CarteiraDigitalViewModel.Criar().ComEmissorService(this);
				informacaoTransacaoCarteiraDigital.SetarValor(valor);
				carteiraDigitalViewModel.AdicionarCartaoResposta(informacaoTransacaoCarteiraDigital);
				preDocumentoFiscal.SetarPagamentos(0m, carteiraDigitalViewModel);
				if (finalizadoEmCarteiraDigitalTef)
				{
					LimparInformacoesTransacao();
				}
			}
			else if (finalizadoEmTerminalPos)
			{
				TerminalPosViewModel terminalPosViewModel = TerminalPosViewModel.Criar().ComEmissorService(this);
				terminalPosViewModel.AdicionarPagamentoTransacao(pagamentoTransacao);
				preDocumentoFiscal.SetarPagamentos(0m, terminalPosViewModel);
			}
			else
			{
				CartaoViewModel cartaoViewModel = CartaoViewModel.Criar().ComEmissorService(this);
				informacaoTransacaoTef.SetarValor(valor);
				cartaoViewModel.AdicionarCartaoResposta(informacaoTransacaoTef);
				preDocumentoFiscal.SetarPagamentos(0m, cartaoViewModel);
			}
			preDocumentoFiscal.SetarObservacao(string.Empty);
			preDocumentoFiscal.SetarMovimentacaoItemFinanceiro(movimentacaoItemFinanceiro: true);
			preDocumentoFiscal.Efetivar(Tipo);
			ImprimirRelatoriosGerenciaisFinalizacao();
			LimparRelatoriosGerenciais();
			VerificarEstado();
		}

		public virtual void ConsultarStatusServico()
		{
			new Thread(ConsultarStatusServicoInterno).Start();
		}

		private void ConsultarStatusServicoInterno()
		{
			_tipoEmissao = 0;
			try
			{
				OnEmissorAvisoEvent("Verificando conexão com o servidor. Aguarde!");
				LoaderProcessoService.MostrarLoader("Verificando conexão com o servidor. Aguarde!");
				DispatcherHelper.DoEvents();
				_service.Canal((IPdvOfflineModuleService service) => service.VerificarAtivacaoPdvOffline());
				_tipoEmissao = _service.Canal((INotaFiscalConsumidorEletronicaModuleService service) => service.ConsultarStatusServicoTipoDeEmissaoSelecionado());
				ThreadPrincipal.Executar(() =>
				{
					PdvEstadoOffline = false;
					OnEmissorCarregadoEvent();
					OnAlterouTipoEmissao(_tipoEmissao);
					OnEmissorProntoEvent();
					OnAlterouEstadoJornadaFiscalEvent(e: true);
					TransmitirDocumentosEmitidosEmContingencia(_tipoEmissao);
					OnPdvOffline(pdvOffline: false);
				});
			}
			catch (Exception ex)
			{
				Exception ex2 = ex;
				Exception e = ex2;
				ConfiguracaoOffline configuracaoOffline = ConfiguracaoOffline.Carregar();
				if (e.Message.Contains("Off-line") && configuracaoOffline.PdvOfflineValido && DadosSistema.HabilitacaoLocalContemModuloPdvOffline() && DadosSistema.VerificarPermissao<PontoDeVendaOffline, Visualizar>())
				{
					ThreadPrincipal.Executar(() =>
					{
						PdvEstadoOffline = true;
						_tipoEmissao = new EmissaoContingenciaServidorOffline().Codigo;
						OnEmissorCarregadoEvent();
						OnAlterouTipoEmissao(_tipoEmissao);
						OnEmissorProntoEvent();
						OnAlterouEstadoJornadaFiscalEvent(e: true);
						OnPdvOffline(pdvOffline: true);
					});
				}
				else
				{
					ThreadPrincipal.Executar(() =>
					{
						PdvEstadoOffline = false;
						OnEmissorEmErroEvent();
						e.ShowLastException("Falha ao consultar o serviço da NFC-e.");
						LoggerFactory.CreateLog().LogError("Falha ao consultar o serviço da NFC-e.", e);
						OnPdvOffline(pdvOffline: false);
					});
				}
			}
			finally
			{
				LoaderProcessoService.EsconderLoader();
				DispatcherHelper.DoEvents();
			}
		}

		public Task ConsultarStatusServicoAsync()
		{
			TaskCompletionSource<bool> tcs = new TaskCompletionSource<bool>();
			new Thread(() =>
			{
				try
				{
					ConsultarStatusServicoInterno();
					tcs.SetResult(result: true);
				}
				catch (Exception exception)
				{
					tcs.SetException(exception);
				}
			}).Start();
			return tcs.Task;
		}

		private void TransmitirDocumentosEmitidosEmContingencia(int tipoEmissao)
		{
			if (tipoEmissao == 9)
			{
				return;
			}
			Thread thread = new Thread(() =>
			{
				try
				{
					int quantidadeDocumentosEmitidosEmContingencia = _service.Canal((INotaFiscalConsumidorEletronicaModuleService service) => service.QuantidadeDocumentosEmitidosEmContingencia());
					if (quantidadeDocumentosEmitidosEmContingencia != 0 && System.Windows.Application.Current.Dispatcher.Invoke(() => DialogoFactory.MostrarDialogoSimNao($"{quantidadeDocumentosEmitidosEmContingencia} notas fiscais emitidas em contingência serão transmitidas automaticamente. Deseja continuar?")) == MessageBoxResult.Yes)
					{
						OnEmissorAvisoEvent("Aguarde! Transmitindo notas fiscais emitidas em contingência...");
						LoaderProcessoService.MostrarLoader("Aguarde! Transmitindo notas fiscais emitidas em contingência...");
						IEnumerable<ResumoNfceTransmitidaDto> resumo = _service.Canal((INotaFiscalConsumidorEletronicaModuleService service) => service.EfetivarDocumentosEmitidosEmContingencia());
						OnTransmitiuDocumentos(resumo);
					}
				}
				catch (Exception ex)
				{
					Exception ex2 = ex;
					Exception ex3 = ex2;
					System.Windows.Application.Current.Dispatcher.Invoke(() => DialogoFactory.MostrarDialogoConfirma(ex3.Message));
				}
				finally
				{
					LoaderProcessoService.EsconderLoader();
					OnEmissorProntoEvent();
				}
			});
			thread.IsBackground = true;
			thread.Start();
		}

		public bool VerificarExistenciaMovimentacaoAguardandoComAbastecimento(string idAbastecimento)
		{
			return _service.Canal((INotaFiscalConsumidorEletronicaModuleService service) => service.VerificarExistenciaMovimentacaoAguardandoComAbastecimento(idAbastecimento));
		}

		public override void AlterarTipoEmissao()
		{
			try
			{
				if (_tipoEmissao == 2)
				{
					ConfiguracaoOffline configuracaoOffline = ConfiguracaoOffline.Carregar();
					int tipoEmissaoNotaFiscalConsumidorEletronicaOffline = configuracaoOffline.TipoEmissaoNotaFiscalConsumidorEletronicaOffline;
					tipoEmissaoNotaFiscalConsumidorEletronicaOffline = ((tipoEmissaoNotaFiscalConsumidorEletronicaOffline != 1) ? 1 : 9);
					ConfiguracaoOffline.Criar().ComSequencia(configuracaoOffline.Sequencia).ComSerie(configuracaoOffline.Serie)
						.ComCSCCodigoSegurancaContribuinteNFCe(configuracaoOffline.CSCCodigoSegurancaContribuinteNFCe)
						.ComIdentificadorCSCNFCe(configuracaoOffline.IdentificadorCSCNFCe)
						.ComCertificadoDigitalNFeThumbPrint(configuracaoOffline.CertificadoDigitalNFeThumbPrint)
						.ComGerarNovosCodigosPagamentoNt2020006(configuracaoOffline.GerarNovosCodigosPagamentoNt2020006)
						.ComGerarQRVersao3Nt2025001(configuracaoOffline.GerarQRVersao3Nt2025001)
						.ComGerarCamposReferenteReformaTributariaConsumo(configuracaoOffline.GerarCamposReferenteReformaTributariaConsumo)
						.ComTransmitirNotaFiscalConsumidorEletronicaOfflineEmContingenciaAutomaticamente(configuracaoOffline.TransmitirNotaFiscalConsumidorEletronicaOfflineEmContingenciaAutomaticamente)
						.ComTipoEmissaoNotaFiscalConsumidorEletronicaOffline(tipoEmissaoNotaFiscalConsumidorEletronicaOffline)
						.ComTipoAmbienteNotaFiscalConsumidorEletronicaOffline(configuracaoOffline.TipoAmbienteNotaFiscalConsumidorEletronicaOffline)
						.ComAccessKeyShipay(configuracaoOffline.AccessKeyShipay)
						.ComSecretKeyShipay(configuracaoOffline.SecretKeyShipay)
						.Salvar();
				}
				else
				{
					_service.Canal((INotaFiscalConsumidorEletronicaModuleService service) =>
					{
						service.AlterarTipoEmissao();
					});
				}
			}
			catch (Exception ex)
			{
				ex.ShowLastException();
			}
			finally
			{
				ConsultarStatusServico();
			}
		}

