		public virtual void TransmitirNfceEmSituacaoAguardando(MovimentacaoDto documentoFiscal)
		{
			OnEmissorAvisoEvent("Aguarde! Transmitindo...");
			Task.Run(() => UltimaNfce = _service.Canal((INotaFiscalConsumidorEletronicaModuleService service) => service.EfetivarPreDocumentoComAtualizacao(documentoFiscal.Id))).ContinueWith((Task<MovimentacaoDto> task) =>
			{
				try
				{
					if (task.Exception.IsNotNull())
					{
						throw new Exception(task.Exception.InnerException.Message);
					}
					if (UltimaNfce.Situacao.Codigo == 6)
					{
						throw new Exception(UltimaNfce.Historicos.LastOrDefault().Observacao);
					}
					AdicionarValorSangria();
					DialogoFactory.MostrarDialogoConfirma("NFC-e transmitida com sucesso");
				}
				catch (Exception ex)
				{
					DialogoFactory.MostrarDialogoConfirma(ex.Message);
				}
				finally
				{
					OnEmissorProntoEvent();
				}
			});
		}

		private void AdicionarValorSangria()
		{
			decimal num = UltimaNfce.ItensPagamentos?.Where((ItemPagamentoDto x) => x.EspeciePagamento.Codigo == 1).Sum((ItemPagamentoDto x) => x.Valor) ?? 0m;
			if (num > 0m)
			{
				new ValorSangriaService(_valorSangriaRepositoryWrite, _valorSangriaRepositoryRead).AlterarValor(num);
			}
		}

		public virtual void FinalizarNfce(PreDocumentoFiscal preDocumentoFiscal, IPagamentoRecebimento recebimento, IEnumerable<ItemPagamento> itensPagamentos)
		{
			if (_tipoEmissao == 2)
			{
				throw new ExceptionContingenciaOffline();
			}
			MovimentacaoDto movimentacao = preDocumentoFiscal.ProjectedPreDocumentoAsMovimentacaoDto(recebimento, itensPagamentos, _arquivoAuxiliarService.Md5ArquivosAutenticados);
			OnEmissorAvisoEvent("Aguarde! Transmitindo...");
			EfetivarPreDocumentoFiscal(preDocumentoFiscal, movimentacao, (Task task) =>
			{
				try
				{
					if (task.Exception.IsNotNull())
					{
						if (!_controleContingencia.IsNotNull())
						{
							throw new Exception(task.Exception.InnerException.Message);
						}
						for (int i = 0; i <= 10; i++)
						{
							Thread.Sleep(1000);
							MovimentacaoDto movimentacaoDto = _service.Canal((INotaFiscalConsumidorEletronicaModuleService service) => service.ObterNfceControleContingencia(_controleContingencia.ToString()));
							if (movimentacaoDto.IsNotNull() && !string.IsNullOrEmpty(movimentacaoDto.XmlTextoAutorizadoNfceCompactadoGZip))
							{
								UltimaNfce = movimentacaoDto;
								break;
							}
						}
						if (UltimaNfce.IsNull())
						{
							throw new Exception(task.Exception.InnerException.Message);
						}
					}
					if (UltimaNfce.Situacao.Codigo == 6)
					{
						preDocumentoFiscal.SetarNumero(UltimaNfce.Numero);
						preDocumentoFiscal.SetarId(UltimaNfce.Id);
						preDocumentoFiscal.SetarVersaoMovimentacao(UltimaNfce.Versao);
						throw new Exception(UltimaNfce.Historicos.LastOrDefault().Observacao);
					}
					System.Windows.Application.Current.Dispatcher.Invoke(() =>
					{
						Imprimir(UltimaNfce);
					});
					if (!string.IsNullOrEmpty(UltimaNfce.Pessoa.CpfCnpj) && DadosSistema.ConfiguracaoDto.Saida.EnviarEmailPdv.Valor)
					{
						Task.Factory.StartNew(() => EnviarEmailNotaFiscalConsumidorEletronica(UltimaNfce));
					}
					if (DadosSistema.ConfiguracaoDto.Saida.SolicitarImpressaoTicketTroca.Valor && DialogoFactory.MostrarDialogoSimNao("Deseja imprimir o ticket de troca?") == MessageBoxResult.Yes)
					{
						ImprimirTicketTroca(UltimaNfce);
					}
					if ((DadosSistema.ConfiguracaoDto.Saida.ImprimirSaldoDevedorAposVenda.Valor || DadosSistema.ConfiguracaoDto.Saida.ImprimirCashbackDisponivelAposVenda.Valor) && !UltimaNfce.Pessoa.ConsumidorReservadoSistema)
					{
						ImprimirValoresCliente(UltimaNfce);
					}
					ThreadPrincipal.Executar(() =>
					{
						ImpressaoBoletoService.Init().ComBoletoProxyService(_boletoProxyService).VerificarImpressaoBoletos(UltimaNfce);
					});
					OnEmissorTerminouDocumentoFiscalEvent(UltimaNfce.Numero);
					OnAlterouTipoEmissao((!UltimaNfce.IsEmitidaEmContingenciaToText.Contains("Sim")) ? 1 : 9);
				}
				catch (Exception ex)
				{
					OnDocumentoFiscalAbertoEvent();
					if (ConfiguracaoOffline.Carregar().PdvOfflineValido && DadosSistema.HabilitacaoLocalContemModuloPdvOffline())
					{
						ex.ShowLastException();
						InicializarEmissor();
						OnCancelarFinalizacao();
					}
					else
					{
						OnErroAoTransmitirDocumentoFiscalEvent(ex.Message);
					}
				}
			});
		}

		public Movimentacao RetornarMovimentacaoNfceOffline(PreDocumentoFiscal preDocumentoFiscal, IPagamentoRecebimento recebimento, IEnumerable<ItemPagamento> itensPagamentos)
		{
			MovimentacaoDto movimentacaoDto = preDocumentoFiscal.ProjectedPreDocumentoAsMovimentacaoDto(recebimento, itensPagamentos, _arquivoAuxiliarService.Md5ArquivosAutenticados);
			OnEmissorAvisoEvent("Aguarde! Transmitindo...");
			List<DigisatServer.Domain.Main.Aggregates.CadastrosAgg.Pessoas.Pessoa> source = _pessoaRepositoryRead.Find(PessoaSpecifications.AtivoPorTipoCadastro(ativo: true, TipoPessoaCadastro.Contabilista)).ToListEmptyWhenNull();
			if (source.Any())
			{
				List<string> list = new List<string>();
				list.AddRange(from a in source
					select a.To<Fisica>().Contabilista?.CnpjContabilidade into a
					where a.IsNotNull()
					select a);
				list.AddRange(from a in source
					select a.CpfCnpj into a
					where a.IsNotNull()
					select a);
				movimentacaoDto.ListaCpfCnpjAutorizacaoObterXmlNfe = new List<string>(list).Distinct();
			}
			ConfiguracaoOffline configuracaoOffline = ConfiguracaoOffline.Carregar();
			SequenciaNFCe sequenciaMovimentacao = new SequenciaNFCe(configuracaoOffline.Sequencia, configuracaoOffline.Serie, DadosSistema.EmpresaLogada.Id.TryParseReferencia());
			Movimentacao movimentacao = movimentacaoDto.MorfarNotaFiscalConsumidorEletronica(DadosSistema.NomeUsuario, DadosSistema.ConfiguracaoDto.Morfar(DadosSistema.EmpresaLogada.Id), sequenciaMovimentacao);
			if (movimentacao.Numero == 0L)
			{
				int sequencia = configuracaoOffline.Sequencia;
				configuracaoOffline.ComSequencia(sequencia + 1).Salvar();
				movimentacao.SetarNumero(sequencia + 1);
			}
			if (configuracaoOffline.TipoEmissaoNotaFiscalConsumidorEletronicaOffline == 1)
			{
				NotaFiscalConsumidorEletronicaServiceOffline.EmitirNormalOffline(movimentacao.To<IDocumentoFiscalEletronico>(), DadosSistema.ObterProxy(), DadosSistema.NomeUsuario, configuracaoOffline);
			}
			else
			{
				NotaFiscalConsumidorEletronicaServiceOffline.EmitirEmContingenciaOffline(movimentacao.To<IDocumentoFiscalEletronico>(), DadosSistema.ObterProxy(), DadosSistema.NomeUsuario, configuracaoOffline);
			}
			UltimaNfce = null;
			UltimaNfce = movimentacao.ProjectedAsDto();
			string valorString = new GeradorArquivos(movimentacao.Empresa.CpfCnpj).ObterProcNfe(movimentacao.ObterChaveAcesso());
			UltimaNfce.XmlTextoAutorizadoNfceCompactadoGZip = valorString.CodificarStringParaBase64CompactoGzip();
			try
			{
				if (UltimaNfce.Situacao.Codigo == 6)
				{
					preDocumentoFiscal.SetarNumero(UltimaNfce.Numero);
					preDocumentoFiscal.SetarId(UltimaNfce.Id);
					preDocumentoFiscal.SetarVersaoMovimentacao(UltimaNfce.Versao);
					throw new Exception(UltimaNfce.Historicos.LastOrDefault().Observacao);
				}
				System.Windows.Application.Current.Dispatcher.Invoke(() =>
				{
					Imprimir(UltimaNfce);
				});
				if (!string.IsNullOrEmpty(UltimaNfce.Pessoa.CpfCnpj) && DadosSistema.ConfiguracaoDto.Saida.EnviarEmailPdv.Valor)
				{
					Task.Factory.StartNew(() => EnviarEmailNotaFiscalConsumidorEletronica(UltimaNfce));
				}
				if (DadosSistema.ConfiguracaoDto.Saida.SolicitarImpressaoTicketTroca.Valor && DialogoFactory.MostrarDialogoSimNao("Deseja imprimir o ticket de troca?") == MessageBoxResult.Yes)
				{
					ImprimirTicketTroca(UltimaNfce);
				}
				if ((DadosSistema.ConfiguracaoDto.Saida.ImprimirSaldoDevedorAposVenda.Valor || DadosSistema.ConfiguracaoDto.Saida.ImprimirCashbackDisponivelAposVenda.Valor) && !UltimaNfce.Pessoa.ConsumidorReservadoSistema)
				{
					ImprimirValoresCliente(UltimaNfce);
				}
				ThreadPrincipal.Executar(() =>
				{
					ImpressaoBoletoService.Init().ComBoletoProxyService(_boletoProxyService).VerificarImpressaoBoletos(UltimaNfce);
				});
			}
			catch (Exception ex)
			{
				OnDocumentoFiscalAbertoEvent();
				OnErroAoTransmitirDocumentoFiscalEvent(ex.Message);
			}
			return movimentacao;
		}

		protected virtual void EfetivarPreDocumentoFiscal(PreDocumentoFiscal preDocumentoFiscal, MovimentacaoDto movimentacao, Action<Task> callbackEfetivarPreDocumentoFiscal)
		{
			bool emitirNfe = false;
			bool flag = false;
			try
			{
				if (movimentacao.Pessoa.IsJuridica && (!DadosSistema.ConfiguracaoDto.Saida.SolicitarEmissaoNfePessoaJuridica.Valor || DialogoFactory.MostrarDialogoSimNao("Detectado indicação de pessoa jurídica. Deseja emitir NF-e?") == MessageBoxResult.Yes))
				{
					AutorizacaoDto autorizacaoDto = DadosSistema.AutenticacaoService.Instancia.VerificarPermissao<DigisatServer.Infrastructure.Crosscutting.Module.PontoDeVenda, PermitirEmitirNotaFiscalEletronicaPeloPontoDeVenda>();
					if (autorizacaoDto == null)
					{
						flag = true;
						return;
					}
					List<AutorizacaoDto> autorizacoes = new List<AutorizacaoDto>(movimentacao.Autorizacoes)
					{
						new AutorizacaoDto
						{
							NomeUsuario = DadosSistema.NomeUsuario,
							Data = DateTime.Now,
							Direito = autorizacaoDto.Direito
						}
					};
					movimentacao.Autorizacoes = autorizacoes;
					emitirNfe = true;
				}
				if (_tipoEmissao == 1 && DadosSistema.ConfiguracaoDto.Saida.VerificarInternetNFCe.Valor)
				{
					ConexaoInternet.CheckForInternetConnection();
				}
			}
			catch (Exception ex)
			{
				if (DadosSistema.VerificarPermissao<DigisatServer.Infrastructure.Crosscutting.Module.PontoDeVenda, PermitirAlterarTipoEmissaoPontoDeVenda>() && DialogoFactory.MostrarDialogoSimNao($"{ex.Message}\nAlterar o tipo de emissão para Contingência Off-line?") == MessageBoxResult.Yes)
				{
					AlterarTipoEmissao();
				}
			}
			finally
			{
				if (flag)
				{
					throw new Exception("Abandonar");
				}
				Task.Run(() =>
				{
					UltimaNfce = null;
					_controleContingencia = ObjectId.GenerateNewId();
					movimentacao.ControleContingencia = _controleContingencia.ToString();
					if (preDocumentoFiscal.OptouPorEmitirNFe != emitirNfe && movimentacao.Numero > 0)
					{
						MovimentacaoDto movimentacaoDto = _service.Canal((INotaFiscalEletronicaSaidaModuleService service) => service.ZerarNumeracao(movimentacao.Id));
						movimentacao.Numero = 0L;
						movimentacao.Versao = movimentacaoDto.Versao;
					}
					preDocumentoFiscal.OptouPorEmitirNFe = emitirNfe;
					if (!movimentacao.Pessoa.IsJuridica)
					{
						UltimaNfce = _service.Canal((INotaFiscalConsumidorEletronicaModuleService service) => service.EfetivarPreDocumentoFiscal(movimentacao));
					}
					else if (emitirNfe)
					{
						UltimaNfce = _service.Canal((INotaFiscalEletronicaSaidaModuleService service) => service.EfetivarNfe(movimentacao));
					}
					else
					{
						UltimaNfce = _service.Canal((INotaFiscalConsumidorEletronicaModuleService service) => service.EfetivarPreDocumentoFiscal(movimentacao));
