		private void ImprimirValoresCliente(MovimentacaoDto movimentacao)
		{
			try
			{
				bool valor = DadosSistema.ConfiguracaoDto.Saida.ImprimirSaldoDevedorAposVenda.Valor;
				bool valor2 = DadosSistema.ConfiguracaoDto.Saida.ImprimirCashbackDisponivelAposVenda.Valor;
				decimal num = (valor ? _service.Canal((IRecebimentoModuleService service) => service.ObterSaldoDevedor(movimentacao.Pessoa.Id)) : 0m);
				decimal num2 = (valor2 ? _service.Canal((IPessoaModuleService service) => service.ObterItensCreditoDebitoCashback(movimentacao.Pessoa.Id)).Sum((ItemCreditoDebitoCashbackDto item) => item.Valor) : 0m);
