				{
					IRelatorio relatorio2;
					if (DadosSistema.TamanhoBobina != TamanhoBobina.CinquentaESeisCinquentaESeteCinquentaEOitoMilimetros)
					{
						IRelatorio relatorio = new RelatorioValoresCliente79Mm80Mm(movimentacao.Pessoa, num, num2, DadosSistema.MargemEsquerdaImpressoraNaoFiscal, DadosSistema.RollPaper, valor, valor2);
						relatorio2 = relatorio;
					}
					else
					{
						IRelatorio relatorio = new RelatorioValoresCliente56Mm57Mm58Mm(movimentacao.Pessoa, num, num2, DadosSistema.MargemEsquerdaImpressoraNaoFiscal, DadosSistema.RollPaper, valor, valor2);
						relatorio2 = relatorio;
					}
					IRelatorio relatorio3 = relatorio2;
					_impressoraNaoFiscalService.Imprimir(relatorio3);
				}
			}
			catch (Exception ex)
			{
				ex.ShowLastException();
			}
