		public void ReimprimirDanfe(MovimentacaoDto movimentacao)
		{
			if (_sessaoService.VerificarPermissao<DigisatServer.Infrastructure.Crosscutting.Module.PontoDeVenda, PermitirReimprimirDocumentoFiscal>() != null)
