		public void Imprimir(MovimentacaoDto movimentacao)
		{
			NFeProc nFeProc = ObterNFe(movimentacao);
			int vias = ((nFeProc != null && nFeProc.NFe.InfNFe.Ide.tpEmis == 1) ? 1 : (DadosSistema.ConfiguracaoDto.Saida.ImprimirViaUnicaDanfeNfceContingencia.Valor ? 1 : 2));
			Imprimir(nFeProc, vias);
		}

		private NFeProc ObterNFe(MovimentacaoDto movimentacao)
		{
			if (movimentacao.XmlTextoAutorizadoNfceCompactadoGZip.IsNullOrEmpty())
			{
				movimentacao = _service.Canal((INotaFiscalConsumidorEletronicaModuleService x) => x.PreencherXmlTextoAutorizadoNfceCompactadoGZip(movimentacao));
			}
			return (NFeProc)HelperXml.StringXmlToObject(movimentacao.XmlTextoAutorizadoNfceCompactadoGZip.DecodificarBase64CompactoGzipParaString(), typeof(NFeProc));
		}

		private void Imprimir(NFeProc nfeProc, int vias)
		{
			if (nfeProc.NFe.InfNFe.Ide.mod.Equals("65"))
			{
				ImprimirNfce(nfeProc, vias);
			}
			else
			{
				ImprimirNfe(nfeProc, vias);
			}
		}

		protected void ImprimirNfce(NFeProc nfeProc, int vias)
		{
			if (DadosSistema.ConfiguracaoDto.Saida.SolicitarImpressao.Valor && DialogoFactory.MostrarDialogoSimNao("Deseja imprimir a NFC-e?") != MessageBoxResult.Yes)
			{
				return;
			}
			for (int i = 0; i < vias; i++)
			{
				Parametros parametros = new Parametros
				{
					ListaDeParametros = new List<IParametro>
					{
						new Parametro
						{
							Tipo = typeof(int),
							Titulo = "Via",
							Valor = i
						}
					},
					Objeto = nfeProc
				};
				IRelatorio relatorio;
				if (DadosSistema.ConfiguracaoDto.Saida.ImprimirDanfeNfceEmFolhaA4.Valor)
				{
					relatorio = new RelatorioDanfeNfceA4(nfeProc, DadosSistema.EmpresaLogada.Imagem, DadosSistema.ImprimirDadosDoEncerranteItemDanfeNfce)
					{
						Parametros = parametros
					};
					_impressoraNaoFiscalService.ImprimirImpressoraNaoFiscalDanfeNfe((DigisatServer.Infrastructure.Crosscutting.Report.Models.Relatorio)relatorio);
					break;
				}
				TamanhoBobina tamanhoBobina = DadosSistema.TamanhoBobina;
				relatorio = ((tamanhoBobina != TamanhoBobina.CinquentaESeisCinquentaESeteCinquentaEOitoMilimetros) ? ((IRelatorio)new RelatorioDanfeNfce79Mm80Mm(nfeProc, DadosSistema.ImprimirDetalheVendaNfce, DadosSistema.ImprimirItemResumidoDanfeNfce, DadosSistema.ImprimirDanfeResumidoNfce, DadosSistema.MargemEsquerdaImpressoraNaoFiscal, DadosSistema.EmpresaLogada.Imagem, DadosSistema.ImprimirDadosDoEncerranteItemDanfeNfce, DadosSistema.RollPaper)
				{
					Parametros = parametros
				}) : ((IRelatorio)new RelatorioDanfeNfce56Mm57Mm58Mm(nfeProc, DadosSistema.ImprimirDetalheVendaNfce, DadosSistema.MargemEsquerdaImpressoraNaoFiscal, DadosSistema.EmpresaLogada.Imagem, DadosSistema.ImprimirDadosDoEncerranteItemDanfeNfce, DadosSistema.ImprimirItemResumidoDanfeNfce, DadosSistema.RollPaper)
				{
					Parametros = parametros
				}));
				_impressoraNaoFiscalService.Imprimir(relatorio);
			}
		}

