		public void ImprimirCancelamentoNfe(NFeProc nfeProc, MovimentacaoDto dto)
		{
			ObterImpressaoDfe(dto).ContinueWith((Task<ImpressaoDFeDto> task) =>
			{
				if (task.IsFaulted)
				{
					task.Exception.ShowLastException();
				}
				else
				{
					ProcEventoNFe nfeProcEventoNfe = ObterProcEventoNFe(task.Result.XmlEventoCancelamento);
					_impressoraNaoFiscalService.Imprimir(ObterComprovanteCancelamento(nfeProc, nfeProcEventoNfe));
				}
			});
		}

		protected async Task<ImpressaoDFeDto> ObterImpressaoDfe(EntityBaseDto dto)
		{
			ImpressaoDFeDto impressaoDFeDto = await _service.Canal((IMovimentacaoSaidaModuleService service) => service.ObterDanfeParaImpressaoAsync(dto.Id));
			if (string.IsNullOrEmpty(impressaoDFeDto.DFe))
			{
				throw new Exception("XML da nota não encontrado na pasta DFe");
			}
			return impressaoDFeDto;
		}

		protected ProcEventoNFe ObterProcEventoNFe(string xmlProcEventoNfe)
		{
			return HelperXml.StringXmlToObject(xmlProcEventoNfe, typeof(ProcEventoNFe)).To<ProcEventoNFe>();
		}

		protected IRelatorio ObterComprovanteCancelamento(NFeProc nfeProc, ProcEventoNFe nfeProcEventoNfe)
		{
			ImpressaoDfe impressaoDfe = ImpressaoDfe.Criar().ComNFeProc(nfeProc).ComProcEventoNFe(nfeProcEventoNfe)
				.Build();
			if (nfeProc.NFe.InfNFe.Ide.tpImp != 3)
			{
				return new RelatorioDanfeRetratoComprovanteCancelamento().ComImpressaoDfe(impressaoDfe).ComCpfCnpj(DadosSistema.EmpresaLogada.CpfCnpj).ComImagem(DadosSistema.EmpresaLogada.Imagem)
					.ComMargemEsquerda(DadosSistema.MargemEsquerdaImpressoraNaoFiscalDanfeNfe)
					.ComMargemSuperior(DadosSistema.MargemSuperiorImpressoraNaoFiscalDanfeNfe);
			}
			return new RelatorioDanfeSimplificadoComprovanteCancelamento().ComImpressaoDfe(impressaoDfe).ComMargemEsquerda(DadosSistema.ObterConfiguracaoClient().ObterConfiguracao().ImpressoraNaoFiscal.RetornarMargemEsquerda()).ComMargemSuperior(DadosSistema.ObterConfiguracaoClient().ObterConfiguracao().ImpressoraNaoFiscal.RetornarMargemSuperior());
		}

