									.ComImprimirNumeroEItemPedidoCompraItemDanfeNfe(DadosSistema.ConfiguracaoDto.Saida.ImprimirNumeroEItemPedidoCompraItemDanfeNfe.Valor)
									.ComSuprimirTotaisReformaTributariaDanfeNfe(DadosSistema.SuprimirTotaisReformaTributariaDanfeNfe);
								relatorio2 = relatorio;
							}
							else
							{
								IRelatorio relatorio = new RelatorioDanfeSimplificadoTipo2(nFeProc, DadosSistema.ImprimirDanfeResumidoNfce, DadosSistema.MargemEsquerdaImpressoraNaoFiscal, DadosSistema.EmpresaLogada.Imagem);
								relatorio2 = relatorio;
							}
						}
						else
						{
							IRelatorio relatorio = new RelatorioDanfeSimplificado().ComNfeProc(nFeProc).ComCasasDecimaisQuantidade(DadosSistema.ConfiguracaoDto.Geral.CasasDecimaisQuantidade.Valor).ComMargemEsquerda(DadosSistema.ObterConfiguracaoClient().ObterConfiguracao().ImpressoraNaoFiscal.RetornarMargemEsquerda())
								.ComMargemSuperior(DadosSistema.ObterConfiguracaoClient().ObterConfiguracao().ImpressoraNaoFiscal.RetornarMargemSuperior())
								.ComSuprimirTotaisReformaTributariaDanfeNfe(DadosSistema.SuprimirTotaisReformaTributariaDanfeNfe);
							relatorio2 = relatorio;
						}
					}
					else
					{
						IRelatorio relatorio = new RelatorioDanfeRetrato().ComNfeProc(nFeProc).ComCpfCnpj(DadosSistema.EmpresaLogada.CpfCnpj).ComImagem(DadosSistema.EmpresaLogada.Imagem)
							.ComImagemMarcaAgua(DadosSistema.EmpresaLogada.ImagemMarcaAgua)
							.ComTransparenciaMarcaAgua(DadosSistema.EmpresaLogada.TransparenciaMarcaAgua)
							.ComMargemEsquerdaImpressoraNaoFiscalDanfeNfe(DadosSistema.MargemEsquerdaImpressoraNaoFiscalDanfeNfe)
							.ComMargemSuperiorImpressoraNaoFiscalDanfeNfe(DadosSistema.MargemSuperiorImpressoraNaoFiscalDanfeNfe)
							.ComExibirAssinaturaDataRecebimentoTodasPaginase(DadosSistema.ConfiguracaoDto.Saida.ExibirAssinaturaDataRecebimentoTodasPaginas.Valor)
							.ComImprimirItemResumidoDanfeNfe(DadosSistema.ImprimirItemResumidoDanfeNfe)
							.ComCasasDecimaisQuantidade(DadosSistema.ConfiguracaoDto.Geral.CasasDecimaisQuantidade.Valor)
							.ComImprimirCodigoBarrasItemDanfeNfe(DadosSistema.ConfiguracaoDto.Saida.ImprimirCodigoBarrasItemDanfeNfe.Valor)
							.ComImprimirFcpItemDanfeNfe(DadosSistema.ConfiguracaoDto.Saida.ImprimirFcpItemDanfeNfe.Valor)
							.ComImprimirStItemDanfeNfe(DadosSistema.ConfiguracaoDto.Saida.ImprimirStItemDanfeNfe.Valor)
							.ComImprimirUnidadeQuantidadeTributariaItemDanfeNfe(DadosSistema.ConfiguracaoDto.Saida.ImprimirUnidadeQuantidadeTributariaItemDanfeNfe.Valor)
							.ComImprimirNumeroEItemPedidoCompraItemDanfeNfe(DadosSistema.ConfiguracaoDto.Saida.ImprimirNumeroEItemPedidoCompraItemDanfeNfe.Valor)
							.ComSuprimirTotaisReformaTributariaDanfeNfe(DadosSistema.SuprimirTotaisReformaTributariaDanfeNfe);
						relatorio2 = relatorio;
					}
					danfe = relatorio2;
				}
				if (!File.Exists(text4))
				{
					if (DadosSistema.ConfiguracaoDto.Geral.ProtegerPdfExportadoComSenha.Valor && movimentacao.Pessoa.CpfCnpj.RemoveCaracteresAlfanumerico().Length >= 6)
					{
						XtraReport xtraReport = danfe.Processar();
						PdfExportOptions pdfExportOptions = new PdfExportOptions();
						pdfExportOptions.PasswordSecurityOptions.OpenPassword = movimentacao.Pessoa.CpfCnpj.RemoveCaracteresAlfanumerico().CopiarTexto(6);
						xtraReport.ExportToPdf(text4, pdfExportOptions);
					}
					else
					{
						danfe.Processar().ExportToPdf(text4);
					}
				}
				HelperXml.CriarArquivoXml(movimentacao.XmlTextoAutorizadoNfceCompactadoGZip.DecodificarBase64CompactoGzipParaString(), text3);
				List<AnexoEmail> anexos = new List<AnexoEmail>
				{
					new AnexoEmail(text4, text2),
					new AnexoEmail(text3, text)
				};
				ConfiguracaoEmailDto configuracaoEmail = await _service.Canal((IConfiguracaoModuleService x) => x.ObterConfiguracaoEmailNfeAsync());
				ProcessarCorpoEmailDocumentoFiscalEletronico(configuracaoEmail, movimentacao);
				await EnviarEmail(configuracaoEmail, anexos, movimentacao);
			}
			catch (Exception ex)
			{
				DialogoFactory.MostrarDialogoConfirma(ex.Message);
			}
		}

		private void ProcessarCorpoEmailDocumentoFiscalEletronico(ConfiguracaoEmailDto configuracaoEmail, MovimentacaoDto dto)
		{
			configuracaoEmail.ModeloEmail.Corpo = configuracaoEmail.ModeloEmail.Corpo.Replace(TagEmailModeloDocumentoFiscalEletronico.NomePessoa.RetornarDescricao(), dto.Pessoa.Nome).Replace(TagEmailModeloDocumentoFiscalEletronico.NumeroDocumentoFiscal.RetornarDescricao(), dto.Numero.ToStringLeftZero(9)).Replace(TagEmailModeloDocumentoFiscalEletronico.DataEmissao.RetornarDescricao(), (dto.DataHoraEntradaSaida == DateTime.MinValue) ? dto.DataHoraEmissao.FormatarData() : dto.DataHoraEntradaSaida.FormatarData())
				.Replace(TagEmailModeloDocumentoFiscalEletronico.Serie.RetornarDescricao(), dto.Serie)
				.Replace(TagEmailModeloDocumentoFiscalEletronico.Total.RetornarDescricao(), dto.Total.FormatarCampoValor(2));
		}

		public async Task EnviarEmail(ConfiguracaoEmailDto configuracaoEmail, IEnumerable<AnexoEmail> caminho, MovimentacaoDto movimentacao)
		{
			try
			{
				LoaderProcessoService.MostrarLoader("Enviando e-mail...");
				string emailDestinatario = RetornarEmailDestinatarios(movimentacao);
				EmailServiceFactory.SetCurrent(ObterEnvioEmailService(caminho, configuracaoEmail, emailDestinatario));
				_serviceEmail = EmailServiceFactory.Create();
				await _serviceEmail.Enviar();
				ThreadPrincipal.Executar(() =>
				{
					_notificacao.MostrarNotificacao($"E-mail enviado para {_emailDestinatario}");
				});
			}
			catch (Exception ex)
			{
				DialogoFactory.MostrarDialogoConfirma(ex.Message);
			}
			finally
			{
				LoaderProcessoService.EsconderLoader();
				_serviceEmail?.Dispose();
			}
		}

		private static string RetornarEmailDestinatarios(MovimentacaoDto dto)
		{
			string text = null;
			if (!string.IsNullOrEmpty(dto.Pessoa.EmailPrincipal.Endereco))
			{
				text = text + dto.Pessoa.EmailPrincipal.Endereco + ";";
			}
			foreach (EnderecoEletronicoDto item in dto.Pessoa.EmailsNfe.Where((EnderecoEletronicoDto x) => !string.IsNullOrEmpty(x.Endereco)))
			{
				text = text + item.Endereco + "; ";
			}
			return text;
		}

		private EnvioEmailServiceFactory ObterEnvioEmailService(IEnumerable<AnexoEmail> anexos, ConfiguracaoEmailDto configuracaoEmail, string emailDestinatario)
		{
			if (configuracaoEmail.ModeloEmail.Is<EmailModeloDtoNull>())
			{
				throw new Exception("Verifique as configurações de modelo de e-mail!");
			}
			string email = (configuracaoEmail.EnviarCopiaRemetente ? configuracaoEmail.UsuarioEmail : string.Empty);
			DigisatServer.Infrastructure.Crosscutting.Mvvm.Email email2 = new DigisatServer.Infrastructure.Crosscutting.Mvvm.Email().ComAssunto(configuracaoEmail.ModeloEmail.Assunto).ComCorpo(configuracaoEmail.ModeloEmail.Corpo).ComEmailResposta(configuracaoEmail.ModeloEmail.EmailParaResposta)
				.ComEmailDestinatario(emailDestinatario)
				.ComAnexos(new Lista<AnexoEmail>(anexos));
			if (!configuracaoEmail.EnviarEmailAutomaticamente || emailDestinatario.IsEmpty())
			{
				if (DialogoFactory.MostrarDialogoEmail(ref emailDestinatario, email2, new EnviarEmail()) != MessageBoxResult.OK)
				{
					throw new Exception("O e-mail não será enviado.");
				}
				if (email2.EmailDestinatario.IsNullOrEmpty())
				{
					throw new Exception("O e-mail não será enviado. Destinatário não informado.");
				}
			}
			EnvioEmailServiceFactory envioEmailServiceFactory = new EnvioEmailServiceFactory().SetarServidorSmtp(configuracaoEmail.ServidorSmtp).SetarAssunto(email2.Assunto).SetarEmailCopiaOculta(email, DadosSistema.EmpresaLogada.Nome)
				.SetarEmailRemetenteParaResposta(email2.EmailResposta, DadosSistema.EmpresaLogada.Nome)
				.SetarEmailRemetente(configuracaoEmail.UsuarioEmail, DadosSistema.EmpresaLogada.Nome)
				.AdicionarDestinatarios(email2.EmailDestinatario, email2.EmailDestinatario)
				.SetarMensagem(email2.Corpo)
				.SetarPorta(configuracaoEmail.PortaEmail)
				.SetarSenha(configuracaoEmail.SenhaEmail)
				.SetarUsaSsl(configuracaoEmail.UsaSsl)
				.SetarIgnorarCertificadoInvalido(configuracaoEmail.IgnorarCertificadoInvalido);
			foreach (AnexoEmail item in email2.Anexos.Itens.Where((AnexoEmail x) => x.IsNotNull()))
			{
				envioEmailServiceFactory.AdicionarAnexo(item.CaminhoArquivo, item.NomeArquivo);
			}
			_emailDestinatario = email2.EmailDestinatario;
			return envioEmailServiceFactory;
		}

		public override void Cancelar(IEstadoDocumentoFiscal estadoDocumentoFiscal, Autorizacao autorizacao)
		{
			if (!estadoDocumentoFiscal.Is<DocumentoFiscalFechado>())
			{
				OnDocumentoFiscalCanceladoEvent();
				return;
			}
			if (UltimaNfce == null)
			{
				throw new Exception("Faça o cancelamento através da opção 'F9 - Abrir NFC-e'");
			}
			CancelarVenda(UltimaNfce, autorizacao);
		}

		public void CancelarVenda(MovimentacaoDto movimentacao)
		{
			AutorizacaoDto autorizacaoDto = _sessaoService.VerificarPermissao<DigisatServer.Infrastructure.Crosscutting.Module.PontoDeVenda, PermitirCancelarDocumentoFiscal>();
			if (autorizacaoDto != null)
			{
				CancelarVenda(movimentacao, autorizacaoDto.Morfar());
			}
		}

		protected virtual void CancelarVenda(MovimentacaoDto movimentacao, Autorizacao autorizacao)
		{
			OnEmissorAvisoEvent("Cancelando...");
			ThreadPrincipal.Executar(() =>
			{
				LoaderProcessoService.MostrarLoader("Cancelando...");
			});
			DispatcherHelper.DoEvents();
			if (!PdvEstadoOffline)
			{
				SituacaoMovimentacaoDto situacaoMovimentacaoDto = _service.Canal((INotaFiscalConsumidorEletronicaModuleService service) => service.ObterSituacaoAtualizada(movimentacao.Id));
				if (movimentacao.IsNotNull() && situacaoMovimentacaoDto.Codigo == 13)
				{
					DialogoFactory.MostrarDialogoConfirma("Esta venda não pode ser cancelada pois está com situação 'Autorizado'. Aguarde alguns instantes e tente novamente.");
					LoaderProcessoService.EsconderLoader();
					return;
				}
				if (movimentacao.IsNotNull() && situacaoMovimentacaoDto.Codigo != 2 && situacaoMovimentacaoDto.Codigo != 14)
				{
					DialogoFactory.MostrarDialogoConfirma("Esta venda não pode ser cancelada.");
					LoaderProcessoService.EsconderLoader();
					return;
				}
			}
			MovimentacaoDto dtoAtualizado = null;
			Task.Run(async () =>
			{
				if (movimentacao.Tipo == TipoMovimentacao.NotaFiscalConsumidorEletronica)
				{
					_ = dtoAtualizado;
					dtoAtualizado = await _service.Canal((INotaFiscalConsumidorEletronicaModuleService service) => service.AdicionarHistoricoAsync(new HistoricoDto
					{
						SituacaoMovimentacao = SituacoesMovimentacao.ObterPorCodigo(4).ProjectedAsDto(),
						MovimentacaoReferencia = movimentacao.Id,
						Observacao = $"Cancelamento de NFC-e autorizado por {autorizacao.NomeUsuario}"
					}));
				}
				else
				{
					_ = dtoAtualizado;
					dtoAtualizado = (MovimentacaoDto)(await _service.Canal((IMovimentacaoSaidaModuleService service) => service.AdicionarHistoricoAsync(new HistoricoDto
					{
						SituacaoMovimentacao = SituacoesMovimentacao.ObterPorCodigo(4).ProjectedAsDto(),
						MovimentacaoReferencia = movimentacao.Id,
						Observacao = $"Cancelamento de NF-e autorizado por {autorizacao.NomeUsuario}"
					})));
				}
			}).ContinueWith((Task task) =>
			{
				try
				{
					if (task.Exception.IsNotNull())
					{
						if (task.Exception.InnerException.Message.Contains("Duplicidade"))
						{
							throw new Exception($"{task.Exception.InnerException.Message}.\n" + "Acesse 'Movimentações de saída' e realize a consulta da situação do documento fiscal eletrônico.");
						}
						ConfiguracaoOffline configuracaoOffline = ConfiguracaoOffline.Carregar();
						if (!configuracaoOffline.PdvOfflineValido || !DadosSistema.HabilitacaoLocalContemModuloPdvOffline())
						{
							throw new Exception(task.Exception.InnerException.Message);
						}
						Movimentacao oneBy = _movimentacaoRepositoryRead.GetOneBy((Movimentacao x) => x.Id, movimentacao.Id.TryParseReferencia());
						if (oneBy.IsNull())
						{
							throw new Exception(task.Exception.InnerException.Message);
						}
						if (oneBy.Historico.Is<HistoricoContingencia>())
						{
							HistoricoContingencia historicoContingencia = oneBy.Historico.To<HistoricoContingencia>();
							if (historicoContingencia != null && historicoContingencia.Offline)
							{
								throw new Exception("Não foi possível consultar o número de protocolo.");
							}
						}
						NotaFiscalConsumidorEletronicaServiceOffline.CancelarNormalOffline(oneBy.To<IDocumentoFiscalEletronico>(), DadosSistema.ObterProxy(), DadosSistema.NomeUsuario, configuracaoOffline);
						RemoverValorDinheiroSangria(movimentacao);
						OnDocumentoFiscalCanceladoEvent(movimentacao.Id);
						UltimaNfce = null;
						_movimentacaoRepositoryWrite.Update(oneBy);
						DialogoFactory.MostrarDialogoConfirma((movimentacao.Tipo == TipoMovimentacao.NotaFiscalConsumidorEletronica) ? "NFC-e cancelada com sucesso. Impressão do comprovante de cancelamento não disponível." : "NF-e cancelada com sucesso. Impressão do comprovante de cancelamento não disponível.");
					}
					else
					{
						if (dtoAtualizado.Situacao.Codigo != 4)
						{
							throw new Exception(dtoAtualizado.Historicos.LastOrDefault().Observacao);
						}
						RemoverValorDinheiroSangria(movimentacao);
						if (DialogoFactory.MostrarDialogoSimNao((movimentacao.Tipo == TipoMovimentacao.NotaFiscalConsumidorEletronica) ? "NFC-e cancelada com sucesso. Imprimir o comprovante de cancelamento?" : "NF-e cancelada com sucesso. Imprimir o comprovante de cancelamento?") == MessageBoxResult.Yes)
						{
							NFeProc nfeProc;
							try
							{
								nfeProc = ObterNFe(movimentacao);
							}
							catch (Exception)
							{
								nfeProc = (NFeProc)HelperXml.StringXmlToObject(DadosSistema.GetService().Canal((INotaFiscalConsumidorEletronicaModuleService x) => x.PreencherXmlTextoAutorizadoNfceCanceladaCompactadoGZip(movimentacao)).XmlTextoAutorizadoNfceCompactadoGZip.DecodificarBase64CompactoGzipParaString(), typeof(NFeProc));
							}
							HistoricoDto historicoDto = dtoAtualizado.Historicos.FirstOrDefault((HistoricoDto x) => x.SituacaoMovimentacao.Codigo == 4);
							if (historicoDto.IsNotNull())
							{
								if (movimentacao.Tipo == TipoMovimentacao.NotaFiscalConsumidorEletronica)
								{
									ImprimirCancelamentoNfce(nfeProc, historicoDto.ProtocoloAutorizacao, historicoDto.DataHoraRegistroEvento);
								}
								else
								{
									ImprimirCancelamentoNfe(nfeProc, movimentacao);
								}
							}
						}
						OnDocumentoFiscalCanceladoEvent(movimentacao.Id);
						UltimaNfce = null;
						EstornarPagamentosDigitais(dtoAtualizado.ItensPagamentos.SelectMany((ItemPagamentoDto item) => from x in item.InformacoesTransacaoCarteriaDigital
							where x.IsNsuValidoCancelamentoShipay
							select x.Nsu));
						CancelarTransacaoTef(new List<InformacaoTransacao>(dtoAtualizado.ItensPagamentos?.Where((ItemPagamentoDto x) => x.InformacoesTransacaoTef.Any() && x.EspeciePagamento.Codigo != 27 && !x.InformacoesTransacaoTef.All((InformacaoTransacaoTefDto y) => y.CodigoAutorizacaoTransacao.IsNullOrEmpty())).SelectMany((ItemPagamentoDto x) => x.InformacoesTransacaoTef.Select((InformacaoTransacaoTefDto y) => new InformacaoTransacao(y.Rede, y.Nsu, y.Valor)))));
						CancelarTransacaoTef(new List<InformacaoTransacao>(dtoAtualizado.ItensPagamentos?.Where((ItemPagamentoDto x) => x.InformacoesTransacaoCarteriaDigital.Any() && x.EspeciePagamento.Codigo != 27 && !x.InformacoesTransacaoCarteriaDigital.All((InformacaoTransacaoCarteiraDigitalDto y) => y.CodigoAutorizacaoTransacao.IsNullOrEmpty()) && x.InformacoesTransacaoCarteriaDigital.Any((InformacaoTransacaoCarteiraDigitalDto y) => !y.IsNsuValidoCancelamentoShipay)).SelectMany((ItemPagamentoDto x) => x.InformacoesTransacaoCarteriaDigital.Select((InformacaoTransacaoCarteiraDigitalDto y) => new InformacaoTransacao(y.Rede, y.Nsu, y.Valor)))));
						if (DadosSistema.IsFarmacia && !dtoAtualizado.NumeroAutorizacaoPortalDrograria.IsNullOrEmpty())
						{
							_farmaciaService.AnularVendaPortalDrogaria(dtoAtualizado.OperadoraPortalDrograria, dtoAtualizado.NumeroAutorizacaoPortalDrograria, 1);
							DialogoFactory.MostrarDialogoConfirma("001 - Operação anterior cancelada com sucesso");
						}
					}
				}
				catch (Exception ex2)
				{
					DialogoFactory.MostrarDialogoConfirma($"Erro ao cancelar documento. {Environment.NewLine} Motivo: {ex2.Message}");
				}
				finally
				{
					LoaderProcessoService.EsconderLoader();
					OnEmissorProntoEvent();
				}
			});
		}

		private void RemoverValorDinheiroSangria(MovimentacaoDto movimentacao)
		{
			decimal num = movimentacao.ItensPagamentos?.Where((ItemPagamentoDto x) => x.EspeciePagamento.Codigo == 1).Sum((ItemPagamentoDto x) => x.Valor) ?? 0m;
			if (num > 0m)
			{
				new ValorSangriaService(_valorSangriaRepositoryWrite, _valorSangriaRepositoryRead).AlterarValor(num, aumentar: false);
			}
		}

