		public void TransmitirDocumentosRejeitados(IEnumerable<ItemResumoNfce> movimentacoes)
		{
			Thread thread = new Thread(() =>
			{
				try
				{
					string mensagem = ((movimentacoes.Count() == 1) ? "Transmitir 1 nota fiscal rejeitada?" : $"Transmitir {movimentacoes.Count()} notas fiscais rejeitadas?");
					if (System.Windows.Application.Current.Dispatcher.Invoke(() => DialogoFactory.MostrarDialogoSimNao(mensagem)) == MessageBoxResult.Yes)
					{
						OnEmissorAvisoEvent("Aguarde! Transmitindo notas fiscais rejeitadas...");
						LoaderProcessoService.MostrarLoader("Aguarde! Transmitindo notas fiscais rejeitadas...");
						IEnumerable<ResumoNfceTransmitidaDto> resumo = _service.Canal((INotaFiscalConsumidorEletronicaModuleService service) => service.EfetivarDocumentosRejeitados(movimentacoes.Select((ItemResumoNfce x) => x.MovimentacaoReferencia)));
						OnTransmitiuDocumentos(resumo);
					}
				}
				catch (Exception ex)
				{
					Exception ex2 = ex;
					Exception ex3 = ex2;
					System.Windows.Application.Current.Dispatcher.Invoke(() => DialogoFactory.MostrarDialogoConfirma(ex3.Message));
				}
				finally
				{
					LoaderProcessoService.EsconderLoader();
					OnEmissorProntoEvent();
				}
			});
			thread.IsBackground = true;
			thread.Start();
		}
	}
	public class UsuarioIdentity : IUsuarioIdentity
	{
		public string AuthenticationType { get; } = string.Empty;

		public string IdEmpresa { get; }

		public string IdToken { get; } = string.Empty;

		public bool IsAuthenticated { get; }

		public string Name { get; } = string.Empty;

		public string NomeUsuario { get; }

		public IReadOnlyDictionary<string, string[]> Roles { get; } = new Dictionary<string, string[]>();

		public string[] RolesEmitente { get; } = new string[0];

		public UsuarioIdentity(string idEmpresa, string nomeUsuario)
		{
			IdEmpresa = idEmpresa;
