		public bool EcfServicePronto => !_ecfEmErro;

		public override bool Pronto
		{
			get
			{
				if (!DadosSistema.IsPostoCombustivel)
				{
					return base.Pronto;
				}
				return true;
			}
		}

		public TipoMovimentacao Tipo => TipoMovimentacao.NotaManual;

		public NotaManualService(IEcfService ecfService, IWService service, Otus.Modulo.PontoDeVendas.Interfaces.ITefService tefService, Otus.Modulo.PontoDeVendas.Interfaces.IShipayService shipayService)
			: base(service, shipayService, tefService)
		{
			_ecfService = ecfService;
			_tefService = tefService;
			((EmissorService)ecfService).WhenEmissorProntoEvent.Subscribe((EventArgs x) =>
			{
				_ecfEmErro = false;
				OnEmissorProntoEvent();
			});
			((EmissorService)ecfService).WhenEmissorErroEvent.Subscribe((string x) =>
			{
				OnEmissorEmErroEvent();
				if (DadosSistema.IsPostoCombustivel)
				{
					OnEmissorProntoEvent();
				}
				_ecfEmErro = true;
			});
			InicializarEmissor();
		}

