		public override void EmitirDocumentoFiscal(IEnumerable<Otus.Modulo.PontoDeVendas.ViewModels.ItemDocumentoFiscal> itens, ConsumidorLocal consumidor = null, AcrescimoDesconto acrescimoDesconto = null, params IMensagemPromocional[] mensagensPromocionais)
		{
			if (!_ecfEmErro)
			{
				_ecfService.EmitirDocumentoFiscal(itens, consumidor, acrescimoDesconto, mensagensPromocionais);
			}
		}

		public void EmitirCupomFiscal(ConsumidorLocal consumidor, IEnumerable<Otus.Modulo.PontoDeVendas.ViewModels.ItemDocumentoFiscal> itens, AcrescimoDesconto acrescimoDesconto, IEnumerable<IMensagemPromocional> mensagensPromocionais, IEnumerable<ItemPagamentoViewModel> pagamentos, IEnumerable<IDadoEmissor> parcelamento, IEnumerable<string> contraVale, IEnumerable<IDadoEmissor> seriaisVendido)
		{
			List<Otus.Modulo.PontoDeVendas.ViewModels.ItemDocumentoFiscal> list = itens.ToList();
			_ecfService.IdentificarConsumidor(consumidor);
			_ecfService.Abrir();
			foreach (Otus.Modulo.PontoDeVendas.ViewModels.ItemDocumentoFiscal item in list)
			{
				_ecfService.Vender(item);
				if (item.Desconto > 0m)
				{
					_ecfService.AplicarDesconto(item, item.Desconto);
				}
				if (item.Acrescimo > 0m)
				{
					_ecfService.AplicarAcrescimo(item, item.Acrescimo);
				}
				if (!item.Ativo)
				{
					_ecfService.CancelarItem(item.NumeroItem);
				}
			}
			try
			{
				_ecfService.Totalizar(acrescimoDesconto ?? Otus.Modulo.PontoDeVendas.ViewModels.Desconto.Criar());
			}
			catch (Exception ex)
			{
				ex.ShowLastException();
			}
			foreach (ItemPagamentoViewModel pagamento in pagamentos)
			{
				_ecfService.EfetuarPagamento(pagamento);
			}
			_ecfService.Finalizar(mensagensPromocionais.OrderBy((IMensagemPromocional x) => x.Indice));
			_tefService?.ImprimirNotaManual();
			_ecfService.AdicionarRelatorioGerencialParcelamento(parcelamento);
			_ecfService.AdicionarRelatorioGerencialContraVale(contraVale);
			_ecfService.AdicionarRelatorioGerencialSeriaisVendidos(seriaisVendido);
			_ecfService.ImprimirRelatorioGerencialParcelamento();
			_ecfService.ImprimirRelatorioGerencialContraVale();
			_ecfService.ImprimirRelatorioGerencialSeriaisVendidos();
		}

