	public class PafEcfService : IPafEcfService
	{
		private readonly IWService _service;

		private readonly ISessaoService _sessaoService;

		private readonly IArquivoAuxiliarService _arquivoAuxiliarService;

		private readonly IConfiguracaoClientService _configuracaoClientService;

		private readonly IRepositoryRead<MapaResumoLocal> _mapaResumoRepositoryRead;

		private readonly IRepositoryBaseWrite<MapaResumoLocal> _mapaResumoRepositoryWrite;

		private readonly IRepositoryBaseWrite<RegistroPafEcf> _registroRRepositoryPafBaseWrite;

		private readonly IRepositoryRead<RegistroPafEcf> _registroRRepositoryPafBaseRead;

		public PafEcfService(IWService service, ISessaoService sessaoService, IArquivoAuxiliarService arquivoAuxiliarService, IConfiguracaoClientService configuracaoClientService, IRepositoryRead<MapaResumoLocal> mapaResumoRepositoryRead, IRepositoryBaseWrite<MapaResumoLocal> mapaResumoRepositoryWrite, IRepositoryBaseWrite<RegistroPafEcf> registroRRepositoryPafBaseWrite, IRepositoryRead<RegistroPafEcf> registroRRepositoryPafBaseRead)
		{
			_service = service;
			_sessaoService = sessaoService;
			_arquivoAuxiliarService = arquivoAuxiliarService;
			_configuracaoClientService = configuracaoClientService;
			_mapaResumoRepositoryRead = mapaResumoRepositoryRead;
			_mapaResumoRepositoryWrite = mapaResumoRepositoryWrite;
			_registroRRepositoryPafBaseWrite = registroRRepositoryPafBaseWrite;
			_registroRRepositoryPafBaseRead = registroRRepositoryPafBaseRead;
		}

		public void SalvarReducaoZ(IEcfDadosReducaoZ dadosReducaoZ)
		{
			RegistroR02 registroR = RegistroR02.Criar();
			registroR.NumeroDeFabricacao = dadosReducaoZ.NumeroFabricacao;
			registroR.MfAdicional = dadosReducaoZ.MfAdicional;
			registroR.ModeloDoEcf = dadosReducaoZ.Modelo;
			registroR.CRZ = dadosReducaoZ.Crz;
			registroR.COO = dadosReducaoZ.Coo;
			registroR.CRO = dadosReducaoZ.Cro;
			registroR.DataDoMovimento = dadosReducaoZ.DataMovimento;
			registroR.DataHoraDeEmissao = dadosReducaoZ.DataHora;
			registroR.VendaBrutaDiaria = dadosReducaoZ.VendaBruta;
			registroR.GtFinal = dadosReducaoZ.GrandeTotal;
			registroR.NumeroCooInicial = dadosReducaoZ.PrimeiroCoo;
			registroR.NumeroCooFinal = dadosReducaoZ.Coo;
			registroR.NumeroDoUsuario = dadosReducaoZ.NumeroUsuario.ToString();
			registroR.NumeroDeOrdemSequencialDeEquipamento = dadosReducaoZ.NumeroEcf;
			registroR.ParametroDoEcfParaIncidenciaDeDescontoDoIssqn = ((!dadosReducaoZ.PermiteDescontoIss) ? ParametroDoEcfParaIncidenciaDeDescontoDoISSQN.Nao : ParametroDoEcfParaIncidenciaDeDescontoDoISSQN.Sim);
			SalvarRegistrosPafEcfReducaoZ<RegistroR02>(CriarRegistroR(registroR, registroR.DataDoMovimento));
			foreach (IEcfAliquota item in dadosReducaoZ.Totalizadores.Where((IEcfAliquota a) => a.Valor > 0m))
			{
				RegistroR03 registroR2 = CriarRegistroR03(dadosReducaoZ);
				registroR2.ValorAcumulado = item.Valor;
				registroR2.TotalizadorParcial = item.Tipo.RetornarDescricaoPeloValor<SiglaPafAttribute>();
				if (item.Tipo == Tributacao.IcmsTributado || item.Tipo == Tributacao.IssTributado)
				{
					registroR2.TotalizadorParcial = item.Id.ToStringLeftZero(2) + registroR2.TotalizadorParcial + item.Percentual.FormatarNumericoPafEcf(4, 2, removerFormatacao: true);
				}
				SalvarRegistroR03(CriarRegistroR(registroR2, registroR.DataDoMovimento));
			}
			if (dadosReducaoZ.DescontoIcms > 0m)
			{
				RegistroR03 registroR3 = CriarRegistroR03(dadosReducaoZ);
				registroR3.TotalizadorParcial = "DT";
				registroR3.ValorAcumulado = dadosReducaoZ.DescontoIcms;
				SalvarRegistroR03(CriarRegistroR(registroR3, registroR.DataDoMovimento));
			}
			if (dadosReducaoZ.DescontoIss > 0m)
			{
				RegistroR03 registroR4 = CriarRegistroR03(dadosReducaoZ);
				registroR4.TotalizadorParcial = "DS";
				registroR4.ValorAcumulado = dadosReducaoZ.DescontoIss;
				SalvarRegistroR03(CriarRegistroR(registroR4, registroR.DataDoMovimento));
			}
			if (dadosReducaoZ.AcrescimoIcms > 0m)
			{
				RegistroR03 registroR5 = CriarRegistroR03(dadosReducaoZ);
				registroR5.TotalizadorParcial = "AT";
				registroR5.ValorAcumulado = dadosReducaoZ.AcrescimoIcms;
				SalvarRegistroR03(CriarRegistroR(registroR5, registroR.DataDoMovimento));
			}
			if (dadosReducaoZ.AcrescimoIss > 0m)
			{
				RegistroR03 registroR6 = CriarRegistroR03(dadosReducaoZ);
				registroR6.TotalizadorParcial = "AS";
				registroR6.ValorAcumulado = dadosReducaoZ.AcrescimoIss;
				SalvarRegistroR03(CriarRegistroR(registroR6, registroR.DataDoMovimento));
			}
			if (dadosReducaoZ.CancelamentoIcms > 0m)
			{
				RegistroR03 registroR7 = CriarRegistroR03(dadosReducaoZ);
				registroR7.TotalizadorParcial = "Can-T";
				registroR7.ValorAcumulado = dadosReducaoZ.CancelamentoIcms;
				SalvarRegistroR03(CriarRegistroR(registroR7, registroR.DataDoMovimento));
			}
			if (dadosReducaoZ.CancelamentoIss > 0m)
			{
				RegistroR03 registroR8 = CriarRegistroR03(dadosReducaoZ);
				registroR8.TotalizadorParcial = "Can-S";
				registroR8.ValorAcumulado = dadosReducaoZ.CancelamentoIss;
				SalvarRegistroR03(CriarRegistroR(registroR8, registroR.DataDoMovimento));
			}
			if (dadosReducaoZ.TotalizadoresNaoFiscais.Sum((IEcfComprovanteNaoFiscal a) => a.Valor) > 0m)
			{
				RegistroR03 registroR9 = CriarRegistroR03(dadosReducaoZ);
				registroR9.TotalizadorParcial = "OPNF";
				registroR9.ValorAcumulado = dadosReducaoZ.TotalizadoresNaoFiscais.Sum((IEcfComprovanteNaoFiscal a) => a.Valor);
				SalvarRegistroR03(CriarRegistroR(registroR9, registroR.DataDoMovimento));
			}
			RegistroR06 registroR10 = RegistroR06.Criar();
			registroR10.NumeroDeFabricacao = dadosReducaoZ.NumeroFabricacao;
			registroR10.MfAdicional = dadosReducaoZ.MfAdicional;
			registroR10.ModeloDoEcf = dadosReducaoZ.Modelo;
			registroR10.NumeroDoUsuario = dadosReducaoZ.NumeroUsuario.ToString();
			registroR10.COO = dadosReducaoZ.Coo;
			registroR10.Denominacao = DenominacaoRegistroR06.ReducaoZ;
			registroR10.DataHoraFinalDeEmissao = dadosReducaoZ.DataHora;
			registroR10.Marca = dadosReducaoZ.Marca;
			SalvarRegistroR06(CriarRegistroR(registroR10, dadosReducaoZ.DataMovimento));
			SalvarMapaResumo(dadosReducaoZ);
		}

		private void SalvarRegistrosPafEcfReducaoZ<T>(RegistroR registroR)
		{
			RegistroPafEcf registroRbase = _registroRRepositoryPafBaseRead.FindOne(RegistroPafEcfSpecifications.PorNumeroFabricacao(registroR.NumeroFabricacao).PorDataMovimento(registroR.DataMovimento).PorTipoRegistro<T>());
			SalvarRegistroR(registroRbase, registroR);
		}

		private void SalvarRegistroR06(RegistroR registroR)
		{
			RegistroPafEcf registroRbase = _registroRRepositoryPafBaseRead.FindOne(RegistroPafEcfSpecifications.PorNumeroFabricacao(registroR.NumeroFabricacao).PorDataMovimento(registroR.DataMovimento).PorTipoRegistro<RegistroR06>()
				.PorRegistroR06Coo(registroR.Registro.To<RegistroR06>().COO));
			SalvarRegistroR(registroRbase, registroR);
		}

		private void SalvarRegistroR03(RegistroR registroR)
		{
			RegistroPafEcf registroRbase = _registroRRepositoryPafBaseRead.FindOne(RegistroPafEcfSpecifications.PorNumeroFabricacao(registroR.NumeroFabricacao).PorDataMovimento(registroR.DataMovimento).PorTipoRegistro<RegistroR03>()
				.PorTotalizadorParcial(registroR.Registro.To<RegistroR03>().TotalizadorParcial));
			SalvarRegistroR(registroRbase, registroR);
		}

		private void SalvarRegistroR(RegistroPafEcf registroRbase, RegistroR registroR)
		{
			if (registroRbase.IsNull())
			{
				_registroRRepositoryPafBaseWrite.Add(registroR);
			}
			else if (registroRbase.ChavePafValida)
			{
				_registroRRepositoryPafBaseWrite.Update(registroR.Atualizar(registroRbase));
			}
		}

		private RegistroR03 CriarRegistroR03(IEcfDadosReducaoZ dadosReducaoZ)
		{
			RegistroR03 registroR = RegistroR03.Criar();
			registroR.NumeroDeFabricacao = dadosReducaoZ.NumeroFabricacao;
			registroR.MfAdicional = dadosReducaoZ.MfAdicional.Trim();
			registroR.ModeloDoEcf = dadosReducaoZ.Modelo;
			registroR.NumeroDoUsuario = dadosReducaoZ.NumeroUsuario.ToString();
			registroR.CRZ = dadosReducaoZ.Crz;
			registroR.DataDoMovimento = dadosReducaoZ.DataMovimento;
			return registroR;
		}

		private void SalvarMapaResumo(IEcfDadosReducaoZ dadosReducaoZ)
		{
			IEnumerable<MapaResumoLocal> source = _mapaResumoRepositoryRead.Find(MapaResumoLocalSpecifications.All().PorNumeroFabricacao(dadosReducaoZ.NumeroFabricacao).PorDataMovimentoMenorIgual(dadosReducaoZ.DataMovimento.Date));
			MapaResumoLocal mapaResumoLocal = source.FirstOrDefault((MapaResumoLocal x) => x.DataMovimento.Date.Equals(dadosReducaoZ.DataMovimento.Date));
			MapaResumoLocal mapaResumoLocal2 = (from x in source
				where x.DataMovimento.Date < dadosReducaoZ.DataMovimento.Date
				orderby x.DataMovimento
				select x).LastOrDefault();
			MapaResumoLocal mapaResumoLocal3 = MapaResumoLocal.Criar().ComNumeroFabricacao(dadosReducaoZ.NumeroFabricacao).ComContadorReducaoZ(dadosReducaoZ.Crz)
				.ComContadorReinicioOperacao(dadosReducaoZ.Cro)
				.ComDataMovimento(dadosReducaoZ.DataMovimento)
				.ComNumeroCooFinal(dadosReducaoZ.Coo)
				.ComNumeroCooInicial((mapaResumoLocal2?.NumeroCooFinal ?? 0) + 1)
				.ComValorInicioDia(mapaResumoLocal2?.ValorFinalDia ?? 0m)
				.ComVendaBruta(dadosReducaoZ.VendaBruta)
				.ComAcrescimoIcms(dadosReducaoZ.AcrescimoIcms)
				.ComAcrescimoIss(dadosReducaoZ.AcrescimoIss)
				.ComAcrescimoNf(dadosReducaoZ.AcrescimoNf)
				.ComCancelamentoIcms(dadosReducaoZ.CancelamentoIcms)
				.ComCancelamentoIss(dadosReducaoZ.CancelamentoIss)
				.ComCancelamentoNf(dadosReducaoZ.CancelamentoNf)
				.ComCcd(dadosReducaoZ.Ccd)
				.ComCcf(dadosReducaoZ.Ccf)
				.ComDescontoIcms(dadosReducaoZ.DescontoIcms)
				.ComDescontoIss(dadosReducaoZ.DescontoIss)
				.ComDescontoNf(dadosReducaoZ.DescontoNf)
				.ComGnf(dadosReducaoZ.Gnf)
				.ComGrg(dadosReducaoZ.Grg)
				.ComValorFinalDia(dadosReducaoZ.GrandeTotal)
