		public void GerarArquivoRegistrosPafEcf(DateTime dataInicial, DateTime dataFinal, IEnumerable<string> ids = null, bool completo = false)
		{
			string numeroFabricacaoEcf = _arquivoAuxiliarService.NumeroFabricacaoEcf;
			GeradorArquivoRegistrosPafEcfDto parametros = new GeradorArquivoRegistrosPafEcfDto
			{
				DataInicial = dataInicial,
				DataFinal = dataFinal,
				NumeroFabricacao = numeroFabricacaoEcf,
				ProdutoServicoReferencias = ids.ToListEmptyWhenNull(),
				Completo = completo
			};
			ConfiguracaoClient configuracaoClient = _configuracaoClientService.ObterConfiguracao();
			if (configuracaoClient.Ecf == null)
			{
				throw new SemConfiguracaoEcfException();
			}
			string codigoNacionalIdentificacao = configuracaoClient.Ecf.CodigoNacionalIdentificacao;
			string arg = (string.IsNullOrWhiteSpace(codigoNacionalIdentificacao) ? "ConfigureOCodigoNacionalDeIdentificacao" : codigoNacionalIdentificacao);
			string nomeArquivo = $"{arg}" + $"{numeroFabricacaoEcf.CopiarTextoDaDireitaParaEsquerda(14)}" + $"{dataInicial:ddMMyyyy}.txt";
			Task<IEnumerable<string>> task = _service.Canal((IGeradorArquivoRegistrosPafEcfModuleService x) => x.ObterLinhasParaGeracaoDoArquivoAsync(parametros));
			string text = Path.Combine(AppDomain.CurrentDomain.BaseDirectory, "Fiscal");
			string path = TxtFile.Criar().ComConteudo(task.Result).ComNomeArquivo(nomeArquivo)
				.ComDiretorioArquivo(text)
				.Build()
				.Gerar();
			string text2 = Path.Combine(text, path);
			Assinaturas.AdicionarAssinaturaPafEcfArquivo(Assinaturas.CalcularAssinaturaPafecfArquivo(Hash.RetornarChavePrivadaInformacaoDecifrada(), text2), text2);
			if (!completo && DadosSistema.UFEmpresaLogada.DeveTransmitirArquivoRegistrosPafEcfRequisitoLXI())
			{
				CompactarArquivoRegistrosPafEcf(text2, nomeArquivo);
			}
			DialogoFactory.MostrarDialogoConfirma($"Arquivo {text2} gerado com sucesso.");
		}

		private void CompactarArquivoRegistrosPafEcf(string diretorioArquivo, string nomeArquivo)
		{
			string text = nomeArquivo.Replace("txt", "zip");
			Path.Combine(AppDomain.CurrentDomain.BaseDirectory, "Fiscal", "Arquivos Requisito XXVI", "Pendente", text).CompactarArquivos(new string[1] { diretorioArquivo });
		}

		public void VerificarTransmissaoRegistrosPafEcf()
		{
			IEnumerable<string> source = ObterArquivosPendentes();
			if (source.Any())
			{
				DialogoFactory.MostrarDialogoConfirma($"HÁ {source.Count()} ARQUIVOS REQUISITO XXVI PENDENTES DE TRANSMISSÃO AO FISCO. " + "O CONTRIBUINTE PODE GERAR A REMESSA ATRAVÉS DO MENU FISCAL POR MEIO DO COMANDO 'TRANSMITIR ARQUIVOS REQUISITO XXVI'.");
			}
		}

		private IEnumerable<string> ObterArquivosPendentes()
		{
			string text = Path.Combine(AppDomain.CurrentDomain.BaseDirectory, "Fiscal", "Arquivos Requisito XXVI", "Pendente");
			VerificarDiretorio(text);
			return Directory.GetFiles(text);
		}

		private void VerificarDiretorio(string diretorio)
		{
			if (!Directory.Exists(diretorio))
			{
				Directory.CreateDirectory(diretorio);
			}
		}

		public void GerarArquivosRemessaRegistrosPafEcf()
		{
			IEnumerable<string> enumerable = ObterArquivosPendentes();
			if (!enumerable.Any())
			{
				DialogoFactory.MostrarDialogoConfirma("Nenhum arquivo pendente.");
				return;
			}
			string text = DateTime.Now.ToString("ddMMyyyy_HHmmss");
			string text2 = Path.Combine(AppDomain.CurrentDomain.BaseDirectory, "Fiscal", "Arquivos Requisito XXVI", "Remessa", text);
			VerificarDiretorio(text2);
			foreach (string item in enumerable)
			{
				string fileName = Path.GetFileName(item);
				File.Move(item, Path.Combine(text2, fileName));
			}
			DialogoFactory.MostrarDialogoConfirma($"Arquivos da remessa gerados com sucesso em {text2}.");
		}
	}
