	public class PostoService : IPostoService
	{
		private readonly PontoDeVendaClientActorSystem _actorSystem;

		private readonly IEventPublisher _eventPublisher;

		private readonly IWService _service;

		public PostoService(IClientActorSystem actorSystem, IEventPublisher eventPublisher, IWService service)
		{
			_actorSystem = actorSystem as PontoDeVendaClientActorSystem;
			_eventPublisher = eventPublisher;
			_service = service;
			eventPublisher.GetEvent<CancelouItemEvent>(ProcessarAbastecimentoItemCancelado);
			eventPublisher.GetEvent<CancelouPreDocumentoFiscalEvent>(ProcessarAbastecimentoCancelado);
			eventPublisher.GetEvent<AutenticouEvent>(ProcessarAutenticacao);
			eventPublisher.GetEvent<ExecutouLogOffEvent>(ProcessarLogOff);
		}

		private void ProcessarLogOff(ExecutouLogOffEvent obj)
		{
			Desconectar();
		}

		private void ProcessarAutenticacao(AutenticouEvent obj)
		{
			Conectar();
		}

		public void Criar()
		{
			_actorSystem.Iniciar();
		}

		public void Desconectar()
		{
			_actorSystem.Desconectar();
		}

		public void Conectar()
		{
			_actorSystem.Conectar();
		}

		private void ProcessarAbastecimentoItemCancelado(CancelouItemEvent obj)
		{
			ItemDocumentoFiscalCombustivel item = obj.ItemDocumentoFiscal as ItemDocumentoFiscalCombustivel;
			if (item == null)
			{
				return;
			}
			if (obj.EmissorService.Tipo == TipoMovimentacao.CupomFiscal)
			{
				_service.Canal((IPostoCombustivelModuleService x) =>
				{
					x.AtualizarStatusAbastecimentosCancelado(new string[1] { item.Abastecimento.Id });
				});
			}
			else
			{
				_eventPublisher.Publish(new TornarAbastecimentosPendentesRequest(new string[1] { item.Abastecimento.Id }));
			}
		}

		private void ProcessarAbastecimentoCancelado(CancelouPreDocumentoFiscalEvent @event)
		{
			if (@event.PreDocumentoFiscal.IsNotNull())
			{
				IEnumerable<ItemDocumentoFiscalCombustivel> itens = @event.PreDocumentoFiscal.Itens.OfType<ItemDocumentoFiscalCombustivel>();
				if (!itens.Any())
				{
					return;
				}
				if (@event.EmissorService.Tipo == TipoMovimentacao.CupomFiscal)
				{
					_service.Canal((IPostoCombustivelModuleService x) =>
					{
						x.AtualizarStatusAbastecimentosCancelado(itens.Select((ItemDocumentoFiscalCombustivel y) => y.Abastecimento.Id));
					});
				}
				else
				{
					_eventPublisher.Publish(new TornarAbastecimentosPendentesRequest(itens.Select((ItemDocumentoFiscalCombustivel y) => y.Abastecimento.Id).ToListEmptyWhenNull()));
				}
			}
			else
			{
				if (string.IsNullOrWhiteSpace(@event.IdentificadorDocumento))
				{
					return;
				}
				if (@event.EmissorService.Tipo == TipoMovimentacao.CupomFiscal)
				{
					string numeroFabricacao = @event.EmissorService.RetornarNumeroFabricacao();
					_service.Canal((IPostoCombustivelModuleService x) =>
					{
						x.AtualizarStatusAbastecimentosCupomFiscal(@event.EmissorService.Tipo, @event.IdentificadorDocumento, numeroFabricacao);
					});
				}
				else
				{
					IEnumerable<string> collection = _service.Canal((IPostoCombustivelModuleService service) => service.ObterAbastecimentosPorMovimentacao(@event.EmissorService.Tipo, @event.IdentificadorDocumento));
					_eventPublisher.Publish(new TornarAbastecimentosPendentesRequest(collection.ToListEmptyWhenNull()));
				}
			}
		}
	}
