		private void ImprimirRegistroVenda(RegistroVendaImpresso registroVendaImpresso)
		{
			try
			{
				LoaderProcessoService.MostrarLoader("Imprimindo...");
				int numeroVias = DadosSistema.ConfiguracaoDto.Saida.NumeroViasRegistroVenda.Valor;
				if (numeroVias <= 0 || (DadosSistema.ConfiguracaoDto.Saida.SolicitarImpressao.Valor && DialogoFactory.MostrarDialogoSimNao("Deseja imprimir o registro de venda?") != MessageBoxResult.Yes))
				{
					return;
				}
				IRelatorio relatorio2;
				if (!DadosSistema.ConfiguracaoDto.Saida.ImprimirDanfeNfceEmFolhaA4.Valor)
				{
					if (DadosSistema.TamanhoBobina != TamanhoBobina.CinquentaESeisCinquentaESeteCinquentaEOitoMilimetros)
					{
						IRelatorio relatorio = new RelatorioRegistroVenda79Mm80Mm(registroVendaImpresso, DadosSistema.ImprimirItemResumidoEm40Colunas, DadosSistema.MargemEsquerdaImpressoraNaoFiscal, DadosSistema.RollPaper, DadosSistema.EmpresaLogada.Imagem);
						relatorio2 = relatorio;
					}
					else
					{
						IRelatorio relatorio = new RelatorioRegistroVenda56Mm57Mm58Mm(registroVendaImpresso, DadosSistema.ImprimirItemResumidoEm40Colunas, DadosSistema.MargemEsquerdaImpressoraNaoFiscal, DadosSistema.RollPaper, DadosSistema.EmpresaLogada.Imagem);
						relatorio2 = relatorio;
					}
				}
				else
				{
					IRelatorio relatorio = new RelatorioRegistroVendaA4(registroVendaImpresso, DadosSistema.EmpresaLogada.Imagem);
					relatorio2 = relatorio;
				}
				IRelatorio impresso = relatorio2;
				Task.Factory.StartNew(() =>
				{
					for (int i = 0; i < numeroVias; i++)
					{
						_impressoraNaoFiscalService.Imprimir(impresso);
					}
				});
			}
			catch (Exception ex)
			{
				ex.ShowLastException();
			}
			finally
			{
				LoaderProcessoService.EsconderLoader();
			}
		}

		public override void Cancelar(IEstadoDocumentoFiscal estadoDocumentoFiscal, Autorizacao autorizacao)
		{
			if (!estadoDocumentoFiscal.Is<DocumentoFiscalFechado>())
			{
				OnDocumentoFiscalCanceladoEvent();
				return;
