			if (_numeroDocumento == 0L)
			{
				throw new Exception("Documento inválido. Faça o cancelamento na lista de movimentações!");
			}
			CancelarComAutorizacao(_numeroDocumento, autorizacao);
			_numeroDocumento = 0L;
		}

