		private void CancelarComAutorizacao(long numero, Autorizacao autorizacao = null)
		{
			OnEmissorAvisoEvent("Cancelando NFC-e...");
			ThreadPrincipal.Executar(() =>
			{
				LoaderProcessoService.MostrarLoader("Cancelando NFC-e...");
			});
			DispatcherHelper.DoEvents();
			if (autorizacao == null && _sessaoService.VerificarPermissao<DigisatServer.Infrastructure.Crosscutting.Module.PontoDeVenda, PermitirCancelarDocumentoFiscal>() == null)
			{
				return;
			}
			RegistroVenda registroVenda = _movimentacaoRepositoryRead.FindOne(MovimentacaoSpecification.PorTipo<RegistroVenda>().PorNumero(numero)) as RegistroVenda;
			if (registroVenda.IsNull())
			{
				DialogoFactory.MostrarDialogoConfirma("Esse registro de venda deve ser cancelado em Saídas > Movimentações de saída");
				return;
			}
			registroVenda?.Cancelar(autorizacao);
			decimal num = registroVenda.Pagamentos?.Where((ItemPagamento x) => x.EspeciePagamento.Codigo == 1).Sum((ItemPagamento x) => x.Valor) ?? 0m;
			if (num > 0m)
			{
				new ValorSangriaService(_valorSangriaRepositoryWrite, _valorSangriaRepositoryRead).AlterarValor(num, aumentar: false);
			}
			_movimentacaoRepositoryWrite.Update(registroVenda);
			ImprimirRegistroVenda(registroVenda.ObterImpresso());
			IEnumerable<ItemPagamento> pagamentos = registroVenda.Pagamentos;
			if (pagamentos != null && pagamentos.OfType<ItemPagamentoCarteiraDigital>().Any())
			{
				EstornarPagamentosDigitais(registroVenda.Pagamentos.OfType<ItemPagamentoCarteiraDigital>().SelectMany((ItemPagamentoCarteiraDigital pagamentoCarteiraDigital) => pagamentoCarteiraDigital.InformacoesTransacao.Select((InformacaoTransacaoCarteiraDigital transacaoCarteiraDigital) => transacaoCarteiraDigital.Nsu)));
			}
			IEnumerable<ItemPagamento> pagamentos2 = registroVenda.Pagamentos;
			if (pagamentos2 != null && pagamentos2.OfType<ItemPagamentoCartao>().Any())
			{
				CancelarTransacaoTef(new List<InformacaoTransacao>(registroVenda.Pagamentos?.OfType<ItemPagamentoCartao>().Where((ItemPagamentoCartao x) => x.InformacoesTransacao.Any() && x.EspeciePagamento.Codigo != 27 && !x.InformacoesTransacao.All((InformacaoTransacaoTef y) => y.CodigoAutorizacaoTransacao.IsNullOrEmpty())).SelectMany((ItemPagamentoCartao x) => x.InformacoesTransacao.Select((InformacaoTransacaoTef y) => new InformacaoTransacao(y.Rede, y.Nsu, y.Valor)))));
			}
			IEnumerable<ItemPagamento> pagamentos3 = registroVenda.Pagamentos;
			if (pagamentos3 != null && pagamentos3.OfType<ItemPagamentoCarteiraDigital>().Any())
			{
				CancelarTransacaoTef(new List<InformacaoTransacao>(registroVenda.Pagamentos?.OfType<ItemPagamentoCarteiraDigital>().Where((ItemPagamentoCarteiraDigital x) => x.InformacoesTransacao.Any() && x.EspeciePagamento.Codigo != 27 && x.InformacoesTransacao.Any((InformacaoTransacaoCarteiraDigital y) => y.CodigoAutorizacaoTransacao != 0) && x.InformacoesTransacao.Any((InformacaoTransacaoCarteiraDigital y) => y.IsNsuValidoCancelamentoShipay)).SelectMany((ItemPagamentoCarteiraDigital x) => x.InformacoesTransacao.Select((InformacaoTransacaoCarteiraDigital y) => new InformacaoTransacao(y.Rede, y.Nsu, y.Valor)))));
			}
			ThreadPrincipal.Executar(LoaderProcessoService.EsconderLoader);
		}

		public void Cancelar(long numero)
		{
