		}

		public void Imprimir(long numero)
		{
			if (_sessaoService.VerificarPermissao<DigisatServer.Infrastructure.Crosscutting.Module.PontoDeVenda, PermitirReimprimirDocumentoFiscal>() == null)
			{
				return;
			}
			RegistroVendaImpresso registroVendaImpresso;
			if (_movimentacaoRepositoryRead.FindOne(MovimentacaoSpecification.PorTipo<RegistroVenda>().PorNumero(numero)) is RegistroVenda registroVenda)
			{
				registroVendaImpresso = registroVenda.ObterImpresso();
			}
			else
			{
				MovimentacaoDto result = _service.Canal((IMovimentacaoSaidaModuleService service) => service.ObterPorNumeroOrigem(numero, 15)).Result;
				registroVendaImpresso = ObterRegistroVendaImpresso(result);
			}
			if (registroVendaImpresso.IsNull())
			{
				throw new Exception($"Registro de venda número {numero} não pode ser impresso.");
			}
			ImprimirRegistroVenda(registroVendaImpresso);
		}

		private RegistroVendaImpresso ObterRegistroVendaImpresso(MovimentacaoDto dto)
		{
			if (dto.Is<MovimentacaoDtoNull>())
			{
				return null;
			}
			bool cancelado = dto.Situacao.Codigo == 4;
			IEnumerable<ItemRegistroVendaImpresso> itens = dto.Itens.Select((ItemDto i) => ItemRegistroVendaImpresso.Criar().ComNumero(i.Numero).ComCodigo(i.ProdutoServico.CodigoInterno)
				.ComBarras(i.ProdutoServico?.Produto?.CodigoBarras ?? string.Empty)
				.ComDescricao(i.ProdutoServico.Descricao)
				.ComUnidadeMedida(i.ProdutoServico.UnidadeMedida.Sigla)
				.ComQuantidade(i.Quantidade)
				.ComPrecoUnitario(i.PrecoUnitario)
				.ComDesconto(i.TotalDesconto)
				.ComTotal(i.TotalLiquido)
				.ComCancelado(i.Cancelado)
				.ComAcrescimo(i.TotalOutrasDespesas)
				.ComTotalBruto(i.TotalBruto)
				.ComObservacao(i.ObservacaoDigitada)
				.Build());
			IEnumerable<ItemPagamentoRegistroVendaImpresso> pagamentos = from i in dto.ItensPagamentos
				where i.Valor > 0m
				select ItemPagamentoRegistroVendaImpresso.Criar().ComDescricao(RetornarDescricao(i)).ComValor(i.Valor)
					.ComValorDigitado(i.ValorDigitado)
					.Build();
			return RegistroVendaImpresso.Criar().ComNumero(dto.Numero).ComCancelado(cancelado)
				.ComNomeEmpresa(dto.Empresa.Nome)
				.ComDocumentoEmpresa(dto.Empresa.CpfCnpjFormatado)
				.ComDataEmissao(dto.DataHoraEmissao)
				.ComEnderecoEmpresa(dto.Empresa.EnderecoPrincipal.IsNot<EnderecoDtoNull>() ? ($"{dto.Empresa.EnderecoPrincipal.Logradouro}, {dto.Empresa.EnderecoPrincipal.Numero} {dto.Empresa.EnderecoPrincipal.Complemento} {dto.Empresa.EnderecoPrincipal.Bairro} " + $"{dto.Empresa.EnderecoPrincipal.Municipio?.Nome}-{dto.Empresa.EnderecoPrincipal.Municipio?.UF?.Sigla}") : string.Empty)
				.ComTelefoneEmpresa(dto.Empresa.TelefonePrincipal.Numero)
				.ComNomeCliente(dto.Pessoa.Nome)
				.ComDocumentoCliente(string.IsNullOrEmpty(dto.Pessoa.CpfCnpjFormatado) ? string.Empty : dto.Pessoa.CpfCnpjFormatado)
				.ComEnderecoCliente(dto.Pessoa.EnderecoPrincipal.IsNot<EnderecoDtoNull>() ? ($"Endereço: {dto.Pessoa.EnderecoPrincipal.Logradouro}, {dto.Pessoa.EnderecoPrincipal.Numero} {dto.Pessoa.EnderecoPrincipal.Complemento} {dto.Pessoa.EnderecoPrincipal.Bairro} " + $"{dto.Pessoa.EnderecoPrincipal.Municipio?.Nome}-{dto.Pessoa.EnderecoPrincipal.Municipio?.UF?.Sigla}") : string.Empty)
				.ComTelefoneCliente(string.IsNullOrEmpty(dto.Pessoa.TelefonePrincipal.Numero) ? string.Empty : $"Telefone: {dto.Pessoa.TelefonePrincipal.Numero}")
				.ComItens(itens)
				.ComPagamentos(pagamentos)
				.ComDesconto(dto.TotalDescontoAplicado)
				.ComAcrescimo(dto.TotalOutrasDespesas)
				.ComTotal(dto.Total)
				.ComTotalRecebido(dto.ItensPagamentos.Sum((ItemPagamentoDto x) => x.ValorDigitado))
				.ComTroco(dto.Troco)
				.ComSubTotal(dto.TotalProdutos + dto.TotalServicos)
				.ComObservacao(dto.Observacao)
				.ComFrete(dto.TotalFrete)
				.Build();
		}

		private static string RetornarDescricao(ItemPagamentoDto i)
		{
			if (i.EspeciePagamento.Codigo == 24)
			{
				IEnumerable<InformacaoTransacaoCarteiraDigitalDto> informacoesTransacaoCarteriaDigital = i.InformacoesTransacaoCarteriaDigital;
				if (informacoesTransacaoCarteriaDigital != null && informacoesTransacaoCarteriaDigital.Any((InformacaoTransacaoCarteiraDigitalDto x) => x.Rede.ToLower().Contains("pix")) && (i.InformacoesTransacaoCarteriaDigital?.Any((InformacaoTransacaoCarteiraDigitalDto x) => !x.EndToEndId.IsNullOrEmpty())).Value)
				{
					return "PagInst(PIX)Dinâmico";
				}
			}
			if (i.EspeciePagamento.Codigo == 24)
			{
				IEnumerable<InformacaoTransacaoCarteiraDigitalDto> informacoesTransacaoCarteriaDigital2 = i.InformacoesTransacaoCarteriaDigital;
				if (informacoesTransacaoCarteriaDigital2 != null && informacoesTransacaoCarteriaDigital2.Any((InformacaoTransacaoCarteiraDigitalDto x) => x.Rede.ToLower().Contains("pix")) && (i.InformacoesTransacaoCarteriaDigital?.All((InformacaoTransacaoCarteiraDigitalDto x) => x.EndToEndId.IsNullOrEmpty())).Value)
				{
					return "PagInst(PIX)Estático";
				}
			}
			if (i.EspeciePagamento.Codigo != 2 || !i.InformacoesTransacaoTef.Any((InformacaoTransacaoTefDto x) => x.Debito))
			{
				if (i.EspeciePagamento.Codigo != 2 || !i.InformacoesTransacaoTef.Any((InformacaoTransacaoTefDto x) => !x.Debito))
				{
					return i.EspeciePagamento.Descricao;
				}
				return "Cartão de crédito";
			}
			return "Cartão de débito";
		}

		public override void EfetivouPreDocumentoFiscal(Movimentacao movimentacao)
		{
			MovimentacaoDto dto = movimentacao.ProjectedAsDto();
			RegistroVendaImpresso registroVendaImpresso = ObterRegistroVendaImpresso(dto);
			ImprimirRegistroVenda(registroVendaImpresso);
			base.EfetivouPreDocumentoFiscal(movimentacao);
			DormirAsync(2000, (object x) =>
			{
				ImprimirTicketTroca(dto);
				ImprimirValoresCliente(dto);
				ThreadPrincipal.Executar(() =>
				{
					ImpressaoBoletoService.Init().ComBoletoProxyService(_boletoProxyService).VerificarImpressaoBoletos(dto);
				});
			});
		}

