		private void ImprimirTicketTroca(MovimentacaoDto movimentacao)
		{
			try
			{
				if (DadosSistema.ConfiguracaoDto.Saida.SolicitarImpressaoTicketTroca.Valor && DialogoFactory.MostrarDialogoSimNao("Deseja imprimir o ticket de troca?") == MessageBoxResult.Yes)
				{
					IRelatorio relatorio2;
					if (DadosSistema.TamanhoBobina != TamanhoBobina.CinquentaESeisCinquentaESeteCinquentaEOitoMilimetros)
					{
						IRelatorio relatorio = new RelatorioTicketTroca79Mm80Mm(movimentacao, DadosSistema.MargemEsquerdaImpressoraNaoFiscal, DadosSistema.RollPaper);
						relatorio2 = relatorio;
					}
					else
					{
						IRelatorio relatorio = new RelatorioTicketTroca56Mm57Mm58Mm(movimentacao, DadosSistema.MargemEsquerdaImpressoraNaoFiscal, DadosSistema.RollPaper);
						relatorio2 = relatorio;
					}
					IRelatorio relatorio3 = relatorio2;
					_impressoraNaoFiscalService.Imprimir(relatorio3);
				}
			}
			catch (Exception ex)
			{
				ex.ShowLastException();
			}
		}

		private void ImprimirValoresCliente(MovimentacaoDto movimentacao)
		{
			try
			{
				if ((!DadosSistema.ConfiguracaoDto.Saida.ImprimirSaldoDevedorAposVenda.Valor || !DadosSistema.ConfiguracaoDto.Saida.ImprimirCashbackDisponivelAposVenda.Valor) && movimentacao.Pessoa.ConsumidorReservadoSistema)
				{
					return;
				}
				bool valor = DadosSistema.ConfiguracaoDto.Saida.ImprimirSaldoDevedorAposVenda.Valor;
				bool valor2 = DadosSistema.ConfiguracaoDto.Saida.ImprimirCashbackDisponivelAposVenda.Valor;
				decimal num = (valor ? _service.Canal((IRecebimentoModuleService service) => service.ObterSaldoDevedor(movimentacao.Pessoa.Id)) : 0m);
				decimal num2 = (valor2 ? _service.Canal((IPessoaModuleService service) => service.ObterItensCreditoDebitoCashback(movimentacao.Pessoa.Id)).Sum((ItemCreditoDebitoCashbackDto item) => item.Valor) : 0m);
				if (!(num <= 0m) || !(num2 <= 0m))
				{
					IRelatorio relatorio2;
					if (DadosSistema.TamanhoBobina != TamanhoBobina.CinquentaESeisCinquentaESeteCinquentaEOitoMilimetros)
					{
						IRelatorio relatorio = new RelatorioValoresCliente79Mm80Mm(movimentacao.Pessoa, num, num2, DadosSistema.MargemEsquerdaImpressoraNaoFiscal, DadosSistema.RollPaper, valor, valor2);
						relatorio2 = relatorio;
					}
					else
					{
						IRelatorio relatorio = new RelatorioValoresCliente56Mm57Mm58Mm(movimentacao.Pessoa, num, num2, DadosSistema.MargemEsquerdaImpressoraNaoFiscal, DadosSistema.RollPaper, valor, valor2);
						relatorio2 = relatorio;
					}
					IRelatorio relatorio3 = relatorio2;
					_impressoraNaoFiscalService.Imprimir(relatorio3);
				}
			}
			catch (Exception ex)
			{
				ex.ShowLastException();
			}
		}
	}
	public class ShipayService : Otus.Modulo.PontoDeVendas.Interfaces.IShipayService
	{
		private ShipayApiService _api;

		private IPixPinPad _pinpad;

		private readonly ShipayDePagarService _dePagar = new ShipayDePagarService("PDV");

		public event EventHandler<OrderResponse> PagamentoCriadoEvent;

		public event EventHandler<OrderStatusResponse> PagamentoAprovadoEvent;

		public event EventHandler<OrderStatusResponse> PagamentoCanceladoEvent;

		public event EventHandler<OrderStatusResponse> PagamentoExpiradoEvent;

		public event EventHandler<Exception> ErroEvent;

		public ShipayService(IEventPublisher eventPublisher)
		{
			eventPublisher.GetEvent<ConfiguracaoDto>(CriarApiService);
			CriarApiService(DadosSistema.ConfiguracaoDto);
			ShipayLog.Init();
		}

		private void CriarApiService(ConfiguracaoDto configuracao)
		{
			try
			{
				if (configuracao.IsNotNull())
				{
					_api = new ShipayApiService(configuracao.Geral.AccessKeyShipay.Valor, configuracao.Geral.SecretKeyShipay.Valor, DadosSistema.ObterProxy());
				}
				else
				{
					ConfiguracaoOffline configuracaoOffline = ConfiguracaoOffline.Carregar();
					if (configuracaoOffline.PdvOfflineValido && DadosSistema.HabilitacaoLocalContemModuloPdvOffline())
					{
						_api = new ShipayApiService(configuracaoOffline.AccessKeyShipay, configuracaoOffline.SecretKeyShipay, DadosSistema.ObterProxy());
					}
				}
				_pinpad = new ShipayDefault((string message) =>
				{
					ShipayLog.CriarLog($"[PIX7] {message}", erro: false);
				});
			}
			catch (Exception ex)
			{
				ex.ShowLastException();
			}
		}

		public async Task<IEnumerable<Wallet>> ObterCarteiras()
		{
			IEnumerable<Wallet> enumerable = ((!DadosSistema.UtilizarShipayDePagar) ? (await ObterCarteirasShipay()) : (await _dePagar.ObterCarteiras()));
			IEnumerable<Wallet> enumerable2 = enumerable;
			if (enumerable2 == null || !enumerable2.Any())
			{
				throw new Exception("Acesse o Painel Shipay e configure as carteiras digitais.");
			}
			if (enumerable2.Any((Wallet wallet) => wallet.active))
			{
				return enumerable2.Where((Wallet wallet) => wallet.active);
			}
			throw new Exception("Nenhuma carteira digital ativa. Acesse o Painel Shipay e configure as carteiras digitais.");
		}

		private async Task<IEnumerable<Wallet>> ObterCarteirasShipay()
		{
			await Autenticar();
			return (await _api.GetAsync<WalletsResponse>(Wallet.Criar()))?.wallets;
		}

		public async Task Pagar(PreDocumentoFiscal preDocumentoFiscal, decimal valor, string wallet)
		{
			await Pagar(preDocumentoFiscal.Morfar(valor, wallet));
		}

		public async Task Pagar(ConsumidorLocal consumidor, decimal valor, string wallet)
		{
			await Pagar(consumidor.Morfar(valor, wallet));
		}

		private async Task Pagar(Order order)
		{
			if (DadosSistema.UtilizarShipayDePagar)
			{
				OrderResponse orderResponse = await _dePagar.CriarCobranca(order);
				OnPagamentoCriadoEvent(orderResponse);
				ApresentarQrCodeNoPinPad(orderResponse.qr_code_text);
				MonitorarCobrancaDePagar(orderResponse.order_id);
			}
			else
			{
				await Autenticar();
				OrderResponse orderResponse2 = await _api.PostAsync<OrderResponse>(order);
				OnPagamentoCriadoEvent(orderResponse2);
				ApresentarQrCodeNoPinPad(orderResponse2.qr_code_text);
				MonitorarResposta(orderResponse2.order_id);
			}
		}

		private void ApresentarQrCodeNoPinPad(string qrCodeText)
		{
			Task.Run(() =>
			{
				_pinpad.ApresentaQrCode(qrCodeText);
			}).ContinueWith((Task tarefa) =>
			{
				Exception ex = tarefa.Exception.Flatten().InnerException ?? tarefa.Exception;
				ShipayLog.CriarLog($"Falha ao apresentar o QR Code no PinPad: {ex.Message}", erro: true);
			}, TaskContinuationOptions.OnlyOnFaulted);
		}

		private void MonitorarResposta(string orderId, string statusAnterior = null)
		{
			new Thread(() =>
			{
				Esperar(() =>
				{
					ConsultarStatus(orderId, statusAnterior);
				});
			}).Start();
		}

		private void Esperar(Action consulta)
		{
			Thread.Sleep(TimeSpan.FromSeconds(2.0));
			consulta();
		}

		private async void ConsultarStatus(string orderId, string statusAnterior)
		{
			try
			{
				OrderStatusResponse orderStatusResponse = default;
				_ = orderStatusResponse;
				orderStatusResponse = await _api.GetAsync<OrderStatusResponse>(OrderStatus.Criar().Comorder_id(orderId));
				if (orderStatusResponse.status != statusAnterior)
				{
					ShipayLog.CriarLog($"{orderStatusResponse.toString()}", erro: false);
				}
				switch (orderStatusResponse.status)
				{
				case "approved":
					ThreadPrincipal.Executar(() =>
					{
						OnPagamentoAprovadoEvent(orderStatusResponse);
					});
					break;
				case "cancelled":
					ThreadPrincipal.Executar(() =>
					{
						OnPagamentoCanceladoEvent(orderStatusResponse);
					});
					break;
				case "expired":
					ThreadPrincipal.Executar(() =>
					{
						OnPagamentoExpiradoEvent(orderStatusResponse);
					});
					break;
				default:
					Esperar(() =>
					{
						ConsultarStatus(orderId, orderStatusResponse.status);
					});
					break;
				}
			}
			catch (Exception ex)
			{
				Exception ex2 = ex;
				Exception e = ex2;
				ThreadPrincipal.Executar(() =>
				{
					if (DialogoFactory.MostrarDialogoSimNao($"{e.GetLastException().Message}. Tentar novamente?") == MessageBoxResult.Yes)
					{
						MonitorarResposta(orderId, statusAnterior);
					}
				});
			}
		}

		private async void MonitorarCobrancaDePagar(string idCobranca)
		{
			try
			{
				OrderStatusResponse orderStatusResponse = default;
				_ = orderStatusResponse;
				orderStatusResponse = await _dePagar.AguardarPagamento(idCobranca);
				ShipayLog.CriarLog($"{orderStatusResponse.toString()}", erro: false);
				string status = orderStatusResponse.status;
				if (!(status == "approved"))
				{
					if (status == "expired")
					{
						ThreadPrincipal.Executar(() =>
						{
							OnPagamentoExpiradoEvent(orderStatusResponse);
						});
					}
					else
					{
						ThreadPrincipal.Executar(() =>
						{
							OnPagamentoCanceladoEvent(orderStatusResponse);
						});
					}
				}
				else
				{
					ThreadPrincipal.Executar(() =>
					{
						OnPagamentoAprovadoEvent(orderStatusResponse);
					});
				}
			}
			catch (Exception ex)
			{
				Exception ex2 = ex;
				Exception e = ex2;
				ThreadPrincipal.Executar(() =>
				{
					if (DialogoFactory.MostrarDialogoSimNao($"{e.GetLastException().Message}. Tentar novamente?") == MessageBoxResult.Yes)
					{
						MonitorarCobrancaDePagar(idCobranca);
					}
				});
			}
		}

		public async Task CancelarPagamento(string orderId)
		{
			if (DadosSistema.UtilizarShipayDePagar)
			{
				await _dePagar.CancelarCobranca(orderId);
				return;
			}
			await Autenticar();
			await _api.DeleteAsync<OrderStatusResponse>(orderId);
		}

		public async Task EstornarPagamento(string orderId)
		{
			if (DadosSistema.UtilizarShipayDePagar)
			{
				await _dePagar.EstornarCobranca(orderId);
			}
			else
			{
				await CancelarPagamento(orderId);
			}
		}

		private async Task Autenticar()
		{
			ConfiguracaoShipay configuracaoShipay = ObterConfiguracao();
			await _api.Autenticar(configuracaoShipay.ClientId, configuracaoShipay.Token, configuracaoShipay.IsTokenValid, configuracaoShipay.RefreshToken, AtualizarToken);
		}

		private static ConfiguracaoShipay ObterConfiguracao()
		{
			ConfiguracaoShipay configuracaoShipay = ConfiguracaoShipay.Carregar();
			if (configuracaoShipay.IsNull() || !configuracaoShipay.IsValid)
			{
				throw new Exception("PDV não configurado. Faça a integração deste PDV através do Menu Administrativo.");
			}
			return configuracaoShipay;
		}

		private void AtualizarToken(Token token)
		{
			ObterConfiguracao().ComToken(token.access_token).ComRefreshToken(token.refresh_token).ComDataHoraLimiteToken(DateTime.Now.AddHours(3.0).AddMinutes(30.0))
				.Salvar();
		}

		protected virtual void OnPagamentoCriadoEvent(OrderResponse e)
		{
			PagamentoCriadoEvent?.Invoke(this, e);
		}

		protected virtual void OnPagamentoAprovadoEvent(OrderStatusResponse e)
		{
			_pinpad.DesconectarPinPad();
			PagamentoAprovadoEvent?.Invoke(this, e);
		}

		protected virtual void OnPagamentoCanceladoEvent(OrderStatusResponse e)
		{
			_pinpad.DesconectarPinPad();
			PagamentoCanceladoEvent?.Invoke(this, e);
		}

		protected virtual void OnPagamentoExpiradoEvent(OrderStatusResponse e)
		{
			_pinpad.DesconectarPinPad();
			PagamentoExpiradoEvent?.Invoke(this, e);
		}

		protected virtual void OnErroEvent(Exception e)
		{
			ErroEvent?.Invoke(this, e);
		}
	}
	public class SincronizacaoService
	{
		public DateTime DataInicial;

		public DateTime DataFinal;

		private readonly IRepositoryRead<Movimentacao> _movimentacaoRepositoryRead;

		private readonly IRepositoryRead<RegistroPafEcf> _registroPafEcfRepositoryRead;

		private readonly IRepositoryRead<DigisatServer.Domain.Main.Aggregates.AuxiliaresAgg.Pbms.TransacaoPbm> _transacaoPbmRepositoryRead;

		private readonly IWService _service;

		public ConcurrentQueue<string> Erros;

		public ConcurrentQueue<int> Registros;

		public SincronizacaoService(IRepositoryRead<Movimentacao> movimentacaoRepositoryRead, IRepositoryRead<RegistroPafEcf> registroPafEcfRepositoryRead, IRepositoryRead<DigisatServer.Domain.Main.Aggregates.AuxiliaresAgg.Pbms.TransacaoPbm> transacaoPbmRepositoryRead, IWService service)
		{
			_movimentacaoRepositoryRead = movimentacaoRepositoryRead;
			_registroPafEcfRepositoryRead = registroPafEcfRepositoryRead;
			_transacaoPbmRepositoryRead = transacaoPbmRepositoryRead;
			_service = service;
		}

		public async Task Processar()
		{
			Erros = new ConcurrentQueue<string>();
			Registros = new ConcurrentQueue<int>();
			ConcurrentQueue<Task> tasks = new ConcurrentQueue<Task>();
			await _movimentacaoRepositoryRead.ForEachAsync(MovimentacaoSpecification.PorDataHoraEmissao(DataInicial.Date, DataFinal.ToFinalDia()), (Movimentacao movimentacao) =>
			{
				tasks.Enqueue(Sincronizar("Movimentacoes", movimentacao.Id.ToString(), movimentacao.ToJson(), movimentacao.Numero));
			});
			await _registroPafEcfRepositoryRead.ForEachAsync(RegistroPafEcfSpecifications.PorDataInclusao(DataInicial, DataFinal), (RegistroPafEcf registroPafEcf) =>
			{
				tasks.Enqueue(Sincronizar("RegistrosPafEcf", registroPafEcf.Id.ToString(), registroPafEcf.ToJson(), 0L));
			});
			await _transacaoPbmRepositoryRead.ForEachAsync(TransacaoPbmSpecification.PorDataInclusao(DataInicial, DataFinal), (DigisatServer.Domain.Main.Aggregates.AuxiliaresAgg.Pbms.TransacaoPbm transacaoPbm) =>
			{
				tasks.Enqueue(Sincronizar("TransacoesPbm", transacaoPbm.Id.ToString(), transacaoPbm.ToJson(), 0L));
			});
			Task.WaitAll(tasks.ToArray());
		}

		public async Task Sincronizar(string colecao, string id, string dados, long numero = 0L)
		{
			await _service.Canal((ISincronizacaoModuleService service) => service.Sincronizar(colecao, id, dados)).ContinueWith((Task task) =>
			{
				if (task.IsFaulted)
				{
					Erros.Enqueue((numero > 0) ? ($"Número: {numero} Erro: " + task.Exception.GetLastException().Message) : ($"{colecao}-Id:{id} Erro: " + task.Exception.GetLastException().Message));
				}
				else
				{
					Registros.Enqueue(1);
				}
			});
		}
	}
	public class ValorSangriaService
	{
		private readonly IRepositoryBaseWrite<ValorSangriaLocal> _valorSangriaRepositoryWrite;

		private readonly IRepositoryRead<ValorSangriaLocal> _valorSangriaRepositoryRead;

		public ValorSangriaService(IRepositoryBaseWrite<ValorSangriaLocal> valorSangriaRepositoryWrite, IRepositoryRead<ValorSangriaLocal> valorSangriaRepositoryRead)
		{
			_valorSangriaRepositoryWrite = valorSangriaRepositoryWrite;
			_valorSangriaRepositoryRead = valorSangriaRepositoryRead;
		}

		public void AlterarValor(decimal valor, bool aumentar = true)
		{
			if (!DadosSistema.ConfiguracaoDto.Saida.PontoDeSangria.Valor)
			{
				return;
			}
			ValorSangriaLocal valorSangriaLocal = _valorSangriaRepositoryRead.Find(ValorSangriaLocalSpecifications.All()).FirstOrDefault();
			if (valorSangriaLocal.IsNull())
			{
				if (aumentar)
				{
					ValorSangriaLocal entity = ValorSangriaLocal.Criar().ComValor(valor);
					_valorSangriaRepositoryWrite.Add(entity);
				}
			}
			else
			{
				_valorSangriaRepositoryWrite.Update(aumentar ? valorSangriaLocal.ComValor(valorSangriaLocal.Valor + valor) : valorSangriaLocal.ComValor(valorSangriaLocal.Valor - valor));
			}
		}
	}
	public class ModoFuncionamentoService : IModoFuncionamentoService
	{
		private readonly IUnityContainer _container;

		private readonly IBalancaService _balancaService;

		private readonly IBackupPontoDeVendaService _backupPontoDeVendaService;

		private readonly IConfiguracaoClientService _configuracaoClientService;

		public ModoFuncionamentoService(IUnityContainer container, IBalancaService balancaService, IBackupPontoDeVendaService backupPontoDeVendaService, IConfiguracaoClientService configuracaoClientService)
		{
			_container = container;
			_balancaService = balancaService;
			_backupPontoDeVendaService = backupPontoDeVendaService;
			_configuracaoClientService = configuracaoClientService;
		}

		public IList<IModoFuncionamento> ObterModosFuncionamento()
		{
			try
			{
				_balancaService.Inicializar();
				_backupPontoDeVendaService.GerarBackup();
			}
			catch (Exception ex)
			{
				ex.ShowLastException();
			}
			bool flag = _configuracaoClientService.ObterConfiguracao().ModoFuncionamentoPaf == ModoFuncionamento.PafNfce;
			List<IModoFuncionamento> list = new List<IModoFuncionamento>();
			if (DadosSistema.IsMEI)
			{
				list.Add(_container.Resolve<ModoFuncionamentoRegistroVenda>(Array.Empty<ResolverOverride>()));
				if (!DadosSistema.IsSistemaDigiSatMEI && !DadosSistema.UFEmpresaLogada.Sigla.Equals("SC"))
				{
					list.Add(_container.Resolve<ModoFuncionamentoNfce>(Array.Empty<ResolverOverride>()));
				}
				if ((!DadosSistema.IsSistemaDigiSatMEI && DadosSistema.UFEmpresaLogada.Sigla.Equals("SC")) & flag)
				{
					list.Add(_container.Resolve<ModoFuncionamentoPafNfce>(Array.Empty<ResolverOverride>()));
				}
				if (!list.Any())
				{
					list.Add(_container.Resolve<ModoFuncionamentoRegistroVenda>(Array.Empty<ResolverOverride>()));
				}
				return list;
			}
			if (DadosSistema.UFEmpresaLogada.Sigla.Equals("SC") & flag)
			{
				return new List<IModoFuncionamento> { _container.Resolve<ModoFuncionamentoPafNfce>(Array.Empty<ResolverOverride>()) };
			}
			if (DadosSistema.EmpresaLogada.PontoDeVenda.Ecfs.Any())
			{
				ModoFuncionamentoCupomFiscal modoFuncionamentoCupomFiscal = _container.Resolve<ModoFuncionamentoCupomFiscal>(Array.Empty<ResolverOverride>());
				list.Add(modoFuncionamentoCupomFiscal);
				if (DadosSistema.PodeEmitirNotaManualPontoDeVenda)
				{
					ModoFuncionamentoNotaManual modoNotaManual = _container.Resolve<ModoFuncionamentoNotaManual>(Array.Empty<ResolverOverride>());
					modoFuncionamentoCupomFiscal.WhenEstadoCupomFiscalChangedEvent.Subscribe((IEstadoDocumentoFiscal estadoDocumentoFiscal) =>
					{
						modoNotaManual.HabilitarModoFuncionamento(estadoDocumentoFiscal is DocumentoFiscalFechado);
					});
					list.Add(modoNotaManual);
				}
				if (DadosSistema.IsPostoCombustivel)
				{
					ModoFuncionamentoNotaManualPosto modoNotaManual2 = _container.Resolve<ModoFuncionamentoNotaManualPosto>(Array.Empty<ResolverOverride>());
					modoFuncionamentoCupomFiscal.WhenHabilitouNotaManualEvent.Subscribe((bool x) =>
					{
						modoNotaManual2.HabilitarModoFuncionamento(x);
					});
					list.Add(modoNotaManual2);
				}
			}
			if (DadosSistema.EmpresaLogada.PontoDeVenda.Sats.Any() && !DadosSistema.PodeEmitirMfe)
			{
				list.Add(_container.Resolve<ModoFuncionamentoSat>(Array.Empty<ResolverOverride>()));
			}
			if (DadosSistema.PodeEmitirNFCe)
			{
				list.Add(_container.Resolve<ModoFuncionamentoNfce>(Array.Empty<ResolverOverride>()));
			}
			if (DadosSistema.PodeEmitirMfe)
			{
				list.Add(_container.Resolve<ModoFuncionamentoMFe>(Array.Empty<ResolverOverride>()));
			}
			return list;
		}
	}
	public class SatService : CFeService, ISatService, ICFeService, IEmissorService
	{
		private IActorRef _satClientActor;

		private readonly IClientActorSystem _actorSystem;

		private readonly IEventPublisher _eventPublisher;

		private readonly IBoletoProxyService _boletoProxyService;

		public SatService(IClientActorSystem actorSystem, IImpressoraNaoFiscalService impressoraNaoFiscalService, ISessaoService sessaoService, IEventPublisher eventPublisher, IWService service, IConfiguracaoClientService configuracaoClientService, IRepositoryRead<Movimentacao> movimentacaoRepositoryRead, IRepositoryWrite<Movimentacao> movimentacaoRepositoryWrite, INotificacao notificacao, Otus.Modulo.PontoDeVendas.Interfaces.IShipayService shipayService, IRepositoryRead<DigisatServer.Domain.Main.Aggregates.CadastrosAgg.Pessoas.Pessoa> pessoaRepositoryRead, IRepositoryBaseWrite<ValorSangriaLocal> valorSangriaRepositoryWrite, IRepositoryRead<ValorSangriaLocal> valorSangriaRepositoryRead, IFarmaciaService farmaciaService, Otus.Modulo.PontoDeVendas.Interfaces.ITefService tefService, IBoletoProxyService boletoProxyService)
			: base(impressoraNaoFiscalService, sessaoService, service, configuracaoClientService, movimentacaoRepositoryRead, movimentacaoRepositoryWrite, notificacao, shipayService, pessoaRepositoryRead, valorSangriaRepositoryWrite, valorSangriaRepositoryRead, farmaciaService, tefService)
		{
			_actorSystem = actorSystem;
			_eventPublisher = eventPublisher;
			_boletoProxyService = boletoProxyService;
			AssinarEventosDoAtor();
		}

		public void Inicializar()
		{
			if (_satClientActor.IsNull())
			{
				_satClientActor = _actorSystem.Criar<SatClientActor>();
			}
			else
			{
				_satClientActor.Tell(new ConsultarStatusRequest());
			}
		}

		public void SetarUltimoCfeDto(CFeDto cFeDto)
		{
			UltimoCfeDto = cFeDto;
		}

		private void AssinarEventosDoAtor()
		{
			_eventPublisher.GetEvent<ConnectResponse>().Subscribe((ConnectResponse x) =>
			{
				_satClientActor.Tell(new ConsultarStatusRequest());
			});
			_eventPublisher.GetEvent<ConsultarStatusResponse>().Subscribe((ConsultarStatusResponse x) =>
			{
				InicializarEmissor();
				OnEmissorProntoEvent();
				OnEmissorCarregadoEvent();
				OnAlterouEstadoJornadaFiscalEvent(e: true);
			});
			_eventPublisher.GetEvent<ErroCFeResponse>().Subscribe((ErroCFeResponse x) =>
			{
				OnErroAoTransmitirDocumentoFiscalEvent(x.Mensagem);
			});
			_eventPublisher.GetEvent<FalhaCFeResponse>().Subscribe((FalhaCFeResponse x) =>
			{
				OnFalhaAoTransmitirDocumentoFiscalEvent(new FalhaAoTransmitirDocumentoFiscalEventArgs(x.Codigo, x.Mensagem));
			});
			_eventPublisher.GetEvent<ErroCFeCancResponse>().Subscribe((ErroCFeCancResponse x) =>
			{
				DialogoFactory.MostrarDialogoConfirma(x.Mensagem);
			});
			_eventPublisher.GetEvent<CancelarUltimaVendaResponse>().Subscribe((CancelarUltimaVendaResponse response) =>
			{
				UltimoCfeDto = null;
				try
				{
					Imprimir(response.CFeCanc);
					Cancelar(response.CFeCanc, response.UsuarioAutorizouCancelamento);
				}
				catch
				{
				}
			});
			_eventPublisher.GetEvent<EnviarDadosVendaResponse>().Subscribe((EnviarDadosVendaResponse x) =>
			{
				UltimoCfeDto = x.CFe;
				CfeDto = null;
				OnEmissorTerminouDocumentoFiscalEvent(UltimoCfeDto.NumeroExtrato);
				if (!string.IsNullOrEmpty(x.CFe.DocumentoCliente))
				{
					Task.Factory.StartNew(() => EnviarEmailCupomFiscalEletronico(x.CFe));
				}
			});
		}

		protected override int ObterNumeroCaixa()
		{
			return ConfiguracaoClientService.ObterConfiguracao().Sat.NumeroPdv;
		}

		public override void Finalizar(IEnumerable<IMensagemPromocional> mensagemPromocional)
		{
			base.Finalizar(mensagemPromocional);
			_satClientActor.Tell(new EnviarDadosVendaRequest(CfeDto));
		}

		protected override void CancelarVenda(string chaveAcesso, Autorizacao autorizacao)
		{
			base.CancelarVenda(chaveAcesso, autorizacao);
			_satClientActor.Tell(new CancelarUltimaVendaRequest(ObterCFeCancDto(chaveAcesso), autorizacao.NomeUsuario));
		}

		public override void EfetivouPreDocumentoFiscal(Movimentacao movimentacao)
		{
			Imprimir(UltimoCfeDto);
			MovimentacaoDto dto = movimentacao.ProjectedAsDto();
			ImprimirTicketTroca(dto);
			ImprimirValoresCliente(dto);
			ThreadPrincipal.Executar(() =>
			{
				ImpressaoBoletoService.Init().ComBoletoProxyService(_boletoProxyService).VerificarImpressaoBoletos(dto);
			});
		}

		public void LimparUltimoDocumentoEmitido()
		{
			UltimoCfeDto = null;
		}
	}
	public class TefService : Otus.Modulo.PontoDeVendas.Interfaces.ITefService
	{
		private readonly Tef _tef = new Tef();

		private CompositeDisposable _subscriptions;

		private decimal _subtotal;

		private decimal _totalAPagar;

		private readonly ISessaoService _sessaoService;

		private readonly IArquivoAuxiliarService _arquivoAuxiliarService;

		private readonly IEventPublisher _eventPublisher;

		private readonly IPessoaRepositoryRead _pessoaRepositoryRead;

		private IModoFuncionamento _modoFuncionamento;

		private readonly BackgroundWorker _bwInicial;

		private readonly BackgroundWorker _bwAdm;

		private readonly BackgroundWorker _bwCrt;

		private readonly BackgroundWorker _bwCartDigi;

		private int _indiceEspecieEcf;

		private bool _isRecebimentoPdv;

		private bool _isMesaContaCreditoCliente;

		private IEnumerable<TefCombustivel> _tefCombustiveis;

		public ConfiguracaoTef ConfiguracaoTef { get; set; }

		public TefService(ISessaoService sessaoService, IArquivoAuxiliarService arquivoAuxiliarService, IEventPublisher eventPublisher, IConfiguracaoClientService configuracaoClientService, IPessoaRepositoryRead pessoaRepositoryRead)
		{
			_sessaoService = sessaoService;
			_arquivoAuxiliarService = arquivoAuxiliarService;
			_eventPublisher = eventPublisher;
			_pessoaRepositoryRead = pessoaRepositoryRead;
			ConfiguracaoTef = configuracaoClientService.ObterConfiguracao()?.Tef;
			_bwInicial = new BackgroundWorker();
			_bwAdm = new BackgroundWorker();
			_bwCrt = new BackgroundWorker();
			_bwCartDigi = new BackgroundWorker();
			AssinarEventos();
		}

		public void SetarModoFuncionamento(IModoFuncionamento modoFuncionamento)
		{
			_modoFuncionamento = modoFuncionamento;
			_tef.SetarImpressao((!modoFuncionamento.Is<ModoFuncionamentoCupomFiscal>()) ? TefTipo.Impressao.ImpressoraNaoFiscal : TefTipo.Impressao.Ecf);
			InicializarPropriedades();
			Inicializar(_tef);
		}

		public void InicializarPropriedades()
		{
			if (ConfiguracaoTef != null && ConfiguracaoTef.Tipo != TipoTef.Nenhum)
			{
				switch (ConfiguracaoTef.Tipo)
				{
				case TipoTef.PayGo:
					_tef.TefPayGo.Habilitado = true;
					_tef.TefPayGo.AutoAtivarGerenciadorPadrao = !_tef.TefPayGo.Habilitado;
					break;
				case TipoTef.Cappta:
					_tef.TefCappta.Habilitado = true;
					_tef.TefCappta.AutoAtivarGerenciadorPadrao = !_tef.TefCappta.Habilitado;
					break;
				case TipoTef.GetCard:
					_tef.TefGetcard.Habilitado = true;
					_tef.TefGetcard.AutoAtivarGerenciadorPadrao = !_tef.TefGetcard.Habilitado;
					break;
				case TipoTef.Sitef:
					_tef.TefSitef.Habilitado = true;
					_tef.TefSitef.AutoAtivarGerenciadorPadrao = !_tef.TefSitef.Habilitado;
					break;
				case TipoTef.Elgin:
					_tef.TefElgin.Habilitado = true;
					_tef.TefElgin.AutoAtivarGerenciadorPadrao = !_tef.TefElgin.Habilitado;
					break;
				case TipoTef.Dial:
					_tef.TefDial.Habilitado = true;
					_tef.TefDial.AutoAtivarGerenciadorPadrao = !_tef.TefDial.Habilitado;
					break;
				case TipoTef.ComnectGpTef:
					_tef.TefComnectGpTef.Habilitado = true;
					_tef.TefComnectGpTef.AutoAtivarGerenciadorPadrao = !_tef.TefComnectGpTef.Habilitado;
					break;
				case TipoTef.Destaxa:
					_tef.TefDestaxa.Habilitado = true;
					_tef.TefDestaxa.AutoAtivarGerenciadorPadrao = !_tef.TefDestaxa.Habilitado;
					break;
				case TipoTef.Auttar:
					_tef.TefAuttar.Habilitado = true;
					_tef.TefAuttar.AutoAtivarGerenciadorPadrao = !_tef.TefAuttar.Habilitado;
					break;
				}
				_tef.NumeroVias = (_tef.TefSitef.Habilitado ? 1 : 2);
				_tef.Identificacao.NomeAplicacao = _arquivoAuxiliarService.NomeAplicativo;
				_tef.Identificacao.RazaoSocial = _sessaoService.Sessao.Perfis.ItemSelecionado.Empresa.Nome;
				_tef.Identificacao.Cnpj = _sessaoService.Sessao.Perfis.ItemSelecionado.Empresa.CpfCnpj;
				_tef.Identificacao.SoftwareHouse = _arquivoAuxiliarService.RazaoSocialSoftwareHouse;
				_tef.Identificacao.CnpjSoftwareHouse = _arquivoAuxiliarService.Cnpj;
				_tef.Identificacao.VersaoAplicacao = _arquivoAuxiliarService.VersaoAplicativo;
			}
		}

		public void Inicializar(Tef tef)
		{
			if (!_bwInicial.IsBusy)
			{
				_bwInicial.RunWorkerAsync(tef);
			}
		}

		private void TestarTefInicializado(Tef tef)
		{
			(_modoFuncionamento?.EmissorService as EcfService)?.AguardarEcfCarregado();
			_eventPublisher.Publish(tef);
			foreach (ITef item in tef.ListaTef.Where((ITef x) => x.Habilitado && !x.Inicializado))
			{
				item.Inicializar();
			}
			ITef tef2 = tef.ListaTef.FirstOrDefault((ITef x) => x.Habilitado);
			if (tef2 != null)
			{
				tef.GerenciadorPadraoAtual = tef2.Tipo;
			}
		}

		private void AssinarEventos()
		{
			_subscriptions = new CompositeDisposable
			{
				_eventPublisher.GetEvent((ConfiguracaoClient config) =>
				{
					ConfiguracaoTef = config?.Tef;
					SetarModoFuncionamento(_modoFuncionamento);
				}),
				_tef.WhenInfoEcfEvent.Subscribe((TefInfoEcfEventArgs args) =>
				{
					switch (args.InfoEcf)
					{
					case TefTipo.InfoEcf.SubTotal:
						args.Retorno = _subtotal.ToStringOrEmpty();
						break;
					case TefTipo.InfoEcf.TotalAPagar:
						args.Retorno = _totalAPagar.ToStringOrEmpty();
						break;
					}
				}),
				_tef.WhenInfoNaoFiscalEvent.Subscribe((TefInfoNaoFiscalEventArgs args) =>
				{
					switch (args.InfoNaoFiscal)
					{
					case TefTipo.InfoNaoFiscal.SubTotal:
						args.Retorno = _subtotal.ToStringOrEmpty();
						break;
					case TefTipo.InfoNaoFiscal.TotalAPagar:
						args.Retorno = _totalAPagar.ToStringOrEmpty();
						break;
					}
				}),
				_tef.WhenAguardarRespEvent.Subscribe((TefAguardarRespEventArgs args) =>
				{
					if (args.SegundosTimeOut == 0)
					{
						args.Interromper = true;
					}
				}),
				_tef.WhenExibirMensagemEvent.Subscribe((TefExibirMensagemEventArgs args) =>
				{
					ThreadPrincipal.Executar(() =>
					{
						switch (args.Tipo)
						{
						case TefTipo.OperacaoMensagem.Ok:
							DialogoFactory.MostrarDialogoConfirma(args.Mensagem);
							ThreadPrincipal.Executar(() =>
							{
								_modoFuncionamento.SeletorDireito.Get<PainelTotalizacaoBase>().HabilitarPainel();
							});
							break;
						case TefTipo.OperacaoMensagem.YesNo:
						{
							MessageBoxResult messageBoxResult = DialogoFactory.MostrarDialogoSimNao(args.Mensagem);
							args.Resultado = ((messageBoxResult == MessageBoxResult.Yes) ? TefTipo.ResultadoMensagem.Sim : TefTipo.ResultadoMensagem.Nao);
							break;
						}
						case TefTipo.OperacaoMensagem.ExibirMsgOperador:
						case TefTipo.OperacaoMensagem.RemoverMsgOperador:
						case TefTipo.OperacaoMensagem.ExibirMsgCliente:
						case TefTipo.OperacaoMensagem.RemoverMsgCliente:
						case TefTipo.OperacaoMensagem.DestaqueVia:
							break;
						}
					});
				}),
				_tef.WhenPagamentoEvent.Subscribe((TefPagamentoEventArgs args) =>
				{
					ThreadPrincipal.Executar(() =>
					{
						DigisatServer.Domain.Main.Aggregates.CadastrosAgg.Pessoas.Pessoa pessoa = RetornarAdministradoraCartao(args.Resposta.Rede);
						if (_isRecebimentoPdv)
						{
							if (_isMesaContaCreditoCliente)
							{
								_isMesaContaCreditoCliente = false;
								_modoFuncionamento.SeletorDireito.Get<PainelAdicionarMesaContaCreditoCliente>().FinalizarPagamentoCartao(InformacaoTransacaoTef.Criar().ComRede(args.Resposta.Rede).ComDebito(args.Resposta.Debito)
									.ComCodigoAutorizacaoTransacao(args.Resposta.CodigoAutorizacaoTransacao.IsNullOrEmpty() ? args.Resposta.NumeroAutorizacao.ToStringOrEmpty() : args.Resposta.CodigoAutorizacaoTransacao.ToStringEmptyWhenNull())
									.ComAdministradoraCartao(pessoa)
									.ComNumeroParcelas(args.Resposta.QtdParcelas)
									.Build());
							}
							else if (args.Resposta.IsCarteiraDigital)
							{
								_modoFuncionamento.SeletorDireito.Get<PainelRecebimento>().SetarFinalizadoEmCarteiraDigital(finalizadoEmCarteiraDigital: true);
								_modoFuncionamento.SeletorDireito.Get<PainelRecebimento>().FinalizarPagamentoCarteiraDigital(InformacaoTransacaoCarteiraDigital.Criar().ComValor(args.Valor).ComNsu(args.Resposta.Nsu)
									.ComRede(args.Resposta.Rede)
									.ComTipo(args.Resposta.TipoCarteiraDigital)
									.ComAdministradoraCartao(pessoa)
									.ComCodigoAutorizacaoTransacao(args.Resposta.CodigoAutorizacaoTransacao.IsNullOrEmpty() ? args.Resposta.NumeroAutorizacao.ToStringOrEmpty() : args.Resposta.CodigoAutorizacaoTransacao.ToStringEmptyWhenNull())
									.ComEndToEndId(args.Resposta.EndToEnd.IsNullOrEmpty() ? args.Resposta.CodigoAutorizacaoTransacao.ToStringOrEmpty() : args.Resposta.EndToEnd.ToStringEmptyWhenNull())
									.ComPspPagador(args.Resposta.PspPagador)
									.Build());
							}
							else
							{
								_modoFuncionamento.SeletorDireito.Get<PainelRecebimento>().FinalizarPagamentoCartao(InformacaoTransacaoTef.Criar().ComRede(args.Resposta.Rede).ComDebito(args.Resposta.Debito)
									.ComCodigoAutorizacaoTransacao(args.Resposta.CodigoAutorizacaoTransacao.IsNullOrEmpty() ? args.Resposta.NumeroAutorizacao.ToStringOrEmpty() : args.Resposta.CodigoAutorizacaoTransacao.ToStringEmptyWhenNull())
									.ComAdministradoraCartao(pessoa)
									.ComNumeroParcelas(args.Resposta.QtdParcelas)
									.Build());
							}
						}
						else
						{
							if (!_tef.MultiplosCartoes && args.Resposta.PrimeiraViaReduzida)
							{
								_modoFuncionamento.SeletorDireito.Get<PainelTotalizacaoBase>().AdicionarMensagemPromocional(TefMensagemPromocional.Criar().Com1Via(args.Resposta.ImagemComprovante1AVia));
							}
							if (args.Resposta.IsCarteiraDigital)
							{
								_modoFuncionamento.SeletorDireito.Get<PainelTotalizacaoEmissorBase>().AdicionarCartaoResposta(InformacaoTransacaoCarteiraDigital.Criar().ComValor(args.Valor).ComNsu(args.Resposta.Nsu)
									.ComRede(args.Resposta.Rede)
									.ComCodigoAutorizacaoTransacao(args.Resposta.CodigoAutorizacaoTransacao.IsNullOrEmpty() ? args.Resposta.NumeroAutorizacao.ToStringOrEmpty() : args.Resposta.CodigoAutorizacaoTransacao.ToStringEmptyWhenNull())
									.ComAdministradoraCartao(pessoa)
									.ComImpresso(args.Resposta.ImagemComprovante2AVia)
									.ComTipo(args.Resposta.TipoCarteiraDigital)
									.ComEndToEndId(args.Resposta.EndToEnd.IsNullOrEmpty() ? args.Resposta.CodigoAutorizacaoTransacao.ToStringOrEmpty() : args.Resposta.EndToEnd.ToStringEmptyWhenNull())
									.ComPspPagador(args.Resposta.PspPagador)
									.Build(), 26);
							}
							else
							{
								_modoFuncionamento.SeletorDireito.Get<PainelTotalizacaoEmissorBase>().AdicionarCartaoResposta(InformacaoTransacaoTef.Criar().ComValor(args.Valor).ComNsu(args.Resposta.Nsu)
									.ComRede(args.Resposta.Rede)
									.ComSaque(args.Resposta.Saque)
									.ComDebito(args.Resposta.Debito)
									.ComDesconto(args.Resposta.Desconto)
									.ComAcrescimo(args.Resposta.Acrescimo)
									.ComCodigoAutorizacaoTransacao(args.Resposta.CodigoAutorizacaoTransacao.IsNullOrEmpty() ? args.Resposta.NumeroAutorizacao.ToStringOrEmpty() : args.Resposta.CodigoAutorizacaoTransacao.ToStringEmptyWhenNull())
									.ComAdministradoraCartao(pessoa)
									.ComNumeroCartao(args.Resposta.NumeroCartao)
									.ComNomeCliente(args.Resposta.NomeCliente)
									.ComNomeAdministradora(args.Resposta.NomeAdministradora)
									.ComNumeroParcelas(args.Resposta.QtdParcelas)
									.ComImpresso(args.Resposta.ImagemComprovante2AVia)
									.Build());
							}
						}
					});
				}),
				_tef.WhenComandarEcfEvent.Subscribe((TefComandarEcfEventArgs args) =>
				{
					ThreadPrincipal.Executar(() =>
					{
						TefTipo.OperacaoEcf operacao = args.Operacao;
						if (operacao == TefTipo.OperacaoEcf.CancelaCupom)
						{
							_modoFuncionamento.PainelTotalizacao.Cancelar();
						}
					});
				}),
				_tef.WhenComandarNaoFiscalEvent.Subscribe((TefComandarNaoFiscalEventArgs args) =>
				{
					ThreadPrincipal.Executar(() =>
					{
						TefTipo.OperacaoNaoFiscal operacao = args.Operacao;
						if (operacao == TefTipo.OperacaoNaoFiscal.CancelarNaoFiscal)
						{
							_modoFuncionamento.PainelTotalizacao.Cancelar();
						}
					});
				})
			};
			_bwInicial.DoWork += BwInicialOnDoWork;
			_bwInicial.RunWorkerCompleted += BwOnRunWorkerCompleted;
			_bwAdm.DoWork += BwAdmOnDoWork;
			_bwAdm.RunWorkerCompleted += BwOnRunWorkerCompleted;
			_bwCrt.DoWork += BwCrtOnDoWork;
			_bwCrt.RunWorkerCompleted += BwOnRunWorkerCompleted;
			_bwCartDigi.DoWork += BwCartDigiOnDoWork;
			_bwCartDigi.RunWorkerCompleted += BwOnRunWorkerCompleted;
		}

		private DigisatServer.Domain.Main.Aggregates.CadastrosAgg.Pessoas.Pessoa RetornarAdministradoraCartao(string rede)
		{
			if (!ConfiguracaoTef.AdministradoraCartaoReferencia.IsObjectIdDefaultOrEmpty())
			{
				DigisatServer.Domain.Main.Aggregates.CadastrosAgg.Pessoas.Pessoa byId = _pessoaRepositoryRead.GetById(ConfiguracaoTef.AdministradoraCartaoReferencia.TryParseReferencia());
				if (byId.IsNotNull() && byId.IsJuridica && byId.To<Juridica>().AdministradoraCartao.IsNotNull())
				{
					return byId;
				}
			}
			IEnumerable<DigisatServer.Domain.Main.Aggregates.CadastrosAgg.Pessoas.Pessoa> source = _pessoaRepositoryRead.Find(EntitySpecification<DigisatServer.Domain.Main.Aggregates.CadastrosAgg.Pessoas.Pessoa>.Ativo().AdministradoraCartao());
			DigisatServer.Domain.Main.Aggregates.CadastrosAgg.Pessoas.Pessoa pessoa = null;
			if (source.Count() > 1)
			{
				pessoa = source.FirstOrDefault((DigisatServer.Domain.Main.Aggregates.CadastrosAgg.Pessoas.Pessoa x) => ((Juridica)x).AdministradoraCartao.Redes.Contains(rede.ToUpper()));
			}
			if (pessoa.IsNull() && !source.Any())
			{
				throw new Exception("Nenhuma pessoa do tipo 'Administradora de cartão' cadastrada.");
			}
			return pessoa ?? source.LastOrDefault();
		}

		private void BwInicialOnDoWork(object sender, DoWorkEventArgs doWorkEventArgs)
		{
			TestarTefInicializado((Tef)doWorkEventArgs.Argument);
		}

		private void BwOnRunWorkerCompleted(object sender, RunWorkerCompletedEventArgs runWorkerCompletedEventArgs)
		{
			if (runWorkerCompletedEventArgs.Error == null)
			{
				return;
			}
			runWorkerCompletedEventArgs.Error.ShowLastException();
			if (_modoFuncionamento != null)
			{
				ThreadPrincipal.Executar(() =>
				{
					_modoFuncionamento?.SeletorDireito.Get<PainelTotalizacaoBase>().HabilitarPainel();
				});
			}
		}

		private void BwAdmOnDoWork(object sender, DoWorkEventArgs doWorkEventArgs)
		{
			TestarTefInicializado(_tef);
			_tef.Adm(TefTipo.GerenciadorPadrao.Nenhum);
		}

		private void BwCrtOnDoWork(object sender, DoWorkEventArgs doWorkEventArgs)
		{
			_tef.Crt((decimal)doWorkEventArgs.Argument, _indiceEspecieEcf.ToString(), "0", 0, _tefCombustiveis);
			ThreadPrincipal.Executar(() =>
			{
				_modoFuncionamento.SeletorDireito.Get<PainelTotalizacaoBase>().HabilitarPainel();
			});
		}

		private void BwCartDigiOnDoWork(object sender, DoWorkEventArgs doWorkEventArgs)
		{
			_tef.CartDigi((decimal)doWorkEventArgs.Argument, _indiceEspecieEcf.ToString(), "0");
			ThreadPrincipal.Executar(() =>
			{
				_modoFuncionamento.SeletorDireito.Get<PainelTotalizacaoBase>().HabilitarPainel();
			});
		}

		public void Terminar()
		{
			if (_tef.ListaTef != null && _tef.ListaTef.Any((ITef x) => x.Inicializado))
			{
				_tef.Terminar(TefTipo.GerenciadorPadrao.Nenhum);
			}
		}

		public void Cancelar()
		{
			if (_tef.RespostasPendentes.Count > 0)
			{
				_tef.CancelarTransacoesPendentes();
			}
		}

		public void Adm()
		{
			if (!_bwAdm.IsBusy)
			{
				_bwAdm.RunWorkerAsync();
			}
		}

		public void Crt(decimal valor, decimal subTotal, decimal totalPagamentos, bool possuiAcrescimoDesconto, int indiceEspecieEcf, bool isRecebimentoPdv = false, IEnumerable<TefCombustivel> tefCombustiveis = null, bool isMesaContaCreditoCliente = false)
		{
			try
			{
				if (!ObterAdministradorasCartao().Any())
				{
					throw new Exception("Nenhuma pessoa do tipo 'Administradora de cartão' cadastrada.");
				}
				_indiceEspecieEcf = indiceEspecieEcf;
				_tefCombustiveis = tefCombustiveis;
				_tef.SuportaReajuste = !possuiAcrescimoDesconto;
				_isRecebimentoPdv = isRecebimentoPdv;
				_isMesaContaCreditoCliente = isMesaContaCreditoCliente;
				ProcessarSubTotalETotalAPagar(valor, subTotal, totalPagamentos);
				if (!_bwCrt.IsBusy)
				{
					_bwCrt.RunWorkerAsync(valor);
				}
			}
			catch (Exception ex)
			{
				DialogoFactory.MostrarDialogoConfirma(ex.Message);
			}
		}

		public IEnumerable<DigisatServer.Domain.Main.Aggregates.CadastrosAgg.Pessoas.Pessoa> ObterAdministradorasCartao()
		{
			return _pessoaRepositoryRead.Find(EntitySpecification<DigisatServer.Domain.Main.Aggregates.CadastrosAgg.Pessoas.Pessoa>.Ativo().AdministradoraCartao());
		}

		public bool Cnc(string rede, string nsu, DateTime dataHoraTransacao, decimal valor, bool forcarCancelamento = false)
		{
			try
			{
				TestarTefInicializado(_tef);
				return _tef.Cnc(rede, nsu, dataHoraTransacao, valor, forcarCancelamento);
			}
			catch (Exception ex)
			{
				DialogoFactory.MostrarDialogoConfirma(ex.Message);
				return false;
			}
		}

		public void CartDigi(decimal valor, decimal subTotal, decimal totalPagamentos, bool possuiAcrescimoDesconto, int indiceEspecieEcf, bool isRecebimentoPdv = false)
		{
			try
			{
				if (!ObterAdministradorasCartao().Any())
				{
					throw new Exception("Nenhuma pessoa do tipo 'Administradora de cartão' cadastrada.");
				}
				_indiceEspecieEcf = indiceEspecieEcf;
				_tef.SuportaReajuste = !possuiAcrescimoDesconto;
				_isRecebimentoPdv = isRecebimentoPdv;
				ProcessarSubTotalETotalAPagar(valor, subTotal, totalPagamentos);
				if (!_bwCartDigi.IsBusy)
				{
					_bwCartDigi.RunWorkerAsync(valor);
				}
			}
			catch (Exception ex)
			{
				DialogoFactory.MostrarDialogoConfirma(ex.Message);
			}
		}

		private void ProcessarSubTotalETotalAPagar(decimal valor, decimal subTotal, decimal totalPagamentos)
		{
			_subtotal = subTotal;
			_totalAPagar = totalPagamentos;
			_totalAPagar -= _tef.RespostasPendentes.TotalPago + _tef.RespostasPendentes.TotalDesconto;
			if (_tef.RespostasPendentes.Count == 0)
			{
				_tef.MultiplosCartoes = _subtotal != _totalAPagar + valor;
			}
			TestarTefInicializado(_tef);
		}

		public void Imprimir()
		{
			if (_tef.RespostasPendentes.Any())
			{
				_tef.ImprimirTransacoesPendentes(_isRecebimentoPdv);
				SetarGnfCcd();
			}
		}

		public void ImprimirNotaManual()
		{
			if (_tef.RespostasPendentes.Any())
			{
				_tef.ImprimirTransacoesPendentesFiscal(isRecebimento: false);
				SetarGnfCcd();
			}
		}

		private void SetarGnfCcd()
		{
			(_modoFuncionamento.SeletorDireito.Get<PainelDocumentoFiscal>()?.PreDocumentoFiscal)?.SetarGnfCcd(_modoFuncionamento.EmissorService.RetornarContadorGeralNaoFiscal());
		}

		public void DesassinarEventos()
		{
			_subscriptions?.Dispose();
			_subscriptions = null;
			_bwInicial.DoWork -= BwInicialOnDoWork;
			_bwInicial.RunWorkerCompleted -= BwOnRunWorkerCompleted;
			_bwAdm.DoWork -= BwAdmOnDoWork;
			_bwAdm.RunWorkerCompleted -= BwOnRunWorkerCompleted;
			_bwCrt.DoWork -= BwCrtOnDoWork;
			_bwCrt.RunWorkerCompleted -= BwOnRunWorkerCompleted;
			_bwCartDigi.DoWork -= BwCartDigiOnDoWork;
			_bwCartDigi.RunWorkerCompleted -= BwOnRunWorkerCompleted;
		}
	}
}
