		public ParcelamentoViaCliente79Mm80Mm(bool rollPaper, int margemEsquerdaImpressoraNaoFiscal)
		{
			_rollPaper = rollPaper;
			_margemEsquerdaImpressoraNaoFiscal = margemEsquerdaImpressoraNaoFiscal;
			InitializeComponent();
		}

		public XtraReport Processar()
		{
			try
			{
				IDadosRelatorioCarne40Colunas item = Parametros.Objeto as IDadosRelatorioCarne40Colunas;
				DataSource = new List<IDadosRelatorioCarne40Colunas> { item };
				RollPaper = _rollPaper;
				Margins.Left = _margemEsquerdaImpressoraNaoFiscal;
				ExibirLogotipo();
				ShowPrintMarginsWarning = false;
				CreateDocument();
			}
			catch (Exception ex)
			{
				DialogoFactory.MostrarDialogoConfirma(ex.Message);
			}
			return this;
		}

		private void ExibirLogotipo()
		{
			logotipoEmitente.Visible = false;
			if (!DadosSistema.EmpresaLogada.Imagem.IsNull() && DadosSistema.EmpresaLogada.Imagem.Length != 0)
			{
				logotipoEmitente.Image = DadosSistema.EmpresaLogada.Imagem.Decompress().ToImage();
				if (logotipoEmitente.Image != null)
				{
					logotipoEmitente.Visible = true;
					painelEmitente.Visible = false;
				}
			}
		}

