			DataSource = itens;
			ShowPrintMarginsWarning = false;
			RequestParameters = false;
		}

		public static RelatorioMapaResumo Criar()
		{
			return new RelatorioMapaResumo();
		}

		public RelatorioMapaResumo ComRazaoSocial(string razaoSocial)
		{
			Parameters["RazaoSocial"].Value = razaoSocial;
			return Build();
		}

		public RelatorioMapaResumo ComCnpj(string cnpj)
		{
			Parameters["Cnpj"].Value = cnpj;
			return Build();
		}

