		{
			DataSource = mapasResumo;
			return Build();
		}

		private RelatorioMapaResumo Build()
		{
			return new RelatorioMapaResumo(Parameters["Cnpj"].Value.ToString(), Parameters["RazaoSocial"].Value.ToString(), DataSource as IEnumerable<MapaResumoLocal>);
		}

