namespace Otus.Modulo.PontoDeVendas.Projections
{
	public static class NfceProjections
	{
		public static MovimentacaoDto ProjectedPreDocumentoAsMovimentacaoDto(this PreDocumentoFiscal documento, IPagamentoRecebimento recebimento, IEnumerable<ItemPagamento> itensPagamentos, string md5)
		{
			string text = string.Empty;
			List<MovimentacaoReferenciada> list = documento.MovimentacoesReferenciadas.ToListEmptyWhenNull();
			foreach (MovimentacaoReferenciada item in list)
			{
				string arg = ((text.Trim().Length == 0) ? string.Empty : ",");
				text += $"{arg} {item.ObterTipoMovimentacao()}: {item.Numero:0000000000000}".Trim();
			}
			CodigoDescricaoDto indicadorPresencaComprador = documento.IndicadorPresencaComprador.ProjectedAsDto();
			IntermediadorTransacaoDto intermediadorTransacao;
			if (documento.IndicadorIntermediadorTransacao != IndicadorIntermediador.SemIntermediador)
			{
				intermediadorTransacao = ((documento.IndicadorIntermediadorTransacao == IndicadorIntermediador.SiteOuPlataformaDeTerceiros) ? new IntermediadorTransacaoDto
				{
					Cnpj = documento.CnpjIntermediadorTransacao.ToStringEmptyWhenNull().RemoveCaracteresAlfanumerico(),
					Identificador = documento.IdentificaoIntermediadorTransacao.ToStringEmptyWhenNull()
				} : new IntermediadorTransacaoDtoNull());
			}
			else
			{
				intermediadorTransacao = new IntermediadorTransacaoDtoNull();
			}
			OperacaoComEntregaDomicilioDto operacaoComEntregaDomicilio = (documento.PossuiEntregaDomicilio ? new OperacaoComEntregaDomicilioDto
			{
				CpfEntregador = documento.OperacaoComEntregaDomicilio.Cpf.ToStringEmptyWhenNull().ApenasNumeros(),
				NomeEntregador = documento.OperacaoComEntregaDomicilio.NomeEntregador.ToStringEmptyWhenNull(),
				Endereco = documento.OperacaoComEntregaDomicilio.Endereco.ProjectedAsDto()
			} : new OperacaoComEntregaDomicilioDtoNull());
			MovimentacaoDto movimentacaoDto = new MovimentacaoDto
			{
				Id = documento.Id.ToString(),
				Versao = documento.VersaoMovimentacao,
				Numero = documento.Numero,
				DataHoraEmissao = DateTime.Now,
				DataHoraEntradaSaida = DateTime.Now,
				Pessoa = documento.Pessoa.ProjectedAsDto(),
				Empresa = documento.Empresa.ProjectedAsDto(),
				MovimentacoesReferenciadas = list.ProjectedAsCollectionDto(),
				Observacao = documento.Observacao,
				ObservacaoDocumentoImportado = text,
				PagamentosRecebimentos = recebimento.Parcelas.ProjectedAsCollectionDto().ToList(),
				ItensPagamentos = itensPagamentos.ProjectedAsCollectionDto(),
				Troco = documento.Troco,
				TotalDescontoAplicado = documento.Desconto,
				TotalOutrasDespesas = documento.OutrasDespesas,
				VendedorResponsavel = (documento.Vendedor?.PessoaHistorico.ProjectedPessoaHistoricoAsDto() ?? new PessoaDtoNull()),
				Md5 = md5,
				Tipo = TipoMovimentacao.NotaFiscalConsumidorEletronica,
				Convenio = (documento.Convenio?.PessoaDto ?? new PessoaDtoNull()),
				ModalidadeFrete = documento.ModalidadeFrete.ProjectedAsDto(),
				TotalFrete = (documento.ModalidadeFrete?.Valor ?? 0m),
				IndicadorPresencaComprador = indicadorPresencaComprador,
				IntermediadorTransacao = intermediadorTransacao,
				OperacaoComEntregaDomicilio = operacaoComEntregaDomicilio,
				UtilizouCashback = documento.UtilizouCashback,
				ValorCashbackUtilizado = documento.ValorCashbackUtilizado,
				NumeroPdvScanntech = documento.NumeroPdvScanntech,
				ComissaoSubsidiada = documento.ComissaoSubsidiada,
				OperadoraPortalDrograria = (documento.RetornoConsultaPbm?.Operadora ?? string.Empty),
				NumeroAutorizacaoPortalDrograria = (documento.RetornoConsultaPbm?.NumeroAutorizacao ?? string.Empty),
				MovimentacaoItemFinanceiro = documento.MovimentacaoItemFinanceiro,
				Tickets = documento.Tickets.ToListEmptyWhenNull()
			};
			if (documento.DadosVeiculoMaquinaEquipamento.IsNotNull())
			{
				movimentacaoDto.DadosVeiculoMaquinaEquipamento = new DadosVeiculoMaquinaEquipamentoDto
				{
					RazaoSocial = documento.DadosVeiculoMaquinaEquipamento.RazaoSocial.ToStringEmptyWhenNull(),
					InscricaoEstadual = documento.DadosVeiculoMaquinaEquipamento.InscricaoEstadual.ToStringEmptyWhenNull(),
					Cnpj = documento.DadosVeiculoMaquinaEquipamento.Cnpj.ToStringEmptyWhenNull(),
					Cpf = documento.DadosVeiculoMaquinaEquipamento.Cpf.ToStringEmptyWhenNull(),
					Horimetro = documento.DadosVeiculoMaquinaEquipamento.Horimetro,
					Placa = documento.DadosVeiculoMaquinaEquipamento.Placa.ToStringEmptyWhenNull(),
					Quilometragem = documento.DadosVeiculoMaquinaEquipamento.Quilometragem,
					UnidadeConsumidora = documento.DadosVeiculoMaquinaEquipamento.UnidadeConsumidora.ToStringEmptyWhenNull(),
					Observacao = documento.DadosVeiculoMaquinaEquipamento.Observacao.ToStringEmptyWhenNull()
				};
			}
			IEnumerable<ItemDto> itens = (from itemDocumentoFiscal in documento.Itens
				where itemDocumentoFiscal.Ativo
				select itemDocumentoFiscal.ObterItem(documento)).ProjectedAsCollectionDto().Select((ItemDto itemDto) =>
			{
				itemDto.PessoaMovimentacao = movimentacaoDto.Pessoa;
				itemDto.EmpresaMovimentacao = movimentacaoDto.Empresa;
				itemDto.IndicadorPresencaCompradorMovimentacao = indicadorPresencaComprador;
				itemDto.IndicadorOperacaoMovimentacao = IndicadoresOperacaoConsumidorFinal.Dados.FirstOrDefault((IndicadorOperacaoConsumidorFinal x) => x.Codigo.Equals(1)).ProjectedAsDto();
				itemDto.NaturezaOperacaoMovimentacao = NaturezasOperacao.Dados.FirstOrDefault((INaturezaOperacao x) => x.Codigo.Equals(1L)).ProjectedAsDto();
				itemDto.TipoMovimentacao = movimentacaoDto.Tipo;
				itemDto.Percentual.IndicadorDesoneracao = ((DadosSistema.ConfiguracaoDto.Saida?.DescontarValorIcmsDesonerado?.Valor ?? false) ? 1 : 0);
				return itemDto;
			});
			movimentacaoDto.Itens = itens;
			IEnumerable<AutorizacaoDto> autorizacoes = documento.Autorizacoes;
			if (autorizacoes != null && autorizacoes.Any())
			{
				movimentacaoDto.Autorizacoes = documento.Autorizacoes;
			}
			return movimentacaoDto;
		}

		public static MovimentacaoDto ProjectedPreVendaDavMovimentacaoDto(this MovimentacaoDto documento, string md5)
		{
			ItemPagamentoDinheiro itemPagamento = new ItemPagamentoDinheiro(documento.Total, documento.Total);
			string observacaoDocumentoImportado = $"{documento.Tipo}: {documento.Numero:0000000000000}".Trim();
			MovimentacaoDto movimentacaoDto = new MovimentacaoDto
			{
				DataHoraEmissao = DateTime.Now,
				DataHoraEntradaSaida = DateTime.Now,
				Pessoa = documento.Pessoa,
				Empresa = documento.Empresa,
				MovimentacoesReferenciadas = new MovimentacaoReferenciadaDto[1]
				{
					new MovimentacaoReferenciadaDto
					{
						MovimentacaoReferencia = documento.Id,
						Numero = documento.Numero,
						Tipo = documento.Tipo,
						DataHoraEmissao = documento.DataHoraEmissao,
						NomePessoa = documento.Pessoa.Nome.ToStringEmptyWhenNull(),
						MunicipioPessoa = (documento.Pessoa.EnderecoPrincipal.Municipio?.Nome.ToStringEmptyWhenNull() ?? string.Empty),
						BairroPessoa = documento.Pessoa.EnderecoPrincipal.Bairro.ToStringEmptyWhenNull(),
						NumeroEcf = documento.NumeroEcf,
						Total = documento.Total
					}
				},
				Observacao = documento.Observacao,
				ObservacaoDocumentoImportado = observacaoDocumentoImportado,
				PagamentosRecebimentos = documento.PagamentosRecebimentos,
				ItensPagamentos = new ItemPagamentoDto[1] { itemPagamento.ProjectedAsDto() },
				Troco = documento.Troco,
				TotalDescontoAplicado = documento.TotalDescontoAplicado,
				TotalOutrasDespesas = documento.TotalOutrasDespesas,
				VendedorResponsavel = documento.VendedorResponsavel,
				Md5 = md5,
				Tipo = TipoMovimentacao.NotaFiscalConsumidorEletronica,
				Convenio = documento.Convenio,
				ModalidadeFrete = documento.ModalidadeFrete,
				TotalFrete = documento.TotalFrete
			};
			IEnumerable<ItemDto> itens = documento.Itens.Select((ItemDto itemDto) =>
			{
				itemDto.PessoaMovimentacao = movimentacaoDto.Pessoa;
				itemDto.EmpresaMovimentacao = movimentacaoDto.Empresa;
				itemDto.IndicadorPresencaCompradorMovimentacao = IndicadoresPresencaComprador.Dados.FirstOrDefault((IndicadorPresencaComprador x) => x.Codigo.Equals(1)).ProjectedAsDto();
				itemDto.IndicadorOperacaoMovimentacao = IndicadoresOperacaoConsumidorFinal.Dados.FirstOrDefault((IndicadorOperacaoConsumidorFinal x) => x.Codigo.Equals(1)).ProjectedAsDto();
				itemDto.NaturezaOperacaoMovimentacao = NaturezasOperacao.Dados.FirstOrDefault((INaturezaOperacao x) => x.Codigo.Equals(1L)).ProjectedAsDto();
				itemDto.TipoMovimentacao = movimentacaoDto.Tipo;
				return itemDto;
			});
			movimentacaoDto.Itens = itens;
			return movimentacaoDto;
		}
	}
