	public static class PainelTotalizacaoSatProjections
	{
		public static IEnumerable<PgtoDto> ProjectedAsDto(this ItemPagamentoViewModel itemPagamento)
		{
			if (itemPagamento.Is<ICartao>())
			{
				foreach (InformacaoTransacaoTef carto in itemPagamento.To<ICartao>().Cartoes)
				{
					yield return new PgtoDto
					{
						Codigo = carto.CodigoSat,
						Valor = carto.Valor
					};
				}
			}
			else if (itemPagamento.Is<ICartaoPos>())
			{
				foreach (RedePosLocal rede in itemPagamento.To<ICartaoPos>().Redes)
				{
					yield return new PgtoDto
					{
						Codigo = rede.CodigoSat,
						Valor = rede.Valor
					};
				}
			}
			else if (itemPagamento.Is<IValeDetalhado>())
			{
				foreach (TipoDeVale item in itemPagamento.To<IValeDetalhado>().TiposDeVale)
				{
					yield return new PgtoDto
					{
						Codigo = item.CodigoSat,
						Valor = item.Valor
					};
				}
			}
			else if (itemPagamento.Is<ITerminalPos>())
			{
				foreach (PagamentoTransacaoDto pagamentosTransaco in itemPagamento.To<ITerminalPos>().PagamentosTransacoes)
				{
					yield return new PgtoDto
					{
						Codigo = pagamentosTransaco.CodigoSat,
						Valor = pagamentosTransaco.Valor
					};
				}
			}
			else
			{
				yield return new PgtoDto
				{
					Codigo = itemPagamento.CodigoSat,
					Valor = itemPagamento.Valor
				};
			}
		}

		public static InfAdicDto ProjectedAsDto(this IEnumerable<IMensagemPromocional> mensagensPromocionais)
		{
			return new InfAdicDto
			{
				Texto = string.Join(Environment.NewLine, mensagensPromocionais.SelectMany((IMensagemPromocional x) => x.Linhas))
			};
		}

		public static DetDto ProjectedAsDto(this Otus.Modulo.PontoDeVendas.ViewModels.ItemDocumentoFiscal itemDocumentoFiscal)
		{
			DetDto detDto = new DetDto
			{
				NumeroItem = itemDocumentoFiscal.NumeroItem,
				Codigo = itemDocumentoFiscal.ProdutoServicoLocal.CodigoInterno,
				CodigoBarras = itemDocumentoFiscal.ProdutoServicoLocal.Barras,
				Descricao = itemDocumentoFiscal.Descricao,
				CodigoNcm = (itemDocumentoFiscal.ProdutoServicoLocal.Is<ProdutoLocal>() ? itemDocumentoFiscal.ProdutoServicoLocal.Ncm.Codigo : "99"),
				Cfop = itemDocumentoFiscal.ProdutoServicoLocal.OperacaoFiscal.Cfop.Codigo,
				UnidadeMedida = itemDocumentoFiscal.UnidadeMedida,
				Quantidade = itemDocumentoFiscal.Quantidade,
				PrecoUnitario = itemDocumentoFiscal.PrecoUnitario,
				ValorDesconto = itemDocumentoFiscal.Desconto,
				ValorAcrescimo = itemDocumentoFiscal.Acrescimo,
				Imposto = ObterImposto(itemDocumentoFiscal),
				Observacao = (itemDocumentoFiscal.To<ItemDocumentoFiscalProduto>()?.Estoque.InformacaoEstoqueVendido ?? string.Empty),
				Cest = itemDocumentoFiscal.ProdutoServicoLocal.Cest.ApenasNumeros().ToStringEmptyWhenNull()
			};
			if (itemDocumentoFiscal is ItemDocumentoFiscalCombustivel || itemDocumentoFiscal.ProdutoServicoLocal.ProdutoServicoHistorico.Tipo == TipoProdutoServico.DerivadoPetroleo || itemDocumentoFiscal.ProdutoServicoLocal.ProdutoServicoHistorico.Tipo == TipoProdutoServico.Glp)
			{
				List<ObsFiscoDetDto> list = new List<ObsFiscoDetDto>();
				ObsFiscoDetDto obsFiscoDetDto = new ObsFiscoDetDto
				{
					xCampoDet = "Cod. Produto ANP"
				};
				object xTextoDet;
				if ((itemDocumentoFiscal.ProdutoServicoLocal.To<ProdutoLocal>()?.CodigoAnp ?? 0) <= 0 || itemDocumentoFiscal.ProdutoServicoLocal.ProdutoServicoHistorico.Tipo == TipoProdutoServico.Glp)
				{
					xTextoDet = "999999999";
				}
				else
				{
					ProdutoLocal produtoLocal = itemDocumentoFiscal.ProdutoServicoLocal.To<ProdutoLocal>();
					xTextoDet = ((produtoLocal != null) ? produtoLocal.CodigoAnp.ToStringOrEmpty() : null);
				}
				obsFiscoDetDto.xTextoDet = (string)xTextoDet;
				list.Add(obsFiscoDetDto);
				detDto.ObsFiscoDet = list;
			}
			return detDto;
		}

		private static ImpostoDto ObterImposto(Otus.Modulo.PontoDeVendas.ViewModels.ItemDocumentoFiscal item)
		{
			IcmsDto icmsDto = ImpostoProjection.ObterIcms(item.ProdutoServicoLocal.To<ProdutoLocal>()?.Percentual);
			return new ImpostoDto
			{
				ValorImpostoAproximado = item.TotalAproximadoImpostos,
				PIS = ImpostoProjection.ObterPisCofins(item.ProdutoServicoLocal.Pis, item.Total, icmsDto.Percentual, item.Quantidade),
				COFINS = ImpostoProjection.ObterPisCofins(item.ProdutoServicoLocal.Cofins, item.Total, icmsDto.Percentual, item.Quantidade),
				ICMS = icmsDto,
				ISSQN = ImpostoProjection.ObterIssqn(item.ProdutoServicoLocal.To<ServicoLocal>()?.Iss, item.ProdutoServicoLocal.To<ServicoLocal>()?.CodigoAtividade.Codigo.ToString() ?? "", DadosSistema.CodigoIbgeMunicipioEmitente, item.Total),
				COFINSST = new PisCofinsStDto(),
				PISST = new PisCofinsStDto()
			};
		}
	}
