namespace Otus.Modulo.PontoDeVendas.Projections.Shipay
{
	public static class BuyerProjection
	{
		public static Buyer Morfar(this ConsumidorLocal consumidorLocal)
		{
			if (!consumidorLocal.IsNotNull())
			{
				return null;
			}
			return Buyer.Criar().Comcpf(consumidorLocal.Documento?.ApenasNumeros()).Comemail(consumidorLocal.Pessoa?.Carteira?.EmailPrincipal?.Endereco)
				.Comfirst_name(PrimeiroNome(consumidorLocal.Nome))
				.Comlast_name(Sobrenome(consumidorLocal.Nome))
				.Comphone(consumidorLocal.Pessoa?.Carteira?.TelefonePrincipal?.Numero);
		}

		private static string PrimeiroNome(string nome)
		{
			if (nome == null)
			{
				return null;
			}
			return nome.Trim().Split(' ')[0];
		}

		private static string Sobrenome(string nome)
		{
			string text = nome?.Trim();
			int num = text?.IndexOf(' ') ?? (-1);
			if (num >= 0)
			{
				return text.Substring(num + 1).Trim();
			}
			return null;
		}
	}
	public static class OrderProjection
	{
		public static Order Morfar(this PreDocumentoFiscal preDocumentoFiscal, decimal valor, string wallet)
		{
			List<OrderItem> items = ObterOrderItems(preDocumentoFiscal, valor);
			return Order.Criar().Combuyer(preDocumentoFiscal.Consumidor.Morfar()).Comitems(items)
				.Comorder_ref(preDocumentoFiscal.Id.ToStringEmptyWhenDefault())
				.Comtotal(valor)
				.Comwallet(wallet);
		}

		private static List<OrderItem> ObterOrderItems(PreDocumentoFiscal preDocumentoFiscal, decimal valor)
		{
			if (!(valor == preDocumentoFiscal.SubTotal))
			{
				return new List<OrderItem> { OrderItem.Criar().Comitem_title("Pagamento em Carteira Digital").Comquantity(1m)
					.Comunit_price(valor) };
			}
			return preDocumentoFiscal.Itens.MorfarCollection().ToList();
		}

		public static Order Morfar(this ConsumidorLocal consumidor, decimal valor, string wallet)
		{
			List<OrderItem> items = ObterOrderItems(valor);
			return Order.Criar().Combuyer(consumidor.Morfar()).Comitems(items)
				.Comorder_ref(consumidor.Id.ToStringEmptyWhenDefault())
				.Comtotal(valor)
				.Comwallet(wallet);
		}

		private static List<OrderItem> ObterOrderItems(decimal valor)
		{
			return new List<OrderItem> { OrderItem.Criar().Comitem_title("Pagamento em Carteira Digital").Comquantity(1m)
				.Comunit_price(valor) };
		}
	}
	public static class OrderItemProjection
	{
		public static OrderItem Morfar(this Otus.Modulo.PontoDeVendas.ViewModels.ItemDocumentoFiscal item)
		{
			return OrderItem.Criar().Comitem_title(item.Descricao).Comquantity(1m)
				.Comunit_price(item.TotalLiquido);
		}

		public static IEnumerable<OrderItem> MorfarCollection(this IEnumerable<Otus.Modulo.PontoDeVendas.ViewModels.ItemDocumentoFiscal> itens)
		{
			List<Otus.Modulo.PontoDeVendas.ViewModels.ItemDocumentoFiscal> source = itens.ToListEmptyWhenNull();
			if (!source.Any())
			{
				return Enumerable.Empty<OrderItem>();
			}
			return source.Select(Morfar);
		}
	}
}
