	{
		public static readonly DependencyProperty NaoFicarSobreTudoProperty = DependencyProperty.RegisterAttached("NaoFicarSobreTudo", typeof(bool), typeof(PopupHelper), new PropertyMetadata(false, OnNaoFicarSobreTudoChanged));

		private static readonly IntPtr HWND_NOTOPMOST = new IntPtr(-2);

		private const uint SWP_NOSIZE = 1u;

		private const uint SWP_NOMOVE = 2u;

		private const uint SWP_NOACTIVATE = 16u;

		public static bool GetNaoFicarSobreTudo(DependencyObject obj)
		{
			return (bool)obj.GetValue(NaoFicarSobreTudoProperty);
		}

		public static void SetNaoFicarSobreTudo(DependencyObject obj, bool value)
		{
			obj.SetValue(NaoFicarSobreTudoProperty, value);
		}

		private static void OnNaoFicarSobreTudoChanged(DependencyObject d, DependencyPropertyChangedEventArgs e)
		{
			if (d is Popup popup)
			{
				if ((bool)e.NewValue)
				{
					popup.Opened += RemoverTopMost;
				}
				else
				{
					popup.Opened -= RemoverTopMost;
				}
			}
		}

		private static void RemoverTopMost(object sender, EventArgs e)
		{
			if (sender is Popup { Child: not null } popup && PresentationSource.FromVisual(popup.Child) is HwndSource hwndSource)
			{
				SetWindowPos(hwndSource.Handle, HWND_NOTOPMOST, 0, 0, 0, 0, 19u);
			}
		}

		[DllImport("user32.dll", SetLastError = true)]
		private static extern bool SetWindowPos(IntPtr hWnd, IntPtr hWndInsertAfter, int X, int Y, int cx, int cy, uint uFlags);
	}
}
