	public class ConsumidorLocal : BindableBase
	{
		private string _documento;

		private decimal _valorAtraso;

		public ObjectId Id { get; protected set; }

		public string Nome { get; protected set; }

		public int DiaAcerto { get; protected set; }

		public decimal LimiteDeCredito { get; protected set; }

		public decimal SaldoLimiteDeCredito { get; protected set; }

		public decimal TotalCreditoDevolucoes { get; protected set; }

		public decimal TotalCashback { get; protected set; }

		public string AvisoValorEmAtraso => $"Valor em atraso: {_valorAtraso:n2}";

		public DigisatServer.Domain.Main.Aggregates.CadastrosAgg.Pessoas.Pessoa Pessoa { get; protected set; }

		public string Documento
		{
			get
			{
				if (string.IsNullOrWhiteSpace(_documento))
				{
					return string.Empty;
				}
				return _documento.RemoverPontoBarraHifen().Length switch
				{
					11 => Convert.ToUInt64(_documento.RemoverPontoBarraHifen()).ToString("000\\.000\\.000\\-00"), 
					14 => FormatarCnpjAlfanumerico(_documento.RemoveCaracteresAlfanumerico()), 
					_ => _documento, 
				};
			}
			protected set
			{
				_documento = value;
			}
		}

		public bool Valido => !string.IsNullOrWhiteSpace(Documento);

		public string Endereco { get; protected set; }

		public Func<ClienteDto> FuncAtualizarClienteDto { get; protected set; }

		public bool PossuiValorEmAtraso => _valorAtraso > 0m;

		private ConsumidorLocal()
		{
		}

		private ConsumidorLocal(DigisatServer.Domain.Main.Aggregates.CadastrosAgg.Pessoas.Pessoa pessoa, Func<ClienteDto> funcAtualizarClienteDto)
		{
			Id = pessoa.Id;
			Nome = pessoa.Nome;
			_documento = (pessoa.IsEstrangeiro ? pessoa.To<Estrangeiro>().IdEstrangeiro : pessoa.CpfCnpj);
			Endereco = pessoa.ObterEndereco();
			DiaAcerto = pessoa.DiaAcerto;
			Pessoa = pessoa;
			FuncAtualizarClienteDto = funcAtualizarClienteDto;
		}

		private ConsumidorLocal(PessoaDto pessoa)
		{
			Id = ObjectId.Parse(pessoa.Id);
			Nome = pessoa.Nome;
			_documento = (pessoa.Estrangeiro.Is<EstrangeiroDtoNull>() ? pessoa.CpfCnpj : pessoa.Estrangeiro.IdEstrangeiro);
			Endereco = pessoa.EnderecoPrincipal.ToText;
			DiaAcerto = pessoa.DiaAcerto;
			Pessoa = pessoa.Morfar();
		}

		private static string FormatarCnpjAlfanumerico(string cnpj)
		{
			if (string.IsNullOrWhiteSpace(cnpj) || cnpj.Length != 14)
			{
				return cnpj;
			}
			return $"{cnpj.Substring(0, 2)}.{cnpj.Substring(2, 3)}.{cnpj.Substring(5, 3)}/{cnpj.Substring(8, 4)}-{cnpj.Substring(12, 2)}";
		}

		public override string ToString()
		{
			return Nome;
		}

		public static ConsumidorLocal Criar()
		{
			return new ConsumidorLocal();
		}

		public bool PossuiLimiteDeCreditoDisponivel(decimal valor)
		{
			if (LimiteDeCredito == 0m)
			{
				return true;
			}
			return SaldoLimiteDeCredito >= valor;
		}

		public void AtualizarClienteDto()
		{
			try
			{
				ClienteDto clienteDto = FuncAtualizarClienteDto();
				if (clienteDto != null)
				{
					LimiteDeCredito = clienteDto.LimiteCredito;
					SaldoLimiteDeCredito = clienteDto.SaldoLimiteCredito;
					TotalCreditoDevolucoes = clienteDto.TotalCreditoDevolucoes;
					TotalCashback = clienteDto.TotalCashback;
					RaisePropertyChanged(() => TotalCashback);
					_valorAtraso = clienteDto.ValorEmAtraso;
				}
			}
			catch (Exception)
			{
				DialogoFactory.MostrarDialogoConfirma("Erro ao atualizar saldo do cliente. Verifique a conexão com o servidor!");
			}
		}

		public ConsumidorLocal ComPessoa(DigisatServer.Domain.Main.Aggregates.CadastrosAgg.Pessoas.Pessoa pessoa)
		{
			return new ConsumidorLocal(pessoa, FuncAtualizarClienteDto);
		}

		public ConsumidorLocal ComPessoa(PessoaDto pessoa)
		{
			return new ConsumidorLocal(pessoa);
		}

		public ConsumidorLocal ComFuncAtualizarClienteDto(Func<ClienteDto> func)
		{
			FuncAtualizarClienteDto = func;
			return this;
		}
	}
