	public class ItemMovimentacaoFactory
	{
		private PreDocumentoFiscal _preDocumentoFiscal;

		private Otus.Modulo.PontoDeVendas.ViewModels.ItemDocumentoFiscal _item;

		public ItemMovimentacaoFactory SetarPreDocumentoFiscal(PreDocumentoFiscal preDocumentoFiscal)
		{
			_preDocumentoFiscal = preDocumentoFiscal;
			return this;
		}

		public ItemMovimentacaoFactory SetarItem(Otus.Modulo.PontoDeVendas.ViewModels.ItemDocumentoFiscal itemDocumentoFiscal)
		{
			_item = itemDocumentoFiscal;
			return this;
		}

		public DigisatServer.Domain.Main.Aggregates.MovimentacoesAgg.Itens.IItemDocumentoFiscal Criar()
		{
			DigisatServer.Domain.Main.Aggregates.MovimentacoesAgg.Itens.IItemDocumentoFiscal item = null;
			EmpresaHistorico empresa = _preDocumentoFiscal.Empresa.ObterPessoaHistorico() as EmpresaHistorico;
			PessoaHistorico pessoa = _preDocumentoFiscal.Consumidor.Pessoa.ObterPessoaHistorico();
			DigisatServer.Domain.Main.Aggregates.CadastrosAgg.OperacoesFiscal.OperacaoFiscal operacaoFiscal;
			if (_preDocumentoFiscal.TipoMovimentacao == TipoMovimentacao.NotaManual)
			{
				operacaoFiscal = OperacaoFiscalCadastroInicial.Obter5929();
			}
			else
			{
				operacaoFiscal = ((_item is ItemDocumentoFiscalCombustivel) ? _preDocumentoFiscal.ObterOperacaoFiscalCombustivel() : _item.ProdutoServicoLocal.OperacaoFiscal);
			}
			IIPI ipiNaoTributado = null;
			if (_item.Is<ItemDocumentoFiscalProduto>())
			{
				ipiNaoTributado = FluentFactory<IPIFactory>.Init().SetarCodigoCSTIPI(53).SetarCodigoEnquadramentoIPI(_item.ProdutoServicoLocal.To<ProdutoLocal>().Ipi.CodigoEnquadramentoIPI.Codigo)
					.Criar();
			}
			_item.ToDo((ItemDocumentoFiscalProduto itemProduto) =>
			{
				if (_preDocumentoFiscal.TipoMovimentacao == TipoMovimentacao.CupomFiscal)
				{
					item = new ItemDocumentoFiscalSaidaProdutoCupomFiscal(itemProduto.Estoque, itemProduto.PrecoUnitario, itemProduto.Desconto, 0m, itemProduto.Acrescimo, 0m, itemProduto.DataHora, itemProduto.ProdutoServicoLocal.ProdutoServicoHistorico, itemProduto.ProdutoServicoLocal.ProdutoServicoEmpresaReferencia, itemProduto.ProdutoServicoLocal.Ncm.NcmNbs, empresa, pessoa, !itemProduto.Ativo, itemProduto.Vendedor?.PessoaHistorico, operacaoFiscal, itemProduto.ProdutoServicoLocal.To<ProdutoLocal>().Percentual, itemProduto.ProdutoServicoLocal.To<ProdutoLocal>().Ipi, itemProduto.ProdutoServicoLocal.Pis, itemProduto.ProdutoServicoLocal.Cofins, itemProduto.Autorizacoes.MorfarCollection(), itemProduto.ProdutoServicoLocal.Cest, itemProduto.LimiteDesconto, itemProduto.IndiceAliquotaEcf, itemProduto.Tributacao, itemProduto.PercentualAliquota, string.Empty, string.Empty, itemProduto.ProdutoServicoLocal.PesoBruto, itemProduto.ProdutoServicoLocal.PesoLiquido, bloquearAlteracaoOperacaoFiscal: false, DadosSistema.ConfiguracaoDto.Saida.DescontarValorIcmsDesonerado.Valor, itemProduto.DepartamentoReferencia, itemProduto.IdPromocaoScanntech, itemProduto.TabelaPrecoLocal?.TabelaPrecoDto?.Morfar(), FormulasDifal.ObterPorCodigo(DadosSistema.ConfiguracaoDto.Saida.FormulaDifal.Valor), itemProduto.ProdutoServicoLocal.CodigoBeneficioFiscalCreditoPresumido, itemProduto.ProdutoServicoLocal.PercentualCreditoPresumido, FormulasCreditoPresumido.ObterPorCodigo(DadosSistema.ConfiguracaoDto.Saida.FormulaCreditoPresumido.Valor), string.Empty, itemProduto.ProdutoServicoLocal.To<ProdutoLocal>().PercentualReformaTributaria, vendaOrgaoGovernamental: false, 0m, string.Empty, 0, null, itemProduto.ComponentesRemovidos);
				}
