	public class ItemPagamentoFactory
	{
		private ItemPagamentoViewModel _itemPagamentoViewModel;

		private PreDocumentoFiscal _preDocumentoFiscal;

		private PagamentoRecebimentoFactory _recebimentoFactory;

		public ItemPagamentoFactory SetarItemPagamentoViewModel(ItemPagamentoViewModel itemPagamentoViewModel)
		{
			_itemPagamentoViewModel = itemPagamentoViewModel;
			return this;
		}

		public ItemPagamentoFactory SetarPreDocumentoFiscal(PreDocumentoFiscal preDocumentoFiscal)
		{
			_preDocumentoFiscal = preDocumentoFiscal;
			return this;
		}

		public ItemPagamentoFactory SetarRecebimento(PagamentoRecebimentoFactory recebimentoFactory)
		{
			_recebimentoFactory = recebimentoFactory;
			return this;
		}

		public ItemPagamento Criar()
		{
			ItemPagamento pagamento = null;
			_itemPagamentoViewModel.ToDo((IDinheiro dinheiro) =>
			{
				pagamento = new ItemPagamentoDinheiro((_preDocumentoFiscal.TotalTrocoDinheiro > 0m) ? (dinheiro.Valor - _preDocumentoFiscal.Troco) : dinheiro.Valor, dinheiro.Valor);
			});
			_itemPagamentoViewModel.ToDo((IVale vale) =>
			{
				pagamento = new ItemPagamentoVale((_preDocumentoFiscal.ContraVale > 0m && _preDocumentoFiscal.Troco > 0m) ? (vale.Valor - _preDocumentoFiscal.Troco) : vale.Valor, vale.Valor, new List<InformacaoVale>());
			});
			_itemPagamentoViewModel.ToDo((ICreditoLoja vale) =>
			{
				pagamento = new ItemPagamentoValeTroca((_preDocumentoFiscal.ContraVale > 0m && _preDocumentoFiscal.Troco > 0m) ? (vale.Valor - _preDocumentoFiscal.Troco) : vale.Valor, vale.Valor);
			});
			_itemPagamentoViewModel.ToDo((IValeDetalhado vale) =>
			{
				decimal num = ((_preDocumentoFiscal.ContraVale > 0m && _preDocumentoFiscal.Troco > 0m) ? (vale.Valor - _preDocumentoFiscal.Troco) : vale.Valor);
				if (num != vale.ValorPago)
				{
					vale.TiposDeVale.LastOrDefault().SetarValorPago(vale.ValorPago - num);
				}
				pagamento = new ItemPagamentoVale(num, vale.Valor, vale.TiposDeVale.Select((TipoDeVale x) => x.Obter()).ToListEmptyWhenNull());
			});
			_itemPagamentoViewModel.ToDo((ICartao cartao) =>
			{
				pagamento = new ItemPagamentoCartao(cartao.Valor, cartao.Valor, cartao.Cartoes);
			});
			_itemPagamentoViewModel.ToDo((ICartaoPos cartaoPos) =>
			{
				pagamento = new ItemPagamentoCartaoPos(cartaoPos.Valor, cartaoPos.Valor, cartaoPos.Redes.Select((RedePosLocal x) => x.Obter()).ToListEmptyWhenNull());
			});
			_itemPagamentoViewModel.ToDo((ICheque cheque) =>
			{
				pagamento = new ItemPagamentoCheque(cheque.Valor, cheque.Valor, _preDocumentoFiscal.Cheque);
			});
			_itemPagamentoViewModel.ToDo((IPrazo prazo) =>
			{
				pagamento = new ItemPagamentoPrazo(prazo.Valor, prazo.Valor, from x in _preDocumentoFiscal.Parcelas.OfType<ParcelaPrazo>()
					where x.CodigoEspeciePagamento == 3
					select x);
			});
			_itemPagamentoViewModel.ToDo((ConvenioFarmaciaPopularViewModel convenio) =>
			{
				pagamento = new ItemPagamentoConvenio(convenio.Valor, convenio.Valor, TipoConvenio.FarmaciaPopular);
			});
			_itemPagamentoViewModel.ToDo((ConvenioPbmViewModel convenio) =>
			{
				decimal valor = convenio.Valor;
				decimal valor2 = convenio.Valor;
				TipoConvenio tipoConvenio = ((convenio.Pbm == TipoPbm.EPharma) ? TipoConvenio.EPharma : ((convenio.Pbm == TipoPbm.VidaLink) ? TipoConvenio.VidaLink : TipoConvenio.PortalDrogaria));
				pagamento = new ItemPagamentoConvenio(valor, valor2, tipoConvenio);
			});
			_itemPagamentoViewModel.ToDo((IDepositoBancario depositoBancario) =>
			{
				pagamento = new ItemPagamentoDepositoBancario(depositoBancario.Valor, depositoBancario.Valor);
			});
			_itemPagamentoViewModel.ToDo((ITed depositoBancario) =>
			{
				pagamento = new ItemPagamentoTed(depositoBancario.Valor, depositoBancario.Valor);
			});
			_itemPagamentoViewModel.ToDo((IDoc depositoBancario) =>
			{
				pagamento = new ItemPagamentoDoc(depositoBancario.Valor, depositoBancario.Valor);
			});
			_itemPagamentoViewModel.ToDo((IValePresente valePresente) =>
			{
				pagamento = new ItemPagamentoValePresente(from x in valePresente.GetValePresente()
					select x.Id, valePresente.Valor, valePresente.Valor);
			});
			_itemPagamentoViewModel.ToDo((ICarteiraDigital carteiraDigital) =>
			{
				pagamento = new ItemPagamentoCarteiraDigital(carteiraDigital.Valor, carteiraDigital.Valor, carteiraDigital.InformacoesTransacoes);
			});
			_itemPagamentoViewModel.ToDo((ITerminalPos mobile) =>
			{
				pagamento = new ItemPagamentoTerminalPos(mobile.Valor, mobile.Valor, mobile.PagamentosTransacoes.MorfarCollectionPagamentosTransacoes());
			});
			_itemPagamentoViewModel.ToDo((IPagamentoPosterior pagamentoPosterior) =>
			{
				pagamento = new ItemPagamentoPagamentoPosterior(pagamentoPosterior.Valor, pagamentoPosterior.Valor, from x in _preDocumentoFiscal.Parcelas.OfType<ParcelaPrazo>()
					where x.CodigoEspeciePagamento == 29
					select x);
			});
			if (pagamento.IsNotNull())
			{
				_recebimentoFactory.SetarParcelas(pagamento.ObterParcelas(_preDocumentoFiscal, _itemPagamentoViewModel.EspeciePagamento).ToListEmptyWhenNull());
			}
			return pagamento;
		}
	}
