	public static class MapaResumoLocalSpecifications
	{
		public static ISpecification<MapaResumoLocal> All()
		{
			return new TrueSpecification<MapaResumoLocal>();
		}

		public static ISpecification<MapaResumoLocal> PorNumeroFabricacao(this ISpecification<MapaResumoLocal> specification, string numeroFabricacao)
		{
			return new AndSpecification<MapaResumoLocal>(specification, new DirectSpecification<MapaResumoLocal>((MapaResumoLocal m) => m.NumeroFabricacao.Equals(numeroFabricacao)));
		}

		public static ISpecification<MapaResumoLocal> PorDataMovimentoMaiorIgual(this ISpecification<MapaResumoLocal> specification, DateTime data)
		{
			return new AndSpecification<MapaResumoLocal>(specification, new DirectSpecification<MapaResumoLocal>((MapaResumoLocal m) => m.DataMovimento >= data));
		}

		public static ISpecification<MapaResumoLocal> PorDataMovimentoMenorIgual(this ISpecification<MapaResumoLocal> specification, DateTime data)
		{
			return new AndSpecification<MapaResumoLocal>(specification, new DirectSpecification<MapaResumoLocal>((MapaResumoLocal m) => m.DataMovimento <= data));
		}
	}
