			: base(seletor, produtoEmpresa, informacao, permitirEstoqueNegativo, impressora, itemFarmaciaPopularDto.QuantidadeAutorizada / (produtoEmpresa.Produto?.QuantidadeUnidadeFarmacotecnica ?? 1m))
