	public class MedicamentoLocal : ProdutoLocal
	{
		public decimal QuantidadeAutorizada { get; }

		public MedicamentoLocal(ItemDto itemDto, ProdutoEmpresa produtoEmpresa)
			: base(itemDto, produtoEmpresa)
		{
		}

		public MedicamentoLocal(Seletor<IPainel> seletor, ProdutoEmpresa produtoEmpresa, string informacao, bool permitirEstoqueNegativo, DigisatServer.Domain.Main.Aggregates.CadastrosAgg.Impressoras.Impressora impressora, decimal quantidadeAutorizada)
			: base(seletor, produtoEmpresa, informacao, permitirEstoqueNegativo, impressora, Enumerable.Empty<ComponenteBase>(), Enumerable.Empty<ObservacaoViewModel>(), 0m, string.Empty, 0m, venderComValorZerado: true, 0m, itemBase: false)
		{
			QuantidadeAutorizada = quantidadeAutorizada;
		}

		public override void ConfirmarEstoque()
		{
			List<IItemEstoque> list = (from z in Seletor.Get<PainelEstoque>().Campos.FirstOrDefault((IItemInteracao x) => x is ItemInteracaoListaEstoque).To<ItemInteracaoListaEstoque>().Valor.Itens
				where z.Quantidade > 0m
				select z.Obter()).ToList();
			decimal num = list.Sum((IItemEstoque x) => x.Quantidade);
			if (num != QuantidadeAutorizada)
			{
				DialogoFactory.MostrarDialogoConfirma($"A quantidade informada '{num}' não corresponde a quantidade autorizada '{QuantidadeAutorizada}'");
				return;
			}
			Seletor.VoltarTudo();
			Vender(((ProdutoEmpresa)ProdutoServicoEmpresa).Estoque.Criar(list));
		}
	}
