		public DigisatServer.Domain.Main.Aggregates.CadastrosAgg.RelacoesEspecieConta.RelacaoEspecieConta ObterRelacaoEspecieConta(int codigoEspeciePagamento, string administradoraCartao)
		{
			DigisatServer.Domain.Main.Aggregates.CadastrosAgg.RelacoesEspecieConta.RelacaoEspecieConta relacaoEspecieConta = ((!administradoraCartao.IsNullOrEmpty()) ? RelacoesEspecieConta?.FirstOrDefault((DigisatServer.Domain.Main.Aggregates.CadastrosAgg.RelacoesEspecieConta.RelacaoEspecieConta x) => x.CodigoEspeciePagamento.Equals(codigoEspeciePagamento) && x.AdministradoraCartaoReferencia.Equals(administradoraCartao.TryParseReferencia())) : RelacoesEspecieConta?.FirstOrDefault((DigisatServer.Domain.Main.Aggregates.CadastrosAgg.RelacoesEspecieConta.RelacaoEspecieConta x) => x.CodigoEspeciePagamento.Equals(codigoEspeciePagamento)));
			DigisatServer.Domain.Main.Aggregates.CadastrosAgg.RelacoesEspecieConta.RelacaoEspecieConta relacaoEspecieConta2 = ((!relacaoEspecieConta.IsNull()) ? relacaoEspecieConta : RelacoesEspecieConta?.FirstOrDefault((DigisatServer.Domain.Main.Aggregates.CadastrosAgg.RelacoesEspecieConta.RelacaoEspecieConta x) => x.CodigoEspeciePagamento.Equals(codigoEspeciePagamento)));
			if (relacaoEspecieConta2.IsNull())
			{
				return FluentFactory<RelacaoEspecieContaFactory>.Init().SetarEmpresaReferencia(DadosSistema.EmpresaLogada.Id.TryParseReferencia()).SetarConta(Conta)
					.SetarPlanoConta(PlanoConta)
					.SetarCentroCusto(CentroCusto)
					.Criar();
			}
			if (relacaoEspecieConta2.PlanoConta.IsNull())
			{
				relacaoEspecieConta2.PreencherPlanoConta(PlanoConta);
			}
			if (relacaoEspecieConta2.CentroCusto.IsNull())
			{
				relacaoEspecieConta2.PreencherCentroCusto(CentroCusto);
			}
			return relacaoEspecieConta2;
		}

