		public DateTime RetornarDataInicioEmissao()
		{
			DateTime now = DateTime.Now;
			if (_emissorService.Tipo != TipoMovimentacao.CupomFiscal)
			{
				return new DateTime(now.Year, now.Month, now.Day, now.Hour, now.Minute, now.Second, DateTimeKind.Utc);
			}
			return DataInicioEmissao;
		}

		public PreDocumentoFiscal(IRepositoryBaseWrite<PreDocumentoFiscal> preDocumentoFiscalRepositoryWrite, IRepositoryWrite<Movimentacao> movimentacaoRepositoryWrite, IRepositoryRead<DigisatServer.Domain.Main.Aggregates.CadastrosAgg.OperacoesFiscal.OperacaoFiscal> operacaoFiscalRepositoryRead, IRepositoryRead<Otus.Modulo.PontoDeVendas.Aggregates.Scanntech.PromocaoScanntech> promocaoScanntechRepositoryRead, IEmissorService emissorService, ISessaoService sessaoService, IEnumerable<Otus.Modulo.PontoDeVendas.ViewModels.ItemDocumentoFiscal> itens, DigisatServer.Domain.Main.Aggregates.CadastrosAgg.Pessoas.Pessoa empresa, ConsumidorLocal pessoa = null, VendedorLocal vendedor = null, TabelaPrecoLocal tabelaPreco = null, DadosVeiculoMaquinaEquipamento dadosVeiculoMaquinaEquipamento = null)
			: base(ObjectId.GenerateNewId())
		{
			SetarRepositorios(preDocumentoFiscalRepositoryWrite, movimentacaoRepositoryWrite, operacaoFiscalRepositoryRead, promocaoScanntechRepositoryRead);
			SetarEmissorService(emissorService);
			AtualizarDadosEmissor();
			NomeUsuario = sessaoService.Sessao.NomeUsuario;
			try
			{
				Empresa = empresa;
				Consumidor = pessoa ?? ConsumidorLocal.Criar().ComPessoa(DigisatServer.Domain.Main.Aggregates.CadastrosAgg.Pessoas.Consumidor.Criar().ComEndereco(Empresa.Carteira.EnderecoPrincipalNacional).Build());
			}
			catch (Exception)
			{
				throw new Exception("Falha ao gerar pré documento fiscal: Emitente não localizado na base local.");
			}
			Itens = itens;
			Vendedor = vendedor;
			TabelaPreco = tabelaPreco;
			DadosVeiculoMaquinaEquipamento = dadosVeiculoMaquinaEquipamento;
			CFeDto = _emissorService.To<ICFeService>()?.ObterCFeDto();
			ModalidadeFrete = FluentFactory<ModalidadeFreteFactory>.Init().Criar(9);
			IndicadorIntermediadorTransacao = IndicadorIntermediador.SemIntermediador;
			IndicadorPresencaComprador = IndicadoresPresencaComprador.Dados.FirstOrDefault((IndicadorPresencaComprador x) => x.Codigo.Equals(1));
			Tickets = new List<string>();
			try
			{
				NumeroPdvScanntech = DadosSistema.NumeroPdvScanntech;
				PlanoConta = DadosSistema.ObterPlanoContaPontoDeVenda();
				CentroCusto = DadosSistema.ObterCentroCustoPontoDeVenda();
				Conta = DadosSistema.ObterContaLivroCaixa();
				RelacoesEspecieConta = DadosSistema.ObterRelacaoEspecieConta();
				Juro = DadosSistema.ObterConfiguracao<TipoCalculoJuro, IJuro>();
				Multa = DadosSistema.ObterConfiguracao<PercentualMulta, Multa>();
				Salvar();
			}
			catch (Exception ex2)
			{
				throw new Exception("Falha ao gerar pré documento fiscal: " + ex2.Message);
			}
		}

