		public void Efetivar(TipoMovimentacao emissorServiceTipo)
		{
			TipoMovimentacao = emissorServiceTipo;
			PagamentoRecebimentoFactory recebimento = FluentFactory<PagamentoRecebimentoFactory>.Init();
			List<ItemPagamento> pagamentos = Pagamentos.Select((ItemPagamentoViewModel itemPagamentoViewModel) => FluentFactory<ItemPagamentoFactory>.Init().SetarItemPagamentoViewModel(itemPagamentoViewModel).SetarPreDocumentoFiscal(this)
				.SetarRecebimento(recebimento)
				.Criar()).ToList();
			switch (emissorServiceTipo)
			{
			case TipoMovimentacao.CupomFiscal:
				Efetivar(ProcessarCupomFiscal(recebimento.Criar(), pagamentos));
				break;
			case TipoMovimentacao.NotaManual:
				Efetivar(ProcessarNotaManual(recebimento.Criar()));
				break;
			case TipoMovimentacao.NotaFiscalConsumidorEletronica:
				ProcessarNotaFiscalConsumidorEletronica(recebimento.Criar(), pagamentos);
				break;
			case TipoMovimentacao.CupomFiscalEletronico:
				Efetivar(ProcessarCupomFiscalEletronico(recebimento.Criar(), pagamentos));
				break;
			case TipoMovimentacao.RegistroVenda:
				Efetivar(ProcessarRegistroVenda(recebimento.Criar(), pagamentos));
				break;
			}
		}

