		}

		private Movimentacao ProcessarCupomFiscalEletronico(IPagamentoRecebimento recebimento, IEnumerable<ItemPagamento> pagamentos)
		{
			return new DigisatServer.Domain.Main.Aggregates.MovimentacoesAgg.Saidas.CupomFiscalEletronico(_emissorService.RetornarNumeroFabricacao(), _emissorService.RetornarChaveAcesso(), _emissorService.RetornarNumeroDocumento(), DataInicioEmissao, Pessoa.ObterPessoaHistorico(), Empresa.ObterPessoaHistorico(), ProcessarItensCfe(), Desconto, OutrasDespesas, NomeUsuario, Observacao, UtilizouCashback, ValorCashbackUtilizado, new DigisatServer.Domain.Main.Aggregates.MovimentacoesAgg.ModelosDocumentoFiscal.CupomFiscalEletronico(), recebimento, MovimentacoesReferenciadas, _emissorService.RetornarXmlAutorizadoTexto(), Autorizacoes.ToListEmptyWhenNull().MorfarCollection(), pagamentos, _emissorService.RetornarNumeroSessao(), ObterConvenio(), DadosVeiculoMaquinaEquipamento, NumeroPdvScanntech, ComissaoSubsidiada, RetornoConsultaPbm?.Operadora, RetornoConsultaPbm?.NumeroAutorizacao, Tickets, null, ativo: true, default, Id);
		}

