		private Movimentacao ProcessarCupomFiscal(IPagamentoRecebimento recebimento, IEnumerable<ItemPagamento> pagamentos)
		{
			return new DigisatServer.Domain.Main.Aggregates.MovimentacoesAgg.Saidas.CupomFiscal(Coo, DataInicioEmissao, Consumidor.Pessoa.ObterPessoaHistorico(), Empresa.ObterPessoaHistorico() as EmpresaHistorico, ProcessarItens(), Desconto, OutrasDespesas, NomeUsuario, Observacao, UtilizouCashback, ValorCashbackUtilizado, recebimento, DataMovimento, NumeroFabricacao, MFAdicional, ModeloEcf, NumeroUsuario, NumeroSequencialEcf, Ccf, GnfCcd, pagamentos, Autorizacoes.ToListEmptyWhenNull().MorfarCollection(), MovimentacoesReferenciadas, ObterConvenio(), DadosVeiculoMaquinaEquipamento, NumeroPdvScanntech, ComissaoSubsidiada, Tickets);
		}

		private Movimentacao ProcessarNotaManual(IPagamentoRecebimento recebimento)
		{
			Efetivar(TipoMovimentacao.CupomFiscal);
			TipoMovimentacao = TipoMovimentacao.NotaManual;
			return new NotaFiscalManualPafEcf(_emissorService.RetornarNumeroFabricacao(), Numero, DataInicioEmissao, Consumidor.Pessoa.ObterPessoaHistorico(), Empresa.ObterPessoaHistorico(), ProcessarItens(), Desconto, OutrasDespesas, NomeUsuario, 0m, Observacao, UtilizouCashback, ValorCashbackUtilizado, recebimento as DigisatServer.Domain.Main.Aggregates.FinanceirosAgg.PagamentosRecebimentos.Recebimento, string.Empty, ComissaoSubsidiada, Autorizacoes.ToListEmptyWhenNull().MorfarCollection(), null, Tickets);
		}

		private void ProcessarNotaFiscalConsumidorEletronica(IPagamentoRecebimento recebimento, IEnumerable<ItemPagamento> pagamentos)
		{
			try
			{
				_emissorService.To<INfceService>().FinalizarNfce(this, recebimento, pagamentos);
				_preDocumentoFiscalRepositoryWrite.DeleteAll();
			}
			catch (ExceptionContingenciaOffline)
			{
				Efetivar(_emissorService.To<INfceService>().RetornarMovimentacaoNfceOffline(this, recebimento, pagamentos));
			}
		}

		private Movimentacao ProcessarRegistroVenda(IPagamentoRecebimento recebimento, IEnumerable<ItemPagamento> pagamentos)
		{
			List<DigisatServer.Domain.Main.Aggregates.MovimentacoesAgg.Itens.IItemDocumentoFiscal> itens = (from x in ProcessarItens()
				where !x.Cancelado
				select x).ToListEmptyWhenNull();
			return new RegistroVenda(_emissorService.RetornarNumeroDocumento(), RetornarDataInicioEmissao(), Consumidor.Pessoa.ObterPessoaHistorico(), Empresa.ObterPessoaHistorico() as EmpresaHistorico, itens, Desconto, OutrasDespesas, NomeUsuario, pagamentos, recebimento, MovimentacoesReferenciadas, ObterConvenio(), Observacao, TotalTrocoDinheiro, ModalidadeFrete.Valor, UtilizouCashback, ValorCashbackUtilizado, null, NumeroPdvScanntech, ComissaoSubsidiada, Autorizacoes.ToListEmptyWhenNull().MorfarCollection(), Tickets);
		}

		public void Cancelar(TipoMovimentacao emissorServiceTipo, AutorizacaoDto autorizacao = null)
		{
			if (emissorServiceTipo == TipoMovimentacao.CupomFiscal)
			{
				TipoMovimentacao = emissorServiceTipo;
				AdicionarAutorizacao(autorizacao);
				CanceladoSemItens = !Itens.Any();
				Salvar();
				Movimentacao movimentacao = ProcessarCupomFiscal(FluentFactory<PagamentoRecebimentoFactory>.Init().Criar(), null);
				Efetivar(movimentacao);
			}
		}

		private void Efetivar(Movimentacao movimentacao)
		{
			try
			{
				PreDocumentoFiscalLogService.CriarLog("------", erro: false);
				PreDocumentoFiscalLogService.CriarLog($"Antes de efetivar movimentação #{movimentacao.Numero}", erro: false);
				MovimentacaoJsonService.CriarJson(movimentacao);
				_movimentacaoRepositoryWrite.Add(movimentacao);
				PreDocumentoFiscalLogService.CriarLog("Movimentação adicionada na base", erro: false);
				_preDocumentoFiscalRepositoryWrite.DeleteAll();
				PreDocumentoFiscalLogService.CriarLog("Pré documento fiscal excluído", erro: false);
				_emissorService.EfetivouPreDocumentoFiscal(movimentacao);
				PreDocumentoFiscalLogService.CriarLog("Movimentação efetivada", erro: false);
			}
			catch (Exception ex)
			{
				PreDocumentoFiscalLogService.CriarLog($"Erro ao efetivar movimentação: {ex.Message}", erro: true);
				throw ex;
			}
		}

		public void Salvar()
		{
			_preDocumentoFiscalRepositoryWrite.Update(this);
		}

