		public void SetarMovimentacaoReferenciada(MovimentacaoDto movimentacao)
		{
			List<MovimentacaoReferenciada> movimentacoesReferenciadas = new List<MovimentacaoReferenciada>(MovimentacoesReferenciadas.ToListEmptyWhenNull()) { FluentFactory<MovimentacaoReferenciadaFactory>.Init().SetarTipo(movimentacao.Tipo).SetarDataHoraEmissao(movimentacao.DataHoraEmissao)
