								item11.ComIdPromocaoScanntech(promocaoScanntech.IdPromocao);
							}
							num15 -= item11.Quantidade;
						}
						foreach (Otus.Modulo.PontoDeVendas.ViewModels.ItemDocumentoFiscal item12 in enumerable5)
						{
							item12.ComAplicouPromocaoScanntech(aplicouPromocaoScanntech: true);
						}
						promocaoScanntech.IncrementarPromocaoAplicada();
					}
					break;
				case TipoPromocao.DESCUENTO_FIJO:
					foreach (Otus.Modulo.PontoDeVendas.Aggregates.Scanntech.Item item13 in promocaoScanntech.Detalhe.Condicao.Itens.Where((Otus.Modulo.PontoDeVendas.Aggregates.Scanntech.Item x) => x.Produtos.Any((Otus.Modulo.PontoDeVendas.Aggregates.Scanntech.Produto y) => y.CodigoBarras.Equals(item.CodigoBarras))))
					{
						decimal num2 = item13.Produtos.Sum((Otus.Modulo.PontoDeVendas.Aggregates.Scanntech.Produto produtoCondicao) => itensAgrupadosPorBarras.FirstOrDefault((ItemPromocaoScanntech x) => x.CodigoBarras.Equals(produtoCondicao.CodigoBarras))?.Quantidade ?? 0m);
						string[] codigosBarrasDaPromocao = item13.Produtos.Select((Otus.Modulo.PontoDeVendas.Aggregates.Scanntech.Produto produtoCondicao) => produtoCondicao.CodigoBarras).ToArray();
						decimal num3 = Math.Truncate(num2 / item13.Quantidade);
						if (promocaoScanntech.Limite != 0 && num3 > (decimal)promocaoScanntech.Limite)
						{
							num3 = promocaoScanntech.Limite;
						}
						decimal num4 = num3 * item13.Quantidade;
						IEnumerable<Otus.Modulo.PontoDeVendas.ViewModels.ItemDocumentoFiscal> enumerable2 = Itens.Where((Otus.Modulo.PontoDeVendas.ViewModels.ItemDocumentoFiscal x) => x.ProdutoServicoLocal.Barras.In(codigosBarrasDaPromocao) && !x.AplicouPromocaoScanntech && x.Ativo);
						decimal num5 = Math.Round(promocaoScanntech.Detalhe.Desconto / item13.Quantidade, 2, MidpointRounding.AwayFromZero);
						decimal num6 = promocaoScanntech.Detalhe.Desconto - num5 * item13.Quantidade;
						decimal num7 = num4 / item13.Quantidade;
						foreach (Otus.Modulo.PontoDeVendas.ViewModels.ItemDocumentoFiscal item14 in enumerable2)
						{
							if (num4 <= 0m)
							{
								break;
							}
							if (item14.Quantidade >= num4)
							{
								item14.ComDesconto(num5 * num4 - ((num6 < 0m) ? (num6 * -1m * num7) : (num6 * num7)));
								AplicarDescontoPromocaoScanntech(item14);
								item14.ComIdPromocaoScanntech(promocaoScanntech.IdPromocao);
							}
							else
							{
								item14.ComDesconto(num5 * item14.Quantidade);
								AplicarDescontoPromocaoScanntech(item14);
								item14.ComIdPromocaoScanntech(promocaoScanntech.IdPromocao);
							}
							num4 -= item14.Quantidade;
						}
						foreach (Otus.Modulo.PontoDeVendas.ViewModels.ItemDocumentoFiscal item15 in enumerable2)
						{
							item15.ComAplicouPromocaoScanntech(aplicouPromocaoScanntech: true);
						}
						promocaoScanntech.IncrementarPromocaoAplicada();
					}
					break;
				}
			}
			if (_acrescimosRemovidos.Any())
			{
				DialogoFactory.MostrarDialogoConfirma($"O acréscimo dos itens abaixo relacionados foram removidos para ativação da promoção Scanntech:\n{_acrescimosRemovidos.ToArray().LinhasParaTexto()}");
			}
		}

		public IEnumerable<Otus.Modulo.PontoDeVendas.Aggregates.Scanntech.PromocaoScanntech> RetornarPromocoesScanntech()
		{
			IEnumerable<Otus.Modulo.PontoDeVendas.Aggregates.Scanntech.PromocaoScanntech> enumerable = _promocaoScanntechRepositoryRead.Find(EntitySpecification<Otus.Modulo.PontoDeVendas.Aggregates.Scanntech.PromocaoScanntech>.Ativo().PorVigenteDataAtual().PorEmpresa(Empresa.Id)
				.PorMeioPagamentoNull());
			if (enumerable.Any())
			{
				return enumerable;
			}
			return null;
		}

		private void AplicarDescontoPromocaoScanntech(Otus.Modulo.PontoDeVendas.ViewModels.ItemDocumentoFiscal itemDaVenda)
		{
			_emissorService.AplicarDesconto(itemDaVenda, itemDaVenda.Desconto);
			if (itemDaVenda.Acrescimo > 0m)
			{
				_acrescimosRemovidos.Add($"{itemDaVenda.Descricao}\n");
				itemDaVenda.ComAcrescimo(0m);
				_emissorService.AplicarAcrescimo(itemDaVenda, 0m);
			}
		}

		private Otus.Modulo.PontoDeVendas.ViewModels.ItemDocumentoFiscal RetornarItemDaVenda(string[] codigosBarrasDaPromocao)
		{
			return (from x in Itens
				where x.ProdutoServicoLocal.Barras.In(codigosBarrasDaPromocao) && string.IsNullOrEmpty(x.IdPromocaoScanntech) && x.Ativo
				orderby x.Total descending
				select x).FirstOrDefault();
		}

		public void DesfazerAplicacaoPromocoesScanntech()
		{
			foreach (Otus.Modulo.PontoDeVendas.ViewModels.ItemDocumentoFiscal iten in Itens)
			{
				iten.ComDesconto(0m).ComAplicouPromocaoScanntech(aplicouPromocaoScanntech: false).ComIdPromocaoScanntech(string.Empty);
			}
		}

		public void SetarOutrasDespesas(decimal outrasDespesas)
		{
			OutrasDespesas = outrasDespesas;
		}
	}
