		public void Efetivar(IRepositoryBaseWrite<PreDocumentoFiscal> preDocumentoFiscalRepositoryWrite, IRepositoryWrite<Movimentacao> movimentacaoRepositoryWrite, IRepositoryRead<DigisatServer.Domain.Main.Aggregates.CadastrosAgg.OperacoesFiscal.OperacaoFiscal> operacaoFiscalRepositoryRead, IRepositoryRead<Otus.Modulo.PontoDeVendas.Aggregates.Scanntech.PromocaoScanntech> promocaoScanntechRepositoryRead, IEmissorService emissorService)
		{
