			PreDocumentoFiscal.SetarEmissorService(emissorService);
			if (string.IsNullOrWhiteSpace(PreDocumentoFiscal.NumeroFabricacao))
			{
				PreDocumentoFiscal.AtualizarDadosEmissor();
			}
			PreDocumentoFiscal.SetarObservacao(string.Join(string.Empty, MensagensPromocionais.SelectMany((IMensagemPromocional x) => x.Linhas.Select((string linha) => linha + Environment.NewLine))));
