			: base(seletor, informacao, produtoEmpresa, impressora)
		{
			_produtoEmpresa = produtoEmpresa;
			_permitirEstoqueNegativo = permitirEstoqueNegativo;
			_componentesRemovidos = componentesRemovidos;
			_observacoes = observacoes;
			_quantidadeImprimirAmbienteProducao = quantidadeImprimirAmbienteProducao;
			_itemBase = itemBase;
			Cest = produtoEmpresa.CodigoEspecificadorSubstituicaoTributaria;
			Barras = produtoEmpresa.Produto.CodigoBarras;
			Pesavel = produtoEmpresa.Produto.Pesavel;
			Percentual = produtoEmpresa.TributacaoEstadual.ObterPercentualNaoContribuinte();
			PercentualReformaTributaria = produtoEmpresa.TributacaoIbsCbs?.ObterPercentualNaoContribuinte();
			Tributacao = produtoEmpresa.TributacaoEstadual.TributacaoEcf?.Tributacao ?? Percentual.SituacaoTributaria.Tipo;
			PercentualAliquota = produtoEmpresa.TributacaoEstadual.TributacaoEcf?.Percentual ?? Percentual.To<IPercentualIcms>()?.PercentualIcms ?? 0m;
			Ipi = produtoEmpresa.TributacaoFederal.TributacaoIpi.IpiSaida;
			OperacaoFiscal = Percentual.To<Percentual>().OperacaoFiscal;
			Quantidade = produtoEmpresa.Estoque.Quantidade;
			QuantidadeSaldo = produtoEmpresa.Estoque.QuantidadeSaldo;
			produtoEmpresa.Produto.ToDo((DerivadoPetroleo p) =>
			{
				CodigoAnp = p.TipoProdutoAnp.Codigo;
			});
			Imagem = produtoEmpresa.Produto.Imagem;
			CodigoBeneficioFiscalUf = ((!produtoEmpresa.TributacaoEstadual.ObterPercentualNaoContribuinte().EnviarCodigoBeneficioFiscal) ? string.Empty : (string.IsNullOrEmpty(produtoEmpresa.TributacaoEstadual.ObterPercentualNaoContribuinte().CodigoBeneficioFiscalUf) ? produtoEmpresa.CodigoBeneficioFiscalUf.ToStringEmptyWhenNull() : produtoEmpresa.TributacaoEstadual.ObterPercentualNaoContribuinte().CodigoBeneficioFiscalUf.ToStringEmptyWhenNull()));
			CodigoBeneficioFiscalCreditoPresumido = (produtoEmpresa.TributacaoEstadual.ObterPercentualNaoContribuinte().EnviarCodigoBeneficioFiscal ? produtoEmpresa.CodigoBeneficioFiscalCreditoPresumido : string.Empty);
