			{
				SetarPrecoUnitario(valorItemMaiorValor);
			}
		}

		private void AplicarDescontoBeneficio(decimal valorDescontarBeneficio, bool venderComValorZerado)
		{
			if (!(valorDescontarBeneficio <= 0m))
			{
				decimal num = Preco - valorDescontarBeneficio;
				ProdutoLocal produtoLocal = this;
				decimal precoUnitario;
				if (num <= 0m)
				{
					precoUnitario = (venderComValorZerado ? 0m : 0.01m);
				}
				else
				{
					precoUnitario = num;
				}
				produtoLocal.SetarPrecoUnitario(precoUnitario);
			}
		}

		public override async void Vender(decimal quantidade, bool capturouPeso = false)
		{
			if (ProdutoEmpresa.Produto is Medicamento && (ProdutoEmpresa.Produto.To<Medicamento>().ClasseTerapeutica.Is<Antimicrobiano>() || ProdutoEmpresa.Produto.To<Medicamento>().ClasseTerapeutica.Is<SujeitoAControleEspecial>()))
			{
				DialogoFactory.MostrarDialogoConfirma("Atenção! Acesse o módulo SNGPC para adicionar a receita.");
			}
			if (ProdutoEmpresa.Estoque.IsNormal && !ProdutoEmpresa.Estoque.PermiteVendaFracionada && quantidade % 1m != 0m)
			{
				DialogoFactory.MostrarDialogoConfirma("Produto configurado para não ser vendido fracionado.");
				return;
			}
			if (ProdutoEmpresa.Produto is Combustivel)
			{
				DialogoFactory.MostrarDialogoConfirma("Produtos do tipo 'Combustível' só podem ser vendidos a partir da importação de abastecimentos.");
				return;
			}
			if (ProdutoEmpresa.Produto.Pesavel && !ProdutoEmpresa.Produto.UnidadeMedida.IsUnidade && !capturouPeso)
			{
				try
				{
					await Seletor.Get<PainelDocumentoFiscal>().ExecutarLerPeso(ProdutoEmpresa, (decimal peso) =>
					{
						Vender(PreencherEstoque(peso, capturouPeso: true));
					});
					return;
				}
				catch (Exception)
				{
					return;
				}
			}
			if (!ProdutoEmpresa.Produto.Pesavel & capturouPeso)
			{
				DialogoFactory.MostrarDialogoConfirma("Esse produto não é pesável!");
			}
			else
			{
				Vender(PreencherEstoque(quantidade, capturouPeso));
			}
		}

		public Estoque ObterEstoqueVenda(decimal quantidade)
		{
			return ProdutoEmpresa.Estoque.Criar(quantidade);
		}

		public Estoque PreencherEstoque(decimal quantidade, bool capturouPeso = false)
		{
			List<IItemEstoque> list = ProdutoEmpresa.Estoque.Pesquisar(InformacaoPesquisa, quantidade).ToList();
			if (list.Any())
			{
				return ProdutoEmpresa.Estoque.Criar(list);
			}
			if (ProdutoEmpresa.Estoque.IsNormal)
			{
				Estoque estoque = ProdutoEmpresa.Estoque.Criar(quantidade);
				if (ProdutoEmpresa.Produto is DigisatServer.Domain.Main.Aggregates.CadastrosAgg.ProdutosServicos.Produtos.Composicao && DadosSistema.ConfiguracaoDto.Saida.MontarComposicaoAutomaticamente.Valor)
				{
					try
					{
						decimal quantidade2 = Seletor.Get<PainelDocumentoFiscal>().ProdutoServicoEmpresaRepositoryRead.ObterComposicaoMontagem(ProdutoEmpresa.Id.ToString(), GetComponentesRemovidos()).ValidarQuantidadeVendida(ObterEstoqueVendidos(Seletor).Sum((Estoque x) => x.Quantidade), quantidade, DadosSistema.ConfiguracaoDto.Saida.PermitirEstoqueNegativo.Valor);
						estoque.SetarQuantidadeParaMontarComposicao(quantidade2);
					}
					catch (Exception ex)
					{
						ex.ShowLastException();
						return null;
					}
				}
				return estoque;
			}
			EstoqueBase estoqueBase = ProdutoEmpresa.Estoque.To<EstoqueBase>();
			IEnumerable<IItemEstoque> enumerable = estoqueBase.ObterDisponiveisVenda(ObterEstoqueVendidos(Seletor), DadosSistema.ConfiguracaoDto.Saida.PermitirEstoqueNegativo.Valor);
			if (!enumerable.Any())
			{
				if (estoqueBase.Is<EstoqueSerial>())
				{
					DialogoFactory.MostrarDialogoConfirma("Nenhum serial disponível para venda");
				}
				if (estoqueBase.Is<EstoqueLote>())
				{
					DialogoFactory.MostrarDialogoConfirma("Nenhum lote disponível para venda");
				}
				if (estoqueBase.Is<EstoqueGrade>())
				{
					DialogoFactory.MostrarDialogoConfirma("Nenhuma grade disponível para venda");
				}
				return null;
			}
			decimal quantidadeInformada = (capturouPeso ? quantidade : 0m);
			if (DadosSistema.ConfiguracaoDto.Saida.MostrarSomenteLotesValidos.Valor && estoqueBase.Is<EstoqueLote>())
			{
				enumerable = from x in enumerable.OfType<ItemEstoqueLote>()
					where x.DataValidade.Date >= DateTime.Now.Date
					select x;
			}
			ItemInteracaoListaEstoque itemInteracaoListaEstoque = ItemInteracaoBase<ItemInteracaoListaEstoque, Lista<Otus.Modulo.PontoDeVendas.ViewModels.ItemBase>>.Criar().ComDescricao("Lista de estoque").ComValor(ItemListaBase.Criar(enumerable))
				.Build();
			itemInteracaoListaEstoque.SetarQuantidadeInformada(quantidadeInformada);
			itemInteracaoListaEstoque.Valor.PosicionarNoPrimeiro();
			Seletor.Get<PainelEstoque>().Campos.Add(itemInteracaoListaEstoque);
			Seletor.Get<PainelEstoque>().SetarProdutoServicoLocal(this);
			Seletor.Selecionar<PainelEstoque, PainelDocumentoFiscal>();
			return null;
		}

		public Estoque CriarEstoqueControlado(decimal quantidade)
		{
			_venderAoConfirmarEstoque = false;
			List<IItemEstoque> list = ProdutoEmpresa.Estoque.Pesquisar(InformacaoPesquisa, quantidade).ToList();
			if (list.Any())
			{
				return ProdutoEmpresa.Estoque.Criar(list);
			}
			EstoqueBase estoqueBase = ProdutoEmpresa.Estoque.To<EstoqueBase>();
			IEnumerable<IItemEstoque> enumerable = estoqueBase.ObterDisponiveisVenda(ObterEstoqueVendidos(Seletor), DadosSistema.ConfiguracaoDto.Saida.PermitirEstoqueNegativo.Valor);
			if (!enumerable.Any())
			{
				if (estoqueBase.Is<EstoqueSerial>())
				{
					DialogoFactory.MostrarDialogoConfirma("Nenhum serial disponível para venda");
				}
				if (estoqueBase.Is<EstoqueLote>())
				{
					DialogoFactory.MostrarDialogoConfirma("Nenhum lote disponível para venda");
				}
				if (estoqueBase.Is<EstoqueGrade>())
				{
					DialogoFactory.MostrarDialogoConfirma("Nenhuma grade disponível para venda");
				}
				return null;
			}
			ItemInteracaoListaEstoque itemInteracaoListaEstoque = ItemInteracaoBase<ItemInteracaoListaEstoque, Lista<Otus.Modulo.PontoDeVendas.ViewModels.ItemBase>>.Criar().ComDescricao("Lista de estoque").ComValor(ItemListaBase.Criar(enumerable))
				.Build();
			itemInteracaoListaEstoque.Valor.PosicionarNoPrimeiro();
			Seletor.Get<PainelEstoque>().Campos.Add(itemInteracaoListaEstoque);
			Seletor.Get<PainelEstoque>().SetarProdutoServicoLocal(this);
			Seletor.Selecionar<PainelEstoque, PainelDocumentoFiscal>();
			return null;
		}

		public IEnumerable<Estoque> ObterEstoqueVendidos(Seletor<IPainel> seletor)
		{
			List<Estoque> first = (from x in seletor.Get<PainelDocumentoFiscal>().Lista.Itens.OfType<ItemDocumentoFiscalProduto>()
				where x.Ativo && x.Estoque.Id.Equals(ProdutoEmpresa.Estoque.Id)
				select x.Estoque).ToList();
			List<Estoque> second = (from x in seletor.Get<PainelDocumentoFiscal>().ObterItensPendentes().OfType<ItemDocumentoFiscalProduto>()
				where x.Ativo && x.Estoque.Id.Equals(ProdutoEmpresa.Estoque.Id)
				select x.Estoque).ToList();
			return first.Union(second);
		}

		protected void Vender(Estoque estoque)
		{
			if (estoque.IsNull())
			{
				return;
			}
			try
			{
				IEnumerable<Estoque> estoquesVendidos = ObterEstoqueVendidos(Seletor);
				if (OperacaoFiscal.MovimentaEstoque)
				{
					_produtoEmpresa.TemEstoque(estoque, estoquesVendidos, _permitirEstoqueNegativo, DadosSistema.ConfiguracaoDto.Saida.MontarComposicaoAutomaticamente.Valor, isOrcamento: false);
				}
				if (_produtoEmpresa.Estoque.VerificarQuantidadeMinima(estoque, estoquesVendidos, DadosSistema.ConfiguracaoDto.Saida.AlertarQuantidadeMinimaMaximaAtingida.Valor))
				{
					DialogoFactory.MostrarDialogoConfirma("Quantidade mínima em estoque atingida.");
				}
				Quantidade = estoque.Quantidade;
				if (Quantidade <= 0m && !_itemBase)
				{
					throw new Exception("Quantidade inválida!");
				}
				if (ProdutoEmpresa.Estoque.IsNormal && !ProdutoEmpresa.Estoque.PermiteVendaFracionada && Quantidade % 1m != 0m)
				{
					throw new Exception("Produto configurado para não ser vendido fracionado.");
				}
				if (!DadosSistema.PodeExecutarFuncao(typeof(Gerencial), typeof(Administrador), typeof(AdministradorIndustria)) || !DadosSistema.ConfiguracaoDto.Saida.AlertarUsuarioAcimaQuantidadeEstipulada.Valor || !(Quantidade > (decimal)DadosSistema.ConfiguracaoDto.Saida.QuantidadeEstipuladaAlertar.Valor) || DialogoFactory.MostrarDialogoSimNao("Quantidade elevada. Continuar?") != MessageBoxResult.No)
				{
					Seletor.Get<PainelDocumentoFiscal>().Vender(CriarItemDocumentoFiscalProduto(estoque));
				}
			}
			catch (Exception ex)
			{
				if (ex.Message.Contains("Produto atingiu estoque negativo!"))
				{
					DialogoFactory.MostrarDialogoConfirma($"Produto: {_produtoEmpresa.ProdutoServico.Descricao}\n" + $"Preço: {_produtoEmpresa.Preco.PrecoVendaVigente.FormatarCampoValor(2)}\n" + "Atingiu estoque negativo!", bloquearEnter: true, System.Windows.HorizontalAlignment.Left);
				}
				else
				{
					ex.ShowLastException("", yesNo: false, bloquearEnter: true);
				}
			}
		}

		public virtual void ConfirmarEstoque()
		{
			List<IItemEstoque> list = (from z in Seletor.Get<PainelEstoque>().Campos.FirstOrDefault((IItemInteracao x) => x is ItemInteracaoListaEstoque).To<ItemInteracaoListaEstoque>().Valor.Itens
				where z.Quantidade > 0m
				select z.Obter()).ToList();
			if (list.OfType<ItemEstoqueLote>().Any() && !ValidarLotes(list.OfType<ItemEstoqueLote>()))
			{
				Seletor.VoltarTudo();
				return;
			}
			_estoqueVendido = ((ProdutoEmpresa)ProdutoServicoEmpresa).Estoque.Criar(list);
			Seletor.VoltarTudo();
			if (_venderAoConfirmarEstoque)
			{
				Vender(_estoqueVendido);
			}
		}

		private bool ValidarLotes(IEnumerable<ItemEstoqueLote> estoqueLote)
		{
			IEnumerable<string> enumerable = from l in estoqueLote
				where l.To<ItemEstoqueLote>().DataValidade < DateTime.Today && l.To<ItemEstoqueLote>().Quantidade > 0m
				select l.To<ItemEstoqueLote>().Numero;
			if (!enumerable.Any())
			{
				return true;
			}
			return DialogoFactory.MostrarDialogoSimNao(string.Format("Os seguintes lotes estão vencidos: {0}.\nDeseja continuar?", string.Join("; ", enumerable))) == MessageBoxResult.Yes;
		}

		public Estoque ObterEstoqueControladoVendido()
		{
			return _estoqueVendido;
		}

		protected Otus.Modulo.PontoDeVendas.ViewModels.ItemDocumentoFiscal CriarItemDocumentoFiscalProduto(Estoque estoque)
		{
			ItemDocumentoFiscalProduto itemDocumentoFiscalProduto = CriarItemDocumentoFiscal().To<ItemDocumentoFiscalProduto>().ComEstoque(estoque);
			itemDocumentoFiscalProduto.SalvarObservacoes(ResumoObservacoesAgrupadas);
			itemDocumentoFiscalProduto.ComDescricaoMenuRapido(DescricaoMenuRapido);
			itemDocumentoFiscalProduto.ComQuantidadeImprimirAmbienteProducao(_quantidadeImprimirAmbienteProducao);
			return itemDocumentoFiscalProduto;
		}

		public Estoque ProcessarComposicaoRestaurante(decimal quantidade, Seletor<IPainel> seletor)
		{
			Seletor = seletor;
			return PreencherEstoque(quantidade);
		}

		public IEnumerable<ComponenteBase> GetComponentesRemovidos()
		{
			return _componentesRemovidos.ToListEmptyWhenNull();
		}
	}
