		public ProdutoServicoLocalFactory ComItemBase(bool itemBase)
		{
			_itemBase = itemBase;
			return this;
		}

		public ProdutoServicoLocal Criar()
		{
			if (_itemDto != null)
			{
				if (_itemDto.ProdutoServico.Tipo == TipoProdutoServico.Servico)
				{
					return new ServicoLocal(_itemDto, _produtoServicoEmpresa.To<ServicoEmpresa>());
				}
				if (!_seletor.IsNotNull())
				{
					return new ProdutoLocal(_itemDto, _produtoServicoEmpresa.To<ProdutoEmpresa>());
				}
				return new ProdutoLocal(_seletor, _itemDto, _produtoServicoEmpresa.To<ProdutoEmpresa>());
			}
			if (_itemFarmaciaPopular != null)
			{
				return new MedicamentoFarmaciaPopularLocal(_seletor, _produtoServicoEmpresa.To<ProdutoEmpresa>(), _informacaoPesquisa, _permitirEstoqueNegativo, _impressora, _itemFarmaciaPopular);
			}
			if (_produtoAutorizado != null)
			{
				return new MedicamentoPbmLocal(_seletor, _produtoServicoEmpresa.To<ProdutoEmpresa>(), _informacaoPesquisa, _permitirEstoqueNegativo, _impressora, _produtoAutorizado);
			}
			if (_produtoServicoEmpresa is ServicoEmpresa)
			{
				if (_catalogo)
				{
					return new ServicoCatalogoLocal(_seletor, _produtoServicoEmpresa.To<ServicoEmpresa>());
				}
				return new ServicoLocal(_seletor, _produtoServicoEmpresa.To<ServicoEmpresa>(), _informacaoPesquisa);
			}
			if (_catalogo)
			{
				return new ProdutoCatalogoLocal(_seletor, _produtoServicoEmpresa.To<ProdutoEmpresa>(), _permitirEstoqueNegativo, _impressora, _componentesRemovidos, _observacoes, _valorDescontarBeneficio, _descricaoMenuRapido, _valorItemMaiorValor, _venderComValorZerado, _quantidadeImprimirAmbienteProducao, _itemBase);
			}
			return new ProdutoLocal(_seletor, _produtoServicoEmpresa.To<ProdutoEmpresa>(), _informacaoPesquisa, _permitirEstoqueNegativo, _impressora, _componentesRemovidos, _observacoes, _valorDescontarBeneficio, _descricaoMenuRapido, _valorItemMaiorValor, _venderComValorZerado, _quantidadeImprimirAmbienteProducao, _itemBase);
		}
	}
