	public class ServicoLocal : ProdutoServicoLocal
	{
		public IISS Iss { get; protected set; }

		[BsonIgnore]
		public byte[] Imagem { get; protected set; }

		public CodigoAtividade CodigoAtividade { get; protected set; }

		public string CodigoTributacaoMunicipio { get; protected set; }

		public ServicoLocal(ItemDto itemDto, ServicoEmpresa servicoEmpresa)
			: base(itemDto, servicoEmpresa)
		{
			Tributacao = servicoEmpresa.TributacaoMunicipal.Iss.CstIss.Tipo;
			PercentualAliquota = servicoEmpresa.TributacaoMunicipal.Iss.To<IISSNormal>()?.Percentual ?? 0m;
			OperacaoFiscal = itemDto.OperacaoFiscal.Morfar();
			Iss = itemDto.Iss.MorfarCalculadoSistema(itemDto.OperacaoFiscal.Id);
			CodigoTributacaoMunicipio = itemDto.CodigoTributacaoMunicipio;
			Imagem = servicoEmpresa.Servico.Imagem;
		}

		public ServicoLocal(Seletor<IPainel> seletor, ServicoEmpresa servicoEmpresa, string informacao)
			: base(seletor, informacao, servicoEmpresa)
		{
			Imagem = servicoEmpresa.Servico.Imagem;
			Tributacao = servicoEmpresa.TributacaoMunicipal.Iss.CstIss.Tipo;
			PercentualAliquota = servicoEmpresa.TributacaoMunicipal.Iss.To<IISSNormal>()?.Percentual ?? 0m;
			OperacaoFiscal = servicoEmpresa.TributacaoMunicipal.Iss.OperacaoFiscal;
			Iss = servicoEmpresa.TributacaoMunicipal.Iss;
			CodigoAtividade = servicoEmpresa.ProdutoServico.To<Servico>().CodigoAtividade;
			CodigoTributacaoMunicipio = servicoEmpresa.CodigoTributacaoMunicipio;
		}

		public override void Vender(decimal quantidade, bool capturouPeso = false)
		{
			try
			{
				if (!DadosSistema.ConfiguracaoDto.Saida.EmiteDocumentoFiscalConjugado.Valor)
				{
					DialogoFactory.MostrarDialogoConfirma("Selecione um cadastro do tipo 'Produto' vendável!");
					return;
				}
				Quantidade = quantidade;
				if (!DadosSistema.ConfiguracaoDto.Saida.AlertarUsuarioAcimaQuantidadeEstipulada.Valor || !(Quantidade >= (decimal)DadosSistema.ConfiguracaoDto.Saida.QuantidadeEstipuladaAlertar.Valor) || DialogoFactory.MostrarDialogoSimNao("Quantidade elevada. Continuar?") != MessageBoxResult.No)
				{
					Seletor.Get<PainelDocumentoFiscal>().Vender(CriarItemDocumentoFiscal());
				}
			}
			catch (Exception ex)
			{
				ex.ShowLastException();
			}
		}

		protected override Otus.Modulo.PontoDeVendas.ViewModels.ItemDocumentoFiscal CriarItemDocumentoFiscal()
		{
			return base.CriarItemDocumentoFiscal().To<ItemDocumentoFiscalServico>();
		}
	}
