		protected string InformacaoPesquisa;

		public string Descricao { get; protected set; }

		public string DescricaoEMarca
		{
			get
			{
				if (!Marca.IsNullOrEmpty())
				{
					return $"{Descricao} ({Marca})";
				}
				return $"{Descricao}";
			}
		}

		public string Marca { get; protected set; }

		public string DescricaoMenuRapido { get; protected set; }

		public string CodigoInterno { get; protected set; }

		public string Barras { get; protected set; }

		public string ToolTipBuscaAberta
		{
			get
			{
				string text = (Marca.IsNullOrEmpty() ? string.Empty : $"\nMarca: {Marca}");
				if (!Caracteristica.IsNullOrEmpty())
				{
					return $"Código: {CodigoInterno} Barras: {Barras} Descrição: {Descricao} \nCaracterística: {Caracteristica} {text}";
				}
				return $"Código: {CodigoInterno} Barras: {Barras} Descrição: {Descricao} {text}";
			}
		}

		public string Unidade { get; protected set; }

		public decimal LimiteDesconto { get; protected set; }

		public string IndicadorArredondamentoTruncamento { get; protected set; }

		public string IndicadorProducaoPropriaTerceiro { get; protected set; }

		public bool Pesavel { get; protected set; }

		public string Cest { get; protected set; }

		public string CodigoBeneficioFiscalUf { get; protected set; }

		public string CodigoBeneficioFiscalCreditoPresumido { get; protected set; }

		public decimal PercentualCreditoPresumido { get; protected set; }

		public NcmNbsLocal Ncm { get; protected set; }

		public decimal Quantidade { get; protected set; }

		public decimal QuantidadeSaldo { get; protected set; }

		public decimal Preco { get; protected set; }

		public decimal PrecoCusto { get; protected set; }

		public Tributacao Tributacao { get; protected set; }

		public decimal PercentualAliquota { get; protected set; }

		public string TributacaoDescricao
		{
			get
			{
				if (!(PercentualAliquota > 0m))
				{
					return Tributacao.RetornarDescricao();
				}
				return $"{Tributacao.RetornarDescricao()} - {PercentualAliquota}%";
			}
		}

		public ProdutoServicoHistorico ProdutoServicoHistorico { get; protected set; }

		public ObjectId ProdutoServicoEmpresaReferencia { get; protected set; }

		public DigisatServer.Domain.Main.Aggregates.CadastrosAgg.OperacoesFiscal.OperacaoFiscal OperacaoFiscal { get; protected set; }

		public IPISCOFINS Pis { get; protected set; }

		public IPISCOFINS Cofins { get; protected set; }

		public ICondicaoEspecial CondicaoEspecial { get; protected set; }

		public bool IsPrecoVendaPromocional { get; protected set; }

		public DigisatServer.Domain.Main.Aggregates.CadastrosAgg.Impressoras.Impressora ImpressoraProduto { get; protected set; }

		public DigisatServer.Domain.Main.Aggregates.CadastrosAgg.Impressoras.Impressora Impressora { get; protected set; }

		public decimal PesoBruto => ProdutoServicoEmpresa?.ProdutoServico?.To<DigisatServer.Domain.Main.Aggregates.CadastrosAgg.ProdutosServicos.Produtos.Produto>()?.PesoBruto ?? 0m;

		public decimal PesoLiquido => ProdutoServicoEmpresa?.ProdutoServico?.To<DigisatServer.Domain.Main.Aggregates.CadastrosAgg.ProdutosServicos.Produtos.Produto>()?.PesoLiquido ?? 0m;

		public string PrincipioAtivo => ProdutoServicoEmpresa?.ProdutoServico?.To<Medicamento>()?.PrincipioAtivo ?? string.Empty;

		public string Laboratorio => ProdutoServicoEmpresa?.ProdutoServico?.To<Medicamento>()?.Laboratorio ?? string.Empty;

		public string TipoMedicamento => ProdutoServicoEmpresa?.ProdutoServico?.To<Medicamento>()?.TipoMedicamento?.Descricao ?? string.Empty;

		public string Caracteristica => ProdutoServicoEmpresa?.ProdutoServico?.Caracteristica ?? string.Empty;

		protected ProdutoServicoLocal()
		{
		}

		protected ProdutoServicoLocal(ItemDto itemDto, ProdutoServicoEmpresa produtoServicoEmpresa)
		{
			NcmNbsLocal ncm = (produtoServicoEmpresa.IsExactlyObject<ServicoEmpresa>() ? NcmNbsLocal.Criar().ComNcmNbs(new NCMNBSService().ObterNbsCodigoZero()) : NcmNbsLocal.Criar().ComNcmNbs(produtoServicoEmpresa.NcmNbs));
			ProdutoServicoEmpresa = produtoServicoEmpresa;
			Descricao = itemDto.ProdutoServico.Descricao.RemoverCaracteresNaoImprimiveis();
			Marca = itemDto.ProdutoServico.Produto?.Marca?.Descricao.RemoverCaracteresNaoImprimiveis();
			CodigoInterno = itemDto.ProdutoServico.CodigoInterno;
			Barras = itemDto.ProdutoServico.Produto.CodigoBarras;
			Unidade = itemDto.ProdutoServico.UnidadeMedida.Sigla;
			LimiteDesconto = itemDto.LimiteDesconto;
			IndicadorArredondamentoTruncamento = itemDto.ProdutoServico.IndicadorArredondamentoTruncamento.Indicador;
			IndicadorProducaoPropriaTerceiro = itemDto.ProdutoServico.IndicadorProducaoPropriaTerceiro.Indicador;
			Pesavel = false;
			Cest = itemDto.CodigoEspecificadorSubstituicaoTributaria;
			Ncm = ncm;
			Quantidade = itemDto.Quantidade;
			Preco = itemDto.PrecoUnitario;
			ProdutoServicoHistorico = itemDto.ProdutoServico.MorfarProdutoServicoHistorico(itemDto.UnidadeMedida.Morfar(), itemDto.Setor.Morfar(), itemDto.PercentualComissao, itemDto.Localizacao.Morfar(), itemDto.VasilhameReferencia.ToStringEmptyWhenNull());
			ProdutoServicoEmpresaReferencia = ObjectId.Parse(itemDto.ProdutoServicoEmpresaReferencia);
			Pis = itemDto.Pis.MorfarCalculadoSistema();
			Cofins = itemDto.Cofins.MorfarCalculadoSistema();
		}

		protected ProdutoServicoLocal(Seletor<IPainel> seletor, string informacao, ProdutoServicoEmpresa produtoServicoEmpresa, DigisatServer.Domain.Main.Aggregates.CadastrosAgg.Impressoras.Impressora impressora = null)
		{
			Seletor = seletor;
			InformacaoPesquisa = informacao;
			if (produtoServicoEmpresa != null)
			{
				NcmNbsLocal ncm = (produtoServicoEmpresa.IsExactlyObject<ServicoEmpresa>() ? NcmNbsLocal.Criar().ComNcmNbs(new NCMNBSService().ObterNbsCodigoZero()) : NcmNbsLocal.Criar().ComNcmNbs(produtoServicoEmpresa.NcmNbs));
				ProdutoServicoEmpresa = produtoServicoEmpresa;
				CodigoInterno = produtoServicoEmpresa.ProdutoServico.CodigoInterno;
				Descricao = produtoServicoEmpresa.ProdutoServico.Descricao.RemoverCaracteresNaoImprimiveis();
				Marca = produtoServicoEmpresa.To<ProdutoEmpresa>()?.Produto?.Marca?.Descricao.RemoverCaracteresNaoImprimiveis();
				Unidade = produtoServicoEmpresa.ProdutoServico.UnidadeMedida.Sigla;
				LimiteDesconto = produtoServicoEmpresa.LimiteDesconto;
				IndicadorArredondamentoTruncamento = produtoServicoEmpresa.ProdutoServico.IndicadorArredondamentoTruncamento.Indicador;
				IndicadorProducaoPropriaTerceiro = produtoServicoEmpresa.ProdutoServico.IndicadorProducaoPropriaTerceiro.Indicador;
				Preco = produtoServicoEmpresa.Preco.PrecoVendaVigente;
				PrecoCusto = produtoServicoEmpresa.Preco.Custo.Valor;
				Ncm = ncm;
				ProdutoServicoHistorico = produtoServicoEmpresa.ProdutoServico.MorfarProdutoServicoHistorico(produtoServicoEmpresa.PercentualComissao, produtoServicoEmpresa.ProdutoServico.To<DigisatServer.Domain.Main.Aggregates.CadastrosAgg.ProdutosServicos.Produtos.Produto>()?.Marca, produtoServicoEmpresa.ProdutoServico.UnidadeMedida, produtoServicoEmpresa.ProdutoServico.To<Servico>()?.Setor, produtoServicoEmpresa.To<ProdutoEmpresa>()?.Localizacao, produtoServicoEmpresa.To<ProdutoEmpresa>()?.VasilhameReferencia);
				ProdutoServicoEmpresaReferencia = produtoServicoEmpresa.Id;
				Pis = produtoServicoEmpresa.TributacaoFederal.TributacaoPisCofins.PISSaida;
				Cofins = produtoServicoEmpresa.TributacaoFederal.TributacaoPisCofins.COFINSSaida;
				CondicaoEspecial = produtoServicoEmpresa.CondicaoEspecial;
				IsPrecoVendaPromocional = produtoServicoEmpresa.Preco.IsPrecoVendaPromocional();
				Impressora = impressora;
				ImpressoraProduto = produtoServicoEmpresa.Impressora;
			}
		}

		public void SetarQuantidade(decimal quantidade)
		{
			Quantidade = quantidade;
		}

		public void SetarOperacaoFiscal(DigisatServer.Domain.Main.Aggregates.CadastrosAgg.OperacoesFiscal.OperacaoFiscal operacaoFiscal)
		{
			OperacaoFiscal = operacaoFiscal;
		}

		public virtual void Vender(decimal quantidade, bool capturouPeso = false)
		{
			throw new NotImplementedException();
		}

		protected virtual Otus.Modulo.PontoDeVendas.ViewModels.ItemDocumentoFiscal CriarItemDocumentoFiscal()
		{
			return FluentFactory<Otus.Modulo.PontoDeVendas.ViewModels.ItemDocumentoFiscalFactory>.Init().ComProdutoServicoLocal(this).Criar()
				.ComVendedor(Seletor.Get<PainelDocumentoFiscal>().Vendedor)
				.ComPermitirVenderAcimaDoLimiteDeDesconto(() => Seletor.Get<PainelDocumentoFiscal>().PermitirVenderAcimaDoLimiteDeDesconto())
				.ComDepartamentoReferencia(DadosSistema.ObterDepartamentoVenda().DepartamentoVendaReferencia);
		}

		public override string ToString()
		{
			return Descricao;
		}

		public void VerificarPercentualComissao(VendedorLocal vendedor)
		{
			decimal comissaoVendedor = vendedor?.PessoaHistorico.To<FisicaHistorico>()?.Vendedor?.PercentualComissao ?? 0m;
			ProdutoServicoHistorico.VerificarPercentualComissao(comissaoVendedor, 0m, 0m);
		}

		public void ProcessarComissaoTabelaPreco(TabelaPrecoLocal tabelaPrecoLocal, decimal percentualComissaoItem)
		{
			if (percentualComissaoItem > 0m)
			{
				ProdutoServicoHistorico.SetarPercentualComissaoTabelaPreco(percentualComissaoItem);
			}
			else if (tabelaPrecoLocal.PercentualComissao > 0m)
			{
				ProdutoServicoHistorico.SetarPercentualComissaoTabelaPreco(tabelaPrecoLocal.PercentualComissao);
			}
		}

		public ProdutoServicoLocal SetarPrecoUnitario(decimal precoUnitario)
		{
			Preco = precoUnitario;
			return this;
		}

		public ProdutoServicoLocal SetarDescricaoMenuRapido(string descricaoMenuRapido)
		{
			DescricaoMenuRapido = descricaoMenuRapido;
			return this;
		}
	}
