	[CollectionName("PromocoesScanntech")]
	[BsonIgnoreExtraElements]
	public class PromocaoScanntech : Entity
	{
		[Index("EmpresaReferencia")]
		public ObjectId EmpresaReferencia { get; protected set; }

		public string IdPromocao { get; protected set; }

		public string Titulo { get; protected set; }

		public string Descricao { get; protected set; }

		public TipoPromocao Tipo { get; protected set; }

		public Detalhe Detalhe { get; protected set; }

		public Autor Autor { get; protected set; }

		public DateTime DataVigenciaInicial { get; protected set; }

		public DateTime DataVigenciaFinal { get; protected set; }

		public int Limite { get; protected set; }

		public bool SomentePessoaCadastrada { get; protected set; }

		public bool AtivadaSomenteNaLeituraDeTicket { get; protected set; }

		public int PromocaoAplicada { get; set; }

		public bool PodeAplicarPromocao
		{
			get
			{
				if (Limite != 0)
				{
					return Limite > PromocaoAplicada;
				}
				return true;
			}
		}

		public PromocaoScanntech(ObjectId empresaReferencia, string idPromocao, string titulo, string descricao, TipoPromocao tipo, Detalhe detalhe, Autor autor, DateTime dataVigenciaInicial, DateTime dataVigenciaFinal, int limite, bool somentePessoaCadastrada, bool ativadaSomenteNaLeituraDeTicket, bool ativo = true, TimeSpan versao = default(TimeSpan), ObjectId id = default(ObjectId))
			: base(ativo, versao, id)
		{
			EmpresaReferencia = empresaReferencia;
			IdPromocao = idPromocao;
			Titulo = titulo;
			Descricao = descricao;
			Tipo = tipo;
			Detalhe = detalhe;
			Autor = autor;
			DataVigenciaInicial = dataVigenciaInicial;
			DataVigenciaFinal = dataVigenciaFinal;
			Limite = limite;
			SomentePessoaCadastrada = somentePessoaCadastrada;
			AtivadaSomenteNaLeituraDeTicket = ativadaSomenteNaLeituraDeTicket;
			AdicionarInformacaoPesquisa(Titulo.Split());
		}

		public void IncrementarPromocaoAplicada()
		{
			PromocaoAplicada++;
		}
	}
	public static class PromocaoScanntechSpecifications
	{
		public static ISpecification<PromocaoScanntech> PorIdPromocao(string idPromocao)
		{
			return new DirectSpecification<PromocaoScanntech>((PromocaoScanntech x) => x.IdPromocao.Equals(idPromocao));
		}

		public static ISpecification<PromocaoScanntech> PorVigenteDataAtual(this ISpecification<PromocaoScanntech> specification)
		{
			return new AndSpecification<PromocaoScanntech>(specification, new DirectSpecification<PromocaoScanntech>((PromocaoScanntech x) => x.DataVigenciaInicial <= DateTime.Now && x.DataVigenciaFinal >= DateTime.Now));
		}

		public static ISpecification<PromocaoScanntech> PorEmpresa(this ISpecification<PromocaoScanntech> specification, ObjectId empresaId)
		{
			return new AndSpecification<PromocaoScanntech>(specification, new DirectSpecification<PromocaoScanntech>((PromocaoScanntech x) => x.EmpresaReferencia.Equals(empresaId)));
		}

		public static ISpecification<PromocaoScanntech> PorMeioPagamentoNull(this ISpecification<PromocaoScanntech> specification)
		{
			return new AndSpecification<PromocaoScanntech>(specification, new DirectSpecification<PromocaoScanntech>((PromocaoScanntech x) => x.Detalhe.Condicao.FormasPagamento == null || !x.Detalhe.Condicao.FormasPagamento.Any()));
		}

		public static ISpecification<PromocaoScanntech> PorMeioPagamentoNotNull(this ISpecification<PromocaoScanntech> specification)
		{
			return new AndSpecification<PromocaoScanntech>(specification, new DirectSpecification<PromocaoScanntech>((PromocaoScanntech x) => x.Detalhe.Condicao.FormasPagamento != null && x.Detalhe.Condicao.FormasPagamento.Any()));
		}
	}
