namespace Otus.Modulo.PontoDeVendas.Actors
{
	public class ConexaoClientActor : ReceiveActor
	{
		private readonly IEventPublisher _eventPublisher;

		private readonly ActorSelection _server;

		public ConexaoClientActor(IEventPublisher eventPublisher, IConfiguracaoClientService configuracaoClientService)
		{
			_eventPublisher = eventPublisher;
			string ip = configuracaoClientService.ObterConfiguracao().Ip;
			_server = UntypedActor.Context.ActorSelection(new AkkaServerAddress("DigisatServerAkka", ip, 12222, "WcfServerActor").ToString());
			Conectando();
		}

		private void Conectando()
		{
			SetReceiveTimeout(TimeSpan.FromSeconds(1.0));
			Receive((ConnectResponse response) =>
			{
				Become(Conectado);
			});
			Receive((ReceiveTimeout r) =>
			{
				_eventPublisher.Publish(new SemComunicacaoServidorEvent());
				Conectar();
			});
			Conectar();
		}

		public void Conectado()
		{
			SetReceiveTimeout(null);
			UntypedActor.Context.Watch(Sender);
			_eventPublisher.Publish(new ComunicandoServidorEvent());
			Receive((Terminated message) =>
			{
				_eventPublisher.Publish(new SemComunicacaoServidorEvent());
				Become(Conectando);
			});
		}

		private void Conectar()
		{
			_server.Tell(new ConnectRequest());
		}
	}
	public class PostoClientActor : ReceiveActor
	{
		private readonly IConfiguracaoClientService _configuracaoClientService;

		private readonly IEventPublisher _eventPublisher;

		private ActorSelection _server;

		private CompositeDisposable _compositeDisposable = new CompositeDisposable();

		private string _guid;

		private string _ip;

		public PostoClientActor(IConfiguracaoClientService configuracaoClientService, IEventPublisher eventPublisher)
		{
			_configuracaoClientService = configuracaoClientService;
			_eventPublisher = eventPublisher;
			System.Windows.Application.Current.Dispatcher.Invoke(() =>
			{
				System.Windows.Application.Current.MainWindow.Closing += MainWindowOnClosing;
			});
			Desconectado();
		}

		private void MainWindowOnClosing(object sender, CancelEventArgs cancelEventArgs)
		{
			System.Windows.Application.Current.MainWindow.Closing -= MainWindowOnClosing;
			_server?.Tell(new DisconnectPontoDeVendaPostoServiceRequest(HelperIp.GetLocalIpAddress(), _guid));
		}

		private void Desconectado()
		{
			ConfiguracaoPosto configuracaoPosto = _configuracaoClientService.ObterConfiguracao()?.Posto;
			if (configuracaoPosto.IsNull() || (configuracaoPosto != null && !configuracaoPosto.PostoConfigurado))
			{
				_eventPublisher.Publish(new SemConfiguracaoPostoServiceEvent());
				return;
			}
			if (_server.IsNull() || !configuracaoPosto.Ip.Equals(_ip))
			{
				_ip = configuracaoPosto.Ip;
				_server = UntypedActor.Context.ActorSelection(new AkkaServerAddress("DigisatServerPosto", configuracaoPosto.Ip, 12226, "PostoServerActor").ToString());
			}
			Receive((ConnectPontoDeVendaPostoServiceRequest message) =>
			{
				Become(() =>
				{
					Conectando(message);
				});
			});
		}

		private void Conectando(ConnectPontoDeVendaPostoServiceRequest message)
		{
			_guid = message.Id;
			SetReceiveTimeout(TimeSpan.FromSeconds(5.0));
			Receive((ConnectPontoDeVendaPostoServiceResponse response) =>
			{
				Become(() =>
				{
					Conectado(response);
				});
			});
			Receive((DisconnectPontoDeVendaPostoServiceRequest x) =>
			{
				Become(Desconectado);
			});
			Receive((ReceiveTimeout r) =>
			{
				Conectar(message);
			});
		}

		private void Conectar(ConnectPontoDeVendaPostoServiceRequest message)
		{
			_eventPublisher.Publish(new SemComunicacaoPostoServiceEvent());
			_server.Tell(message);
		}

		public void Conectado(ConnectPontoDeVendaPostoServiceResponse response)
		{
			SetReceiveTimeout(null);
			UntypedActor.Context.Watch(Sender);
			_compositeDisposable = new CompositeDisposable(_eventPublisher.GetEvent((RemoverAbastecimentosRequest x) =>
			{
				_server.Tell(x);
			}), _eventPublisher.GetEvent((PresetRequest x) =>
			{
				_server.Tell(x);
			}), _eventPublisher.GetEvent((AtualizarPrecosRequest x) =>
			{
				_server.Tell(x);
			}), _eventPublisher.GetEvent((AutorizarAbastecimentoRequest x) =>
			{
				_server.Tell(x);
			}), _eventPublisher.GetEvent((PararAbastecimentoRequest x) =>
			{
				_server.Tell(x);
			}), _eventPublisher.GetEvent((BicoSemComunicacaoRequest x) =>
			{
				_server.Tell(x);
			}), _eventPublisher.GetEvent((RemoverQuebraContinuidadeEncerranteRequest x) =>
			{
				_server.Tell(x);
			}), _eventPublisher.GetEvent((TornarAbastecimentosPendentesRequest x) =>
			{
				_server.Tell(x);
			}), _eventPublisher.GetEvent((AbastecimentoValidoRequest x) =>
			{
				_server.Tell(x);
			}));
			Receive((NovoAbastecimentoResponse abastecimento) =>
			{
				_eventPublisher.Publish(abastecimento);
			});
			Receive((RemoverAbastecimentosResponse abastecimento) =>
			{
				_eventPublisher.Publish(abastecimento.Abastecimentos);
			});
			Receive((StatusBicosResponse status) =>
			{
				_eventPublisher.Publish(status);
			});
			Receive((PerdeuComunicacaoTotalResponse perdeuComunicacaoTotal) =>
			{
				_eventPublisher.Publish(perdeuComunicacaoTotal);
			});
			Receive((RetornouComunicacaoTotalResponse retornouComunicacaoTotal) =>
			{
				_eventPublisher.Publish(retornouComunicacaoTotal);
			});
			Receive((NotificouSituacaoComunicacaoBicoResponse informacaoComunicacao) =>
			{
				_eventPublisher.Publish(informacaoComunicacao);
			});
			Receive((BicoSemComunicacaoResponse bicoSemComunicacaoResponse) =>
			{
				_eventPublisher.Publish(bicoSemComunicacaoResponse);
			});
			Receive((QuebraContinuidadeEncerranteResponse quebraContinuidadeEncerranteResponse) =>
			{
				_eventPublisher.Publish(quebraContinuidadeEncerranteResponse);
			});
			Receive((RemoverQuebraContinuidadeEncerranteResponse removerQuebraContinuidadeEncerranteResponse) =>
			{
				_eventPublisher.Publish(removerQuebraContinuidadeEncerranteResponse);
			});
			Receive((AbastecimentoValidoResponse abastecimentoValido) =>
			{
				_eventPublisher.Publish(abastecimentoValido);
			});
			Receive((DisconnectPontoDeVendaPostoServiceRequest message) =>
			{
				_eventPublisher.Publish(new SemComunicacaoPostoServiceEvent());
				_server.Tell(message);
				_compositeDisposable.Dispose();
				Become(Desconectado);
			});
			Receive((Terminated message) =>
			{
				_eventPublisher.Publish(new SemComunicacaoPostoServiceEvent());
				_compositeDisposable.Dispose();
				UntypedActor.Context.System.Terminate();
			});
			_eventPublisher.Publish(response);
		}
	}
	public abstract class CfeClientActor : ReceiveActor
	{
		protected readonly IConfiguracaoClientService ConfiguracaoClientService;

		private readonly IEventPublisher _eventPublisher;

		protected ActorSelection Server;

		protected CfeClientActor(IConfiguracaoClientService configuracaoClientService, IEventPublisher eventPublisher)
		{
			ConfiguracaoClientService = configuracaoClientService;
			_eventPublisher = eventPublisher;
			Conectando();
		}

		private void Conectando()
		{
			SetReceiveTimeout(TimeSpan.FromSeconds(5.0));
			Receive((ConnectResponse r) =>
			{
				_eventPublisher.Publish(r);
				Become(Conectado);
			});
			Receive((ReceiveTimeout r) =>
			{
				CriarServer();
			});
			CriarServer();
		}

		protected abstract void CriarServer();

		private void Conectado()
		{
			SetReceiveTimeout(null);
			ConsultarStatus();
			EnviarDadosVenda();
			CancelarUltimaVenda();
			Receive((ErroCFeResponse r) =>
			{
				_eventPublisher.Publish(r);
			});
			Receive((FalhaCFeResponse r) =>
			{
				_eventPublisher.Publish(r);
			});
			Receive((ErroCFeCancResponse r) =>
			{
				_eventPublisher.Publish(r);
			});
			Receive((Terminated ack) =>
			{
				Become(Conectando);
			});
		}

		private void ConsultarStatus()
		{
			Receive((ConsultarStatusRequest r) =>
			{
				Server.Tell(r);
			});
			Receive((ConsultarStatusResponse r) =>
			{
				_eventPublisher.Publish(r);
			});
		}

		private void EnviarDadosVenda()
		{
			Receive((EnviarDadosVendaRequest r) =>
			{
				Server.Tell(r);
			});
			Receive((EnviarDadosVendaResponse r) =>
			{
				_eventPublisher.Publish(r);
			});
		}

		private void CancelarUltimaVenda()
		{
			Receive((CancelarUltimaVendaRequest r) =>
			{
				Server.Tell(r);
			});
			Receive((CancelarUltimaVendaResponse r) =>
			{
				_eventPublisher.Publish(r);
			});
		}
	}
