	public class PontoDeVendaClientActorSystem : DClientActorSystemBase<IUnityContainer, UnityDependencyResolver>
	{
		private readonly string _guid;

		private readonly string _ipPontoDeVenda;

		public IActorRef PostoClientActor { get; private set; }

		public IActorRef ConexaoClientActor { get; private set; }

		public PontoDeVendaClientActorSystem(IUnityContainer container)
			: base(container)
		{
			_guid = Guid.NewGuid().ToString();
			_ipPontoDeVenda = HelperIp.GetLocalIpAddress();
		}

		public override IActorSystem Criar(string sistema)
		{
			System = ActorSystem.Create(sistema, ObterConfiguracao());
			System.WhenTerminated.ContinueWith(Reiniciar);
			return this;
		}

		private void Reiniciar(Task task)
		{
			Finalizar(PostoClientActor);
			Finalizar(ConexaoClientActor);
			Reload();
			Iniciar();
		}

		public void Iniciar()
		{
			PostoClientActor = Criar<PostoClientActor>();
			Conectar();
			ConexaoClientActor = Criar<ConexaoClientActor>();
		}

		public void Desconectar()
		{
			PostoClientActor?.Tell(new DisconnectPontoDeVendaPostoServiceRequest(_ipPontoDeVenda, _guid));
		}

		public void Conectar()
		{
			PostoClientActor?.Tell(new ConnectPontoDeVendaPostoServiceRequest(_ipPontoDeVenda, _guid));
		}
	}
}
